  select 'Segons l''article 3.1 del Codi penal, una pena o una mesura de seguretat només es pot executar en virtut de:', 'L''article 3.1 CP recull la garantia jurisdiccional: cap pena ni mesura de seguretat es pot executar si no és en virtut de sentència ferma del jutge o tribunal competent.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 3.1 CP', '1. No podrá ejecutarse pena ni medida de seguridad sino en virtud de sentencia firme dictada por el Juez o Tribunal competente, de acuerdo con las leyes procesales.', null, 'be1fd3856ae3a1c7a97e022e029f059ee02d161be9269e77802b41021c8b3bca', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'be1fd3856ae3a1c7a97e022e029f059ee02d161be9269e77802b41021c8b3bca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Resolució ferma de l''Administració penitenciària.', false), ('B', 'Sentència ferma dictada pel jutge o tribunal competent, d''acord amb les lleis processals.', true), ('C', 'Sentència, encara que no sigui ferma, si el condemnat es troba en presó provisional.', false), ('D', 'Acord del Ministeri Fiscal ratificat pel jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la garantia d''execució de l''article 3.2 del Codi penal, quina de les afirmacions següents NO és correcta?', 'L''article 3.2 CP disposa que l''execució de la pena i també la de la mesura de seguretat es fa sota el control dels jutges i tribunals competents.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 3.2 CP', 'Tampoco podrá ejecutarse pena ni medida de seguridad en otra forma que la prescrita por la Ley y reglamentos que la desarrollan, ni con otras circunstancias o accidentes que los expresados en su texto. La ejecución de la pena o de la medida de seguridad se realizará bajo el control de los Jueces y Tribunales competentes.', null, '1599147a3f42a83b55b2bd2c2e91adc592368ce7fb63012496342087ba8968f2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1599147a3f42a83b55b2bd2c2e91adc592368ce7fb63012496342087ba8968f2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena no es pot executar en una forma diferent de la prescrita per la llei i els reglaments que la despleguen.', false), ('B', 'La pena no es pot executar amb circumstàncies o accidents diferents dels que expressa el text legal.', false), ('C', 'L''execució de la pena es fa sota el control dels jutges i tribunals competents.', false), ('D', 'L''execució de les mesures de seguretat no està sotmesa a control judicial, sinó al de l''Administració penitenciària.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
