with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 4.1 del Codi penal, les lleis penals:', 'L''article 4.1 CP prohibeix l''aplicació de les lleis penals a casos diferents dels compresos expressament en elles (prohibició de l''analogia, derivada del principi de legalitat).', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 4.1 CP', '1. Las leyes penales no se aplicarán a casos distintos de los comprendidos expresamente en ellas.', null, 'a5d33cbe13f5005f6f2d66574b553a6b5a793ccad85f8dfe311ab19cb4253bc2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a5d33cbe13f5005f6f2d66574b553a6b5a793ccad85f8dfe311ab19cb4253bc2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No s''han d''aplicar a casos diferents dels que hi estan compresos expressament.', true), ('B', 'Es poden aplicar a casos semblants quan hi hagi identitat de raó.', false), ('C', 'S''han d''interpretar d''acord amb la jurisprudència del Tribunal Suprem, que n''és font directa.', false), ('D', 'S''apliquen supletòriament a les infraccions administratives.', false)) as v(label, body, ok)
)
