with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, les accions o omissions imprudents:', 'L''article 10 CP considera delictes les accions i omissions doloses o imprudents penades per la llei, i l''article 12 limita el càstig de la imprudència als casos en què la llei ho disposa expressament.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 10 i 12 CP', 'Las acciones u omisiones imprudentes sólo se castigarán cuando expresamente lo disponga la Ley.', null, '7837a343ba4bd16c2134cfe20c93ac9e9be9eaa0b62cf68e6db52e38216cb65b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7837a343ba4bd16c2134cfe20c93ac9e9be9eaa0b62cf68e6db52e38216cb65b')
  returning id
