  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 del Codi penal, quan un fet es pot qualificar d''acord amb dos o més preceptes i no és aplicable cap dels altres criteris de resolució del concurs de normes, s''aplica la regla segons la qual:', 'La regla 4a de l''article 8 CP (criteri d''alternativitat) opera en defecte de les altres: el precepte més greu exclou els que castiguen el fet amb pena menor.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8.4 CP', '4.ª En defecto de los criterios anteriores, el precepto penal más grave excluirá los que castiguen el hecho con pena menor.', null, 'f72cc53ebdfae950bcd14b70da52bb4cd7290976eae0b4971588ac43011db68d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f72cc53ebdfae950bcd14b70da52bb4cd7290976eae0b4971588ac43011db68d')
  returning id
