  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''aplica el precepte més favorable al reu.', false), ('B', 'El precepte especial s''aplica amb preferència al general.', false), ('C', 'El precepte penal més greu exclou els que castiguen el fet amb pena menor.', true), ('D', 'S''aplica el precepte que hagi entrat en vigor més recentment.', false)) as v(label, body, ok)
)
