  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina regla de l''article 8 del Codi penal disposa que el precepte penal més ampli o complex absorbeix els que castiguen les infraccions consumides en aquell?', 'L''article 8 CP ordena quatre regles: 1a especialitat, 2a subsidiarietat, 3a consumció (el precepte més ampli o complex absorbeix les infraccions consumides) i 4a alternativitat (el precepte més greu).', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8.3 CP', '3.ª El precepto penal más amplio o complejo absorberá a los que castiguen las infracciones consumidas en aquél.', null, 'b9bcc73f7a79ddc9f0068db866c40f114e2914be55d5fad4480a194ecfe74e92', false
