select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''exposició de motius del Codi penal de 1995, l''eix dels criteris en què s''inspira el Codi és:', 'L''exposició de motius afirma que l''eix dels criteris és l''adaptació positiva del Codi als valors constitucionals, i hi destaca la reforma del sistema de penes, la intervenció mínima, la tutela dels drets fonamentals i la igualtat.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'El eje de dichos criterios ha sido, como es lógico, el de la adaptación positiva del nuevo Código Penal a los valores constitucionales.', null, 'ce128804b2d85224f862839efe65c2e36592d8182844136dc8927b694ca38631', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ce128804b2d85224f862839efe65c2e36592d8182844136dc8927b694ca38631')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''enduriment general de les penes privatives de llibertat.', false), ('B', 'L''adaptació positiva del nou Codi penal als valors constitucionals.', true), ('C', 'La incorporació de tota la legislació penal especial al Codi.', false), ('D', 'La recuperació de la tradició codificadora del segle XIX.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les novetats següents NO és una de les que l''exposició de motius del Codi penal de 1995 atribueix a la reforma del sistema de penes?', 'L''exposició de motius de 1995 esmenta la simplificació de les penes privatives de llibertat, l''ampliació de la seva substitució, els dies multa i els treballs en benefici de la comunitat. La presó permanent revisable es va introduir amb la reforma de la LO 1/2015.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'El sistema que se propone simplifica, de una parte, la regulación de las penas privativas de libertad, ampliando, a la vez, las posibilidades de sustituirlas por otras que afecten a bienes jurídicos menos básicos, y, de otra, introduce cambios en las penas pecuniarias, adoptando el sistema de días-multa y añade los trabajos en beneficio de la comunidad.', null, 'b03b4fd80e08edd0e4c4003b0a7f945b9cc19ca80bdf752b48d2e5ea039728c3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b03b4fd80e08edd0e4c4003b0a7f945b9cc19ca80bdf752b48d2e5ea039728c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''adopció del sistema de dies multa en les penes pecuniàries.', false), ('B', 'La incorporació dels treballs en benefici de la comunitat.', false), ('C', 'La simplificació de la regulació de les penes privatives de llibertat.', false), ('D', 'La introducció de la presó permanent revisable.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
