with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la regla 2a de l''article 8 del Codi penal, el precepte subsidiari s''aplica:', 'La regla de subsidiarietat permet aplicar el precepte subsidiari només si no és aplicable el principal, sigui la subsidiarietat expressa o tàcita.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8.2a CP', '2.ª El precepto subsidiario se aplicará sólo en defecto del principal, ya se declare expresamente dicha subsidiariedad, ya sea ésta tácitamente deducible.', null, '212189c5b7f1f866007e72bc7296e37a7fc34b8b60c440b50196fd026fb9e302', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '212189c5b7f1f866007e72bc7296e37a7fc34b8b60c440b50196fd026fb9e302')
  returning id
), o as (
