with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25 del Codi penal, a l''efecte del Codi s''entén per discapacitat la situació d''una persona amb deficiències físiques, mentals, intel·lectuals o sensorials:', 'L''article 25 CP defineix la discapacitat per la permanència de la deficiència i la seva interacció amb barreres, sense exigir cap reconeixement administratiu ni judicial.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 25 CP', 'A los efectos de este Código se entiende por discapacidad aquella situación en que se encuentra una persona con deficiencias físicas, mentales, intelectuales o sensoriales de carácter permanente que, al interactuar con diversas barreras, puedan limitar o impedir su participación plena y efectiva en la sociedad, en igualdad de condiciones con las demás.', null, '67d670f7212e277a547a1bc5f7e512e8903e5b69e8995035322d06b80dd824ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '67d670f7212e277a547a1bc5f7e512e8903e5b69e8995035322d06b80dd824ee')
  returning id
), o as (
