  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De caràcter temporal o permanent reconegudes administrativament amb un grau igual o superior al 33 %.', false), ('B', 'De caràcter permanent que, en interactuar amb diverses barreres, poden limitar o impedir la seva participació plena i efectiva en la societat, en igualtat de condicions amb les altres.', true), ('C', 'Que hagin donat lloc a una modificació judicial de la capacitat d''obrar.', false), ('D', 'Que impedeixin a la persona comprendre la il·licitud dels seus actes.', false)) as v(label, body, ok)
)
