  select 'Segons l''article 26 del Codi penal, a l''efecte del Codi es considera document:', 'El concepte penal de document és ampli: inclou qualsevol suport material (també l''electrònic) amb eficàcia probatòria o rellevància jurídica.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 26 CP', 'A los efectos de este Código se considera documento todo soporte material que exprese o incorpore datos, hechos o narraciones con eficacia probatoria o cualquier otro tipo de relevancia jurídica.', null, '79d1005db14aaa4c57b7e136c8d133a592a86b5a8ede75ac5cda2d1e4cf1aadd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '79d1005db14aaa4c57b7e136c8d133a592a86b5a8ede75ac5cda2d1e4cf1aadd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només l''escrit en paper signat per una autoritat o un funcionari públic.', false), ('B', 'Qualsevol escrit, sigui quina sigui la seva rellevància jurídica.', false), ('C', 'Només el document públic, oficial o mercantil.', false), ('D', 'Tot suport material que expressi o incorpori dades, fets o narracions amb eficàcia probatòria o qualsevol altre tipus de rellevància jurídica.', true)) as v(label, body, ok)
)
