with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels títols següents NO forma part del llibre I del Codi penal?', 'El llibre I té set títols: de la infracció penal, de les persones criminalment responsables, de les penes, de les mesures de seguretat, de la responsabilitat civil i de les costes, de les conseqüències accessòries i de l''extinció de la responsabilitat criminal. Els delictes contra l''Administració pública són el títol XIX del llibre II.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Llibre I CP (títols)', 'TÍTULO V. De la responsabilidad civil derivada de los delitos y de las costas procesales […] TÍTULO VI. De las consecuencias accesorias […] TÍTULO VII. De la extinción de la responsabilidad criminal y sus efectos', null, '8fa6ecf76fd93752d4247c91fb2bd8753975e57972967e21ccf3898e3cefa940', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8fa6ecf76fd93752d4247c91fb2bd8753975e57972967e21ccf3898e3cefa940')
  returning id
), o as (
