with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''exposició de motius del Codi penal de 1995, el bé jurídic protegit en la nova regulació dels delictes contra la llibertat sexual és:', 'L''exposició de motius explica que la nova regulació adequa els tipus al bé jurídic protegit, que ja no és, com històricament, l''honestedat de la dona, sinó la llibertat sexual de tots.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'Se pretende con ella adecuar los tipos penales al bien jurídico protegido, que no es ya, como fuera históricamente, la honestidad de la mujer, sino la libertad sexual de todos.', null, '5f628309e74e0fc57f965584f855736b65105f3778b2e904f7afc9bba1cb74c0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f628309e74e0fc57f965584f855736b65105f3778b2e904f7afc9bba1cb74c0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La llibertat sexual de tots.', true), ('B', 'L''honestedat de la dona.', false), ('C', 'La moral pública.', false), ('D', 'La integritat física de la víctima.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
