with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''exposició de motius del Codi penal de 1995, en tutelar específicament la integritat moral s''atorga al ciutadà una protecció més forta davant:', 'L''exposició de motius cita la tutela específica de la integritat moral (protecció més forta davant la tortura) i la nova regulació dels delictes contra l''honor (relleu de la llibertat d''expressió) com a exemples de tutela dels drets fonamentals.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'Al tutelar específicamente la integridad moral, se otorga al ciudadano una protección más fuerte frente a la tortura', null, '66d81bb91adc7f030b00f7874bec5c93439350779806faecff403d28e3dc0fb5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '66d81bb91adc7f030b00f7874bec5c93439350779806faecff403d28e3dc0fb5')
