)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició transitòria primera del Codi penal de 1995, els delictes i faltes comesos fins al dia de l''entrada en vigor del Codi:', 'La disposició transitòria primera aplica la regla general d''irretroactivitat amb l''excepció de la llei penal més favorable (art. 2.2 CP).', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Disposició transitòria primera CP', 'Los delitos y faltas cometidos hasta el día de la entrada en vigor de este Código se juzgarán conforme al cuerpo legal y demás leyes penales especiales que se derogan. Una vez que entre en vigor el presente Código, si las disposiciones del mismo son más favorables para el reo, se aplicarán éstas.', null, 'fb6ff00196fdd53106e255ea918cce183fff8da664547a01bd1a467e16fe08e1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fb6ff00196fdd53106e255ea918cce183fff8da664547a01bd1a467e16fe08e1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es jutgen sempre d''acord amb el nou Codi.', false), ('B', 'Es jutgen sempre d''acord amb el Codi derogat, encara que el nou sigui més favorable.', false), ('C', 'Es jutgen d''acord amb el cos legal i les lleis penals especials que es deroguen, però s''apliquen les disposicions del nou Codi si són més favorables per al reu.', true), ('D', 'Es jutgen d''acord amb la norma que triï el Ministeri Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició derogatòria única del Codi penal de 1995, quina de les lleis següents va quedar derogada amb les seves modificacions posteriors i disposicions complementàries?', 'El Codi de 1995 va derogar, entre altres, el text refós del Codi penal de 1973, la Llei de condemna condicional de 1908 i la Llei de perillositat i rehabilitació social de 1970. La LOGP, la LECrim i la LO d''habeas corpus continuen vigents.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Disposició derogatòria única CP', 'c) La Ley 16/1970, de 4 de agosto, sobre Peligrosidad y Rehabilitación Social, con sus modificaciones posteriores y disposiciones complementarias.', null, '7ec789fc1cc5abc64e6285468426eed8db95611cde11012a1075b9791f7ff0d5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7ec789fc1cc5abc64e6285468426eed8db95611cde11012a1075b9791f7ff0d5')
  returning id
