)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A més del cas de vulneració del dret a un procés sense dilacions indegudes, segons l''article 4.4 del Codi penal el jutge o tribunal també pot suspendre l''execució de la pena, mentre no es resolgui sobre l''indult:', 'El segon paràgraf de l''article 4.4 CP permet suspendre l''execució mentre es tramita l''indult si executar la sentència en faria il·lusòria la finalitat.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 4.4 CP (paràgraf segon)', 'También podrá el Juez o Tribunal suspender la ejecución de la pena, mientras no se resuelva sobre el indulto cuando, de ser ejecutada la sentencia, la finalidad de éste pudiera resultar ilusoria.', null, 'f99d73f5f58a4bfa93d3ac015e9068ec7d905f076da29149a1d1682edb6b2f4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f99d73f5f58a4bfa93d3ac015e9068ec7d905f076da29149a1d1682edb6b2f4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan, si s''executés la sentència, la finalitat de l''indult podria resultar il·lusòria.', true), ('B', 'Quan el penat no tingui antecedents penals.', false), ('C', 'Quan la pena imposada no sigui superior a dos anys de presó.', false), ('D', 'Quan el Ministeri Fiscal hagi informat favorablement l''indult.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 del Codi penal, les regles de resolució del concurs de normes (especialitat, subsidiarietat, consumpció i alternativitat) s''apliquen als fets susceptibles de ser qualificats d''acord amb dos o més preceptes del Codi:', 'L''article 8 CP regula el concurs aparent de normes i exclou expressament els supòsits de concurs de delictes dels articles 73 a 77.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 8 CP', 'Los hechos susceptibles de ser calificados con arreglo a dos o más preceptos de este Código, y no comprendidos en los artículos 73 a 77, se castigarán observando las siguientes reglas:', null, 'f0913fac45acd6cf74d650c38af2f3b3f8e2f56d1189c515dc7819c145984d1a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f0913fac45acd6cf74d650c38af2f3b3f8e2f56d1189c515dc7819c145984d1a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Encara que constitueixin un concurs real de delictes.', false), ('B', 'I no compresos en els articles 73 a 77.', true), ('C', 'Només quan es tracti de delictes lleus.', false), ('D', 'I compresos en els articles 73 a 77.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''exposició de motius del Codi penal de 1995 posa com a exemple de matèria que, per la modificació constant de les condicions econòmiques i del context normatiu, convé situar fora del Codi, en lleis especials:', 'L''exposició de motius renuncia a la universalitat absoluta del Codi i cita els delictes de control de canvis com a exemple de matèria que exigeix una estabilitat impossible. Els delictes contra l''ordre socioeconòmic i els d''ordenació del territori s''hi esmenten, en canvi, com a noves formes de delinqüència incorporades al Codi.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'Tal es, por ejemplo, el caso de los delitos relativos al control de cambios. En ellos, la modificación constante de las condiciones económicas y del contexto normativo, en el que, quiérase o no, se integran tales delitos, aconseja situar las normas penales en dicho contexto y dejarlas fuera del Código', null, '8a1482627f4062c61184420dfc25c7516dff65d3156ee369605b0d243289c380', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a1482627f4062c61184420dfc25c7516dff65d3156ee369605b0d243289c380')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els delictes contra la Hisenda pública.', false), ('B', 'Els delictes contra l''ordre socioeconòmic.', false), ('C', 'Els delictes relatius a l''ordenació del territori.', false), ('D', 'Els delictes relatius al control de canvis.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''exposició de motius del Codi penal de 1995, les figures complexes de robatori amb violència i intimidació en les persones, que havien de desaparèixer deixant pas a l''aplicació de les regles generals, havien sorgit en el marc de:', 'L''exposició de motius cita la desaparició d''aquestes figures, nascudes en la lluita contra el bandolerisme, com a exemple d''eliminació de figures delictives que han perdut la seva raó de ser (intervenció mínima).', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'la desaparición de las figuras complejas de robo con violencia e intimidación en las personas que, surgidas en el marco de la lucha contra el bandolerismo, deben desaparecer dejando paso a la aplicación de las reglas generales.', null, '667d4c071950848a3b75eee8b15017483aa23fed4efd99ea9e3da5740152638b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '667d4c071950848a3b75eee8b15017483aa23fed4efd99ea9e3da5740152638b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La lluita contra el terrorisme.', false), ('B', 'La repressió del contraban.', false), ('C', 'La lluita contra el bandolerisme.', true), ('D', 'La protecció de la propietat agrària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''exposició de motius del Codi penal de 1995, les detencions i les entrades i registres en el domicili fets per una autoritat o un funcionari fora dels casos permesos per la llei s''han de tractar:', 'L''exposició de motius elimina el «règim de privilegi» de les ingerències il·legítimes dels funcionaris, que fins llavors eren delictes especials atenuats, i les converteix en formes agreujades dels delictes comuns.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Exposició de motius CP', 'se propone que las detenciones, entradas y registros en el domicilio llevadas a cabo por autoridad o funcionario fuera de los casos permitidos por la Ley, sean tratadas como formas agravadas de los correspondientes delitos comunes, y no como hasta ahora lo han venido siendo, esto es, como delitos especiales incomprensible e injustificadamente atenuados.', null, '4829205d612455dc225d6417da956823efc0fa77d09c8af57a1e2d79a8d531a9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4829205d612455dc225d6417da956823efc0fa77d09c8af57a1e2d79a8d531a9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com a delictes especials atenuats.', false), ('B', 'Com a formes agreujades dels delictes comuns corresponents.', true), ('C', 'Com a infraccions disciplinàries, no penals.', false), ('D', 'Com a delictes lleus.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició transitòria segona del Codi penal de 1995, per determinar quina és la llei més favorable s''ha de tenir en compte:', 'La disposició transitòria segona exigeix comparar l''aplicació completa d''un Codi i de l''altre (no es poden combinar preceptes) i escoltar en tot cas el reu, com també preveu l''article 2.2 CP en cas de dubte.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Disposició transitòria segona CP', 'Para la determinación de cuál sea la ley más favorable se tendrá en cuenta la pena que correspondería al hecho enjuiciado con la aplicación de las normas completas de uno u otro Código. […] En todo caso, será oído el reo.', null, '1f8a9f69b83b34001e09e1947378c07808b282a423c3815461c27bbf2c2e77a3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1f8a9f69b83b34001e09e1947378c07808b282a423c3815461c27bbf2c2e77a3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena que correspondria al fet enjudiciat aplicant les normes completes d''un Codi o de l''altre, i en tot cas s''ha d''escoltar el reu.', true), ('B', 'Els preceptes més favorables de cada Codi, combinats entre si.', false), ('C', 'Només la durada màxima de la pena de presó prevista en cada Codi.', false), ('D', 'El criteri del Ministeri Fiscal, sense audiència del reu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició addicional primera del Codi penal, quan una persona és declarada exempta de responsabilitat criminal per les causes dels números 1r i 3r de l''article 20, qui ha d''avaluar la procedència de promoure un procés per a l''adopció judicial de mesures de suport a la persona amb discapacitat?', 'La disposició addicional primera CP, modificada per la Llei 8/2021, encomana al Ministeri Fiscal avaluar si cal promoure o revisar les mesures judicials de suport a la persona amb discapacitat.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Disposició addicional primera CP', 'Cuando una persona sea declarada exenta de responsabilidad criminal por concurrir alguna de las causas previstas en los números 1.º y 3.º del artículo 20, el Ministerio Fiscal evaluará, atendiendo a las circunstancias del caso, la procedencia de promover un proceso para la adopción judicial de medidas de apoyo a la persona con discapacidad', null, '2063352b12c321b161dbac4224b3b69e207b2679f6f51aedb1baa6ce6e41c740', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2063352b12c321b161dbac4224b3b69e207b2679f6f51aedb1baa6ce6e41c740')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge de vigilància penitenciària.', false), ('B', 'Els serveis socials de l''Administració penitenciària.', false), ('C', 'La família de la persona declarada exempta.', false), ('D', 'El Ministeri Fiscal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin títol del llibre II del Codi penal regula «De les tortures i altres delictes contra la integritat moral»?', 'El títol VII del llibre II (arts. 173 a 177) regula les tortures i altres delictes contra la integritat moral; el VI, els delictes contra la llibertat; el VIII, els delictes contra la llibertat sexual; i el XXI, els delictes contra la Constitució.', 'pcat_e01_dret_penal', (select id from public.topics where slug = 'pcat-e01-dret-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Llibre II CP (títol VII)', 'TÍTULO VII. De las torturas y otros delitos contra la integridad moral', null, 'f8936a1e51b3fa8262f2a7f4a9a12f4bc303075baf33a2f1cac7aca5b69ea52f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f8936a1e51b3fa8262f2a7f4a9a12f4bc303075baf33a2f1cac7aca5b69ea52f')
  returning id
), o as (
