with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10 del Codi penal, són delictes:', 'L''article 10 CP defineix el delicte com l''acció o omissió, dolosa o imprudent, penada per la llei.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 10 CP', 'Son delitos las acciones y omisiones dolosas o imprudentes penadas por la ley.', null, '83da3e8bbce484ccfe0f928b21db0ece61c3628c7542071337e6729089137bcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '83da3e8bbce484ccfe0f928b21db0ece61c3628c7542071337e6729089137bcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les accions doloses penades per la llei, però no les omissions.', false), ('B', 'Les accions i omissions contràries a l''ordenament jurídic, encara que no estiguin penades.', false), ('C', 'Les accions i omissions doloses penades per la llei o pels reglaments.', false), ('D', 'Les accions i omissions doloses o imprudents penades per la llei.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En els delictes que consisteixen en la producció d''un resultat, en quin dels casos següents NO s''equipara l''omissió a l''acció segons l''article 11 del Codi penal?', 'L''article 11 CP només equipara l''omissió a l''acció quan existeix una obligació legal o contractual específica d''actuar o quan l''omitent ha creat prèviament una ocasió de risc (ingerència). Un deure moral genèric no n''hi ha prou.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 11 CP', 'a) Cuando exista una específica obligación legal o contractual de actuar. b) Cuando el omitente haya creado una ocasión de riesgo para el bien jurídicamente protegido mediante una acción u omisión precedente.', null, '3e440d034a96c189085afc34408f9367cebaa3fb4d194d39a8b96759d7b11d4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e440d034a96c189085afc34408f9367cebaa3fb4d194d39a8b96759d7b11d4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan l''omitent només tenia un deure moral genèric de solidaritat amb la víctima.', true), ('B', 'Quan existeix una obligació legal específica d''actuar.', false), ('C', 'Quan existeix una obligació contractual específica d''actuar.', false), ('D', 'Quan l''omitent ha creat una ocasió de risc per al bé jurídic mitjançant una acció o omissió precedent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 13.4 del Codi penal, quan la pena, per la seva extensió, es pot considerar alhora lleu i menys greu, el delicte es considera:', 'L''article 13.4 CP resol els casos frontera: si la pena pot ser alhora greu i menys greu, el delicte és greu; si pot ser lleu i menys greu, el delicte és lleu.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 13.4 CP', 'Cuando la pena, por su extensión, pueda considerarse como leve y como menos grave, el delito se considerará, en todo caso, como leve.', null, '0f1b31dc9cc48846d2efae22a7f5403ead0d0276f9789c76bae2edb4575b6dfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0f1b31dc9cc48846d2efae22a7f5403ead0d0276f9789c76bae2edb4575b6dfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En tot cas, menys greu.', false), ('B', 'Greu.', false), ('C', 'En tot cas, lleu.', true), ('D', 'Lleu o menys greu, segons el que determini el jutge atenent les circumstàncies del fet.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un delicte castigat amb una pena de presó de sis a deu anys és, d''acord amb els articles 13 i 33 del Codi penal:', 'Són delictes greus els castigats amb pena greu (art. 13.1), i la presó superior a cinc anys és pena greu (art. 33.2.b).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 13.1 i 33.2 CP', '1. Son delitos graves las infracciones que la Ley castiga con pena grave. […] b) La prisión superior a cinco años.', null, '4c17f73e1091d91ac920674131d9b33fa715ebdba61c393c43da9ac048236d0f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c17f73e1091d91ac920674131d9b33fa715ebdba61c393c43da9ac048236d0f')
  returning id
), o as (
