  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un delicte menys greu.', false), ('B', 'Un delicte greu.', true), ('C', 'Un delicte lleu.', false), ('D', 'Un delicte greu o menys greu, segons la pena concreta imposada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14.1 del Codi penal, l''error vencible sobre un fet constitutiu de la infracció penal:', 'L''error de tipus invencible exclou la responsabilitat criminal; el vencible fa que la infracció es castigui, si escau, com a imprudent (art. 14.1 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 14.1 CP', '1. El error invencible sobre un hecho constitutivo de la infracción penal excluye la responsabilidad criminal. Si el error, atendidas las circunstancias del hecho y las personales del autor, fuera vencible, la infracción será castigada, en su caso, como imprudente.', null, 'ec479a5b77153637dafbe89d13cb2ea64d53cd16d6bf30e029d7d80606c88e50', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec479a5b77153637dafbe89d13cb2ea64d53cd16d6bf30e029d7d80606c88e50')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclou la responsabilitat criminal.', false), ('B', 'Comporta que la infracció es castigui, si escau, com a imprudent.', true), ('C', 'Comporta l''aplicació de la pena inferior en un o dos graus.', false), ('D', 'No té cap efecte sobre la responsabilitat criminal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin efecte té, segons l''article 14.3 del Codi penal, l''error vencible sobre la il·licitud del fet constitutiu de la infracció penal?', 'L''error de prohibició invencible exclou la responsabilitat criminal; si és vencible, s''aplica la pena inferior en un o dos graus (art. 14.3 CP). El càstig com a imprudent és propi de l''error de tipus vencible (art. 14.1).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 14.3 CP', '3. El error invencible sobre la ilicitud del hecho constitutivo de la infracción penal excluye la responsabilidad criminal. Si el error fuera vencible, se aplicará la pena inferior en uno o dos grados.', null, '6fc38696ef0e233e13588d5af8b9ddf09f2976e160895b1631f121094ff33a5f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6fc38696ef0e233e13588d5af8b9ddf09f2976e160895b1631f121094ff33a5f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''exclou la responsabilitat criminal.', false), ('B', 'La infracció es castiga com a imprudent.', false), ('C', 'S''aplica la pena inferior en un o dos graus.', true), ('D', 'S''aplica la pena en la meitat inferior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 del Codi penal, són punibles:', 'L''article 15 CP declara punibles el delicte consumat i la temptativa. La conspiració i la proposició només es castiguen en els casos especialment previstos per la llei (art. 17.3).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 15 CP', 'Son punibles el delito consumado y la tentativa de delito.', null, 'b6eb0ea4daab6ef0c6a17a8d08ea401f8153c0fc1925235b5a68f40023d7ff1a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b6eb0ea4daab6ef0c6a17a8d08ea401f8153c0fc1925235b5a68f40023d7ff1a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El delicte consumat i la temptativa de delicte.', true), ('B', 'Només el delicte consumat.', false), ('C', 'El delicte consumat, la temptativa i la frustració.', false), ('D', 'El delicte consumat i, en tot cas, la conspiració.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 16.2 del Codi penal, qui evita voluntàriament la consumació del delicte, sigui desistint de l''execució ja iniciada, sigui impedint la producció del resultat:', 'El desistiment voluntari eximeix de la responsabilitat pel delicte intentat, però no de la que correspongui pels actes executats si aquests ja constitueixen un altre delicte (art. 16.2 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 16.2 CP', '2. Quedará exento de responsabilidad penal por el delito intentado quien evite voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado, sin perjuicio de la responsabilidad en que pudiera haber incurrido por los actos ejecutados, si éstos fueren ya constitutivos de otro delito.', null, '71244d480947ea67ec0d151ede10f3327a2fe9f76dd43a589ed4f968f46ffbc4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71244d480947ea67ec0d151ede10f3327a2fe9f76dd43a589ed4f968f46ffbc4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Respon per temptativa, però amb la pena inferior en un grau.', false), ('B', 'Queda exempt de qualsevol responsabilitat penal, també pels actes ja executats.', false), ('C', 'Té dret a l''aplicació d''una circumstància atenuant molt qualificada.', false), ('D', 'Queda exempt de responsabilitat penal pel delicte intentat, sens perjudici de la responsabilitat pels actes executats si ja eren constitutius d''un altre delicte.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan en un fet intervenen diversos subjectes, quins queden exempts de responsabilitat penal pel delicte intentat, segons l''article 16.3 del Codi penal?', 'Amb pluralitat d''intervinents no n''hi ha prou amb abandonar l''execució: cal desistir i, a més, impedir o intentar impedir la consumació de manera seriosa, ferma i decidida (art. 16.3 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 16.3 CP', '3. Cuando en un hecho intervengan varios sujetos, quedarán exentos de responsabilidad penal aquél o aquéllos que desistan de la ejecución ya iniciada, e impidan o intenten impedir, seria, firme y decididamente, la consumación', null, 'a76cbc7c60c260e527e6bfb365799930f8b2ce926c4bf8a3600891213f685270', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a76cbc7c60c260e527e6bfb365799930f8b2ce926c4bf8a3600891213f685270')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els qui simplement desisteixin de la seva pròpia aportació a l''execució.', false), ('B', 'Només els qui aconsegueixin impedir efectivament la consumació.', false), ('C', 'Els qui, després de desistir, ho comuniquin a l''autoritat abans de la consumació.', false), ('D', 'Els qui desisteixin de l''execució ja iniciada i impedeixin o intentin impedir, seriosament, fermament i decididament, la consumació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17 del Codi penal, hi ha conspiració quan:', 'L''article 17.1 CP defineix la conspiració (concert i resolució conjunta d''executar el delicte). La invitació a participar és la proposició (art. 17.2), la incitació pública és la provocació i l''enaltiment, l''apologia (art. 18.1).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 17.1 CP', '1. La conspiración existe cuando dos o más personas se conciertan para la ejecución de un delito y resuelven ejecutarlo.', null, 'd86349c5d8b9276ebde928fac0abe9269e68550093f83380a936124d55fb6d7f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd86349c5d8b9276ebde928fac0abe9269e68550093f83380a936124d55fb6d7f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues o més persones es concerten per a l''execució d''un delicte i resolen executar-lo.', true), ('B', 'Qui ha resolt cometre un delicte convida una altra o altres persones a participar-hi.', false), ('C', 'S''incita directament, per mitjà de la impremta o la radiodifusió, a la perpetració d''un delicte.', false), ('D', 'S''exposen davant una concurrència de persones idees que enalteixen l''autor d''un delicte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre la conspiració, la proposició i la provocació NO és correcta?', 'Segons l''article 17.3 CP, la conspiració i la proposició només es castiguen en els casos especialment previstos per la llei. Les altres tres afirmacions reprodueixen els articles 17.2 i 18.2.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 17 i 18 CP', '3. La conspiración y la proposición para delinquir sólo se castigarán en los casos especialmente previstos en la ley.', null, 'ee822fff074d990b0d27627a4d539245866d3dc82aa8579aade24cad6994f762', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ee822fff074d990b0d27627a4d539245866d3dc82aa8579aade24cad6994f762')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La proposició existeix quan qui ha resolt cometre un delicte convida una altra o altres persones a participar-hi.', false), ('B', 'La provocació es castiga exclusivament en els casos en què la llei ho preveu.', false), ('C', 'La conspiració i la proposició per delinquir es castiguen sempre, amb la pena inferior en un grau a la del delicte.', true), ('D', 'Si a la provocació ha seguit la perpetració del delicte, es castiga com a inducció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
