with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 18.1 del Codi penal, l''apologia:', 'L''apologia (exposició d''idees que enalteixen el crim o el seu autor) només és delictiva quan és una forma de provocació i constitueix una incitació directa a delinquir (art. 18.1 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 18.1 CP', 'La apología sólo será delictiva como forma de provocación y si por su naturaleza y circunstancias constituye una incitación directa a cometer un delito.', null, '724b463cbbd0046fc2c94e173fe89b74a3399113de73e41632fd0d05cea76a24', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '724b463cbbd0046fc2c94e173fe89b74a3399113de73e41632fd0d05cea76a24')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És delictiva sempre que es faci davant una concurrència de persones.', false), ('B', 'Només és delictiva com a forma de provocació i si, per la seva naturalesa i circumstàncies, constitueix una incitació directa a cometre un delicte.', true), ('C', 'És delictiva quan enalteix l''autor d''un delicte, encara que no inciti a cometre''n cap.', false), ('D', 'Es castiga en tot cas com a inducció.', false)) as v(label, body, ok)
)
