with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels requisits següents NO forma part de l''eximent de legítima defensa de l''article 20.4 del Codi penal?', 'La legítima defensa exigeix agressió il·legítima, necessitat racional del mitjà emprat i falta de provocació suficient. Que el mal causat no sigui més gran que el que s''evita és un requisit de l''estat de necessitat (art. 20.5).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.4 CP', 'Primero. Agresión ilegítima. […] Segundo. Necesidad racional del medio empleado para impedirla o repelerla. Tercero. Falta de provocación suficiente por parte del defensor.', null, 'ca91fb70ab8cda9a4ed0b4bc7c18fd6e6abe13a7d09c1a9a1e7ac53a84963a00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca91fb70ab8cda9a4ed0b4bc7c18fd6e6abe13a7d09c1a9a1e7ac53a84963a00')
  returning id
