with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per apreciar l''atenuant de confessió de l''article 21.4 del Codi penal, el culpable ha d''haver confessat la infracció a les autoritats:', 'La confessió atenua si es produeix abans que el culpable conegui que el procediment judicial es dirigeix contra ell. El límit del judici oral és el de l''atenuant de reparació del dany (art. 21.5).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 21.4 CP', '4.ª La de haber procedido el culpable, antes de conocer que el procedimiento judicial se dirige contra él, a confesar la infracción a las autoridades.', null, '92b0b64c96183c1b2568ab0797fa3624aab3e48c794f988f5d5e6d87014eac1a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '92b0b64c96183c1b2568ab0797fa3624aab3e48c794f988f5d5e6d87014eac1a')
