  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les penes següents NO és una pena lleu segons l''article 33.4 del Codi penal?', 'Són lleus la multa de fins a tres mesos, la localització permanent d''un dia a tres mesos, els treballs en benefici de la comunitat d''un a trenta dies i la privació del dret a conduir de tres mesos a un any. La multa de més de tres mesos és pena menys greu (art. 33.3.j CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 33.4 CP', '4. Son penas leves: a) La privación del derecho a conducir vehículos a motor y ciclomotores de tres meses a un año. […] g) La multa de hasta tres meses. h) La localización permanente de un día a tres meses. i) Los trabajos en beneficio de la comunidad de uno a treinta días.', null, 'a3e45655903a045c332a1c0b436bc54d8c071cee79cdeed6a9579209bf37ff51', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a3e45655903a045c332a1c0b436bc54d8c071cee79cdeed6a9579209bf37ff51')
  returning id
), o as (
