with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16.1 del Codi penal, hi ha temptativa quan el subjecte dona principi a l''execució del delicte directament per fets exteriors, practicant tots o part dels actes que objectivament n''haurien de produir el resultat, i aquest no es produeix:', 'La temptativa exigeix que el resultat no es produeixi per causes alienes a la voluntat de l''autor. Si l''autor evita voluntàriament la consumació, queda exempt de responsabilitat pel delicte intentat (art. 16.2 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 16.1 CP', '1. Hay tentativa cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado, y sin embargo éste no se produce por causas independientes de la voluntad del autor.', null, '1f584c08869f4db3cb1f6f09ecfcff44d93027bd122e027abd08f1c9db7ec24a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1f584c08869f4db3cb1f6f09ecfcff44d93027bd122e027abd08f1c9db7ec24a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè l''autor desisteix voluntàriament de l''execució.', false), ('B', 'Per causes independents de la voluntat de l''autor.', true), ('C', 'Perquè l''autor impedeix la producció del resultat.', false), ('D', 'Per qualsevol causa, fins i tot el desistiment de l''autor.', false)) as v(label, body, ok)
)
