  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 62 del Codi penal, als autors de temptativa de delicte se''ls imposa la pena inferior en un o dos graus a la del delicte consumat, en l''extensió que es consideri adequada, atenent:', 'L''article 62 CP fixa dos criteris per graduar la pena de la temptativa: el perill inherent a l''intent i el grau d''execució assolit.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 62 CP', 'A los autores de tentativa de delito se les impondrá la pena inferior en uno o dos grados a la señalada por la Ley para el delito consumado, en la extensión que se estime adecuada, atendiendo al peligro inherente al intento y al grado de ejecución alcanzado.', null, '5f5f46c2ac463174510c381bdf99a5f45ae4d1e4a8605a4b99a6ab764e258e5b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f5f46c2ac463174510c381bdf99a5f45ae4d1e4a8605a4b99a6ab764e258e5b')
