with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 17.2 del Codi penal, hi ha proposició quan:', 'La proposició és la invitació a participar en un delicte feta per qui ja ha resolt cometre''l (art. 17.2 CP). Les altres opcions descriuen la conspiració (art. 17.1), la provocació i l''apologia (art. 18.1).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 17.2 CP', '2. La proposición existe cuando el que ha resuelto cometer un delito invita a otra u otras personas a participar en él.', null, '13f0456c5ee451ab50b0c18cb79d1464f7f852972ba007a7c11a6f1b9ce6e95e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '13f0456c5ee451ab50b0c18cb79d1464f7f852972ba007a7c11a6f1b9ce6e95e')
  returning id
