  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qui ha resolt cometre un delicte convida una altra o altres persones a participar-hi.', true), ('B', 'Dues o més persones es concerten per a l''execució d''un delicte i resolen executar-lo.', false), ('C', 'S''incita directament, per mitjà de la impremta o la radiodifusió, a la perpetració d''un delicte.', false), ('D', 'S''exposen, davant una concurrència de persones, idees que enalteixen el crim o el seu autor.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
