  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 18.2 del Codi penal, si a la provocació ha seguit la perpetració del delicte:', 'La provocació només es castiga en els casos que preveu la llei; però si el delicte arriba a cometre''s, el provocador respon com a inductor (art. 18.2 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 18.2 CP', 'Si a la provocación hubiese seguido la perpetración del delito, se castigará como inducción.', null, '0d49c04c3a72731a81e32c332c3d7e21464db018b95746daf3893bffae59217d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0d49c04c3a72731a81e32c332c3d7e21464db018b95746daf3893bffae59217d')
