with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20.1 del Codi penal, el trastorn mental transitori NO eximeix de pena quan:', 'L''anomalia o alteració psíquica eximeix quan impedeix comprendre la il·licitud del fet o actuar d''acord amb aquesta comprensió, però el trastorn mental transitori no eximeix si el subjecte l''ha provocat amb el propòsit de delinquir o n''ha previst o n''hauria hagut de preveure la comissió.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.1 CP', 'El trastorno mental transitorio no eximirá de pena cuando hubiese sido provocado por el sujeto con el propósito de cometer el delito o hubiera previsto o debido prever su comisión.', null, '81e92467feeea452b01c22474717747256c250e1103c43087febb2c402f7cd7a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '81e92467feeea452b01c22474717747256c250e1103c43087febb2c402f7cd7a')
  returning id
), o as (
