with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les situacions següents NO permet aplicar l''eximent de l''article 20.2 del Codi penal?', 'L''article 20.2 CP eximeix la intoxicació plena i la síndrome d''abstinència que impedeixen comprendre la il·licitud del fet, sempre que la intoxicació no s''hagi buscat amb el propòsit de cometre la infracció ni se n''hagi previst o hagut de preveure la comissió (actio libera in causa).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.2 CP', '2.º El que al tiempo de cometer la infracción penal se halle en estado de intoxicación plena por el consumo de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas u otras que produzcan efectos análogos, siempre que no haya sido buscado con el propósito de cometerla o no se hubiese previsto o debido prever su comisión, o se halle bajo la influencia de un síndrome de abstinencia', null, '294ddba267cd7afdbd123788915d41569432d37d7eb47795a50d6086e61f9ac7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '294ddba267cd7afdbd123788915d41569432d37d7eb47795a50d6086e61f9ac7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''estat d''intoxicació plena buscat pel subjecte amb el propòsit de cometre la infracció.', true), ('B', 'L''estat d''intoxicació plena per consum de begudes alcohòliques, no buscat ni previst, en el moment de cometre la infracció.', false), ('C', 'La influència d''una síndrome d''abstinència, causada per la dependència de drogues, que impedeix comprendre la il·licitud del fet.', false), ('D', 'L''estat d''intoxicació plena per consum de substàncies psicotròpiques, no buscat amb el propòsit de cometre la infracció ni previst.', false)) as v(label, body, ok)
)
