with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20.5 del Codi penal, entre els requisits de l''estat de necessitat com a eximent hi ha:', 'L''estat de necessitat exigeix que el mal causat no sigui més gran que el que es vol evitar, que la situació no l''hagi provocada intencionadament el subjecte i que el necessitat no tingui, pel seu ofici o càrrec, l''obligació de sacrificar-se. La necessitat racional del mitjà i la manca de provocació són requisits de la legítima defensa (art. 20.4).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.5 CP', 'Tercero. Que el necesitado no tenga, por su oficio o cargo, obligación de sacrificarse.', null, 'f77a4af38096f5e83eefe6ceee0d5feea3ee0f0361f87cec5ddf1c6c17040223', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f77a4af38096f5e83eefe6ceee0d5feea3ee0f0361f87cec5ddf1c6c17040223')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que hi hagi necessitat racional del mitjà emprat per impedir o repel·lir l''agressió.', false), ('B', 'Que el necessitat no tingui, pel seu ofici o càrrec, l''obligació de sacrificar-se.', true), ('C', 'Que no hi hagi hagut provocació suficient per part del defensor.', false), ('D', 'Que el mal causat sigui igual o més gran que el que es tracta d''evitar.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
