)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el darrer paràgraf de l''article 20 del Codi penal, en quins supòsits d''exempció de responsabilitat criminal s''han d''aplicar, si escau, les mesures de seguretat previstes al Codi?', 'Les mesures de seguretat es fonamenten en la perillositat criminal del subjecte; per això el Codi les preveu per als inimputables dels números 1r, 2n i 3r de l''article 20, i no per a les causes de justificació.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20 (paràgraf final) CP', 'En los supuestos de los tres primeros números se aplicarán, en su caso, las medidas de seguridad previstas en este Código.', null, 'a700407094e9e21b60c3d7f6ac1230838a5490dd128ca6e113aa604d80ffc84e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a700407094e9e21b60c3d7f6ac1230838a5490dd128ca6e113aa604d80ffc84e')
  returning id
), o as (
