with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per apreciar l''atenuant de reparació del dany de l''article 21.5 del Codi penal, el culpable ha d''haver reparat el dany ocasionat a la víctima, o n''ha d''haver disminuït els efectes:', 'L''atenuant de reparació del dany admet la reparació en qualsevol moment del procediment, però sempre abans del judici oral. El límit «abans de conèixer que el procediment es dirigeix contra ell» correspon a l''atenuant de confessió (art. 21.4 CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 21.5 CP', '5.ª La de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración del acto del juicio oral.', null, '0d3e61b8d99dba0724b3eb71bcb7f1611fc88135d85f63ec15a793fd7faeceda', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0d3e61b8d99dba0724b3eb71bcb7f1611fc88135d85f63ec15a793fd7faeceda')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Abans de conèixer que el procediment judicial es dirigeix contra ell.', false), ('B', 'En qualsevol moment, fins i tot després de dictar-se la sentència ferma.', false), ('C', 'En qualsevol moment del procediment i abans de la celebració de l''acte del judici oral.', true), ('D', 'Dins dels trenta dies següents a la comissió del fet.', false)) as v(label, body, ok)
)
