with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin d''aquests requisits NO és exigit per l''article 21.6 del Codi penal per apreciar l''atenuant de dilacions indegudes?', 'L''article 21.6 CP no fixa cap durada mínima: exigeix una dilació extraordinària i indeguda, no atribuïble a l''inculpat i desproporcionada en relació amb la complexitat de la causa.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 21.6 CP', '6.ª La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible al propio inculpado y que no guarde proporción con la complejidad de la causa.', null, '859bac3088a804e0950a593a7473c2103d85aed4635e112b61d26bfe2fa4ad8f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '859bac3088a804e0950a593a7473c2103d85aed4635e112b61d26bfe2fa4ad8f')
