with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO és una circumstància agreujant de l''article 22 del Codi penal?', 'L''arravatament o obcecació és una atenuant (art. 21.3 CP). Les altres tres són agreujants (art. 22.3a, 5a i 6a CP).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 21 i 22 CP', '3.ª La de obrar por causas o estímulos tan poderosos que hayan producido arrebato, obcecación u otro estado pasional de entidad semejante.', null, 'd59feb29c63d0a75e22eba503307ed073bd65ea6420bac88c5448010e1d7b48f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd59feb29c63d0a75e22eba503307ed073bd65ea6420bac88c5448010e1d7b48f')
  returning id
), o as (
