)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 22.1 del Codi penal, hi ha traïdoria quan el culpable comet qualsevol dels delictes contra les persones emprant en l''execució mitjans, maneres o formes que tendeixin directament o especialment a assegurar-la:', 'La traïdoria (alevosia) consisteix a assegurar l''execució eliminant el risc que pugui venir de la defensa de l''ofès. L''abús de superioritat i la disfressa són l''agreujant 2a; l''acarnissament, la 5a.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 22.1 CP', 'Hay alevosía cuando el culpable comete cualquiera de los delitos contra las personas empleando en la ejecución medios, modos o formas que tiendan directa o especialmente a asegurarla, sin el riesgo que para su persona pudiera proceder de la defensa por parte del ofendido.', null, '966c93ff10c437acc379204c52e12be3e2076bffde526fb2b1fad44b39cee363', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '966c93ff10c437acc379204c52e12be3e2076bffde526fb2b1fad44b39cee363')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb abús de superioritat o aprofitant les circumstàncies de lloc i temps.', false), ('B', 'Causant a la víctima patiments innecessaris per a l''execució del delicte.', false), ('C', 'Mitjançant disfressa o amb l''auxili d''altres persones.', false), ('D', 'Sense el risc que per a la seva persona pugui procedir de la defensa per part de l''ofès.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 22.4 del Codi penal, l''agreujant de cometre el delicte per motius racistes o per altres motius de discriminació s''aplica:', 'L''agreujant de discriminació atén el mòbil de l''autor: s''aplica encara que la condició (ideologia, ètnia, sexe, aporofòbia, malaltia, discapacitat, etc.) no concorri realment en la víctima.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 22.4 CP', 'con independencia de que tales condiciones o circunstancias concurran efectivamente en la persona sobre la que recaiga la conducta.', null, 'bbbf9215c923db9d8cd446ea6d23d5fa8c57f0388c86ea932dbf2651136d9703', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bbbf9215c923db9d8cd446ea6d23d5fa8c57f0388c86ea932dbf2651136d9703')
  returning id
), o as (
