  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només si la condició o circumstància concorre efectivament en la víctima.', false), ('B', 'Amb independència que aquestes condicions o circumstàncies concorrin efectivament en la persona sobre la qual recau la conducta.', true), ('C', 'Només en els delictes contra les persones.', false), ('D', 'Només si la discriminació s''ha manifestat públicament.', false)) as v(label, body, ok)
)
