with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionari que comet un delicte aprofitant-se de la seva condició de funcionari pot veure agreujada la seva responsabilitat per la circumstància de l''article 22.7 del Codi penal, consistent a:', 'L''agreujant 7a de l''article 22 CP és prevaler-se del caràcter públic del culpable. L''abús de confiança és la 6a i l''abús de superioritat forma part de la 2a.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 22.7 CP', '7.ª Prevalerse del carácter público que tenga el culpable.', null, '12492e6d34cc87d979c649a3ed5a26d961a08580094ff186399c21d7b4072a76', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '12492e6d34cc87d979c649a3ed5a26d961a08580094ff186399c21d7b4072a76')
