)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 22.8 del Codi penal, hi ha reincidència quan, en delinquir, el culpable ha estat condemnat executòriament per un delicte:', 'La reincidència exigeix una condemna executòria anterior per un delicte del mateix títol i de la mateixa naturalesa. No es computen els antecedents cancel·lats o cancel·lables ni els dels delictes lleus (llevat dels tipus de multireincidència).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 22.8 CP', 'Hay reincidencia cuando, al delinquir, el culpable haya sido condenado ejecutoriamente por un delito comprendido en el mismo título de este código, siempre que sea de la misma naturaleza.', 'Circumstància 8a de l''art. 22 modificada per la LO 1/2026, de 8 d''abril (BOE-A-2026-7966); la definició preguntada coincideix amb el text consolidat, però convé revisar-la per la reforma recent.', '64ea79cd80ce30dce58ab6ec6f27d991e59cc0b266e1f300b0212fa42fd6ada8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '64ea79cd80ce30dce58ab6ec6f27d991e59cc0b266e1f300b0212fa42fd6ada8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De qualsevol títol del Codi, sempre que sigui dolós.', false), ('B', 'Comprès en el mateix capítol del Codi, encara que sigui lleu.', false), ('C', 'Comprès en el mateix títol del Codi, sempre que sigui de la mateixa naturalesa.', true), ('D', 'Castigat amb una pena igual o més greu que la del nou delicte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
