with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 30.1 del Codi penal, en els delictes que es cometen utilitzant mitjans o suports de difusió mecànics:', 'L''article 30 CP exclou la responsabilitat dels còmplices i dels afavoridors en aquests delictes i estableix per als autors una responsabilitat esglaonada, excloent i subsidiària.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 30.1 CP', '1. En los delitos que se cometan utilizando medios o soportes de difusión mecánicos no responderán criminalmente ni los cómplices ni quienes los hubieren favorecido personal o realmente.', null, 'ab9f7642057546a01255312ca65e4f6c24efe3c7b2d158aeca628c8441875807', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ab9f7642057546a01255312ca65e4f6c24efe3c7b2d158aeca628c8441875807')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Responen solidàriament tots els autors i còmplices.', false), ('B', 'No responen criminalment ni els còmplices ni els qui els han afavorit personalment o realment.', true), ('C', 'Només responen els directors de l''empresa editora o difusora.', false), ('D', 'Els còmplices responen amb la pena inferior en dos graus.', false)) as v(label, body, ok)
)
