with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 31 del Codi penal, qui actua com a administrador de fet o de dret d''una persona jurídica, o en nom o representació d''un altre, respon personalment del delicte:', 'L''article 31 CP regula l''actuació en nom d''un altre: permet castigar el representant o administrador en els delictes especials encara que la qualitat típica concorri només en la persona representada.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 31 CP', 'responderá personalmente, aunque no concurran en él las condiciones, cualidades o relaciones que la correspondiente figura de delito requiera para poder ser sujeto activo del mismo, si tales circunstancias se dan en la entidad o persona en cuyo nombre o representación obre.', null, '391e6520ee1ae0b28b2fe88a112f491ad922fbb14cf944871909d05156f040bc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '391e6520ee1ae0b28b2fe88a112f491ad922fbb14cf944871909d05156f040bc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només si hi concorren personalment les condicions o qualitats que la figura de delicte requereix.', false), ('B', 'Només si la persona jurídica no és penalment responsable.', false), ('C', 'De manera subsidiària, si no es pot perseguir la persona en nom de la qual actua.', false), ('D', 'Encara que no hi concorrin les condicions, qualitats o relacions que la figura de delicte requereix, si es donen en l''entitat o persona en nom de la qual actua.', true)) as v(label, body, ok)
)
