with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 31 quinquies del Codi penal, les disposicions relatives a la responsabilitat penal de les persones jurídiques NO s''apliquen:', 'L''article 31 quinquies.1 CP exclou l''Estat, les administracions públiques territorials i institucionals, els organismes reguladors, les agències i entitats públiques empresarials, les organitzacions internacionals de dret públic i les que exerceixen potestats públiques. Les persones jurídiques de petites dimensions sí que responen (art. 31 bis.3).', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 31 quinquies CP', '1. Las disposiciones relativas a la responsabilidad penal de las personas jurídicas no serán aplicables al Estado, a las Administraciones públicas territoriales e institucionales', null, '34bb8d16307f25d4a9ad32d9a2d6763092bc520f4cb64294dfa95e3d986a7ed9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '34bb8d16307f25d4a9ad32d9a2d6763092bc520f4cb64294dfa95e3d986a7ed9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A les societats mercantils de capital privat.', false), ('B', 'A les administracions públiques territorials i institucionals.', true), ('C', 'A les associacions i fundacions privades.', false), ('D', 'A les persones jurídiques de petites dimensions.', false)) as v(label, body, ok)
)
