with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65.3 del Codi penal, quan en l''inductor o en el cooperador necessari no concorren les condicions, qualitats o relacions personals que fonamenten la culpabilitat de l''autor, els jutges o tribunals:', 'L''article 65.3 CP permet (no obliga) rebaixar en un grau la pena de l''inductor o del cooperador necessari extraneus en els delictes especials.', 'pcat_e02_delicte', (select id from public.topics where slug = 'pcat-e02-delicte'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 65.3 CP', '3. Cuando en el inductor o en el cooperador necesario no concurran las condiciones, cualidades o relaciones personales que fundamentan la culpabilidad del autor, los jueces o tribunales podrán imponer la pena inferior en grado a la señalada por la ley para la infracción de que se trate.', null, '35f94c7874ec435566011014320cab3190ee1cadfd41d84f31de9f09b7416ad8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '35f94c7874ec435566011014320cab3190ee1cadfd41d84f31de9f09b7416ad8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Han d''imposar la pena inferior en dos graus.', false), ('B', 'Han d''absoldre''ls, perquè no poden ser autors d''un delicte especial.', false), ('C', 'Han d''imposar la mateixa pena que a l''autor, en la meitat inferior.', false), ('D', 'Poden imposar la pena inferior en grau a la que assenyala la llei per a la infracció.', true)) as v(label, body, ok)
)
