with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona condemnada a presó permanent revisable per un delicte que no és de terrorisme, a partir de quan pot ser classificada en tercer grau segons l''article 36.1 del Codi penal?', 'La classificació en tercer grau requereix vint anys de presó efectiva per als delictes de terrorisme (capítol VII del títol XXII del llibre II) i quinze anys en la resta de casos. Els permisos de sortida exigeixen dotze i vuit anys, respectivament.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 36.1 CP', 'La clasificación del condenado en el tercer grado deberá ser autorizada por el tribunal […] b) Hasta el cumplimiento de quince años de prisión efectiva, en el resto de los casos.', null, '03e42d2f46d6e5a68253a692caaf5563f4b1b6a9a0507aee534cec5920b21303', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03e42d2f46d6e5a68253a692caaf5563f4b1b6a9a0507aee534cec5920b21303')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan hagi complert vint anys de presó efectiva.', false), ('B', 'Quan hagi complert quinze anys de presó efectiva.', true), ('C', 'Quan hagi complert vint-i-cinc anys de presó efectiva.', false), ('D', 'Quan hagi complert dotze anys de presó efectiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
