with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el condemnat no satisfà la multa imposada pel sistema de dies multa, segons l''article 53.1 del Codi penal queda subjecte a una responsabilitat personal subsidiària de:', 'L''impagament de la multa comporta un dia de privació de llibertat per cada dues quotes diàries no satisfetes; en delictes lleus es pot complir en localització permanent i, amb la conformitat del penat, mitjançant treballs en benefici de la comunitat.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 53.1 CP', 'quedará sujeto a una responsabilidad personal subsidiaria de un día de privación de libertad por cada dos cuotas diarias no satisfechas', null, '0a42dfe75055471711100a9821405f37552842569432318368a9bb24f26cd116', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a42dfe75055471711100a9821405f37552842569432318368a9bb24f26cd116')
  returning id
