with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 81 del Codi penal, el termini de suspensió de l''execució de les penes privatives de llibertat no superiors a dos anys és:', 'El termini de suspensió és de dos a cinc anys per a les penes privatives de llibertat no superiors a dos anys i de tres mesos a un any per a les penes lleus. En la suspensió per drogodependència de l''article 80.5 és de tres a cinc anys.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 81 CP', 'El plazo de suspensión será de dos a cinco años para las penas privativas de libertad no superiores a dos años, y de tres meses a un año para las penas leves', null, 'bb8bba2302a1f4adcd8b6822ac05c733e305844e138e9a5b115d28cff0a94132', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bb8bba2302a1f4adcd8b6822ac05c733e305844e138e9a5b115d28cff0a94132')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De dos a cinc anys.', true), ('B', 'De tres mesos a un any.', false), ('C', 'D''un a tres anys.', false), ('D', 'De tres a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
