with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les següents NO és una de les condicions necessàries per deixar en suspens l''execució de la pena que estableix l''article 80.2 del Codi penal?', 'L''article 80.2 CP exigeix delinquir per primera vegada, una pena o suma de penes no superior a dos anys i haver satisfet les responsabilitats civils i el decomís. La suspensió no requereix complir cap part de la pena.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 80.2 CP', '1.ª Que el condenado haya delinquido por primera vez. […] 2.ª Que la pena o la suma de las impuestas no sea superior a dos años, sin incluir en tal cómputo la derivada del impago de la multa. 3.ª Que se hayan satisfecho las responsabilidades civiles que se hubieren originado y se haya hecho efectivo el decomiso acordado en sentencia conforme al artículo 127.', null, 'b238c96ae575f3732b853fbe18f9b73e4754a9f306b0acb7674fb0a8c37e2675', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b238c96ae575f3732b853fbe18f9b73e4754a9f306b0acb7674fb0a8c37e2675')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el condemnat hagi delinquit per primera vegada.', false), ('B', 'Que la pena o la suma de les imposades no sigui superior a dos anys, sense incloure la derivada de l''impagament de la multa.', false), ('C', 'Que s''hagin satisfet les responsabilitats civils originades i s''hagi fet efectiu el decomís acordat en sentència.', false), ('D', 'Que el condemnat hagi complert una tercera part de la pena.', true)) as v(label, body, ok)
)
