select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80.5 del Codi penal, encara que no concorrin les condicions 1a i 2a de l''apartat 2, el jutge pot suspendre l''execució de les penes privatives de llibertat dels penats que hagin comès el fet a causa de la seva dependència de les drogues, si la pena no és superior a:', 'L''article 80.5 CP permet suspendre penes privatives de llibertat no superiors a cinc anys en aquests casos, si es certifica que el condemnat està deshabituat o sotmès a tractament.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 80.5 CP', 'el juez o tribunal podrá acordar la suspensión de la ejecución de las penas privativas de libertad no superiores a cinco años de los penados que hubiesen cometido el hecho delictivo a causa de su dependencia de las sustancias señaladas en el numeral 2.º del artículo 20', null, '0c9410f3e419c60958f6981b2351bca300935b7b33bf61b3fc79b0497a80077a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0c9410f3e419c60958f6981b2351bca300935b7b33bf61b3fc79b0497a80077a')
  returning id
), o as (
