  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 89.1 del Codi penal, les penes de presó imposades a un ciutadà estranger que se substitueixen per l''expulsió del territori espanyol són les de:', 'Les penes de presó de més d''un any imposades a un estranger se substitueixen per l''expulsió, amb les excepcions de l''article 89. L''estranger no pot tornar a Espanya en un termini de cinc a deu anys (art. 89.5).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 89.1 CP', '1. Las penas de prisión de más de un año impuestas a un ciudadano extranjero serán sustituidas por su expulsión del territorio español.', null, '80ba06785af39d22f8539d746abc3c0005a8a33629ca4560c6ee216cadca3e13', false
