  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les mesures de seguretat següents és privativa de llibertat segons l''article 96 del Codi penal?', 'Són mesures privatives de llibertat l''internament en centre psiquiàtric, en centre de deshabituació i en centre educatiu especial. La llibertat vigilada, la custòdia familiar i la inhabilitació professional són mesures no privatives (art. 96.3).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 96.2 CP', '2. Son medidas privativas de libertad: 1.ª El internamiento en centro psiquiátrico. 2.ª El internamiento en centro de deshabituación. 3.ª El internamiento en centro educativo especial.', null, 'ffb32b676076da56303cd8814ad69c0fd5c4b39c6243a3e3e0e2ab6dd0a4f100', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ffb32b676076da56303cd8814ad69c0fd5c4b39c6243a3e3e0e2ab6dd0a4f100')
