  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De fins a deu anys.', false), ('B', 'No superior a cinc anys.', true), ('C', 'No superior a tres anys.', false), ('D', 'No superior a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les següents NO és una causa d''extinció de la responsabilitat criminal segons l''article 130 del Codi penal?', 'L''article 130.1 CP enumera la mort del reu, el compliment de la condemna, la remissió definitiva de la pena, l''amnistia o l''indult, el perdó de l''ofès en els casos previstos i la prescripció del delicte, de la pena o de la mesura de seguretat. La reparació del dany és una atenuant (art. 21.5).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 130.1 CP', '1.º Por la muerte del reo. 2.º Por el cumplimiento de la condena. […] 6.º Por la prescripción del delito.', null, '0961b605e5fd914e4cbb95f1460d56d8680c04ceba22eaa684b60624ea4a9f31', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0961b605e5fd914e4cbb95f1460d56d8680c04ceba22eaa684b60624ea4a9f31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La mort del reu.', false), ('B', 'El compliment de la condemna.', false), ('C', 'La reparació del dany ocasionat a la víctima abans del judici oral.', true), ('D', 'La prescripció del delicte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 133 del Codi penal, les penes menys greus imposades per sentència ferma prescriuen:', 'Les penes lleus prescriuen a l''any, les menys greus als cinc anys i les restants penes greus als deu anys, amb terminis més llargs per a la presó i la inhabilitació de més durada (art. 133.1).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 133.1 CP', 'A los cinco, las penas menos graves.', null, '640461fbe6849618f2b06333242395cbf1aebd8dac5dd87c6cf59ffe76ba4a9e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '640461fbe6849618f2b06333242395cbf1aebd8dac5dd87c6cf59ffe76ba4a9e')
  returning id
