with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa a la durada de les penes privatives de drets, quina de les afirmacions següents NO és correcta segons l''article 40 del Codi penal?', 'La suspensió d''ocupació o càrrec públic dura de tres mesos a sis anys (art. 40.1 CP). Les altres durades són correctes.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 40 CP', '1. La pena de inhabilitación absoluta tendrá una duración de seis a 20 años; las de inhabilitación especial, de tres meses a 20 años, y la de suspensión de empleo o cargo público, de tres meses a seis años. 2. La pena de privación del derecho a conducir vehículos a motor y ciclomotores, y la de privación del derecho a la tenencia y porte de armas, tendrán una duración de tres meses a 10 años.', null, '718dd333eb0594d5a69fe50fa91575ec940f9276c3cf86d6ce309d62bfae27de', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '718dd333eb0594d5a69fe50fa91575ec940f9276c3cf86d6ce309d62bfae27de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La suspensió d''ocupació o càrrec públic té una durada de tres mesos a deu anys.', true), ('B', 'La inhabilitació absoluta té una durada de sis a vint anys.', false), ('C', 'Les inhabilitacions especials tenen una durada de tres mesos a vint anys.', false), ('D', 'La privació del dret a conduir vehicles a motor i ciclomotors té una durada de tres mesos a deu anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 40.3 del Codi penal, la prohibició d''aproximar-se a la víctima o de comunicar-s''hi té una durada:', 'La prohibició d''aproximar-se a la víctima o de comunicar-s''hi dura d''un mes a deu anys, i la privació del dret a residir en determinats llocs o anar-hi, fins a deu anys (art. 40.3 CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 40.3 CP', 'La prohibición de aproximarse a la víctima o a aquellos de sus familiares u otras personas, o de comunicarse con ellas, tendrá una duración de un mes a 10 años.', null, 'db8f6b3ffd53ba02b9c69e65e75988785e0b9065e7c722e07090e0a42dba4745', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db8f6b3ffd53ba02b9c69e65e75988785e0b9065e7c722e07090e0a42dba4745')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De sis mesos a cinc anys.', false), ('B', 'D''un mes a deu anys.', true), ('C', 'De tres mesos a vint anys.', false), ('D', 'D''un mes a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 37.3 del Codi penal, si el condemnat a localització permanent incompleix la pena, el jutge o tribunal sentenciador:', 'L''incompliment de la localització permanent dona lloc a la deducció de testimoni pel delicte de trencament de condemna de l''article 468 CP.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 37.3 CP', '3. Si el condenado incumpliera la pena, el juez o tribunal sentenciador deducirá testimonio para proceder de conformidad con lo que dispone el artículo 468.', null, 'ec7474afa0fb2b435952d578fc6f4496dfb5526d0d5d353b105d4d36698e04d1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec7474afa0fb2b435952d578fc6f4496dfb5526d0d5d353b105d4d36698e04d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La substituirà automàticament per una pena de presó d''igual durada.', false), ('B', 'La convertirà en treballs en benefici de la comunitat.', false), ('C', 'Imposarà una multa de deu a trenta dies.', false), ('D', 'En deduirà testimoni per procedir de conformitat amb l''article 468 (trencament de condemna).', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la regla general de l''article 76.1 del Codi penal, el màxim de compliment efectiu de la condemna del culpable de diversos delictes no pot excedir:', 'La regla general és el triple de la pena més greu, amb un màxim de 20 anys. Excepcionalment el límit és de 25, 30 o 40 anys segons la pena dels delictes (art. 76.1 a-d CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 76.1 CP', 'el máximo de cumplimiento efectivo de la condena del culpable no podrá exceder del triple del tiempo por el que se le imponga la más grave de las penas en que haya incurrido, declarando extinguidas las que procedan desde que las ya impuestas cubran dicho máximo, que no podrá exceder de 20 años.', null, '49d46f21f7dfed26c43225315cfd98f93ab525d18614337336c2735d82a3d906', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '49d46f21f7dfed26c43225315cfd98f93ab525d18614337336c2735d82a3d906')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El doble del temps de la pena més greu, amb un límit de 25 anys.', false), ('B', 'La suma de totes les penes imposades, amb un límit de 30 anys.', false), ('C', 'El triple del temps pel qual se li imposi la més greu de les penes, amb un límit de 20 anys.', true), ('D', 'El triple del temps de la pena més greu, amb un límit de 40 anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80.1 del Codi penal, els jutges o tribunals poden deixar en suspens l''execució de les penes privatives de llibertat no superiors a dos anys quan:', 'El fonament de la suspensió és el pronòstic favorable: que l''execució de la pena no sigui necessària per evitar nous delictes. La resolució ha de ser motivada.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 80.1 CP', 'Los jueces o tribunales, mediante resolución motivada, podrán dejar en suspenso la ejecución de las penas privativas de libertad no superiores a dos años cuando sea razonable esperar que la ejecución de la pena no sea necesaria para evitar la comisión futura por el penado de nuevos delitos.', null, 'a0e83f88edb58501a40e87a4352512a155b29657ee052fcf0377d85a9666069f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a0e83f88edb58501a40e87a4352512a155b29657ee052fcf0377d85a9666069f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El penat ho sol·liciti i el Ministeri Fiscal no s''hi oposi.', false), ('B', 'El penat hagi complert la meitat de la pena en presó provisional.', false), ('C', 'La víctima hi doni el consentiment exprés.', false), ('D', 'Sigui raonable esperar que l''execució de la pena no sigui necessària per evitar la comissió futura per part del penat de nous delictes.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 80.4 del Codi penal, si el penat pateix una malaltia molt greu amb patiments incurables, els jutges i tribunals:', 'L''article 80.4 CP permet la suspensió de qualsevol pena, sense requisits, per malaltia molt greu amb patiments incurables, amb l''única excepció de tenir ja una altra pena suspesa pel mateix motiu.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 80.4 CP', '4. Los jueces y tribunales podrán otorgar la suspensión de cualquier pena impuesta sin sujeción a requisito alguno en el caso de que el penado esté aquejado de una enfermedad muy grave con padecimientos incurables, salvo que en el momento de la comisión del delito tuviera ya otra pena suspendida por el mismo motivo.', null, 'bb959413ad09f84eff97a317b7b8830f2220679d2f3dd6580435982bf7555add', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bb959413ad09f84eff97a317b7b8830f2220679d2f3dd6580435982bf7555add')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només poden suspendre les penes de presó no superiors a cinc anys.', false), ('B', 'Poden atorgar la suspensió de qualsevol pena imposada sense subjecció a cap requisit, llevat que ja tingués una altra pena suspesa pel mateix motiu en el moment de cometre el delicte.', true), ('C', 'Han de suspendre la pena, però sempre condicionada a la reparació del dany.', false), ('D', 'Han de substituir la pena per la de localització permanent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 90.5 del Codi penal, el termini de suspensió de l''execució de la resta de la pena en la llibertat condicional és:', 'El termini és de dos a cinc anys, però mai inferior a la pena pendent, i es computa des de la posada en llibertat del penat (art. 90.5 CP). El de cinc a deu anys és el de la presó permanent revisable (art. 92.3).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 90.5 CP', 'El plazo de suspensión de la ejecución del resto de la pena será de dos a cinco años. En todo caso, el plazo de suspensión de la ejecución y de libertad condicional no podrá ser inferior a la duración de la parte de pena pendiente de cumplimiento.', null, 'af1bd50e959102c496a43441998314b3b5b395092055a5c614d9f927dacc8f90', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'af1bd50e959102c496a43441998314b3b5b395092055a5c614d9f927dacc8f90')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'D''un a tres anys, sigui quina sigui la pena pendent.', false), ('B', 'De cinc a deu anys.', false), ('C', 'De dos a cinc anys, i no pot ser inferior a la durada de la part de la pena pendent de compliment.', true), ('D', 'Igual, en tot cas, a la durada de la part de la pena pendent de compliment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 92.4 del Codi penal, un cop extingida la part de la condemna exigida per a la suspensió de la presó permanent revisable, amb quina periodicitat mínima ha de verificar el tribunal el compliment de la resta de requisits de la llibertat condicional?', 'El tribunal ha de verificar els requisits almenys cada dos anys i, després de rebutjar una petició, pot fixar un termini de fins a un any en què no s''admetin noves sol·licituds (art. 92.4 CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 92.4 CP', 'el tribunal deberá verificar, al menos cada dos años, el cumplimiento del resto de requisitos de la libertad condicional.', null, 'db319a919307a1f91e402b00b05290dd0ddcde8d80cbcc395e3cfe88d18b6e2e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db319a919307a1f91e402b00b05290dd0ddcde8d80cbcc395e3cfe88d18b6e2e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys cada dos anys.', true), ('B', 'Almenys cada any.', false), ('C', 'Almenys cada sis mesos.', false), ('D', 'Almenys cada cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 101.1 del Codi penal, l''internament per a tractament mèdic o educació especial del subjecte declarat exempt de responsabilitat per anomalia o alteració psíquica:', 'L''internament té com a límit màxim la durada de la pena que s''hauria imposat; el jutge o tribunal fixa aquest límit a la sentència.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 101.1 CP', 'El internamiento no podrá exceder del tiempo que habría durado la pena privativa de libertad, si hubiera sido declarado responsable el sujeto, y a tal efecto el Juez o Tribunal fijará en la sentencia ese límite máximo.', null, '11413101f8eeb7d763af06ba686b91f8e187295f7d1f23a20d6eabfaf2476fc0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11413101f8eeb7d763af06ba686b91f8e187295f7d1f23a20d6eabfaf2476fc0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pot durar indefinidament mentre persisteixi la perillositat.', false), ('B', 'No pot excedir del temps que hauria durat la pena privativa de llibertat si hagués estat declarat responsable.', true), ('C', 'No pot excedir de cinc anys.', false), ('D', 'No pot excedir de la meitat de la pena que li hauria correspost.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels delictes següents NO és imprescriptible segons l''article 131.3 del Codi penal?', 'No prescriuen mai els delictes de lesa humanitat, de genocidi, els delictes contra les persones i béns protegits en cas de conflicte armat (llevat dels de l''art. 614) i els de terrorisme que han causat la mort d''una persona. L''assassinat comú prescriu (art. 131.1 CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 131.3 CP', '3. Los delitos de lesa humanidad y de genocidio y los delitos contra las personas y bienes protegidos en caso de conflicto armado, salvo los castigados en el artículo 614, no prescribirán en ningún caso. Tampoco prescribirán los delitos de terrorismo, si hubieren causado la muerte de una persona.', null, '644e4cf9a7c3d43c76982f7b243e93f767d5bc6e5410d7f736520c6464cbbf43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '644e4cf9a7c3d43c76982f7b243e93f767d5bc6e5410d7f736520c6464cbbf43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El genocidi.', false), ('B', 'Els delictes de lesa humanitat.', false), ('C', 'Els delictes de terrorisme que han causat la mort d''una persona.', false), ('D', 'L''assassinat amb traïdoria d''una sola persona, sense vinculació terrorista.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 37.1 del Codi penal, quan la localització permanent està prevista com a pena principal, atenent la reiteració en la comissió de la infracció i sempre que el precepte aplicable ho disposi expressament, el jutge pot acordar en sentència que es compleixi:', 'La localització permanent es compleix normalment al domicili o en el lloc que fixi el jutge, però en cas de reiteració i si el precepte ho preveu, es pot complir els caps de setmana i festius al centre penitenciari més proper al domicili.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 37.1 CP', 'el Juez podrá acordar en sentencia que la pena de localización permanente se cumpla los sábados, domingos y días festivos en el centro penitenciario más próximo al domicilio del penado', null, 'b5b30848016008202e63859aff3c6d0ed786cdf86298d6be91c2a41e887bfb69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b5b30848016008202e63859aff3c6d0ed786cdf86298d6be91c2a41e887bfb69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els dissabtes, diumenges i dies festius en el centre penitenciari més proper al domicili del penat.', true), ('B', 'De dilluns a divendres en un centre d''inserció social.', false), ('C', 'Al domicili del penat amb un dispositiu electrònic durant el doble de temps.', false), ('D', 'En un centre penitenciari, en règim tancat, de manera continuada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
