with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 36.1 del Codi penal, un condemnat a presó permanent revisable per un delicte que no és de terrorisme no pot gaudir de permisos de sortida fins que hagi complert un mínim de:', 'Els permisos de sortida dels condemnats a presó permanent revisable exigeixen un mínim de dotze anys de presó en els delictes de terrorisme del capítol VII del títol XXII i de vuit anys en la resta de casos.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 36.1 CP', 'el penado no podrá disfrutar de permisos de salida hasta que haya cumplido un mínimo de doce años de prisión, en el caso previsto en la letra a), y ocho años de prisión, en el previsto en la letra b).', null, 'dda0f980d33e69dfbe9e1a8104b50ca79fa256ca93fd12bfcfd4c7f9bd347d6e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dda0f980d33e69dfbe9e1a8104b50ca79fa256ca93fd12bfcfd4c7f9bd347d6e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dotze anys de presó.', false), ('B', 'Quinze anys de presó.', false), ('C', 'Vuit anys de presó.', true), ('D', 'Cinc anys de presó.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 36.2 del Codi penal, quan la durada de la pena de presó imposada és superior a cinc anys, el jutge o tribunal pot ordenar que la classificació del condemnat en tercer grau no s''efectuï fins:', 'És l''anomenat període de seguretat. És potestatiu en general i obligatori per als delictes enumerats a l''article 36.2 (terrorisme, organització o grup criminal, determinats delictes sexuals i de tràfic d''éssers humans).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 36.2 CP', 'Cuando la duración de la pena de prisión impuesta sea superior a cinco años, el juez o tribunal podrá ordenar que la clasificación del condenado en el tercer grado de tratamiento penitenciario no se efectúe hasta el cumplimiento de la mitad de la pena impuesta.', null, '778a774bce3400716151f35908c3e9d7d824069cdc7ab5fcf0ccdd7226590ccb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '778a774bce3400716151f35908c3e9d7d824069cdc7ab5fcf0ccdd7226590ccb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al compliment de les tres quartes parts de la pena imposada.', false), ('B', 'Al compliment d''una quarta part de la pena imposada.', false), ('C', 'Al compliment de la meitat de la pena imposada.', true), ('D', 'Al compliment de les dues terceres parts de la pena imposada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 58.2 del Codi penal, qui ha d''acordar l''abonament de la presó provisional en una causa diferent d''aquella en què es va decretar?', 'L''abonament en una causa diferent l''acorda d''ofici o a petició del penat el jutge de vigilància penitenciària, després de comprovar que no s''ha abonat en una altra causa i amb audiència del ministeri fiscal.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 58.2 CP', '2. El abono de prisión provisional en causa distinta de la que se decretó será acordado de oficio o a petición del penado y previa comprobación de que no ha sido abonada en otra causa, por el Juez de Vigilancia Penitenciaria de la jurisdicción de la que dependa el centro penitenciario en que se encuentre el penado, previa audiencia del ministerio fiscal.', null, '46fae07aef00ff0d3110e3cc2feb2df54350ca25356ce34b6772d9a64a236580', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '46fae07aef00ff0d3110e3cc2feb2df54350ca25356ce34b6772d9a64a236580')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge o tribunal que va decretar la presó provisional.', false), ('B', 'El director del centre penitenciari, a proposta de la junta de tractament.', false), ('C', 'El jutge o tribunal sentenciador de la causa més recent, sense audiència del fiscal.', false), ('D', 'El jutge de vigilància penitenciària de la jurisdicció de la qual depengui el centre penitenciari on es trobi el penat, amb audiència prèvia del ministeri fiscal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan se suspèn la pena per un delicte comès sobre la dona per qui és o ha estat el seu cònjuge o parella, encara que sense convivència, quines regles de l''article 83.1 del Codi penal s''han d''imposar sempre?', 'En aquests casos s''imposen sempre la prohibició d''aproximar-se a la víctima o de comunicar-s''hi (1a), la prohibició de residir en un lloc determinat o d''anar-hi (4a) i la participació en programes formatius (6a).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 83.2 CP', 'se impondrán siempre las prohibiciones y deberes indicados en las reglas 1.ª, 4.ª y 6.ª del apartado anterior.', null, 'a9bf1ee17a7ea7209e0dc6d29dc9392ff3449a44f86891f0099613b00fc5b4f1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a9bf1ee17a7ea7209e0dc6d29dc9392ff3449a44f86891f0099613b00fc5b4f1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les regles 1a, 2a i 3a.', false), ('B', 'Les regles 1a, 4a i 6a.', true), ('C', 'Les regles 5a, 7a i 9a.', false), ('D', 'Només la regla 1a.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 90.3 del Codi penal, excepcionalment el jutge de vigilància penitenciària pot concedir la llibertat condicional als penats que compleixen la seva primera condemna de presó, si aquesta no supera els tres anys de durada i han extingit:', 'La llibertat condicional excepcional de primaris exigeix primera condemna de presó no superior a tres anys i haver extingit la meitat de la condemna. No s''aplica als condemnats per delictes contra la llibertat i la indemnitat sexuals.', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 90.3 CP', 'a) Que se encuentren cumpliendo su primera condena de prisión y que ésta no supere los tres años de duración. b) Que hayan extinguido la mitad de su condena.', null, '217eead21d3913afd12b093d560fb89271ca9ced99e6ef1a161d2f27f04eb199', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '217eead21d3913afd12b093d560fb89271ca9ced99e6ef1a161d2f27f04eb199')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La meitat de la condemna.', true), ('B', 'Les dues terceres parts de la condemna.', false), ('C', 'Una tercera part de la condemna.', false), ('D', 'Les tres quartes parts de la condemna.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 92.3 del Codi penal, la suspensió de l''execució de la pena de presó permanent revisable té una durada:', 'La suspensió de la presó permanent revisable dura de cinc a deu anys i es computa des de la posada en llibertat del penat (art. 92.3 CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 92.3 CP', '3. La suspensión de la ejecución tendrá una duración de cinco a diez años. El plazo de suspensión y libertad condicional se computará desde la fecha de puesta en libertad del penado.', null, 'f392adbb923f0d7f98951f5b85714f1b0294c18021522f28808984418ac1053d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f392adbb923f0d7f98951f5b85714f1b0294c18021522f28808984418ac1053d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De cinc a deu anys.', true), ('B', 'De dos a cinc anys.', false), ('C', 'De deu a quinze anys.', false), ('D', 'Igual a la de la part de la pena pendent de compliment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 33.5 del Codi penal, quina naturalesa té la responsabilitat personal subsidiària per impagament de multa?', 'La responsabilitat personal subsidiària té la mateixa naturalesa (menys greu o lleu) que la multa que substitueix (art. 33.5 CP).', 'pcat_e03_penes', (select id from public.topics where slug = 'pcat-e03-penes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 33.5 CP', '5. La responsabilidad personal subsidiaria por impago de multa tendrá naturaleza menos grave o leve, según la que corresponda a la pena que sustituya.', null, 'e8383747922ddcef831f4cb9f25166b58ff75244c08d0e27ac7504d8d93f8530', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e8383747922ddcef831f4cb9f25166b58ff75244c08d0e27ac7504d8d93f8530')
  returning id
), o as (
