with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 234.1 del Codi penal, el furt és castigat amb la pena de presó de sis a divuit mesos quan la quantia del que s''ha sostret:', 'El furt de més de 400 euros es castiga amb presó de sis a divuit mesos; si no excedeix de 400 euros, amb multa d''un a tres mesos, llevat que concorri alguna circumstància de l''article 235 (art. 234.2).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234.1 CP', 'será castigado, como reo de hurto, con la pena de prisión de seis a dieciocho meses si la cuantía de lo sustraído excediese de 400 euros.', null, '78c57daabfcd38afc394bc0302f3ce7e3e342662fefa06c14f8ad8ef9c4445b6', false
