with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 550.2 del Codi penal, l''atemptat contra un funcionari públic que no té la condició d''autoritat es castiga amb la pena de:', 'L''atemptat contra l''autoritat es castiga amb presó d''un a quatre anys i multa de tres a sis mesos, i en els altres casos (agents i funcionaris públics), amb presó de sis mesos a tres anys (art. 550.2). Per a determinades autoritats (art. 550.3), la presó és d''un a sis anys i la multa de sis a dotze mesos. La resistència o desobediència greus de l''article 556 es castiguen amb presó de tres mesos a un any o multa de sis a divuit mesos.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 550.2 CP', '2. Los atentados serán castigados con las penas de prisión de uno a cuatro años y multa de tres a seis meses si el atentado fuera contra autoridad y de prisión de seis meses a tres años en los demás casos.', null, '8890eda7fe1a2f98bf6b04a782d96f53f6389f581504cab8b2d1f0383fac8614', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8890eda7fe1a2f98bf6b04a782d96f53f6389f581504cab8b2d1f0383fac8614')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a quatre anys i multa de tres a sis mesos.', false), ('B', 'Presó de sis mesos a tres anys.', true), ('C', 'Presó d''un a sis anys i multa de sis a dotze mesos.', false), ('D', 'Presó de tres mesos a un any o multa de sis a divuit mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
