with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 551 del Codi penal, quina conseqüència té que l''atemptat es cometi amb ocasió d''un motí, plante o incident col·lectiu a l''interior d''un centre penitenciari?', 'L''article 551 CP preveu les penes superiors en grau quan l''atemptat es comet amb armes o objectes perillosos, amb actes potencialment perillosos per a la vida, amb un vehicle de motor o amb ocasió d''un motí, plante o incident col·lectiu a l''interior d''un centre penitenciari.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 551.4 CP', 'Se impondrán las penas superiores en grado a las respectivamente previstas en el artículo anterior siempre que el atentado se cometa: […] 4.º Cuando los hechos se lleven a cabo con ocasión de un motín, plante o incidente colectivo en el interior de un centro penitenciario.', null, 'ea97ca3c7074b0c18bebdaf62efb920c7cf3b4af76f0a1ebd2972e8b6500558c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ea97ca3c7074b0c18bebdaf62efb920c7cf3b4af76f0a1ebd2972e8b6500558c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposen les penes de l''article 550 en la meitat superior.', false), ('B', 'S''imposen les penes inferiors en grau, perquè es tracta d''un fet col·lectiu.', false), ('C', 'No té conseqüències específiques; s''aplica l''agreujant genèrica d''abús de superioritat.', false), ('D', 'S''imposen les penes superiors en grau a les previstes a l''article 550.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
