  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 178.1 del Codi penal, qui fa qualsevol acte que atempti contra la llibertat sexual d''una altra persona sense el seu consentiment és castigat, com a responsable d''agressió sexual, amb la pena de presó de:', 'El tipus bàsic d''agressió sexual es castiga amb presó d''un a quatre anys; si hi ha violència o intimidació o la víctima té la voluntat anul·lada, d''un a cinc anys (art. 178.3 CP).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 178.1 CP', '1. Será castigado con la pena de prisión de uno a cuatro años, como responsable de agresión sexual, el que realice cualquier acto que atente contra la libertad sexual de otra persona sin su consentimiento.', null, 'd8bcfc84b259c6e597ea843d8cb54fae6fc222b34ee6698d6a00e8df854000d0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd8bcfc84b259c6e597ea843d8cb54fae6fc222b34ee6698d6a00e8df854000d0')
  returning id
