with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 234.2 del Codi penal, si la quantia del que s''ha sostret en un furt no excedeix de 400 euros i no concorre cap circumstància de l''article 235, la pena és de:', 'El furt de fins a 400 euros es castiga amb multa d''un a tres mesos, llevat dels casos de multireincidència (almenys tres condemnes per delictes de la mateixa naturalesa del títol), en què s''aplica la pena de l''apartat 1.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 234.2 CP', '2. Se impondrá la pena de multa de uno a tres meses si la cuantía de lo sustraído no excediese de 400 euros, salvo si concurriere alguna de las circunstancias del artículo 235.', 'Art. 234.2 modificat per la LO 1/2026, de 8 d''abril (BOE-A-2026-7966); reforma recent: confirmar que la pena del furt de fins a 400 euros es manté en la redacció vigent.', '7272cfa0a6135d66b58b6a88f3c3c885882c79a24c1e80b83f5e7b32b28c42af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7272cfa0a6135d66b58b6a88f3c3c885882c79a24c1e80b83f5e7b32b28c42af')
