with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels elements següents NO forma part de la definició del delicte de robatori de l''article 237 del Codi penal?', 'El robatori és l''apoderament de coses mobles alienes amb ànim de lucre emprant força en les coses o violència o intimidació en les persones, sigui quin sigui el valor. El llindar de 400 euros distingeix les modalitats del furt (art. 234 CP).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 237 CP', 'Son reos del delito de robo los que, con ánimo de lucro, se apoderaren de las cosas muebles ajenas empleando fuerza en las cosas para acceder o abandonar el lugar donde éstas se encuentran o violencia o intimidación en las personas', null, 'e271b3b20dc22868fe41c1eabea1c6b4b4b6386f1544db113adceb7cce2bdf7b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e271b3b20dc22868fe41c1eabea1c6b4b4b6386f1544db113adceb7cce2bdf7b')
  returning id
