  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 139.2 del Codi penal, quan en un assassinat concorre més d''una de les circumstàncies de l''apartat 1 (traïdoria, preu, acarnissament, facilitar o encobrir un altre delicte):', 'La concurrència de diverses circumstàncies de l''assassinat no crea delictes diferents: la pena de 15 a 25 anys s''imposa en la meitat superior (art. 139.2 CP).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 139.2 CP', '2. Cuando en un asesinato concurran más de una de las circunstancias previstas en el apartado anterior, se impondrá la pena en su mitad superior.', null, '478b8358f144f5b3345afccecf85a209bd2b425085d7ad6658c561c0e4e44875', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '478b8358f144f5b3345afccecf85a209bd2b425085d7ad6658c561c0e4e44875')
  returning id
