)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les conductes següents NO constitueix el delicte d''atemptat de l''article 550.1 del Codi penal?', 'Són atemptat l''agressió, la resistència greu amb intimidació greu o violència i l''escomesa a l''autoritat, als seus agents o als funcionaris públics, i sempre els actes contra funcionaris docents o sanitaris. La falta de respecte a l''autoritat és un delicte lleu de l''article 556.2 CP.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 550.1 CP', '1. Son reos de atentado los que agredieren o, con intimidación grave o violencia, opusieren resistencia grave a la autoridad, a sus agentes o funcionarios públicos, o los acometieren, cuando se hallen en el ejercicio de las funciones de sus cargos o con ocasión de ellas. En todo caso, se considerarán actos de atentado los cometidos contra los funcionarios docentes o sanitarios', null, '6f05094855f41374cb500ff9bfb5304f1dc60f96298056368ba629cadbb19a20', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6f05094855f41374cb500ff9bfb5304f1dc60f96298056368ba629cadbb19a20')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Faltar al respecte i a la consideració deguda a l''autoritat en l''exercici de les seves funcions.', true), ('B', 'Agredir un funcionari públic en l''exercici de les funcions del seu càrrec.', false), ('C', 'Oposar resistència greu, amb violència, a un agent de l''autoritat amb ocasió de les seves funcions.', false), ('D', 'Escometre un funcionari sanitari en l''exercici de les funcions pròpies del seu càrrec.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
