with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 174.1 del Codi penal, quina pena de presó correspon al culpable de tortura si l''atemptat és greu?', 'La tortura es castiga amb presó de dos a sis anys si l''atemptat és greu i d''un a tres anys si no ho és, i a més amb inhabilitació absoluta de vuit a dotze anys en tot cas.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 174.1 CP', 'El culpable de tortura será castigado con la pena de prisión de dos a seis años si el atentado fuera grave, y de prisión de uno a tres años si no lo es.', null, 'a81c66d8edb42e44d750ca5b545bc5222611ce08aa460d89908d36b7965fec27', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a81c66d8edb42e44d750ca5b545bc5222611ce08aa460d89908d36b7965fec27')
