)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''autoritat o funcionari públic que, abusant del seu càrrec i fora dels casos de tortura, atempta contra la integritat moral d''una persona, segons l''article 175 del Codi penal és castigat, si l''atemptat és greu, amb:', 'L''article 175 CP castiga l''atemptat contra la integritat moral comès per autoritat o funcionari amb presó de dos a quatre anys si és greu i de sis mesos a dos anys si no ho és, i en tot cas amb inhabilitació especial de dos a quatre anys.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 175 CP', 'será castigado con la pena de prisión de dos a cuatro años si el atentado fuera grave, y de prisión de seis meses a dos años si no lo es. Se impondrá, en todo caso, al autor, además de las penas señaladas, la de inhabilitación especial para empleo o cargo público de dos a cuatro años.', null, 'd6391fdd6cdcc5cf906b456f709d881a35de158aaf17417870e763760d2c2d6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6391fdd6cdcc5cf906b456f709d881a35de158aaf17417870e763760d2c2d6b')
