  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO és una de les agreujants del tràfic de drogues previstes a l''article 369.1 del Codi penal?', 'Ser consumidor no és cap de les agreujants de l''article 369.1 CP. Les altres tres hi figuren (circumstàncies 1a, 4a i 5a), al costat del tràfic en establiments penitenciaris (7a).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 369.1 CP', '1.ª El culpable fuere autoridad, funcionario público, facultativo, trabajador social, docente o educador y obrase en el ejercicio de su cargo, profesión u oficio. […] 4.ª Las sustancias a que se refiere el artículo anterior se faciliten a menores de 18 años […] 5.ª Fuere de notoria importancia la cantidad de las citadas sustancias', null, 'f6d3bfa0bc93408936e1c532de97c3ee423511225aa526673733f6e96783e392', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f6d3bfa0bc93408936e1c532de97c3ee423511225aa526673733f6e96783e392')
