  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 556.1 del Codi penal, els qui, sense estar compresos a l''article 550, resisteixen o desobeeixen greument l''autoritat o els seus agents en l''exercici de les seves funcions són castigats amb:', 'La resistència o desobediència greu es castiga amb presó de tres mesos a un any o multa de sis a divuit mesos; la falta de respecte a l''autoritat, amb multa d''un a tres mesos (art. 556.2 CP).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 556.1 CP', '1. Serán castigados con la pena de prisión de tres meses a un año o multa de seis a dieciocho meses, los que, sin estar comprendidos en el artículo 550, resistieren o desobedecieren gravemente a la autoridad o sus agentes en el ejercicio de sus funciones', null, '70b62d56f6e4eb14ed7e5ccdbe65870618d80a111db1e4787c8648c38d7ad706', false
