)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 173.4 del Codi penal, qui causa una injúria o vexació injusta de caràcter lleu a una de les persones de l''article 173.2 és castigat amb:', 'La injúria o vexació lleu en l''àmbit familiar és un delicte lleu, perseguible només amb denúncia de la persona agreujada o del seu representant legal; la multa només és possible si no hi ha relacions econòmiques entre autor i víctima (art. 84.2).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 173.4 CP', 'será castigado con la pena de localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima, o trabajos en beneficio de la comunidad de cinco a treinta días, o multa de uno a cuatro meses, esta última únicamente en los supuestos en los que concurren las circunstancias expresadas en el apartado 2 del artículo 84.', null, 'ce25fd56f8a66a24509bf94452f15d8b7b09d7b3156d78829a84074aa352b5d6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ce25fd56f8a66a24509bf94452f15d8b7b09d7b3156d78829a84074aa352b5d6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a un any o treballs en benefici de la comunitat de trenta-un a vuitanta dies.', false), ('B', 'Multa d''un a tres mesos, perseguible d''ofici.', false), ('C', 'Presó de tres mesos a un any i privació del dret a la tinença i portada d''armes.', false), ('D', 'Localització permanent de cinc a trenta dies, sempre en un domicili diferent i allunyat del de la víctima, treballs en benefici de la comunitat de cinc a trenta dies o multa d''un a quatre mesos en els casos de l''article 84.2.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 177 del Codi penal, si en els delictes de tortura i contra la integritat moral, a més de l''atemptat a la integritat moral, es produeix una lesió o dany a la vida, la integritat física, la salut, la llibertat sexual o els béns de la víctima o d''un tercer:', 'L''article 177 CP estableix una regla de concurs real: l''atemptat a la integritat moral es castiga a part dels resultats lesius, llevat que ja estiguin especialment castigats.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 177 CP', 'se castigarán los hechos separadamente con la pena que les corresponda por los delitos cometidos, excepto cuando aquél ya se halle especialmente castigado por la ley.', null, '639c955e41b6193439b1fd44a82f9dba80c9de50d20f5f5d57e8f481bd4b6992', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '639c955e41b6193439b1fd44a82f9dba80c9de50d20f5f5d57e8f481bd4b6992')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''aplica només la pena del delicte més greu.', false), ('B', 'La pena del delicte contra la integritat moral absorbeix la de la lesió.', false), ('C', 'S''imposa la pena del delicte contra la integritat moral en la meitat superior.', false), ('D', 'Els fets es castiguen separadament amb la pena que correspongui per cada delicte, excepte quan aquell ja estigui castigat especialment per la llei.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO és una de les que agreugen les agressions sexuals segons l''article 180.1 del Codi penal?', 'L''article 180.1 CP enumera set circumstàncies (actuació conjunta, violència extrema o actes degradants, especial vulnerabilitat, víctima esposa o parella, prevaliment, ús d''armes i submissió química). Cometre el fet en un lloc públic no n''és cap.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 180.1 CP', '1.ª Cuando los hechos se cometan por la actuación conjunta de dos o más personas. […] 4.ª Cuando la víctima sea o haya sido esposa o mujer que esté o haya estado ligada por análoga relación de afectividad, aun sin convivencia. […] 7.ª Cuando para la comisión de estos hechos la persona responsable haya anulado la voluntad de la víctima suministrándole fármacos, drogas o cualquier otra sustancia natural o química idónea a tal efecto.', null, 'b2a463731241c89312d4cac99d95884a75d78d8d43ea7bbd1647a5a720e2727b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b2a463731241c89312d4cac99d95884a75d78d8d43ea7bbd1647a5a720e2727b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que els fets es cometin per l''actuació conjunta de dues o més persones.', false), ('B', 'Que la víctima sigui o hagi estat esposa o parella de l''autor, encara que sense convivència.', false), ('C', 'Que els fets es cometin en un lloc públic.', true), ('D', 'Que el responsable hagi anul·lat la voluntat de la víctima subministrant-li fàrmacs, drogues o qualsevol altra substància idònia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el segon paràgraf de l''article 368 del Codi penal, els tribunals poden imposar la pena inferior en grau en el tràfic de drogues atenent l''escassa entitat del fet i les circumstàncies personals del culpable, però NO poden fer ús d''aquesta facultat:', 'La rebaixa en grau per escassa entitat és aplicable tant a les drogues que causen greu dany com a les altres, però queda exclosa quan hi concorren les circumstàncies dels articles 369 bis (organitzacions) o 370 (extrema gravetat, ús de menors, caps d''organització).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 368 (paràgraf segon) CP', 'No se podrá hacer uso de esta facultad si concurriere alguna de las circunstancias a que se hace referencia en los artículos 369 bis y 370.', null, '531d7e51363bf63f025bce3a9067db08d2f15b79e148ee8d52010a36f76b971b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '531d7e51363bf63f025bce3a9067db08d2f15b79e148ee8d52010a36f76b971b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si la substància causa greu dany a la salut.', false), ('B', 'Si concorre alguna de les circumstàncies dels articles 369 bis i 370.', true), ('C', 'Si el culpable té antecedents penals per qualsevol delicte.', false), ('D', 'Si el fet s''ha comès a la via pública.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 550.3 del Codi penal, si l''autoritat contra la qual s''atempta és un jutge, un magistrat o un membre del Ministeri Fiscal, la pena és de:', 'L''atemptat contra membres del Govern, dels consells de govern autonòmics, de les cambres legislatives, de les corporacions locals, del CGPJ, magistrats del TC, jutges, magistrats o fiscals es castiga amb presó d''un a sis anys i multa de sis a dotze mesos.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 550.3 CP', 'Magistrado del Tribunal Constitucional, juez, magistrado o miembro del Ministerio Fiscal, se impondrá la pena de prisión de uno a seis años y multa de seis a doce meses.', null, 'f15928822c7ec6bd124200a4756bf111a90b9b390a9cc5afbcd941667c9c29b5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f15928822c7ec6bd124200a4756bf111a90b9b390a9cc5afbcd941667c9c29b5')
  returning id
), o as (
