  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a sis anys i multa de sis a dotze mesos.', true), ('B', 'Presó d''un a quatre anys i multa de tres a sis mesos.', false), ('C', 'Presó de dos a sis anys i multa de dotze a vint-i-quatre mesos.', false), ('D', 'Presó de sis mesos a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 554.3 del Codi penal, també s''imposen les penes dels articles 550 i 551 a qui escomet, empra violència o intimida greument:', 'L''article 554.3 CP estén les penes de l''atemptat als bombers, al personal sanitari o equips de socors que intervenen en un sinistre o emergència i al personal de seguretat privada identificat que actua en cooperació amb les forces i cossos de seguretat. Els militars hi queden inclosos quan vesteixen uniforme i presten un servei encomanat (art. 554.1).', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 554.3 CP', 'b) Al personal de seguridad privada, debidamente identificado, que desarrolle actividades de seguridad privada en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad.', null, '973f77b68422833978f73e469de3a8627fdd99025cd653ad20bb957fe82dc1b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '973f77b68422833978f73e469de3a8627fdd99025cd653ad20bb957fe82dc1b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol empleat d''una empresa privada en l''exercici de la seva feina.', false), ('B', 'El personal de seguretat privada, degudament identificat, que fa activitats de seguretat privada en cooperació i sota el comandament de les forces i cossos de seguretat.', true), ('C', 'Els vigilants d''aparcaments públics, encara que no estiguin identificats.', false), ('D', 'Els membres de les forces armades, encara que no vesteixin l''uniforme.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 235.1 del Codi penal, el furt es castiga amb la pena de presó d''un a tres anys, entre altres casos, quan els objectes sostrets són:', 'El numeral 10è de l''article 235.1 CP inclou els telèfons mòbils i altres dispositius que poden contenir dades personals, excepte els que són a la venda, en magatzem o en exposició en establiments comercials.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 235.1.10è CP', '10.º Cuando los objetos sustraídos fueran teléfonos móviles. Así mismo, cualquier otro dispositivo móvil de comunicación, o de almacenamiento masivo de información digital susceptible de contener datos e información de carácter personal.', 'Numeral 10è afegit a l''art. 235.1 per la LO 1/2026, de 8 d''abril (BOE-A-2026-7966); reforma molt recent, convé confirmar-ne la vigència i si entra al temari de la propera convocatòria.', 'b289c44bc8ca5588c4243d2b037493ee53530ce4f848db54611e08bd7734d529', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b289c44bc8ca5588c4243d2b037493ee53530ce4f848db54611e08bd7734d529')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol objecte de valor superior a 400 euros.', false), ('B', 'Vehicles de motor de qualsevol valor.', false), ('C', 'Diners en efectiu, sigui quina sigui la quantia.', false), ('D', 'Telèfons mòbils o altres dispositius mòbils de comunicació o d''emmagatzematge massiu d''informació digital, llevat dels que estiguin a la venda o exposats en establiments comercials.', true)) as v(label, body, ok)
)
