-- Lote pcat-e04-principals-delictes-lovg-v1 (3 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2004, de 28 de diciembre, de Medidas de Protección Integral contra la Violencia de Género (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e04-principals-delictes', 'Tema 4. Els principals delictes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e04-principals-delictes' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.1 de la Llei orgànica 1/2004, de mesures de protecció integral contra la violència de gènere, aquesta llei actua contra la violència que s''exerceix sobre les dones per part de:', 'L''objecte de la LO 1/2004 és la violència exercida sobre les dones, com a manifestació de la discriminació i de les relacions de poder dels homes sobre les dones, per part de cònjuges, excònjuges o parelles o exparelles, encara que no hi hagi convivència.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.1 LO 1/2004', 'se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.', null, '6993bb140ada9950a469891cb613873940bc31d6ecf29fb8b9c7896c4cb717ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6993bb140ada9950a469891cb613873940bc31d6ecf29fb8b9c7896c4cb717ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qui siguin o hagin estat els seus cònjuges o qui hi estiguin o hagin estat lligats per relacions similars d''afectivitat, fins i tot sense convivència.', true), ('B', 'Qualsevol membre del seu nucli familiar, amb convivència o sense.', false), ('C', 'El seu cònjuge actual o la persona amb qui convisquin de manera estable.', false), ('D', 'Qualsevol home, en qualsevol àmbit de les relacions socials o laborals.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 1.3 de la Llei orgànica 1/2004, la violència de gènere a què es refereix la llei comprèn tot acte de violència física i psicològica, incloses:', 'L''article 1.3 de la LO 1/2004 hi inclou expressament les agressions a la llibertat sexual, les amenaces, les coaccions i la privació arbitrària de llibertat.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.3 LO 1/2004', '3. La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.', null, '36d6c927b86b0a077a6d8f02b8c7076fb0d465638a72792433f24032bb9489e7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '36d6c927b86b0a077a6d8f02b8c7076fb0d465638a72792433f24032bb9489e7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les agressions a la llibertat sexual.', false), ('B', 'Totes les respostes anteriors són correctes.', true), ('C', 'Les amenaces i les coaccions.', false), ('D', 'La privació arbitrària de llibertat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.4 de la Llei orgànica 1/2004, de mesures de protecció integral contra la violència de gènere, la violència de gènere també comprèn:', 'L''apartat 4, afegit per la LO 8/2021, inclou la violència vicària: la que s''exerceix sobre familiars o persones properes menors d''edat per causar dany a la dona.', 'pcat_e04_principals_delictes', (select id from public.topics where slug = 'pcat-e04-principals-delictes'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.4 LO 1/2004', '4. La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.', null, 'a1a8a65aac69d19bcb88d23adc5bcf1d046cc053d32596b926f13ee1ea43156a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1a8a65aac69d19bcb88d23adc5bcf1d046cc053d32596b926f13ee1ea43156a')
  returning id
), o as (
