  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol violència exercida entre membres d''una mateixa família, sigui quin sigui el sexe de la víctima.', false), ('B', 'La violència que, amb l''objectiu de causar perjudici o dany a les dones, s''exerceix sobre els seus familiars o persones properes menors d''edat per part del cònjuge o la parella o exparella.', true), ('C', 'La violència exercida sobre les dones per qualsevol persona desconeguda.', false), ('D', 'Només la violència física exercida sobre els fills comuns.', false)) as v(label, body, ok)
)
