-- Lote pcat-e05-delictes-administracio-publica-cp-v1 (50 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e05-delictes-administracio-publica', 'Tema 5. Delictes contra l''Administració pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e05-delictes-administracio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24 del Codi penal, a efectes penals es considera funcionari públic:', 'L''art. 24.2 CP adopta un concepte ampli de funcionari públic: qui participa en l''exercici de funcions públiques per disposició immediata de la llei, per elecció o per nomenament d''autoritat competent. Tenir comandament o exercir jurisdicció pròpia és el concepte d''autoritat (art. 24.1).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24.2 CP', 'Se considerará funcionario público todo el que por disposición inmediata de la Ley o por elección o por nombramiento de autoridad competente participe en el ejercicio de funciones públicas.', null, '91a5fe681209580389abe9802cdc1a082e46448e4746a9826cf8960c9ededaf6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91a5fe681209580389abe9802cdc1a082e46448e4746a9826cf8960c9ededaf6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només qui hagi adquirit la condició de funcionari de carrera després de superar un procés selectiu.', false), ('B', 'Tothom qui per disposició immediata de la llei, per elecció o per nomenament d''autoritat competent participi en l''exercici de funcions públiques.', true), ('C', 'Qui per si sol o com a membre d''una corporació, tribunal o òrgan col·legiat tingui comandament o exerceixi jurisdicció pròpia.', false), ('D', 'Només el personal que presti serveis a l''Administració General de l''Estat o a les administracions de les comunitats autònomes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, comet el delicte de prevaricació l''autoritat o funcionari públic que:', 'L''art. 404 CP castiga l''autoritat o funcionari que, sabent-ne la injustícia, dicta una resolució arbitrària en un assumpte administratiu. La negativa oberta a complir ordres és desobediència (art. 410) i l''abandonament de destí per no perseguir delictes, l''art. 407.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 404 CP', 'A la autoridad o funcionario público que, a sabiendas de su injusticia, dictare una resolución arbitraria en un asunto administrativo', null, 'c6069c744e862210786f7696955ea4d67dd547c7bd26c114f4cb8dbd6f7df202', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c6069c744e862210786f7696955ea4d67dd547c7bd26c114f4cb8dbd6f7df202')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per negligència, dicta una resolució contrària a un informe preceptiu.', false), ('B', 'Es nega obertament a complir una ordre de l''autoritat superior dictada dins de la seva competència.', false), ('C', 'Abandona el seu destí amb el propòsit de no perseguir un delicte.', false), ('D', 'Sabent-ne la injustícia, dicta una resolució arbitrària en un assumpte administratiu.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina pena estableix el Codi penal per a l''autoritat o funcionari públic que comet el delicte de prevaricació de l''article 404?', 'La prevaricació administrativa de l''art. 404 CP es castiga només amb inhabilitació especial per a ocupació o càrrec públic i per al dret de sufragi passiu de 9 a 15 anys, sense pena de presó.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 404 CP', 'se le castigará con la pena de inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a quince años.', null, 'd63a364940a80c2687b78985589af4eac419699985891f63e97189b426de50b2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd63a364940a80c2687b78985589af4eac419699985891f63e97189b426de50b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inhabilitació especial per a ocupació o càrrec públic i per a l''exercici del dret de sufragi passiu de nou a quinze anys.', true), ('B', 'Presó de dos a quatre anys i inhabilitació especial de cinc a nou anys.', false), ('C', 'Multa de tres a dotze mesos i inhabilitació especial de sis mesos a dos anys.', false), ('D', 'Suspensió d''ocupació o càrrec públic d''un a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, l''autoritat o funcionari públic que, en l''exercici de la seva competència i sabent-ne la il·legalitat, nomena per a un càrrec públic una persona que no reuneix els requisits legalment establerts, és castigat amb:', 'L''art. 405 CP castiga els nomenaments il·legals amb multa de 3 a 8 mesos i suspensió d''1 a 3 anys. La mateixa pena de multa s''imposa a qui accepta el nomenament sabent que no té els requisits (art. 406).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 405 CP', 'A la autoridad o funcionario público que, en el ejercicio de su competencia y a sabiendas de su ilegalidad, propusiere, nombrare o diere posesión para el ejercicio de un determinado cargo público a cualquier persona sin que concurran los requisitos legalmente establecidos para ello, se le castigará con las penas de multa de tres a ocho meses y suspensión de empleo o cargo público por tiempo de uno a tres años.', null, '6c9790fd438155bb8ee59e4caaa31ede6568cb869378e77335496577c84a2624', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6c9790fd438155bb8ee59e4caaa31ede6568cb869378e77335496577c84a2624')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inhabilitació especial per a ocupació o càrrec públic de nou a quinze anys.', false), ('B', 'Presó de sis mesos a un any i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('C', 'Multa de tres a vuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', true), ('D', 'Multa de vuit a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, les autoritats o funcionaris públics que es neguen obertament a donar el compliment degut a resolucions judicials o a ordres de l''autoritat superior, dictades dins l''àmbit de la seva competència i revestides de les formalitats legals, incorren en la pena de:', 'L''art. 410.1 CP castiga la desobediència amb multa de 3 a 12 mesos i inhabilitació especial de 6 mesos a 2 anys. La multa de 12 a 24 mesos i la inhabilitació d''1 a 3 anys són les de l''art. 411.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 410.1 CP', 'Las autoridades o funcionarios públicos que se negaren abiertamente a dar el debido cumplimiento a resoluciones judiciales, decisiones u órdenes de la autoridad superior, dictadas dentro del ámbito de su respectiva competencia y revestidas de las formalidades legales, incurrirán en la pena de multa de tres a doce meses e inhabilitación especial para empleo o cargo público por tiempo de seis meses a dos años.', null, 'ff44d6985049d4248538215d9ecbbe04f64b99e1c71553307189e4110789bbf0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ff44d6985049d4248538215d9ecbbe04f64b99e1c71553307189e4110789bbf0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a vint-i-quatre mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('B', 'Presó d''un a quatre anys i inhabilitació absoluta de sis a deu anys.', false), ('C', 'Multa de tres a dotze mesos i inhabilitació especial per a ocupació o càrrec públic de sis mesos a dos anys.', true), ('D', 'Multa de tres a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, no incorren en responsabilitat criminal per desobediència les autoritats o funcionaris que no compleixen un manament que:', 'L''art. 410.2 CP exclou la responsabilitat criminal quan el manament constitueix una infracció manifesta, clara i terminant d''un precepte de llei o d''una altra disposició general.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 410.2 CP', 'No obstante lo dispuesto en el apartado anterior, no incurrirán en responsabilidad criminal las autoridades o funcionarios por no dar cumplimiento a un mandato que constituya una infracción manifiesta, clara y terminante de un precepto de Ley o de cualquier otra disposición general.', null, '2979f801d99bce5bbce4d8a41eb0fa17264c9c81af0c970360e3c6edfe418163', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2979f801d99bce5bbce4d8a41eb0fa17264c9c81af0c970360e3c6edfe418163')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Considerin inoportú o contrari als criteris de bona gestió del servei.', false), ('B', 'Constitueixi una infracció manifesta, clara i terminant d''un precepte de llei o de qualsevol altra disposició general.', true), ('C', 'No els hagi estat comunicat per escrit pel superior jeràrquic.', false), ('D', 'Hagin impugnat en via administrativa, mentre no es resolgui el recurs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionari suspèn l''execució d''una ordre del seu superior per un motiu diferent del de l''article 410.2 del Codi penal, el superior desaprova la suspensió i el funcionari continua desobeint. Segons el Codi penal, la pena és de:', 'L''art. 411 CP agreuja la pena quan el funcionari desobeeix després que els superiors hagin desaprovat la suspensió de l''ordre: multa de 12 a 24 mesos i inhabilitació especial d''1 a 3 anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 411 CP', 'La autoridad o funcionario público que, habiendo suspendido, por cualquier motivo que no sea el expresado en el apartado segundo del artículo anterior, la ejecución de las órdenes de sus superiores, las desobedeciere después de que aquéllos hubieren desaprobado la suspensión, incurrirá en las penas de multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años.', null, '6468f0417d8405478b0c9966d4ad69a580eb1ebbf67cc180393880edf3ec14e1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6468f0417d8405478b0c9966d4ad69a580eb1ebbf67cc180393880edf3ec14e1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de tres a dotze mesos i inhabilitació especial per a ocupació o càrrec públic de sis mesos a dos anys.', false), ('B', 'Multa de tres a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false), ('C', 'Presó d''un a dos anys i inhabilitació especial per a ocupació o càrrec públic de tres a sis anys.', false), ('D', 'Multa de dotze a vint-i-quatre mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, el funcionari públic que, requerit per l''autoritat competent, no presta l''auxili degut per a l''Administració de justícia o un altre servei públic incorre en la pena de:', 'L''art. 412.1 CP castiga la denegació d''auxili amb multa de 3 a 12 mesos i suspensió de 6 mesos a 2 anys. Si el requerit és autoritat, cap o responsable d''una força pública o agent de l''autoritat, la pena és de multa de 12 a 18 mesos i suspensió de 2 a 3 anys (art. 412.2).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 412.1 CP', 'El funcionario público que, requerido por autoridad competente, no prestare el auxilio debido para la Administración de Justicia u otro servicio público, incurrirá en las penas de multa de tres a doce meses, y suspensión de empleo o cargo público por tiempo de seis meses a dos años.', null, '613000846d3e8ca1852f6937f5bacd93ea2170f0d72cdf21e52c2c6083886b90', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '613000846d3e8ca1852f6937f5bacd93ea2170f0d72cdf21e52c2c6083886b90')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de tres a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', true), ('B', 'Multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic de dos a tres anys.', false), ('C', 'Multa de divuit a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false), ('D', 'Presó de sis mesos a un any i inhabilitació especial d''un a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona privada de llibertat demana auxili a un funcionari per evitar un delicte contra la vida d''un altre intern, i el funcionari, obligat a prestar-lo per raó del seu càrrec, s''absté de fer-ho. Segons el Codi penal, la pena aplicable és:', 'L''art. 412.3 CP gradua la pena segons el delicte que es vol evitar: contra la vida, multa de 18 a 24 mesos i inhabilitació especial de 3 a 6 anys; contra la integritat, la llibertat sexual, la salut o la llibertat, multa de 12 a 18 mesos i suspensió d''1 a 3 anys; altres delictes o mals, multa de 3 a 12 mesos i suspensió de 6 mesos a 2 anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 412.3 CP', 'La autoridad o funcionario público que, requerido por un particular a prestar algún auxilio a que venga obligado por razón de su cargo para evitar un delito contra la vida de las personas, se abstuviera de prestarlo, será castigado con la pena de multa de dieciocho a veinticuatro meses e inhabilitación especial para empleo o cargo público por tiempo de tres a seis años.', null, '1a385c9393fd6d1c2671de77dceb787e66bc828417798b54d3473b8265925c81', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a385c9393fd6d1c2671de77dceb787e66bc828417798b54d3473b8265925c81')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('B', 'Multa de divuit a vint-i-quatre mesos i inhabilitació especial per a ocupació o càrrec públic de tres a sis anys.', true), ('C', 'Multa de tres a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false), ('D', 'Presó d''un a quatre anys i inhabilitació absoluta de sis a dotze anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, quina de les conductes següents, feta conscientment per un funcionari sobre documents la custòdia dels quals té encomanada per raó del seu càrrec, NO és una de les que descriu l''article 413?', 'L''art. 413 CP tipifica la infidelitat en la custòdia de documents amb quatre verbs: sostreure, destruir, inutilitzar o ocultar, totalment o parcialment, documents la custòdia dels quals està encomanada al funcionari per raó del seu càrrec. Fer-ne una còpia no és cap d''aquestes conductes.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 413 CP', 'La autoridad o funcionario público que, a sabiendas, sustrajere, destruyere, inutilizare u ocultare, total o parcialmente, documentos cuya custodia le esté encomendada por razón de su cargo', null, '40c7d5a29e6dd7889d839686c04e4915ca4777ce82a7bda8d0fd8a33b97534b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '40c7d5a29e6dd7889d839686c04e4915ca4777ce82a7bda8d0fd8a33b97534b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fotocopiar-los per arxivar-ne una còpia al seu domicili.', true), ('B', 'Sostreure''ls.', false), ('C', 'Destruir-los o inutilitzar-los.', false), ('D', 'Ocultar-los, totalment o parcialment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, si l''autoritat o funcionari públic revela secrets d''un particular dels quals té coneixement per raó del seu ofici o càrrec, la pena és de:', 'L''art. 417.2 CP castiga la revelació de secrets d''un particular amb presó de 2 a 4 anys, multa de 12 a 18 mesos i suspensió d''1 a 3 anys. Les altres opcions corresponen a la revelació bàsica (art. 417.1, primer paràgraf), a la que causa dany greu (art. 417.1, segon paràgraf) i a l''accés indegut a documents secrets (art. 415).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 417.2 CP', 'Si se tratara de secretos de un particular, las penas serán las de prisión de dos a cuatro años, multa de doce a dieciocho meses, y suspensión de empleo o cargo público por tiempo de uno a tres años.', null, 'c822623b389e814018b4c2e072eb23b57704a1a1bec064da01108fda6cb5409a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c822623b389e814018b4c2e072eb23b57704a1a1bec064da01108fda6cb5409a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a divuit mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('B', 'Presó d''un a tres anys i inhabilitació especial per a ocupació o càrrec públic de tres a cinc anys.', false), ('C', 'Multa de sis a dotze mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('D', 'Presó de dos a quatre anys, multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''autoritat o funcionari públic que, en profit propi o d''un tercer, sol·licita una retribució per fer, en l''exercici del seu càrrec, un acte contrari als deures inherents a aquest càrrec, comet, segons el Codi penal, un suborn castigat amb:', 'L''art. 419 CP castiga el suborn per a un acte contrari als deures del càrrec amb presó de 3 a 6 anys, multa de 12 a 24 mesos i inhabilitació especial de 9 a 12 anys, sens perjudici de la pena per l''acte fet si és delicte. Per a un acte propi del càrrec, la pena és de 2 a 4 anys (art. 420).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 419 CP', 'incurrirá en la pena de prisión de tres a seis años, multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a doce años', null, '50f621f0b9a92892f390acb26934ed1bf537993697d3dc688542bf62cfc9db5f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50f621f0b9a92892f390acb26934ed1bf537993697d3dc688542bf62cfc9db5f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de dos a quatre anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial de cinc a nou anys.', false), ('B', 'Presó de sis mesos a un any i suspensió d''ocupació i càrrec públic d''un a tres anys.', false), ('C', 'Presó de tres a sis anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial per a ocupació o càrrec públic i per al dret de sufragi passiu de nou a dotze anys.', true), ('D', 'Presó d''un a quatre anys, multa de set a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, la pena de presó per a l''autoritat o funcionari públic que accepta una promesa de retribució per fer un acte propi del seu càrrec és de:', 'L''art. 420 CP castiga el suborn per a un acte propi del càrrec amb presó de 2 a 4 anys, multa de 12 a 24 mesos i inhabilitació especial de 5 a 9 anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 420 CP', 'La autoridad o funcionario público que, en provecho propio o de un tercero, recibiere o solicitare, por sí o por persona interpuesta, dádiva, favor o retribución de cualquier clase o aceptare ofrecimiento o promesa para realizar un acto propio de su cargo, incurrirá en la pena de prisión de dos a cuatro años', null, '75d683043322f7fe0d489499101ebae25bfdeed31874c3bb3752f1116c6cdad8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '75d683043322f7fe0d489499101ebae25bfdeed31874c3bb3752f1116c6cdad8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres a sis anys.', false), ('B', 'Sis mesos a un any.', false), ('C', 'Un a dos anys.', false), ('D', 'Dos a quatre anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa al suborn comès per particulars, quina de les afirmacions següents NO és correcta segons l''article 424 del Codi penal?', 'L''art. 424 CP castiga el particular que ofereix o lliura la dàdiva amb les mateixes penes de presó i multa que el funcionari (424.1), també quan la lliura atenent la seva sol·licitud (424.2), i hi afegeix inhabilitació de 5 a 10 anys si l''actuació té relació amb contractació, subvencions o subhastes (424.3). L''exempció només es dona en el cas de l''art. 426 (accés ocasional i denúncia en el termini de dos mesos).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 424 CP', 'será castigado en sus respectivos casos, con las mismas penas de prisión y multa que la autoridad, funcionario o persona corrompida. 2. Cuando un particular entregare la dádiva o retribución atendiendo la solicitud de la autoridad, funcionario público o persona que participe en el ejercicio de la función pública, se le impondrán las mismas penas de prisión y multa que a ellos les correspondan. 3. Si la actuación conseguida o pretendida de la autoridad o funcionario tuviere relación con un procedimiento de contratación, de subvenciones o de subastas convocados por las Administraciones o entes públicos, se impondrá al particular y, en su caso, a la sociedad, asociación u organización a que representare la pena de inhabilitación para obtener subvenciones y ayudas públicas, para contratar con entes, organismos o entidades que formen parte del sector público y para gozar de beneficios o incentivos fiscales y de la Seguridad Social por un tiempo de cinco a diez años.', null, '143350cb2694ed41ee0da86fd776e65580b0c72878ad869a4806a67fb37e897e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '143350cb2694ed41ee0da86fd776e65580b0c72878ad869a4806a67fb37e897e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El particular que lliura la dàdiva atenent la sol·licitud del funcionari queda sempre exempt de pena.', true), ('B', 'El particular que ofereix una dàdiva a un funcionari perquè faci un acte contrari als deures del càrrec és castigat amb les mateixes penes de presó i multa que el funcionari corromput.', false), ('C', 'El particular que lliura la dàdiva atenent la sol·licitud del funcionari és castigat amb les mateixes penes de presó i multa que corresponen al funcionari.', false), ('D', 'Si l''actuació pretesa té relació amb un procediment de contractació, de subvencions o de subhastes, al particular se li imposa, a més, la inhabilitació per obtenir subvencions i per contractar amb el sector públic de cinc a deu anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, queda exempt de pena pel delicte de suborn el particular que, havent accedit ocasionalment a la sol·licitud de dàdiva feta per un funcionari públic, denuncia el fet a l''autoritat que té el deure d''investigar-lo:', 'L''art. 426 CP preveu l''excusa absolutòria del particular que accedeix ocasionalment a la sol·licitud del funcionari i denuncia els fets abans de l''obertura del procediment, dins dels dos mesos següents als fets.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 426 CP', 'Quedará exento de pena por el delito de cohecho el particular que, habiendo accedido ocasionalmente a la solicitud de dádiva u otra retribución realizada por autoridad o funcionario público, denunciare el hecho a la autoridad que tenga el deber de proceder a su averiguación antes de la apertura del procedimiento, siempre que no haya transcurrido más de dos meses desde la fecha de los hechos.', null, '311bc0fcc1ee4bfddf057acbee18e0ed8d5b6583efd463d478b46edd04b5b735', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '311bc0fcc1ee4bfddf057acbee18e0ed8d5b6583efd463d478b46edd04b5b735')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Abans de l''obertura del judici oral, sempre que no hagin transcorregut més de sis mesos des de la data dels fets.', false), ('B', 'En qualsevol moment del procediment, si retorna la dàdiva lliurada.', false), ('C', 'Abans de l''obertura del procediment, sempre que no hagin transcorregut més de dos mesos des de la data dels fets.', true), ('D', 'Abans de l''obertura del procediment, sempre que no hagi transcorregut més d''un any des de la data dels fets.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, quan el suborn s''efectua en una causa criminal a favor del reu per part del seu cònjuge, d''un ascendent, d''un descendent o d''un germà, al subornador se li imposa la pena de:', 'L''art. 425 CP atenua la pena del subornador quan el suborn es fa en causa criminal a favor del reu pel seu cònjuge o persona lligada per relació d''afectivitat anàloga, o per ascendents, descendents o germans, per naturalesa, adopció o afinitat: presó de 6 mesos a 1 any.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 425 CP', 'Cuando el soborno mediare en causa criminal a favor del reo por parte de su cónyuge u otra persona a la que se halle ligado de forma estable por análoga relación de afectividad, o de algún ascendiente, descendiente o hermano por naturaleza, por adopción o afines en los mismos grados, se impondrá al sobornador la pena de prisión de seis meses a un año.', null, '5d51f70f3e678bb977bce8b8fb60512eeee9050c222af1430e6d68b1577f989f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5d51f70f3e678bb977bce8b8fb60512eeee9050c222af1430e6d68b1577f989f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les mateixes penes de presó i multa que al funcionari corromput.', false), ('B', 'Presó de sis mesos a un any.', true), ('C', 'Multa de tres a sis mesos.', false), ('D', 'Cap pena, perquè queda exempt de responsabilitat criminal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, l''autoritat o funcionari públic que, amb ànim de lucre, s''apropia del patrimoni públic que té al seu càrrec per raó de les seves funcions comet un delicte de malversació castigat, en el tipus bàsic, amb:', 'L''art. 432.1 CP castiga la malversació per apropiació amb presó de 2 a 6 anys i inhabilitació especial de 6 a 10 anys. Les penes de 4 a 8 anys corresponen als supòsits agreujats (art. 432.2) i les d''1 a 2 anys, als casos de perjudici inferior a 4.000 euros (art. 432.3).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 432.1 CP', 'La autoridad o funcionario público que, con ánimo de lucro, se apropiare o consintiere que un tercero, con igual ánimo, se apropie del patrimonio público que tenga a su cargo por razón de sus funciones o con ocasión de las mismas, será castigado con una pena de prisión de dos a seis años, inhabilitación especial para cargo o empleo público y para el ejercicio del derecho de sufragio pasivo por tiempo de seis a diez años.', null, 'cb7527d64ee40e9d777bd3d49529fdf3a8e2640d8bd330bc9c060bb96c1ab3a2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cb7527d64ee40e9d777bd3d49529fdf3a8e2640d8bd330bc9c060bb96c1ab3a2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de dos a sis anys i inhabilitació especial per a càrrec o ocupació pública i per al dret de sufragi passiu de sis a deu anys.', true), ('B', 'Presó de quatre a vuit anys i inhabilitació absoluta de deu a vint anys.', false), ('C', 'Presó d''un a dos anys i multa de tres mesos i un dia a dotze mesos.', false), ('D', 'Presó d''un a quatre anys i inhabilitació especial de dos a sis anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En els delictes de malversació, si el culpable ha reparat de manera efectiva i íntegra el perjudici causat al patrimoni públic abans de l''inici del judici oral, el Codi penal preveu que:', 'L''art. 434 CP obliga a imposar la pena inferior en un o dos graus si el culpable repara efectivament i íntegrament el perjudici abans del judici oral, o si col·labora activament i eficaçment amb les autoritats per obtenir proves decisives.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 434 CP', 'Si el culpable de cualquiera de los hechos tipificados en este capítulo hubiere reparado de modo efectivo e íntegro el perjuicio causado al patrimonio público antes del inicio del juicio oral […] los jueces y tribunales impondrán al responsable de este delito la pena inferior en uno o dos grados.', null, 'c7fcc16ce10ad9e5840c489193e54e42a52931409bf60fe6de90e1f21524282a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c7fcc16ce10ad9e5840c489193e54e42a52931409bf60fe6de90e1f21524282a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quedi exempt de pena.', false), ('B', 'Els jutges i tribunals li imposin la pena inferior en un o dos graus.', true), ('C', 'Se li imposi la pena en la meitat inferior.', false), ('D', 'Només se li imposi la pena de multa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, el funcionari d''institucions penitenciàries que sol·licita sexualment una persona subjecta a la seva guarda és castigat amb:', 'L''art. 443.2 CP castiga el funcionari d''institucions penitenciàries, centres de protecció o reforma de menors, CIE o qualsevol centre de detenció o custòdia que sol·licita sexualment una persona sota la seva guarda amb presó d''1 a 4 anys i inhabilitació absoluta de 6 a 12 anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 443.2 CP', 'El funcionario de Instituciones Penitenciarias, de centros de protección o reforma de menores, centro de internamiento de personas extranjeras, o cualquier otro centro de detención, o custodia, incluso de estancia temporal, que solicitara sexualmente a una persona sujeta a su guarda, será castigado con la pena de prisión de uno a cuatro años e inhabilitación absoluta por tiempo de seis a doce años.', null, '1b38811f6d4643df2947b94c3351f1dff15283322670981b0b24c298f640bb96', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1b38811f6d4643df2947b94c3351f1dff15283322670981b0b24c298f640bb96')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a dos anys i inhabilitació absoluta de sis a dotze anys.', false), ('B', 'Presó de sis mesos a un any i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('C', 'Multa de dotze a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false), ('D', 'Presó d''un a quatre anys i inhabilitació absoluta de sis a dotze anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 443 del Codi penal, quina de les afirmacions següents sobre la sol·licitació sexual comesa per un funcionari de presons NO és correcta?', 'L''art. 443.3 CP estén les mateixes penes a la sol·licitació de l''ascendent, descendent, germà o afí de la persona sota guarda, i del seu cònjuge o persona lligada per relació d''afectivitat anàloga. L''art. 444 afegeix que les penes s''imposen sens perjudici de les dels delictes contra la llibertat sexual efectivament comesos.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 443.3 CP', 'En las mismas penas incurrirán cuando la persona solicitada fuera ascendiente, descendiente, hermano, por naturaleza, por adopción, o afines en los mismos grados de persona que tuviere bajo su guarda. Incurrirá, asimismo, en estas penas cuando la persona solicitada sea cónyuge de persona que tenga bajo su guarda o se halle ligada a ésta de forma estable por análoga relación de afectividad.', null, '9a4695f7aeb30d2bd9900734fc67fce967b34e4cc8afc4db7a7e4c38c09678b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a4695f7aeb30d2bd9900734fc67fce967b34e4cc8afc4db7a7e4c38c09678b0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'També es castiga quan la persona sol·licitada és ascendent, descendent o germana de la interna que té sota la seva guarda.', false), ('B', 'També es castiga quan la persona sol·licitada és el cònjuge de l''intern que té sota la seva guarda.', false), ('C', 'Només és punible si la persona sol·licitada és la mateixa interna que té sota la seva guarda.', true), ('D', 'Les penes s''imposen sens perjudici de les que corresponguin pels delictes contra la llibertat sexual efectivament comesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.1 del Codi penal, a efectes penals es considera autoritat:', 'L''autoritat es defineix pel comandament o la jurisdicció pròpia (art. 24.1 CP). La participació en l''exercici de funcions públiques per llei, elecció o nomenament defineix el funcionari públic (art. 24.2).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24.1 CP', '1. A los efectos penales se reputará autoridad al que por sí solo o como miembro de alguna corporación, tribunal u órgano colegiado tenga mando o ejerza jurisdicción propia.', null, 'd4582a8161c82dadb42b0803a7c68f650b0b78ab66e5793f7ad571be37963ece', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd4582a8161c82dadb42b0803a7c68f650b0b78ab66e5793f7ad571be37963ece')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tothom qui participa en l''exercici de funcions públiques per disposició immediata de la llei.', false), ('B', 'Qualsevol funcionari de carrera del grup A.', false), ('C', 'Qui, per si sol o com a membre d''una corporació, un tribunal o un òrgan col·legiat, té comandament o exerceix jurisdicció pròpia.', true), ('D', 'Qui ha estat nomenat per una autoritat competent per exercir funcions públiques.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
