  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 406 del Codi penal, la persona que accepta la proposta, el nomenament o la presa de possessió per a un càrrec públic sabent que no reuneix els requisits legalment exigibles:', 'L''article 406 CP castiga qui accepta el nomenament il·legal amb la mateixa multa prevista a l''article 405 per a l''autoritat o funcionari que el fa (multa de tres a vuit mesos).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 406 CP', 'La misma pena de multa se impondrá a la persona que acepte la propuesta, nombramiento o toma de posesión mencionada en el artículo anterior, sabiendo que carece de los requisitos legalmente exigibles.', null, '411361ec299e14edceb953e21866b844a3681474dc0bfde41cc577982442edba', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '411361ec299e14edceb953e21866b844a3681474dc0bfde41cc577982442edba')
  returning id
