with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 422 del Codi penal, l''autoritat o funcionari públic que, en profit propi o d''un tercer, admet una dàdiva o un regal que se li ofereix en consideració al seu càrrec o funció incorre en la pena de:', 'El suborn impropi de l''article 422 CP (dàdiva oferta en consideració al càrrec, sense contrapartida concreta) es castiga amb presó de sis mesos a un any i suspensió d''un a tres anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 422 CP', 'incurrirá en la pena de prisión de seis meses a un año y suspensión de empleo y cargo público de uno a tres años.', null, '13e4eb28a7f014a09616babc9eda2a29e6e61c53a66ece9abbe33547191728dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '13e4eb28a7f014a09616babc9eda2a29e6e61c53a66ece9abbe33547191728dd')
  returning id
