with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 432 bis del Codi penal, l''autoritat o funcionari públic que, sense ànim d''apropiar-se''l, destina a usos privats el patrimoni públic que té al seu càrrec per raó de les seves funcions incorre en la pena de:', 'La malversació d''ús (art. 432 bis CP) es castiga amb presó de sis mesos a tres anys i suspensió d''un a quatre anys; si no es reintegra el patrimoni en deu dies des de la incoació del procés, s''apliquen les penes de l''article 432.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 432 bis CP', 'La autoridad o funcionario público que, sin ánimo de apropiárselo, destinare a usos privados el patrimonio público puesto a su cargo por razón de sus funciones o con ocasión de las mismas, incurrirá en la pena de prisión de seis meses a tres años, y suspensión de empleo o cargo público de uno a cuatro años.', null, '2d2ee55d555a4f230d91f75c10f588353870d3665d9f9b61c56282b5404cda99', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2d2ee55d555a4f230d91f75c10f588353870d3665d9f9b61c56282b5404cda99')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de dos a sis anys i inhabilitació especial de sis a deu anys.', false), ('B', 'Presó de quatre a vuit anys i inhabilitació absoluta de deu a vint anys.', false), ('C', 'Presó de sis mesos a tres anys i suspensió d''ocupació o càrrec públic d''un a quatre anys.', true), ('D', 'Multa de tres a dotze mesos i inhabilitació especial d''un a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 413 del Codi penal, l''autoritat o funcionari públic que, a sabent, sostreu, destrueix, inutilitza o oculta documents la custòdia dels quals té encomanada per raó del seu càrrec incorre en la pena de:', 'La infidelitat en la custòdia de documents de l''article 413 CP és la modalitat més greu del capítol IV. Les penes menors corresponen a la destrucció dels mitjans que restringeixen l''accés (art. 414) i a l''accés no autoritzat a documents secrets (art. 415).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 413 CP', 'incurrirá en las penas de prisión de uno a cuatro años, multa de siete a veinticuatro meses, e inhabilitación especial para empleo o cargo público por tiempo de tres a seis años.', null, '099097e099a33323661a6408dcd82942acc8c0eff1a8f6afba87bc0db1302eef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '099097e099a33323661a6408dcd82942acc8c0eff1a8f6afba87bc0db1302eef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
