)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 436 del Codi penal, l''autoritat o funcionari públic que, intervenint per raó del seu càrrec en un procediment de contractació pública, es concerta amb els interessats per defraudar un ens públic incorre en la pena de presó de:', 'El frau a l''Administració (art. 436 CP) es castiga amb presó de dos a sis anys i inhabilitació especial de sis a deu anys. El particular que s''hi concerta rep la mateixa pena de presó.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 436 CP', 'se concertara con los interesados o usase de cualquier otro artificio para defraudar a cualquier ente público, incurrirá en las penas de prisión de dos a seis años e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de seis a diez años.', null, '3c8fedd48c5b25f074d94f3acd6447a606be377c85a9b33ba27f42379c6fcf33', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3c8fedd48c5b25f074d94f3acd6447a606be377c85a9b33ba27f42379c6fcf33')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos a dos anys, a més d''una multa de dotze a vint-i-quatre mesos.', false), ('B', 'Dos a sis anys, a més de la inhabilitació especial per a ocupació o càrrec públic i per al dret de sufragi passiu de sis a deu anys.', true), ('C', 'Un a quatre anys, a més de la suspensió d''ocupació o càrrec públic.', false), ('D', 'Quatre a vuit anys, a més de la inhabilitació absoluta de deu a vint anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa als delictes del títol XIX del llibre II del Codi penal (contra l''Administració pública), quina de les afirmacions següents NO és correcta segons l''article 445?', 'L''article 445 CP declara punibles la provocació, la conspiració i la proposició per cometre qualsevol delicte del títol XIX, amb la pena inferior en un o dos graus.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 445 CP', 'La provocación, la conspiración y la proposición para cometer los delitos previstos en este Título se castigará, respectivamente, con la pena inferior en uno o dos grados.', null, '4e5a07698741d6a2ad136bb52aaa137d873c70c13aaf9f2c2171ac2b24312b6c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e5a07698741d6a2ad136bb52aaa137d873c70c13aaf9f2c2171ac2b24312b6c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La provocació per cometre''ls es castiga amb la pena inferior en un o dos graus.', false), ('B', 'La conspiració per cometre''ls es castiga amb la pena inferior en un o dos graus.', false), ('C', 'La conspiració per cometre''ls no és punible.', true), ('D', 'La proposició per cometre''ls es castiga amb la pena inferior en un o dos graus.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.1 del Codi penal, quines de les persones següents NO tenen en tot cas la consideració d''autoritat per mandat exprés del precepte?', 'L''article 24.1 CP atribueix en tot cas la condició d''autoritat als parlamentaris (Congrés, Senat, assemblees autonòmiques i Parlament Europeu) i als fiscals. Els funcionaris de presons són funcionaris públics (art. 24.2), però no figuren en aquesta llista.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 24.1 CP', 'En todo caso, tendrán la consideración de autoridad los miembros del Congreso de los Diputados, del Senado, de las Asambleas Legislativas de las Comunidades Autónomas y del Parlamento Europeo. Tendrán también la consideración de autoridad los funcionarios del Ministerio Fiscal y los Fiscales de la Fiscalía Europea.', null, '482109e37c2cce85f8f085fb2c3e7d63aa3ce1b13add9d47f2ce70d333805d6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '482109e37c2cce85f8f085fb2c3e7d63aa3ce1b13add9d47f2ce70d333805d6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els funcionaris d''institucions penitenciàries.', true), ('B', 'Els membres del Congrés dels Diputats i del Senat.', false), ('C', 'Els membres de les assemblees legislatives de les comunitats autònomes i del Parlament Europeu.', false), ('D', 'Els funcionaris del Ministeri Fiscal i els fiscals de la Fiscalia Europea.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 412.2 del Codi penal, si qui, requerit per l''autoritat competent, no presta l''auxili degut per a l''Administració de justícia o un altre servei públic és una autoritat, un cap o responsable d''una força pública o un agent de l''autoritat, la pena és de:', 'La denegació d''auxili es castiga amb multa de tres a dotze mesos i suspensió de sis mesos a dos anys si l''autor és funcionari (art. 412.1 CP), i amb multa de dotze a divuit mesos i suspensió de dos a tres anys si és autoritat, cap d''una força pública o agent (art. 412.2).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 412.2 CP', '2. Si el requerido fuera autoridad, jefe o responsable de una fuerza pública o un agente de la autoridad, se impondrán las penas de multa de doce a dieciocho meses y suspensión de empleo o cargo público por tiempo de dos a tres años.', null, '0c8e0799bb6d2c2d3a460da5325219146ddc7680fd5e461e0811595787b95808', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0c8e0799bb6d2c2d3a460da5325219146ddc7680fd5e461e0811595787b95808')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de tres a dotze mesos i suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false), ('B', 'Multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic de dos a tres anys.', true), ('C', 'Multa de divuit a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false), ('D', 'Presó d''un a tres anys i inhabilitació absoluta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 414.1 del Codi penal, l''autoritat o funcionari que té encomanada la custòdia de documents d''accés restringit i que, a sabent, destrueix o inutilitza els mitjans posats per impedir aquest accés incorre en la pena de:', 'L''article 414.1 CP castiga el funcionari amb presó de sis mesos a un any o multa i inhabilitació especial. El particular que fa la mateixa conducta és castigat amb multa de sis a divuit mesos (art. 414.2).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 414.1 CP', 'incurrirá en la pena de prisión de seis meses a un año o multa de seis a veinticuatro meses y, en cualquier caso, inhabilitación especial para empleo o cargo público por tiempo de uno a tres años.', null, '9522b1321aece8f7842e5836cc2c5335589ff2d28a1731b9a3488b6432bc6459', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9522b1321aece8f7842e5836cc2c5335589ff2d28a1731b9a3488b6432bc6459')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a quatre anys, multa de set a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false), ('B', 'Multa de sis a divuit mesos, sense cap pena privativa de drets.', false), ('C', 'Presó de dos a quatre anys i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('D', 'Presó de sis mesos a un any o multa de sis a vint-i-quatre mesos i, en qualsevol cas, inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 415 del Codi penal, l''autoritat o funcionari públic que, a sabent i sense la deguda autorització, accedeix o permet accedir a documents secrets la custòdia dels quals li està confiada per raó del seu càrrec incorre en la pena de:', 'L''accés no autoritzat a documents secrets custodiats es castiga amb multa de sis a dotze mesos i inhabilitació especial d''un a tres anys (art. 415 CP).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 415 CP', 'accediere o permitiere acceder a documentos secretos cuya custodia le esté confiada por razón de su cargo, incurrirá en la pena de multa de seis a doce meses, e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años.', null, '6c377e0fe82ead3255a955552a5360cb30ce4d50eceb07e6975a97cddbb76584', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6c377e0fe82ead3255a955552a5360cb30ce4d50eceb07e6975a97cddbb76584')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a quatre anys i inhabilitació especial de tres a sis anys.', false), ('B', 'Multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('C', 'Multa de sis a dotze mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', true), ('D', 'Presó de sis mesos a un any i inhabilitació absoluta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 421 del Codi penal, les penes del suborn dels articles 419 i 420 també s''imposen quan l''autoritat o funcionari rep o sol·licita la dàdiva, el favor o la retribució:', 'L''article 421 CP equipara el suborn subsegüent (la dàdiva rebuda com a recompensa per l''acte ja fet) al suborn antecedent.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 421 CP', 'Las penas señaladas en los artículos precedentes se impondrán también cuando la dádiva, favor o retribución se recibiere o solicitare por la autoridad o funcionario público, en sus respectivos casos, como recompensa por la conducta descrita en dichos artículos.', null, '3ddcfa30ec9a9dd9725ee9b3e5df04571c455baef1ff4db0412670f3bcd4cf08', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3ddcfa30ec9a9dd9725ee9b3e5df04571c455baef1ff4db0412670f3bcd4cf08')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com a recompensa per la conducta que descriuen aquests articles.', true), ('B', 'Només si l''acte ja s''ha executat abans de l''oferiment.', false), ('C', 'Només si la retribució supera els 4.000 euros.', false), ('D', 'Per mitjà d''una persona interposada, però no directament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 423 del Codi penal, les disposicions sobre el suborn dels articles precedents s''apliquen igualment:', 'L''article 423 CP estén el suborn a jurats, àrbitres, mediadors, pèrits, administradors o interventors judicials, administradors concursals i a qualsevol persona que participi en l''exercici de la funció pública.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 423 CP', 'Lo dispuesto en los artículos precedentes será igualmente aplicable a los jurados y árbitros, nacionales o internacionales, así como a mediadores, peritos, administradores o interventores designados judicialmente, administradores concursales o a cualesquiera personas que participen en el ejercicio de la función pública.', null, '84755697c58e78a995f914336e605f25a50400c67d833992762e093737a7eb66', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '84755697c58e78a995f914336e605f25a50400c67d833992762e093737a7eb66')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només a les autoritats i funcionaris de carrera de les administracions públiques espanyoles.', false), ('B', 'Només als funcionaris de la Unió Europea.', false), ('C', 'Als treballadors de qualsevol empresa privada que contracti amb l''Administració.', false), ('D', 'Als jurats i àrbitres, nacionals o internacionals, als mediadors, pèrits, administradors o interventors designats judicialment, als administradors concursals i a qualsevol persona que participi en l''exercici de la funció pública.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 428 del Codi penal, el funcionari públic o autoritat que influeix en un altre funcionari o autoritat, prevalent-se de l''exercici de les facultats del seu càrrec, per aconseguir una resolució que li pugui generar un benefici econòmic per a si o per a un tercer, incorre en la pena de:', 'El tràfic d''influències comès per funcionari es castiga amb presó de sis mesos a dos anys, multa del tant al doble i inhabilitació especial de cinc a nou anys; si obté el benefici perseguit, les penes s''imposen en la meitat superior.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 428 CP', 'incurrirá en las penas de prisión de seis meses a dos años, multa del tanto al duplo del beneficio perseguido u obtenido e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de cinco a nueve años.', null, '755fe504b244b110c71f030f868030fbd3676e8835ac8c2b7c8456fde67ce7a9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '755fe504b244b110c71f030f868030fbd3676e8835ac8c2b7c8456fde67ce7a9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de dos a sis anys i inhabilitació especial de sis a deu anys.', false), ('B', 'Presó de sis mesos a dos anys, multa del tant al doble del benefici perseguit o obtingut i inhabilitació especial de cinc a nou anys.', true), ('C', 'Presó de sis mesos a un any, sense multa.', false), ('D', 'Presó de tres a sis anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial de nou a dotze anys.', false)) as v(label, body, ok)
)
