with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO dona lloc a la malversació agreujada de l''article 432.2 del Codi penal?', 'La malversació agreujada (presó de quatre a vuit anys i inhabilitació absoluta de deu a vint anys) exigeix dany o entorpiment greus al servei públic, un valor superior a 50.000 euros o béns de valor artístic, històric, cultural o científic o destinats a pal·liar una calamitat pública.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 432.2 CP', 'a) se hubiera causado un daño o entorpecimiento graves al servicio público, b) el valor del perjuicio causado o del patrimonio público apropiado excediere de 50.000 euros, c) las cosas malversadas fueran de valor artístico, histórico, cultural o científico', null, '403fcfc6bfc8003aeaa1dad7a3ad0901b678a91b3e4b8e372934a1b84eed2472', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '403fcfc6bfc8003aeaa1dad7a3ad0901b678a91b3e4b8e372934a1b84eed2472')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que s''hagi causat un dany o entorpiment greus al servei públic.', false), ('B', 'Que el valor del perjudici causat o del patrimoni públic apropiat excedeixi de 50.000 euros.', false), ('C', 'Que les coses malversades siguin de valor artístic, històric, cultural o científic.', false), ('D', 'Que l''autoritat o funcionari sigui reincident.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 439 del Codi penal, l''autoritat o funcionari públic que, havent d''intervenir per raó del seu càrrec en un contracte, assumpte, operació o activitat, s''aprofita d''aquesta circumstància per forçar o facilitar-se qualsevol forma de participació en aquests negocis incorre en la pena de:', 'Les negociacions prohibides als funcionaris (art. 439 CP) es castiguen amb presó de sis mesos a dos anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial de dos a set anys. La multa de sis a dotze mesos i la suspensió de dos a cinc anys són les de l''activitat professional privada incompatible (art. 441).', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 439 CP', 'incurrirá en la pena de prisión de seis meses a dos años, multa de doce a veinticuatro meses e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de dos a siete años.', null, '7f52b4e43285521c0d68363e40e90824427275a9933b99eba273f279e9c3b330', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f52b4e43285521c0d68363e40e90824427275a9933b99eba273f279e9c3b330')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a dos anys, multa de dotze a vint-i-quatre mesos i inhabilitació especial de dos a set anys.', true), ('B', 'Multa de sis a dotze mesos i suspensió d''ocupació o càrrec públic de dos a cinc anys.', false), ('C', 'Presó de dos a sis anys i inhabilitació especial de sis a deu anys.', false), ('D', 'Presó d''un a tres anys i inhabilitació absoluta de sis a dotze anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 407.1 del Codi penal, l''autoritat o funcionari públic que abandona la seva destinació amb el propòsit de no impedir o no perseguir un delicte dels títols XXI, XXII, XXIII o XXIV és castigat amb:', 'Si l''abandonament de destinació pretén no impedir o no perseguir delictes contra la Constitució, l''ordre públic, de traïció o contra la comunitat internacional, la pena és de presó d''un a quatre anys i inhabilitació absoluta; per a qualsevol altre delicte, inhabilitació especial d''un a tres anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 407.1 CP', 'se le castigará con la pena de prisión de uno a cuatro años e inhabilitación absoluta para empleo o cargo público por tiempo de seis a diez años.', null, 'acc62c8f31b21fb4f46f7dbf71bd38a7b541bc3feaa7bb4c304f58043627e137', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'acc62c8f31b21fb4f46f7dbf71bd38a7b541bc3feaa7bb4c304f58043627e137')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inhabilitació especial d''un a tres anys, sense pena de presó.', false), ('B', 'Presó de sis mesos a dos anys i suspensió d''ocupació o càrrec públic.', false), ('C', 'Presó d''un a quatre anys i inhabilitació absoluta de sis a deu anys.', true), ('D', 'Multa de vuit a dotze mesos i suspensió de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 409 del Codi penal, les autoritats o funcionaris públics que promouen, dirigeixen o organitzen l''abandonament col·lectiu i manifestament il·legal d''un servei públic són castigats amb:', 'Els promotors, directors o organitzadors de l''abandonament col·lectiu il·legal d''un servei públic reben multa de vuit a dotze mesos i suspensió; els qui només hi prenen part en un servei públic essencial i amb greu perjudici, només la multa de vuit a dotze mesos.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 409 CP', 'A las autoridades o funcionarios públicos que promovieren, dirigieren u organizaren el abandono colectivo y manifiestamente ilegal de un servicio público, se les castigará con la pena de multa de ocho a doce meses y suspensión de empleo o cargo público por tiempo de seis meses a dos años.', null, '20ae8ef8c3b973c8371cd29535c1fecc4f44575729c39b5fdbf9286521f718fb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '20ae8ef8c3b973c8371cd29535c1fecc4f44575729c39b5fdbf9286521f718fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
