insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels següents NO és un dels capítols del títol XIX del llibre II del Codi penal, «Delictes contra l''Administració pública»?', 'Les falsedats formen un títol propi, el XVIII. El títol XIX comprèn la prevaricació, l''abandonament de destinació, la desobediència i denegació d''auxili, la infidelitat en la custòdia de documents i la violació de secrets, el suborn, el tràfic d''influències, la malversació, els fraus i exaccions il·legals i les negociacions i activitats prohibides.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Títol XIX, llibre II CP', 'CAPÍTULO IV. De la infidelidad en la custodia de documentos y de la violación de secretos […] CAPÍTULO V. Del cohecho […] CAPÍTULO VI. Del tráfico de influencias', null, '80c6d54cb8d1e4b4670c502630850ac882dc889db6e537986305ef41da5ab4a5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '80c6d54cb8d1e4b4670c502630850ac882dc889db6e537986305ef41da5ab4a5')
  returning id
), o as (
