)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 416 del Codi penal, els particulars encarregats accidentalment del despatx o la custòdia de documents per comissió del Govern o de les autoritats o funcionaris que incorren en les conductes dels articles 413 a 415 són castigats amb:', 'L''article 416 CP castiga els particulars encarregats accidentalment de documents públics amb les penes de presó o multa immediatament inferiors a les dels funcionaris.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 416 CP', 'Serán castigados con las penas de prisión o multa inmediatamente inferiores a las respectivamente señaladas en los tres artículos anteriores los particulares encargados accidentalmente del despacho o custodia de documentos', null, '0c3cebe849860961a28884c0b2a88b4190ae4ca4827917db7d7aa4f57eb0e507', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0c3cebe849860961a28884c0b2a88b4190ae4ca4827917db7d7aa4f57eb0e507')
  returning id
), o as (
