)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 418 del Codi penal, el particular que aprofita per a si o per a un tercer el secret o la informació privilegiada que ha obtingut d''un funcionari públic o autoritat, quan no en resulta un dany greu, és castigat amb:', 'El particular que aprofita el secret rep multa proporcional i la pèrdua de subvencions i beneficis d''un a tres anys; si en resulta un dany greu per a la causa pública o per a tercers, presó d''un a sis anys i pèrdua de sis a deu anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 418 CP', 'El particular que aprovechare para sí o para un tercero el secreto o la información privilegiada que obtuviere de un funcionario público o autoridad, será castigado con multa del tanto al triplo del beneficio obtenido o facilitado y la pérdida de la posibilidad de obtener subvenciones o ayudas públicas y del derecho a gozar de los beneficios o incentivos fiscales o de la Seguridad Social durante el período de uno a tres años.', null, '4c01d7f40fc44c0405fcd1e15d09e9f6d457844a74f9509f69b2b766ad9e410e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c01d7f40fc44c0405fcd1e15d09e9f6d457844a74f9509f69b2b766ad9e410e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a sis anys.', false), ('B', 'Multa de dotze a divuit mesos i inhabilitació especial d''un a tres anys.', false), ('C', 'Presó de dos a quatre anys i multa de dotze a divuit mesos.', false), ('D', 'Multa del tant al triple del benefici obtingut o facilitat i pèrdua de la possibilitat d''obtenir subvencions o ajudes públiques i dels beneficis fiscals o de la Seguretat Social d''un a tres anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 427 del Codi penal, les disposicions sobre el suborn també s''apliquen quan les conductes les fan o afecten:', 'L''article 427 CP estén el suborn als càrrecs i funcionaris de països de la UE i d''altres països estrangers, als funcionaris o agents de la UE i d''organitzacions internacionals públiques i a qui gestiona interessos financers de la UE.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 427 CP', 'c) Cualquier funcionario o agente de la Unión Europea o de una organización internacional pública.', null, '9a1bd6cd68ff03c36a85daba01d45af2168b0f4ae84a72df336598a6f345182c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a1bd6cd68ff03c36a85daba01d45af2168b0f4ae84a72df336598a6f345182c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només les autoritats i funcionaris de l''Estat espanyol.', false), ('B', 'Els directius d''empreses privades estrangeres sense cap funció pública.', false), ('C', 'Qualsevol funcionari o agent de la Unió Europea o d''una organització internacional pública.', true), ('D', 'Només els funcionaris dels estats membres de la Unió Europea, però no els d''altres països.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 430 del Codi penal, els qui, oferint-se a fer les conductes de tràfic d''influències dels articles 428 i 429, sol·liciten de tercers dàdives, presents o qualsevol altra remuneració, o n''accepten l''oferiment o la promesa, són castigats amb la pena de:', 'L''oferiment de tràfic d''influències es castiga amb presó de sis mesos a un any; si l''autor és autoritat o funcionari, a més amb inhabilitació especial d''un a quatre anys.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 430 CP', 'Los que, ofreciéndose a realizar las conductas descritas en los dos artículos anteriores, solicitaren de terceros dádivas, presentes o cualquier otra remuneración, o aceptaren ofrecimiento o promesa, serán castigados con la pena de prisión de seis meses a un año.', null, 'a53616442987271352daef166060cf1831b2c71275fecb92a3b11073a7c26cc1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a53616442987271352daef166060cf1831b2c71275fecb92a3b11073a7c26cc1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a un any.', true), ('B', 'Presó de sis mesos a dos anys i multa del tant al doble.', false), ('C', 'Multa de tres a sis mesos.', false), ('D', 'Presó d''un a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 432.3 del Codi penal, la malversació es castiga amb presó d''un a dos anys, multa de tres mesos i un dia a dotze mesos i inhabilitació especial d''un a cinc anys quan el perjudici causat o el valor del patrimoni públic és inferior a:', 'La malversació de menor quantia (menys de 4.000 euros) té una pena atenuada. Per sobre de 50.000 euros, la malversació és agreujada (art. 432.2), i per sobre de 250.000 euros la presó s''imposa en la meitat superior.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 432.3 CP', '3. Los hechos a que se refiere el presente artículo serán castigados con una pena de prisión de uno a dos años y multa de tres meses y un día a doce meses, y en todo caso inhabilitación especial para cargo o empleo público y derecho de sufragio pasivo por tiempo de uno a cinco años, cuando el perjuicio causado o el valor del patrimonio público sea inferior a 4.000 euros.', null, '4abe3841537f94f2d572493553e8a9ea83ce27ee2160ab67b05db4c06b0372e4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4abe3841537f94f2d572493553e8a9ea83ce27ee2160ab67b05db4c06b0372e4')
  returning id
