  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '400 euros.', false), ('B', '4.000 euros.', true), ('C', '50.000 euros.', false), ('D', '1.000 euros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 432 bis del Codi penal, si el funcionari que ha destinat a usos privats el patrimoni públic no reintegra els mateixos elements distrets dins dels deu dies següents al de la incoació del procés:', 'La malversació d''ús es converteix, a efectes penològics, en malversació per apropiació si no es reintegren els béns en deu dies des de la incoació del procés.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 432 bis CP', 'Si el culpable no reintegrara los mismos elementos del patrimonio público distraídos dentro de los diez días siguientes al de la incoación del proceso, se le impondrán las penas del artículo anterior.', null, '7ce222303c71e2ee11d44603034bbde38ed3e8e0b878367202073326df9b3d95', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7ce222303c71e2ee11d44603034bbde38ed3e8e0b878367202073326df9b3d95')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena s''imposa en la meitat superior.', false), ('B', 'Se li imposa, a més, una multa del tant al triple del valor distret.', false), ('C', 'Queda exempt de pena si els reintegra abans del judici oral.', false), ('D', 'Se li imposen les penes de l''article 432 (malversació per apropiació).', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 433 del Codi penal, l''autoritat o funcionari públic que dona al patrimoni públic que administra una aplicació pública diferent d''aquella a què estava destinat, si en resulta dany o entorpiment greus del servei, incorre en la pena de:', 'La desviació del patrimoni públic a una altra finalitat pública es castiga amb presó d''un a quatre anys i inhabilitació especial de dos a sis anys si causa dany o entorpiment greus; si no en causa, amb inhabilitació d''un a tres anys i multa de tres a dotze mesos.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 433 CP', 'incurrirá en las penas de prisión de uno a cuatro años e inhabilitación especial de empleo o cargo público de dos a seis años, si resultare daño o entorpecimiento graves del servicio al que estuviere consignado', null, '594f6e5f69b53b8b6ce058d849354c53c398e8eda7ace4a69981d008941bdc7b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '594f6e5f69b53b8b6ce058d849354c53c398e8eda7ace4a69981d008941bdc7b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de dos a sis anys i inhabilitació especial de sis a deu anys.', false), ('B', 'Presó d''un a quatre anys i inhabilitació especial d''ocupació o càrrec públic de dos a sis anys.', true), ('C', 'Inhabilitació d''ocupació o càrrec públic d''un a tres anys i multa de tres a dotze mesos.', false), ('D', 'Presó de sis mesos a tres anys i suspensió d''un a quatre anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A l''efecte de l''article 442 del Codi penal (ús de secret o d''informació privilegiada per autoritat o funcionari), s''entén per informació privilegiada:', 'L''article 442 CP defineix la informació privilegiada per tres notes: caràcter concret, coneixement exclusivament per raó del càrrec i absència de notificació, publicació o divulgació.', 'pcat_e05_delictes_administracio_publica', (select id from public.topics where slug = 'pcat-e05-delictes-administracio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 442 CP', 'A los efectos de este artículo se entiende por información privilegiada toda información de carácter concreto que se tenga exclusivamente por razón del oficio o cargo público y que no haya sido notificada, publicada o divulgada.', null, '6ce5d331596c43b5933ee0a9301b1d31c4bf0e8f5f5c8e4451e0fca0adb71564', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6ce5d331596c43b5933ee0a9301b1d31c4bf0e8f5f5c8e4451e0fca0adb71564')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol informació classificada com a secreta per llei.', false), ('B', 'Tota informació relativa a dades personals de particulars obtinguda en l''exercici del càrrec.', false), ('C', 'Qualsevol informació econòmica de què disposi l''Administració, encara que s''hagi publicat.', false), ('D', 'Tota informació de caràcter concret que es tingui exclusivament per raó de l''ofici o càrrec públic i que no hagi estat notificada, publicada o divulgada.', true)) as v(label, body, ok)
)
