insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e06-delictes-justicia-garanties', 'Tema 6. Delictes contra l''Administració de justícia i contra les garanties constitucionals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e06-delictes-justicia-garanties' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 469 del Codi penal, els condemnats o presos que s''evadeixin del lloc on estan reclosos fent ús de violència o intimidació en les persones, força en les coses o prenent part en un motí seran castigats amb la pena de:', 'L''art. 469 CP castiga l''evasió violenta (violència o intimidació, força en les coses o participació en un motí) amb presó de sis mesos a quatre anys.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 469 CP', 'Los sentenciados o presos que se fugaren del lugar en que estén recluidos, haciendo uso de violencia o intimidación en las personas o fuerza en las cosas o tomando parte en motín, serán castigados con la pena de prisión de seis meses a cuatro años.', null, '16bbd5fb65e37098e5d22fe1d9ae9d6da796ce5c192dbfca1a6853edeec8deaf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '16bbd5fb65e37098e5d22fe1d9ae9d6da796ce5c192dbfca1a6853edeec8deaf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a quatre anys.', true), ('B', 'Presó de sis mesos a un any.', false), ('C', 'Presó d''un a tres anys.', false), ('D', 'Presó de dos a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 468.1 del Codi penal, qui trenqui la seva condemna, mesura de seguretat, presó, mesura cautelar, conducció o custòdia, si està privat de llibertat, serà castigat amb la pena de:', 'L''art. 468.1 CP distingeix: presó de sis mesos a un any si el qui trenca la condemna està privat de llibertat, i multa de dotze a vint-i-quatre mesos en els altres casos.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 468.1 CP', 'Los que quebrantaren su condena, medida de seguridad, prisión, medida cautelar, conducción o custodia serán castigados con la pena de prisión de seis meses a un año si estuvieran privados de libertad, y con la pena de multa de doce a veinticuatro meses en los demás casos.', null, '9fdfc23952615ef14dc82b4c86add171e57478d471b261e8b947a5d106da5dcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9fdfc23952615ef14dc82b4c86add171e57478d471b261e8b947a5d106da5dcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a vint-i-quatre mesos.', false), ('B', 'Presó de sis mesos a un any.', true), ('C', 'Presó de sis mesos a quatre anys.', false), ('D', 'Presó d''un a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, quina pena s''imposa quan qui proporciona l''evasió d''un condemnat, pres o detingut és el funcionari públic encarregat de la seva conducció o custòdia?', 'L''art. 471 CP agreuja la conducta de l''art. 470 quan el culpable és el funcionari encarregat de la conducció o custòdia: pena superior en grau, a més de la inhabilitació especial.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 471 CP', 'Se impondrá la pena superior en grado, en sus respectivos casos, si el culpable fuera un funcionario público encargado de la conducción o custodia de un condenado, preso o detenido.', null, '54b323e96fddeadca00835ad431cd9e2bd6b2b22ccb41275b10ecf5a5cf989ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '54b323e96fddeadca00835ad431cd9e2bd6b2b22ccb41275b10ecf5a5cf989ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La mateixa pena prevista per al particular, sense cap agreujament.', false), ('B', 'La pena en la seva meitat inferior.', false), ('C', 'La pena superior en grau, en els casos respectius.', true), ('D', 'La pena inferior en grau, si no ha emprat violència ni intimidació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 471 del Codi penal, el funcionari encarregat de la custòdia que faciliti l''evasió d''un intern condemnat per sentència executòria serà castigat, a més, amb la pena d''inhabilitació especial per a ocupació o càrrec públic de:', 'L''art. 471 CP preveu inhabilitació especial de sis a deu anys si el fugitiu estava condemnat per sentència executòria, i de tres a sis anys en els altres casos.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 471 CP', 'El funcionario será castigado, además, con la pena de inhabilitación especial para empleo o cargo público de seis a diez años si el fugitivo estuviera condenado por sentencia ejecutoria, y con la inhabilitación especial para empleo o cargo público de tres a seis años en los demás casos.', null, '146865b40c97b804a817b7a9b71b1577cdf26434cf10d2a234938825bfc73cfb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '146865b40c97b804a817b7a9b71b1577cdf26434cf10d2a234938825bfc73cfb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres a sis anys.', false), ('B', 'Dos a quatre anys.', false), ('C', 'Deu a vint anys.', false), ('D', 'Sis a deu anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, el particular que proporcioni l''evasió a un condemnat, pres o detingut, del lloc on està reclòs o durant la seva conducció, sense emprar violència, intimidació, força ni suborn, serà castigat amb la pena de:', 'L''art. 470.1 CP fixa presó de sis mesos a un any i multa de dotze a vint-i-quatre mesos; si hi ha violència, intimidació, força o suborn, la pena és de sis mesos a quatre anys (art. 470.2).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 470.1 CP', 'El particular que proporcionare la evasión a un condenado, preso o detenido, bien del lugar en que esté recluido, bien durante su conducción, será castigado con la pena de prisión de seis meses a un año y multa de doce a veinticuatro meses.', null, '020ba9cc0a7c57a889aa68cf1818d86f1328d0f519242466ed53f96275d4a05f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '020ba9cc0a7c57a889aa68cf1818d86f1328d0f519242466ed53f96275d4a05f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a quatre anys.', false), ('B', 'Presó de sis mesos a un any i multa de dotze a vint-i-quatre mesos.', true), ('C', 'Multa de tres a sis mesos.', false), ('D', 'Presó d''un a tres anys i multa de sis a dotze mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 470.3 del Codi penal, si qui proporciona l''evasió és alguna de les persones citades a l''article 454 del mateix Codi, se la castigarà amb la pena de:', 'L''art. 470.3 CP preveu multa de tres a sis mesos i permet que el jutge o tribunal imposi només les penes corresponents als danys causats o a les amenaces o violències exercides.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 470.3 CP', 'Si se tratara de alguna de las personas citadas en el artículo 454, se les castigará con la pena de multa de tres a seis meses', null, 'd0ad39783b26a56bd06d563d74d70dfc3de48c908fd2a0cfeb3983eb51779d24', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd0ad39783b26a56bd06d563d74d70dfc3de48c908fd2a0cfeb3983eb51779d24')
