)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, qui inutilitzi o pertorbi el funcionament normal dels dispositius tècnics disposats per controlar el compliment de penes, mesures de seguretat o mesures cautelars serà castigat amb la pena de:', 'L''art. 468.3 CP castiga amb multa de sis a dotze mesos inutilitzar o pertorbar els dispositius de control, no portar-los a sobre o ometre les mesures per mantenir-ne el funcionament correcte.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 468.3 CP', 'Los que inutilicen o perturben el funcionamiento normal de los dispositivos técnicos que hubieran sido dispuestos para controlar el cumplimiento de penas, medidas de seguridad o medidas cautelares, no los lleven consigo u omitan las medidas exigibles para mantener su correcto estado de funcionamiento, serán castigados con una pena de multa de seis a doce meses.', null, '2b5f4e1d10b3d9e2aa3191c9e376fac6ebca2087fbbbc793b9ee9e3083964939', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2b5f4e1d10b3d9e2aa3191c9e376fac6ebca2087fbbbc793b9ee9e3083964939')
  returning id
), o as (
