)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 458.1 del Codi penal, el testimoni que falti a la veritat en el seu testimoni en una causa judicial serà castigat amb la pena de:', 'El tipus bàsic de fals testimoni (art. 458.1 CP) es castiga amb presó de sis mesos a dos anys i multa de tres a sis mesos; si és contra el reu en causa criminal, la pena puja a presó d''un a tres anys (art. 458.2).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 458.1 CP', 'El testigo que faltare a la verdad en su testimonio en causa judicial, será castigado con las penas de prisión de seis meses a dos años y multa de tres a seis meses.', null, 'dd16891bab93c33f4e05e52e5e64241f1adb88e4e4613bb8abc7047d8cf830c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dd16891bab93c33f4e05e52e5e64241f1adb88e4e4613bb8abc7047d8cf830c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a tres anys i multa de sis a dotze mesos.', false), ('B', 'Multa de sis a dotze mesos.', false), ('C', 'Presó de sis mesos a dos anys i multa de tres a sis mesos.', true), ('D', 'Presó de tres a sis mesos o multa de sis a vint-i-quatre mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre el fals testimoni NO és correcta, segons el Codi penal?', 'L''art. 462 CP només eximeix de pena la retractació feta en temps i forma perquè tingui efecte abans que es dicti sentència. Les altres tres afirmacions reprodueixen els arts. 458.2, 461.1 i 460 CP.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 458.2, 460, 461.1 i 462 CP', 'Quedará exento de pena el que, habiendo prestado un falso testimonio en causa criminal, se retracte en tiempo y forma, manifestando la verdad para que surta efecto antes de que se dicte sentencia en el proceso de que se trate.', null, '31929a42e5b3a1dd903afc52d77c3114e9f45b27d1ba48a717c1d9e02878ca29', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '31929a42e5b3a1dd903afc52d77c3114e9f45b27d1ba48a717c1d9e02878ca29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Queda exempt de pena qui es retracti del fals testimoni prestat en causa criminal, encara que ho faci després que s''hagi dictat sentència.', true), ('B', 'Si el fals testimoni es dona contra el reu en causa criminal per delicte, la pena és de presó d''un a tres anys i multa de sis a dotze mesos.', false), ('C', 'Qui presenti conscientment testimonis falsos és castigat amb les mateixes penes que s''estableixen per a ells.', false), ('D', 'El testimoni que, sense faltar substancialment a la veritat, l''alteri amb reticències o inexactituds és castigat amb multa de sis a dotze mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, els perits o intèrprets que faltin a la veritat maliciosament en el seu dictamen o traducció seran castigats amb les penes del fals testimoni en la meitat superior i, a més, amb inhabilitació especial per a professió o ofici, ocupació o càrrec públic per un temps de:', 'L''art. 459 CP imposa als perits i intèrprets mendaços les penes dels articles precedents en la meitat superior i inhabilitació especial de sis a dotze anys.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 459 CP', 'Las penas de los artículos precedentes se impondrán en su mitad superior a los peritos o intérpretes que faltaren a la verdad maliciosamente en su dictamen o traducción, los cuales serán, además, castigados con la pena de inhabilitación especial para profesión u oficio, empleo o cargo público, por tiempo de seis a doce años.', null, '94f05cf72368dbd257fc2f013968ad881f0c7598de0bc10d4fea711386b38278', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '94f05cf72368dbd257fc2f013968ad881f0c7598de0bc10d4fea711386b38278')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos a quatre anys.', false), ('B', 'Sis mesos a tres anys.', false), ('C', 'Tres a sis anys.', false), ('D', 'Sis a dotze anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 463.1 del Codi penal, qui, citat en forma legal, deixi voluntàriament de comparèixer sense causa justa davant un jutjat o tribunal en un procés criminal amb reu en presó provisional, i provoqui la suspensió del judici oral, serà castigat amb la pena de:', 'La incompareixença injustificada en causa amb reu en presó provisional que provoca la suspensió del judici oral es castiga amb presó de tres a sis mesos o multa de sis a 24 mesos (art. 463.1 CP).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 463.1 CP', 'El que, citado en legal forma, dejare voluntariamente de comparecer, sin justa causa, ante un juzgado o tribunal en proceso criminal con reo en prisión provisional, provocando la suspensión del juicio oral, será castigado con la pena de prisión de tres a seis meses o multa de seis a 24 meses.', null, '71860f0f56439dc3e97b53d65bc9376e50174f55c3e2c9984eca27f2a5b62ca3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71860f0f56439dc3e97b53d65bc9376e50174f55c3e2c9984eca27f2a5b62ca3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de sis a deu mesos.', false), ('B', 'Presó d''un a quatre anys i multa de sis a vint-i-quatre mesos.', false), ('C', 'Presó de tres a sis mesos o multa de sis a vint-i-quatre mesos.', true), ('D', 'Presó de sis mesos a dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, qui amb violència o intimidació intenti influir directament o indirectament en un testimoni perquè modifiqui la seva actuació processal serà castigat amb la pena de:', 'L''art. 464.1 CP castiga les coaccions a denunciants, parts, imputats, advocats, procuradors, perits, intèrprets o testimonis amb presó d''un a quatre anys i multa de sis a vint-i-quatre mesos.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 464.1 CP', 'El que con violencia o intimidación intentare influir directa o indirectamente en quien sea denunciante, parte o imputado, abogado, procurador, perito, intérprete o testigo en un procedimiento para que modifique su actuación procesal, será castigado con la pena de prisión de uno a cuatro años y multa de seis a veinticuatro meses.', null, '64b326769ff029e3cb377c6fcf762f58820c51d03e93be24da59d0c5247d2f6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '64b326769ff029e3cb377c6fcf762f58820c51d03e93be24da59d0c5247d2f6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de tres a sis mesos o multa de sis a vint-i-quatre mesos.', false), ('B', 'Presó d''un a quatre anys i multa de sis a vint-i-quatre mesos.', true), ('C', 'Presó de sis mesos a dos anys i multa de tres a sis mesos.', false), ('D', 'Presó de dos a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre l''obstrucció a la justícia NO és correcta, segons el Codi penal?', 'L''art. 464.1 CP disposa que, si l''autor aconsegueix el seu objectiu, la pena s''imposa en la meitat superior, no en la inferior. Les altres afirmacions recullen els arts. 463.1, 463.2 i 464.2 CP.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 463 i 464 CP', 'Si el autor del hecho alcanzara su objetivo se impondrá la pena en su mitad superior.', null, '3c53ae790eb7f8d01e0fc06139013d62e5b6b73bf0b29a14a32e586a44b115e9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3c53ae790eb7f8d01e0fc06139013d62e5b6b73bf0b29a14a32e586a44b115e9')
  returning id
