with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, l''autoritat o funcionari públic que, mediant causa per delicte, acordi, practiqui o prolongui qualsevol privació de llibertat d''un detingut, pres o condemnat amb violació dels terminis o altres garanties constitucionals o legals serà castigat amb inhabilitació especial per a ocupació o càrrec públic de:', 'L''art. 530 CP fixa inhabilitació especial de quatre a vuit anys per a la privació de llibertat il·legal acordada, practicada o prolongada per autoritat o funcionari.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 530 CP', 'La autoridad o funcionario público que, mediando causa por delito, acordare, practicare o prolongare cualquier privación de libertad de un detenido, preso o sentenciado, con violación de los plazos o demás garantías constitucionales o legales, será castigado con la pena de inhabilitación especial para empleo o cargo público por tiempo de cuatro a ocho años.', null, '91b438850409ccf10b9323940ef14a380530f618299bbbab1981061aaaed467c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91b438850409ccf10b9323940ef14a380530f618299bbbab1981061aaaed467c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quatre a vuit anys.', true), ('B', 'Dos a sis anys.', false), ('C', 'Sis mesos a dos anys.', false), ('D', 'Sis a deu anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 531 del Codi penal, l''autoritat o funcionari públic que, mediant causa per delicte, decreti, practiqui o prolongui la incomunicació d''un detingut, pres o condemnat amb violació dels terminis o altres garanties serà castigat amb inhabilitació especial per a ocupació o càrrec públic de:', 'L''art. 531 CP castiga la incomunicació il·legal amb inhabilitació especial de dos a sis anys (la privació de llibertat il·legal de l''art. 530 té quatre a vuit anys).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 531 CP', 'La autoridad o funcionario público que, mediando causa por delito, decretare, practicare o prolongare la incomunicación de un detenido, preso o sentenciado, con violación de los plazos o demás garantías constitucionales o legales, será castigado con la pena de inhabilitación especial para empleo o cargo público por tiempo de dos a seis años.', null, 'c0d8d75a9b88e54f51700bf062e70883eacbdf24320cf8b3f3398b8d4188ac26', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c0d8d75a9b88e54f51700bf062e70883eacbdf24320cf8b3f3398b8d4188ac26')
  returning id
