)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, si els fets descrits als articles 530 i 531 (privació de llibertat o incomunicació amb violació dels terminis o garanties) es cometen per imprudència greu:', 'L''art. 532 CP preveu la modalitat imprudent (imprudència greu) dels arts. 530 i 531, castigada amb suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 532 CP', 'Si los hechos descritos en los dos artículos anteriores fueran cometidos por imprudencia grave, se castigarán con la pena de suspensión de empleo o cargo público por tiempo de seis meses a dos años.', null, 'ffc16898ad87b23999542bd19f5d029703248c40d23b1825d0a7362d7a4d5fd1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ffc16898ad87b23999542bd19f5d029703248c40d23b1825d0a7362d7a4d5fd1')
