insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 537 del Codi penal, quina de les conductes següents de l''autoritat o funcionari públic respecte d''un detingut o pres NO hi està tipificada?', 'L''art. 537 CP castiga impedir o obstaculitzar l''assistència d''advocat, procurar-ne o afavorir-ne la renúncia i no informar immediatament i de manera comprensible dels drets i de les raons de la detenció (multa de quatre a deu mesos i inhabilitació especial de dos a quatre anys).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 537 CP', 'La autoridad o funcionario público que impida u obstaculice el derecho a la asistencia de abogado al detenido o preso, procure o favorezca la renuncia del mismo a dicha asistencia o no le informe de forma inmediata y de modo que le sea comprensible de sus derechos y de las razones de su detención, será castigado con la pena de multa de cuatro a diez meses e inhabilitación especial para empleo o cargo público de dos a cuatro años.', null, '6473429cbe46dfc5034f6c526d7ad7fe49fc892190cf1e24f242bd169a30ea2f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6473429cbe46dfc5034f6c526d7ad7fe49fc892190cf1e24f242bd169a30ea2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No comunicar la detenció als seus familiars en el termini de vint-i-quatre hores.', true), ('B', 'Impedir o obstaculitzar el dret a l''assistència d''advocat.', false), ('C', 'Procurar o afavorir la renúncia a l''assistència d''advocat.', false), ('D', 'No informar-lo de forma immediata i de manera comprensible dels seus drets i de les raons de la detenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 408 del Codi penal, l''autoritat o funcionari que, faltant a l''obligació del seu càrrec, deixi intencionadament de promoure la persecució dels delictes dels quals tingui notícia o dels seus responsables serà castigat amb la pena de:', 'L''omissió del deure de perseguir delictes (art. 408 CP) es castiga amb inhabilitació especial per a ocupació o càrrec públic de sis mesos a dos anys.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 408 CP', 'La autoridad o funcionario que, faltando a la obligación de su cargo, dejare intencionadamente de promover la persecución de los delitos de que tenga noticia o de sus responsables, incurrirá en la pena de inhabilitación especial para empleo o cargo público por tiempo de seis meses a dos años.', null, '9608f895b91eb7112f60a350f1854c26ef1d8758809b2038012e472cbca6340c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9608f895b91eb7112f60a350f1854c26ef1d8758809b2038012e472cbca6340c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspensió d''ocupació o càrrec públic de sis mesos a dos anys.', false), ('B', 'Inhabilitació especial per a ocupació o càrrec públic de dos a sis anys.', false), ('C', 'Inhabilitació especial per a ocupació o càrrec públic de sis mesos a dos anys.', true), ('D', 'Multa de sis a dotze mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 468.2 del Codi penal, qui trenqui una pena de les previstes a l''article 48 del Codi (com la prohibició d''aproximar-se a la víctima) imposada en un procés en què l''ofès sigui alguna de les persones de l''article 173.2 serà castigat, en tot cas, amb la pena de:', 'L''art. 468.2 CP imposa en tot cas presó de sis mesos a un any per trencar les penes de l''art. 48 o les mesures de la mateixa naturalesa en processos de l''àmbit de l''art. 173.2, i també per trencar la llibertat vigilada.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 468.2 CP', 'Se impondrá en todo caso la pena de prisión de seis meses a un año a los que quebrantaren una pena de las contempladas en el artículo 48 de este Código o una medida cautelar o de seguridad de la misma naturaleza impuesta en procesos criminales en los que el ofendido sea alguna de las personas a las que se refiere el artículo 173.2, así como a aquellos que quebrantaren la medida de libertad vigilada.', null, '0fab51fcb0777e67a406b7c23288bd31055c8fcba2f6046577de48ebc96f1481', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0fab51fcb0777e67a406b7c23288bd31055c8fcba2f6046577de48ebc96f1481')
  returning id
