  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a vint-i-quatre mesos.', false), ('B', 'Multa de sis a dotze mesos.', false), ('C', 'Presó de sis mesos a un any.', true), ('D', 'Presó de sis mesos a quatre anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
