with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 470 del Codi penal, si el particular que proporciona l''evasió d''un pres empra violència o intimidació en les persones, força en les coses o suborn, la pena és de:', 'L''art. 470.2 CP eleva la pena del particular que proporciona l''evasió a presó de sis mesos a quatre anys quan hi empra violència, intimidació, força en les coses o suborn.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 470.2 CP', 'Si se empleara al efecto violencia o intimidación en las personas, fuerza en las cosas o soborno, la pena será de prisión de seis meses a cuatro años.', null, 'ab992ce336ebdf7f99388b364a91708368fe9f3bec395057ed5ed3406544ecca', false
