insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 457 del Codi penal, qui davant un funcionari judicial o administratiu simuli ser responsable o víctima d''una infracció penal, o en denunciï una d''inexistent, provocant actuacions processals, serà castigat amb la pena de:', 'La simulació de delictes (art. 457 CP) es castiga amb multa de sis a dotze mesos.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 457 CP', 'El que, ante alguno de los funcionarios señalados en el artículo anterior, simulare ser responsable o víctima de una infracción penal o denunciare una inexistente, provocando actuaciones procesales, será castigado con la multa de seis a doce meses.', null, 'e17c6e4d1a9b74f8a9c7a1ae42dfe6d2b4bc0548b520c7a509b2e8cdeb8b3955', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e17c6e4d1a9b74f8a9c7a1ae42dfe6d2b4bc0548b520c7a509b2e8cdeb8b3955')
  returning id
