insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 450 del Codi penal, qui, podent fer-ho, no acudeixi a l''autoritat o als seus agents perquè impedeixin un delicte contra la vida de la comissió pròxima o actual del qual tingui notícia:', 'L''art. 450.2 CP equipara a l''omissió d''impedir el delicte (art. 450.1) la conducta de qui, podent fer-ho, no acudeix a l''autoritat o als seus agents perquè l''impedeixin.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 450.2 CP', 'En las mismas penas incurrirá quien, pudiendo hacerlo, no acuda a la autoridad o a sus agentes para que impidan un delito de los previstos en el apartado anterior y de cuya próxima o actual comisión tenga noticia.', null, 'c478768b24ba233a421275f95630f2d19994f09386221a9939b870158d9a9e8a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c478768b24ba233a421275f95630f2d19994f09386221a9939b870158d9a9e8a')
  returning id
