  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 535 del Codi penal, l''autoritat o funcionari públic que, mediant causa per delicte, intercepti qualsevol classe de correspondència privada, postal o telegràfica, amb violació de les garanties constitucionals o legals, incorre en la pena de:', 'La intercepció il·legal de correspondència per autoritat o funcionari (art. 535 CP) es castiga amb inhabilitació especial de dos a sis anys; si se''n divulga la informació, en la meitat superior i multa de sis a divuit mesos.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 535 CP', 'La autoridad o funcionario público que, mediando causa por delito, interceptare cualquier clase de correspondencia privada, postal o telegráfica, con violación de las garantías constitucionales o legales, incurrirá en la pena de inhabilitación especial para empleo o cargo público de dos a seis años.', null, '6897cba03b7c7d8ac6e5c67fb541c45b062c4566b877b8a7c9911626bb9f112a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6897cba03b7c7d8ac6e5c67fb541c45b062c4566b877b8a7c9911626bb9f112a')
