select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre l''acusació i denúncia falses NO és correcta, segons l''article 456.1 del Codi penal?', 'L''art. 456.1 CP castiga la imputació falsa feta davant un funcionari judicial o administratiu que tingui el deure d''investigar-la, i gradua la pena segons que el delicte imputat sigui greu, menys greu o lleu.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 456.1 CP', 'si esta imputación se hiciera ante funcionario judicial o administrativo que tenga el deber de proceder a su averiguación, serán sancionados: 1.º Con la pena de prisión de seis meses a dos años y multa de doce a veinticuatro meses, si se imputara un delito grave. 2.º Con la pena de multa de doce a veinticuatro meses, si se imputara un delito menos grave. 3.º Con la pena de multa de tres a seis meses, si se imputara un delito leve.', null, 'dfe18939ae51030644893d030656bd541d436b7e34ef124e93698c90a584eae7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dfe18939ae51030644893d030656bd541d436b7e34ef124e93698c90a584eae7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si s''imputa un delicte greu, la pena és de presó de sis mesos a dos anys i multa de dotze a vint-i-quatre mesos.', false), ('B', 'Si s''imputa un delicte menys greu, la pena és de multa de dotze a vint-i-quatre mesos.', false), ('C', 'La imputació només és punible si es fa davant un funcionari judicial; la feta davant un funcionari administratiu és atípica.', true), ('D', 'Si s''imputa un delicte lleu, la pena és de multa de tres a sis mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
