with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 450.1 del Codi penal, qui, podent fer-ho amb la seva intervenció immediata i sense risc propi o aliè, no impedeixi la comissió d''un delicte contra la vida serà castigat amb la pena de:', 'L''art. 450.1 CP castiga l''omissió del deure d''impedir delictes amb presó de sis mesos a dos anys si el delicte és contra la vida, i amb multa de sis a vint-i-quatre mesos en els altres casos (llevat que el delicte no impedit tingui una pena igual o menor).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 450.1 CP', 'será castigado con la pena de prisión de seis meses a dos años si el delito fuera contra la vida, y la de multa de seis a veinticuatro meses en los demás casos', null, 'a15276a2b8f399aedd18cc2920824bed9d2f93266809238ba84763bd63313976', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a15276a2b8f399aedd18cc2920824bed9d2f93266809238ba84763bd63313976')
  returning id
