with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 538 del Codi penal, l''autoritat o funcionari públic que estableixi la censura prèvia o, fora dels casos permesos, reculli edicions de llibres o periòdics incorre en la pena de:', 'L''art. 538 CP és dels pocs de la secció que preveu inhabilitació absoluta (de sis a deu anys).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 538 CP', 'La autoridad o funcionario público que establezca la censura previa o, fuera de los casos permitidos por la Constitución y las Leyes, recoja ediciones de libros o periódicos o suspenda su publicación o la difusión de cualquier emisión radiotelevisiva, incurrirá en la pena de inhabilitación absoluta de seis a diez años.', null, '8910c979b5a0a08ac79d69d1831df132fa75d5a34ec8f4cde3f72734f2538dd9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8910c979b5a0a08ac79d69d1831df132fa75d5a34ec8f4cde3f72734f2538dd9')
