with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 463.3 del Codi penal, si la suspensió del judici oral en una causa amb reu en presó provisional és conseqüència de la incompareixença del jutge o d''un membre del tribunal, la pena és de:', 'L''art. 463.3 CP castiga la incompareixença del jutge, membre del tribunal o qui exerceixi les funcions de secretari judicial amb presó de tres a sis mesos o multa de sis a 24 mesos i, en qualsevol cas, inhabilitació especial de dos a quatre anys.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 463.3 CP', 'Si la suspensión tuviera lugar, en el caso del apartado 1 de este artículo, como consecuencia de la incomparecencia del juez o miembro del tribunal o de quien ejerza las funciones de secretario judicial, se impondrá la pena de prisión de tres a seis meses o multa de seis a 24 meses y, en cualquier caso, inhabilitación especial por tiempo de dos a cuatro años.', null, 'a2b37c104c82bde043889707dd82b2aa92f2354cf5670a3639260d94d2a39684', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2b37c104c82bde043889707dd82b2aa92f2354cf5670a3639260d94d2a39684')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de tres a sis mesos o multa de sis a vint-i-quatre mesos i, en tot cas, inhabilitació especial de dos a quatre anys.', true), ('B', 'Multa de sis a deu mesos.', false), ('C', 'Inhabilitació especial per a ocupació o càrrec públic de sis mesos a quatre anys, sense pena de presó ni de multa.', false), ('D', 'Presó de sis mesos a un any i inhabilitació especial de tres a sis anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
