with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 466.2 del Codi penal, si la revelació d''actuacions processals declarades secretes la fa un funcionari al servei de l''Administració de justícia, se li imposen:', 'L''art. 466.2 CP remet, per al jutge, membre del tribunal, fiscal, secretari judicial o funcionari de l''Administració de justícia, a les penes de l''art. 417 en la meitat superior; per a un altre particular que intervingui en el procés, la pena de l''apartat 1 s''imposa en la meitat inferior (art. 466.3).', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 466.2 CP', 'Si la revelación de las actuaciones declaradas secretas fuese realizada por el Juez o miembro del Tribunal, representante del Ministerio Fiscal, Secretario Judicial o cualquier funcionario al servicio de la Administración de Justicia, se le impondrán las penas previstas en el artículo 417 en su mitad superior.', null, '7bd1dc7a8664319322c7949252d4e3ebc176f1164106d827f245e9a1e6e316d1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7bd1dc7a8664319322c7949252d4e3ebc176f1164106d827f245e9a1e6e316d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les mateixes penes que a l''advocat o procurador, en la meitat inferior.', false), ('B', 'Les penes de l''article 417 en la meitat inferior.', false), ('C', 'Les penes previstes a l''article 417 (revelació de secrets) en la meitat superior.', true), ('D', 'Multa de dotze a vint-i-quatre mesos i inhabilitació especial d''un a quatre anys.', false)) as v(label, body, ok)
)
