with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 456.2 del Codi penal, quan es pot procedir contra el denunciant o acusador per acusació o denúncia falses?', 'L''art. 456.2 CP exigeix sentència ferma o interlocutòria ferma de sobreseïment o arxivament; el jutge o tribunal ha de mandar procedir d''ofici si hi ha indicis bastants de falsedat, sens perjudici de la denúncia de l''ofès.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 456.2 CP', 'No podrá procederse contra el denunciante o acusador sino tras sentencia firme o auto también firme, de sobreseimiento o archivo del Juez o Tribunal que haya conocido de la infracción imputada.', null, 'bd91d8312c59102feacbfcdf062cedd71c4af75d6cb10492bdaeaa1852b31359', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bd91d8312c59102feacbfcdf062cedd71c4af75d6cb10492bdaeaa1852b31359')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En qualsevol moment, des que el funcionari que rep la denúncia n''apreciï la falsedat.', false), ('B', 'Només després d''una sentència ferma o d''una interlocutòria, també ferma, de sobreseïment o arxivament del jutge o tribunal que hagi conegut de la infracció imputada.', true), ('C', 'Només després que l''ofès hagi presentat querella, i mai d''ofici.', false), ('D', 'Quan el jutge d''instrucció hagi dictat la interlocutòria d''incoació de la causa principal.', false)) as v(label, body, ok)
)
