with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 534.1 del Codi penal, si l''autoritat o funcionari que ha registrat il·legalment papers o efectes d''una persona no els retorna al propietari immediatament després del registre, les penes són de:', 'L''art. 534.1 CP agreuja la conducta si no es retornen immediatament els papers, documents i efectes registrats: inhabilitació especial de sis a dotze anys i multa de dotze a vint-i-quatre mesos, sens perjudici de la pena per l''apropiació.', 'pcat_e06_delictes_justicia_garanties', (select id from public.topics where slug = 'pcat-e06-delictes-justicia-garanties'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 534.1 CP', 'Si no devolviera al dueño, inmediatamente después del registro, los papeles, documentos y efectos registrados, las penas serán las de inhabilitación especial para empleo o cargo público de seis a doce años y multa de doce a veinticuatro meses', null, '8c9528368bb0cbf07fe9da7b4518a679f2763be70493bbab01ab026e90a267df', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8c9528368bb0cbf07fe9da7b4518a679f2763be70493bbab01ab026e90a267df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de sis a dotze mesos i inhabilitació especial de dos a sis anys, en la meitat superior.', false), ('B', 'Inhabilitació absoluta de sis a deu anys.', false), ('C', 'Inhabilitació especial per a ocupació o càrrec públic de sis a dotze anys i multa de dotze a vint-i-quatre mesos.', true), ('D', 'Inhabilitació especial de quatre a vuit anys i multa de sis a divuit mesos.', false)) as v(label, body, ok)
)
