with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels drets següents NO figura en l''enumeració de l''article 24.2 de la Constitució espanyola?', 'L''art. 24.2 CE enumera, entre d''altres, el dret al jutge ordinari predeterminat per la llei, a la defensa i a l''assistència de lletrat, a un procés públic sense dilacions indegudes i a utilitzar els mitjans de prova pertinents. La participació en el jurat es regula a l''art. 125 CE i només en els processos que la llei determini.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 24.2 CE', 'todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, a ser informados de la acusación formulada contra ellos, a un proceso público sin dilaciones indebidas y con todas las garantías, a utilizar los medios de prueba pertinentes para su defensa', null, 'f8a9e0a3f0ada5f0371a1f9034bbb31bd6cee9839754464c60b71da851d41fcb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f8a9e0a3f0ada5f0371a1f9034bbb31bd6cee9839754464c60b71da851d41fcb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret al jutge ordinari predeterminat per la llei.', false), ('B', 'El dret a un procés públic sense dilacions indegudes i amb totes les garanties.', false), ('C', 'El dret a ser jutjat en tot cas per un tribunal del jurat.', true), ('D', 'El dret a utilitzar els mitjans de prova pertinents per a la defensa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 125 de la Constitució espanyola, els ciutadans poden exercir l''acció popular i participar en l''Administració de justícia mitjançant:', 'L''art. 125 CE preveu l''acció popular i la participació ciutadana en l''Administració de justícia mitjançant el Jurat i els tribunals consuetudinaris i tradicionals.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 125 CE', 'Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la ley determine', null, 'c9a6e816e1215c03a63c334b9eaead30562d98d9f676f0dfe2cfc237d1f811b2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c9a6e816e1215c03a63c334b9eaead30562d98d9f676f0dfe2cfc237d1f811b2')
  returning id
), o as (
