  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministeri Fiscal.', false), ('B', 'L''elecció dels membres del Consell General del Poder Judicial.', false), ('C', 'La designació dels jutges de pau de cada municipi.', false), ('D', 'La institució del Jurat, en la forma i respecte als processos penals que la llei determini.', true)) as v(label, body, ok)
)
