with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 120 de la Constitució espanyola, les sentències:', 'L''art. 120 CE estableix la publicitat de les actuacions judicials, el caràcter predominantment oral del procediment, sobretot en matèria criminal, i que les sentències són sempre motivades i es pronuncien en audiència pública.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 120.3 CE', 'Las sentencias serán siempre motivadas y se pronunciarán en audiencia pública.', null, '996c247c997845235eacd67a17e9a05ac99057e8a3cab1e62581f374a4020dac', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '996c247c997845235eacd67a17e9a05ac99057e8a3cab1e62581f374a4020dac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seran sempre motivades i es pronunciaran en audiència pública.', true), ('B', 'Només s''han de motivar quan siguin condemnatòries.', false), ('C', 'Es pronunciaran a porta tancada en matèria criminal.', false), ('D', 'S''han de motivar quan ho sol·liciti alguna de les parts.', false)) as v(label, body, ok)
)
