  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 117.1 de la Constitució espanyola, la justícia emana del poble i s''administra en nom del Rei per jutges i magistrats integrants del poder judicial, que són:', 'L''art. 117.1 CE qualifica els jutges i magistrats d''independents, inamovibles, responsables i sotmesos únicament a l''imperi de la llei.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 117.1 CE', 'La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.', null, '5e3423edba27f6e21c55860f621acebdc54c863c9f79923c320cea78304a8f60', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e3423edba27f6e21c55860f621acebdc54c863c9f79923c320cea78304a8f60')
