  select 'Segons l''article 117.3 de la Constitució espanyola, a qui correspon exclusivament l''exercici de la potestat jurisdiccional en tota mena de processos, jutjant i fent executar allò que s''ha jutjat?', 'L''art. 117.3 CE reserva la potestat jurisdiccional, jutjant i fent executar allò jutjat, exclusivament als jutjats i tribunals determinats per les lleis.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 117.3 CE', 'El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes', null, '8d7e5e349eb86586122c74aff398e96b7d130500ddf0844640564173778ee29c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8d7e5e349eb86586122c74aff398e96b7d130500ddf0844640564173778ee29c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consell General del Poder Judicial.', false), ('B', 'Als jutjats i tribunals determinats per les lleis.', true), ('C', 'Al Ministeri Fiscal i als jutjats i tribunals.', false), ('D', 'Al Tribunal Constitucional i al Tribunal Suprem.', false)) as v(label, body, ok)
)
