with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 757 de la Llei d''enjudiciament criminal, quan el delicte està castigat amb penes de naturalesa diferent de la privativa de llibertat, el procediment abreujat s''aplica:', 'L''art. 757 LECrim inclou en el procediment abreujat els delictes castigats amb qualssevol altres penes de naturalesa diferent, úniques, conjuntes o alternatives, qualsevol que en sigui la quantia o la durada.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 757 LECrim', 'o bien con cualesquiera otras penas de distinta naturaleza bien sean únicas, conjuntas o alternativas, cualquiera que sea su cuantía o duración.', null, '459ee9772a532a5c49e0191f92d13fe90ed3b9c97df025b9c90c12624f22a804', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '459ee9772a532a5c49e0191f92d13fe90ed3b9c97df025b9c90c12624f22a804')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol que en sigui la quantia o la durada, tant si són úniques com conjuntes o alternatives.', true), ('B', 'Només si la durada d''aquestes penes no excedeix de deu anys.', false), ('C', 'Només si són penes úniques, no conjuntes ni alternatives.', false), ('D', 'Només si la pena de multa no excedeix de vint-i-quatre mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14 de la Llei d''enjudiciament criminal, a qui correspon, amb caràcter general, el coneixement i la decisió de les causes per delictes als quals la llei assenyala una pena privativa de llibertat de durada no superior a cinc anys?', 'L''art. 14.3 LECrim atribueix a la Secció Penal del Tribunal d''Instància les causes per delictes amb pena privativa de llibertat no superior a cinc anys (o multa de qualsevol quantia, o altres penes de durada no superior a deu anys); la resta correspon a l''Audiència Provincial (art. 14.4).', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.3 LECrim', 'Para el conocimiento y fallo de las causas por delitos a los que la ley señale pena privativa de libertad de duración no superior a cinco años o pena de multa cualquiera que sea su cuantía, o cualesquiera otras de distinta naturaleza, bien sean únicas, conjuntas o alternativas, siempre que la duración de estas no exceda de diez años […] la Sección de lo Penal del Tribunal de Instancia de la circunscripción donde el delito fue cometido', null, '5e719265ac257d4d993b1857fea65e203cf2a7cc1c449881f9df842d456a447c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e719265ac257d4d993b1857fea65e203cf2a7cc1c449881f9df842d456a447c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A l''Audiència Provincial de la circumscripció on es va cometre el delicte.', false), ('B', 'A la Secció d''Instrucció del Tribunal d''Instància del partit on es va cometre el delicte.', false), ('C', 'Al Tribunal del Jurat.', false), ('D', 'A la Secció Penal del Tribunal d''Instància de la circumscripció on es va cometre el delicte.', true)) as v(label, body, ok)
)
