with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14.4 de la Llei d''enjudiciament criminal, en els supòsits de competència de l''Audiència Provincial, si el delicte és dels atribuïts al Tribunal del Jurat, el coneixement i la decisió corresponen:', 'L''art. 14.4 LECrim reserva a l''Audiència Provincial les causes no atribuïdes a altres òrgans, però si el delicte és dels atribuïts al Tribunal del Jurat, el coneixement i la decisió corresponen a aquest.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.4 LECrim', 'No obstante, en los supuestos de competencia de la Audiencia Provincial, si el delito fuere de los atribuidos al Tribunal de Jurado, el conocimiento y fallo corresponderá a éste.', null, '25ec106cce6946860181fac34085bcdd9f57f1dcc89a49327f5832cc36f44bf0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '25ec106cce6946860181fac34085bcdd9f57f1dcc89a49327f5832cc36f44bf0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A l''Audiència Provincial igualment.', false), ('B', 'A la Sala Penal de l''Audiència Nacional.', false), ('C', 'Al Tribunal del Jurat.', true), ('D', 'A la Secció Penal del Tribunal d''Instància.', false)) as v(label, body, ok)
)
