with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei d''enjudiciament criminal, el procediment per a l''enjudiciament ràpid de determinats delictes s''aplica a delictes castigats amb pena privativa de llibertat que no excedeixi de:', 'L''art. 795.1 LECrim aplica el judici ràpid a delictes castigats amb pena privativa de llibertat no superior a cinc anys (o altres penes de durada no superior a deu anys), quan el procés s''incoa en virtut d''un atestat policial i concorre alguna de les circumstàncies previstes.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 795.1 LECrim', 'el procedimiento regulado en este Título se aplicará a la instrucción y al enjuiciamiento de delitos castigados con pena privativa de libertad que no exceda de cinco años', null, '8e623c174c57abe65f3d4f5259cdbc9b410b8aaf12c4e9a498e4f6f70fb37ebf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8e623c174c57abe65f3d4f5259cdbc9b410b8aaf12c4e9a498e4f6f70fb37ebf')
  returning id
), o as (
