select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 102 de la Llei d''enjudiciament criminal, quina de les persones següents no pot exercir, amb caràcter general, l''acció penal?', 'L''art. 102 LECrim exclou de l''exercici de l''acció penal qui no gaudeixi de la plenitud dels drets civils, qui hagi estat condemnat dues vegades per denúncia o querella calumnioses i el jutge o magistrat (llevat dels delictes contra ells o els seus familiars).', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 102 LECrim', 'no podrán ejercitar la acción penal: 1.º El que no goce de la plenitud de los derechos civiles. 2.º El que hubiera sido condenado dos veces por sentencia firme como reo del delito de denuncia o querella calumniosas. 3.º El Juez o Magistrado.', null, '001490b40c3472de4ca1bfd4b7dc5b1a2e8a89d72ab2a80f4b6e7293a7dd01ab', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '001490b40c3472de4ca1bfd4b7dc5b1a2e8a89d72ab2a80f4b6e7293a7dd01ab')
  returning id
), o as (
