  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 118.2 de la Llei d''enjudiciament criminal, el dret de defensa s''exerceix sense més limitacions que les previstes expressament en la llei:', 'L''art. 118.2 LECrim estén el dret de defensa des de l''atribució del fet punible investigat fins a l''extinció de la pena; inclou l''assistència d''un advocat de lliure designació o d''ofici.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 118.2 LECrim', 'El derecho de defensa se ejercerá sin más limitaciones que las expresamente previstas en la ley desde la atribución del hecho punible investigado hasta la extinción de la pena.', null, '1cc29efdee8be0f82a55059fad4b8977bceacffc8b80b4a0633ab128f24acea4', false
