with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14.4 de la Llei d''enjudiciament criminal, en els casos que no corresponen a la Secció Penal del Tribunal d''Instància (delictes castigats amb penes més greus), el coneixement i la decisió de les causes corresponen, amb caràcter general, a:', 'L''art. 14.4 LECrim atribueix els altres casos a l''Audiència Provincial de la circumscripció on s''ha comès el delicte (o la que correspongui en matèria de violència sobre la dona, o la Sala Penal de l''Audiència Nacional), sens perjudici del Tribunal del Jurat.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.4 LECrim', 'Para el conocimiento y fallo de las causas en los demás casos la Audiencia Provincial de la circunscripción donde el delito se haya cometido', null, 'be0e431078122f5275b2a6f7c3fefd1f40b58ac4ed9b03e0684a14a1da533fbe', false
