  select 'Segons l''article 680 de la Llei d''enjudiciament criminal, els debats del judici oral:', 'L''art. 680 LECrim imposa la publicitat dels debats del judici oral sota pena de nul·litat; l''art. 681 permet acordar la porta tancada per raons de seguretat, ordre públic o protecció de drets fonamentals.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 680 LECrim', 'Los debates del juicio oral serán públicos, bajo pena de nulidad, sin perjuicio de lo dispuesto en el artículo siguiente.', null, '8b62b766d5b788691f8dbbd445596d779aba8d25509064be3ed5aa523b156d8e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8b62b766d5b788691f8dbbd445596d779aba8d25509064be3ed5aa523b156d8e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són públics, sota pena de nul·litat, sens perjudici que es puguin celebrar a porta tancada en els casos previstos.', true), ('B', 'Són sempre a porta tancada si hi ha víctimes menors d''edat.', false), ('C', 'Són públics només si ho sol·licita la defensa.', false), ('D', 'Són reservats, com les diligències del sumari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la Llei d''enjudiciament criminal, totes les autoritats i els funcionaris que intervenen en el procediment penal han de:', 'L''art. 2 LECrim imposa el deure d''objectivitat (circumstàncies adverses i favorables) i el d''informar el reu dels seus drets i recursos si no té defensor.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 2 LECrim', 'Todas las Autoridades y funcionarios que intervengan en el procedimiento penal cuidarán, dentro de los límites de su respectiva competencia, de consignar y apreciar las circunstancias así adversas como favorables al presunto reo, y estarán obligados, a falta de disposición expresa, a instruir a éste de sus derechos y de los recursos que pueda ejercitar mientras no se hallare asistido de defensor.', null, '123b52d02cc6845458bda96cc7a5b7afa6cc9f9237a17a9c19eb7bc92b00842b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '123b52d02cc6845458bda96cc7a5b7afa6cc9f9237a17a9c19eb7bc92b00842b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Consignar només les circumstàncies adverses al presumpte reu, ja que les favorables pertoquen a la defensa.', false), ('B', 'Instruir el presumpte reu dels seus drets només quan ho sol·liciti expressament.', false), ('C', 'Consignar i apreciar les circumstàncies tant adverses com favorables al presumpte reu, i instruir-lo dels seus drets i recursos mentre no estigui assistit de defensor.', true), ('D', 'Abstenir-se d''informar el presumpte reu dels recursos fins que hagi designat advocat.', false)) as v(label, body, ok)
)
