  select 'Segons l''article 14.1 de la Llei d''enjudiciament criminal, en la redacció vigent, a qui correspon, amb caràcter general, el coneixement i la decisió dels judicis per delicte lleu?', 'L''art. 14.1 LECrim atribueix els judicis per delicte lleu a la Secció d''Instrucció del Tribunal d''Instància, llevat que correspongui a les seccions de violència sobre la dona o de violència contra la infància i l''adolescència.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.1 LECrim', 'Para el conocimiento y fallo de los juicios por delito leve, la Sección de Instrucción de los Tribunales de Instancia', null, 'de090bc9805d2571b48bf90af37732dcd49d6976ef8150798bc91ce1236f8e51', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'de090bc9805d2571b48bf90af37732dcd49d6976ef8150798bc91ce1236f8e51')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la Secció Penal del Tribunal d''Instància.', false), ('B', 'A l''Audiència Provincial.', false), ('C', 'A la Secció d''Instrucció del Tribunal d''Instància.', true), ('D', 'Al jutge de pau del municipi on es va cometre el fet.', false)) as v(label, body, ok)
)
