with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels supòsits següents NO es considera delicte connex segons l''article 17.2 de la Llei d''enjudiciament criminal?', 'L''art. 17.2 LECrim considera connexos, entre d''altres, els comesos per dues o més persones reunides, els comesos per diverses persones en llocs o temps diferents amb concert previ, els comesos com a mitjà per a d''altres, els comesos per procurar la impunitat i el favoriment real i personal i el blanqueig respecte del delicte antecedent.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 17.2 LECrim', '1.º Los cometidos por dos o más personas reunidas. 2.º Los cometidos por dos o más personas en distintos lugares o tiempos si hubiera precedido concierto para ello. 3.º Los cometidos como medio para perpetrar otros o facilitar su ejecución. 4.º Los cometidos para procurar la impunidad de otros delitos.', null, '9e99681683a94e06fea2340dcca8adea5774c1d55405e3866fc3d9d332a9f01d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9e99681683a94e06fea2340dcca8adea5774c1d55405e3866fc3d9d332a9f01d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els delictes comesos per dues o més persones reunides.', false), ('B', 'Els delictes comesos per una mateixa persona en llocs diferents sense cap relació entre si.', true), ('C', 'Els delictes comesos com a mitjà per perpetrar-ne d''altres o facilitar-ne l''execució.', false), ('D', 'Els delictes comesos per procurar la impunitat d''altres delictes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
