with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 105.1 de la Llei d''enjudiciament criminal, els funcionaris del Ministeri Fiscal tenen l''obligació d''exercir totes les accions penals que considerin procedents, hi hagi o no acusador particular, excepte:', 'L''art. 105.1 LECrim exceptua de l''obligació del Ministeri Fiscal les accions que el Codi penal reserva exclusivament a la querella privada.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 105.1 LECrim', 'Los funcionarios del Ministerio Fiscal tendrán la obligación de ejercitar, con arreglo a las disposiciones de la Ley, todas las acciones penales que consideren procedentes, haya o no acusador particular en las causas, menos aquellas que el Código Penal reserva exclusivamente a la querella privada.', null, 'cf746cd68d3f5e1f76b2c68d229580ceb4d852fb4790641de153038448733066', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf746cd68d3f5e1f76b2c68d229580ceb4d852fb4790641de153038448733066')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les que deriven de delictes lleus.', false), ('B', 'Les que deriven de delictes comesos per funcionaris públics.', false), ('C', 'Les que la víctima ja hagi exercit mitjançant querella.', false), ('D', 'Les que el Codi penal reserva exclusivament a la querella privada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 106 de la Llei d''enjudiciament criminal, l''acció penal per un delicte que dona lloc al procediment d''ofici:', 'L''art. 106 LECrim: la renúncia de l''ofès no extingeix l''acció penal dels delictes perseguibles d''ofici; sí que extingeix la dels perseguibles només a instància de part i les accions civils.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 106 LECrim', 'La acción penal por delito o falta que dé lugar al procedimiento de oficio no se extingue por la renuncia de la persona ofendida.', null, '29b394ef15ebae87fd2da191265e99a0d91fe099c2e532969360e9d17439f5ac', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29b394ef15ebae87fd2da191265e99a0d91fe099c2e532969360e9d17439f5ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No s''extingeix per la renúncia de la persona ofesa.', true), ('B', 'S''extingeix per la renúncia de la persona ofesa, si es fa abans del judici oral.', false), ('C', 'S''extingeix pel perdó de l''ofès en qualsevol moment.', false), ('D', 'S''extingeix per la renúncia de l''ofès si el Ministeri Fiscal hi està d''acord.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 115 de la Llei d''enjudiciament criminal, la mort del culpable:', 'L''art. 115 LECrim declara extingida l''acció penal per la mort del culpable i manté la civil contra hereus i causahavents, per la via civil.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 115 LECrim', 'La acción penal se extingue por la muerte del culpable; pero en este caso subsiste la civil contra sus herederos y causahabientes, que sólo podrá ejercitarse ante la jurisdicción y por la vía de lo civil.', null, '1c923d909d67d46f8ad11cc786db0903a8dc26975550e3d684acbbfdcf248ec3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1c923d909d67d46f8ad11cc786db0903a8dc26975550e3d684acbbfdcf248ec3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Extingeix tant l''acció penal com la civil.', false), ('B', 'No extingeix l''acció penal si ja s''havia obert el judici oral.', false), ('C', 'Extingeix l''acció penal, però subsisteix la civil contra els seus hereus i causahavents, que només es pot exercir davant la jurisdicció civil.', true), ('D', 'Extingeix l''acció penal, i l''acció civil s''ha de continuar davant el mateix tribunal penal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
