with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 123.1 de la Llei d''enjudiciament criminal, quin dels documents següents NO figura entre els que s''han de traduir en tot cas a l''investigat o acusat que no parla ni entén el castellà o la llengua oficial en què es desenvolupa l''actuació?', 'L''art. 123.1.d LECrim obliga a traduir en tot cas les resolucions que acordin la presó, l''escrit d''acusació i la sentència; les despeses van a càrrec de l''Administració.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 123.1.d LECrim', 'Deberán ser traducidos, en todo caso, las resoluciones que acuerden la prisión del imputado, el escrito de acusación y la sentencia.', null, 'adfa22ab594510490847c7094543f9af2289099d2a1434be8d434bc4b6a675d0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'adfa22ab594510490847c7094543f9af2289099d2a1434be8d434bc4b6a675d0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les resolucions que acordin la presó de l''investigat.', false), ('B', 'La interlocutòria d''incoació de les diligències prèvies.', true), ('C', 'L''escrit d''acusació.', false), ('D', 'La sentència.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 261 de la Llei d''enjudiciament criminal, quina de les persones següents NO està exempta, amb caràcter general, de l''obligació de denunciar el delicte que presenciï?', 'L''art. 261 LECrim eximeix el cònjuge o persona que hi convisqui en relació anàloga, els ascendents i descendents i els parents col·laterals fins al segon grau inclusivament (els germans); el cosí germà és col·lateral de quart grau. L''excepció no s''aplica a certs delictes greus quan la víctima és menor o persona amb discapacitat necessitada d''especial protecció.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 261 LECrim', '1.º Quien sea cónyuge del delincuente no separado legalmente o de hecho o la persona que conviva con él en análoga relación de afectividad. 2.º Quienes sean ascendientes y descendientes del delincuente y sus parientes colaterales hasta el segundo grado inclusive.', null, '484aa18a72941094b4f37b46f4fec71b5ceecdd7b0f98ccc4592c030181638da', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '484aa18a72941094b4f37b46f4fec71b5ceecdd7b0f98ccc4592c030181638da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un cosí germà del delinqüent.', true), ('B', 'El cònjuge del delinqüent no separat legalment ni de fet.', false), ('C', 'Un descendent del delinqüent.', false), ('D', 'Un germà del delinqüent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 324 de la Llei d''enjudiciament criminal, la investigació judicial s''ha de desenvolupar en un termini màxim de:', 'L''art. 324.1 LECrim fixa dotze mesos des de la incoació i permet pròrrogues successives per períodes iguals o inferiors a sis mesos, mitjançant interlocutòria motivada.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 324.1 LECrim', 'La investigación judicial se desarrollará en un plazo máximo de doce meses desde la incoación de la causa. […] podrá acordar prórrogas sucesivas por periodos iguales o inferiores a seis meses.', null, 'da17216675704ec5c528016d749afc206d25746e1c72f50a99810ba64d90dd48', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'da17216675704ec5c528016d749afc206d25746e1c72f50a99810ba64d90dd48')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos des de la incoació de la causa, prorrogable per una sola vegada per sis mesos més.', false), ('B', 'Divuit mesos des de la incoació de la causa, sense pròrroga possible.', false), ('C', 'Dotze mesos des de la declaració de l''investigat, prorrogable per períodes de dotze mesos.', false), ('D', 'Dotze mesos des de la incoació de la causa, prorrogable per períodes iguals o inferiors a sis mesos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 741 de la Llei d''enjudiciament criminal, el tribunal dicta sentència apreciant les proves practicades en el judici, les raons exposades per l''acusació i la defensa i el que han manifestat els processats:', 'L''art. 741 LECrim recull el principi de lliure valoració de la prova: el tribunal aprecia les proves «según su conciencia».', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 741 LECrim', 'El Tribunal, apreciando según su conciencia las pruebas practicadas en el juicio, las razones expuestas por la acusación y la defensa y lo manifestado por los mismos procesados, dictará sentencia dentro del término fijado en esta Ley.', null, '7d8c209d06c18540f5d7df51102beb83d37a3fd86296ab054ff22ff09c791ba7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7d8c209d06c18540f5d7df51102beb83d37a3fd86296ab054ff22ff09c791ba7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'D''acord amb un sistema de prova taxada fixat per la llei.', false), ('B', 'Només a partir de les proves practicades en la fase d''instrucció.', false), ('C', 'Segons l''informe vinculant del Ministeri Fiscal.', false), ('D', 'Segons la seva consciència.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels delictes següents NO figura en la llista de l''article 795.1.2a de la Llei d''enjudiciament criminal per a l''aplicació del procediment d''enjudiciament ràpid?', 'La llista de l''art. 795.1.2a LECrim inclou, entre d''altres, lesions i coaccions de l''àmbit de l''art. 173.2 CP, furt, robatori, furt i robatori d''ús de vehicles, seguretat del trànsit, danys de l''art. 263, salut pública (art. 368, incís segon), propietat intel·lectual i industrial, allanament de morada i usurpació; no hi figura el trencament de condemna.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 795.1.2a LECrim', 'b) Delitos de hurto. c) Delitos de robo. d) Delitos de hurto y robo de uso de vehículos. e) Delitos contra la seguridad del tráfico. […] i) Delitos de allanamiento de morada del artículo 202 del Código Penal.', null, '105e02b1e6155f6d5f543197c859f84e034515d32cd796d60c6d76b9d11e6bdd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '105e02b1e6155f6d5f543197c859f84e034515d32cd796d60c6d76b9d11e6bdd')
  returning id
), o as (
