)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4 de la Llei d''enjudiciament criminal, si una qüestió prejudicial és determinant de la culpabilitat o de la innocència, el tribunal penal suspèn el procediment fins que la resolgui qui correspongui, i pot fixar perquè les parts acudeixin al jutge civil o contenciós administratiu un termini que no excedeixi de:', 'L''art. 4 LECrim permet fixar un termini màxim de dos mesos; si passa sense que l''interessat acrediti haver-lo utilitzat, el lletrat de l''Administració de justícia aixeca la suspensió.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 4 LECrim', 'el Tribunal de lo criminal suspenderá el procedimiento hasta la resolución de aquélla por quien corresponda; pero puede fijar un plazo, que no exceda de dos meses, para que las partes acudan al Juez o Tribunal civil o contencioso-administrativo competente.', null, '47f524205df997ac30a907169b434e33adb712c91090764fdc40ab1c8eeba334', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '47f524205df997ac30a907169b434e33adb712c91090764fdc40ab1c8eeba334')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos mesos.', true), ('B', 'Un mes.', false), ('C', 'Tres mesos.', false), ('D', 'Sis mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14.7 de la Llei d''enjudiciament criminal, si els fets objecte d''instrucció per la Secció de Violència contra la Infància i l''Adolescència també poden ser coneguts per la Secció de Violència sobre la Dona:', 'L''art. 14.7 LECrim resol el conflicte a favor de la Secció de Violència sobre la Dona.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.7 LECrim', 'En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia le corresponderá en todo caso a la segunda.', null, '3b11c81b64f1ffe460b0d9b0e78e50a61315e44aecc157b2599c49f6908cf30b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3b11c81b64f1ffe460b0d9b0e78e50a61315e44aecc157b2599c49f6908cf30b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La competència correspon en tot cas a la Secció de Violència contra la Infància i l''Adolescència.', false), ('B', 'La competència correspon en tot cas a la Secció de Violència sobre la Dona.', true), ('C', 'La competència la decideix l''Audiència Provincial en cada cas.', false), ('D', 'Les dues seccions instrueixen conjuntament la causa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 de la Llei d''enjudiciament criminal, quan no consta el lloc on s''ha comès el delicte, quin jutge o tribunal té preferència per conèixer de la causa si se suscita una qüestió de competència entre els que hi poden ser competents?', 'L''art. 15 LECrim estableix quatre fòrums (proves materials, lloc de l''aprehensió, residència del reu i qualsevol que n''hagi tingut notícia) i dona preferència per l''ordre en què s''enumeren.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 15 LECrim', '1.º El del término municipal, partido o circunscripción en que se hayan descubierto pruebas materiales del delito. […] Si se suscitase competencia entre estos Jueces o Tribunales, se decidirá dando la preferencia por el orden con que están expresados en los números que preceden.', null, '9dbf9e9d9606a363774f71d8c5670684885785aecdb0c451395a0a29eaa9dbee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9dbf9e9d9606a363774f71d8c5670684885785aecdb0c451395a0a29eaa9dbee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El del lloc on el presumpte reu ha estat detingut.', false), ('B', 'El del terme municipal, partit o circumscripció on s''han descobert proves materials del delicte.', true), ('C', 'El de la residència del presumpte reu.', false), ('D', 'Qualsevol que hagi tingut notícia del delicte en primer lloc.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 103 de la Llei d''enjudiciament criminal, els cònjuges no poden exercir accions penals entre si, EXCEPTE:', 'L''art. 103.1r LECrim admet l''acció penal entre cònjuges per delictes contra la persona de l''altre o dels fills i per bigàmia.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 103 LECrim', '1.º Los cónyuges, a no ser por delito o falta cometidos por el uno contra la persona del otro o la de sus hijos, y por el delito de bigamia.', null, '03cfde5f146004b6788e0c23e5fec669a385f7a8e46d594ce3e8544ccd192162', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03cfde5f146004b6788e0c23e5fec669a385f7a8e46d594ce3e8544ccd192162')
