)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 118.4 de la Llei d''enjudiciament criminal, totes les comunicacions entre l''investigat o encausat i el seu advocat tenen caràcter confidencial. Si aquestes comunicacions s''han captat o intervingut durant l''execució d''alguna diligència, el jutge:', 'L''art. 118.4 LECrim ordena eliminar la gravació o lliurar la correspondència; la regla no s''aplica si hi ha indicis objectius de participació de l''advocat en el fet delictiu, sens perjudici del que disposa la Llei general penitenciària.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 118.4 LECrim', 'Si estas conversaciones o comunicaciones hubieran sido captadas o intervenidas durante la ejecución de alguna de las diligencias reguladas en esta ley, el juez ordenará la eliminación de la grabación o la entrega al destinatario de la correspondencia detenida, dejando constancia de estas circunstancias en las actuaciones.', null, 'f53da67bb070301e5fdb5501848ca0c7cc50b59a3c7088f4dc866fbd508215e5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f53da67bb070301e5fdb5501848ca0c7cc50b59a3c7088f4dc866fbd508215e5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les incorpora a la causa com a prova, si són rellevants per a la investigació.', false), ('B', 'Les remet al Col·legi d''Advocats perquè decideixi sobre la seva validesa.', false), ('C', 'Les declara secretes durant un mes.', false), ('D', 'N''ordena l''eliminació de la gravació o el lliurament al destinatari de la correspondència detinguda, i en deixa constància a les actuacions.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 302 de la Llei d''enjudiciament criminal, el jutge d''instrucció pot declarar el sumari secret, totalment o parcialment, per a totes les parts personades per un temps no superior a un mes. Amb quanta antelació a la conclusió del sumari s''ha d''aixecar necessàriament el secret?', 'L''art. 302 LECrim limita el secret a un mes i obliga a aixecar-lo almenys deu dies abans de la conclusió del sumari.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 302 LECrim', 'El secreto del sumario deberá alzarse necesariamente con al menos diez días de antelación a la conclusión del sumario.', null, '586e48e781f286c448de81e8850df6861d7241cb109a4341f2630597750e1fb5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '586e48e781f286c448de81e8850df6861d7241cb109a4341f2630597750e1fb5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys cinc dies.', false), ('B', 'Almenys quinze dies.', false), ('C', 'Almenys deu dies.', true), ('D', 'Almenys un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 779.1 de la Llei d''enjudiciament criminal, en el procediment abreujat, les víctimes del delicte poden recórrer la interlocutòria de sobreseïment:', 'L''art. 779.1.1a LECrim permet a les víctimes recórrer el sobreseïment en vint dies encara que no siguin part; la comunicació s''entén feta cinc dies després d''enviar-la.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 779.1.1a LECrim', 'Las víctimas podrán recurrir el auto de sobreseimiento dentro del plazo de veinte días aunque no se hubieran mostrado como parte en la causa.', null, 'bf8133b32add1147a5d29afbee8c7b81d985a8dc0b2c63a87ce759f70b514345', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bf8133b32add1147a5d29afbee8c7b81d985a8dc0b2c63a87ce759f70b514345')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins el termini de vint dies, encara que no s''hagin personat com a part en la causa.', true), ('B', 'Dins el termini de cinc dies, només si s''han personat com a part.', false), ('C', 'Dins el termini de deu dies, només si s''han personat com a acusació particular.', false), ('D', 'Dins el termini de tres dies des que el Ministeri Fiscal hi posi el «vist».', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 787.1 de la Llei d''enjudiciament criminal, l''absència injustificada de la persona acusada citada en forma no és causa de suspensió del judici oral si el tribunal estima que hi ha elements suficients per a l''enjudiciament i, a més, la pena més greu sol·licitada no excedeix de:', 'L''art. 787.1 LECrim exigeix que la pena més greu sol·licitada no excedeixi de dos anys de privació de llibertat (sis si és de naturalesa diferent, o multa de qualsevol quantia) i que la suma de penes privatives no passi de cinc anys.', 'pcat_e07_processal_penal', (select id from public.topics where slug = 'pcat-e07-processal-penal'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 787.1 LECrim', 'a) Que la pena más grave solicitada no exceda de dos años de privación de libertad, que no exceda de seis años si se trata de pena de distinta naturaleza o que se trate de pena de multa cualquiera que sea su cuantía o duración. b) Que, en todo caso, tratándose de penas privativas de libertad, la suma total de las penas solicitadas no exceda de cinco años.', null, 'fbc72668ad945596f59cd17b00b00be24f758eb9bd60a56350b5af1a172a8b0c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fbc72668ad945596f59cd17b00b00be24f758eb9bd60a56350b5af1a172a8b0c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc anys de privació de llibertat, o deu anys si és una pena de naturalesa diferent.', false), ('B', 'Un any de privació de llibertat, sigui quina sigui la suma de les penes sol·licitades.', false), ('C', 'Dos anys de privació de llibertat, o sis anys si és una pena de naturalesa diferent, i la suma de penes privatives de llibertat sol·licitades no excedeix de cinc anys.', true), ('D', 'Nou anys de privació de llibertat, que és el límit del procediment abreujat.', false)) as v(label, body, ok)
)
