insert into public.topics (slug, title) values ('pcat-e08-mesures-cautelars', 'Tema 8. Mesures cautelars, detenció, habeas corpus, presó i llibertat provisional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e08-mesures-cautelars' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17.4 de la Constitució espanyola, què ha de determinar la llei en relació amb la presó provisional?', 'L''art. 17.4 CE remet a la llei la regulació del procediment d''habeas corpus i la determinació del termini màxim de durada de la presó provisional.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 17.4 CE', 'Asimismo, por ley se determinará el plazo máximo de duración de la prisión provisional.', null, '972c8c3d9d8311cb7875427702bd2ba37f94276b0f4ae11abb4ffcfdd5c8c1c5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '972c8c3d9d8311cb7875427702bd2ba37f94276b0f4ae11abb4ffcfdd5c8c1c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El termini màxim de durada de la presó provisional.', true), ('B', 'Els centres penitenciaris on s''ha de complir.', false), ('C', 'Les causes d''extinció de la responsabilitat penal.', false), ('D', 'El nombre màxim de pròrrogues de la detenció policial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les garanties següents NO figura a l''article 17.3 de la Constitució espanyola en relació amb la persona detinguda?', 'L''art. 17.3 CE recull el dret a la informació immediata i comprensible, a no declarar i a l''assistència d''advocat; el termini màxim de la detenció preventiva (art. 17.2 CE) és de setanta-dues hores, no de vint-i-quatre.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 17.3 CE', 'Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar. Se garantiza la asistencia de abogado al detenido en las diligencias policiales y judiciales, en los términos que la ley establezca.', null, '29ee5abceae8eea84693c0580eb707e1bcca4524f314ddd692a5e2abbd0c4c6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29ee5abceae8eea84693c0580eb707e1bcca4524f314ddd692a5e2abbd0c4c6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ser informada de forma immediata i comprensible dels seus drets i de les raons de la detenció.', false), ('B', 'No poder ser obligada a declarar.', false), ('C', 'L''assistència d''advocat en les diligències policials i judicials, en els termes que estableixi la llei.', false), ('D', 'Ser posada a disposició judicial en un termini màxim de vint-i-quatre hores.', true)) as v(label, body, ok)
)
