with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 520.1 de la Llei d''enjudiciament criminal, dins dels terminis establerts en la llei i, en tot cas, en quin termini màxim el detingut ha de ser posat en llibertat o a disposició de l''autoritat judicial?', 'La detenció preventiva no pot durar més del temps estrictament necessari per a les averiguacions i, en tot cas, el detingut ha de ser posat en llibertat o a disposició judicial en un màxim de setanta-dues hores (art. 520.1 LECrim, que reprodueix l''art. 17.2 CE).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.1 LECrim', 'Dentro de los plazos establecidos en la presente Ley, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.', null, 'f13f42dcfc59773f2e099a95209a324399d7da1f74625988e478dfe83fc8a860', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f13f42dcfc59773f2e099a95209a324399d7da1f74625988e478dfe83fc8a860')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores.', false), ('B', 'Setanta-dues hores.', true), ('C', 'Quaranta-vuit hores.', false), ('D', 'Cinc dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei d''enjudiciament criminal, el particular, l''autoritat o l''agent de policia judicial que detingui una persona ha de posar-la en llibertat o lliurar-la al jutge més pròxim al lloc de la detenció:', 'L''art. 496 LECrim obliga qui ha practicat la detenció a posar el detingut en llibertat o lliurar-lo al jutge més pròxim dins de les vint-i-quatre hores següents; si la dilació excedeix aquest termini, incorre en responsabilitat penal.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 496 LECrim', 'deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma.', null, '07ab5acc151248ba5d8e68930eba113f3ac417c632cde3ff03df5223cc05d8df', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07ab5acc151248ba5d8e68930eba113f3ac417c632cde3ff03df5223cc05d8df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les vint-i-quatre hores següents a la detenció.', true), ('B', 'Dins de les setanta-dues hores següents a la detenció.', false), ('C', 'Dins de les quaranta-vuit hores següents a la detenció.', false), ('D', 'Immediatament, sense que pugui passar més d''una hora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 490 de la Llei d''enjudiciament criminal, qualsevol persona pot detenir, entre d''altres, les persones següents, EXCEPTE:', 'L''art. 490 LECrim enumera els casos en què qualsevol persona pot detenir. La detenció del processat per delicte amb pena superior a la de presó correccional és una obligació de l''autoritat o agent de policia judicial (art. 492.2), no una facultat de qualsevol persona.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Arts. 490 i 492 LECrim', 'Cualquier persona puede detener: 1.º Al que intentare cometer un delito en el momento de ir a cometerlo. 2.º Al delincuente in fraganti. 3.º Al que se fugare del establecimiento penal en que se halle extinguiendo condena.', null, '690d2714f2203cfd53e58d3784793458cd410492977a31125c96787f348beeed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '690d2714f2203cfd53e58d3784793458cd410492977a31125c96787f348beeed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qui intenti cometre un delicte en el moment d''anar a cometre''l.', false), ('B', 'El delinqüent in fraganti.', false), ('C', 'Qui estigui processat per un delicte que tingui assenyalada una pena superior a la de presó correccional.', true), ('D', 'Qui s''escapi de l''establiment penal on està extingint condemna.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 497 de la Llei d''enjudiciament criminal, el jutge o tribunal de la causa a qui es lliuri un detingut ha d''elevar la detenció a presó, o deixar-la sense efecte, en el termini de:', 'L''art. 497 LECrim fixa setanta-dues hores, comptades des del lliurament del detingut al jutge o tribunal, per elevar la detenció a presó o deixar-la sense efecte.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 497 LECrim', 'elevará la detención a prisión, o la dejará sin efecto, en el término de setenta y dos horas, a contar desde que el detenido le hubiese sido entregado.', null, '959e828d34de7087d59aec970a7ba4819608ac2af3adb6bbf401046114704f46', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '959e828d34de7087d59aec970a7ba4819608ac2af3adb6bbf401046114704f46')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores des que el detingut li hagi estat lliurat.', false), ('B', 'Setanta-dues hores des del moment de la detenció.', false), ('C', 'Deu dies des que el detingut li hagi estat lliurat.', false), ('D', 'Setanta-dues hores des que el detingut li hagi estat lliurat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels drets següents NO figura entre els que, segons l''article 520.2 de la Llei d''enjudiciament criminal, s''han de comunicar a tota persona detinguda o presa?', 'L''art. 520.2 LECrim enumera, entre d''altres, el dret a guardar silenci, a no declarar contra si mateix, a designar advocat, a comunicar la privació de llibertat a un familiar, a intèrpret i a reconeixement pel metge forense. No inclou cap dret a triar el lloc de custòdia.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.2 LECrim', 'a) Derecho a guardar silencio no declarando si no quiere, a no contestar alguna o algunas de las preguntas que le formulen, o a manifestar que sólo declarará ante el juez. […] c) Derecho a designar abogado, sin perjuicio de lo dispuesto en el apartado 1.a) del artículo 527 y a ser asistido por él sin demora injustificada. […] i) Derecho a ser reconocido por el médico forense o su sustituto legal', null, 'c16d6292d8ba921ea8db7d5f812bdd11951299693b742921943eebeb8f653f9d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c16d6292d8ba921ea8db7d5f812bdd11951299693b742921943eebeb8f653f9d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret a guardar silenci o a manifestar que només declararà davant el jutge.', false), ('B', 'El dret a escollir el centre o dependència on ha de quedar sota custòdia.', true), ('C', 'El dret a designar advocat i a ser assistit per ell sense demora injustificada.', false), ('D', 'El dret a ser reconegut pel metge forense o el seu substitut legal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 520.5 de la Llei d''enjudiciament criminal, l''advocat designat per assistir un detingut ha d''acudir al centre de detenció amb la màxima promptitud i sempre dins del termini màxim de:', 'L''art. 520.5 LECrim fixa un màxim de tres hores des de la recepció de l''encàrrec; si l''advocat no compareix, el Col·legi d''Advocats en designa un altre del torn d''ofici.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.5 LECrim', 'El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo.', null, '01526d39c488acb2412e0c9b648d1ce44a80edde60f57034c7c83cc083b82599', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '01526d39c488acb2412e0c9b648d1ce44a80edde60f57034c7c83cc083b82599')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una hora des de la recepció de l''encàrrec.', false), ('B', 'Vuit hores des de la detenció.', false), ('C', 'Tres hores des de la recepció de l''encàrrec.', true), ('D', 'Vint-i-quatre hores des de la detenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 503 de la Llei d''enjudiciament criminal, amb caràcter general, la presó provisional només es pot decretar si consten en la causa fets que presentin caràcters de delicte sancionat amb una pena el màxim de la qual sigui igual o superior a:', 'El primer requisit de l''art. 503.1 LECrim és un delicte castigat amb pena màxima igual o superior a dos anys de presó, o inferior si l''investigat té antecedents penals no cancel·lats per delicte dolós.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 503.1 LECrim', 'Que conste en la causa la existencia de uno o varios hechos que presenten caracteres de delito sancionado con pena cuyo máximo sea igual o superior a dos años de prisión', null, '26ad28fcd0f2373f099bf20cf93f72840715ea6dc06bfd2913948454f187c35e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '26ad28fcd0f2373f099bf20cf93f72840715ea6dc06bfd2913948454f187c35e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any de presó.', false), ('B', 'Tres anys de presó.', false), ('C', 'Dos anys de presó.', true), ('D', 'Cinc anys de presó.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 506 de la Llei d''enjudiciament criminal, la interlocutòria que acordi la presó provisional o en disposi la prolongació ha d''expressar:', 'Les resolucions sobre la situació personal de l''investigat adopten la forma d''interlocutòria, i la que acorda la presó provisional o la prolonga ha d''expressar els motius de necessitat i proporcionalitat respecte dels fins de la mesura (art. 506.1 LECrim).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 506.1 LECrim', 'El auto que acuerde la prisión provisional o disponga su prolongación expresará los motivos por los que la medida se considera necesaria y proporcionada respecto de los fines que justifican su adopción.', null, '14bb03f9f16ba2f0ad3ff2cb2ee93a5bd2266a726209d7f4889325479e6c94c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14bb03f9f16ba2f0ad3ff2cb2ee93a5bd2266a726209d7f4889325479e6c94c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els motius pels quals la mesura es considera necessària i proporcionada respecte dels fins que en justifiquen l''adopció.', true), ('B', 'Només el delicte imputat i la pena que s''hi podria imposar.', false), ('C', 'La data prevista per a la celebració del judici oral.', false), ('D', 'El centre penitenciari on s''ha de complir i el grau de tractament inicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 506.2 de la Llei d''enjudiciament criminal, si la causa s''ha declarat secreta, en la notificació de la interlocutòria de presó provisional no es pot ometre en cap cas:', 'L''art. 506.2 LECrim permet ometre de la còpia notificada els particulars que afectin el secret, però mai la descripció succinta del fet imputat ni els fins de l''art. 503; quan s''aixeca el secret, s''ha de notificar la interlocutòria íntegra.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 506.2 LECrim', 'En ningún caso se omitirá en la notificación una sucinta descripción del hecho imputado y de cuál o cuáles de los fines previstos en el artículo 503 se pretende conseguir con la prisión.', null, '71d0059edc5b2c5a669ac015ed71905f0eb4d1f931dda75f1a5958b8a64bd9ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71d0059edc5b2c5a669ac015ed71905f0eb4d1f931dda75f1a5958b8a64bd9ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La identitat dels testimonis que han declarat contra l''investigat.', false), ('B', 'La totalitat dels fonaments de la interlocutòria, encara que afectin el secret.', false), ('C', 'La durada màxima prevista de la presó provisional.', false), ('D', 'Una descripció succinta del fet imputat i del fi o fins de l''article 503 que es pretenen aconseguir amb la presó.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 504.2 de la Llei d''enjudiciament criminal, la presó provisional acordada per evitar el risc de fuga, si el delicte té assenyalada una pena privativa de llibertat superior a tres anys, no pot excedir, amb caràcter general, de:', 'L''art. 504.2 LECrim limita la presó provisional a un any si la pena és igual o inferior a tres anys i a dos anys si és superior, amb una única pròrroga possible; per evitar l''ocultació de proves, el màxim és de sis mesos (art. 504.3).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 504.2 LECrim', 'su duración no podrá exceder de un año si el delito tuviere señalada pena privativa de libertad igual o inferior a tres años, o de dos años si la pena privativa de libertad señalada para el delito fuera superior a tres años.', null, 'a3e72bacb5bb7dab932866e9de9648d347150b7ba15b388c70a200a150890e85', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a3e72bacb5bb7dab932866e9de9648d347150b7ba15b388c70a200a150890e85')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any.', false), ('B', 'Dos anys.', true), ('C', 'Sis mesos.', false), ('D', 'Quatre anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 509 de la Llei d''enjudiciament criminal, la incomunicació d''un detingut o pres no es pot estendre, amb caràcter general, més enllà de:', 'L''art. 509.2 LECrim limita la incomunicació a cinc dies, prorrogables per un altre termini no superior a cinc dies en els delictes de l''art. 384 bis o comesos de manera organitzada; els menors de setze anys no poden ser objecte de detenció incomunicada.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 509.2 LECrim', 'La incomunicación no podrá extenderse más allá de cinco días.', null, '6b633efcfc5d1e1b1c4b3d5e9808462d9e5b219a2e44e8bea55e30e8620276eb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6b633efcfc5d1e1b1c4b3d5e9808462d9e5b219a2e44e8bea55e30e8620276eb')
  returning id
), o as (
