  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres dies.', false), ('B', 'Deu dies.', false), ('C', 'Setanta-dues hores.', false), ('D', 'Cinc dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 511 de la Llei d''enjudiciament criminal, els directors dels establiments penitenciaris no poden rebre cap persona en condició de pres:', 'Per executar la interlocutòria de presó s''expedeixen dos manaments, un a la policia judicial i un altre al director de l''establiment; sense el manament de presó el director no pot rebre ningú com a pres (art. 511 LECrim).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 511 LECrim', 'Los directores de los establecimientos no recibirán a ninguna persona en condición de preso sin que se les entregue mandamiento de prisión.', null, 'f6327530f6e16f31490c0d98f6f6b521d6f91a301e9453b1c13410f9ad4b933c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f6327530f6e16f31490c0d98f6f6b521d6f91a301e9453b1c13410f9ad4b933c')
  returning id
), o as (
