  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 502.2 de la Llei d''enjudiciament criminal, la presó provisional només s''adoptarà:', 'L''art. 502.2 LECrim configura la presó provisional com a mesura excepcional i subsidiària.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 502.2 LECrim', 'La prisión provisional sólo se adoptará cuando objetivamente sea necesaria, de conformidad con lo establecido en los artículos siguientes, y cuando no existan otras medidas menos gravosas para el derecho a la libertad a través de las cuales puedan alcanzarse los mismos fines que con la prisión provisional.', null, 'e9688c19de91d46bea2f2f0f338558841f9850d9409f16ae071f95ceb1f7c6f1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e9688c19de91d46bea2f2f0f338558841f9850d9409f16ae071f95ceb1f7c6f1')
