  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels fins següents NO figura a l''article 503.1.3r de la Llei d''enjudiciament criminal com a finalitat que pot justificar la presó provisional?', 'L''art. 503.1.3r LECrim enumera tres fins (risc de fuga, protecció de les fonts de prova i protecció de la víctima); l''art. 503.2 hi afegeix el risc de reiteració delictiva. L''alarma social no hi figura.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 503.1.3r LECrim', 'a) Asegurar la presencia del investigado o encausado en el proceso cuando pueda inferirse racionalmente un riesgo de fuga. […] b) Evitar la ocultación, alteración o destrucción de las fuentes de prueba relevantes para el enjuiciamiento en los casos en que exista un peligro fundado y concreto. […] c) Evitar que el investigado o encausado pueda actuar contra bienes jurídicos de la víctima', null, '20c329fb0f7c55bb72b07de6858569d60040d7c864b6fd2c29c7bc4154045200', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '20c329fb0f7c55bb72b07de6858569d60040d7c864b6fd2c29c7bc4154045200')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
