insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 508.1 de la Llei d''enjudiciament criminal, el jutge o tribunal pot acordar que la presó provisional es compleixi en el domicili de l''investigat, amb les mesures de vigilància necessàries:', 'L''art. 508.1 LECrim preveu la presó provisional domiciliària per malaltia quan l''internament entranyi greu perill per a la salut; l''art. 508.2 permet substituir-la per l''ingrés en un centre de deshabituació.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 508.1 LECrim', 'El juez o tribunal podrá acordar que la medida de prisión provisional del investigado o encausado se verifique en su domicilio, con las medidas de vigilancia que resulten necesarias, cuando por razón de enfermedad el internamiento entrañe grave peligro para su salud.', null, '4957f642d7e8bcdbd7c0eac936bccdb1f872f3c93bf5c9cffae43cfe4b5ae8ed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4957f642d7e8bcdbd7c0eac936bccdb1f872f3c93bf5c9cffae43cfe4b5ae8ed')
  returning id
