insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 527.1 de la Llei d''enjudiciament criminal, en els supòsits d''incomunicació, el detingut o pres pot ser privat de determinats drets si ho justifiquen les circumstàncies. Quin dels drets següents NO se li pot restringir?', 'L''art. 527.1.b LECrim permet restringir la comunicació amb les persones amb qui el detingut té dret a fer-ho, «salvo con la autoridad judicial, el Ministerio Fiscal y el Médico Forense».', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 527.1 LECrim', 'b) Comunicarse con todas o alguna de las personas con las que tenga derecho a hacerlo, salvo con la autoridad judicial, el Ministerio Fiscal y el Médico Forense.', null, '4d6cd9e23812b92fcc59cb9048107631ceeabaf3a1268d465ee93c86e87b0bbc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4d6cd9e23812b92fcc59cb9048107631ceeabaf3a1268d465ee93c86e87b0bbc')
  returning id
), o as (
