)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 541 de la Llei d''enjudiciament criminal, quin dels supòsits següents NO és causa de cancel·lació de la fiança?', 'L''art. 541 LECrim cancel·la la fiança quan el fiador ho demana presentant el processat, quan aquest és reduït a presó, quan hi ha sobreseïment ferm, sentència absolutòria ferma o el reu es presenta a complir la condemna, i per mort del processat. La incompareixença porta, en canvi, a fer efectiva la fiança (arts. 534 i 535).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 541 LECrim', '1.º Cuando el fiador lo pidiere, presentando a la vez al procesado. 2.º Cuando éste fuere reducido a prisión. […] 4.º Por muerte del procesado estando pendiente la causa.', null, '3dee9d6ca5dd31273c2004b0f432499dca7ecd421361e74e86919bec23123531', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3dee9d6ca5dd31273c2004b0f432499dca7ecd421361e74e86919bec23123531')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el fiador ho demani presentant alhora el processat.', false), ('B', 'Que el processat no compareixi al primer requeriment judicial.', true), ('C', 'Que el processat sigui reduït a presó.', false), ('D', 'La mort del processat mentre la causa està pendent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 525 de la Llei d''enjudiciament criminal, contra el detingut o pres només es pot adoptar una mesura extraordinària de seguretat:', 'L''art. 525 LECrim limita les mesures extraordinàries de seguretat a la desobediència, la violència, la rebel·lió o l''intent o preparació de fuga, i les vol temporals.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 525 LECrim', 'No se adoptará contra el detenido o preso ninguna medida extraordinaria de seguridad sino en caso de desobediencia, de violencia o de rebelión, o cuando haya intentado o hecho preparativos para fugarse. Esta medida deberá ser temporal, y sólo subsistirá el tiempo estrictamente necesario.', null, 'ab640bd08529927d099be8206aeeea4485174ba15575b3b0d5552db052bdf982', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ab640bd08529927d099be8206aeeea4485174ba15575b3b0d5552db052bdf982')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan ho ordeni el jutge, amb caràcter indefinit.', false), ('B', 'En cas de qualsevol infracció disciplinària, durant un màxim de catorze dies.', false), ('C', 'Quan el detingut estigui incomunicat, durant tota la incomunicació.', false), ('D', 'En cas de desobediència, de violència o de rebel·lió, o quan hagi intentat fugir o hagi fet preparatius per fugir, i només durant el temps estrictament necessari.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 503.1.3r.a de la Llei d''enjudiciament criminal, procedeix acordar la presó provisional per risc de fuga, sense que s''apliqui el límit de pena de dos anys, quan consti que s''han dictat contra l''investigat, per qualsevol òrgan judicial:', 'L''art. 503.1.3r.a LECrim fixa almenys dues requisitòries en els dos anys anteriors i exclou en aquest cas el límit de pena de l''ordinal 1r.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 503.1.3r.a LECrim', 'hubieran sido dictadas al menos dos requisitorias para su llamamiento y busca por cualquier órgano judicial en los dos años anteriores. En estos supuestos no será aplicable el límite que respecto de la pena establece el ordinal 1.º de este apartado.', null, 'd7c69260ca658a72cd07082aa1e916b110dfff5182929a7181474e07b5368ccb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd7c69260ca658a72cd07082aa1e916b110dfff5182929a7181474e07b5368ccb')
