)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 504.2 de la Llei d''enjudiciament criminal, si l''investigat ha estat condemnat i la sentència ha estat recorreguda, la presó provisional es pot prorrogar fins al límit de:', 'L''art. 504.2 LECrim permet, en cas de condemna recorreguda, prorrogar la presó provisional fins a la meitat de la pena efectivament imposada.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 504.2 LECrim', 'Si fuere condenado el investigado o encausado, la prisión provisional podrá prorrogarse hasta el límite de la mitad de la pena efectivamente impuesta en la sentencia, cuando ésta hubiere sido recurrida.', null, '03055aa44db4bfd258d2688c9b4cc383fbe7e8752dacab1d43aae5b1015c702f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03055aa44db4bfd258d2688c9b4cc383fbe7e8752dacab1d43aae5b1015c702f')
