insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 504.6 de la Llei d''enjudiciament criminal, quan la presó provisional acordada excedeix de les dues terceres parts de la seva durada màxima, el jutge o tribunal i el Ministeri Fiscal ho han de comunicar, respectivament:', 'L''art. 504.6 LECrim imposa aquesta comunicació perquè s''imprimeixi la màxima celeritat a les actuacions, que passen a tenir preferència.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 504.6 LECrim', 'Cuando la medida de prisión provisional acordada exceda de las dos terceras partes de su duración máxima, el juez o tribunal que conozca de la causa y el ministerio fiscal comunicarán respectivamente esta circunstancia al presidente de la sala de gobierno y al fiscal-jefe del tribunal correspondiente', null, 'bf0739a781e12bf43aaaa16a8be19c210490c703793a14f2edd3fe6b2602306b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bf0739a781e12bf43aaaa16a8be19c210490c703793a14f2edd3fe6b2602306b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consell General del Poder Judicial i al fiscal general de l''Estat.', false), ('B', 'Al jutge de vigilància penitenciària i al director o directora del centre.', false), ('C', 'Al president de la sala de govern i al fiscal en cap del tribunal corresponent.', true), ('D', 'Al president de l''Audiència Provincial i a l''advocat de l''investigat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 509.2 de la Llei d''enjudiciament criminal, quan la presó s''acorda en una causa per delictes de l''article 384 bis o per altres delictes comesos de manera concertada i organitzada per dues o més persones, la incomunicació:', 'L''art. 509.2 LECrim limita la incomunicació a cinc dies, prorrogables per un altre termini no superior a cinc dies en els casos de l''art. 384 bis o de delinqüència organitzada.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 509.2 LECrim', 'En los casos en que la prisión se acuerde en causa por alguno de los delitos a que se refiere el artículo 384 bis u otros delitos cometidos concertadamente y de forma organizada por dos o más personas, la incomunicación podrá prorrogarse por otro plazo no superior a cinco días.', null, 'e6934848a25160b0b32b59725844cbf716afe7bd8c700dc8df7dd0dcdbbdc889', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e6934848a25160b0b32b59725844cbf716afe7bd8c700dc8df7dd0dcdbbdc889')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot prorrogar per un altre termini no superior a cinc dies.', true), ('B', 'Es pot prorrogar per un altre termini no superior a deu dies.', false), ('C', 'Es pot prorrogar fins a un màxim de tretze dies en total.', false), ('D', 'No es pot prorrogar en cap cas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 520 bis de la Llei d''enjudiciament criminal, la detenció d''una persona com a presumpta partícip d''algun dels delictes de l''article 384 bis es pot prolongar més enllà de les setanta-dues hores fins a un màxim de:', 'L''art. 520 bis.1 LECrim permet prolongar la detenció fins a quaranta-vuit hores més amb sol·licitud motivada dins les primeres quaranta-vuit hores i autorització judicial en les vint-i-quatre hores següents.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520 bis.1 LECrim', 'podrá prolongarse la detención el tiempo necesario para los fines investigadores, hasta un límite máximo de otras cuarenta y ocho horas, siempre que, solicitada tal prórroga mediante comunicación motivada dentro de las primeras cuarenta y ocho horas desde la detención, sea autorizada por el Juez en las veinticuatro horas siguientes.', null, 'b512a89cd6b6d27c955faced7d8bdc20fc329455312b0a5a103c2ec3684d3e4b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b512a89cd6b6d27c955faced7d8bdc20fc329455312b0a5a103c2ec3684d3e4b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Setanta-dues hores més, si l''autoritza el Ministeri Fiscal.', false), ('B', 'Quaranta-vuit hores més, si la pròrroga se sol·licita dins de les primeres quaranta-vuit hores i el jutge l''autoritza en les vint-i-quatre hores següents.', true), ('C', 'Vint-i-quatre hores més, sense necessitat d''autorització judicial.', false), ('D', 'Cinc dies més, si se n''acorda la incomunicació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 527.3 de la Llei d''enjudiciament criminal, amb quina freqüència mínima s''han de fer els reconeixements mèdics al detingut a qui s''ha restringit el dret a comunicar-se amb les persones amb qui té dret a fer-ho?', 'L''art. 527.3 LECrim exigeix almenys dos reconeixements mèdics cada vint-i-quatre hores.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 527.3 LECrim', 'se realizarán con una frecuencia de al menos dos reconocimientos cada veinticuatro horas, según criterio facultativo.', null, '7ea16fb0071f748012d118ffb1cf12f507123381c56dffb24156ad916de11c5a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7ea16fb0071f748012d118ffb1cf12f507123381c56dffb24156ad916de11c5a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys un reconeixement cada setanta-dues hores.', false), ('B', 'Almenys tres reconeixements cada vint-i-quatre hores.', false), ('C', 'Un reconeixement en iniciar-se i un altre en acabar la incomunicació.', false), ('D', 'Almenys dos reconeixements cada vint-i-quatre hores, segons el criteri facultatiu.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 544 ter.7 de la Llei d''enjudiciament criminal, quina vigència temporal tenen les mesures de caràcter civil contingudes en l''ordre de protecció?', 'L''art. 544 ter.7 LECrim fixa trenta dies de vigència; si s''inicia un procés de família, les mesures continuen trenta dies més des de la presentació de la demanda, i el jutge civil les ha de ratificar, modificar o deixar sense efecte.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 544 ter.7 LECrim', 'Las medidas de carácter civil contenidas en la orden de protección tendrán una vigencia temporal de treinta días. Si dentro de este plazo fuese incoado a instancia de la víctima o de su representante legal un proceso de familia ante la jurisdicción civil, las medidas adoptadas permanecerán en vigor durante los treinta días siguientes a la presentación de la demanda.', null, '3a805161f53023f3fde1b5655d3cdc3e403c3f0ef0534de0dd3022a6b7dbe795', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3a805161f53023f3fde1b5655d3cdc3e403c3f0ef0534de0dd3022a6b7dbe795')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seixanta dies, prorrogables per un període igual.', false), ('B', 'Trenta dies, que es mantenen trenta dies més des de la presentació de la demanda si dins d''aquest termini s''incoa un procés de família.', true), ('C', 'Tres mesos, prorrogables fins a sis.', false), ('D', 'Fins que es dicti sentència ferma en el procés penal.', false)) as v(label, body, ok)
)
