insert into public.topics (slug, title) values ('pcat-e08-mesures-cautelars', 'Tema 8. Mesures cautelars, detenció, habeas corpus, presó i llibertat provisional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e08-mesures-cautelars' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 6/1984, reguladora del procediment d''habeas corpus, es consideren persones il·legalment detingudes, entre d''altres:', 'L''art. 1 LOHC considera il·legalment detingudes, entre d''altres, les persones privades de llibertat a qui no es respecten els drets que la Constitució i les lleis processals garanteixen al detingut (lletra d).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 1 LOHC', 'd) Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las leyes procesales garantizan a toda persona detenida.', null, 'cd89b9ccef41c21fd5db75b415d1653ec0eccf5c645966daa024a8f60fa13134', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cd89b9ccef41c21fd5db75b415d1653ec0eccf5c645966daa024a8f60fa13134')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les que compleixen condemna en un centre penitenciari en règim tancat.', false), ('B', 'Les que estan en presó provisional acordada per interlocutòria judicial motivada.', false), ('C', 'Les detingudes per un particular en el moment de cometre un delicte flagrant.', false), ('D', 'Les privades de llibertat a qui no es respecten els drets que la Constitució i les lleis processals garanteixen a tota persona detinguda.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 6/1984, d''habeas corpus, amb caràcter general, qui és competent per conèixer de la sol·licitud d''habeas corpus?', 'L''art. 2 LOHC atribueix la competència al jutge d''instrucció del lloc on es trobi la persona privada de llibertat; si no consta, al del lloc de la detenció i, si no, al del lloc on se n''hagin tingut les darreres notícies.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 2 LOHC', 'Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad; si no constare, el del lugar en que se produzca la detención, y, en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido.', null, '4b2d5c9f25fc8b7230fbd9e38e7e76b55c1b33bb3b39802a7031d8630fd05ce2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b2d5c9f25fc8b7230fbd9e38e7e76b55c1b33bb3b39802a7031d8630fd05ce2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge d''instrucció del lloc on es trobi la persona privada de llibertat.', true), ('B', 'El jutge d''instrucció del lloc on s''hagi comès el delicte.', false), ('C', 'El jutge o jutgessa de vigilància penitenciària.', false), ('D', 'L''Audiència Provincial del lloc on s''hagi produït la detenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 6/1984, d''habeas corpus, si la detenció obeeix a l''aplicació de la llei orgànica que desplega els supòsits de l''article 55.2 de la Constitució, el procediment s''ha de seguir davant:', 'L''art. 2, paràgraf segon, LOHC reserva al Jutge Central d''Instrucció els habeas corpus derivats de l''aplicació de la llei orgànica de l''art. 55.2 CE; en l''àmbit militar és competent el Jutge Togat Militar d''Instrucció.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 2 LOHC', 'Si la detención obedece a la aplicación de la ley orgánica que desarrolla los supuestos previstos en el art. 55.2 de la Constitución, el procedimiento deberá seguirse ante el Juez Central de Instrucción correspondiente.', null, 'c85141dc8f3c3567e850337480cd2982827e2dd9c6e27e35f5453ab20cf22704', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c85141dc8f3c3567e850337480cd2982827e2dd9c6e27e35f5453ab20cf22704')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge d''instrucció del lloc on es trobi el detingut.', false), ('B', 'La Sala Penal de l''Audiència Nacional.', false), ('C', 'El Jutge Togat Militar d''Instrucció.', false), ('D', 'El Jutge Central d''Instrucció corresponent.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la Llei orgànica 6/1984, d''habeas corpus, quina de les persones o institucions següents NO hi figura com a legitimada per instar el procediment?', 'L''art. 3 LOHC legitima el privat de llibertat i els seus familiars o representants, el Ministeri Fiscal, el Defensor del Poble i l''advocat defensor; a més, el jutge competent el pot iniciar d''ofici.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 3 LOHC', 'Podrán instar el procedimiento de “Habeas Corpus” que esta ley establece: […] b) El Ministerio Fiscal. c) El Defensor del Pueblo. d) El abogado defensor del privado de libertad.', null, '4e54672567fbb23e7817cddc3b68e26af16042094df06d6d4d667076ddf4b9eb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e54672567fbb23e7817cddc3b68e26af16042094df06d6d4d667076ddf4b9eb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Ministeri Fiscal.', false), ('B', 'El Defensor del Poble.', false), ('C', 'El director o directora del centre penitenciari.', true), ('D', 'L''advocat defensor del privat de llibertat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 6/1984, d''habeas corpus, el procediment s''inicia, llevat que s''incoï d''ofici:', 'L''art. 4 LOHC permet iniciar el procediment per escrit o compareixença, sense advocat ni procurador preceptius, fent-hi constar les dades del sol·licitant, el lloc de la privació de llibertat i el motiu concret.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 4 LOHC', 'El procedimiento se iniciará, salvo cuando se incoe de oficio, por medio de escrito o comparecencia, no siendo preceptiva la intervención de Abogado ni de Procurador.', null, '223a0b832cdcb9e92367cf970809cb4fdcd9c4bcfd1f09bfdf14b157d5b63704', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '223a0b832cdcb9e92367cf970809cb4fdcd9c4bcfd1f09bfdf14b157d5b63704')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicament per escrit signat per advocat i procurador.', false), ('B', 'Per mitjà d''escrit o compareixença, sense que sigui preceptiva la intervenció d''advocat ni de procurador.', true), ('C', 'Per mitjà de querella presentada davant el jutjat de guàrdia.', false), ('D', 'Per mitjà d''instància adreçada al director del centre on es troba el detingut.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 6/1984, d''habeas corpus, en quin termini el jutge ha de practicar totes les actuacions i dictar la resolució que correspongui?', 'L''art. 7 LOHC fixa vint-i-quatre hores des de la interlocutòria d''incoació per practicar les actuacions (audiència del privat de llibertat, del fiscal i de l''autoritat) i resoldre.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 7 LOHC', 'En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación, los Jueces practicarán todas las actuaciones a que se refiere este artículo y dictarán la resolución que proceda.', null, 'cd2760d53237247f60bb6e144727d8eb3d5b695415c03365d6b846efd6fc4dab', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cd2760d53237247f60bb6e144727d8eb3d5b695415c03365d6b846efd6fc4dab')
  returning id
