with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 5 de la Llei orgànica 6/1984, d''habeas corpus, què ha de fer el funcionari públic que té sota la seva custòdia una persona privada de llibertat que formula una sol·licitud d''habeas corpus?', 'L''art. 5 LOHC obliga l''autoritat governativa, els seus agents i els funcionaris públics a comunicar immediatament la sol·licitud al jutge competent; si no ho fan, el jutge els aperceb, sens perjudici de les responsabilitats penals i disciplinàries.', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 5 LO 6/1984', 'La autoridad gubernativa, agente de la misma o funcionario público, estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», formulada por la persona privada de libertad que se encuentre bajo su custodia.', null, '0a716e30ed5198e17cdbdf77f73f794ed40f4cc23682983f47355c5ffcfe6e70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a716e30ed5198e17cdbdf77f73f794ed40f4cc23682983f47355c5ffcfe6e70')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Traslladar-la al Ministeri Fiscal perquè decideixi si la tramita.', false), ('B', 'Posar-la immediatament en coneixement del jutge competent.', true), ('C', 'Comunicar-la al director o directora del centre en el termini de vint-i-quatre hores.', false), ('D', 'Valorar-ne la procedència abans de remetre-la al jutge.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 de la Llei orgànica 6/1984, d''habeas corpus, si el jutge estima que concorre alguna de les circumstàncies de detenció il·legal, quina de les mesures següents NO pot acordar en l''acte?', 'L''art. 8.2 LOHC preveu la llibertat, la continuació de la privació en un altre establiment o sota una altra custòdia, o la posada immediata a disposició judicial. Per a la persecució dels delictes comesos, el jutge només en dedueix testimoni (art. 9).', 'pcat_e08_mesures_cautelars', (select id from public.topics where slug = 'pcat-e08-mesures-cautelars'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 8.2 LO 6/1984', 'a) La puesta en libertad del privado de ésta, si lo fue ilegalmente. b) Que continúe la situación de privación de libertad de acuerdo con las disposiciones legales aplicables al caso, pero, si lo considerase necesario, en establecimiento distinto, o bajo la custodia de personas distintas a las que hasta entonces la detentaban. c) Que la persona privada de libertad sea puesta inmediatamente a disposición judicial, si ya hubiese transcurrido el plazo legalmente establecido para su detención.', null, 'e140baa17f7d78c0dead0991d375a0808d6d9dee4b3d256d15eda8721314520b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e140baa17f7d78c0dead0991d375a0808d6d9dee4b3d256d15eda8721314520b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La condemna en ferm de l''autoritat que va practicar la detenció.', true), ('B', 'La posada en llibertat de la persona privada de llibertat, si ho va ser il·legalment.', false), ('C', 'Que continuï la privació de llibertat d''acord amb les disposicions legals, però en un establiment diferent o sota la custòdia de persones diferents.', false), ('D', 'Que la persona privada de llibertat sigui posada immediatament a disposició judicial, si ja ha passat el termini legal de detenció.', false)) as v(label, body, ok)
)
