with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25.2 de la Constitució espanyola, cap a on han d''estar orientades les penes privatives de llibertat i les mesures de seguretat?', 'L''art. 25.2 CE estableix que les penes privatives de llibertat i les mesures de seguretat estaran orientades cap a la reeducació i la reinserció social i que no podran consistir en treballs forçats.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'Las penas privativas de libertad y las medidas de seguridad estarán orientadas hacia la reeducación y reinserción social y no podrán consistir en trabajos forzados.', null, '00f4a2e366ecc4e31f9bce48986d5b5a492a2ff6eee8fda68860ab75ea5ddb02', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '00f4a2e366ecc4e31f9bce48986d5b5a492a2ff6eee8fda68860ab75ea5ddb02')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap a la retenció i la custòdia dels condemnats.', false), ('B', 'Cap a la prevenció general i la retribució del delicte.', false), ('C', 'Cap a la reeducació i la reinserció social.', true), ('D', 'Cap a la reparació del dany causat a la víctima.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
