with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 25.2 de la Constitució espanyola, el condemnat a pena de presó que l''estigui complint gaudirà dels drets fonamentals del capítol II, a excepció dels que es vegin expressament limitats per:', 'Segons l''art. 25.2 CE, els drets fonamentals del condemnat només es poden limitar pel contingut de la decisió condemnatòria (fallo condenatorio), el sentit de la pena i la llei penitenciària.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'El condenado a pena de prisión que estuviere cumpliendo la misma gozará de los derechos fundamentales de este Capítulo, a excepción de los que se vean expresamente limitados por el contenido del fallo condenatorio, el sentido de la pena y la ley penitenciaria.', null, '4b5ebf7a2a43abc6eb1097b8f0f05234ddc34d76869d3c4606a30adab0cc51ad', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4b5ebf7a2a43abc6eb1097b8f0f05234ddc34d76869d3c4606a30adab0cc51ad')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El contingut de la decisió condemnatòria, el sentit de la pena i la llei penitenciària.', true), ('B', 'El contingut de la decisió condemnatòria, el Reglament penitenciari i les normes de règim interior.', false), ('C', 'El sentit de la pena, les ordres del director o directora del centre i la llei penitenciària.', false), ('D', 'Les resolucions del jutge de vigilància penitenciària i les circulars del centre directiu.', false)) as v(label, body, ok)
)
