with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25.2 de la Constitució espanyola, a què tindrà dret en tot cas el condemnat a pena de presó que l''estigui complint?', 'L''últim incís de l''art. 25.2 CE reconeix «en tot cas» el dret a un treball remunerat, als beneficis de la Seguretat Social, a l''accés a la cultura i al desenvolupament integral de la personalitat.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 25.2 CE', 'En todo caso, tendrá derecho a un trabajo remunerado y a los beneficios correspondientes de la Seguridad Social, así como al acceso a la cultura y al desarrollo integral de su personalidad.', null, '043e8894d1c6f9235a15ebdc2c6e0eb9ddfe464070d0e87bc8d2fd0829a8b68c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '043e8894d1c6f9235a15ebdc2c6e0eb9ddfe464070d0e87bc8d2fd0829a8b68c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A un treball remunerat, sempre que ho permetin les disponibilitats pressupostàries de l''Administració penitenciària.', false), ('B', 'A la reducció de la condemna pel treball fet i a l''accés a la cultura.', false), ('C', 'A un permís ordinari de sortida anual i als beneficis de la Seguretat Social.', false), ('D', 'A un treball remunerat i als beneficis corresponents de la Seguretat Social, així com a l''accés a la cultura i al desenvolupament integral de la seva personalitat.', true)) as v(label, body, ok)
)
