with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el preàmbul de la Circular 2/2011, sobre el Codi ètic dels professionals de l''execució penal a Catalunya, quin és el primer instrument normatiu internacional que s''hi cita en aquesta matèria?', 'El preàmbul (apartat II) cita en primer lloc la Declaració Universal dels Drets Humans, de 10 de desembre de 1948 [Resolució de l''Assemblea General de les Nacions Unides 217 A (iii)].', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Preàmbul II Circular 2/2011', 'És important citar, quant als instruments normatius que incideixen en aquesta matèria, en primer lloc, la Declaració Universal dels Drets Humans, de 10 de desembre de 1948', null, '71fe4ff3e4fab467c4db9ef22129ea6d879867b9c9ad806a9c74ee7da4e0c8b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71fe4ff3e4fab467c4db9ef22129ea6d879867b9c9ad806a9c74ee7da4e0c8b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
