with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A més de la seva finalitat primordial, segons l''article 1 de la LOGP, què tenen igualment al seu càrrec les institucions penitenciàries?', 'El segon paràgraf de l''art. 1 LOGP afegeix que les institucions penitenciàries tenen a càrrec seu una tasca assistencial i d''ajuda per a interns i alliberats.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 1 LOGP', 'Igualmente tienen a su cargo una labor asistencial y de ayuda para internos y liberados.', null, 'b071574ae911b1507b553ef215df8989a4a229a6598aec534fa580debd68bdde', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b071574ae911b1507b553ef215df8989a4a229a6598aec534fa580debd68bdde')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La vigilància de les persones en llibertat condicional.', false), ('B', 'La protecció i tutela dels menors infractors.', false), ('C', 'Una tasca assistencial i d''ajuda per a interns i alliberats.', true), ('D', 'L''execució de les penes de multa i de treballs en benefici de la comunitat.', false)) as v(label, body, ok)
)
