with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 5 de la LOGP, quin principi ha de presidir el règim penitenciari dels preventius?', 'L''art. 5 LOGP diu que el règim de presó preventiva té per objecte retenir l''intern a disposició de l''autoritat judicial i que l''ha de presidir el principi de presumpció d''innocència.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 5 LOGP', 'El régimen de prisión preventiva tiene por objeto retener al interno a disposición de la autoridad judicial. El principio de la presunción de inocencia presidirá el régimen penitenciario de los preventivos.', null, 'd09f580dc5d7116366d70b255302475ba7611de9c69f72608ec84ac78a719bce', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd09f580dc5d7116366d70b255302475ba7611de9c69f72608ec84ac78a719bce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El principi d''individualització científica.', false), ('B', 'El principi de presumpció d''innocència.', true), ('C', 'El principi de legalitat.', false), ('D', 'El principi d''oportunitat.', false)) as v(label, body, ok)
)
