  select 'Segons l''article 3 de la LOGP, l''Administració penitenciària vetllarà per:', 'L''art. 3, apartat quatre, LOGP imposa a l''Administració penitenciària el deure de vetllar per la vida, la integritat i la salut dels interns.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.4 LOGP', 'La Administración penitenciaria velará por la vida, integridad y salud de los internos.', null, '7660f5c5015d36f7ea74090bb5db8983bb19a37682990844fde5ec688ae9b253', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7660f5c5015d36f7ea74090bb5db8983bb19a37682990844fde5ec688ae9b253')
