with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.1 de la LOGP, les penes privatives de llibertat s''executen segons el sistema:', 'L''art. 72.1 LOGP recull el sistema d''individualització científica, separat en graus, l''últim dels quals és el de llibertat condicional.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.1 LOGP', 'Las penas privativas de libertad se ejecutarán según el sistema de individualización científica, separado en grados, el último de los cuales será el de libertad condicional, conforme determina el Código Penal.', null, '0584be821e550e4831d33452fdef893a67dc5ea54e55dc6fc2085f31101616be', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0584be821e550e4831d33452fdef893a67dc5ea54e55dc6fc2085f31101616be')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
