with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LOGP, els interns poden exercir els drets civils, polítics, socials, econòmics i culturals:', 'L''art. 3, apartat u, LOGP reconeix l''exercici de tots aquests drets, inclòs el sufragi, amb el límit de la incompatibilitat amb l''objecte de la detenció o el compliment de la condemna.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.1 LOGP', 'Los internos podrán ejercitar los derechos civiles, políticos, sociales, económicos y culturales, sin exclusión del derecho de sufragio, salvo que fuesen incompatibles con el objeto de su detención o el cumplimiento de la condena.', null, '45cb3d3e66e0c7d98b704b5599de5664537bf2e5bb3a85eb3bb3bc193f0ed85b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '45cb3d3e66e0c7d98b704b5599de5664537bf2e5bb3a85eb3bb3bc193f0ed85b')
  returning id
), o as (
