insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 de la LOGP, en els establiments de preventius també es poden complir penes i mesures penals privatives de llibertat quan l''internament efectiu pendent no excedeixi de:', 'L''art. 8.1 LOGP destina els establiments de preventius a la retenció i custòdia de detinguts i presos, i hi admet el compliment de penes amb un internament efectiu pendent no superior a sis mesos.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 8.1 LOGP', 'También podrán cumplirse penas y medidas penales privativas de libertad cuando el internamiento efectivo pendiente no exceda de seis meses.', null, '298df306a43ba855edc4bef62e4b4d99169310871cc946f592a34d7b9dc1adef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '298df306a43ba855edc4bef62e4b4d99169310871cc946f592a34d7b9dc1adef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos.', true), ('B', 'Un any.', false), ('C', 'Tres mesos.', false), ('D', 'Dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 9.2 de la LOGP, a l''efecte de complir separadament dels adults, es consideren joves les persones que no hagin complert:', 'L''art. 9.2 LOGP fixa el límit en 21 anys i permet excepcionalment, segons la personalitat de l''intern, la permanència fins als 25.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 9.2 LOGP', 'se entiende por jóvenes las personas de uno u otro sexo que no hayan cumplido los veintiún años. Excepcionalmente, y teniendo en cuenta la personalidad del interno, podrán permanecer en centros destinados a jóvenes quienes, habiendo cumplido veintiún años, no hayan alcanzado los veinticinco.', null, '5ae48a30f26106f54876739223b06c95a1675f8775d082ea31c087556947d7d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5ae48a30f26106f54876739223b06c95a1675f8775d082ea31c087556947d7d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Divuit anys, i excepcionalment fins als vint-i-un.', false), ('B', 'Vint-i-cinc anys, sense excepcions.', false), ('C', 'Vint-i-un anys, i excepcionalment fins als trenta.', false), ('D', 'Vint-i-un anys, i excepcionalment poden romandre en centres de joves els qui, havent-los complert, no hagin arribat als vint-i-cinc.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10.1 de la LOGP, els establiments de compliment de règim tancat o departaments especials són per als penats:', 'L''art. 10.1 LOGP exigeix perillositat extrema o inadaptació als règims ordinari i obert, apreciades per causes objectives en resolució motivada.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 10.1 LOGP', 'existirán establecimientos de cumplimiento de régimen cerrado o departamentos especiales para los penados calificados de peligrosidad extrema o para casos de inadaptación a los regímenes ordinario y abierto, apreciados por causas objetivas en resolución motivada', null, '5a8e2a4f5ea26ffeee7c5088a9618223d33c79d5f0928856235c4d910c980904', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a8e2a4f5ea26ffeee7c5088a9618223d33c79d5f0928856235c4d910c980904')
  returning id
