)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels centres següents NO és un tipus d''establiment especial segons l''article 11 de la LOGP?', 'L''art. 11 LOGP defineix els establiments especials com aquells en què preval el caràcter assistencial: hospitalaris, psiquiàtrics i de rehabilitació social. El règim obert és una modalitat dels establiments de compliment (art. 9 LOGP).', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 11 LOGP', 'Los establecimientos especiales son aquellos en los que prevalece el carácter asistencial y serán de los siguientes tipos: a) Centros hospitalarios. b) Centros psiquiátricos. c) Centros de rehabilitación social, para la ejecución de medidas penales, de conformidad con la legislación vigente en esta materia.', null, '979605b41922774aca1b7630a920378474a9b0a70a8031b7edaa8cffde661553', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '979605b41922774aca1b7630a920378474a9b0a70a8031b7edaa8cffde661553')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Centres hospitalaris.', false), ('B', 'Centres psiquiàtrics.', false), ('C', 'Centres de rehabilitació social, per a l''execució de mesures penals.', false), ('D', 'Centres de règim obert.', true)) as v(label, body, ok)
)
