  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 12 de la LOGP, els establiments penitenciaris no haurien d''acollir més de:', 'L''art. 12.2 LOGP limita a 350 els interns per unitat; l''art. 12.1 vol que cada àrea territorial tingui prou establiments per evitar el desarrelament social dels penats.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 12.2 LOGP', 'Los establecimientos penitenciarios no deberán acoger más de trescientos cincuenta internos por unidad.', null, 'bc1c656fc4736e4cdbcbde7d35a3179ac0ad70be9fda218668249cf9cd342ffe', false
