  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.2 de la LOGP, quina de les afirmacions següents NO és correcta?', 'L''art. 72.2 LOGP vincula el segon grau al règim ordinari, el tercer al règim obert i el primer al règim tancat (art. 10.1 LOGP).', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.2 LOGP', 'Los grados segundo y tercero se cumplirán respectivamente en establecimientos de régimen ordinario y de régimen abierto. Los clasificados en primer grado serán destinados a los establecimientos de régimen cerrado', null, 'a9e26d136c0d824328f1055ca8dea3e46e30729e2fe36f48ed4023373408295f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a9e26d136c0d824328f1055ca8dea3e46e30729e2fe36f48ed4023373408295f')
