insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.4 de la LOGP, quan un intern, per l''evolució del seu tractament, es fa mereixedor de la progressió:', 'L''art. 72.4 LOGP prohibeix mantenir un intern en un grau inferior quan la seva evolució justifica la progressió.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.4 LOGP', 'En ningún caso se mantendrá a un interno en un grado inferior cuando por la evolución de su tratamiento se haga merecedor a su progresión.', null, '33357aefd8a03c29030077f12e9ebb9b6272343be5b6246bfb782682b73ddc93', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '33357aefd8a03c29030077f12e9ebb9b6272343be5b6246bfb782682b73ddc93')
  returning id
), o as (
