)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 79 de la LOGP, a qui correspon la direcció, l''organització i la inspecció de les institucions penitenciàries, llevat de les comunitats autònomes que hagin assumit en els seus estatuts l''execució de la legislació penitenciària?', 'L''art. 79 LOGP atribueix aquestes funcions a la Direcció General d''Institucions Penitenciàries, amb l''excepció de les comunitats autònomes que han assumit l''execució de la legislació penitenciària, com Catalunya.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 79 LOGP', 'Corresponde a la Dirección General de Instituciones Penitenciarias del Ministerio de Justicia la dirección, organización e inspección de las instituciones que se regulan en la presente Ley, salvo respecto de las Comunidades Autónomas que hayan asumido en sus respectivos Estatutos la ejecución de la legislación penitenciaria y consiguiente gestión de la actividad penitenciaria.', 'El text consolidat de l''art. 79 LOGP encara diu «del Ministerio de Justicia»; a l''Administració General de l''Estat aquesta direcció general depèn actualment del Ministeri de l''Interior. La pregunta no hi entra, però convé revisar-ne l''explicació.', '9145576d58795b63b74ec73302ddc2dc2f88d6d15d0d8992600d877aeb7aa4b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9145576d58795b63b74ec73302ddc2dc2f88d6d15d0d8992600d877aeb7aa4b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consell General del Poder Judicial.', false), ('B', 'A la Direcció General d''Institucions Penitenciàries.', true), ('C', 'Als jutges de vigilància penitenciària.', false), ('D', 'A la Fiscalia General de l''Estat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels serveis següents NO figura en l''enumeració de l''article 13 de la LOGP sobre les dependències amb què han de comptar els establiments penitenciaris?', 'L''art. 13 LOGP enumera dormitoris individuals, infermeria, escoles, biblioteques, instal·lacions esportives i recreatives, tallers, patis, perruqueria, cuina, menjador, locutoris individualitzats, departament d''informació a l''exterior i sales annexes de relacions familiars, entre d''altres.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 13 LOGP', 'Los establecimientos penitenciarios deberán contar en el conjunto de sus dependencias con servicios idóneos de dormitorios individuales, enfermería, escuelas, bibliotecas, instalaciones deportivas y recreativas, talleres, patios, peluquería, cocina, comedor, locutorios individualizados, departamento de información al exterior, salas anejas de relaciones familiares', null, 'b62820fb80028ece41b7052397481625158e6ffa92575a6a09d4623316452d05', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b62820fb80028ece41b7052397481625158e6ffa92575a6a09d4623316452d05')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Habitatges per als funcionaris del centre.', true), ('B', 'Dormitoris individuals i infermeria.', false), ('C', 'Escoles, biblioteques i instal·lacions esportives i recreatives.', false), ('D', 'Locutoris individualitzats i sales annexes de relacions familiars.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10.2 de la LOGP, els interns preventius en què concorrin les circumstàncies de perillositat extrema o d''inadaptació poden ser destinats als establiments de règim tancat o departaments especials:', 'L''art. 10.2 LOGP permet aquest destí per als preventius amb caràcter excepcional, amb absoluta separació dels penats i donant-ne compte a l''autoritat judicial; la inadaptació es refereix al règim dels establiments de preventius.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 10.2 LOGP', 'También podrán ser destinados a estos establecimientos o departamentos especiales con carácter de excepción y absoluta separación de los penados, dando cuenta a la autoridad judicial correspondiente, aquellos internos preventivos en los que concurran las circunstancias expresadas en el número anterior', null, '9121db7f0ef1a44e1839a225bea93755cb1fc4d312a65869b7295e682ccfe603', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9121db7f0ef1a44e1839a225bea93755cb1fc4d312a65869b7295e682ccfe603')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En les mateixes condicions que els penats i sense necessitat de comunicar-ho a ningú.', false), ('B', 'Amb caràcter d''excepció i absoluta separació dels penats, donant-ne compte a l''autoritat judicial corresponent.', true), ('C', 'Només amb l''autorització prèvia del jutge de vigilància penitenciària.', false), ('D', 'En cap cas, perquè el règim tancat és exclusiu dels penats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.3 de la LOGP, si de l''observació i la classificació d''un intern resulta que està en condicions per a això, pot ser situat inicialment en grau superior:', 'L''art. 72.3 LOGP admet la classificació inicial en un grau superior sense passar pels anteriors, excepte la llibertat condicional.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.3 LOGP', 'Siempre que de la observación y clasificación correspondiente de un interno resulte estar en condiciones para ello, podrá ser situado inicialmente en grado superior, salvo el de libertad condicional, sin tener que pasar necesariamente por los que le preceden.', null, '05838e22c597be5dea406867f9b285524492db2f3504dd2cf5597234f38f2313', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '05838e22c597be5dea406867f9b285524492db2f3504dd2cf5597234f38f2313')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inclòs el de llibertat condicional, sense haver de passar pels anteriors.', false), ('B', 'Només després d''haver passat sis mesos en segon grau.', false), ('C', 'Només si ha complert una quarta part de la condemna.', false), ('D', 'Llevat del de llibertat condicional, sense haver de passar necessàriament pels que el precedeixen.', true)) as v(label, body, ok)
)
