insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 23/2014, de 20 de noviembre, de reconocimiento mutuo de resoluciones penales en la Unión Europea (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e09-marc-sistema-penitenciari', 'Tema 9. Marc legal i principis del sistema penitenciari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e09-marc-sistema-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la Llei 23/2014, de reconeixement mutu de resolucions penals a la Unió Europea, quin dels següents NO és un dels instruments de reconeixement mutu que regula?', 'L''art. 2.2 de la Llei 23/2014 enumera, entre d''altres, l''ordre europea de detenció i lliurament, la resolució que imposa una pena o mesura privativa de llibertat, la de llibertat vigilada i l''ordre europea de protecció. L''extradició no hi figura.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 2.2 Llei 23/2014', 'b) La resolución por la que se impone una pena o medida privativa de libertad. c) La resolución de libertad vigilada. […] e) La orden europea de protección.', null, 'c386bd877f6f2044200ae4b8680b673a2edd60996283dd1665dd807eaccb9b6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c386bd877f6f2044200ae4b8680b673a2edd60996283dd1665dd807eaccb9b6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La resolució per la qual s''imposa una pena o mesura privativa de llibertat.', false), ('B', 'La resolució d''extradició a un Estat tercer.', true), ('C', 'La resolució de llibertat vigilada.', false), ('D', 'L''ordre europea de protecció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 64 de la Llei 23/2014, quines són les autoritats competents a Espanya per transmetre a un altre Estat membre una resolució per la qual s''imposa una pena privativa de llibertat, quan ja s''ha iniciat el compliment de la condemna?', 'L''art. 64.1 atribueix la transmissió als jutges de vigilància penitenciària (i als jutges de menors per a mesures de menors). Si no s''ha iniciat el compliment, és competent el tribunal que va dictar la sentència en primera instància.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 64.1 Llei 23/2014', 'Son autoridades competentes para la transmisión de una resolución por la que se impone una pena o medida privativa de libertad los Jueces de Vigilancia Penitenciaria', null, 'ddc90a4f776794be60fe29ab3a79550b52434414d1b5c3e220c69e6270401f5d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ddc90a4f776794be60fe29ab3a79550b52434414d1b5c3e220c69e6270401f5d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge central penal.', false), ('B', 'El Ministeri de Justícia, com a autoritat central.', false), ('C', 'El centre directiu de l''Administració penitenciària.', false), ('D', 'Els jutges de vigilància penitenciària.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 64.2 de la Llei 23/2014, quan un altre Estat membre transmet a Espanya una sentència que imposa una pena privativa de llibertat a un adult, qui és competent per reconèixer-la i acordar-ne l''execució?', 'L''art. 64.2 atribueix el reconeixement i l''acord d''execució al jutge central penal. Després, la portarà a terme el jutge central de vigilància penitenciària.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 64.2 Llei 23/2014', 'La autoridad competente para reconocer y acordar la ejecución de una resolución por la que se impone una pena o medida privativa de libertad será el Juez Central de lo Penal. Para llevar a cabo la ejecución de la misma, será competente el Juez Central de Vigilancia Penitenciaria.', null, '5c21324b217ff4368fe6d1241be94d24b3c39a3c5d2219692c05f348601ef557', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5c21324b217ff4368fe6d1241be94d24b3c39a3c5d2219692c05f348601ef557')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge central penal.', true), ('B', 'El jutge central de vigilància penitenciària.', false), ('C', 'El jutge de vigilància penitenciària del lloc de residència del condemnat.', false), ('D', 'La Sala Penal del Tribunal Suprem.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 67.2 de la Llei 23/2014, en quin dels supòsits següents no cal el consentiment del condemnat per transmetre la resolució que li imposa una pena privativa de llibertat?', 'L''art. 67.2 c) dispensa del consentiment quan l''Estat d''execució és aquell al qual el condemnat s''ha fugat o ha tornat davant el procés penal obert a Espanya o per haver-hi estat condemnat. Els altres supòsits no hi figuren.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 67.2 Llei 23/2014', 'c) El Estado miembro al que el condenado se haya fugado o haya regresado ante el proceso penal abierto contra él en España o por haber sido condenado en España.', null, '21a954df0467349bad42c3c9c715558407be4dbcd45b857b85458f4191772ee5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '21a954df0467349bad42c3c9c715558407be4dbcd45b857b85458f4191772ee5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan l''Estat d''execució sigui qualsevol Estat membre on visqui algun familiar del condemnat.', false), ('B', 'Quan l''Estat d''execució sigui l''Estat membre que hagi sol·licitat la transmissió.', false), ('C', 'Quan l''Estat d''execució sigui l''Estat membre al qual el condemnat s''hagi fugat davant el procés penal obert contra ell a Espanya.', true), ('D', 'Quan la pena pendent de compliment sigui superior a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 23/2014, quan l''Estat d''execució accepta executar la resolució i el condemnat es troba a Espanya, en quin termini màxim s''ha de fer efectiu el trasllat?', 'L''art. 73.2 fixa un màxim de trenta dies. Si per circumstàncies imprevistes no és possible, s''acorda una nova data i el trasllat s''ha de fer en un màxim de deu dies des d''aquesta nova data.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 73.2 Llei 23/2014', 'El plazo para hacer efectivo este traslado no podrá superar los treinta días desde la adopción por el Estado de ejecución de la resolución firme sobre el reconocimiento y la ejecución de la resolución por la que se impone una pena o medida privativa de libertad.', null, 'c5236965ae194b4a07fd483d0cc81a7d0bcd43f1e69e1fb93e3914d4819762d9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c5236965ae194b4a07fd483d0cc81a7d0bcd43f1e69e1fb93e3914d4819762d9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies des que l''Estat d''execució adopta la resolució ferma sobre el reconeixement i l''execució.', false), ('B', 'Trenta dies des que l''Estat d''execució adopta la resolució ferma sobre el reconeixement i l''execució.', true), ('C', 'Seixanta dies des de la notificació de l''acte de transmissió al condemnat.', false), ('D', 'Noranta dies des de la recepció del certificat per l''Estat d''execució.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 85.1 de la Llei 23/2014, el jutge central penal ha de denegar el reconeixement i l''execució d''una resolució que imposa una pena privativa de llibertat quan, en el moment de rebre-la, la part de la condemna que queda per complir és inferior a:', 'L''art. 85.1 b) preveu la denegació quan la part de condemna pendent és inferior a sis mesos.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 85.1 Llei 23/2014', 'b) Cuando la autoridad judicial española competente constate que, en el momento de recibir la resolución condenatoria, la parte de la condena que queda por cumplir es inferior a seis meses.', null, '57fbb919b1e2d308672e6be9a590da1d4106d5d68a4edfdc6ea1ab4cf750235f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '57fbb919b1e2d308672e6be9a590da1d4106d5d68a4edfdc6ea1ab4cf750235f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos.', false), ('B', 'Un any.', false), ('C', 'Dos anys.', false), ('D', 'Sis mesos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les mesures següents NO figura entre les mesures de llibertat vigilada susceptibles de transmissió i execució en un altre Estat membre segons l''article 94 de la Llei 23/2014?', 'L''art. 94 enumera mesures no privatives de llibertat (comunicar canvis de domicili, prohibicions d''entrada, treballs en benefici de la comunitat, tractament terapèutic, etc.). L''internament en un centre penitenciari no hi figura.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 94 Llei 23/2014', 'a) La obligación de la persona condenada de comunicar a una autoridad específica todo cambio de domicilio o lugar de trabajo. […] i) La obligación de realizar trabajos en beneficio de la comunidad. […] k) La obligación de someterse a un tratamiento terapéutico o de deshabituación.', null, 'b4e7dc8a78a6188de425644a57affd09259be197345e8b2b15b39a204e3253b8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b4e7dc8a78a6188de425644a57affd09259be197345e8b2b15b39a204e3253b8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''obligació de comunicar a una autoritat específica tot canvi de domicili o de lloc de treball.', false), ('B', 'L''obligació de fer treballs en benefici de la comunitat.', false), ('C', 'L''internament en un centre penitenciari en règim obert.', true), ('D', 'L''obligació de sotmetre''s a un tractament terapèutic o de deshabituació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1 de la Llei 23/2014, de reconeixement mutu de resolucions penals a la Unió Europea, en aplicació de quin principi les autoritats judicials espanyoles poden transmetre a un altre Estat membre les resolucions que regula la Llei perquè les reconegui i executi?', 'L''art. 1 Llei 23/2014 fonamenta la transmissió i l''execució de resolucions en el principi de reconeixement mutu, dins l''espai de llibertat, seguretat i justícia de la UE.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 1 Llei 23/2014', 'En aplicación del principio de reconocimiento mutuo de resoluciones penales en el espacio de libertad, seguridad y justicia de la Unión Europea, las autoridades judiciales españolas que dicten una orden o resolución incluida dentro de la regulación de esta Ley, podrán transmitirla a otro Estado miembro para su reconocimiento y ejecución.', null, '9cf909e0b86ade2823223bba5b681be1e382f7dc2f30d2d1ac5b72bb541587c5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9cf909e0b86ade2823223bba5b681be1e382f7dc2f30d2d1ac5b72bb541587c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El principi de reconeixement mutu de resolucions penals en l''espai de llibertat, seguretat i justícia de la Unió Europea.', true), ('B', 'El principi de doble incriminació en tots els casos.', false), ('C', 'El principi de reciprocitat diplomàtica entre estats.', false), ('D', 'El principi d''extraterritorialitat de la llei penal espanyola.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 66.1 de la Llei 23/2014, quin dels requisits següents NO s''exigeix per transmetre a un altre Estat membre una resolució que imposa una pena privativa de llibertat?', 'L''art. 66.1 Llei 23/2014 exigeix la presència del condemnat a Espanya o a l''Estat d''execució, la finalitat de reinserció i el consentiment (llevat dels casos de l''art. 67.2); no exigeix haver complert cap part de la pena.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 66.1 Llei 23/2014', 'a) Que el condenado se encuentre en España o en el Estado de ejecución. b) Que la autoridad judicial española considere que la ejecución de la condena por el Estado de ejecución contribuirá a alcanzar el objetivo de facilitar la reinserción social del condenado, después de haber consultado al Estado de ejecución, cuando corresponda. c) Que medie el consentimiento del condenado, salvo que el mismo no sea necesario, en los términos previstos en el artículo siguiente.', null, '26e75bb4d4fbd9be192d28d7033d4628806299bbcba265bb9b164049d92a8458', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '26e75bb4d4fbd9be192d28d7033d4628806299bbcba265bb9b164049d92a8458')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el condemnat hagi complert almenys la meitat de la condemna a Espanya.', true), ('B', 'Que el condemnat es trobi a Espanya o a l''Estat d''execució.', false), ('C', 'Que l''autoritat judicial espanyola consideri que l''execució a l''Estat d''execució contribuirà a facilitar la reinserció social del condemnat.', false), ('D', 'Que hi hagi el consentiment del condemnat, llevat que no sigui necessari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65.1 de la Llei 23/2014, les sol·licituds de l''autoritat competent de l''Estat d''execució o de la persona condemnada perquè es transmeti una resolució que imposa una pena privativa de llibertat:', 'L''art. 65.1 Llei 23/2014 permet la transmissió d''ofici o a sol·licitud de l''Estat d''execució o del condemnat, però aquestes sol·licituds no obliguen l''autoritat judicial espanyola.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 65.1 Llei 23/2014', 'Las solicitudes de la autoridad competente del Estado de ejecución y de la persona condenada no obligarán a la autoridad judicial española competente a la transmisión de la resolución.', null, 'd8c47de90ce919cb0d23c2894ec6beb479a6a58d3ebc1dc18746fce6b3f55424', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd8c47de90ce919cb0d23c2894ec6beb479a6a58d3ebc1dc18746fce6b3f55424')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obliguen l''autoritat judicial espanyola a transmetre-la en el termini de trenta dies.', false), ('B', 'No obliguen l''autoritat judicial espanyola competent a transmetre-la.', true), ('C', 'Només es poden presentar davant l''autoritat de l''Estat d''execució.', false), ('D', 'Obliguen a transmetre-la si el condemnat hi presta el consentiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 68 de la Llei 23/2014, en quin cas és obligatòria la consulta prèvia a l''autoritat de l''Estat d''execució abans de transmetre-li una resolució que imposa una pena privativa de llibertat?', 'L''art. 68.1 Llei 23/2014 configura la consulta com a facultativa i l''art. 68.2 la fa obligatòria en aquests supòsits.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12029'), 'Art. 68.2 Llei 23/2014', 'Esta consulta será obligatoria en los casos en que la resolución se transmita a un Estado de ejecución distinto de aquél en que el condenado vive y del que es nacional o de aquél al que vaya a ser expulsado una vez puesto en libertad.', null, 'd68194b2b7e97aca346619db5930cbc3e28593c1840dca86e0e5e570163776e8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd68194b2b7e97aca346619db5930cbc3e28593c1840dca86e0e5e570163776e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
