insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e09-marc-sistema-penitenciari', 'Tema 9. Marc legal i principis del sistema penitenciari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e09-marc-sistema-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 del Reglament penitenciari (RP), entre els fins de l''activitat penitenciària, a més de la reeducació, la reinserció social i la retenció i custòdia, s''hi inclou:', 'L''art. 2 RP amplia el text de l''art. 1 LOGP i hi inclou l''assistència social dels interns, dels alliberats i dels seus familiars.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 2 RP', 'La actividad penitenciaria tiene como fin primordial la reeducación y reinserción social de los sentenciados a penas y medidas de seguridad privativas de libertad, así como la retención y custodia de los detenidos, presos y penados y la asistencia social de los internos, liberados y de sus familiares.', null, 'bb9fc659c2f5e8a19fd41c99198a4f192da24579d45a05854c8e4677bc8d9d73', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bb9fc659c2f5e8a19fd41c99198a4f192da24579d45a05854c8e4677bc8d9d73')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La reparació econòmica a les víctimes del delicte.', false), ('B', 'L''assistència social dels interns, dels alliberats i dels seus familiars.', true), ('C', 'La prevenció de la reincidència mitjançant el control telemàtic dels alliberats.', false), ('D', 'La formació del personal penitenciari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''article 3.3 del Reglament penitenciari considera que l''intern és subjecte de dret i que continua formant part de la societat. Quina de les conseqüències següents NO es deriva d''aquest principi segons aquest precepte?', 'L''art. 3.3 RP diu que la vida a la presó ha de prendre com a referència la vida en llibertat, reduint els efectes nocius de l''internament i afavorint els vincles socials, la col·laboració i participació de les entitats públiques i privades i l''accés a les prestacions públiques. No limita la col·laboració de les entitats privades.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.3 RP', 'En consecuencia, la vida en prisión debe tomar como referencia la vida en libertad, reduciendo al máximo los efectos nocivos del internamiento, favoreciendo los vínculos sociales, la colaboración y participación de las entidades públicas y privadas y el acceso a las prestaciones públicas.', null, '244660a9cfbb1db9408ef4ee2e75b0ed3e47a1b134ece8001fd27eb8889ad3ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '244660a9cfbb1db9408ef4ee2e75b0ed3e47a1b134ece8001fd27eb8889ad3ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Limitar la col·laboració de les entitats privades a l''àmbit purament assistencial.', true), ('B', 'Reduir al màxim els efectes nocius de l''internament.', false), ('C', 'Afavorir els vincles socials.', false), ('D', 'Afavorir l''accés a les prestacions públiques.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.5 del Reglament penitenciari, mitjançant quins instruments poden dirigir els òrgans directius de l''Administració penitenciària les activitats dels seus òrgans jeràrquicament dependents?', 'L''art. 3.5 RP preveu que els òrgans directius dirigeixin els òrgans dependents mitjançant circulars, instruccions i ordres de servei.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.5 RP', 'Los órganos directivos de la Administración penitenciaria podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante circulares, instrucciones y órdenes de servicio.', null, '4615c51f493a2a50dc19811abe617dd6878a2401d65c5f3c43480bdc766c5bcc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4615c51f493a2a50dc19811abe617dd6878a2401d65c5f3c43480bdc766c5bcc')
  returning id
), o as (
