)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.4 del Reglament penitenciari, en la mesura que sigui compatible amb la seva situació processal, els presos preventius:', 'L''art. 3.4 RP equipara els preventius als penats en l''accés a activitats educatives, formatives, esportives i culturals, sempre que sigui compatible amb la seva situació processal.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.4 RP', 'En cuanto sea compatible con su situación procesal, los presos preventivos podrán acceder a las actividades educativas, formativas, deportivas y culturales que se celebren en el centro penitenciario, en las mismas condiciones que los penados.', null, '716435fd9833abcd3372c146a30036fa2b45f1b3537a2fa027429de56216eb21', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '716435fd9833abcd3372c146a30036fa2b45f1b3537a2fa027429de56216eb21')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No poden participar en cap activitat del centre fins que tinguin sentència ferma.', false), ('B', 'Només poden accedir a les activitats esportives.', false), ('C', 'Poden accedir a les activitats educatives, formatives, esportives i culturals del centre en les mateixes condicions que els penats.', true), ('D', 'Poden accedir a les activitats, però només si ho autoritza el jutge instructor en cada cas.', false)) as v(label, body, ok)
)
