  select 'Segons l''article 12 del Reglament penitenciari, què és un establiment polivalent?', 'L''art. 12 RP defineix l''establiment polivalent i exigeix que tots els seus departaments, mòduls o unitats tinguin garantits en igualtat de condicions els serveis generals, en especial la separació entre penats i preventius.', 'pcat_e09_marc_sistema_penitenciari', (select id from public.topics where slug = 'pcat-e09-marc-sistema-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 12 RP', 'Se entiende por establecimiento polivalente aquel que cumple los diversos fines previstos en los artículos 7 a 11 de la Ley Orgánica General Penitenciaria.', null, '4f73606d04ad67c8c80f5927485f5be42cc4ba94e353c9f226a96727b6cf34d4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4f73606d04ad67c8c80f5927485f5be42cc4ba94e353c9f226a96727b6cf34d4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El que acull alhora interns homes i dones en unitats mixtes.', false), ('B', 'El que disposa d''unitats de règim tancat i de departaments especials.', false), ('C', 'El que comparteixen l''Administració penitenciària de l''Estat i la d''una comunitat autònoma.', false), ('D', 'El que compleix els diversos fins previstos als articles 7 a 11 de la LOGP.', true)) as v(label, body, ok)
