with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quina de les atribucions següents NO correspon al director o directora del centre penitenciari?', 'Les tres últimes són atribucions del director o directora (art. 12.2 g, h i m). La concessió dels permisos de sortida amb l''informe previ de l''equip multidisciplinari correspon a la Junta de Tractament (art. 32.1 h).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 12.2 Decret 329/2006', 'h) Concedir els permisos penitenciaris de sortida, amb l''informe previ de l''equip multidisciplinari, sol·licitant l''autorització del jutge de vigilància penitenciària o del centre directiu, segons correspongui.', null, 'd0a4d46ec8eacefc1052cd000cad995a258b2b9350bbe93a759dad195e9bf092', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd0a4d46ec8eacefc1052cd000cad995a258b2b9350bbe93a759dad195e9bf092')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
