with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, qui designa l''òrgan unipersonal que ha de suplir el director o directora del centre en els supòsits de vacant, absència o malaltia, i amb quina periodicitat?', 'L''art. 18.1 encarrega al centre directiu designar anualment l''òrgan unipersonal que suplirà el director o directora. El gerent el supleix el secretari tècnic jurídic, i els subdirectors se supleixen entre si (art. 18.2).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 18.1 Decret 329/2006', 'El centre directiu haurà de designar, amb caràcter anual, l''òrgan unipersonal del centre penitenciari que haurà de suplir el/la director/a en els supòsits de vacant, absència o malaltia.', null, '36d44f7f0a3f3e1836dd5f86d05be6bb1f16b019da49bf5694bda1c80928c463', false
