  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4.4 del Decret 329/2006, els centres oberts o centres d''inserció social són establiments ordinaris destinats preferentment al compliment de les penes privatives de llibertat en les modalitats de vida del règim obert. Qui més hi pot ser destinat?', 'L''art. 4.4 del Decret 329/2006 hi admet també interns de segon grau capacitats per a la semillibertat i persones amb un procés d''inserció social perllongat i consolidat que l''ingrés a presó perjudicaria notòriament.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 4.4 Decret 329/2006', 'i podran ser-hi destinades les persones classificades en segon grau de tractament penitenciari que, per les seves circumstàncies personals i penitenciàries, estiguin capacitades per complir sense riscos la seva condemna en un règim de vida de semillibertat, i les persones que acreditin un perllongat i consolidat procés personal d''inserció social', null, '7f49d9d65ab03b5df87bfc947dfb93f780020aa113ceb3156b3f670035c0cfdf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f49d9d65ab03b5df87bfc947dfb93f780020aa113ceb3156b3f670035c0cfdf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les persones classificades en segon grau capacitades per complir sense riscos la condemna en un règim de semillibertat, i les que acreditin un procés personal d''inserció social perllongat i consolidat.', true), ('B', 'Només els interns classificats en tercer grau que hagin complert les tres quartes parts de la condemna.', false), ('C', 'Els preventius que no hagin estat classificats.', false), ('D', 'Els interns classificats en primer grau, en fase de progressió.', false)) as v(label, body, ok)
)
