with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 12.2 del Decret 329/2006, quina competència té el director o directora del centre en matèria disciplinària?', 'L''art. 12.2.h del Decret 329/2006 atribueix al director o directora les mesures cautelars i la imposició de sancions per faltes lleus (procediment abreujat); les greus i molt greus les resol la Comissió Disciplinària (art. 35.2.a).', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 12.2.h Decret 329/2006', 'h) Adoptar, davant de fets o actuacions dels/de les interns/es que puguin constituir faltes disciplinàries, les mesures cautelars que escaiguin fins que recaigui resolució definitiva en l''expedient disciplinari corresponent, i imposar les sancions per les infraccions lleus comeses pels/per les interns/es, amb la instrucció prèvia d''un procediment abreujat.', null, 'e0dd1a2e3e6a2c40113d4e557ccdbde34160244b2bf84a54309e3fef6f161068', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e0dd1a2e3e6a2c40113d4e557ccdbde34160244b2bf84a54309e3fef6f161068')
  returning id
