with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 1436/1984, en supòsits excepcionals de motins, catàstrofes, epidèmies o incendis que facin necessari el trasllat massiu d''interns a establiments d''una altra administració penitenciària, qui decideix i organitza aquest trasllat?', 'L''art. 7 encarrega la decisió i l''organització a l''administració que pateix la situació crítica, que ho ha de comunicar immediatament a l''Administració de l''Estat perquè distribueixi els interns amb l''acord previ de l''administració receptora.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-17054'), 'Art. 7 RD 1436/1984', 'éste será decidido y organizado por la Administración que sufra la situación crítica.', null, '5aa9bc99501ed2a4822bea14020c3b87e341cca4a7458951d6352f95ea6ce786', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5aa9bc99501ed2a4822bea14020c3b87e341cca4a7458951d6352f95ea6ce786')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Direcció General d''Institucions Penitenciàries, en tots els casos.', false), ('B', 'L''administració penitenciària que hagi de rebre els interns.', false), ('C', 'El jutge de vigilància penitenciària competent.', false), ('D', 'L''administració que pateixi la situació crítica.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
