with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 6.1 del Reial decret 1436/1984, de normes provisionals de coordinació de les administracions penitenciàries, qui ordena el trasllat i la conducció d''interns entre establiments dins del territori d''una mateixa administració penitenciària?', 'L''art. 6.1 RD 1436/1984 atribueix al centre directiu de cada administració penitenciària els trasllats i conduccions dins del seu territori.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-17054'), 'Art. 6.1 RD 1436/1984', 'El traslado y conducción entre establecimientos dentro del territorio de una Administración Penitenciaria, cualesquiera que sean sus razones o autoridad requirente, serán ordenados por el Centro directivo de la misma.', null, 'c93a49bf8be7e54ebfb443747ef2d8e298cd4cdc2d5135883a09cce8c98368e2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c93a49bf8be7e54ebfb443747ef2d8e298cd4cdc2d5135883a09cce8c98368e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''autoritat judicial que l''hagi sol·licitat.', false), ('B', 'El centre directiu d''aquesta administració, sigui quina sigui la raó o l''autoritat requeridora.', true), ('C', 'El director o directora del centre d''origen.', false), ('D', 'La Direcció General d''Institucions Penitenciàries de l''Estat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 5.1 del Reial decret 1436/1984, de normes provisionals de coordinació de les administracions penitenciàries, en quina llengua s''han de redactar els expedients i protocols de personalitat dels interns?', 'L''art. 5.1 RD 1436/1984 exigeix la redacció en castellà, sens perjudici de la redacció en la llengua oficial de la comunitat.', 'pcat_e10_sistema_penitenciari_catala', (select id from public.topics where slug = 'pcat-e10-sistema-penitenciari-catala'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-17054'), 'Art. 5.1 RD 1436/1984', 'Los expedientes y protocolos de personalidad de los internos deberán redactarse en castellano, sin perjuicio de la redacción en la lengua oficial de la Comunidad, de conformidad con su legislación específica.', 'Norma de 1984 («normes provisionals»): convé confirmar que l''art. 5.1 continua aplicant-se tal qual a Catalunya amb la normativa lingüística posterior; el text consolidat del BOE el manté sense modificacions.', '1648dd19a2f17dc24d8bdb1fd81df16cd8809c7aadbcd9d4d2dc82ef0a487d6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1648dd19a2f17dc24d8bdb1fd81df16cd8809c7aadbcd9d4d2dc82ef0a487d6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivament en la llengua oficial de la comunitat autònoma que gestiona l''establiment.', false), ('B', 'En la llengua que esculli l''intern.', false), ('C', 'En castellà, sens perjudici de la redacció en la llengua oficial de la comunitat, d''acord amb la seva legislació específica.', true), ('D', 'En castellà i en anglès, per facilitar els trasllats internacionals.', false)) as v(label, body, ok)
)
