with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2011, per quants membres està formada la Comissió de seguiment del Codi ètic i qui els designa?', 'El punt cinquè de la Circular crea la Comissió de seguiment, formada per sis membres designats per la Direcció General de Serveis Penitenciaris; la participació hi és gratuïta.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Cinquè Circular 2/2011', 'Aquesta Comissió està formada per sis membres, designats per la Direcció General de Serveis Penitenciaris', null, 'e7d1d48ca302d23747d82bf570478ebf2d211209be7fc7a59d145d1d36b4d815', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e7d1d48ca302d23747d82bf570478ebf2d211209be7fc7a59d145d1d36b4d815')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc membres, designats pel conseller o consellera de Justícia.', false), ('B', 'Sis membres, designats per la Direcció General de Serveis Penitenciaris.', true), ('C', 'Sis membres, elegits per la Taula de Participació Social.', false), ('D', 'Vuit membres, designats pel secretari o secretària general del Departament de Justícia.', false)) as v(label, body, ok)
)
