with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la base 3 del Codi ètic dels professionals de l''execució penal a Catalunya, quina de les persones següents NO té la consideració d''«empleada o empleat públic d''execució penal»?', 'La base 3.3 inclou com a empleat públic d''execució penal el funcionari de carrera, eventual o interí i el personal laboral. Als voluntaris i altres persones que actuen per una relació humanitària, assistencial, professional o de voluntariat se''ls aplica el Codi en allò que no sigui inherent a la condició d''empleat públic (base 3.2).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 3.3 Codi ètic', 's’entén com a “empleada o empleat públic d’execució penal” qualsevol funcionari o funcionària de carrera, eventual, interí o interina i personal laboral al servei de l’Administració competent en matèria d’execució penal, en tots els seus nivells jeràrquics.', null, 'b49e7f00c7774577da00f159d72c37f006fa08ea6a4857a91cae701e1ef39fe6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b49e7f00c7774577da00f159d72c37f006fa08ea6a4857a91cae701e1ef39fe6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El voluntari d''una entitat col·laboradora que actua en un centre penitenciari.', true), ('B', 'El funcionari interí destinat en un centre penitenciari.', false), ('C', 'El personal laboral al servei de l''Administració competent en execució penal.', false), ('D', 'El funcionari eventual al servei de l''Administració competent en execució penal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi ètic dels professionals de l''execució penal a Catalunya, quin deure té l''empleat públic d''execució penal respecte del Síndic de Greuges?', 'La base 6 configura el Síndic de Greuges com a institució que exerceix un control de legalitat i eticopúblic en l''execució penal, i la base 6.2 obliga l''empleat públic a auxiliar-lo.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 6.2 Codi ètic', 'L’empleada o empleat públic d’execució penal ha d’auxiliar el Síndic de Greuges en l’exercici de les seves funcions i competències.', null, '028c2be536b6a19c5322d8afde196b1e90bb4e31054a51e34c5c538ef8280a3d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '028c2be536b6a19c5322d8afde196b1e90bb4e31054a51e34c5c538ef8280a3d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Informar-lo de totes les sancions disciplinàries imposades als interns.', false), ('B', 'Auxiliar-lo en l''exercici de les seves funcions i competències.', true), ('C', 'Demanar autorització al director abans de respondre qualsevol requeriment seu.', false), ('D', 'Cap: el Síndic de Greuges no té competències en l''àmbit de l''execució penal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la base 8 del Codi ètic dels professionals de l''execució penal a Catalunya (principi d''idoneïtat), què ha d''acompanyar la idoneïtat, entesa com a aptitud tècnica i legal, per a l''accés i l''exercici de la funció pública?', 'La base 8 estableix que l''ingrés i l''exercici impliquen conèixer i complir el Codi ètic, i que la idoneïtat tècnica i legal ha d''anar acompanyada d''una idoneïtat ètica.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 8 Codi ètic', 'La idoneïtat, entesa com a aptitud tècnica i legal, ha d’anar acompanyada d’una idoneïtat ètica per a l’accés i l’exercici de la funció pública.', null, 'e2eae3b4177dac6c3bde396de82ad0667939573c5b69b7157423750db9cb42f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e2eae3b4177dac6c3bde396de82ad0667939573c5b69b7157423750db9cb42f3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una idoneïtat física acreditada cada any.', false), ('B', 'Una idoneïtat lingüística de nivell C2.', false), ('C', 'Una idoneïtat ètica.', true), ('D', 'Una idoneïtat jeràrquica, valorada pel superior immediat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi ètic dels professionals de l''execució penal a Catalunya, en quins supòsits han d''utilitzar la força física els professionals quan sigui necessari per complir les seves funcions?', 'La base 27.2 limita l''ús de la força als supòsits totalment indispensables, com a darrera mesura, pel temps necessari i amb proporcionalitat, amb l''autorització reglamentària i personal capacitat. La base 27.1 n''exclou finalitats disciplinàries o d''exemplaritat.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Base 27.2 Codi ètic', 'l’han d’utilitzar només en aquells supòsits que sigui totalment indispensable, com a darrera mesura, sempre durant el temps necessari i amb respecte al criteri de proporcionalitat.', null, 'c74c67b6277c4f3d21db7ffa7b6331658db3506443552ad93cfef9df7ddfa20d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c74c67b6277c4f3d21db7ffa7b6331658db3506443552ad93cfef9df7ddfa20d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre que un intern desobeeixi una ordre, com a mesura exemplar.', false), ('B', 'Només quan sigui totalment indispensable, com a darrera mesura, durant el temps necessari i amb respecte al criteri de proporcionalitat.', true), ('C', 'Com a primera mesura davant de qualsevol alteració, per evitar que s''agreugi.', false), ('D', 'Quan ho decideixi lliurement el funcionari, sense necessitat de cap autorització.', false)) as v(label, body, ok)
)
