select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el punt cinquè de la Circular 2/2011, quina de les persones següents NO forma part de la Comissió de seguiment del Codi ètic?', 'La Comissió té sis membres: un professional de la DGSP (que la presideix), un de la DG d''Execució Penal a la Comunitat i de Justícia Juvenil, un del Servei d''Inspecció, un representant sindical, un director d''equipament i una persona de la part social de la Taula de Participació Social. No hi ha cap jutge.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/ambits/reinsercio_i_serveis_peni/instruccions_i_circulars/circular_codi_etic_execucio_penal.pdf'), 'Cinquè Circular 2/2011', 'c) una persona adscrita al Servei d’Inspecció, de la Direcció General de Serveis Penitenciaris; d) una persona representant sindical de les persones treballadores al servei d’aquesta Administració competent en matèria d’execució penal; e) un/a director/a d’un equipament d’execució penal; f) una persona integrant de la part social de la Taula de Participació Social.', null, 'c58404e9e2830abdb5426f557b5e540fc1a4e95f4fdda04d7247d7da5167a236', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c58404e9e2830abdb5426f557b5e540fc1a4e95f4fdda04d7247d7da5167a236')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un jutge o jutgessa de vigilància penitenciària.', true), ('B', 'Una persona adscrita al Servei d''Inspecció de la Direcció General de Serveis Penitenciaris.', false), ('C', 'Un director o directora d''un equipament d''execució penal.', false), ('D', 'Una persona integrant de la part social de la Taula de Participació Social.', false)) as v(label, body, ok)
)
