insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 329/2006, de 5 de setembre, pel qual s''aprova el Reglament d''organització i funcionament dels serveis d''execució penal a Catalunya (DOGC núm. 4714, 07/09/2006)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e11-personal-penitenciari', 'Tema 11. El personal al servei de l''Administració penitenciària a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e11-personal-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 40.3 del Decret 329/2006, quines funcions corresponen als funcionaris del cos tècnic d''especialistes, grup de serveis penitenciaris?', 'L''art. 40.3 atribueix al cos tècnic d''especialistes, grup de serveis penitenciaris, funcions d''inspecció, execució, control o similars i de suport administratiu a la gestió. Les funcions de nivell superior són del grup A (art. 40.1) i les de col·laboració en la gestió, del grup B (art. 40.2).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 40.3 Decret 329/2006', 'Corresponen als/a les funcionaris/àries del cos tècnic d''especialistes, grup de serveis penitenciaris, les funcions d''inspecció, d''execució, de control o similars adients al seu nivell de titulació i especialització necessàries per a la prestació dels serveis públics penitenciaris i també les de suport administratiu a les activitats de gestió que es duen a terme en el centre penitenciari.', null, 'c36658e0919df0835341a2fd3ab06a61f04ccb7bc62c0f87cf3ea59ca95d9389', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c36658e0919df0835341a2fd3ab06a61f04ccb7bc62c0f87cf3ea59ca95d9389')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les de nivell superior, de direcció administrativa, d''estudi i de proposta de la funció pública d''execució penal.', false), ('B', 'Les de col·laboració en les tasques de gestió i les de proposta de resolució d''expedients que no corresponguin a tasques de nivell superior.', false), ('C', 'Les d''inspecció, d''execució, de control o similars necessàries per a la prestació dels serveis públics penitenciaris i les de suport administratiu a les activitats de gestió del centre.', true), ('D', 'Exclusivament les de vigilància i custòdia dels interns a les unitats de separació interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 52 del Decret 329/2006, quin dels següents NO és un dels àmbits d''actuació en què s''organitza el personal que presta serveis als centres penitenciaris?', 'L''art. 52 organitza el personal dels centres en tres àmbits d''actuació: administratiu, de rehabilitació i de règim interior.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 52 Decret 329/2006', 'el personal que presti serveis als centres penitenciaris s''organitzarà substancialment en els següents àmbits d''actuació: l''administratiu, el de rehabilitació i el de règim interior.', null, 'a1385584422e32d880c0e3ee3e916b86d62a4b9fcf3e842f20eb663cf93cf824', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1385584422e32d880c0e3ee3e916b86d62a4b9fcf3e842f20eb663cf93cf824')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''àmbit administratiu.', false), ('B', 'L''àmbit de seguretat exterior.', true), ('C', 'L''àmbit de rehabilitació.', false), ('D', 'L''àmbit de règim interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 63.3 del Decret 329/2006, quina de les funcions següents NO correspon al personal de l''àmbit de règim interior?', 'Les tres últimes són funcions del personal de règim interior (art. 63.3 i, j i m). Decidir la separació interior dels interns correspon al subdirector o subdirectora d''Interior (art. 15.2 h).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 63.3 Decret 329/2006', 'h) Decidir la separació interior dels/de les interns/es tenint en compte els antecedents i circumstàncies que concorrin en cadascun/a d''ells/elles, d''acord amb el que disposa la legislació penitenciària.', null, '193233680006bf2e6147399c7a457d6d5b7d7dd3e7f3bd7c82c8218cc7531aec', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '193233680006bf2e6147399c7a457d6d5b7d7dd3e7f3bd7c82c8218cc7531aec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Decidir la separació interior dels interns tenint en compte els antecedents i les circumstàncies de cadascun.', true), ('B', 'Fer les tasques d''identificació personal dels interns.', false), ('C', 'Fer les tasques d''identificació i control dels vehicles, paquets, béns i subministraments que entrin o surtin de l''establiment.', false), ('D', 'Informar els familiars de la població reclosa, els visitants, els col·laboradors voluntaris i els proveïdors sobre els procediments i la normativa de funcionament dels serveis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, de qui depèn directament el cap de serveis?', 'L''art. 64 diu que el cap de serveis depèn directament del subdirector o subdirectora d''Interior i coordina i supervisa tots els serveis de l''àmbit de règim interior.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 64 Decret 329/2006', 'El/La cap de serveis, que depèn directament del/de la subdirector/a d''Interior del centre, com a encarregat/ada de coordinar i supervisar tots els serveis de l''àmbit de règim interior', null, 'ca6941ff64e723554b6338bc2ba17c8f6ae8fcc50fc92d0eb805fad5d0893e43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca6941ff64e723554b6338bc2ba17c8f6ae8fcc50fc92d0eb805fad5d0893e43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del director o directora del centre.', false), ('B', 'Del o la gerent.', false), ('C', 'Del subdirector o subdirectora de Tractament.', false), ('D', 'Del subdirector o subdirectora d''Interior.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, què correspon al cap de serveis en absència del director o directora o del subdirector o subdirectora d''incidències?', 'L''art. 64 o) disposa que, en absència del director o del subdirector d''incidències, el cap de serveis és el responsable dels diferents serveis i àrees d''intervenció del centre.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 64.o Decret 329/2006', 'o) En absència del/de la director/a o del/de la subdirector/a d''incidències, serà el/la responsable dels diferents serveis i àrees d''intervenció del centre i, per tant, adoptarà les mesures que corresponguin per tal de mantenir el seu funcionament eficient i eficaç.', null, 'addcc8bea33a4eb54b9f17a3fd23443e5631052bb9a3ba98e972b02f54ef410f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'addcc8bea33a4eb54b9f17a3fd23443e5631052bb9a3ba98e972b02f54ef410f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Convocar d''urgència el Consell de Direcció perquè designi un substitut.', false), ('B', 'Ser el responsable dels diferents serveis i àrees d''intervenció del centre i adoptar les mesures que corresponguin per mantenir-ne el funcionament eficient i eficaç.', true), ('C', 'Limitar-se a comunicar la situació al centre directiu i esperar instruccions.', false), ('D', 'Assumir la presidència de la Comissió Disciplinària fins que es reincorpori el director o directora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65 del Decret 329/2006, quina de les funcions següents NO correspon al cap d''unitat?', 'El cap d''unitat despatxa amb els caps de serveis i, diàriament, amb el personal al seu càrrec (art. 65 a i b). Despatxar diàriament amb el director i els subdirectors és funció del cap de serveis (art. 64 a) i del coordinador d''unitat especialitzada (art. 67.2 b).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 65 Decret 329/2006', 'a) Despatxar amb els/les caps de serveis per informar-los del desenvolupament dels serveis i rebre''n les instruccions. b) Despatxar diàriament amb el personal al seu càrrec', null, '237e10e1a024960e9a5585ffe4a01109b7157e75fbb48a482a5dcc1fb4b826b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '237e10e1a024960e9a5585ffe4a01109b7157e75fbb48a482a5dcc1fb4b826b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Assignar a cada intern que ingressi a la unitat la cel·la que ha d''ocupar i fer-ne les reassignacions adients.', false), ('B', 'Assistir com a vocal a les sessions de l''equip multidisciplinari.', false), ('C', 'Despatxar diàriament amb el director o directora i amb els subdirectors per informar-los del desenvolupament dels serveis.', true), ('D', 'Portar una relació actualitzada dels interns de la unitat i de les circumstàncies regimentals que s''hi refereixin.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, de qui depèn directament el cap d''unitat?', 'L''art. 65 estableix que el cap d''unitat depèn directament del cap de serveis i coordina, dirigeix i gestiona els serveis de la unitat o unitats de separació interior de què és cap.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 65 Decret 329/2006', 'El/La cap d''unitat, que depèn directament del/de la cap de serveis, com a encarregat/ada de coordinar, dirigir i gestionar els serveis i les prestacions propis de la unitat o unitats de separació interior de què és cap', null, '0b74cc3a9089ca7e4e312eccd6fc0198872fa86584f61703edce16f0ba90dbe7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0b74cc3a9089ca7e4e312eccd6fc0198872fa86584f61703edce16f0ba90dbe7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del subdirector o subdirectora d''Interior.', false), ('B', 'Del coordinador o coordinadora d''unitat especialitzada.', false), ('C', 'Del cap d''àrea funcional.', false), ('D', 'Del cap de serveis.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, a quines àrees poden ser assignats els caps d''àrea funcional, segons permetin les relacions de llocs de treball?', 'L''art. 66.3 preveu que els caps d''àrea funcional s''assignin a àrees com ara comunicacions, tallers productius o dependències de formació. Durant el servei assumeixen les funcions pròpies dels caps d''unitat en allò que afecti la seva àrea (art. 66.2).', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 66 Decret 329/2006', 'Els/Les caps de l''àrea funcional seran assignats/ades, segons permetin les relacions de llocs de treball, a àrees com ara les de comunicacions, de tallers productius, de dependències de formació acadèmica o per al treball', null, '9a9e268cf33442fb274be56218a2268b26eb5cef8cfd1e103101c54c9ea4d259', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a9e268cf33442fb274be56218a2268b26eb5cef8cfd1e103101c54c9ea4d259')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A àrees com ara les de comunicacions, tallers productius o dependències de formació acadèmica o per al treball.', true), ('B', 'Exclusivament als departaments especials de règim tancat.', false), ('C', 'A les unitats de gestió penitenciària, de recursos humans i de gestió econòmica.', false), ('D', 'A les unitats dependents i als centres oberts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, de qui depèn funcionalment el coordinador o coordinadora d''unitat especialitzada?', 'L''art. 67.1 preveu que el coordinador d''unitat especialitzada, en unitats amb formes especials d''execució, tractaments especialitzats o règim obert o tancat, depengui funcionalment del director i dels subdirectors d''Interior i de Tractament.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 67.1 Decret 329/2006', 'que dependrà funcionalment del/de la director/a i dels/de les subdirectors/es d''Interior i Tractament.', null, '85c4ad62e1123d7d2b661f72d7e2813870ee1a40c14411597080ba1c3d0718dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '85c4ad62e1123d7d2b661f72d7e2813870ee1a40c14411597080ba1c3d0718dd')
  returning id
), o as (
