with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 39 del Decret 329/2006, què pot sol·licitar el Departament de Justícia a l''autoritat competent per al desenvolupament de tasques pròpies de la titulació als serveis d''execució penal?', 'L''art. 39.2 permet al Departament de Justícia sol·licitar l''adscripció d''empleats públics de qualsevol administració per a tasques pròpies de la seva titulació, sempre d''acord amb les relacions de llocs de treball.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 39.2 Decret 329/2006', 'El Departament de Justícia podrà sol·licitar a l''autoritat competent l''adscripció d''empleats públics de qualsevol administració per al desenvolupament de tasques pròpies de la seva titulació als serveis d''execució penal, d''acord amb les relacions de llocs de treball corresponents.', null, 'd8538596d224724b3bca01a7abffe1ed69d2d86e62e0a91ffe931e8da9cf8f44', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd8538596d224724b3bca01a7abffe1ed69d2d86e62e0a91ffe931e8da9cf8f44')
  returning id
