select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 43 del Decret 329/2006, quan per necessitats excepcionals i justificades s''exigeix als empleats públics destinats als establiments penitenciaris un nombre superior d''hores de servei, com han de ser compensats si les necessitats del servei ho permeten?', 'L''art. 43.2 permet exigir més hores de servei per necessitats excepcionals i justificades; quan el servei ho permeti, els funcionaris han de ser compensats amb hores de lliure disposició o retribuïts de la manera legalment establerta.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 43.2 Decret 329/2006', 'En aquest cas, quan les necessitats del servei ho permetin, els/les funcionaris/àries hauran de ser compensats amb hores de lliure disposició o bé retribuïts de la manera legalment establerta', null, '97eea3e20dcc0feccaaa0fdd43c16bff7df5a535c057cb68d871405bf364c4f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '97eea3e20dcc0feccaaa0fdd43c16bff7df5a535c057cb68d871405bf364c4f3')
  returning id
), o as (
