select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 44 del Decret 329/2006, qui elabora el manual d''organització del centre penitenciari i qui l''aprova?', 'L''art. 44.1 encarrega al Consell de Direcció l''elaboració del manual d''organització, que ha de ser aprovat (també les seves modificacions) pel centre directiu per resolució expressa amb rang d''instrucció.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 44.1 Decret 329/2006', 'El Consell de Direcció haurà d''elaborar un manual d''organització del centre penitenciari […] Aquest manual d''organització i les seves modificacions posteriors hauran de ser aprovats pel centre directiu mitjançant resolució expressa, que tindrà rang d''instrucció.', null, '40a54ff6933b986c4713b4e31688c7c9445a3a863f0466e62e224930239d6eb1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '40a54ff6933b986c4713b4e31688c7c9445a3a863f0466e62e224930239d6eb1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''elabora el director o directora del centre i l''aprova el Consell de Direcció per majoria absoluta.', false), ('B', 'L''elabora la Junta de Tractament i l''aprova el conseller o consellera de Justícia per ordre.', false), ('C', 'L''elabora el gerent i l''aprova el jutge de vigilància penitenciària.', false), ('D', 'L''elabora el Consell de Direcció i l''aprova el centre directiu mitjançant resolució expressa, que té rang d''instrucció.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 44.3 del Decret 329/2006, amb quina periodicitat s''ha de revisar el manual d''organització del centre penitenciari i qui el pot modificar provisionalment?', 'L''art. 44.3 exigeix publicitat suficient del manual entre la plantilla, revisió anual i permet que el director el modifiqui provisionalment quan ho exigeixin les necessitats del servei.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 44.3 Decret 329/2006', 'El manual d''organització, que haurà de tenir publicitat suficient entre la plantilla del centre penitenciari, haurà de ser revisat anualment i podrà ser modificat provisionalment pel/per la director/a del centre quan les necessitats del servei ho exigeixin.', null, 'f8343b923ad220c9480de4ce030188cdb515b908f192757f8657a5d28a5d76ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f8343b923ad220c9480de4ce030188cdb515b908f192757f8657a5d28a5d76ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de revisar anualment i el pot modificar provisionalment el director o directora del centre quan les necessitats del servei ho exigeixin.', true), ('B', 'S''ha de revisar cada dos anys i el pot modificar provisionalment el cap de serveis.', false), ('C', 'S''ha de revisar cada sis mesos i només el pot modificar el centre directiu.', false), ('D', 'S''ha de revisar cada quatre anys i el pot modificar provisionalment el subdirector o subdirectora d''Interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 45 del Decret 329/2006, quin caràcter té el llibre de serveis del centre penitenciari?', 'L''art. 45 preveu un llibre de serveis on consten tots els serveis, els funcionaris assignats (amb el número d''identificació), el servei i l''horari. Té caràcter d''ordre de serveis i l''han de signar els funcionaris quan es fan càrrec dels serveis.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 45.2 Decret 329/2006', 'El llibre de serveis, que tindrà el caràcter d''ordre de serveis, s''emplenarà amb prou antelació i hi signaran tots/es els/les funcionaris/àries en el moment que es facin càrrec dels serveis', null, '2910dea8b654bbd150faef29cc0b6a98753e672203c0fcb1fac088ebd33b7c17', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2910dea8b654bbd150faef29cc0b6a98753e672203c0fcb1fac088ebd33b7c17')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El caràcter d''instrucció del centre directiu.', false), ('B', 'El caràcter d''ordre de serveis.', true), ('C', 'El caràcter de circular de la Direcció General.', false), ('D', 'El caràcter de registre merament informatiu, sense valor d''ordre.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 47 del Decret 329/2006, com pot gaudir de les vacances el personal de l''àmbit de règim interior que fa la jornada subjecta al règim de cicles de treball?', 'L''art. 47 permet al personal de règim interior amb cicles de treball fer les vacances en un sol període o en diversos, coincidint amb els cicles de torns i garantint la continuïtat del servei, d''acord amb el coeficient de simultaneïtat que s''estableixi.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 47 Decret 329/2006', 'es podrà fer en un sol període o en diversos, que en tot cas hauran de coincidir amb els cicles de torns horaris, sempre que es garanteixi la continuïtat en la prestació del servei.', null, '90a16931bf0aec1f7fc73080e64f174546cea66d02cdf89d6f1791ba547a5283', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '90a16931bf0aec1f7fc73080e64f174546cea66d02cdf89d6f1791ba547a5283')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obligatòriament en un sol període durant els mesos d''estiu.', false), ('B', 'En un màxim de dos períodes, independentment dels cicles de torns horaris.', false), ('C', 'En els períodes que fixi el jutge de vigilància, a proposta del cap de serveis.', false), ('D', 'En un sol període o en diversos, que han de coincidir amb els cicles de torns horaris, sempre que es garanteixi la continuïtat del servei.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
