with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quan un treballador ha de comparèixer en un procediment judicial per raó de les seves actuacions professionals, com se''l compensa?', 'L''art. 48.1 preveu que els treballadors que hagin de comparèixer en un procediment judicial per raó de les seves actuacions professionals siguin compensats amb el temps indispensable per complir-ho.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 48.1 Decret 329/2006', 'Quan per raó de les seves actuacions professionals els/les treballadors/es hagin de comparèixer en un procediment judicial, seran compensats/ades amb el temps indispensable per al seu compliment', null, '1ed9df61c40fe8b535b569a1bf24ee029f6fb6a2de3ba3f805354556ed022cf1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1ed9df61c40fe8b535b569a1bf24ee029f6fb6a2de3ba3f805354556ed022cf1')
  returning id
), o as (
