  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb un dia complet de permís per cada compareixença.', false), ('B', 'Amb dos dies de lliure disposició.', false), ('C', 'Amb el temps indispensable per al seu compliment.', true), ('D', 'No se''l compensa, perquè la compareixença és un deure del funcionari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
