with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 49.3 del Decret 329/2006, quin dels tipus de prova següents NO s''esmenta entre els que poden incloure les proves selectives per a l''ingrés als cossos de serveis penitenciaris?', 'L''art. 49.3 permet que les proves siguin teoricopràctiques i incloguin proves de capacitat física, psicotècniques, mèdiques i de coneixements generals i específics, que han de constar a les bases. No s''hi preveu cap entrevista davant del Consell de Direcció.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 49.3 Decret 329/2006', 'Les proves selectives per a l''ingrés als cossos esmentats podran ser de caràcter teoricopràctic i podran incloure proves de capacitat física, psicotècniques, mèdiques i de coneixements generals i específics, les quals hauran de constar a les bases de les convocatòries corresponents.', null, '8d6c2217407001373c4283ce4cbb2d0a269bdff6c42cda2b7f47d85d3fcc0d0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8d6c2217407001373c4283ce4cbb2d0a269bdff6c42cda2b7f47d85d3fcc0d0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les proves de capacitat física.', false), ('B', 'Les proves d''entrevista personal davant del Consell de Direcció.', true), ('C', 'Les proves psicotècniques i mèdiques.', false), ('D', 'Les proves de coneixements generals i específics.', false)) as v(label, body, ok)
)
