insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 50 del Decret 329/2006, quines dades ha de facilitar el personal dels centres penitenciaris als òrgans de personal que corresponguin?', 'L''art. 50 imposa, per la naturalesa i les peculiaritats del servei públic penitenciari, l''obligació de facilitar les dades completes del domicili particular i un número de telèfon de contacte.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 50 Decret 329/2006', 'haurà de facilitar als òrgans de personal que corresponguin les dades completes relatives al seu domicili particular i un número de telèfon de contacte.', null, '5bd38313b48c0a8d771f82cb441ae935956cf036e67a7798dc8d9dff8c414e64', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5bd38313b48c0a8d771f82cb441ae935956cf036e67a7798dc8d9dff8c414e64')
