  select 'D''acord amb l''article 54 de la Llei 17/2015, amb quin objectiu ha d''oferir l''Administració de la Generalitat formació específica en gènere, igualtat i drets de les dones als cossos penitenciaris?', 'L''art. 54.4 b) fixa per als cossos penitenciaris l''objectiu d''evitar l''estigmatització de les internes i els micromasclismes. L''objectiu de la segona opció és el que l''art. 54.4 c) assigna als cossos judicials.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 54.4.b Llei 17/2015', 'b) A los cuerpos penitenciarios, con el objetivo de evitar la estigmatización de las internas y el ejercicio de micromachismos contra las mujeres.', null, '5a6fe5b6a367f98b50c33976a0651bfe993333472b5fe30910e01ddbd4bb029a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a6fe5b6a367f98b50c33976a0651bfe993333472b5fe30910e01ddbd4bb029a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Evitar l''estigmatització de les internes i l''exercici de micromasclismes contra les dones.', true), ('B', 'Evitar la perpetuació d''actituds i l''estigmatització de les dones que delinqueixen en el procés judicial.', false), ('C', 'Fer anàlisis pericials psicològiques i psicosocials amb perspectiva de gènere.', false), ('D', 'Acreditar el requisit per accedir als llocs de comandament dels centres.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
