with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 de la Llei 17/2015, d''igualtat efectiva de dones i homes, mitjançant quin instrument ha d''incorporar l''Administració de la Generalitat la perspectiva de gènere en la planificació de les instal·lacions, els equipaments i els proveïments dels centres penitenciaris?', 'L''art. 54.5 encomana al Pla director d''equipaments penitenciaris incorporar la perspectiva de gènere i vetllar, entre altres coses, perquè les dones tinguin les mateixes garanties i qualitat de serveis i infraestructures que els homes.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 54.5 Llei 17/2015', 'La Administración de la Generalidad, mediante el Plan director de equipamientos penitenciarios, debe incorporar la perspectiva de género en la planificación de las instalaciones, equipamientos y abastecimientos de los centros penitenciarios.', null, 'cd1df3125a9cd883f05068e6c7a83f24f7b291db3f37e7e416d7a0a1ad625aea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cd1df3125a9cd883f05068e6c7a83f24f7b291db3f37e7e416d7a0a1ad625aea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El manual d''organització de cada centre penitenciari.', false), ('B', 'El Pla director d''equipaments penitenciaris.', true), ('C', 'El pla d''igualtat de dones i homes del Departament de Justícia.', false), ('D', 'El programa de salut penitenciària.', false)) as v(label, body, ok)
)
