with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 de la LOGP, quina condició tenen els funcionaris de l''Administració penitenciària en l''exercici del seu càrrec?', 'L''art. 80.2 LOGP atribueix als funcionaris penitenciaris, en l''exercici del càrrec, la condició d''agents de l''autoritat, que poden identificar pel seu número de registre professional.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 80.2 LOGP', 'Los funcionarios de la administración penitenciaria en el ejercicio de su cargo tendrán la condición de agentes de la autoridad', null, '3c9375720ce25b3c5621e018b25402cb08f4052e399dad253ab310e12befcedf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3c9375720ce25b3c5621e018b25402cb08f4052e399dad253ab310e12befcedf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La condició d''autoritat pública.', false), ('B', 'La condició de policia judicial.', false), ('C', 'La condició d''agents de seguretat privada.', false), ('D', 'La condició d''agents de l''autoritat.', true)) as v(label, body, ok)
)
