with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 de la LOGP, quin valor tenen, en els procediments disciplinaris sancionadors, els informes emesos pels funcionaris de l''Administració penitenciària que han presenciat els fets?', 'L''art. 80.2 LOGP disposa que aquests informes constitueixen base suficient per a la resolució, salvat prova en contra i sens perjudici que els funcionaris hagin d''aportar a l''expedient tots els elements probatoris disponibles.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 80.Dos LOGP', 'los informes emitidos por los funcionarios de la administración penitenciaria en el ejercicio de sus funciones, que hubiesen presenciado los hechos, constituirán base suficiente para adoptar la resolución que proceda, salvo prueba en contrario', null, '8e4a0c59f4d57eb570d384880614c8e05a52e045e782d2c69db7d300763b6ef6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8e4a0c59f4d57eb570d384880614c8e05a52e045e782d2c69db7d300763b6ef6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Constitueixen base suficient per adoptar la resolució que escaigui, llevat de prova en contra.', true), ('B', 'Tenen un valor merament orientatiu i necessiten sempre la ratificació d''un altre funcionari.', false), ('C', 'Només tenen valor si l''intern els reconeix expressament.', false), ('D', 'Han de ser ratificats pel jutge de vigilància abans de poder-se tenir en compte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
