with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 80 de la LOGP, què han de rebre els funcionaris de l''Administració penitenciària abans d''iniciar la seva activitat?', 'L''art. 80.4 LOGP exigeix que, abans d''iniciar l''activitat, rebin formació específica teòrica i pràctica en el centre que determini l''Administració General de l''Estat o la comunitat autònoma de la qual depenguin.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 80.Cuatro LOGP', 'Antes de iniciar su actividad, los funcionarios de la administración penitenciaria deberán recibir la formación específica, tanto teórica como práctica, en el centro que reglamentariamente se determine', null, '01f138cb89c600ed4eb6549b248528bd824e5bc4ad56a249187c938a44f966b4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '01f138cb89c600ed4eb6549b248528bd824e5bc4ad56a249187c938a44f966b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un certificat mèdic d''aptitud expedit pel jutge de vigilància.', false), ('B', 'Una autorització individual del Ministeri de l''Interior.', false), ('C', 'Una formació exclusivament teòrica en dret penitenciari.', false), ('D', 'La formació específica, tant teòrica com pràctica, en el centre que es determini reglamentàriament.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
