with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 de la LOGP, en quin cas ha de rescabalar econòmicament l''Administració els funcionaris penitenciaris que pateixin danys personals o materials en acte de servei o amb ocasió del servei?', 'L''art. 80.5 LOGP obliga l''Administració a rescabalar els danys personals o materials soferts en acte de servei o amb ocasió d''aquest, sense dol, culpa o negligència greu del funcionari, en els termes que es fixin reglamentàriament.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 80.Cinco LOGP', 'La Administración deberá resarcir económicamente a los funcionarios de la administración penitenciaria cuando sufran daños personales o materiales en acto o con ocasión del servicio, sin mediar por su parte dolo, culpa o negligencia grave', null, 'ad01626e2012065618258315d530637ea85cae0a01b9486c3355f8bda7de4382', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ad01626e2012065618258315d530637ea85cae0a01b9486c3355f8bda7de4382')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només quan el dany l''hagi causat un intern condemnat per sentència ferma.', false), ('B', 'Sempre, fins i tot si hi ha hagut negligència greu del funcionari.', false), ('C', 'Només quan el dany sigui personal, però no quan sigui material.', false), ('D', 'Quan no hi hagi mediat per part seva dol, culpa o negligència greu.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 de la LOGP, en els procediments penals seguits contra funcionaris de l''Administració penitenciària, què s''ha de garantir?', 'L''art. 80.6 LOGP garanteix la separació dels funcionaris de la resta de detinguts i de reclusos (en la detenció, l''ingrés a presó i els trasllats sota custòdia) per salvaguardar la seva integritat física.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 80.Seis LOGP', 'se garantizará su separación del resto de los detenidos en caso de detención, así como la separación de otros reclusos en el supuesto de ser ingresados en prisión y en los traslados bajo custodia', null, '7380d80879e773e58679c6a8f3eb57a1107b522d47273ad2ace9ebcad96e931f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7380d80879e773e58679c6a8f3eb57a1107b522d47273ad2ace9ebcad96e931f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el seu ingrés a presó es faci sempre en un centre d''una altra comunitat autònoma.', false), ('B', 'Que no puguin ser detinguts sense autorització prèvia del centre directiu.', false), ('C', 'La seva separació de la resta de detinguts en cas de detenció, i dels altres reclusos si ingressen a presó i en els trasllats sota custòdia.', true), ('D', 'Que compleixin la presó provisional al seu domicili.', false)) as v(label, body, ok)
)
