insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 1/1998, de 7 de enero, de Política Lingüística (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e11-personal-penitenciari', 'Tema 11. El personal al servei de l''Administració penitenciària a Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e11-personal-penitenciari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 9.1 de la Llei 1/1998, de política lingüística, quina llengua han d''utilitzar la Generalitat i les institucions i empreses que en depenen en les seves actuacions internes i en la relació entre elles?', 'L''art. 9.1 de la Llei 1/1998 obliga la Generalitat, les administracions locals i les institucions i empreses que en depenen a utilitzar el català en les actuacions internes i en la relació entre elles.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 9.1 Llei 1/1998', 'La Generalidad, las Administraciones locales y las demás Corporaciones públicas de Cataluña, las instituciones y empresas que dependen de las mismas y los concesionarios de sus servicios deben utilizar el catalán en sus actuaciones internas y en la relación entre ellos.', null, '79efc65d5d971886cde6620c130a7342ab3fbe97a43fcbc4a8ebbd4d648ecdc1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '79efc65d5d971886cde6620c130a7342ab3fbe97a43fcbc4a8ebbd4d648ecdc1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El català o el castellà, indistintament, segons el criteri de cada òrgan.', false), ('B', 'El castellà, llevat que tots els interessats acceptin el català.', false), ('C', 'El català.', true), ('D', 'La llengua que triï el ciutadà afectat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 11 de la Llei 1/1998, de política lingüística, quin nivell de coneixement de les llengües oficials ha de tenir el personal al servei de les administracions públiques de Catalunya?', 'L''art. 11.1 exigeix un coneixement adequat i suficient de les dues llengües oficials, oral i escrit, apte per a les funcions del lloc. L''art. 11.3 obliga a acreditar el coneixement del català en el procés de selecció.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 11.1 Llei 1/1998', 'El personal al servicio de las Administraciones, las Corporaciones y las instituciones públicas de Cataluña debe tener un nivel de conocimiento adecuado y suficiente de las dos lenguas oficiales, tanto en la expresión oral como en la escrita, que lo haga apto para desarrollar las funciones propias de su puesto de trabajo.', null, '171bb985c9af424bfef5ba2e541cc35d48f6853aca002a5a1255b3912c8eb098', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '171bb985c9af424bfef5ba2e541cc35d48f6853aca002a5a1255b3912c8eb098')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un nivell avançat de català, i del castellà només quan el lloc de treball impliqui atenció al públic.', false), ('B', 'Un nivell bàsic de català en l''expressió oral, sense exigència en l''expressió escrita.', false), ('C', 'El nivell que determini cada departament, sense que calgui acreditar-lo en el procés de selecció.', false), ('D', 'Un nivell de coneixement adequat i suficient de les dues llengües oficials, tant en l''expressió oral com en l''escrita, que el faci apte per a les funcions del lloc de treball.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10.2 de la Llei 1/1998, de política lingüística, quan una persona interessada en un procediment administratiu demana un testimoni traduït a la llengua oficial que sol·licita, quina de les afirmacions següents és correcta?', 'L''art. 10.2 obliga l''Administració a lliurar el testimoni traduït del que afecta l''interessat i precisa que la sol·licitud no pot suposar perjudici, despesa, retards ni suspensió de la tramitació o dels terminis.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 10.2 Llei 1/1998', 'La Administración ha de entregar a las personas interesadas que lo requieran, en la lengua oficial solicitada, un testimonio traducido de aquello que les afecta. La solicitud de traducción no puede suponer ningún perjuicio o gasto al solicitante ni retrasos en el procedimiento ni suspender su tramitación ni los plazos establecidos.', null, '1241d34f9808458596ab416e1a6430761034525eeb7b3e985260171d1247c465', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1241d34f9808458596ab416e1a6430761034525eeb7b3e985260171d1247c465')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sol·licitud no li pot suposar cap perjudici ni despesa, ni retards en el procediment, ni suspendre''n la tramitació ni els terminis.', true), ('B', 'La sol·licitud suspèn el termini per resoldre fins que es lliuri la traducció.', false), ('C', 'La persona interessada ha d''avançar el cost de la traducció, que se li reintegra si el procediment li és favorable.', false), ('D', 'L''Administració només està obligada a lliurar-lo si el procediment s''ha iniciat a instància de part.', false)) as v(label, body, ok)
)
