with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la Llei 1/1998, de política lingüística, quina és la llengua pròpia de Catalunya?', 'L''art. 2.1 declara el català llengua pròpia de Catalunya; l''art. 3.1 afegeix que el català és llengua oficial de Catalunya, com també ho és el castellà.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 2.1 Llei 1/1998', 'El catalán es la lengua propia de Cataluña y la singulariza como pueblo.', null, '9fa245b2313f960de3563ac92b1fd3e8b230de9367132ce5f311198bad4be722', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9fa245b2313f960de3563ac92b1fd3e8b230de9367132ce5f311198bad4be722')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El català i el castellà, en igualtat de condicions.', false), ('B', 'El català, l''aranès i el castellà.', false), ('C', 'La que determini cada administració en el seu àmbit.', false), ('D', 'El català, que la singularitza com a poble.', true)) as v(label, body, ok)
)
