with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels següents NO és un dels drets lingüístics que l''article 4.1 de la Llei 1/1998, de política lingüística, reconeix a totes les persones a Catalunya?', 'L''art. 4.1 reconeix el dret a conèixer les dues llengües oficials, a expressar-s''hi, a ser ateses en qualsevol d''elles, a utilitzar-les lliurement i a no ser discriminades per la llengua oficial que utilitzen. No hi figura cap complement retributiu.', 'pcat_e11_personal_penitenciari', (select id from public.topics where slug = 'pcat-e11-personal-penitenciari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 4.1 Llei 1/1998', 'a) Conocer las dos lenguas oficiales. b) Expresarse en cualquiera de las dos lenguas oficiales, oralmente y por escrito, en las relaciones y actos públicos y privados. c) Ser atendidas en cualquiera de las dos lenguas oficiales en los términos que la presente Ley establece. d) Utilizar libremente cualquiera de las dos lenguas oficiales en todos los ámbitos. e) No ser discriminadas por razón de la lengua oficial que utilizan.', null, 'dd03029b0c9e839f5f85e2fa0c3f11abfa140c74f543838cbaf24c6adbce8f00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dd03029b0c9e839f5f85e2fa0c3f11abfa140c74f543838cbaf24c6adbce8f00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conèixer les dues llengües oficials.', false), ('B', 'Expressar-se en qualsevol de les dues llengües oficials, oralment i per escrit.', false), ('C', 'No ser discriminades per raó de la llengua oficial que utilitzen.', false), ('D', 'Percebre un complement retributiu per acreditar el coneixement de les dues llengües oficials.', true)) as v(label, body, ok)
)
