with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4 de la LOGP, els interns han de mantenir una actitud normal de respecte i consideració amb els funcionaris i les autoritats:', 'L''art. 4.1 c) LOGP estén el deure de respecte i consideració fora de l''establiment amb ocasió de trasllats, conduccions o pràctica de diligències.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 4.Uno.c LOGP', 'c) Mantener una normal actitud de respeto y consideración con los funcionarios de instituciones penitenciarias y autoridades judiciales o de otro orden, tanto dentro de los establecimientos penitenciarios como fuera de ellos con ocasión de traslado, conducciones o prácticas de diligencias.', null, '4e9aeb243c220debc8ca0257bb59e17997b5e33d56f1dc7de92a47d8e413aab8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e9aeb243c220debc8ca0257bb59e17997b5e33d56f1dc7de92a47d8e413aab8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només dins dels establiments penitenciaris.', false), ('B', 'Només durant les comunicacions i visites.', false), ('C', 'Dins dels establiments i, fora, només si estan classificats en primer grau.', false), ('D', 'Tant dins dels establiments com fora, amb ocasió de trasllats, conduccions o pràctica de diligències.', true)) as v(label, body, ok)
)
