with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LOGP, respecte a les prestacions de la Seguretat Social, s''han d''adoptar les mesures necessàries perquè:', 'L''art. 3.2 LOGP disposa que s''adoptaran les mesures necessàries perquè els interns i els seus familiars conservin els drets a les prestacions de la Seguretat Social adquirits abans de l''ingrés.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.Dos LOGP', 'Dos. Se adoptarán las medidas necesarias para que los internos y sus familiares conserven sus derechos a las prestaciones de la Seguridad Social, adquiridos antes del ingreso en prisión.', null, 'ec956754bf5a0452491c42cb25c0b967c84fbba6d46a24641c486074b2a0ea18', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec956754bf5a0452491c42cb25c0b967c84fbba6d46a24641c486074b2a0ea18')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els interns i els seus familiars conservin els drets a les prestacions adquirits abans de l''ingrés a la presó.', true), ('B', 'Els interns perdin el dret a les prestacions mentre durin la condemna, però no els seus familiars.', false), ('C', 'Només els interns penats conservin els drets adquirits.', false), ('D', 'Els interns adquireixin nous drets només si treballen en tallers productius.', false)) as v(label, body, ok)
)
