with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LOGP, què s''esdevé amb els procediments que l''intern tenia pendents en el moment d''ingressar a la presó?', 'L''art. 3.3 LOGP disposa que en cap cas s''impedirà que els interns continuïn els procediments pendents ni que entaulin noves accions.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.Tres LOGP', 'Tres. En ningún caso se impedirá que los internos continúen los procedimientos que tuvieren pendientes en el momento de su ingreso en prisión y puedan entablar nuevas acciones.', null, '2b4edff4aba45f424046cc2b8d1b50903e024ab5c88a4eb0cc137fbae42cac1b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2b4edff4aba45f424046cc2b8d1b50903e024ab5c88a4eb0cc137fbae42cac1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Queden suspesos fins que l''intern obtingui la llibertat.', false), ('B', 'Només els pot continuar si el jutge de vigilància ho autoritza.', false), ('C', 'Els pot continuar, però no pot entaular noves accions mentre estigui intern.', false), ('D', 'En cap cas s''impedirà que els continuï ni que pugui entaular noves accions.', true)) as v(label, body, ok)
)
