  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 3 de la LOGP, per què ha de vetllar l''Administració penitenciària respecte dels interns?', 'L''art. 3.4 LOGP estableix que l''Administració penitenciària vetllarà per la vida, la integritat i la salut dels interns.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.Cuatro LOGP', 'Cuatro. La Administración penitenciaria velará por la vida, integridad y salud de los internos.', null, '65fe68d415bd036a8b7c813fe1d8b0cd65b2141eb85ca443faea4cb8353cab2a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '65fe68d415bd036a8b7c813fe1d8b0cd65b2141eb85ca443faea4cb8353cab2a')
  returning id
), o as (
