  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només per la seva seguretat durant les conduccions.', false), ('B', 'Per la seva vida, integritat i salut.', true), ('C', 'Per la seva reinserció laboral després de la llibertat.', false), ('D', 'Per la conservació dels seus béns fora de l''establiment.', false)) as v(label, body, ok)
)
