with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 22 de la LOGP, qui pot ordenar per raons d''higiene la inutilització de les robes i els efectes contaminats propietat dels interns?', 'L''art. 22.2 LOGP atribueix aquesta facultat al director, a instància del metge.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 22.Dos LOGP', 'Dos. El Director, a instancia del Médico, podrá ordenar por razones de higiene la inutilización de las ropas y efectos contaminados propiedad de los internos.', null, '53b93221627f24db2bc0017c87ac4f6bfd0f7b4ea3e9b2c6ee611a028144300c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '53b93221627f24db2bc0017c87ac4f6bfd0f7b4ea3e9b2c6ee611a028144300c')
  returning id
