with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''article 26 de la LOGP considera el treball com un dret i un deure de l''intern i com un element fonamental del tractament. Quina de les condicions següents NO és una de les que estableix aquest article?', 'L''art. 26 a) LOGP disposa expressament que el treball no tindrà caràcter aflictiu ni s''aplicarà com a mesura de correcció.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 26 LOGP', 'a) No tendrá carácter aflictivo ni será aplicado como medida de corrección. b) No atentará a la dignidad del interno.', null, '332813b0b81616c7b4a63f46fc4c1eb263db92de1b54bd4e3ec73f9df6021723', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '332813b0b81616c7b4a63f46fc4c1eb263db92de1b54bd4e3ec73f9df6021723')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No atemptarà contra la dignitat de l''intern.', false), ('B', 'Gaudirà de la protecció dispensada per la legislació vigent en matèria de Seguretat Social.', false), ('C', 'Es pot aplicar com a mesura de correcció quan l''intern incompleixi les normes de règim interior.', true), ('D', 'No se supeditarà a l''assoliment d''interessos econòmics per l''Administració.', false)) as v(label, body, ok)
)
