with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 50 de la LOGP, com es poden presentar les peticions i queixes que els interns formulin per escrit al director o directora?', 'L''art. 50.1 LOGP permet presentar les peticions i queixes escrites en plec tancat, que es lliura sota rebut.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 50.Uno LOGP', 'Si fueren hechas por escrito, podrán presentarse en pliego cerrado, que se entregará bajo recibo.', null, '6248e54f072d53d822cebbac3974e1178bcbd4fd7480e47e25528a021c2350c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6248e54f072d53d822cebbac3974e1178bcbd4fd7480e47e25528a021c2350c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només per mitjà del funcionari encarregat de la unitat, que n''ha de verificar el contingut.', false), ('B', 'Obligatòriament a través del registre general de la Generalitat.', false), ('C', 'En plec tancat, que s''ha de lliurar sota rebut.', true), ('D', 'En sobre obert perquè el cap de serveis en pugui fer la revisió prèvia.', false)) as v(label, body, ok)
)
