with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 76 de la LOGP, sobre quines peticions o queixes dels interns ha d''acordar el que escaigui el jutge de vigilància?', 'L''art. 76.2 g) LOGP atribueix al jutge de vigilància les peticions o queixes sobre règim i tractament quan afectin drets fonamentals o drets i beneficis penitenciaris. És una peça clau del sistema de garanties dels drets dels interns.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 76.2.g LOGP', 'g) Acordar lo que proceda sobre las peticiones o quejas que los internos formulen en relación con el régimen y el tratamiento penitenciario en cuanto afecte a lo derechos fundamentales o a los derechos y beneficio penitenciarios de aquéllos.', null, 'fafd6f0a1aa977a610e16294e5ba9b7c9b058b47c8d44a0c1fc3dc8c241fcbd9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fafd6f0a1aa977a610e16294e5ba9b7c9b058b47c8d44a0c1fc3dc8c241fcbd9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Totes les relatives a l''alimentació i a les condicions materials de vida del centre.', false), ('B', 'Les relatives al règim i al tractament penitenciari en tant que afectin els drets fonamentals o els drets i beneficis penitenciaris dels interns.', true), ('C', 'Només les que el director o directora del centre hagi desestimat prèviament.', false), ('D', 'Exclusivament les relatives a les sancions d''aïllament.', false)) as v(label, body, ok)
)
