with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1 de la LOGP, quin és el fi primordial de les institucions penitenciàries?', 'L''art. 1 LOGP fixa com a fi primordial la reeducació i la reinserció social dels sentenciats, juntament amb la retenció i custòdia de detinguts, presos i penats; també els encarrega una labor assistencial i d''ajuda per a interns i alliberats.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 1 LOGP', 'Las instituciones penitenciarias reguladas en la presente Ley tienen como fin primordial la reeducación y la reinserción social de los sentenciados a penas y medidas penales privativas de libertad, así como la retención y custodia de detenidos, presos y penados.', null, '1b605294b74c0eaa46d921c8c25ce400be32fe33321baa89473fb98c89c6091b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1b605294b74c0eaa46d921c8c25ce400be32fe33321baa89473fb98c89c6091b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La retenció i custòdia dels detinguts i presos, i la intimidació dels possibles infractors.', false), ('B', 'El càstig proporcionat dels penats i la reparació del dany causat a la víctima.', false), ('C', 'L''aïllament dels penats perillosos respecte de la resta de la societat.', false), ('D', 'La reeducació i la reinserció social dels sentenciats a penes i mesures penals privatives de llibertat, i també la retenció i custòdia de detinguts, presos i penats.', true)) as v(label, body, ok)
)
