  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 5 de la LOGP, quin principi ha de presidir el règim penitenciari dels preventius?', 'L''art. 5 LOGP disposa que el règim de presó preventiva té per objecte retenir l''intern a disposició de l''autoritat judicial i que el principi de presumpció d''innocència presideix el règim dels preventius.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 5 LOGP', 'El principio de la presunción de inocencia presidirá el régimen penitenciario de los preventivos.', null, 'a2a004d3db341bc57ce485013f11d8edfe00b707a87a2f2adb52272be4c32951', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2a004d3db341bc57ce485013f11d8edfe00b707a87a2f2adb52272be4c32951')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El principi de presumpció d''innocència.', true), ('B', 'El principi d''individualització científica.', false), ('C', 'El principi de flexibilitat.', false), ('D', 'El principi de mínima intervenció.', false)) as v(label, body, ok)
)
