  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 de la LOGP, sobre la roba dels interns, assenyaleu la resposta correcta.', 'L''art. 20.1 LOGP reconeix el dret a vestir les pròpies peces adequades o les que faciliti l''establiment, que han de ser correctes i sense elements que afectin la dignitat. En les sortides a l''exterior han de dur roba que no en denoti la condició de reclusos (art. 20.2).', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 20.Uno LOGP', 'El interno tiene derecho a vestir sus propias prendas, siempre que sean adecuadas u optar por las que le facilite el establecimiento', null, '405255d142a16026e8cc50514f59fc4471667e7a778414af21873a49c28ca3b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '405255d142a16026e8cc50514f59fc4471667e7a778414af21873a49c28ca3b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''intern ha de vestir obligatòriament l''uniforme que li faciliti l''establiment.', false), ('B', 'L''intern té dret a vestir les seves pròpies peces, sempre que siguin adequades, o optar per les que li faciliti l''establiment.', true), ('C', 'L''intern només pot vestir les seves pròpies peces si està classificat en tercer grau.', false), ('D', 'L''intern pot vestir les seves pròpies peces només amb l''autorització del jutge de vigilància.', false)) as v(label, body, ok)
)
