  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pel cap de serveis.', false), ('B', 'Per la comissió d''interns de serveis alimentaris.', false), ('C', 'Pel metge.', true), ('D', 'Pel gerent del centre.', false)) as v(label, body, ok)
)
