with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 de la LOGP, què ha de garantir l''Administració en matèria d''assistència religiosa?', 'L''art. 54 LOGP obliga l''Administració a garantir la llibertat religiosa dels interns i a facilitar els mitjans per exercir-la.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 54 LOGP', 'La Administración garantizará la libertad religiosa de los internos y facilitará los medios para que dicha libertad pueda ejercitarse.', null, '8032b05d0cf98316c54caa9c78d696f3759de23d3ab1fbfefd32e6537ff64945', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8032b05d0cf98316c54caa9c78d696f3759de23d3ab1fbfefd32e6537ff64945')
  returning id
), o as (
