with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LOGP, els interns poden exercir els drets civils, polítics, socials, econòmics i culturals. Què hi afegeix expressament la llei?', 'L''art. 3.1 LOGP permet l''exercici dels drets civils, polítics, socials, econòmics i culturals «sin exclusión del derecho de sufragio», excepte quan siguin incompatibles amb l''objecte de la detenció o el compliment de la condemna.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 3.Uno LOGP', 'Los internos podrán ejercitar los derechos civiles, políticos, sociales, económicos y culturales, sin exclusión del derecho de sufragio, salvo que fuesen incompatibles con el objeto de su detención o el cumplimiento de la condena.', null, 'b988a798099df00935654aeb2d2ff8feb847b0472e62def7ecd34dddcae18dd1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b988a798099df00935654aeb2d2ff8feb847b0472e62def7ecd34dddcae18dd1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que en queda exclòs, en tot cas, el dret de sufragi.', false), ('B', 'Que el dret de sufragi només el poden exercir els interns preventius.', false), ('C', 'Que el dret de sufragi requereix l''autorització prèvia del jutge de vigilància.', false), ('D', 'Que no queda exclòs el dret de sufragi, llevat que sigui incompatible amb l''objecte de la detenció o el compliment de la condemna.', true)) as v(label, body, ok)
)
