  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 19 de la LOGP, com ha de facilitar l''Administració als interns els serveis i articles d''higiene diària necessaris?', 'L''art. 19.3 LOGP exigeix una cura acurada de la higiene personal i, amb aquesta finalitat, obliga l''Administració a facilitar gratuïtament els serveis i articles d''higiene diària necessaris.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 19.Tres LOGP', 'A tal fin, la administración facilitará gratuitamente a los internos los servicios y artículos de aseo diario necesarios.', null, '856a2b598745d3947df297a2a8619737e67201ee563e93d3672fe8a3fe853d1b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '856a2b598745d3947df297a2a8619737e67201ee563e93d3672fe8a3fe853d1b')
  returning id
), o as (
