  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4 de la LOGP, què s''ha de procurar respecte de la col·laboració dels interns en el tractament penitenciari?', 'L''art. 4.2 LOGP no configura el tractament com un deure: disposa que es procurarà fomentar la col·laboració dels interns amb les tècniques i els mètodes prescrits segons el diagnòstic individualitzat.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 4.Dos LOGP', 'Se procurará fomentar la colaboración de los internos en el tratamiento penitenciario con arreglo a las técnicas y métodos que les sean prescritos en función del diagnóstico individualizado.', null, 'dbb23ca1e48256171d4ff0eecc6eb99cfe6476aca5f3aa790c9550dac7d7edfb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dbb23ca1e48256171d4ff0eecc6eb99cfe6476aca5f3aa790c9550dac7d7edfb')
  returning id
), o as (
