  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 29 de la LOGP, tots els penats tenen l''obligació de treballar d''acord amb les seves aptituds. Quin dels col·lectius següents NO n''està exceptuat?', 'L''art. 29.1 LOGP exceptua els sotmesos a tractament mèdic, els que tenen incapacitat permanent, els majors de 65 anys, els perceptors de jubilació, les dones embarassades durant el període legal i els que no poden treballar per força major. La classificació en primer grau no n''és una excepció.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 29.Uno LOGP', 'Quedarán exceptuados de esta obligación, sin perjuicio de poder disfrutar, en su caso, de los beneficios penitenciarios: a) Los sometidos a tratamiento médico por causas de accidente o enfermedad hasta que sean dados de alta. b) Los que padezcan incapacidad permanente para toda clase de trabajos. c) Los mayores de sesenta y cinco años. d) Los perceptores de prestaciones por jubilación.', null, 'da17cc44ddc2165e53b29f5c70d1f3c4ff8625756d123ae8ab4f352b93d15e5d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'da17cc44ddc2165e53b29f5c70d1f3c4ff8625756d123ae8ab4f352b93d15e5d')
  returning id
), o as (
