select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 73 de la LOGP, sobre la reintegració de qui ha complert la pena, assenyaleu la resposta correcta.', 'L''art. 73 LOGP disposa que qui ha complert la pena o ha extingit d''una altra manera la responsabilitat penal ha de ser plenament reintegrat en l''exercici dels seus drets i que els antecedents no poden ser en cap cas motiu de discriminació social o jurídica.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 73.Dos LOGP', 'Los antecedentes no podrán ser en ningún caso motivo de discriminación social o jurídica.', null, '458c079f8f3b74e7923f712df4e85ecee0f83da0c771fc44cbf137a8be60e086', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '458c079f8f3b74e7923f712df4e85ecee0f83da0c771fc44cbf137a8be60e086')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els antecedents poden justificar limitacions en l''accés a les prestacions públiques durant cinc anys.', false), ('B', 'La plena reintegració en els drets requereix la cancel·lació prèvia dels antecedents.', false), ('C', 'Els antecedents només es poden tenir en compte si el delit era greu.', false), ('D', 'Els antecedents no poden ser en cap cas motiu de discriminació social o jurídica.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 76.2 de la LOGP, quina de les atribucions següents NO correspon al jutge de vigilància?', 'Les tres últimes són atribucions del jutge de vigilància (art. 76.2 d, e i i). La classificació la resol el centre directiu (art. 103.4 RP); el jutge en coneix per via de recurs (art. 76.2 f).', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 76.2 LOGP', 'd) Aprobar las sanciones de aislamiento en celda de duración superior a catorce días. e) Resolver por vía de recurso las reclamaciones que formulen los internos sobre sanciones disciplinarias. […] i) Autorizar los permisos de salida cuya duración sea superior a dos días, excepto de los clasificados en tercer grado.', null, '5ac7727ab76d40dc6430ac1e93bfa9ea66648b903467e743644081bae7dedc1a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5ac7727ab76d40dc6430ac1e93bfa9ea66648b903467e743644081bae7dedc1a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dictar la resolució de classificació inicial dels penats.', true), ('B', 'Aprovar les sancions d''aïllament en cel·la de durada superior a catorze dies.', false), ('C', 'Resoldre per via de recurs les reclamacions dels interns sobre sancions disciplinàries.', false), ('D', 'Autoritzar els permisos de sortida de durada superior a dos dies, excepte els dels classificats en tercer grau.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 50 de la LOGP, davant de qui han de presentar els interns els recursos previstos en aquesta llei?', 'L''art. 50.2 LOGP disposa que els recursos es presenten davant del director, que els ha de fer arribar a l''autoritat judicial i lliurar-ne una còpia segellada a qui recorre.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 50.Dos LOGP', 'Si los internos interpusieren alguno de los recursos previstos en esta Ley, los presentarán asimismo ante el Director del establecimiento, quien los hará llegar a la autoridad judicial, entregando una copia sellada de los mismos al recurrente.', null, '8bd02946a546cefe624918ce1d1978d9bb718caff577b9291d058fba918d84f7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8bd02946a546cefe624918ce1d1978d9bb718caff577b9291d058fba918d84f7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Directament davant del Ministeri Fiscal, que els tramet al jutge.', false), ('B', 'Davant del cap de serveis, que els resol en primera instància.', false), ('C', 'Davant de la Junta de Tractament, que n''informa el jutge de vigilància.', false), ('D', 'Davant del director de l''establiment, que els fa arribar a l''autoritat judicial i lliura al recurrent una còpia segellada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 29 de la LOGP, durant quant de temps queden exceptuades de l''obligació de treballar les dones embarassades?', 'L''art. 29.1 e) LOGP exceptua les embarassades durant setze setmanes ininterrompudes, ampliables fins a divuit per part múltiple; la interessada distribueix el període, sempre que sis setmanes siguin immediatament posteriors al part.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 29.Uno.e LOGP', 'e) Las mujeres embarazadas durante dieciséis semanas ininterrumpidas ampliables por parto múltiple hasta dieciocho semanas. El período de excepción se distribuirá a opción de la interesada siempre que seis semanas sean inmediatamente posteriores al parto.', null, '3171256c3524c80470af9fb34fc3ae2f235b7f4f2ffa426aa902f4b3d5bbc059', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3171256c3524c80470af9fb34fc3ae2f235b7f4f2ffa426aa902f4b3d5bbc059')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Catorze setmanes ininterrompudes, de les quals sis han de ser immediatament posteriors al part.', false), ('B', 'Setze setmanes ininterrompudes, ampliables fins a divuit per part múltiple, de les quals sis han de ser immediatament posteriors al part.', true), ('C', 'Setze setmanes ininterrompudes, ampliables fins a vint per part múltiple, totes posteriors al part.', false), ('D', 'Tot l''embaràs i fins que el fill compleixi tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 33 de la LOGP, és embargable la retribució del treball dels interns?', 'L''art. 33.2 LOGP equipara l''embargabilitat de la retribució dels interns a la del salari del treballador lliure. L''art. 33.1 d) demana que contribueixin a les càrregues familiars i a les altres obligacions.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 33.Dos LOGP', 'La retribución del trabajo de los internos sólo será embargable en las condiciones y con los requisitos establecidos para el salario del trabajador libre.', null, '16fb66891dc34c11f5d8005ed3d5c521587ce9c5cf361fbe2e6814e0816dc4b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '16fb66891dc34c11f5d8005ed3d5c521587ce9c5cf361fbe2e6814e0816dc4b0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, en cap cas.', false), ('B', 'Sí, sense límit, per fer front a la responsabilitat civil derivada del delit.', false), ('C', 'Només en les condicions i amb els requisits establerts per al salari del treballador lliure.', true), ('D', 'Només amb l''autorització del jutge de vigilància.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 35 de la LOGP, dins de quin termini s''han d''inscriure a l''oficina d''ocupació els alliberats per tenir dret a la prestació per desocupació si no han rebut una oferta de treball adequada?', 'L''art. 35 LOGP reconeix el dret a la prestació per desocupació als alliberats inscrits a l''oficina d''ocupació dins dels quinze dies següents a l''excarceració que no hagin rebut una oferta de treball adequada.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 35 LOGP', 'Los liberados que se hayan inscrito en la oficina de empleo dentro de los quince días siguientes a su excarcelación y no hayan recibido una oferta de trabajo adecuada tendrán derecho a la prestación por desempleo', null, '484d9c9c449cd25ebe39fe03bf2866431a2a6c93809d36d8b3fa353573225d7d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '484d9c9c449cd25ebe39fe03bf2866431a2a6c93809d36d8b3fa353573225d7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins dels quinze dies següents a l''excarceració.', true), ('B', 'Dins dels trenta dies següents a l''excarceració.', false), ('C', 'Dins del mes anterior a l''excarceració.', false), ('D', 'Dins dels deu dies hàbils següents a l''excarceració.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 58 de la LOGP, els interns tenen dret a disposar de llibres, diaris i revistes de lliure circulació a l''exterior. Com se''n poden establir limitacions en casos concrets?', 'L''art. 58 LOGP admet limitacions en casos concrets quan ho aconsellin les exigències del tractament individualitzat, amb resolució motivada prèvia de l''equip d''observació i tractament.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 58 LOGP', 'Los internos tienen derecho a disponer de libros, periódicos y revistas de libre circulación en el exterior, con las limitaciones que, en casos concretos, aconsejen las exigencias del tratamiento individualizado, previa resolución motivada del equipo de observación y tratamiento del establecimiento.', null, '1e5b165ddd92ddee79cf4dc16462ae60fe38717c6118ae23ecfbe03b8bb9ac0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1e5b165ddd92ddee79cf4dc16462ae60fe38717c6118ae23ecfbe03b8bb9ac0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per decisió del cap de serveis, per raons de bon ordre.', false), ('B', 'Per resolució del jutge de vigilància, a proposta del director.', false), ('C', 'Per exigències del tractament individualitzat, amb resolució motivada prèvia de l''equip d''observació i tractament.', true), ('D', 'No s''hi pot establir cap limitació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 77 de la LOGP, a qui poden adreçar els jutges de vigilància propostes sobre l''organització dels serveis de vigilància, l''ordenació de la convivència interior o les activitats dels tallers i escoles?', 'L''art. 77 LOGP permet als jutges de vigilància dirigir-se a la Direcció General d''Institucions Penitenciàries amb propostes sobre els serveis de vigilància, la convivència interior, tallers, escola, assistència mèdica i religiosa i activitats regimentals i de tractament.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 77 LOGP', 'Los Jueces de Vigilancia podrán dirigirse a la Dirección General de Instituciones Penitenciarias, formulando propuestas referentes a la organización y desarrollo de los servicios de vigilancia, a la ordenación de la convivencia interior en los establecimientos', 'L''art. 77 LOGP esmenta la Direcció General d''Institucions Penitenciàries (Administració de l''Estat); a Catalunya l''òrgan equivalent és la direcció general competent en serveis penitenciaris del Departament de Justícia. Revisar si convé matisar l''enunciat.', '6a2a26bfbc4b5f204faba9cc05d309608c2cf6f8b6761593f8556aa638215704', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6a2a26bfbc4b5f204faba9cc05d309608c2cf6f8b6761593f8556aa638215704')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consell General del Poder Judicial.', false), ('B', 'A la Direcció General d''Institucions Penitenciàries.', true), ('C', 'Al Ministeri Fiscal.', false), ('D', 'Al Consell de Direcció de cada establiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 38 de la LOGP, com s''han de fer les visites dels fills menors que no superin els deu anys i no convisquin amb la mare al centre penitenciari?', 'L''art. 38.3 LOGP remet al reglament un règim específic de visites per a menors de fins a deu anys que no convisquin amb la mare, sense restriccions de freqüència i intimitat; la durada i l''horari s''ajusten a l''organització regimental.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 38.Tres LOGP', 'Estas visitas se realizarán sin restricciones de ningún tipo en cuanto a frecuencia e intimidad y su duración y horario se ajustará a la organización regimental de los establecimientos.', null, '0bb46c7cc217a7b544dead8976340aa9ececb1525b5095f52a35f7fa4f84b130', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0bb46c7cc217a7b544dead8976340aa9ececb1525b5095f52a35f7fa4f84b130')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una vegada al mes com a mínim, d''una a tres hores de durada.', false), ('B', 'Només en locutoris, amb separació física i control visual.', false), ('C', 'Amb l''autorització prèvia del jutge de vigilància en cada cas.', false), ('D', 'Sense restriccions de cap mena quant a freqüència i intimitat, amb durada i horari ajustats a l''organització regimental.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 22 de la LOGP, qui decideix sobre el destí dels medicaments que l''intern porta en el moment d''ingressar o que rep de l''exterior?', 'L''art. 22.3 LOGP atribueix la decisió al director, a instància de l''intern o del metge i sempre de conformitat amb el metge, i n''estableix quins pot conservar i quins queden dipositats a la infermeria.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 22.Tres LOGP', 'El Director, a instancia del interno o del Médico, y de conformidad con éste en todo caso, decidirá sobre el destino de los medicamentos que tuviere en su poder el interno en el momento del ingreso en el establecimiento o reciba del exterior', null, '8765d71db080466fd1b563c7f91f97419bef38b1e5791a842445fb893d47e35c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8765d71db080466fd1b563c7f91f97419bef38b1e5791a842445fb893d47e35c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director, a instància de l''intern o del metge i, en tot cas, d''acord amb el metge.', true), ('B', 'El metge, sense intervenció del director.', false), ('C', 'El cap de serveis, després de l''escorcoll d''ingrés.', false), ('D', 'La Junta de Tractament, amb informe de l''equip multidisciplinari.', false)) as v(label, body, ok)
)
