select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcat-e12-relacio-juridica-penitenciaria-rdtall-v1 (2 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 782/2001, de 6 de julio, relación laboral especial de los penados en talleres penitenciarios (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e12-relacio-juridica-penitenciaria', 'Tema 12. La relació jurídica penitenciària: drets i deures dels interns') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e12-relacio-juridica-penitenciaria' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reial decret 782/2001, que regula la relació laboral especial dels penats en els tallers penitenciaris, quin òrgan adjudica als interns els llocs de treball dels tallers productius?', 'L''art. 3.2 del RD 782/2001 atribueix l''adjudicació a la junta de tractament, segons un ordre de prelació que comença pels interns el programa individualitzat de tractament dels quals prevegi una activitat laboral. L''organisme autònom (o l''equivalent autonòmic) és l''ocupador i elabora la llista de vacants.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 3.2 RD 782/2001', 'La Junta de Tratamiento, como órgano administrativo competente, adjudicará los puestos a los internos, siguiendo el siguiente orden de prelación:', null, '567a1d196dca1c23f70c0a0196b8a00af7bf2392962f9b44c4a280bf2cad8067', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '567a1d196dca1c23f70c0a0196b8a00af7bf2392962f9b44c4a280bf2cad8067')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
