insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 del Reglament penitenciari, quan un intern presenta un escrit de queixa o de recurs adreçat al jutge de vigilància penitenciària en una oficina de registre de l''Administració penitenciària, en quin termini màxim s''ha de remetre al jutge?', 'L''art. 54.3 RP obliga a remetre l''escrit sense dilació i, en tot cas, en un termini màxim de tres dies, després de lliurar-ne rebut o còpia segellada a l''intern.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 54.3 RP', 'se remitirá, sin dilación y en todo caso en el plazo máximo de tres días, al Juez de Vigilancia Penitenciaria correspondiente.', null, 'df93c63e89444d203b90a2bf1826af9e8913d7030bef012083fbfc3c08222b72', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'df93c63e89444d203b90a2bf1826af9e8913d7030bef012083fbfc3c08222b72')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-quatre hores.', false), ('B', 'Cinc dies.', false), ('C', 'Deu dies.', false), ('D', 'Tres dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.3 del Reglament penitenciari, la vida en presó ha de prendre com a referència la vida en llibertat. Quina de les conseqüències següents NO s''hi esmenta?', 'L''art. 3.3 RP parteix que l''intern és subjecte de dret i continua formant part de la societat; per això cal reduir els efectes nocius de l''internament i afavorir els vincles socials, la participació d''entitats i l''accés a les prestacions públiques. Restringir els contactes exteriors hi és contrari.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.3 RP', 'el interno es sujeto de derecho y no se halla excluido de la sociedad, sino que continúa formando parte de la misma. En consecuencia, la vida en prisión debe tomar como referencia la vida en libertad, reduciendo al máximo los efectos nocivos del internamiento, favoreciendo los vínculos sociales, la colaboración y participación de las entidades públicas y privadas y el acceso a las prestaciones públicas.', null, '27efb8592d2bd38c21766fadbd6a5446fc8a0da8eebab560218eff9da99e53cd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '27efb8592d2bd38c21766fadbd6a5446fc8a0da8eebab560218eff9da99e53cd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Reduir al màxim els efectes nocius de l''internament.', false), ('B', 'Restringir els contactes amb l''exterior per afavorir l''adaptació de l''intern a la vida en presó.', true), ('C', 'Afavorir els vincles socials i la col·laboració i participació de les entitats públiques i privades.', false), ('D', 'Afavorir l''accés a les prestacions públiques.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 del Reglament penitenciari, quina de les finalitats següents NO correspon a l''activitat penitenciària?', 'L''art. 2 RP enumera com a fins la reeducació i reinserció social (fi primordial), la retenció i custòdia i l''assistència social dels interns, alliberats i familiars. La prevenció general per intimidació no hi figura.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 2 RP', 'La actividad penitenciaria tiene como fin primordial la reeducación y reinserción social de los sentenciados a penas y medidas de seguridad privativas de libertad, así como la retención y custodia de los detenidos, presos y penados y la asistencia social de los internos, liberados y de sus familiares.', null, '42bb46e07e464173f1ca09a443b4a06686230bf39ad952729820e8b2a84625f4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '42bb46e07e464173f1ca09a443b4a06686230bf39ad952729820e8b2a84625f4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La reeducació i la reinserció social dels sentenciats a penes i mesures de seguretat privatives de llibertat.', false), ('B', 'La retenció i custòdia dels detinguts, presos i penats.', false), ('C', 'La prevenció general per intimidació de la resta de la ciutadania.', true), ('D', 'L''assistència social dels interns, dels alliberats i dels seus familiars.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.4 del Reglament penitenciari, en quines condicions poden accedir els presos preventius a les activitats educatives, formatives, esportives i culturals del centre?', 'L''art. 3.4 RP permet als preventius accedir a aquestes activitats en les mateixes condicions que els penats, en la mesura que sigui compatible amb la seva situació processal.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.4 RP', 'En cuanto sea compatible con su situación procesal, los presos preventivos podrán acceder a las actividades educativas, formativas, deportivas y culturales que se celebren en el centro penitenciario, en las mismas condiciones que los penados.', null, '34e146ad5c656c989ab8e96cc8a3729a4d0efbad1ddc4180a68377820b0074e4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '34e146ad5c656c989ab8e96cc8a3729a4d0efbad1ddc4180a68377820b0074e4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només amb l''autorització prèvia del jutge o tribunal de qui depenen.', false), ('B', 'No hi poden accedir fins que no hi hagi sentència ferma.', false), ('C', 'Només si accepten el programa individualitzat de tractament.', false), ('D', 'En les mateixes condicions que els penats, en tant que sigui compatible amb la seva situació processal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 3.5 del Reglament penitenciari, mitjançant quins instruments poden dirigir els òrgans directius de l''Administració penitenciària les activitats dels òrgans que en depenen jeràrquicament?', 'L''art. 3.5 RP habilita els òrgans directius per dirigir l''activitat dels òrgans dependents mitjançant circulars, instruccions i ordres de servei; és la base de les circulars de la Direcció General (p. ex., la Circular 1/2008 o la 2/2017).', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 3.5 RP', 'Los órganos directivos de la Administración penitenciaria podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante circulares, instrucciones y órdenes de servicio.', null, 'deb7a60013d325907ce0669dae652995b93a259f486f2e0ee18c857e3603aa4b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'deb7a60013d325907ce0669dae652995b93a259f486f2e0ee18c857e3603aa4b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Circulars, instruccions i ordres de servei.', true), ('B', 'Decrets, ordres i resolucions.', false), ('C', 'Reials decrets i reglaments de règim interior.', false), ('D', 'Interlocutòries i providències.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4.2 a) del Reglament penitenciari, el dret dels interns a que l''Administració vetlli per la seva vida, integritat i salut comporta que en cap cas puguin ser:', 'L''art. 4.2 a) RP prohibeix les tortures, els maltractaments i el rigor innecessari en aplicar les normes. Els mitjans coercitius, els escorcolls i els trasllats són mesures previstes i regulades pel mateix Reglament.', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 4.2.a RP', 'sin que puedan, en ningún caso, ser sometidos a torturas, a malos tratos de palabra o de obra, ni ser objeto de un rigor innecesario en la aplicación de las normas.', null, '43a0ae5102e89d8190f0cdc5906674829ce76bc0c42ed267e3999f87a85f1a9b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '43a0ae5102e89d8190f0cdc5906674829ce76bc0c42ed267e3999f87a85f1a9b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sotmesos a escorcolls o a recomptes durant el descans nocturn.', false), ('B', 'Sotmesos a mitjans coercitius, sigui quina sigui la situació.', false), ('C', 'Traslladats a un altre centre sense el seu consentiment.', false), ('D', 'Sotmesos a tortures, a maltractaments de paraula o d''obra, ni ser objecte d''un rigor innecessari en l''aplicació de les normes.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4.2 del Reglament penitenciari, a qui es reconeix expressament el dret al tractament penitenciari i a les mesures que se''ls programin per assegurar-ne l''èxit?', 'L''art. 4.2 d) RP reconeix el dret al tractament i a les mesures programades «de los penados». Als preventius se''ls aplica el principi de presumpció d''innocència i un model individualitzat d''intervenció (art. 20.1 RP).', 'pcat_e12_relacio_juridica_penitenciaria', (select id from public.topics where slug = 'pcat-e12-relacio-juridica-penitenciaria'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 4.2.d RP', 'd) Derecho de los penados al tratamiento penitenciario y a las medidas que se les programen con el fin de asegurar el éxito del mismo.', null, '4f8faf8f2fa5d9188b6465c5219f62f56d235c343077fa584e8ad797f36e28c5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4f8faf8f2fa5d9188b6465c5219f62f56d235c343077fa584e8ad797f36e28c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Als penats.', true), ('B', 'A tots els interns, siguin preventius o penats.', false), ('C', 'Només als penats classificats en tercer grau.', false), ('D', 'Als detinguts i presos preventius.', false)) as v(label, body, ok)
)
