insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/1979, de 26 de septiembre, General Penitenciaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e13-regim-penitenciari-1', 'Tema 13. El règim penitenciari I: ingressos, llibertats, trasllats, comunicacions i queixes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e13-regim-penitenciari-1' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17 de la LOGP, quan ha de posar en llibertat el director de l''establiment els detinguts si no s''ha rebut manament o ordre de presó?', 'L''art. 17.2 LOGP obliga el director a posar en llibertat els detinguts si, passades les 72 hores següents a l''ingrés, no s''ha rebut el manament o l''ordre de presó (vegeu també l''art. 23.1 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 17.Dos LOGP', 'Los detenidos serán puestos en libertad por el Director del establecimiento si, transcurridas las setenta y dos horas siguientes al momento del ingreso, no se hubiere recibido mandamiento u orden de prisión.', null, '162747609fb422c7c4bc4716049e5bb25b6abd663bbf04c4d536a3f1b77cbbd9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '162747609fb422c7c4bc4716049e5bb25b6abd663bbf04c4d536a3f1b77cbbd9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un cop transcorregudes les vint-i-quatre hores següents a l''ingrés.', false), ('B', 'Un cop transcorreguts cinc dies des de l''ingrés.', false), ('C', 'Un cop transcorregudes les setanta-dues hores següents al moment de l''ingrés.', true), ('D', 'Mai sense una ordre judicial expressa de llibertat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 52 de la LOGP, en cas de defunció, malaltia o accident greu de l''intern, a qui ha d''informar el director?', 'L''art. 52.1 LOGP obliga el director a informar el familiar més pròxim o la persona designada per l''intern. L''art. 52.2 preveu que també s''informi l''intern de la defunció o malaltia greu d''un parent pròxim.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 52.Uno LOGP', 'En los casos de defunción, enfermedad o accidente grave del interno, el Director informará al familiar más próximo o a la persona designada por aquél.', null, 'c5b9bcfe3e16669f683d4140d631113090f79dc9718574c56911a5528cb9359a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c5b9bcfe3e16669f683d4140d631113090f79dc9718574c56911a5528cb9359a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només al jutge de vigilància penitenciària.', false), ('B', 'Al familiar més pròxim o a la persona que l''intern hagi designat.', true), ('C', 'Al Ministeri Fiscal i a l''autoritat consular.', false), ('D', 'A l''advocat defensor de l''intern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17 de la LOGP, quin d''aquests elements NO s''ha de lliurar a l''alliberat en el moment de l''excarceració?', 'L''art. 17.4 LOGP obliga a lliurar el saldo de peculi, els valors i efectes dipositats i una certificació del temps de privació de llibertat i de la qualificació professional; si no té mitjans, se li faciliten els necessaris per arribar a la residència.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 17.Cuatro LOGP', 'En el momento de la excarcelación se entregará al liberado el saldo de su cuenta de peculio, los valores y efectos depositados a su nombre, así como una certificación del tiempo que estuvo privado de libertad y cualificación profesional obtenida durante su reclusión', null, 'fd6e9bbf17f801d4be626ca70e1d74ac2f9eef35747796b96f0f1bedca5fe1f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fd6e9bbf17f801d4be626ca70e1d74ac2f9eef35747796b96f0f1bedca5fe1f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El saldo del seu compte de peculi.', false), ('B', 'Els valors i efectes dipositats al seu nom.', false), ('C', 'Una certificació del temps que ha estat privat de llibertat i de la qualificació professional obtinguda.', false), ('D', 'Una còpia completa de l''expedient personal i del protocol de personalitat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16 de la LOGP, en l''ingrés s''ha de fer una completa separació dels interns. Quin dels criteris de separació següents NO s''hi preveu?', 'L''art. 16 LOGP separa per sexe, situació processal (i primaris/reincidents), edat, malaltia o deficiència i delictes dolosos/imprudents. La nacionalitat no és criteri de separació.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 16 LOGP', 'b) Los detenidos y presos estarán separados de los condenados y, en ambos casos, los primarios de los reincidentes. c) Los jóvenes, sean detenidos, presos o penados, estarán separados de los adultos en las condiciones que se determinen reglamentariamente. d) Los que presenten enfermedad o deficiencias físicas o mentales estarán separados de los que puedan seguir el régimen normal del establecimiento. e) Los detenidos y presos por delitos dolosos estarán separados de los que estén por delitos de imprudencia.', null, 'e85a17f95929c26eff731ed2d832f0cfd4dd399ce2c6946b6f30160bfd5488e5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e85a17f95929c26eff731ed2d832f0cfd4dd399ce2c6946b6f30160bfd5488e5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els detinguts i presos han d''estar separats dels condemnats i, en tots dos casos, els primaris dels reincidents.', false), ('B', 'Els joves han d''estar separats dels adults.', false), ('C', 'Els estrangers han d''estar separats dels nacionals.', true), ('D', 'Els detinguts i presos per delictes dolosos han d''estar separats dels que ho estan per delictes d''imprudència.', false)) as v(label, body, ok)
)
