with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 del Reglament penitenciari, quan l''ordre de detenció prové de la Policia Judicial, quin dels extrems següents NO hi ha de constar expressament?', 'L''art. 15.2 RP exigeix que constin les dades identificatives, el delicte imputat, que es troba a disposició judicial i l''hora i el dia de venciment del termini màxim de detenció. La direcció pot denegar motivadament l''ingrés si no hi consten. L''advocat defensor no figura en la llista.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 15.2 RP', 'a) Datos identificativos del detenido. b) Delito imputado. c) Que se halla a disposición judicial. d) Hora y día de vencimiento del plazo máximo de detención.', null, '5fc918b44d7c7d1e1f5d15c6853958846b8e7d6ff925f17d65bcd5ed2f68c1ea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5fc918b44d7c7d1e1f5d15c6853958846b8e7d6ff925f17d65bcd5ed2f68c1ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les dades identificatives del detingut.', false), ('B', 'El delicte imputat.', false), ('C', 'L''hora i el dia de venciment del termini màxim de detenció.', false), ('D', 'El nom de l''advocat defensor designat pel detingut.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, en un cas de presentació voluntària en un centre penitenciari, quan s''ha d''excarcerar l''ingressat si no s''ha rebut la documentació que legalitzi l''ingrés?', 'El director ha de demanar el manament al jutge o tribunal dins les 24 hores següents a l''ingrés (art. 16.3 RP), però l''excarceració es produeix si, passades 72 hores, no ha arribat la documentació que legalitzi l''ingrés (art. 16.4 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 16.3 i 16.4 RP', 'Si, transcurrido el plazo de las setenta y dos horas siguientes al ingreso, no se hubiese recibido en el centro la documentación que legalice el mismo, se procederá a la excarcelación del ingresado.', null, '42abeabedf255cf2ac1094ae3bbfe0f107c31852acd0808a470dd1a388245e8a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '42abeabedf255cf2ac1094ae3bbfe0f107c31852acd0808a470dd1a388245e8a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un cop transcorregut el termini de les setanta-dues hores següents a l''ingrés.', true), ('B', 'Un cop transcorregut el termini de les vint-i-quatre hores següents a l''ingrés.', false), ('C', 'Un cop transcorregut el termini de les quaranta-vuit hores següents a l''ingrés.', false), ('D', 'Un cop transcorregut el termini de cinc dies des de l''ingrés.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 del Reglament penitenciari, quina és la durada màxima de l''estada dels preventius o penats al departament d''ingressos?', 'L''estada al departament d''ingressos és, com a màxim, de cinc dies i només es pot prorrogar per motius sanitaris o de seguretat de l''intern; de la pròrroga se n''informa el jutge de vigilància (art. 20.3 RP).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 20.3 RP', 'La estancia de preventivos o penados en el departamento de ingresos será, como máximo, de cinco días y sólo podrá prolongarse por motivos de orden sanitario o para preservar su seguridad. De la prolongación se dará cuenta al Juez de Vigilancia correspondiente.', null, 'cbec1cd5fd31d61b5a4a654488384516fadb4e73c429942026a25552b510bf4e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cbec1cd5fd31d61b5a4a654488384516fadb4e73c429942026a25552b510bf4e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres dies, prorrogables només per motius d''ordre sanitari.', false), ('B', 'Set dies, prorrogables per decisió de la junta de tractament.', false), ('C', 'Cinc dies, prorrogables només per motius d''ordre sanitari o per preservar-ne la seguretat.', true), ('D', 'Quinze dies, prorrogables per motius de seguretat.', false)) as v(label, body, ok)
)
