with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 38 del Reglament penitenciari, què ha de proporcionar l''establiment d''origen als interns conduïts?', 'L''art. 38.3 RP obliga l''establiment d''origen a proporcionar racionat en fred als interns conduïts; també hi ha d''acompanyar l''expedient mèdic (art. 38.4).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 38.3 RP', 'El establecimiento de origen proporcionará a los internos conducidos racionado en frío.', null, '5b6e54372eece1581fb85d578dc2f805785e397d0d188ccee3304be75d34c871', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5b6e54372eece1581fb85d578dc2f805785e397d0d188ccee3304be75d34c871')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Racionat en fred.', true), ('B', 'Un àpat calent a l''establiment de destinació.', false), ('C', 'Una quantitat de diners per comprar menjar durant el trajecte.', false), ('D', 'Res: l''alimentació durant la conducció correspon a la força conductora.', false)) as v(label, body, ok)
)
