with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 del Reglament penitenciari, quan la detenció ha estat acordada pel Ministeri Fiscal, què ha de constar en l''ordre?', 'L''art. 15.3 RP exigeix en l''ordre del Ministeri Fiscal les dades d''identificació de les diligències d''investigació i el moment de venciment del termini màxim de detenció; admès l''ingrés, s''aplica l''art. 23 RP.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 15.3 RP', 'Cuando la detención hubiese sido acordada por el Ministerio Fiscal, en la orden constarán los datos de identificación de las diligencias de investigación y el momento de vencimiento del plazo máximo de detención.', null, '8a2b2af27adf8339fde0bcc002f6dd55fabb79a5ff4c0fc065d74036b885bd1f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a2b2af27adf8339fde0bcc002f6dd55fabb79a5ff4c0fc065d74036b885bd1f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les dades d''identificació de les diligències d''investigació i el moment de venciment del termini màxim de detenció.', true), ('B', 'El nom del jutge de guàrdia i la qualificació jurídica definitiva dels fets.', false), ('C', 'La conformitat de l''advocat defensor i del detingut.', false), ('D', 'Només les dades identificatives del detingut.', false)) as v(label, body, ok)
)
