with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17 del Reglament penitenciari, a qui han de sol·licitar les internes que tenen a l''exterior fills menors de tres anys sota la seva pàtria potestat l''autorització perquè romanguin amb elles a l''interior del centre?', 'L''art. 17.2 RP atribueix la decisió al Consell de Direcció, que l''ha de concedir si s''acredita la filiació i que no hi ha risc per als menors; cal demanar l''opinió del Ministeri Fiscal i notificar-li la decisió.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 17.2 RP', 'Las internas que tuviesen en el exterior hijos menores de tres años bajo su patria potestad podrán solicitar del Consejo de Dirección autorización para que éstos permanezcan en su compañía en el interior del centro penitenciario', null, 'b64977c06f970679a0eace82bc1d7e22cd9c1b5e1c71aec741a87dba87f33003', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b64977c06f970679a0eace82bc1d7e22cd9c1b5e1c71aec741a87dba87f33003')
  returning id
), o as (
