with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 19 del Reglament penitenciari, si l''ordre d''ingrés disposa la incomunicació del detingut o pres, amb qui pot comunicar aquest?', 'L''art. 19.1 RP disposa que l''incomunicat ocupi una cel·la individual, sigui reconegut pel metge i atès exclusivament pels funcionaris encarregats, i que només comuniqui amb les persones que tinguin autorització expressa del jutge.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 19.1 RP', 'Únicamente podrá comunicar con las personas que tengan expresa autorización del Juez.', null, '630d8ccc82107f864dbf13a57bdc64fe3f0ed3035abe978fe665c960811649f0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '630d8ccc82107f864dbf13a57bdc64fe3f0ed3035abe978fe665c960811649f0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb els seus familiars, però no amb el seu advocat.', false), ('B', 'Amb qualsevol persona, si el director ho autoritza.', false), ('C', 'Únicament amb les persones que tinguin autorització expressa del jutge.', true), ('D', 'Amb els funcionaris i amb els altres interns del departament.', false)) as v(label, body, ok)
)
