with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 20.1 del Reglament penitenciari, a més de ser examinats pel metge, per quins professionals han de ser entrevistats els detinguts i presos al departament d''ingressos?', 'L''art. 20.1 RP preveu que els detinguts i presos siguin entrevistats pel treballador social i per l''educador per detectar àrees carencials i necessitats. Per als penats hi intervenen també el psicòleg i el jurista (art. 20.2).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 20.1 RP', 'Igualmente, serán entrevistados por el Trabajador Social y por el Educador, a fin de detectar las áreas carenciales y necesidades del interno', null, 'be9424a013f023f3c534d2a14a6f88245c04b0cc11662a0498eb8b12e5fd8b71', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'be9424a013f023f3c534d2a14a6f88245c04b0cc11662a0498eb8b12e5fd8b71')
