with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 22 del Reglament penitenciari, qui ha de fer una revisió completa de l''expedient personal de l''intern abans que el director estengui l''ordre de llibertat, per comprovar que no està subjecte a altres responsabilitats?', 'L''art. 22.3 RP encarrega la revisió de l''expedient al funcionari de l''Oficina de Règim. Després, el funcionari encarregat del servei o el que designi el cap de serveis identifica el que surt en llibertat i l''acompanya fins a la sortida (art. 22.4).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 22.3 RP', 'Antes de que el Director extienda la orden de libertad a que se refiere el apartado anterior, el funcionario encargado de la Oficina de Régimen procederá a realizar una completa revisión del expediente personal del interno', null, '1dcb6c22db59fefd06ef7cc63ff5d757b3e72068c0b62db1269c137548954c7e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1dcb6c22db59fefd06ef7cc63ff5d757b3e72068c0b62db1269c137548954c7e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis.', false), ('B', 'El jurista de l''equip multidisciplinari.', false), ('C', 'El funcionari encarregat de l''Oficina de Règim.', true), ('D', 'El funcionari que acompanya l''intern fins a la sortida.', false)) as v(label, body, ok)
)
