with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25 del Reglament penitenciari, quan l''alliberament definitiu d''un penat es produeix per aplicació de mesures de gràcia, què ha de fer el director?', 'L''art. 25 RP impedeix posar en llibertat els penats per mesures de gràcia sense ordre o manament escrit del tribunal sentenciador.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 25 RP', 'Cuando la liberación definitiva de los penados se produzca por aplicación de medidas de gracia, el Director del centro se abstendrá, en todo caso, de poner en libertad a los penados sin haber recibido orden o mandamiento por escrito del Tribunal sentenciador.', null, 'd247507cf14afa544bf740a0b6fbc73cf0ff6990320ee0a6362c1af715513178', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd247507cf14afa544bf740a0b6fbc73cf0ff6990320ee0a6362c1af715513178')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Posar-lo en llibertat immediatament un cop publicat l''indult al BOE.', false), ('B', 'Abstenir-se de posar-lo en llibertat sense haver rebut ordre o manament per escrit del tribunal sentenciador.', true), ('C', 'Posar-lo en llibertat amb l''autorització verbal del jutge de vigilància.', false), ('D', 'Comunicar-ho al Ministeri Fiscal i alliberar-lo si en tres dies no hi ha oposició.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 35 del Reglament penitenciari, qui acorda la sortida d''interns per a consulta o ingrés en centres hospitalaris no penitenciaris i què passa en cas d''urgència?', 'L''art. 35.1 RP atribueix la decisió al centre directiu; l''art. 35.3 permet al director, en casos d''urgència segons dictamen mèdic, fer la conducció i l''ingrés, donant-ne compte immediatament al centre directiu.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 35 RP', 'La salida de internos para consulta o ingreso, en su caso, en centros hospitalarios no penitenciarios será acordada por el centro directivo. […] En caso de urgencia, según dictamen médico, el Director procederá a la conducción e ingreso en el centro hospitalario, dando cuenta seguidamente al centro directivo.', null, 'f8538c2c342d6296af836804759287c7012f0141a1a79caa90515cf979b4dd27', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f8538c2c342d6296af836804759287c7012f0141a1a79caa90515cf979b4dd27')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acorda el jutge de vigilància; en cas d''urgència, el metge del centre.', false), ('B', 'L''acorda el director; en cas d''urgència, el cap de serveis sense necessitat de comunicar-ho.', false), ('C', 'L''acorda el centre directiu; en cas d''urgència, segons dictamen mèdic, el director fa la conducció i l''ingrés i en dona compte tot seguit al centre directiu.', true), ('D', 'L''acorda el Consell de Direcció; en cas d''urgència, la Junta de Tractament.', false)) as v(label, body, ok)
)
