with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 42 del Reglament penitenciari, què han de fer els visitants que no són familiars de l''intern per poder comunicar-hi oralment?', 'La norma 5a de l''art. 42 RP obliga els familiars a acreditar el parentiu i exigeix als visitants no familiars l''autorització del director per poder comunicar.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 42.5ª RP', 'Los familiares deberán acreditar el parentesco con los internos y los visitantes que no sean familiares habrán de obtener autorización del Director del establecimiento para poder comunicar.', null, 'acbe0982c1660fa03c2e2c480bdf40ce069f37b2e3a008b23e9d7343dd8c4aeb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'acbe0982c1660fa03c2e2c480bdf40ce069f37b2e3a008b23e9d7343dd8c4aeb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obtenir l''autorització del jutge de vigilància.', false), ('B', 'Acreditar un parentiu fins al quart grau.', false), ('C', 'Inscriure''s al Registre d''Entitats Col·laboradores.', false), ('D', 'Obtenir l''autorització del director de l''establiment.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 45 del Reglament penitenciari, quina limitació tenen els familiars o allegats que acudeixen a les comunicacions íntimes, familiars i de convivència?', 'L''art. 45.3 RP prohibeix als visitants portar bosses o paquets i, en les comunicacions íntimes, dur menors amb ells.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 45.3 RP', 'Los familiares o allegados que acudan a visitar a los internos en las comunicaciones previstas en este artículo no podrán ser portadores de bolsos o paquetes, ni llevar consigo a menores cuando se trate de comunicaciones íntimas.', null, 'd1aeee6ae861575e2f285a9eac6614cd58025cac8f58e5ce68422e85eab94180', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd1aeee6ae861575e2f285a9eac6614cd58025cac8f58e5ce68422e85eab94180')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No poden portar bosses o paquets, ni dur menors en el cas de les comunicacions íntimes.', true), ('B', 'No poden superar el nombre de dues persones en cap modalitat.', false), ('C', 'Han de ser sempre familiars en primer grau.', false), ('D', 'Han de tenir l''autorització prèvia del jutge de vigilància.', false)) as v(label, body, ok)
)
