with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 47 del Reglament penitenciari, es permeten les trucades des de l''exterior als interns?', 'L''art. 47.5 RP no permet trucades des de l''exterior als interns, excepte en casos excepcionals apreciats lliurement pel director.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 47.5 RP', 'Salvo casos excepcionales, libremente apreciados por el Director del establecimiento, no se permitirán llamadas desde el exterior a los internos.', null, 'b1bfe7ff21a190833f6e11fa07a797d97266ee69fa1df8c15b7f03b333b88f99', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b1bfe7ff21a190833f6e11fa07a797d97266ee69fa1df8c15b7f03b333b88f99')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, sempre que les pagui qui truca.', false), ('B', 'No, llevat de casos excepcionals apreciats lliurement pel director de l''establiment.', true), ('C', 'Sí, una per setmana com a màxim.', false), ('D', 'Només les de l''advocat defensor, sense limitació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
