with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53 del Reglament penitenciari, davant de quin d''aquests òrgans o persones NO es preveu que l''intern pugui formular les peticions i queixes sobre matèries de competència de l''Administració penitenciària?', 'L''art. 53.2 RP permet formular-les davant del funcionari encarregat de la dependència, del cap de serveis o del director (o de qui el substitueixi). Les peticions es poden fer verbalment o per escrit, en sobre tancat si es vol (art. 53.1).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 53.2 RP', 'Dichas peticiones y quejas podrán ser formuladas ante el funcionario encargado de la dependencia que al interno corresponda, ante el Jefe de Servicios o ante el Director del Centro o quien legalmente le sustituya.', null, '098f3404aa6824e555876745f0cc712a15f1d62ddeea5c7b192c0ab753e0cb7c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '098f3404aa6824e555876745f0cc712a15f1d62ddeea5c7b192c0ab753e0cb7c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Davant del funcionari encarregat de la dependència que correspongui a l''intern.', false), ('B', 'Davant de la Junta de Tractament.', true), ('C', 'Davant del cap de serveis.', false), ('D', 'Davant del director del centre o de qui legalment el substitueixi.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24 del Reglament penitenciari, què ha de fer el director si quinze dies abans de la data proposada per a la llibertat definitiva no ha rebut resposta del tribunal sentenciador?', 'L''art. 24.3 RP obliga a reiterar la proposta amb l''advertiment que, si no hi ha ordre expressa en contra, es procedirà a alliberar el reclús en la data proposada. La proposta inicial s''ha de fer amb dos mesos d''antelació (art. 24.2).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 24.3 RP', 'Si quince días antes de la fecha propuesta para la libertad definitiva no se hubiese recibido respuesta, el Director del establecimiento reiterará la propuesta al Tribunal sentenciador, significándole que, de no recibirse orden expresa en contrario, se procederá a liberar al recluso en la fecha propuesta.', null, 'a8ab27308eb30c413029027fff00635808ceee7e09c231766be215a54a9413fa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a8ab27308eb30c413029027fff00635808ceee7e09c231766be215a54a9413fa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Esperar la resposta del tribunal, sense alliberar el penat fins que no es rebi.', false), ('B', 'Sol·licitar l''aprovació de la llibertat al jutge de vigilància.', false), ('C', 'Prorrogar d''ofici la retenció fins a dos mesos més.', false), ('D', 'Reiterar la proposta al tribunal sentenciador, advertint que, si no rep ordre expressa en contra, alliberarà el reclús en la data proposada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
