with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 26 del Reglament penitenciari, quan el penat és un estranger subjecte a una mesura d''expulsió posterior al compliment de la condemna, amb quina antelació ha de notificar el director la data previsible d''extinció de la condemna a l''autoritat competent?', 'L''art. 26 RP fixa una antelació de tres mesos o el moment de la proposta de llibertat definitiva (que es fa amb un mínim de dos mesos, art. 24.2).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 26 RP', 'el Director notificará, con una antelación de tres meses o en el momento de formular la propuesta de libertad definitiva a que se refiere el artículo 24.2, la fecha previsible de extinción de la condena a la autoridad competente', null, 'f0474f613c9b331de61eed6caec3fcf4fb535b18ec96ed466cc10f7081b6cc0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f0474f613c9b331de61eed6caec3fcf4fb535b18ec96ed466cc10f7081b6cc0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb una antelació de tres mesos o en el moment de formular la proposta de llibertat definitiva.', true), ('B', 'Amb una antelació d''un mes.', false), ('C', 'Amb una antelació de sis mesos.', false), ('D', 'Amb una antelació de quinze dies.', false)) as v(label, body, ok)
)
