with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 36 del Reglament penitenciari, en quin cas es pot disposar el trasllat d''interns a càrrec de funcionaris d''institucions penitenciàries?', 'L''art. 36.2 RP fixa la regla general (custòdia de la força pública, generalment per carretera) i l''art. 36.3 admet, excepcionalment i per urgència o necessitat peremptòria, el trasllat a càrrec de funcionaris de servei designats pel director.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 36.3 RP', 'Excepcionalmente y sólo en casos de urgencia o necesidad perentoria, podrá disponerse el traslado de internos a cargo de los funcionarios de instituciones penitenciarias que el Director del establecimiento designe entre los que se hallen de servicio.', null, '9c3d7e3960abf42a8d125f60df8770a3643d28b239c250149c8d24a4d5b329ce', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9c3d7e3960abf42a8d125f60df8770a3643d28b239c250149c8d24a4d5b329ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre que l''intern estigui classificat en segon o tercer grau.', false), ('B', 'Quan el trasllat sigui dins de la mateixa província.', false), ('C', 'Quan ho sol·liciti l''intern i n''assumeixi el cost.', false), ('D', 'Excepcionalment i només en casos d''urgència o necessitat peremptòria, amb els funcionaris que el director designi entre els que estiguin de servei.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
