  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els classificats en tercer grau i els classificats en segon grau que gaudeixin de permisos ordinaris.', true), ('B', 'Només els classificats en tercer grau en règim obert restringit.', false), ('C', 'Tots els penats que no tinguin sancions pendents de complir.', false), ('D', 'Els preventius amb una pena sol·licitada inferior a cinc anys.', false)) as v(label, body, ok)
)
