with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 46 del Reglament penitenciari, com es pot intervenir la correspondència entre interns de centres penitenciaris diferents?', 'La norma 7a de l''art. 46 RP permet que el director intervingui aquesta correspondència per resolució motivada; es cursa a través de la direcció del centre d''origen, es notifica a l''intern i se''n dona coneixement al jutge de vigilància.', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 46.7ª RP', 'La correspondencia entre los internos de distintos centros penitenciarios podrá ser intervenida mediante resolución motivada del Director y se cursará a través de la Dirección del establecimiento de origen. Efectuada dicha intervención se notificará al interno y se pondrá en conocimiento del Juez de Vigilancia.', null, '844a516e7c247357e4a50d37a05a51236795d1be66ec7454e7e46ed9053ba071', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '844a516e7c247357e4a50d37a05a51236795d1be66ec7454e7e46ed9053ba071')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només per ordre de l''autoritat judicial.', false), ('B', 'Per decisió del cap de serveis, que n''informa el director l''endemà.', false), ('C', 'Mitjançant resolució motivada del director; s''ha de notificar a l''intern i posar en coneixement del jutge de vigilància.', true), ('D', 'Per acord de la Junta de Tractament, amb informe de l''equip multidisciplinari.', false)) as v(label, body, ok)
)
