with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 51 del Reglament penitenciari, què es fa amb els articles o objectes no autoritzats intervinguts que ningú no ha reclamat?', 'L''art. 51.3 RP preveu la publicació d''una relació al tauler d''anuncis passats tres mesos i la destrucció passats quinze dies, excepte els objectes de valor (art. 317 RP). Els productes peribles es destrueixen (art. 51.2).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 51.3 RP', 'Transcurrido un plazo de tres meses desde su recepción, se colocará una relación de tales artículos u objetos en el tablón de anuncios al público, invitando a que los mismos sean retirados, con la advertencia de que, transcurridos quince días desde la publicación, se procederá a su destrucción', null, 'cda63c119f6e4f12b18c6796f5de1f8e975f211f80ed44ef7de98bef4cdbe35c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cda63c119f6e4f12b18c6796f5de1f8e975f211f80ed44ef7de98bef4cdbe35c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Passats tres mesos des de la recepció, se''n publica una relació al tauler d''anuncis i, si no es retiren en quinze dies, es destrueixen, llevat dels objectes de valor.', true), ('B', 'Passat un mes, es lliuren a una entitat benèfica.', false), ('C', 'Passats sis mesos, es venen i l''import s''ingressa al compte de peculi de l''intern.', false), ('D', 'Es destrueixen immediatament, sigui quina sigui la seva naturalesa.', false)) as v(label, body, ok)
)
