with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 58 del Reglament penitenciari, què han de fer els consells de direcció si cap dels interns que volen participar en les comissions no és elegit per més d''un quinze per cent dels interns de la unitat?', 'L''art. 58.1 RP preveu el sorteig entre els interns que volen participar quan cap no supera el 15 % dels vots. En cas d''alteració de l''ordre o d''irregularitats, el Consell de Direcció pot suspendre el procés (art. 58.2).', 'pcat_e13_regim_penitenciari_1', (select id from public.topics where slug = 'pcat-e13-regim-penitenciari-1'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 58.1 RP', 'Si ninguno de los internos que deseen participar en las Comisiones resultase elegido por más de un quince por ciento de los internos de la unidad, los Consejos de Dirección procederán a sortear entre los mismos', null, 'db6291be1b1ffd745a00597b05b8368fcb4bf9d73328b98f770018e153215d8c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db6291be1b1ffd745a00597b05b8368fcb4bf9d73328b98f770018e153215d8c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Designar directament els interns amb més antiguitat al centre.', false), ('B', 'Deixar la comissió sense constituir fins a l''any següent.', false), ('C', 'Fer un sorteig entre aquests interns per designar qui ha de col·laborar en les activitats fins a una nova convocatòria.', true), ('D', 'Encomanar les funcions de la comissió als educadors del centre.', false)) as v(label, body, ok)
)
