with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008 sobre escorcolls i aplicació de mitjans de control adequats, quina de les dades següents NO s''exigeix que consti en el comunicat que s''ha de fer dels escorcolls?', 'Segons l''apartat 1.3 de la Circular 1/2008, el comunicat el signen els funcionaris que han fet l''escorcoll i s''adreça al cap de serveis. Hi ha de constar el nom de l''intern, el lloc i la data, el cap de serveis present o la persona delegada, la motivació del nu integral i el resultat. No s''hi exigeix la signatura de l''intern.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.3', 'Dels escorcolls que es facin, s''han de fer comunicats, que han de signar els funcionaris que els hagin portat a terme i que s''han d''adreçar al cap de serveis. En aquests comunicats, hi ha de constar el nom de l''intern, el lloc i la data de l''escorcoll, el/la cap de serveis present durant l''escorcoll o persona en qui hagi delegat, la motivació suficient de l''escorcoll amb nu integral i el resultat del mateix', null, '7adb9d7c35119f65f4310d97b661652faa53eedaa45be2f56472b091bfe9434b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7adb9d7c35119f65f4310d97b661652faa53eedaa45be2f56472b091bfe9434b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El nom de l''intern i el lloc i la data de l''escorcoll.', false), ('B', 'El cap de serveis present durant l''escorcoll o la persona en qui hagi delegat.', false), ('C', 'La signatura de conformitat de l''intern escorcollat.', true), ('D', 'La motivació suficient de l''escorcoll amb nu integral i el resultat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, sota la supervisió i presència de qui s''han de fer els escorcolls amb nu integral dels interns?', 'L''apartat 1.2.3 de la Circular 1/2008 exigeix la supervisió i la presència d''un cap de serveis del mateix gènere que l''intern. Si no hi pot ser objectivament, ho delega en el cap d''unitat o en un altre que designi, però continua sent responsable de la supervisió.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.3', 'Aquests escorcolls s’hauran de realitzar sota la supervisió i presència d’un cap de serveis del mateix gènere que el del/ de la intern/interna sobre el que s’ha de practicar l’escorcoll. Si un cap de serveis no pogués objectivament estar present ho delegarà en el cap d’unitat del departament corresponent o en un altre que designi', null, '7b831e86634541a415b0db818fcea1d04f982425c92a2ccb3116e9b262cce5b1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7b831e86634541a415b0db818fcea1d04f982425c92a2ccb3116e9b262cce5b1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del director del centre o, en la seva absència, del subdirector d''interior.', false), ('B', 'Del metge de guàrdia del centre penitenciari.', false), ('C', 'D''un cap de serveis del mateix gènere que l''intern o la interna. Si no hi pot ser objectivament, ho delega en el cap d''unitat del departament o en un altre que designi.', true), ('D', 'D''un funcionari de qualsevol gènere designat pel cap d''unitat, sense necessitat de delegació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
