with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què s''entén per escorcoll superficial d''un intern?', 'L''apartat 1.1 de la Circular 1/2008 considera l''escorcoll superficial i el dels efectes personals el supòsit normal o general. L''escorcoll superficial és la palpació de l''esquema corporal de la persona.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.1', 'El supòsit normal o general és l’escorcoll superficial de la persona i el dels seus efectes personals. Per escorcoll superficial s’entén la palpació de l’esquema corporal de la persona.', null, '63a6114b2b51c037b516a15b3e7762d9a793ec38a2848f5b20a0aab6c0eace31', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '63a6114b2b51c037b516a15b3e7762d9a793ec38a2848f5b20a0aab6c0eace31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El despullament parcial de la persona en una dependència tancada.', false), ('B', 'La palpació de l''esquema corporal de la persona.', true), ('C', 'La inspecció visual del cos de l''intern després de lliurar-li una bata.', false), ('D', 'La realització de proves radiològiques amb el consentiment de l''intern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què cal per fer proves radiològiques a un intern quan no les accepta voluntàriament?', 'Segons l''apartat 1.4 de la Circular 1/2008, si l''intern no hi consent, sempre cal que el jutjat de guàrdia autoritzi la proposta motivada de la direcció del centre. La proposta ha d''expressar l''excepcionalitat, la necessitat i la proporcionalitat de la mesura.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.4', 'Pel que fa a les proves radiològiques, excepte en els casos que l’intern ho accepti voluntàriament, sempre és necessari que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre', null, 'ec8526e7067974dad7db0fd4e165d9a0cbe0c547489bb584d9f4e6b15ad64703', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec8526e7067974dad7db0fd4e165d9a0cbe0c547489bb584d9f4e6b15ad64703')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el jutjat de guàrdia autoritzi la proposta formulada prèviament per la direcció del centre.', true), ('B', 'Que el cap de serveis l''autoritzi per escrit i en doni compte al director.', false), ('C', 'Que el jutge de vigilància penitenciària l''autoritzi a proposta de la junta de tractament.', false), ('D', 'Que el metge del centre l''autoritzi i en doni compte al centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què passa si una persona autoritzada a comunicar amb un intern es nega a sotmetre''s a l''escorcoll amb nu integral acordat d''acord amb l''article 68 del Reglament penitenciari?', 'L''apartat 2.2 de la Circular 1/2008, d''acord amb l''art. 45.7 RP, disposa que, si el visitant es nega a l''escorcoll, la comunicació no es fa, sens perjudici de les mesures que corresponguin si els fets poden ser constitutius de delicte.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 2.2; art. 45.7 RP', 'En el cas que el visitant es negui a realitzar l’escorcoll, la comunicació no es durà a terme, sense perjudici de les mesures que es puguin adoptar en el cas que els fets puguin ser constitutius de delicte.', null, '709a7c6e0bc1a1a43de9c9f2bb885662a75ab09e3bc200c563554bc864b89f07', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '709a7c6e0bc1a1a43de9c9f2bb885662a75ab09e3bc200c563554bc864b89f07')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La comunicació no es fa, sens perjudici de les mesures que es puguin adoptar si els fets poden ser constitutius de delicte.', true), ('B', 'La comunicació es fa igualment, però en un locutori amb separació física.', false), ('C', 'El cap de serveis l''ha de retenir al centre fins que arribi el jutge de guàrdia.', false), ('D', 'La comunicació es fa, però se suspenen les comunicacions de l''intern durant un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''apartat 1.2.2 de la Circular 1/2008, sobre escorcolls i aplicació de mitjans de control adequats, quina afirmació NO és correcta respecte dels escorcolls amb despullament?', 'L''apartat 1.2.2 exigeix que no vagin acompanyats de flexions, que els faci personal del mateix sexe, en la màxima intimitat, de manera individual i a la cel·la de l''intern o en una dependència adequada (art. 68.3 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.2', 'Aquests escorcolls, que no han d’anar acompanyats de flexions, han de ser duts a terme per personal del mateix sexe que el de la persona que s’ha d’escorcollar, en la màxima intimitat i de manera individual, fora de l’abast de la mirada de terceres persones, utilitzant la cel·la que ocupa l’intern o una altra dependència adequada a l’efecte', null, '4294e69de3da0f3f384f5df3122cdd009c3a69ffa1378823950d3fbb8a86070c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4294e69de3da0f3f384f5df3122cdd009c3a69ffa1378823950d3fbb8a86070c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els ha de fer personal del mateix sexe que la persona escorcollada.', false), ('B', 'S''han de fer en la màxima intimitat i de manera individual, fora de l''abast de la mirada de terceres persones.', false), ('C', 'Es poden fer a la cel·la que ocupa l''intern o en una altra dependència adequada.', false), ('D', 'S''han d''acompanyar de flexions per comprovar les cavitats corporals.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què s''ha de lliurar a l''intern en l''escorcoll amb nu integral un cop feta la inspecció visual del cos?', 'L''apartat 1.2.4 preveu que l''intern es tregui ell mateix la roba i la lliuri per al control, i que, feta la inspecció visual, se li doni una bata per evitar la nuesa més enllà del temps imprescindible.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.4', 'un cop s’hagi fet una inspecció visual del cos de l’intern s’haurà de lliurar a l’intern una bata per tal que es vesteixi mentre dura l’escorcoll i evitar així la seva nuesa més enllà del temps imprescindible.', null, 'aa0ad032c81d4f62f1e9073b2348b002117d63268ca83f488f3b2f459111ee5c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa0ad032c81d4f62f1e9073b2348b002117d63268ca83f488f3b2f459111ee5c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una bata, perquè es vesteixi mentre dura l''escorcoll i s''eviti la nuesa més enllà del temps imprescindible.', true), ('B', 'Un rebut de les peces de roba retirades.', false), ('C', 'Una còpia del comunicat de l''escorcoll.', false), ('D', 'La roba que portava, sense esperar el control de les peces.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, en què s''ha de basar, amb caràcter sistemàtic i general, l''escorcoll i el control de les persones autoritzades a comunicar amb els interns?', 'L''apartat 2.1 basa el control dels visitants en detectors manuals i arcs detectors; en les comunicacions especials s''hi afegeixen la retenció d''efectes personals i l''escorcoll superficial de la roba i els efectes.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 2.1', 's’ha de basar en la utilització, amb caràcter sistemàtic i general, de mitjans de detecció d’objectes metàl·lics com son els detectors manuals i els arcs detectors.', null, 'ac13bd6f4667ed470cd36b64a349dea673f886602d724560ccb7ec719cac4561', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ac13bd6f4667ed470cd36b64a349dea673f886602d724560ccb7ec719cac4561')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En l''escorcoll amb nu integral de tots els visitants.', false), ('B', 'En proves radiològiques voluntàries.', false), ('C', 'En l''escorcoll superficial practicat per funcionaris de qualsevol sexe.', false), ('D', 'En la utilització de mitjans de detecció d''objectes metàl·lics, com els detectors manuals i els arcs detectors.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''apartat 1.2.1 de la Circular 1/2008, en quin supòsit s''ha de fer sistemàticament l''escorcoll amb despullament de la persona?', 'L''apartat 1.2.1 el preveu sistemàticament en l''ingrés al centre; en el retorn de permisos o en finalitzar comunicacions especials només amb motivació concreta, i mai de manera aleatòria.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.1', 'Sistemàticament, quan l’intern ingressa al centre d’acord amb l’article 18.1 del Reglament Penitenciari.', null, '65ade9089db7e2d95fce37968d321e82582c0ae841e663d00512c7a2b78807d9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '65ade9089db7e2d95fce37968d321e82582c0ae841e663d00512c7a2b78807d9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan l''intern ingressa al centre, d''acord amb l''article 18.1 del Reglament penitenciari.', true), ('B', 'Cada vegada que l''intern finalitza qualsevol comunicació oral ordinària.', false), ('C', 'De manera aleatòria, un cop al mes, a tots els interns del mòdul.', false), ('D', 'Sempre que l''intern torna d''una conducció a l''hospital.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, quina mesura es pot aplicar a l''intern que es nega injustificadament a lliurar els objectes o les substàncies detectades mitjançant les exploracions?', 'L''apartat 1.5 permet l''aïllament provisional de l''art. 72 RP amb observació visual constant, en les condicions de l''art. 45 LOGP i només el temps estrictament necessari; el director ho ha de comunicar immediatament al jutge de vigilància.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.5', 'se li podrà aplicar la mesura d’aïllament provisional prevista per l’article 72 del Reglament Penitenciari i mantenir-lo en situació d’observació visual constant, en els termes i en les condicions establertes per l’article 45 de la LOGP, mesura que només pot durar el temps estrictament necessari.', null, '559addfaf8a07c41c27d8e135f0ed851d55b2435da7261304e52c832399454ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '559addfaf8a07c41c27d8e135f0ed851d55b2435da7261304e52c832399454ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sanció d''aïllament en cel·la de fins a catorze dies, imposada pel cap de serveis.', false), ('B', 'La regressió automàtica a primer grau.', false), ('C', 'La suspensió de totes les comunicacions durant un mes.', false), ('D', 'L''aïllament provisional previst a l''article 72 del Reglament penitenciari, mantenint-lo en observació visual constant el temps estrictament necessari.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què s''ha de fer quan hi ha prou indicis racionals d''una possible introducció al centre d''objectes o substàncies prohibides per part de visitants?', 'L''apartat 2.2 obliga a comunicar-ho als Mossos d''Esquadra per escrit motivat perquè facin les diligències necessàries; l''escorcoll amb nu integral dels visitants només es pot fer amb les raons i la forma de l''art. 68 RP.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 2.2', 's’ha de comunicar aquesta suposició als Mossos d’Esquadra mitjançant un escrit motivat, procurant concretar la persona o les persones sospitoses, per tal que es duguin a terme les diligències necessàries.', null, '4ae0a447ecdd872593e7fe3720457d8fc265e146a90056070eb900751e19bd72', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4ae0a447ecdd872593e7fe3720457d8fc265e146a90056070eb900751e19bd72')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspendre de manera indefinida les comunicacions de l''intern.', false), ('B', 'Comunicar aquesta suposició als Mossos d''Esquadra mitjançant un escrit motivat, concretant tant com es pugui les persones sospitoses.', true), ('C', 'Fer en tot cas una prova radiològica al visitant.', false), ('D', 'Comunicar-ho al jutge de vigilància perquè autoritzi l''escorcoll.', false)) as v(label, body, ok)
)
