select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, per facilitar el control dels interns que tornen de permís, com han de tornar i qui ha de vetllar perquè els funcionaris del departament disposin de la informació sobre els seus comportaments anteriors?', 'L''apartat 1.2.1 disposa que els interns tornin de permís esglaonadament i encarrega al subdirector d''Interior que la informació sobre comportaments anteriors estigui a l''abast dels funcionaris del departament.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.2.1', 'Els interns han de tornar de permís esglaonadament per facilitar aquest control. El subdirector d’interior vetllarà per a que aquesta informació estigui a l’abast dels funcionaris adscrits al departament.', null, 'f5b706dbfd92faeb842aeb8e32d7f76d15316a1248b0c1b943e3441ba932d455', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f5b706dbfd92faeb842aeb8e32d7f76d15316a1248b0c1b943e3441ba932d455')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Han de tornar tots alhora, i ho ha de vetllar el cap de serveis.', false), ('B', 'Han de tornar esglaonadament, i ho ha de vetllar el jutge de vigilància.', false), ('C', 'Han de tornar en grups de cinc, i ho ha de vetllar el cap d''unitat.', false), ('D', 'Han de tornar esglaonadament, i ho ha de vetllar el subdirector o subdirectora d''Interior.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, què s''ha de fer quan es troben substàncies tòxiques, estupefaents o psicotròpiques en poder de les persones autoritzades a comunicar amb els interns?', 'L''apartat 2.3 obliga a comunicar-ho immediatament als Mossos d''Esquadra, que se''n fan càrrec i ho comuniquen al jutjat de guàrdia, que decideix el procediment. Sense dotació permanent de Mossos, la persona detinguda roman en un lloc adequat amb les garanties dels arts. 520 i següents de la LECrim.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 2.3', 's’ha de comunicar immediatament al cos de Mossos d’Esquadra, perquè es faci càrrec d’aquestes persones i ho comuniqui al jutjat de guàrdia. El jutjat de guàrdia decidirà quin és el procediment que cal seguir.', null, '2b78f07fc13ee2bd197eea2a687bc1b21b4e9d55a744c97414dc165e51afdced', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2b78f07fc13ee2bd197eea2a687bc1b21b4e9d55a744c97414dc165e51afdced')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Retenir-les al centre fins que el director decideixi si les denuncia.', false), ('B', 'Prohibir-los l''entrada al centre durant sis mesos, sense altres tràmits.', false), ('C', 'Comunicar-ho al jutge de vigilància penitenciària, que decideix el procediment.', false), ('D', 'Comunicar-ho immediatament al cos de Mossos d''Esquadra, perquè es faci càrrec d''aquestes persones i ho comuniqui al jutjat de guàrdia.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 1/2008, a qui s''han de lliurar les substàncies tòxiques, estupefaents o psicotròpiques trobades en els escorcolls dels interns, juntament amb els comunicats dels funcionaris i una còpia de la fitxa bàsica de l''intern?', 'L''apartat 1.7, d''acord amb la LECrim, ordena lliurar-les al jutjat de guàrdia amb els comunicats o informes dels funcionaris i una còpia de la fitxa bàsica de l''intern, amb la col·laboració, si cal, dels Mossos d''Esquadra.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular1_2008.pdf'), 'Circular 1/2008, apartat 1.7', 's’han de lliurar juntament amb els comunicats o informes dels funcionaris que han duta a terme la intervenció i una còpia de la fitxa bàsica de l’intern al jutjat de guàrdia, la qual cosa es pot fer mitjançant la col·laboració dels Mossos d’Esquadra.', null, '44b3e9b48e207f39e09be07a083331bf7784c031b06890be5cbab8f18125faac', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '44b3e9b48e207f39e09be07a083331bf7784c031b06890be5cbab8f18125faac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al jutge de vigilància penitenciària, per correu ordinari.', false), ('B', 'Al servei mèdic del centre, perquè les destrueixi.', false), ('C', 'Al jutjat de guàrdia, cosa que es pot fer amb la col·laboració dels Mossos d''Esquadra.', true), ('D', 'Al Ministeri Fiscal, a través del gerent.', false)) as v(label, body, ok)
)
