with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició transitòria de la Circular 1/2022, de quin termini disposen els centres penitenciaris que no tinguin cel·les d''aïllament o de contenció dotades amb gravació de so per adequar-les?', 'La disposició transitòria dona sis mesos per adequar les cel·les sense gravació de so (totes ja disposaven de gravació d''imatge).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, disposició transitòria', 'Els centres penitenciaris que no disposin de cel·les d’aïllament i/o de contenció dotades amb gravació de so -actualment totes disposen de gravació d’imatge-, disposaran d’un termini de 6 mesos per a la seva adequació.', 'Disposició transitòria ja exhaurida (el termini de sis mesos comptava des de l''entrada en vigor, l''1 d''abril de 2022). Valorar si convé mantenir la pregunta.', 'a51db85f468d3cbda9fa45346c84b2064b81976d5320e4752db2b51d2929264a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a51db85f468d3cbda9fa45346c84b2064b81976d5320e4752db2b51d2929264a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos.', true), ('B', 'Tres mesos.', false), ('C', 'Un any.', false), ('D', 'Dos anys.', false)) as v(label, body, ok)
)
