with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la disposició addicional segona de la Circular 1/2022, quina alternativa a la contenció mecànica al llit havia d''analitzar el grup de treball que constituiria la Direcció General?', 'La disposició addicional segona preveu un grup de treball per avaluar contínuament l''aplicació del protocol i analitzar alternatives a la contenció mecànica al llit, com ara les cel·les encoixinades.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, disposició addicional segona', 'per analitzar possibles alternatives a la contenció mecànica al llit, com la possible implementació de cel·les encoixinades.', 'Disposició addicional d''execució temporal (grup de treball previst per al primer semestre de 2022); se''n desconeix el resultat. Valorar si convé mantenir la pregunta.', '1099f84c0dff69ef184c85a75f71209c5aab35bd46264134676ed88f443aa6d1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1099f84c0dff69ef184c85a75f71209c5aab35bd46264134676ed88f443aa6d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''ús de pistoles d''impulsos elèctrics.', false), ('B', 'La possible implementació de cel·les encoixinades.', true), ('C', 'El trasllat immediat a un hospital psiquiàtric extern.', false), ('D', 'La sedació farmacològica obligatòria.', false)) as v(label, body, ok)
)
