with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la justificació de la Circular 1/2022, de quins organismes s''incorporen especialment les recomanacions als procediments de contenció mecànica?', 'La Circular incorpora especialment la Guia de bones pràctiques en contencions mecàniques del Defensor del Pueblo (MNPT) i les recomanacions del MCPT del Síndic de Greuges, per millorar les condicions de les contencions i evitar al màxim les immobilitzacions.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/documents/instruccions_i_circulars/circular-1-2022-contencions.pdf'), 'Circular 1/2022, justificació normativa', 'especialment les contemplades a la Guia de bones pràctiques en contencions mecàniques del Defensor del Pueblo en la seva condició de Mecanisme Nacional de Prevenció de la Tortura (MNPT) i les recomanacions del Mecanisme Català de Prevenció de la Tortura', null, 'a175538f1c12cb05b3e2790314b84c9d38ad56040c9eae5f9e3ebef08dc60082', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a175538f1c12cb05b3e2790314b84c9d38ad56040c9eae5f9e3ebef08dc60082')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del Defensor del Pueblo com a Mecanisme Nacional de Prevenció de la Tortura i del Mecanisme Català de Prevenció de la Tortura del Síndic de Greuges.', true), ('B', 'Del Consell General del Poder Judicial i de la Fiscalia de Catalunya.', false), ('C', 'Del Comitè de Ministres del Consell d''Europa i de la Comissió Europea.', false), ('D', 'De la Comissió de seguiment del Codi ètic i dels jutjats de vigilància penitenciària.', false)) as v(label, body, ok)
)
