insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/1979, de 26 de septiembre, General Penitenciaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e14-regim-penitenciari-2-seguretat', 'Tema 14. El règim penitenciari II: seguretat, mitjans coercitius i protocols') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e14-regim-penitenciari-2-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 45 de la Llei orgànica 1/1979, general penitenciària (LOGP), poden utilitzar armes de foc els funcionaris d''institucions penitenciàries en l''exercici de les seves funcions de vigilància?', 'L''art. 45.4 LOGP prohibeix que els funcionaris facin servir armes de foc en les funcions de vigilància. Si les han d''utilitzar les Forces de Seguretat a qui el director demana auxili, s''apliquen les limitacions de la seva legislació (art. 72.5 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 45.4 LOGP', 'En el desempeño de sus funciones de vigilancia los funcionarios de instituciones penitenciarias no podrán utilizar armas de fuego.', null, '36a6f6061ba5a467450c238c7d2cc4afe6d529aceb19a10ad201948bc10856f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '36a6f6061ba5a467450c238c7d2cc4afe6d529aceb19a10ad201948bc10856f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, amb l''autorització prèvia del director.', false), ('B', 'No, en cap cas.', true), ('C', 'Sí, però només per impedir actes d''evasió.', false), ('D', 'Sí, en els casos de motí, amb l''autorització del jutge de vigilància.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 23 de la LOGP, com s''han de fer els escorcolls de les persones dels interns, de les seves pertinences i dels locals que ocupen, els recomptes i les requises?', 'L''art. 23 LOGP remet al reglament els casos, les garanties i la periodicitat d''aquestes mesures i exigeix sempre el respecte a la dignitat de la persona.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 23 LOGP', 'se efectuarán en los casos con las garantías y periodicidad que reglamentariamente se determinen y dentro del respeto a la dignidad de la persona.', null, 'e88fab16fd0aeeebd0be82329b821f63645ff1a9f7337a2ecfe95d0789592e6a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e88fab16fd0aeeebd0be82329b821f63645ff1a9f7337a2ecfe95d0789592e6a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre amb l''autorització prèvia del jutge de vigilància.', false), ('B', 'En els casos, amb les garanties i amb la periodicitat que es determinin reglamentàriament i dins del respecte a la dignitat de la persona.', true), ('C', 'Només en presència de l''advocat de l''intern.', false), ('D', 'Lliurement, segons el criteri de cada funcionari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 45 de la LOGP, a què s''ha d''adreçar l''ús de les mesures coercitives i quant de temps poden subsistir?', 'L''art. 45.3 LOGP limita els mitjans coercitius al restabliment de la normalitat i al temps estrictament necessari; l''art. 72.1 RP afegeix que mai no poden suposar una sanció encoberta.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 45.Tres LOGP', 'El uso de las medidas coercitivas estará dirigido exclusivamente al restablecimiento de la normalidad y solo subsistirá el tiempo estrictamente necesario.', null, '66eb17a29af0fca125f6b3f8d37e3ef303562d2fb6b3ab9007d045a7c24f7c4d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '66eb17a29af0fca125f6b3f8d37e3ef303562d2fb6b3ab9007d045a7c24f7c4d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A sancionar la conducta de l''intern, durant el temps que fixi la comissió disciplinària.', false), ('B', 'A garantir la custòdia de l''intern, fins a un màxim de catorze dies.', false), ('C', 'Exclusivament al restabliment de la normalitat, i només el temps estrictament necessari.', true), ('D', 'A prevenir futures alteracions, fins que l''intern sigui traslladat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 45 de la LOGP, en quin dels casos següents NO es poden utilitzar els mitjans coercitius?', 'L''art. 45.1 LOGP només admet els mitjans coercitius per impedir evasions o violència, evitar danys i vèncer la resistència a les ordres. Mai no poden suposar una sanció encoberta (art. 72.1 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 45.Uno LOGP', 'a) Para impedir actos de evasión o de violencia de los internos. b) Para evitar daños de los internos a sí mismos, a otras personas o cosas. c) Para vencer la resistencia activa o pasiva de los internos a las órdenes del personal penitenciario en el ejercicio de su cargo.', null, '760f9ab7bba39705fcf3e201b98ee5d592ac56fcdb32877b9fdb6d1945a8a488', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '760f9ab7bba39705fcf3e201b98ee5d592ac56fcdb32877b9fdb6d1945a8a488')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per sancionar un intern que ha comès una falta disciplinària greu.', true), ('B', 'Per impedir actes d''evasió o de violència dels interns.', false), ('C', 'Per evitar danys dels interns a si mateixos, a altres persones o a coses.', false), ('D', 'Per vèncer la resistència activa o passiva dels interns a les ordres del personal penitenciari en l''exercici del seu càrrec.', false)) as v(label, body, ok)
)
