insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-e14-regim-penitenciari-2-seguretat', 'Tema 14. El règim penitenciari II: seguretat, mitjans coercitius i protocols') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-e14-regim-penitenciari-2-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, a qui correspon la seguretat exterior dels establiments penitenciaris?', 'L''art. 63.1 RP atribueix la seguretat exterior a les Forces i Cossos de Seguretat de l''Estat o, si escau, als cossos de policia de les comunitats autònomes. En matèria de seguretat exterior, aquests cossos reben indicacions dels directors dels centres.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 63.1 RP', 'La seguridad exterior de los Establecimientos corresponde a las Fuerzas y Cuerpos de Seguridad del Estado o, en su caso, a los Cuerpos de Policía de las Comunidades Autónomas', null, 'c23c658e2b9543a20900d936efaefa15a1744ec07f5932e66b5355fbba718944', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c23c658e2b9543a20900d936efaefa15a1744ec07f5932e66b5355fbba718944')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A les Forces i Cossos de Seguretat de l''Estat o, si escau, als cossos de policia de les comunitats autònomes.', true), ('B', 'Als funcionaris dels cossos d''institucions penitenciàries, sota la direcció del cap de serveis.', false), ('C', 'A empreses de seguretat privada contractades pel centre directiu.', false), ('D', 'Al director de l''establiment, que la pot encomanar a grups especialitzats de funcionaris.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 64 del Reglament penitenciari, a qui correspon, amb caràcter general, la seguretat interior dels establiments penitenciaris?', 'Segons l''art. 64 RP, la seguretat interior correspon als funcionaris dels cossos d''institucions penitenciàries, segons els comesos propis de cadascú i la distribució de serveis que acordi el director, llevat dels casos de la disposició final primera de la LOGP.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 64 RP', 'La seguridad interior de los Establecimientos corresponde, salvo en los casos previstos en la disposición final primera de la Ley Orgánica General Penitenciaria, a los funcionarios de los Cuerpos de Instituciones Penitenciarias, con arreglo a los cometidos propios de cada uno y a la distribución de los servicios acordada por el Director del Establecimiento.', null, 'aa97c79fd1a9ba054412925d0894709fc686e60cf60fbba3a3f31484e6594ebd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa97c79fd1a9ba054412925d0894709fc686e60cf60fbba3a3f31484e6594ebd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A les Forces i Cossos de Seguretat de l''Estat de guàrdia a l''establiment.', false), ('B', 'Al jutge de vigilància penitenciària, que n''aprova el pla anual.', false), ('C', 'Als funcionaris dels cossos d''institucions penitenciàries, d''acord amb la distribució de serveis que acordi el director.', true), ('D', 'Al consell de direcció, que en designa els responsables cada mes.', false)) as v(label, body, ok)
)
