with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65.1 del Reglament penitenciari, quina de les actuacions següents NO figura entre les mesures de seguretat interior dels establiments?', 'L''aïllament provisional no és una mesura de seguretat interior de l''art. 65.1 RP, sinó un mitjà coercitiu (art. 72.1 RP). L''art. 65.1 enumera l''observació, els recomptes, els registres, els escorcolls, les requises, els controls, els canvis de cel·la, l''assignació adequada de destinacions i les cauteles de les sortides.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 65.1 RP', 'Las actuaciones encaminadas a garantizar la seguridad interior de los establecimientos consistirán en la observación de los internos, los recuentos de población reclusa, los registros, los cacheos, las requisas, los controles, los cambios de celda, la asignación adecuada de destinos y las actividades y cautelas propias de las salidas tanto fuera de los módulos como fuera del establecimiento.', null, 'ca76aae0a9b264d81080b10fdbd2d28b3dc2ddbfbe7fd5832d5f1ae7415aa0fb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca76aae0a9b264d81080b10fdbd2d28b3dc2ddbfbe7fd5832d5f1ae7415aa0fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els recomptes de població reclusa.', false), ('B', 'L''aïllament provisional.', true), ('C', 'Les requises.', false), ('D', 'Els canvis de cel·la.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 67 del Reglament penitenciari, qui ordena els recomptes extraordinaris de la població reclusa?', 'Els recomptes extraordinaris els ordena el cap de serveis i ho comunica a la direcció (art. 67.2 RP). Els recomptes ordinaris es fan cada dia, coincidint amb els relleus del personal de vigilància que fixa l''horari aprovat pel consell de direcció (art. 67.1 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 67.2 RP', 'También se efectuarán los recuentos extraordinarios que se ordenen por el Jefe de Servicios, comunicándolo a la Dirección', null, '4930ba8d32ebec4990eb31f9d012c95e49ac6ea9ec64de61402fd86e27ef9429', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4930ba8d32ebec4990eb31f9d012c95e49ac6ea9ec64de61402fd86e27ef9429')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director, que ho ha de comunicar al jutge de vigilància.', false), ('B', 'El consell de direcció, en l''horari que aprova.', false), ('C', 'El funcionari encarregat del departament, que ho ha de comunicar al cap d''unitat.', false), ('D', 'El cap de serveis, que ho ha de comunicar a la direcció.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 68 del Reglament penitenciari, amb l''autorització de qui es pot fer un escorcoll amb despullament integral a un intern?', 'L''escorcoll amb despullament integral requereix motius de seguretat concrets i específics i raons individuals i contrastades, i l''ha d''autoritzar el cap de serveis (art. 68.2 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.2 RP', 'se podrá realizar cacheo con desnudo integral con autorización del Jefe de Servicios.', null, '79ceced848cd34eadde8bebc59a382650f988857d0bd4b89a69227749b61f7ec', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '79ceced848cd34eadde8bebc59a382650f988857d0bd4b89a69227749b61f7ec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del cap de serveis.', true), ('B', 'Del director de l''establiment.', false), ('C', 'Del jutge de vigilància penitenciària.', false), ('D', 'Del jutge de guàrdia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, com s''ha de fer l''escorcoll amb despullament integral d''un intern?', 'L''art. 68.3 RP exigeix funcionaris del mateix sexe que l''intern, un lloc tancat sense altres interns i la preservació de la intimitat tant com sigui possible.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.3 RP', 'El cacheo con desnudo integral se efectuará por funcionarios del mismo sexo que el interno, en lugar cerrado sin la presencia de otros internos y preservando, en todo lo posible, la intimidad.', null, '82ba54b925e43964a316e32a6a7edcc780a58ad24208cf3a4c7e8e4040bac5cc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '82ba54b925e43964a316e32a6a7edcc780a58ad24208cf3a4c7e8e4040bac5cc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per funcionaris de qualsevol sexe, sempre que hi sigui present el metge de l''establiment.', false), ('B', 'Per funcionaris del mateix sexe que l''intern, en un lloc tancat sense la presència d''altres interns i preservant tant com es pugui la intimitat.', true), ('C', 'Per funcionaris del mateix sexe que l''intern, en presència d''un altre intern que faci de testimoni.', false), ('D', 'Per personal sanitari, a la infermeria de l''establiment i amb l''autorització prèvia del jutge.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 68 del Reglament penitenciari, si el resultat de l''escorcoll amb despullament integral és infructuós i la sospita persisteix, què es pot fer?', 'Segons l''art. 68.4 RP, si l''escorcoll és infructuós i la sospita persisteix, el director pot demanar a l''autoritat judicial competent que autoritzi altres mitjans de control adequats.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.4 RP', 'Si el resultado del cacheo con desnudo integral fuese infructuoso y persistiese la sospecha, se podrá solicitar por el Director a la Autoridad judicial competente la autorización para la aplicación de otros medios de control adecuados.', null, 'e4d7d16aeebf4b2a8364f1eb9189615a98dd02df99996414b8a0dbb6cc5ef2ad', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4d7d16aeebf4b2a8364f1eb9189615a98dd02df99996414b8a0dbb6cc5ef2ad')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis pot ordenar directament proves radiològiques a l''intern.', false), ('B', 'El director pot acordar l''aïllament provisional de l''intern fins que lliuri l''objecte, sense comunicar-ho a ningú.', false), ('C', 'El cap de serveis pot repetir l''escorcoll tantes vegades com consideri necessari.', false), ('D', 'El director pot sol·licitar a l''autoritat judicial competent l''autorització per aplicar altres mitjans de control adequats.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71 del Reglament penitenciari, quins principis regeixen les mesures de seguretat i a quins mitjans s''ha de donar preferència quan n''hi ha d''igual eficàcia?', 'Les mesures de seguretat es regeixen pels principis de necessitat i proporcionalitat, amb respecte a la dignitat i als drets fonamentals. Si hi ha mitjans d''igual eficàcia, es prefereixen els electrònics (art. 71.1 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 71.1 RP', 'Las medidas de seguridad se regirán por los principios de necesidad y proporcionalidad y se llevarán siempre a cabo con el respeto debido a la dignidad y a los derechos fundamentales, especialmente las que se practiquen directamente sobre las personas. Ante la opción de utilizar medios de igual eficacia, se dará preferencia a los de carácter electrónico.', null, 'df6ce0713e2005ee5d22836c8a860d254e602e93c4b292ada95a8b6d77c20f2f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'df6ce0713e2005ee5d22836c8a860d254e602e93c4b292ada95a8b6d77c20f2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els principis d''oportunitat i eficàcia, amb preferència pels mitjans de caràcter personal.', false), ('B', 'Els principis de necessitat i proporcionalitat, amb preferència per l''escorcoll personal.', false), ('C', 'Els principis de legalitat i jerarquia, amb preferència pels mitjans de caràcter electrònic.', false), ('D', 'Els principis de necessitat i proporcionalitat, amb preferència pels mitjans de caràcter electrònic.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.1 del Reglament penitenciari, quin dels següents NO és un mitjà coercitiu?', 'L''art. 72.1 RP enumera com a mitjans coercitius l''aïllament provisional, la força física personal, les defenses de goma, els aerosols d''acció adequada i les manilles. El trasllat a un departament especial no hi figura.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.1 RP', 'Son medios coercitivos, a los efectos del artículo 45.1 de la Ley Orgánica General Penitenciaria, el aislamiento provisional, la fuerza física personal, las defensas de goma, los aerosoles de acción adecuada y las esposas.', null, '62a4c4f420c5f3e5372de4cbe385c0758165911f64a7eb034415482f5bf51a69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '62a4c4f420c5f3e5372de4cbe385c0758165911f64a7eb034415482f5bf51a69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''aïllament provisional.', false), ('B', 'Les defenses de goma.', false), ('C', 'El trasllat a un departament especial de règim tancat.', true), ('D', 'Els aerosols d''acció adequada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, qui autoritza prèviament l''ús dels mitjans coercitius i a qui s''ha de comunicar immediatament que s''han adoptat i que han cessat?', 'L''ús dels mitjans coercitius l''autoritza prèviament el director, llevat dels casos d''urgència, en què se l''informa immediatament. El director comunica immediatament al jutge de vigilància l''adopció i el cessament de la mesura, amb el detall dels fets (art. 72.3 RP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.3 RP', 'La utilización de los medios coercitivos será previamente autorizada por el Director, salvo que razones de urgencia no lo permitan, en cuyo caso se pondrá en su conocimiento inmediatamente. El Director comunicará inmediatamente al Juez de Vigilancia la adopción y cese de los medios coercitivos', null, '569dd4377106ca095c33f36f52639170d3c68374d9edc3f4becc68109610641b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '569dd4377106ca095c33f36f52639170d3c68374d9edc3f4becc68109610641b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els autoritza el director, que n''ha de comunicar l''adopció i el cessament al jutge de vigilància.', true), ('B', 'Els autoritza el cap de serveis, que n''ha de comunicar l''adopció al director.', false), ('C', 'Els autoritza el jutge de vigilància, a proposta del director.', false), ('D', 'Els autoritza el director, que només n''ha de comunicar l''adopció al centre directiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, què pot fer el director en cas de greus alteracions de l''ordre amb perill imminent per a les persones o les instal·lacions?', 'L''art. 72.5 RP permet al director demanar provisionalment l''auxili de les Forces de Seguretat de guàrdia. Si aquestes han d''utilitzar armes de foc, ho fan pels motius i amb les limitacions de la legislació de Forces i Cossos de Seguretat. Els funcionaris penitenciaris no en poden fer servir (art. 45.4 LOGP).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.5 RP', 'En los casos de graves alteraciones del orden con peligro inminente para las personas o para las instalaciones, el Director con carácter provisional podrá recabar el auxilio de las Fuerzas de Seguridad de guardia en el Establecimiento', null, 'f45afba826e1dd2419f428319d2fae15040046b6c9b1fd618f454eec2dbee2ed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f45afba826e1dd2419f428319d2fae15040046b6c9b1fd618f454eec2dbee2ed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Autoritzar els funcionaris de vigilància a fer servir armes de foc.', false), ('B', 'Acordar el trasllat immediat de tots els interns del departament a un altre centre, sense comunicar-ho al centre directiu.', false), ('C', 'Suspendre per a tots els interns del centre totes les comunicacions, incloses les comunicacions amb els advocats defensors.', false), ('D', 'Demanar, amb caràcter provisional, l''auxili de les Forces de Seguretat de guàrdia a l''establiment.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 75 del Reglament penitenciari, quan cal per salvaguardar la vida o la integritat física d''un intern, qui pot acordar l''adopció de mesures que impliquin limitacions regimentals i a qui se n''ha d''informar?', 'L''art. 75.2 RP atribueix aquesta decisió al director, per resolució motivada i a sol·licitud de l''intern o per iniciativa pròpia, i el director n''informa el jutge de vigilància.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 75.2 RP', 'En su caso, a solicitud del interno o por propia iniciativa, el Director podrá acordar mediante resolución motivada, cuando fuere preciso para salvaguardar la vida o integridad física del recluso, la adopción de medidas que impliquen limitaciones regimentales, dando cuenta al Juez de Vigilancia.', null, '3fc201bee335134c23765bbb3924f820e4886dd6b97d95fc19da1398f91e6b98', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3fc201bee335134c23765bbb3924f820e4886dd6b97d95fc19da1398f91e6b98')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La junta de tractament, a proposta de l''equip tècnic, i n''informa el centre directiu.', false), ('B', 'El director, en resolució motivada, a sol·licitud de l''intern o per iniciativa pròpia, i n''informa el jutge de vigilància.', true), ('C', 'El cap de serveis, per iniciativa pròpia, i n''informa el director.', false), ('D', 'El consell de direcció, només a sol·licitud de l''intern, i n''informa el Ministeri Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 66 del Reglament penitenciari, a què s''adreça l''observació dels interns com a mesura de seguretat interior?', 'L''art. 66 RP orienta l''observació al coneixement del comportament habitual, les activitats, els moviments i les relacions dels interns; si es detecten fets rellevants per a la seguretat o el tractament, s''han d''elevar els informes oportuns.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 66 RP', 'La observación de los internos estará encaminada al conocimiento de su comportamiento habitual y de sus actividades y movimientos dentro y fuera del departamento asignado, así como de sus relaciones con los demás internos y del influjo beneficioso o nocivo que, en su caso, ejercieren sobre los mismos.', null, '5a07029cff9e8e4bbe8f123c4baa02ac718f99ee19cffcdcd1fe27967dd46cf5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a07029cff9e8e4bbe8f123c4baa02ac718f99ee19cffcdcd1fe27967dd46cf5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivament a la vigilància nocturna de les cel·les.', false), ('B', 'A l''elaboració de la proposta de classificació inicial en grau.', false), ('C', 'Al coneixement del seu comportament habitual, de les seves activitats i moviments dins i fora del departament, de les relacions amb els altres interns i de la influència que hi exerceixen.', true), ('D', 'Al control de les comunicacions orals i escrites dels interns.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 67 del Reglament penitenciari, en quins moments de la jornada es fan els recomptes ordinaris de la població reclusa?', 'L''art. 67.1 RP preveu recomptes ordinaris diaris coincidint amb els relleus del personal de vigilància, d''acord amb l''horari aprovat pel Consell de Direcció. Els extraordinaris els ordena el cap de serveis (art. 67.2).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 67.1 RP', 'Se realizarán diariamente los recuentos ordinarios de control de la población reclusa en los momentos de la jornada regimental que coincidan con los relevos del personal de vigilancia, que se fijen en el horario aprobado por el Consejo de Dirección del Establecimiento penitenciario.', null, '91b2e1cb4f203ee242e4570f22f4ad7a006df8ca34fc71266fe694ef296aca6e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91b2e1cb4f203ee242e4570f22f4ad7a006df8ca34fc71266fe694ef296aca6e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una vegada a la setmana, el dia que fixi el cap de serveis.', false), ('B', 'Només en els horaris d''àpats i a l''hora de tancar les cel·les.', false), ('C', 'Quan ho ordeni el jutge de vigilància.', false), ('D', 'Diàriament, en els moments que coincideixen amb els relleus del personal de vigilància, fixats en l''horari aprovat pel Consell de Direcció.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
