  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 68.1 del Reglament penitenciari, sobre què es fan les requises?', 'L''art. 68.1 RP distingeix els escorcolls de persones, roba i efectes dels interns i les requises de portes, finestres, terres, parets i sostres de les cel·les i dels locals d''ús comú. El control de vehicles i visitants el regula l''art. 69 RP.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.1 RP', 'requisas de las puertas, ventanas, suelos, paredes y techos de las celdas o dormitorios, así como de los locales y dependencias de uso común.', null, 'a6f11f0ab079f4a96f2c901fd21049b09d94e5269e7f4707a28a64d84efab4a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a6f11f0ab079f4a96f2c901fd21049b09d94e5269e7f4707a28a64d84efab4a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sobre les portes, les finestres, els terres, les parets i els sostres de les cel·les o dormitoris, i dels locals i dependències d''ús comú.', true), ('B', 'Exclusivament sobre la roba i els efectes personals dels interns.', false), ('C', 'Sobre els vehicles que entren o surten de l''establiment.', false), ('D', 'Sobre les persones que visiten els interns.', false)) as v(label, body, ok)
)
