with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 63 del Reglament penitenciari, què ha de fer el cap de la guàrdia exterior un cop fet el relleu?', 'L''art. 63.2 RP obliga el cap de la guàrdia exterior a presentar-se al director o al seu substitut un cop fet el relleu, i també quan durant el servei es produeixi un fet que s''hagi de comunicar immediatament.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 63.2 RP', 'Una vez practicado el relevo, el Jefe de la guardia exterior deberá presentarse al Director o funcionario que le sustituya para informarle de las incidencias del servicio.', null, '45548b2bc5c63e919da9dbf68bec54ae70c02aec878137fa7ab10745aca9cd90', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '45548b2bc5c63e919da9dbf68bec54ae70c02aec878137fa7ab10745aca9cd90')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presentar-se al director o al funcionari que el substitueixi per informar-lo de les incidències del servei.', true), ('B', 'Signar el llibre de serveis del centre davant del cap d''unitat.', false), ('C', 'Comunicar-se amb el jutge de guàrdia.', false), ('D', 'Fer un recompte extraordinari dels interns.', false)) as v(label, body, ok)
)
