with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 65.2 del Reglament penitenciari, la intensitat de les mesures de seguretat interior s''ajusta a la perillositat potencial dels interns. Quin dels supòsits següents NO s''hi esmenta expressament?', 'L''art. 65.2 RP esmenta particularment els interns de grups terroristes, de delinqüència organitzada o de perillositat extrema, sempre respectant els principis de l''art. 71 (necessitat i proporcionalitat).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 65.2 RP', 'La intensidad de las medidas señaladas en el apartado anterior se ajustará a la potencial peligrosidad de los internos a que se apliquen, particularmente en los supuestos de internos pertenecientes a grupos terroristas, de delincuencia organizada o de peligrosidad extrema', null, '556165e5dc1f935de3a5fff949f578492a017aa5f3a6168215cc491ee96c88bb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '556165e5dc1f935de3a5fff949f578492a017aa5f3a6168215cc491ee96c88bb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els interns que pertanyen a grups terroristes.', false), ('B', 'Els interns reincidents en faltes disciplinàries lleus.', true), ('C', 'Els interns que pertanyen a grups de delinqüència organitzada.', false), ('D', 'Els interns de perillositat extrema.', false)) as v(label, body, ok)
)
