  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 67 del Reglament penitenciari, com s''han de reflectir els resultats dels recomptes ordinaris i extraordinaris?', 'L''art. 67.3 RP exigeix rapidesa i fiabilitat i que el resultat consti en part escrit signat pels funcionaris que han fet el recompte, adreçat al cap de serveis.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 67.3 RP', 'sus resultados se reflejarán en parte escrito suscrito por los funcionarios que los hubiesen efectuado, que se dirigirá al Jefe de Servicios.', null, '29cd7cf33fba65a2f8ffe12d6776e217820c77ceb9d5f3dd92e2b573c581d5e8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29cd7cf33fba65a2f8ffe12d6776e217820c77ceb9d5f3dd92e2b573c581d5e8')
  returning id
