with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 70 del Reglament penitenciari, quins objectes s''han d''intervenir als interns?', 'L''art. 70.1 RP ordena intervenir diners, joies i objectes de valor no autoritzats i objectes perillosos o d''il·lícita procedència; dels perillosos o prohibits retirats se''n deixa constància per escrit (art. 70.2).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 70.1 RP', 'Se intervendrá el dinero, alhajas, u objetos de valor no autorizados, así como los objetos que se entiendan peligrosos para la seguridad o convivencia ordenada o de ilícita procedencia.', null, '8148a2efdb3c724e4b88e41698e3e5a5b51bd5b2f950b3aea03457d47730802d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8148a2efdb3c724e4b88e41698e3e5a5b51bd5b2f950b3aea03457d47730802d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tots els aparells electrònics, siguin o no autoritzats.', false), ('B', 'Només les drogues tòxiques i les armes.', false), ('C', 'Els diners, les joies o els objectes de valor no autoritzats, i els objectes perillosos per a la seguretat o la convivència ordenada o d''il·lícita procedència.', true), ('D', 'Qualsevol objecte que no figuri a l''inventari d''ingrés, encara que sigui autoritzat.', false)) as v(label, body, ok)
)
