with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71 del Reglament penitenciari, què han de fer els funcionaris que, amb ocasió d''una mesura de seguretat, detectin una anomalia regimental o un fet indiciari d''una possible pertorbació de la vida normal del centre?', 'L''art. 71.2 RP obliga a posar-ho immediatament en coneixement del cap de serveis, sens perjudici de l''ús, quan escaigui, dels mitjans coercitius de l''art. 72.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 71.2 RP', 'lo pondrán inmediatamente en conocimiento del Jefe de Servicios, sin perjuicio de que, en su caso, hagan uso de los medios coercitivos a que se refiere el artículo siguiente.', null, '9f4d54066d98c5e74e3a1bfe66e25821403c7847e8066c58b22bec823864cc7b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9f4d54066d98c5e74e3a1bfe66e25821403c7847e8066c58b22bec823864cc7b')
  returning id
), o as (
