with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.1 del Reglament penitenciari, sobre els principis d''ús dels mitjans coercitius, assenyaleu la resposta correcta.', 'L''art. 72.1 RP imposa proporcionalitat, prohibeix la sanció encoberta i en limita l''ús als casos sense alternativa menys gravosa i al temps estrictament necessari.', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.1 RP', 'Su uso será proporcional al fin pretendido, nunca supondrá una sanción encubierta, y sólo se aplicarán cuando no exista otra manera menos gravosa para conseguir la finalidad perseguida y por el tiempo estrictamente necesario.', null, 'e22ec8def8e935e1a9cee9050b8b095ec7c68e92878692a9445f31909f50bcbd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e22ec8def8e935e1a9cee9050b8b095ec7c68e92878692a9445f31909f50bcbd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden aplicar com a sanció provisional mentre es tramita l''expedient disciplinari.', false), ('B', 'S''han d''aplicar sempre en la seva modalitat més intensa per garantir-ne l''eficàcia.', false), ('C', 'El seu ús ha de ser proporcional al fi pretès, mai no pot suposar una sanció encoberta i només s''han d''aplicar quan no hi hagi una altra manera menys gravosa.', true), ('D', 'Només els pot aplicar personal sanitari.', false)) as v(label, body, ok)
)
