  select 'Segons l''article 75 del Reglament penitenciari, qui proposa al centre directiu el trasllat d''un reclús a un altre establiment de característiques similars per poder aixecar les limitacions regimentals exigides per l''assegurament de la seva persona?', 'L''art. 75.3 RP atribueix la proposta motivada al Consell de Direcció (detinguts i presos) o a la Junta de Tractament (penats); l''acord de trasllat es comunica a l''autoritat judicial o al jutge de vigilància, respectivament (art. 75.4).', 'pcat_e14_regim_penitenciari_2_seguretat', (select id from public.topics where slug = 'pcat-e14-regim-penitenciari-2-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 75.3 RP', 'Mediante acuerdo motivado, el Consejo de Dirección, en el caso de los detenidos y presos, o la Junta de Tratamiento, en el caso de penados, propondrán al Centro Directivo el traslado del recluso a otro Establecimiento de similares características', null, 'a84cc89b17c0d4f05a932e38e49ea58d126f980b3e4ccfbdfdde09e8558c1783', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a84cc89b17c0d4f05a932e38e49ea58d126f980b3e4ccfbdfdde09e8558c1783')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director en tots els casos, amb informe del cap de serveis.', false), ('B', 'La Junta de Tractament en tots els casos, amb aprovació del jutge de vigilància.', false), ('C', 'El Consell de Direcció, si es tracta de detinguts i presos, o la Junta de Tractament, si es tracta de penats.', true), ('D', 'El jutge de vigilància, a sol·licitud de l''intern.', false)) as v(label, body, ok)
)
