with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, del règim tancat en els centres penitenciaris de Catalunya, quantes hores diàries fora de la cel·la tenen com a mínim els interns en la modalitat de vida de l''article 93 del RP?', 'L''apartat V.2.1.a de la Circular 2/2017 garanteix un mínim de 6 hores diàries fora de la cel·la, que inclouen les 3 hores de pati. En un període inicial d''adaptació de 15 dies com a màxim, es garanteixen 3 hores diàries de pati i 2 hores setmanals d''atenció individualitzada.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.1.a', 'Gaudiran un mínim de 6 hores diàries fora de la cel·la, comptant les 3 hores diàries de pati, l’atenció individualitzada, les activitats programades i l’ús dels espais comuns.', null, 'c24ecd12090cb244ba07ae3988f380e257fb2bfd71911dc76cb3ed91a8357826', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c24ecd12090cb244ba07ae3988f380e257fb2bfd71911dc76cb3ed91a8357826')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis hores, comptant-hi les tres hores diàries de pati, l''atenció individualitzada, les activitats programades i l''ús dels espais comuns.', true), ('B', 'Tres hores, que són les de pati.', false), ('C', 'Quatre hores, comptant-hi el pati i la vida en comú.', false), ('D', 'Vuit hores, comptant-hi les activitats programades.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, quin és el període màxim de revisió de la modalitat de vida de l''article 93 del RP?', 'L''apartat V.2.2 de la Circular 2/2017 fixa un període màxim de revisió de 45 dies, en què s''estudia si es manté la modalitat de l''article 93 o si es reassigna a la de l''article 94 RP. Els 3 mesos són el termini màxim de revisió de la regressió per part de la junta de tractament.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.2', 'El període de revisió màxim és de 45 dies, moment en què s’estudiarà la conveniència de mantenir aquesta modalitat de vida o fer una reassignació a la prevista a l’article 94 del RP.', null, 'd5b5817020eee55625931c0cffec8d9312f28b49ad8484b7ec2bf804e4d9ab8f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd5b5817020eee55625931c0cffec8d9312f28b49ad8484b7ec2bf804e4d9ab8f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '15 dies.', false), ('B', '3 mesos.', false), ('C', '6 mesos.', false), ('D', '45 dies.', true)) as v(label, body, ok)
)
