with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, del règim tancat, amb quina freqüència mínima ha de fer el tutor una entrevista de seguiment a les persones en la modalitat de vida de l''article 93 del Reglament penitenciari?', 'L''apartat V.2.1 b) assigna un tutor a totes les persones en la modalitat de l''art. 93, amb almenys una entrevista setmanal; a les fases I i II de l''art. 94 l''entrevista és, almenys, cada quinze dies.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.1.b', 'b) Totes les persones en aquesta modalitat de vida tindran assignat un tutor que farà, almenys, una entrevista setmanal de seguiment.', null, '6bc1132b7f97f68480c74b06ce2441ba571f4bb28af025f526eebe66f757d995', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6bc1132b7f97f68480c74b06ce2441ba571f4bb28af025f526eebe66f757d995')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys una entrevista setmanal.', true), ('B', 'Almenys una entrevista cada quinze dies.', false), ('C', 'Almenys una entrevista al mes.', false), ('D', 'Només en cada revisió de la modalitat de vida.', false)) as v(label, body, ok)
)
