with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, del règim tancat, dins de quin termini màxim ha de revisar la Junta de Tractament la regressió?', 'L''apartat IV.2 obliga la Junta de Tractament a revisar la regressió com a màxim al cap de tres mesos de la resolució. El període màxim de revisió de la modalitat de vida de l''art. 93 és de 45 dies (apartat V.2.2).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat IV.2', 'La regressió l’haurà de revisar la Junta de Tractament, com a màxim, al cap de 3 mesos de la data de la resolució.', null, '2cfda738768956727930b174603416971ebd11b7e72c4e47f52454adb390e7bd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2cfda738768956727930b174603416971ebd11b7e72c4e47f52454adb390e7bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al cap de quaranta-cinc dies de la data de la resolució, com a màxim.', false), ('B', 'Al cap de sis mesos de la data de la resolució, com a màxim.', false), ('C', 'Al cap d''un mes de la data de l''ingrés al DERT, com a màxim.', false), ('D', 'Al cap de tres mesos de la data de la resolució, com a màxim.', true)) as v(label, body, ok)
)
