with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, sobre l''activitat als departaments de règim tancat (DERT), quina de les afirmacions següents NO és correcta?', 'L''apartat VI.12 fixa els mínims d''activitat grupal (1 h en l''art. 93; 2 h en la fase 1 i 3 h en la fase 2 de l''art. 94) i prohibeix donar de baixa d''una activitat: només es poden programar suspensions temporals.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat VI.12', 'Cap intern o interna pot ser donat/ada de baixa d’una activitat. En cas de mantenir conductes disruptives o de manca de participació, s’han de programar suspensions temporals de l’activitat.', null, 'c93fd67a60db20071c6f0c1819b06c3407793a8a1a4939d96740b2c9428fac77', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c93fd67a60db20071c6f0c1819b06c3407793a8a1a4939d96740b2c9428fac77')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les persones en la modalitat de vida de l''article 93 han de tenir, com a mínim, una hora d''activitat grupal al dia.', false), ('B', 'Les persones en la fase 1 de la modalitat de l''article 94 han de tenir dues hores d''activitat grupal al dia.', false), ('C', 'L''intern que manté conductes disruptives pot ser donat de baixa definitivament de l''activitat.', true), ('D', 'Les persones en la fase 2 de la modalitat de l''article 94 han de tenir tres hores d''activitat grupal al dia.', false)) as v(label, body, ok)
)
