with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, dins de quin termini màxim s''han d''elevar la proposta de regressió i els informes al Servei de Classificació, i per quina via?', 'L''apartat IV.2 demana que la Junta de Tractament adopti l''acord demorant el mínim necessari el procés i que la proposta i els informes s''elevin en un màxim de 10 dies per via telemàtica (art. 32.3 del Decret 329/2006).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat IV.2', 'En tot cas, la proposta i els informes s’han d’elevar en el termini màxim de 10 dies i per via telemàtica d’acord amb l’article 32.3 del ROFSEPC.', null, '8c3a40614df75726e60c82e4008d6396820dd8417b1cd8a835f13c5dee7c4720', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8c3a40614df75726e60c82e4008d6396820dd8417b1cd8a835f13c5dee7c4720')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini màxim de 72 hores i per correu certificat.', false), ('B', 'En el termini màxim de 10 dies i per via telemàtica.', true), ('C', 'En el termini màxim d''un mes i per via telemàtica.', false), ('D', 'En el termini màxim de 15 dies i en mà, pel cap de serveis.', false)) as v(label, body, ok)
)
