with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, a partir de quina durada d''estada continuada als DERT es considera que una persona interna és un cas de llarga estada que requereix una atenció especial?', 'L''apartat VI.14 considera llarga estada més de 9 mesos (adults) o 6 mesos (joves) i exigeix un nou pla de treball aprovat per la Junta de Tractament i ratificat pel Servei de Classificació.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat VI.14', 'Les persones que acumulen llargs períodes continuats d’estada als DERT (més de 9 mesos en el cas dels adults o 6 mesos per als joves) han de rebre una atenció especial', null, 'ecf0d395116f4989ef750c8d04cc5cefd7309f01769796ea71d3b71b6c9438a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ecf0d395116f4989ef750c8d04cc5cefd7309f01769796ea71d3b71b6c9438a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Més de 9 mesos en el cas dels adults o 6 mesos per als joves.', true), ('B', 'Més de 6 mesos en el cas dels adults o 3 mesos per als joves.', false), ('C', 'Més d''un any en el cas dels adults o 9 mesos per als joves.', false), ('D', 'Més de 45 dies, sigui quina sigui l''edat.', false)) as v(label, body, ok)
)
