  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Circular 2/2017, quins requisits ha de complir una persona en la modalitat de vida de l''article 93 per ser reassignada a la modalitat de l''article 94 del Reglament penitenciari?', 'L''apartat V.2.2 exigeix un mes mínim sense faltes molt greus o greus de l''art. 109 a)-e) del RP de 1981 i una assistència mínima del 50 % a l''activitat fora de la cel·la amb actitud correcta.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat V.2.2', 'la persona ha d’haver estat un període mínim de un mes sense faltes molt greus o greus de les previstes entre els apartats a) i e) de l’article 109 del Reglament penitenciari de 1981 (Reial decret 1201/1981, de 8 de maig) i haver mantingut una assistència mínima a l’activitat fora de la cel·la del 50 % amb una actitud correcta.', null, 'a75c8f56ee29a1ab6118c0097f2547775fda3023aa78f05da8bb4a6008686f0c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a75c8f56ee29a1ab6118c0097f2547775fda3023aa78f05da8bb4a6008686f0c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un període mínim de quinze dies sense faltes de cap mena i una assistència del 60 % a les activitats.', false), ('B', 'Un període mínim d''un mes sense faltes molt greus o greus de les previstes a l''article 109 a)-e) del RP de 1981 i una assistència mínima del 50 % a l''activitat fora de la cel·la amb actitud correcta.', true), ('C', 'Un període mínim de tres mesos sense faltes molt greus i l''acceptació expressa del programa de tractament.', false), ('D', 'Un període mínim de 45 dies sense sancions i l''informe favorable del jutge de vigilància.', false)) as v(label, body, ok)
)
