with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 72 de la Llei orgànica 1/1979, general penitenciària (LOGP), segons quin sistema s''executen les penes privatives de llibertat?', 'L''art. 72.1 LOGP estableix el sistema d''individualització científica, separat en graus, l''últim dels quals és la llibertat condicional, tal com determina el Codi penal.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.1 LOGP', 'Las penas privativas de libertad se ejecutarán según el sistema de individualización científica, separado en grados, el último de los cuales será el de libertad condicional, conforme determina el Código Penal.', null, '39f116d78fe7bca3a9bdf6c7915111a5cfac62da0bb585d7e193e86233384b69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '39f116d78fe7bca3a9bdf6c7915111a5cfac62da0bb585d7e193e86233384b69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Segons el sistema progressiu, separat en quatre períodes, el primer dels quals és el d''aïllament.', false), ('B', 'Segons el sistema d''individualització científica, separat en graus, el primer dels quals és el de llibertat condicional.', false), ('C', 'Segons el sistema d''individualització científica, separat en graus, l''últim dels quals és el de llibertat condicional.', true), ('D', 'Segons el sistema de redempció de penes pel treball, separat en graus.', false)) as v(label, body, ok)
)
