with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10 de la LOGP, què caracteritza el règim dels establiments de compliment de règim tancat o departaments especials?', 'L''art. 10.3 LOGP caracteritza el règim tancat per la limitació de les activitats en comú i un control i vigilància més grans; la permanència dura fins que desapareguin o disminueixin les raons que en van motivar l''ingrés.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 10.Tres LOGP', 'El régimen de estos centros se caracterizará por una limitación de las actividades en común de los internos y por un mayor control y vigilancia sobre los mismos en la forma que reglamentariamente se determine.', null, 'a78f16a8709a8a026c4f50f9023597b96d4e083ca8e660ac7e2bd024c627a8cc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a78f16a8709a8a026c4f50f9023597b96d4e083ca8e660ac7e2bd024c627a8cc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una limitació de les activitats en comú dels interns i un control i una vigilància més grans.', true), ('B', 'L''absència de controls rígids i l''autoresponsabilitat dels interns.', false), ('C', 'La pernoctació fora del centre amb control telemàtic.', false), ('D', 'L''aïllament total i permanent de l''intern, sense activitats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72 de la LOGP, un intern pot ser situat inicialment en un grau superior sense haver de passar necessàriament pels que el precedeixen?', 'L''art. 72.3 LOGP admet la classificació inicial en grau superior sense passar pels precedents, excepte la llibertat condicional; i l''art. 72.4 impedeix mantenir un intern en un grau inferior quan mereix la progressió.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.Tres LOGP', 'Siempre que de la observación y clasificación correspondiente de un interno resulte estar en condiciones para ello, podrá ser situado inicialmente en grado superior, salvo el de libertad condicional, sin tener que pasar necesariamente por los que le preceden.', null, 'b686a5eb92499c6e3d90fcf3dafe6a59659dac5684eedb81ad36a91b44a85adc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b686a5eb92499c6e3d90fcf3dafe6a59659dac5684eedb81ad36a91b44a85adc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, si de l''observació i classificació resulta que està en condicions per a això, excepte en el grau de llibertat condicional.', true), ('B', 'No, la classificació inicial ha de ser sempre en primer grau.', false), ('C', 'No, la classificació inicial ha de ser sempre en segon grau.', false), ('D', 'Sí, en qualsevol grau, inclosa la llibertat condicional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72.5 de la LOGP, la classificació o progressió al tercer grau requereix que el penat hagi satisfet la responsabilitat civil derivada del delit, i aquesta norma s''aplica singularment a determinats delictes. Quin dels següents NO s''hi esmenta?', 'L''art. 72.5 LOGP esmenta singularment els delictes contra el patrimoni i l''ordre socioeconòmic de notòria gravetat, contra els drets dels treballadors, contra la Hisenda Pública i la Seguretat Social i contra l''Administració pública (capítols V a IX del títol XIX del llibre II del Codi penal).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 72.Cinco LOGP', 'a) Delitos contra el patrimonio y contra el orden socioeconómico que hubieran revestido notoria gravedad y hubieran perjudicado a una generalidad de personas. b) Delitos contra los derechos de los trabajadores. c) Delitos contra la Hacienda Pública y contra la Seguridad Social. d) Delitos contra la Administración pública comprendidos en los capítulos V al IX del título XIX del libro II del Código Penal.', null, '593c4c94b3c8b7c9253392add36d20006ad50c1ee62ebe996e8b13e5f1a9edaf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '593c4c94b3c8b7c9253392add36d20006ad50c1ee62ebe996e8b13e5f1a9edaf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els delictes contra els drets dels treballadors.', false), ('B', 'Els delictes contra la Hisenda Pública i contra la Seguretat Social.', false), ('C', 'Els delictes contra el patrimoni i contra l''ordre socioeconòmic de notòria gravetat que hagin perjudicat una generalitat de persones.', false), ('D', 'Els delictes contra la seguretat viària.', true)) as v(label, body, ok)
)
