insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 93 del Reglament penitenciari, de quantes hores diàries de sortida al pati han de gaudir, com a mínim, els interns destinats a departaments especials?', 'Als departaments especials el mínim és de tres hores diàries de pati, ampliables fins a tres hores més per a activitats programades (art. 93.1.1a RP). Les quatre hores de vida en comú corresponen als mòduls o centres tancats (art. 94 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP, norma 1a', 'Los internos disfrutarán, como mínimo, de tres horas diarias de salida al patio. Este número podrá ampliarse hasta tres horas más para la realización de actividades programadas.', null, '4a4b2bd6c723281dd0bbf113d217ce735b141e91292165d2116c6bbb86a8b93b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4a4b2bd6c723281dd0bbf113d217ce735b141e91292165d2116c6bbb86a8b93b')
  returning id
), o as (
