with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 80 del Reglament penitenciari, quin dels següents NO és un tipus d''establiment de règim obert?', 'L''art. 80.1 RP enumera tres tipus d''establiments de règim obert: els centres oberts o d''inserció social, les seccions obertes i les unitats dependents. Els departaments especials són una modalitat del règim tancat (art. 91 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 80.1 RP', 'a) Centros Abiertos o de Inserción Social. b) Secciones Abiertas. c) Unidades Dependientes.', null, '881dda000a129eb075f0ba7ce4e8f331566864d55cd5bf40ca9659bb8d18c625', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '881dda000a129eb075f0ba7ce4e8f331566864d55cd5bf40ca9659bb8d18c625')
  returning id
