with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quan s''aplica el règim tancat a un intern preventiu, en quin termini màxim s''ha de revisar l''acord?', 'L''art. 98.2 RP fixa un màxim de tres mesos per revisar l''acord. L''acord de la junta de tractament s''ha de notificar a l''intern dins de 24 hores i s''ha de comunicar al jutge de vigilància dins de 72 hores (art. 97.2 RP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Arts. 97.2 i 98.2 RP', 'En todo caso, la revisión del acuerdo a que se refiere el artículo anterior, no podrá demorarse más de tres meses, previa emisión de los preceptivos informes.', null, 'da37ab7bba9cc2843d23d86f74b8ea5398cab73ee106254c37e16cd7cbdb4d16', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'da37ab7bba9cc2843d23d86f74b8ea5398cab73ee106254c37e16cd7cbdb4d16')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
