)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 101 del Reglament penitenciari, quina de les correspondències següents entre grau de classificació i règim NO és correcta?', 'L''art. 101 RP vincula el segon grau al règim ordinari, el tercer al règim obert (en qualsevol modalitat) i el primer al règim tancat.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 101 RP', 'La clasificación en segundo grado implica la aplicación de las normas correspondientes al régimen ordinario de los Establecimientos. 2. El tercer grado determina la aplicación del régimen abierto en cualquiera de sus modalidades. 3. El primer grado determina la aplicación de las normas del régimen cerrado.', null, '0288892ac6086d2729a8adf9e2724fc9aca479649f5e02e0219233508953115c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0288892ac6086d2729a8adf9e2724fc9aca479649f5e02e0219233508953115c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El segon grau implica l''aplicació de les normes del règim ordinari.', false), ('B', 'El tercer grau determina l''aplicació de les normes del règim ordinari.', true), ('C', 'El tercer grau determina l''aplicació del règim obert en qualsevol de les seves modalitats.', false), ('D', 'El primer grau determina l''aplicació de les normes del règim tancat.', false)) as v(label, body, ok)
)
