select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 85 del Reglament penitenciari, què s''ha de fer quan un intern ingressa en un establiment de règim obert?', 'L''art. 85.1 RP preveu una entrevista amb un professional que informi l''intern de les normes, els serveis, els horaris i la convivència; després, un membre de l''Equip Tècnic l''entrevista i l''equip adopta les decisions per executar el programa de tractament (art. 85.2).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 85.1 RP', 'Al ingresar el interno en un Establecimiento de régimen abierto mantendrá una entrevista con un profesional del Centro, quien le informará de las normas de funcionamiento que rijan en la unidad, de cómo poder utilizar los servicios y recursos, de los horarios y de todos aquellos aspectos que regulen la convivencia del Centro.', null, '88a1456c802b0c650247bb2555a03e9727b8d2127e45f3c3b4d6bd19e7368b3f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '88a1456c802b0c650247bb2555a03e9727b8d2127e45f3c3b4d6bd19e7368b3f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha de passar cinc dies al departament d''ingressos abans de poder sortir.', false), ('B', 'Ha de signar un compromís davant del jutge de vigilància.', false), ('C', 'Ha de ser escorcollat amb nu integral en tots els casos.', false), ('D', 'Ha de mantenir una entrevista amb un professional del centre, que l''ha d''informar de les normes de funcionament, dels serveis i recursos, dels horaris i de la convivència.', true)) as v(label, body, ok)
