  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 90 del Reglament penitenciari, en quin tipus de cel·les s''ha de complir el règim tancat?', 'L''art. 90.2 RP exigeix que el règim tancat es compleixi en tot cas en cel·les individuals, amb limitació de les activitats en comú i més control i vigilància.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 90.2 RP', 'En todo caso, se cumplirá en celdas individuales, caracterizándose por una limitación de las actividades en común de los internos y por un mayor control y vigilancia sobre los mismos', null, 'b414c2afebdc6a1ea6cfb682899531dab7dc3592cf285da8885df0223844de55', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b414c2afebdc6a1ea6cfb682899531dab7dc3592cf285da8885df0223844de55')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En cel·les dobles, per raons de seguretat.', false), ('B', 'En dependències col·lectives d''un màxim de cinc interns.', false), ('C', 'En cel·les individuals, en tot cas.', true), ('D', 'En el tipus de cel·la que decideixi en cada cas el cap d''unitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 76 del Reglament penitenciari, quina consideració tenen el treball i la formació en els establiments de règim ordinari?', 'L''art. 76.3 RP considera el treball i la formació activitat bàsica en la vida del centre de règim ordinari, on la seguretat, l''ordre i la disciplina tenen la seva raó de ser i el seu límit en una convivència ordenada (art. 76.1).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 76.3 RP', 'El trabajo y la formación tendrán la consideración de actividad básica en la vida del Centro.', null, '92428858ec571283a9715d91a7ebd856c34cfba32045c525a6e2e306a03ae78c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '92428858ec571283a9715d91a7ebd856c34cfba32045c525a6e2e306a03ae78c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La consideració d''activitat bàsica en la vida del centre.', true), ('B', 'La consideració d''activitats voluntàries i complementàries.', false), ('C', 'La consideració de recompenses per bona conducta.', false), ('D', 'La consideració de prestacions personals obligatòries.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
