with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 77 del Reglament penitenciari, en l''horari del règim ordinari, quantes hores s''han de garantir per al descans nocturn i quin temps mínim per a assumptes propis?', 'L''art. 77.2 RP garanteix vuit hores de descans nocturn, un mínim de dues hores per a assumptes propis i temps suficient per a activitats culturals, terapèutiques i contactes amb l''exterior.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 77.2 RP', 'En cualquier caso, se garantizarán ocho horas de descanso nocturno, un mínimo de dos horas para que el interno pueda dedicarlas a asuntos propios', null, 'f3f585b30d36e75b0be23a4f2e4991c553aae75f9a43049f3c8028c193b0a0b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f3f585b30d36e75b0be23a4f2e4991c553aae75f9a43049f3c8028c193b0a0b0')
  returning id
), o as (
