  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Set hores de descans nocturn i un mínim d''una hora per a assumptes propis.', false), ('B', 'Vuit hores de descans nocturn i un mínim de dues hores per a assumptes propis.', true), ('C', 'Nou hores de descans nocturn i un mínim de tres hores per a assumptes propis.', false), ('D', 'Vuit hores de descans nocturn i un mínim de quatre hores per a assumptes propis.', false)) as v(label, body, ok)
)
