select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 87 del Reglament penitenciari, com a norma general, quina és la durada màxima de les sortides de cap de setmana dels interns en establiments de règim obert?', 'L''art. 87.2 RP fixa com a màxim de les setze hores del divendres a les vuit del dilluns; si hi ha festius consecutius, la sortida s''amplia vint-i-quatre hores per cada festiu (art. 87.3).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 87.2 RP', 'Como norma general, estos internos disfrutarán de salidas de fin de semana, como máximo, desde las dieciséis horas del viernes hasta las ocho horas del lunes.', null, 'a8ff69377d2b1c465f518e486a304a522fdec32faa12c06de963c1aa717d8d4b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a8ff69377d2b1c465f518e486a304a522fdec32faa12c06de963c1aa717d8d4b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Des de les vint hores del divendres fins a les vint hores del diumenge.', false), ('B', 'Des de les dotze hores del dissabte fins a les vuit hores del dilluns.', false), ('C', 'Des de les setze hores del divendres fins a les vuit hores del dilluns.', true), ('D', 'Des de les setze hores del divendres fins a les dotze hores del dilluns.', false)) as v(label, body, ok)
)
