select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 88 del Reglament penitenciari, com reben, com a regla general, l''assistència sanitària els interns en règim obert?', 'L''art. 88.1 RP estableix que, com a regla general, els interns en règim obert s''atenen a la xarxa sanitària pública extrapenitenciària; els treballadors socials els orienten en els tràmits (art. 88.3).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 88.1 RP', 'Como regla general, los internos en régimen abierto recibirán la asistencia sanitaria que precisen a través de la red sanitaria pública extrapenitenciaria.', null, 'acec3a65d3e0f38904f6667bbe083791e92dbf03b8406ed36755ef5b19a57f0f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'acec3a65d3e0f38904f6667bbe083791e92dbf03b8406ed36755ef5b19a57f0f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivament a través dels serveis mèdics del centre penitenciari.', false), ('B', 'A través de mútues privades contractades per l''Administració penitenciària.', false), ('C', 'A través de l''hospital penitenciari de referència.', false), ('D', 'A través de la xarxa sanitària pública extrapenitenciària.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 81 del Reglament penitenciari, qui pot destinar els interns a les unitats dependents i amb quina condició?', 'L''art. 81.3 RP atribueix la destinació a unitats dependents al centre directiu, a proposta de la Junta de Tractament, amb l''acceptació expressa de les normes per part de l''intern.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 81.3 RP', 'A las Unidades Dependientes, podrán ser destinados por el Centro Directivo, a propuesta de la Junta de Tratamiento, aquellos internos que, previa aceptación expresa de las normas de funcionamiento, se adecuen a los objetivos específicos del programa establecido.', null, '9772a33b43d6faef90fc13616e4324865ffe2d6c9d97cc0ed2851f556f8e88c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9772a33b43d6faef90fc13616e4324865ffe2d6c9d97cc0ed2851f556f8e88c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge de vigilància, a proposta del director, sense necessitat d''acceptació de l''intern.', false), ('B', 'El director del centre, amb informe del cap de serveis.', false), ('C', 'El centre directiu, a proposta de la Junta de Tractament, si l''intern accepta expressament les normes de funcionament i s''adequa als objectius del programa.', true), ('D', 'La Junta de Tractament, amb l''aprovació de l''entitat col·laboradora.', false)) as v(label, body, ok)
)
