with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 82 del Reglament penitenciari, quin òrgan pot establir per a determinats penats classificats en tercer grau una modalitat de vida en règim obert restringit i restringir-ne les sortides a l''exterior?', 'L''art. 82.1 RP faculta la Junta de Tractament per establir el règim obert restringit en casos de trajectòria delictiva peculiar, personalitat anòmala, condicions personals diverses, impossibilitat de treballar a l''exterior o quan ho aconselli el tractament.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 82.1 RP', 'la Junta de Tratamiento podrá establecer la modalidad de vida en régimen abierto adecuada para estos internos y restringir las salidas al exterior, estableciendo las condiciones, controles y medios de tutela que se deban observar', null, '4ae00980972a4e8c4454d9e23b1dc916bb2499e0a64c273b0c7857bc530cba43', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4ae00980972a4e8c4454d9e23b1dc916bb2499e0a64c273b0c7857bc530cba43')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge de vigilància penitenciària.', false), ('B', 'La Junta de Tractament.', true), ('C', 'El Consell de Direcció.', false), ('D', 'El centre directiu, a proposta del cap de serveis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 83 del Reglament penitenciari, quin dels següents NO és un dels principis que regeixen l''activitat penitenciària en règim obert?', 'L''art. 83.2 RP enumera l''atenuació de les mesures de control, l''autoresponsabilitat, la normalització social i integració, la prevenció i la coordinació amb organismes i institucions. No hi ha cap intensificació del control.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 83.2 RP', 'a) Atenuación de las medidas de control, sin perjuicio del establecimiento de programas de seguimiento y evaluación de las actividades realizadas por los internos dentro y fuera del Establecimiento. b) Autorresponsabilidad, mediante el estímulo de la participación de los internos en la organización de las actividades.', null, 'd339f0c7e5a67c7dbc525a10171d705b1a421205a55d5de0d37dd879ee7ce58d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd339f0c7e5a67c7dbc525a10171d705b1a421205a55d5de0d37dd879ee7ce58d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''autoresponsabilitat, mitjançant l''estímul de la participació dels interns en l''organització de les activitats.', false), ('B', 'La normalització social i la integració.', false), ('C', 'La prevenció per evitar la desestructuració familiar i social.', false), ('D', 'La intensificació de les mesures de control dins i fora de l''establiment.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 91 del Reglament penitenciari, quins penats classificats en primer grau han de ser destinats a departaments especials?', 'L''art. 91.3 RP destina als departaments especials els protagonistes o inductors d''alteracions molt greus amb perillositat extrema; els que mostren manifesta inadaptació als règims comuns van a centres o mòduls de règim tancat (art. 91.2).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 91.3 RP', 'Serán destinados a departamentos especiales aquellos penados clasificados en primer grado que hayan sido protagonistas o inductores de alteraciones regimentales muy graves, que hayan puesto en peligro la vida o integridad de los funcionarios, Autoridades, otros internos o personas ajenas a la Institución, tanto dentro como fuera de los Establecimientos y en las que se evidencie una peligrosidad extrema.', null, '8a96ffa6903781dc78158e47e5a0bffcedcc5d49056eec1c9b6d9e0345b7cfdc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a96ffa6903781dc78158e47e5a0bffcedcc5d49056eec1c9b6d9e0345b7cfdc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els que mostrin una manifesta inadaptació als règims comuns.', false), ('B', 'Els que hagin estat protagonistes o inductors d''alteracions regimentals molt greus que hagin posat en perill la vida o la integritat de les persones i en què s''evidenciï una perillositat extrema.', true), ('C', 'Tots els condemnats per delictes de terrorisme, sigui quina sigui la seva conducta.', false), ('D', 'Els que tinguin pendent alguna causa en situació de preventiu.', false)) as v(label, body, ok)
)
