select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 92 del Reglament penitenciari, qui acorda l''assignació de les modalitats de vida del règim tancat i qui l''autoritza?', 'L''art. 92.1 RP atribueix l''acord a la Junta de Tractament (previ informe de l''Equip Tècnic) i l''autorització al centre directiu; la Circular 2/2017 encomana l''aprovació dels canvis al Servei de Classificació del centre directiu.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 92.1 RP', 'La asignación de las modalidades de vida previstas en el artículo anterior será acordada por la Junta de Tratamiento, previo informe del Equipo Técnico, y será autorizada por el Centro Directivo.', null, '3e5145c02d0c6081e4a58dfda1198fc080e690e04229f03abe13491bc680e3c2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e5145c02d0c6081e4a58dfda1198fc080e690e04229f03abe13491bc680e3c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acorda el director, amb informe del cap de serveis, i l''autoritza el jutge de vigilància.', false), ('B', 'L''acorda el Consell de Direcció i l''autoritza la Junta de Tractament.', false), ('C', 'L''acorda la Junta de Tractament, amb informe previ de l''Equip Tècnic, i l''autoritza el centre directiu.', true), ('D', 'L''acorda el centre directiu i l''autoritza el jutge de vigilància.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 93 del Reglament penitenciari, en els departaments especials, quan es pot recórrer a l''escorcoll amb despullament integral dels interns?', 'La norma 2a de l''art. 93.1 RP preveu registre de cel·les i escorcoll diaris; el despullament integral només amb sospites fonamentades i urgència, per ordre motivada del cap de serveis i donant compte al director, en la forma de l''art. 68.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1.2ª RP', 'Cuando existan fundadas sospechas de que el interno posee objetos prohibidos y razones de urgencia exijan una actuación inmediata, podrá recurrirse al desnudo integral por orden motivada del Jefe de Servicios, dando cuenta al Director.', null, 'f493d44d8e46434b0a205adb2365967718e2913ee44c427f55fbd80b0404e22c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f493d44d8e46434b0a205adb2365967718e2913ee44c427f55fbd80b0404e22c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diàriament i de manera sistemàtica a tots els interns, sense necessitat d''ordre.', false), ('B', 'Només amb l''autorització prèvia del jutge de vigilància.', false), ('C', 'Per decisió de qualsevol funcionari del departament, sense comunicar-ho.', false), ('D', 'Quan hi hagi sospites fonamentades que l''intern posseeix objectes prohibits i raons d''urgència exigeixin una actuació immediata, per ordre motivada del cap de serveis, donant-ne compte al director.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 103 del Reglament penitenciari, en quin termini màxim ha de dictar el centre directiu la resolució sobre la proposta de classificació inicial?', 'L''art. 103.4 RP fixa dos mesos des de la recepció de la proposta per dictar la resolució, escrita i motivada; el termini es pot ampliar fins a dos mesos més (art. 103.6).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 103.4 RP', 'La resolución sobre la propuesta de clasificación penitenciaria se dictará, de forma escrita y motivada, por el Centro Directivo en el plazo máximo de dos meses desde su recepción.', null, '1a6156a392da4c76ff73d0adad60919c906b4d3bdfec12fab51ecd67164487db', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a6156a392da4c76ff73d0adad60919c906b4d3bdfec12fab51ecd67164487db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos mesos des que la rep.', true), ('B', 'Un mes des que la rep.', false), ('C', 'Tres mesos des de l''ingrés del penat.', false), ('D', 'Quinze dies hàbils des que la rep.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 104 del Reglament penitenciari, què passa quan un penat té pendents una o més causes en situació de preventiu?', 'L''art. 104.1 RP impedeix formular la proposta de classificació inicial mentre duri la situació de preventiu; si el penat ja estava classificat i se li decreta presó preventiva per una altra causa, la classificació queda sense efecte (art. 104.2).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 104.1 RP', 'Cuando un penado tuviese además pendiente una o varias causas en situación de preventivo, no se formulará propuesta de clasificación inicial mientras dure esta situación procesal.', null, '43bd2f00772008fd098651a1b53a9cddb88d6f50e9898b0d62d160dff00d34ac', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '43bd2f00772008fd098651a1b53a9cddb88d6f50e9898b0d62d160dff00d34ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se''l classifica directament en primer grau.', false), ('B', 'Se''l classifica provisionalment en segon grau.', false), ('C', 'No es formula proposta de classificació inicial mentre duri aquesta situació processal.', true), ('D', 'La Junta de Tractament formula la proposta, però el jutge de vigilància l''ha d''aprovar.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 108 del Reglament penitenciari, què s''ha de fer amb un intern classificat en tercer grau que no retorna al centre després d''haver gaudit d''un permís de sortida?', 'L''art. 108.1 RP preveu la classificació provisional en segon grau; produït el reingrés, el director acorda com a mesura cautelar el pas provisional a règim ordinari fins a la reclassificació (art. 108.2).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 108.1 i 108.2 RP', 'se le clasificará provisionalmente en segundo grado, en espera de efectuar la reclasificación correspondiente cuando vuelva a ingresar en un Centro penitenciario. 2. Producido el reingreso, el Director del Centro acordará, como medida cautelar, el pase provisional a régimen ordinario hasta que se efectúe la reclasificación correspondiente.', null, 'bd04602464544a2647252dbf0294305e78d3ca87562c676663348191232ddea0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bd04602464544a2647252dbf0294305e78d3ca87562c676663348191232ddea0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se''l classifica directament en primer grau, sense possibilitat de recurs.', false), ('B', 'Se''l classifica provisionalment en segon grau i, quan reingressa, el director n''acorda el pas provisional a règim ordinari com a mesura cautelar fins a la reclassificació.', true), ('C', 'Manté el tercer grau fins que el jutge de vigilància decideixi.', false), ('D', 'Se li revoca automàticament la llibertat condicional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 95.3 del Reglament penitenciari, si hi ha hagut motí, agressió física amb arma o objecte perillós, presa d''ostatges o intent violent d''evasió, el centre directiu pot acordar el trasllat del penat a un establiment de règim tancat sense resolució prèvia de classificació en primer grau. Dins de quin termini s''ha de dictar aquesta resolució?', 'L''art. 95.3 RP admet el trasllat immediat en aquests supòsits, però la resolució de classificació en primer grau s''ha de fer dins dels catorze dies següents, i el trasllat s''ha de comunicar immediatament al jutge de vigilància.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 95.3 RP', 'Mediando motín, agresión física con arma u objeto peligroso, toma de rehenes o intento violento de evasión, el traslado del penado a un Establecimiento de régimen cerrado podrá acordarse por el Centro Directivo, aunque no se haya producido resolución clasificatoria en primer grado, que, en todo caso, deberá efectuarse dentro de los catorce días siguientes', null, '075a9302e46ed3d49df409ec950444906d98248ce3e869237052632706c48da0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '075a9302e46ed3d49df409ec950444906d98248ce3e869237052632706c48da0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins dels catorze dies següents, donant compte immediatament del trasllat al jutge de vigilància.', true), ('B', 'Dins de les setanta-dues hores següents.', false), ('C', 'Dins del mes següent.', false), ('D', 'Dins dels dos mesos següents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
