with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 97 del Reglament penitenciari, en quin termini s''ha de notificar a l''intern preventiu l''acord d''aplicació de les normes del règim tancat?', 'L''art. 97.2 RP exigeix notificar l''acord a l''intern en vint-i-quatre hores, amb expressió del dret d''acudir al jutge de vigilància; al jutge se li dona coneixement dins de les setanta-dues hores.', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 97.2 RP', 'El acuerdo se notificará al interno, mediante entrega de copia del mismo, dentro de las veinticuatro horas siguientes a su adopción, con expresión del derecho de acudir al Juez de Vigilancia', null, '73fc25fb5db4d2d432006902d7b597b7ab7b470180e2d796be73647e22690e86', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '73fc25fb5db4d2d432006902d7b597b7ab7b470180e2d796be73647e22690e86')
  returning id
