with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 103 del Reglament penitenciari, fins a quant pot ampliar el centre directiu el termini per dictar la resolució de classificació inicial i amb quina finalitat?', 'L''art. 103.6 RP permet ampliar el termini fins a dos mesos més per observar millor la conducta i consolidar els factors positius; el mateix règim s''aplica a les progressions i regressions (art. 106.5).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 103.6 RP', 'El Centro Directivo podrá ampliar el plazo para dictar la resolución de clasificación inicial hasta un máximo de dos meses más, para la mejor observación de la conducta y la consolidación de los factores positivos del interno.', null, '096d8ef722631fcbc6912afd3a11af7bca8b0d19d3ad1cd27f737c30a1c0167e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '096d8ef722631fcbc6912afd3a11af7bca8b0d19d3ad1cd27f737c30a1c0167e')
  returning id
), o as (
