  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fins a un màxim de dos mesos més, per a una millor observació de la conducta i la consolidació dels factors positius de l''intern.', true), ('B', 'Fins a un màxim de sis mesos més, per completar l''estudi de la personalitat.', false), ('C', 'Fins a un màxim d''un mes més, per demanar informe al jutge de vigilància.', false), ('D', 'No el pot ampliar en cap cas.', false)) as v(label, body, ok)
)
