with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 109 del Reglament penitenciari, quina de les funcions següents NO correspon a la Central Penitenciària d''Observació?', 'L''art. 109.1 RP atribueix a la Central Penitenciària d''Observació completar la labor dels equips tècnics, informar sobre qüestions tècniques i requeriments pericials, investigar i participar en la docència. Els recursos contra la classificació els resol el jutge de vigilància (art. 76.2 f LOGP).', 'pcat_e15_classificacio_regims', (select id from public.topics where slug = 'pcat-e15-classificacio-regims'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 109.1 RP', 'a) Completar la labor de los Equipos Técnicos de los Establecimientos en sus tareas específicas. […] c) Realizar una labor de investigación criminológica. d) Participar en las tareas docentes y de formación de funcionarios.', null, '2e17a0f3814784e93f77f15be3001851bed82fd5a0bec4f31115a9fe11305008', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2e17a0f3814784e93f77f15be3001851bed82fd5a0bec4f31115a9fe11305008')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Completar la labor dels equips tècnics dels establiments en les seves tasques específiques.', false), ('B', 'Fer una labor d''investigació criminològica.', false), ('C', 'Resoldre els recursos dels interns contra les resolucions de classificació.', true), ('D', 'Participar en les tasques docents i de formació de funcionaris.', false)) as v(label, body, ok)
)
