with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, els equips multidisciplinaris són:', 'L''art. 36 del Decret 329/2006 defineix els equips multidisciplinaris com les unitats d''estudi, proposta i execució de la junta de tractament, encarregades de proposar i executar els programes de tractament o els models individualitzats d''intervenció.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 36 D329', 'Els equips multidisciplinaris seran les unitats d''estudi, proposta i execució amb que comptarà la Junta de Tractament.', null, '48cfe5cca878783dfd4e6fb4a3fbdbbda9ab9c172c6cef8b34eb0820b167b261', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '48cfe5cca878783dfd4e6fb4a3fbdbbda9ab9c172c6cef8b34eb0820b167b261')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els òrgans col·legiats que resolen els expedients disciplinaris per faltes greus i molt greus.', false), ('B', 'Les unitats de gestió administrativa dels expedients personals dels interns.', false), ('C', 'Les unitats d''estudi, proposta i execució amb què compta la junta de tractament.', true), ('D', 'Els òrgans de direcció que aproven la classificació inicial dels interns penats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, sota la direcció de quin òrgan actua l''equip multidisciplinari dels centres penitenciaris?', 'L''art. 37.1 del Decret 329/2006 estableix que a cada centre hi ha, almenys, un equip multidisciplinari, que actua sota la direcció del/de la subdirector/a de Tractament.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.1 D329', 'En els centres penitenciaris hi haurà, almenys, un equip multidisciplinari. L''equip multidisciplinari actuarà sota la direcció del/de la subdirector/a de Tractament.', null, '3cc4a865202ca4a019ed9c93af538a712fa757e92c6cc4328cecd2db51d6beae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3cc4a865202ca4a019ed9c93af538a712fa757e92c6cc4328cecd2db51d6beae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del/de la director/a del centre penitenciari.', false), ('B', 'Del/de la gerent del centre penitenciari.', false), ('C', 'Del/de la subdirector/a de Tractament.', true), ('D', 'Del/de la cap de serveis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 37.2 del Decret 329/2006, quin dels professionals següents NO figura entre els que formen part de l''equip multidisciplinari?', 'L''art. 37.2 enumera el coordinador o cap de programes, psicòleg, jurista, educador, docent, metge, treballador social, monitor ocupacional o insertor laboral, monitor esportiu i cap d''unitat o coordinador d''unitat especialitzada. El director no en forma part.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.2 D329', '2. Formaran part de l''equip multidisciplinari: a) El/La coordinador/a dels equips multidisciplinaris, si n''hi ha, o el/la cap de programes d''atenció especialitzada. b) El/La psicòleg/oga adscrit/a a l''equip. c) El/La jurista adscrit/a a l''equip. d) L''educador/a adscrit/a a l''equip. e) Un/a docent. f) Un/a metge/essa. g) Un/a treballador/a social. h) Un/a monitor/a ocupacional i/o insertor/a laboral. i) Un/a monitor/a esportiu/iva. j) El/La cap d''unitat o el/la coordinador/a d''unitat especialitzada.', null, '2e76eecbcc39412b61c8964718218d96536b99ea454281d8626219c535b07a4a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2e76eecbcc39412b61c8964718218d96536b99ea454281d8626219c535b07a4a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El/La jurista adscrit/a a l''equip.', false), ('B', 'Un/a monitor/a esportiu/iva.', false), ('C', 'El/La cap d''unitat o el/la coordinador/a d''unitat especialitzada.', false), ('D', 'El/La director/a del centre penitenciari.', true)) as v(label, body, ok)
)
