with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quins professionals s''incorporen a les reunions de l''equip multidisciplinari només en les unitats que els tinguin assignats?', 'L''art. 37.3 del Decret 329/2006 preveu que les unitats que en tinguin assignats incorporin a les reunions el psiquiatre, l''infermer, el pedagog i el criminòleg. Els altres professionals citats formen part de l''equip d''acord amb l''art. 37.2.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 37.3 D329', '3. Aquelles unitats que en tinguin assignats incorporaran a les reunions de l''equip els professionals següents: a) Un/a psiquiatre/a. b) Un/a infermer/a. c) Un/a pedagog/a. d) Un/a criminòleg/oga.', null, 'a037406636131b44e2958cb32154b60cf66284dbea5f921817a0f362720c7fbf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a037406636131b44e2958cb32154b60cf66284dbea5f921817a0f362720c7fbf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un/a psiquiatre/a, un/a infermer/a, un/a pedagog/a i un/a criminòleg/oga.', true), ('B', 'Un/a psicòleg/oga, un/a jurista, un/a educador/a i un/a docent.', false), ('C', 'Un/a metge/essa, un/a treballador/a social, un/a monitor/a esportiu/iva i un/a docent.', false), ('D', 'Un/a psiquiatre/a, un/a jurista, un/a cap de serveis i un/a criminòleg/oga.', false)) as v(label, body, ok)
)
