with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 38 del Decret 329/2006, quina de les funcions següents NO correspon als equips multidisciplinaris?', 'L''art. 38.1 atribueix als equips multidisciplinaris, entre d''altres, elaborar el programa de tractament (a), proposar la programació anual (c) i atendre peticions i queixes (e). Resoldre els expedients per faltes greus o molt greus correspon a la Comissió Disciplinària (art. 35.2.a).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 38.1 D329', 'a) Elaborar el programa de tractament o el model d''intervenció individual dels/de les interns/es que tinguin assignats/ades. […] c) Proposar a la Junta de Tractament la programació anual d''activitats del seu àmbit d''actuació […] e) Atendre les peticions i queixes que formulin els/les interns/es respecte de la seva classificació, tractament o model d''intervenció.', null, '6a1c41e035e6ce8fef0e5823df55f5b609a05eb1161fd2865ea6c2b81ebdacfc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6a1c41e035e6ce8fef0e5823df55f5b609a05eb1161fd2865ea6c2b81ebdacfc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Elaborar el programa de tractament o el model d''intervenció individual dels interns que tinguin assignats.', false), ('B', 'Proposar a la junta de tractament la programació anual d''activitats del seu àmbit d''actuació.', false), ('C', 'Atendre les peticions i queixes que formulin els interns respecte de la seva classificació, tractament o model d''intervenció.', false), ('D', 'Resoldre els expedients disciplinaris instruïts als interns per la comissió d''infraccions greus o molt greus.', true)) as v(label, body, ok)
)
