with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, l''intern que ho sol·liciti té dret a un tràmit d''audiència davant la junta de tractament en determinats procediments. En quin dels següents NO està previst aquest tràmit?', 'L''art. 32.2 del Decret 329/2006 preveu el tràmit d''audiència en la classificació inicial, la progressió al tercer grau, la proposta del primer permís ordinari, la llibertat condicional i els beneficis penitenciaris, però no en l''adjudicació de llocs de treball.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 32.2 D329', 'en els procediments de classificació inicial, progressió al tercer grau de classificació penitenciària, proposta del primer permís ordinari de sortida, llibertat condicional i beneficis penitenciaris.', null, '453414df37bb1453f4883d7a9b362a9fb47dd22a634bcfa444f570c30ba72837', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '453414df37bb1453f4883d7a9b362a9fb47dd22a634bcfa444f570c30ba72837')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En la classificació inicial.', false), ('B', 'En la proposta del primer permís ordinari de sortida.', false), ('C', 'En la progressió al tercer grau.', false), ('D', 'En l''adjudicació d''un lloc de treball en un taller productiu.', true)) as v(label, body, ok)
)
