with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 59 de la Llei orgànica 1/1979, general penitenciària (LOGP), el tractament penitenciari consisteix en:', 'L''art. 59.1 LOGP defineix el tractament com el conjunt d''activitats directament dirigides a la reeducació i reinserció social dels penats; la convivència ordenada i la seguretat són finalitats del règim i del règim disciplinari (art. 41 LOGP).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 59.1 LOGP', 'El tratamiento penitenciario consiste en el conjunto de actividades directamente dirigidas a la consecución de la reeducación y reinserción social de los penados.', null, 'b45a4f957188933a31c45d40311018f4db69d9e10a9726c919882507ca4d0c28', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b45a4f957188933a31c45d40311018f4db69d9e10a9726c919882507ca4d0c28')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El conjunt d''activitats directament dirigides a la consecució de la reeducació i la reinserció social dels penats.', true), ('B', 'El conjunt de normes que regulen la convivència ordenada i la seguretat dels establiments penitenciaris.', false), ('C', 'L''aplicació de mesures de vigilància i control a tots els interns, preventius i penats, des de l''ingrés.', false), ('D', 'El sistema de recompenses que estimula la bona conducta i l''esperit de treball dels interns.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 62 de la LOGP, quin dels següents NO és un dels principis en què s''inspira el tractament penitenciari?', 'L''art. 62 LOGP diu que el tractament serà individualitzat (c), complex (d), programat (e) i continu i dinàmic, depenent de les incidències en l''evolució de la personalitat de l''intern (f). Un tractament uniforme i estable contradiu aquests principis.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 62 LOGP', 'c) Será individualizado, consistiendo en la variable utilización de métodos médico-biológicos, psiquiátricos, psicológicos, pedagógicos y sociales, en relación a la personalidad del interno. […] e) Será programado, fijándose el plan general que deberá seguirse en su ejecución […] f) Será de carácter continuo y dinámico, dependiente de las incidencias en la evolución de la personalidad del interno durante el cumplimiento de la condena.', null, '117571859ce70914bc33024c7e7351df3cb55fbb609f8e404cf13e1bda271f89', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '117571859ce70914bc33024c7e7351df3cb55fbb609f8e404cf13e1bda271f89')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Serà individualitzat, amb la utilització variable de mètodes mèdics-biològics, psiquiàtrics, psicològics, pedagògics i socials.', false), ('B', 'Serà uniforme i estable per a tots els interns d''un mateix grau, independentment de l''evolució de la seva personalitat.', true), ('C', 'Serà programat, amb un pla general que s''ha de seguir en la seva execució.', false), ('D', 'Serà de caràcter continu i dinàmic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 59 de la LOGP, el tractament penitenciari pretén fer de l''intern una persona:', 'L''art. 59.2 LOGP diu que el tractament pretén fer de l''intern una persona amb la intenció i la capacitat de viure respectant la llei penal i de subvenir a les seves necessitats, i desenvolupar-hi una actitud de respecte a si mateix i de responsabilitat individual i social.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 59.2 LOGP', 'El tratamiento pretende hacer del interno una persona con la intención y la capacidad de vivir respetando la Ley penal, así como de subvenir a sus necesidades.', null, 'dfaa1b1aebcd9bb6b3553eaaa0a924c392811071137c729c0a1b669fb2344e70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dfaa1b1aebcd9bb6b3553eaaa0a924c392811071137c729c0a1b669fb2344e70')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb la intenció i la capacitat de viure respectant la llei penal, i també de subvenir a les seves necessitats.', true), ('B', 'Que accepti sense objeccions el règim disciplinari i les normes de convivència del centre.', false), ('C', 'Que compleixi íntegrament la condemna en el grau de classificació inicial.', false), ('D', 'Capaç d''exercir funcions auxiliars de vigilància dins de l''establiment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71 de la LOGP, el fi primordial del règim dels establiments de compliment és:', 'L''art. 71.1 LOGP subordina el règim al tractament: el fi primordial del règim és aconseguir l''ambient adequat per a l''èxit del tractament, i les funcions regimentals són mitjans, no finalitats en si mateixes.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 71.1 LOGP', 'El fin primordial del régimen de los establecimientos de cumplimiento es lograr en los mismos el ambiente adecuado para el éxito del tratamiento; en consecuencia, las funciones regimentales deben ser consideradas como medios y no como finalidades en sí mismas.', null, '582be6278fbed78a31b69decf6a9c09b9f00013d56db9a2b3ba0c295bd5d30b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '582be6278fbed78a31b69decf6a9c09b9f00013d56db9a2b3ba0c295bd5d30b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Garantir la seguretat de l''establiment, que preval sempre sobre les activitats de tractament.', false), ('B', 'Assegurar la custòdia dels interns fins a la data de llibertat definitiva.', false), ('C', 'Mantenir la disciplina mitjançant l''aplicació immediata de les sancions.', false), ('D', 'Aconseguir l''ambient adequat per a l''èxit del tractament, de manera que les funcions regimentals s''han de considerar mitjans i no finalitats en si mateixes.', true)) as v(label, body, ok)
)
