with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 47 de la LOGP, per obtenir permisos ordinaris de sortida com a preparació per a la vida en llibertat, els condemnats de segon i tercer grau han de:', 'L''art. 47.2 LOGP (i l''art. 154.1 RP) exigeix, amb l''informe previ de l''equip tècnic, haver extingit la quarta part de la condemna i no observar mala conducta.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 47.2 LOGP', 'siempre que hayan extinguido la cuarta parte de la condena y no observen mala conducta.', null, 'a2cec0ef2acc3f6f7afea8928cb5b00ace40df00782ab4db0d80cfa8790312ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2cec0ef2acc3f6f7afea8928cb5b00ace40df00782ab4db0d80cfa8790312ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Haver extingit la meitat de la condemna i no tenir cap sanció pendent de cancel·lar.', false), ('B', 'Haver extingit la quarta part de la condemna i no observar mala conducta.', true), ('C', 'Haver extingit les dues terceres parts de la condemna.', false), ('D', 'Haver extingit la tercera part de la condemna i haver satisfet la responsabilitat civil.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LOGP, es poden concedir permisos de sortida als interns preventius?', 'L''art. 48 LOGP permet concedir als preventius els permisos de l''art. 47 amb l''aprovació, en cada cas, de l''autoritat judicial corresponent (vegeu també els arts. 159 i 161.3 RP).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 48 LOGP', 'Los permisos a que se refiere el artículo anterior podrán ser concedidos asimismo a internos preventivos con la aprobación, en cada caso, de la autoridad judicial correspondiente.', null, '26212f9a848b668b6e5ac24aef34f9aebce03ae5ec5c0bffca257b02e249f70a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '26212f9a848b668b6e5ac24aef34f9aebce03ae5ec5c0bffca257b02e249f70a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, els permisos de sortida només es poden concedir als penats classificats.', false), ('B', 'Sí, amb l''autorització del centre directiu i sense intervenció judicial.', false), ('C', 'Sí, amb l''aprovació, en cada cas, de l''autoritat judicial corresponent.', true), ('D', 'Només els permisos extraordinaris, amb l''autorització del/de la director/a del centre.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 62 de la LOGP, el principi segons el qual el tractament, en general, exigeix integrar diversos mètodes en una direcció de conjunt i en el marc del règim adequat és el del seu caràcter:', 'L''art. 62.d LOGP diu que el tractament serà, en general, complex, i exigirà la integració de diversos mètodes en una direcció de conjunt. Programat (e) vol dir fixar un pla general; individualitzat (c), l''ús variable de mètodes segons la personalitat; continu i dinàmic (f), dependent de l''evolució de l''intern.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 62.d LOGP', 'd) En general será complejo, exigiendo la integración de varios de los métodos citados en una dirección de conjunto y en el marco del régimen adecuado.', null, '1f1554ad31607fca17efee690cdfc23e13dc149de0f6c6067e4ed8f47e4a80a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1f1554ad31607fca17efee690cdfc23e13dc149de0f6c6067e4ed8f47e4a80a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Complex.', true), ('B', 'Programat.', false), ('C', 'Individualitzat.', false), ('D', 'Continu i dinàmic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 66 bis de la LOGP, el seguiment i l''aprofitament dels programes específics per a persones internes condemnades per delictes relacionats amb la violència contra la infància i l''adolescència els han de valorar les juntes de tractament:', 'L''art. 66 bis LOGP (afegit per la LO 8/2021) obliga l''Administració a elaborar aquests programes i les juntes de tractament n''han de valorar el seguiment en les progressions de grau, els permisos i la llibertat condicional.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 66 bis.2 LOGP', 'Las Juntas de Tratamiento valorarán, en las progresiones de grado, concesión de permisos y concesión de la libertad condicional, el seguimiento y aprovechamiento de dichos programas específicos', null, 'e3a13c84ff7fade27230cc21ba9c63efc50a6fa2d1e054f432dae8ebb6085855', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e3a13c84ff7fade27230cc21ba9c63efc50a6fa2d1e054f432dae8ebb6085855')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només en la proposta de llibertat condicional.', false), ('B', 'En la imposició i la cancel·lació de les sancions disciplinàries.', false), ('C', 'En l''adjudicació de llocs de treball als tallers productius.', false), ('D', 'En les progressions de grau, la concessió de permisos i la concessió de la llibertat condicional.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
