with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 70 de la LOGP, quina de les funcions següents NO correspon a l''equip tècnic d''especialistes de la Central Penitenciària d''Observació?', 'L''art. 70.1 LOGP atribueix a la Central Penitenciària d''Observació completar la tasca dels equips, resoldre consultes tècniques del centre directiu, fer investigació criminològica i participar en tasques docents. Els recursos contra la classificació els resol el jutge de vigilància, no la Central.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 70.1 LOGP', 'a) Completar la labor de los Equipos de Observación y de Tratamiento en sus tareas específicas. b) Resolver las dudas y consultas de carácter técnico que se formulen por el centro directivo. c) Realizar una labor de investigación criminológica.', null, '4e209655c93ca030975184fed5948689e49dd0d295f4c9b5b55f27880b393c66', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e209655c93ca030975184fed5948689e49dd0d295f4c9b5b55f27880b393c66')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Completar la tasca dels equips d''observació i de tractament en les seves tasques específiques.', false), ('B', 'Resoldre els recursos dels interns contra els acords de classificació inicial.', true), ('C', 'Resoldre els dubtes i les consultes de caràcter tècnic que formuli el centre directiu.', false), ('D', 'Fer una tasca d''investigació criminològica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 76 de la LOGP, correspon al jutge de vigilància penitenciària autoritzar els permisos de sortida:', 'L''art. 76.2.i LOGP atribueix al jutge de vigilància autoritzar els permisos de més de dos dies, excepte els dels interns de tercer grau, que autoritza el centre directiu (art. 161.1 RP).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 76.2.i LOGP', 'i) Autorizar los permisos de salida cuya duración sea superior a dos días, excepto de los clasificados en tercer grado.', null, '9df60563e933f7cbdeef23e036f4216150aa90c0f8562861355c23a10f9e2011', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9df60563e933f7cbdeef23e036f4216150aa90c0f8562861355c23a10f9e2011')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De qualsevol durada, inclosos els dels classificats en tercer grau.', false), ('B', 'La durada dels quals sigui superior a set dies.', false), ('C', 'Només els extraordinaris dels interns preventius.', false), ('D', 'La durada dels quals sigui superior a dos dies, excepte els dels classificats en tercer grau.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 62 de la LOGP, l''estudi científic de la constitució, el temperament, el caràcter, les aptituds i les actituds del subjecte, que condueix a un judici global de la seva personalitat, s''ha de recollir:', 'L''art. 62.a LOGP diu que el tractament es basa en l''estudi científic de la personalitat, que condueix a un judici global que es recull en el protocol de l''intern.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 62.a LOGP', 'a) Estará basado en el estudio científico de la constitución, el temperamento, el carácter, las aptitudes y las actitudes del sujeto a tratar, así como de su sistema dinámico-motivacional y del aspecto evolutivo de su personalidad, conducente a un enjuiciamiento global de la misma, que se recogerá en el protocolo del interno.', null, '89ebc0974f7c6e863ffb207b87ba9d0a8f15ceb0b898a73bb187d0e81bd77bb8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '89ebc0974f7c6e863ffb207b87ba9d0a8f15ceb0b898a73bb187d0e81bd77bb8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En l''expedient disciplinari.', false), ('B', 'En el llibre d''ingressos.', false), ('C', 'En l''historial escolar de l''intern.', false), ('D', 'En el protocol de l''intern.', true)) as v(label, body, ok)
)
