with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 782/2001, quin òrgan adjudica als interns els llocs de treball dels tallers productius dels centres penitenciaris?', 'L''art. 3.2 del RD 782/2001 atribueix l''adjudicació a la junta de tractament, com a òrgan administratiu competent, amb un ordre de prelació en què el primer criteri és que el programa individualitzat de tractament prevegi una activitat laboral.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 3.2 RD 782/2001', 'La Junta de Tratamiento, como órgano administrativo competente, adjudicará los puestos a los internos, siguiendo el siguiente orden de prelación: 1.º Los internos en cuyo programa individualizado de tratamiento se contemple el desarrollo de una actividad laboral.', null, 'eb4ac4c40a2cdf740f1b3c441c44daf07a403d3a1345742fbd124b5b94fdcc1e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eb4ac4c40a2cdf740f1b3c441c44daf07a403d3a1345742fbd124b5b94fdcc1e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El/La director/a del centre.', false), ('B', 'La junta de tractament.', true), ('C', 'L''equip multidisciplinari.', false), ('D', 'El Consell de Direcció.', false)) as v(label, body, ok)
)
