with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari (RP), quan el centre directiu autoritza la constitució d''un grup en comunitat terapèutica, la junta de tractament que n''està al capdavant:', 'L''art. 115.2 RP atribueix a la junta de tractament que està al capdavant del grup en comunitat terapèutica les funcions del Consell de Direcció i de la Comissió Disciplinària, amb exclusió de les economicoadministratives.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 115.2 RP', 'Siempre que el Centro Directivo autorice la constitución de uno de estos grupos, la Junta de Tratamiento que esté al frente del mismo asumirá las funciones que tienen atribuidas el Consejo de Dirección y la Comisión Disciplinaria del Centro penitenciario, con exclusión de las que se refieran a los aspectos económico-administrativos.', null, '68c931a5eb22a77dc3231cc15ef2c5f09fdb4825bbbaad34079ad4cd2122d6eb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '68c931a5eb22a77dc3231cc15ef2c5f09fdb4825bbbaad34079ad4cd2122d6eb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Assumeix únicament les funcions de la Comissió Disciplinària respecte dels interns del grup.', false), ('B', 'Assumeix totes les funcions del Consell de Direcció, incloses les economicoadministratives, però no les disciplinàries.', false), ('C', 'Necessita l''autorització del jutge de vigilància penitenciària per exercir qualsevol funció disciplinària.', false), ('D', 'Assumeix les funcions del Consell de Direcció i de la Comissió Disciplinària, llevat de les que es refereixen als aspectes economicoadministratius.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 103 del Reglament penitenciari, el protocol de classificació penitenciària ha de contenir:', 'L''art. 103.3 RP diu que el protocol de classificació conté la proposta raonada de grau i el programa individualitzat de tractament, que ha d''assenyalar els destins, activitats, programes educatius, treball i activitats ocupacionals que ha de seguir l''intern.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 103.3 RP', 'El protocolo de clasificación penitenciaria contendrá la propuesta razonada de grado y el programa individualizado de tratamiento', null, '8b96afa11d8da41e991e841cd437912bb6653ae9a6f5f3bbc115cc0a8d5959e0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8b96afa11d8da41e991e841cd437912bb6653ae9a6f5f3bbc115cc0a8d5959e0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només la proposta raonada de grau, ja que el programa individualitzat de tractament s''elabora després de la resolució del centre directiu.', false), ('B', 'La proposta raonada de grau i el programa individualitzat de tractament.', true), ('C', 'La resolució del jutge de vigilància penitenciària i l''informe del/de la director/a.', false), ('D', 'L''informe pronòstic final i la proposta de llibertat condicional.', false)) as v(label, body, ok)
)
