with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, els permisos de sortida ordinaris es poden concedir als penats classificats en segon o tercer grau amb una durada de fins a:', 'L''art. 154.1 RP (i l''art. 47.2 LOGP) preveu permisos ordinaris de fins a set dies, amb un total de 36 dies l''any (segon grau) o 48 (tercer grau), si s''ha extingit la quarta part de la condemna i no s''observa mala conducta.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 154.1 RP', 'permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad, hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente, siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta.', null, 'c27b9349a2a1e42a012cf6b5a2c91f8b03a4ee18db1038ad24f0b95384155f32', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c27b9349a2a1e42a012cf6b5a2c91f8b03a4ee18db1038ad24f0b95384155f32')
  returning id
), o as (
