  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc dies cadascun, amb un màxim de trenta o quaranta dies l''any, respectivament.', false), ('B', 'Set dies cadascun, amb un màxim de quaranta-vuit dies l''any en tots dos graus.', false), ('C', 'Deu dies cadascun, amb un màxim de trenta-sis o quaranta-vuit dies l''any, respectivament.', false), ('D', 'Set dies cadascun, amb un màxim de trenta-sis o quaranta-vuit dies l''any, respectivament.', true)) as v(label, body, ok)
)
