)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en els supòsits d''urgència, qui pot autoritzar un permís extraordinari de sortida?', 'L''art. 161.4 RP permet que, en supòsits d''urgència, el director autoritzi el permís extraordinari, amb consulta prèvia al centre directiu si escau, i que ho comuniqui després a la junta de tractament.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 161.4 RP', 'En los supuestos de urgencia, el permiso extraordinario podrá ser autorizado por el Director del Establecimiento, previa consulta al Centro Directivo si hubiere lugar a ello, y sin perjuicio de comunicar a la Junta de Tratamiento la autorización concedida.', null, 'd40ce5cd80f8662f1c2cc47317319bba303c3dd84e8e2d9021d1ecc8a9566c3a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd40ce5cd80f8662f1c2cc47317319bba303c3dd84e8e2d9021d1ecc8a9566c3a')
