insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, on es duen a terme les activitats de tractament?', 'L''art. 113.1 RP diu que les activitats de tractament es fan tant a l''interior dels centres com fora, en funció de les condicions més adequades en cada cas; l''Administració ha de tenir en compte els recursos de la comunitat (art. 113.2).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 113.1 RP', 'Las actividades de tratamiento se realizarán tanto en el interior de los Centros penitenciarios como fuera de ellos', null, '762bf4713fee68d963405b6d9869b85d19df184437f4eac063b5416fb924031e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '762bf4713fee68d963405b6d9869b85d19df184437f4eac063b5416fb924031e')
  returning id
), o as (
