  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivament a l''interior del centre penitenciari, per raons de seguretat.', false), ('B', 'Fora del centre només quan l''intern estigui classificat en tercer grau.', false), ('C', 'Tant a l''interior dels centres penitenciaris com fora, segons les condicions més adequades per assolir els fins de la pena en cada cas.', true), ('D', 'Només a les unitats dependents i als centres oberts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
