with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, l''intern amb dependència de substàncies psicoactives que vulgui seguir programes de tractament i deshabituació:', 'L''art. 116.1 RP garanteix que tot intern drogodependent que ho desitgi pugui seguir programes de tractament i deshabituació, amb independència de la seva situació processal i de les seves vicissituds penals i penitenciàries.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 116.1 RP', 'Todo interno con dependencia de sustancias psicoactivas que lo desee, debe tener a su alcance la posibilidad de seguir programas de tratamiento y deshabituación, con independencia de su situación procesal y de sus vicisitudes penales y penitenciarias.', null, '1355cc5dd5a47c178bbcea56651e1345f3fe15b20e703a3ae0e292b491028a2d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1355cc5dd5a47c178bbcea56651e1345f3fe15b20e703a3ae0e292b491028a2d')
