insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, les certificacions acreditatives dels ensenyaments, els cursos o les activitats que l''intern ha fet:', 'L''art. 119.2 RP preveu que les certificacions s''expedeixin a sol·licitud de l''intern i que no continguin cap indicació relativa a la seva obtenció en un establiment penitenciari, per no dificultar-ne la reinserció.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 119.2 RP', 'Se expedirán a solicitud del interno certificaciones acreditativas de las enseñanzas, cursos o actividades desarrollados, que no deberán contener indicación alguna relativa a su obtención en un Establecimiento penitenciario.', null, '1a12726b68dbfe866c9fb4a6964f336cf4ea6093cc049569510457f5b351e93b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a12726b68dbfe866c9fb4a6964f336cf4ea6093cc049569510457f5b351e93b')
  returning id
), o as (
