  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''expedeixen a sol·licitud de l''intern i no poden contenir cap indicació que s''han obtingut en un establiment penitenciari.', true), ('B', 'S''expedeixen d''ofici i hi ha de constar el centre penitenciari on s''han cursat.', false), ('C', 'Només es poden expedir quan l''intern obté la llibertat definitiva.', false), ('D', 'Les expedeix el jutge de vigilància penitenciària amb l''informe de la junta de tractament.', false)) as v(label, body, ok)
