with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, si l''intern aprofita el gaudi d''un permís per fugir o comet un nou delicte durant el permís:', 'L''art. 157.2 RP disposa que el permís queda sense efecte, sens perjudici de les conseqüències penals i penitenciàries i de la valoració negativa que n''ha de fer l''equip tècnic per a futurs permisos ordinaris.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 157.2 RP', 'Si el interno aprovechase el disfrute de cualquier clase de permiso para fugarse o cometiese un nuevo delito durante el mismo, quedará sin efecto el permiso concedido', null, 'd61b2de30a8ecbf7e50bce9be352204ba9f25880fe341ec33c2d6d674479c201', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd61b2de30a8ecbf7e50bce9be352204ba9f25880fe341ec33c2d6d674479c201')
