with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quan la junta de tractament acorda denegar el permís de sortida sol·licitat per l''intern:', 'L''art. 162 RP obliga a notificar a l''intern la denegació motivada i a indicar-li expressament el dret de queixa davant el jutge de vigilància penitenciària.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 162 RP', 'Cuando la Junta de Tratamiento acuerde denegar el permiso solicitado por el interno, se notificará a éste la decisión motivada con indicación expresa de su derecho a acudir en vía de queja al Juez de Vigilancia Penitenciaria.', null, 'f756707669b4ae149b6677d1aabdf772a0f84702057a26daf31c4bbc35789f7d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f756707669b4ae149b6677d1aabdf772a0f84702057a26daf31c4bbc35789f7d')
