insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 110 del Reglament penitenciari, quina de les actuacions següents NO figura entre els elements del tractament que ha de dur a terme l''Administració penitenciària per assolir la finalitat resocialitzadora de la pena?', 'L''art. 110 RP enumera tres elements: programes formatius (a), programes i tècniques psicosocials (b) i potenciació dels contactes amb l''exterior amb els recursos de la comunitat (c). Limitar aquests contactes és el contrari del que preveu.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 110 RP', 'a) Diseñará programas formativos orientados a desarrollar las aptitudes de los internos, enriquecer sus conocimientos, mejorar sus capacidades técnicas o profesionales y compensar sus carencias. b) Utilizará los programas y las técnicas de carácter psicosocial que vayan orientadas a mejorar las capacidades de los internos […] c) Potenciará y facilitará los contactos del interno con el exterior contando, siempre que sea posible, con los recursos de la comunidad como instrumentos fundamentales en las tareas de reinserción.', null, '4d8e00f18cd8c5f715b8a8f0cc84931db1335aa1345972c9e86dd49fbe2fa865', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4d8e00f18cd8c5f715b8a8f0cc84931db1335aa1345972c9e86dd49fbe2fa865')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
