  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, en les sortides programades els interns:', 'L''art. 114.2 RP exigeix que, en tot cas, els interns vagin acompanyats per personal del centre, d''altres institucions o per voluntaris que habitualment fan activitats de tractament amb els reclusos.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 114.2 RP', 'En todo caso, los internos serán acompañados por personal del Centro penitenciario o de otras instituciones o por voluntarios que habitualmente realicen actividades relacionadas con el tratamiento penitenciario de los reclusos.', null, '57474308f56c8b331bc64a3b1bd5dab98a0ef3745e0a4139b00b225f99c5abdf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '57474308f56c8b331bc64a3b1bd5dab98a0ef3745e0a4139b00b225f99c5abdf')
