with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, els programes específics de tractament per a interns condemnats per delictes contra la llibertat sexual:', 'L''art. 116.4 RP permet a l''Administració fer programes específics per a condemnats per delictes contra la llibertat sexual segons el seu diagnòstic previ; el seguiment és sempre voluntari i no pot suposar-ne la marginació.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 116.4 RP', 'La Administración Penitenciaria podrá realizar programas específicos de tratamiento para internos condenados por delitos contra la libertad sexual a tenor de su diagnóstico previo y todos aquellos otros que se considere oportuno establecer. El seguimiento de estos programas será siempre voluntario y no podrá suponer la marginación de los internos afectados en los Centros penitenciarios.', null, 'dcb42bc34726d3bbacfb17a8dc522ea9ed71caf4794590c685060d5eaf6e9ce8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dcb42bc34726d3bbacfb17a8dc522ea9ed71caf4794590c685060d5eaf6e9ce8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són obligatoris per a tots els condemnats per aquests delictes per poder accedir al tercer grau.', false), ('B', 'Es fan d''acord amb el diagnòstic previ i el seu seguiment és sempre voluntari, sense que pugui suposar la marginació dels interns afectats.', true), ('C', 'Només es poden fer en departaments específics situats fora dels centres ordinaris.', false), ('D', 'Requereixen l''autorització prèvia del tribunal sentenciador.', false)) as v(label, body, ok)
)
