  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb el còmput dels límits anuals de permisos ordinaris (trenta-sis o quaranta-vuit dies) establerts pel Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'L''art. 154.3 RP exclou del còmput les sortides de cap de setmana del règim obert, les sortides programades de l''art. 114 i els permisos extraordinaris (l''art. 114.5 RP també diu que les sortides programades no computen).', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 154.3 RP', 'Dentro de los indicados límites no se computarán las salidas de fin de semana propias del régimen abierto ni las salidas programadas que se regulan en el artículo 114 de este Reglamento, ni los permisos extraordinarios regulados en el artículo siguiente.', null, 'b0235db1b883b24cfe98c7227e543b4ba5df5c7a55b0102acf6b0965ee2ad41a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b0235db1b883b24cfe98c7227e543b4ba5df5c7a55b0102acf6b0965ee2ad41a')
