with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb les mesures regimentals per executar programes especialitzats per a penats classificats en segon grau (art. 117 RP), quina de les afirmacions següents NO és correcta?', 'L''art. 117.2 RP prohibeix expressament que les mesures de seguiment i control consisteixin en el control personal per membres dels cossos i forces de seguretat. Les altres afirmacions reprodueixen els arts. 117.1, 117.2 i 117.5 RP.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 117.1, 117.2 i 117.5 RP', 'Los internos clasificados en segundo grado de tratamiento que presenten un perfil de baja peligrosidad social y no ofrezcan riesgos de quebrantamiento de condena […] Esta medida requerirá haber sido planificada con el interno por la Junta de Tratamiento y estará condicionada a que aquél preste su consentimiento […] que no podrán consistir en control personal por miembros de los Cuerpos y Fuerzas de Seguridad del Estado. […] La participación en el programa podrá ser revocada por decisión voluntaria del interno', null, '456529c89edd89792ff7b52495b5b1c284182944484d92ae067b118475394ce5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '456529c89edd89792ff7b52495b5b1c284182944484d92ae067b118475394ce5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden aplicar als interns que presentin un perfil de baixa perillositat social i no ofereixin riscos de trencament de condemna.', false), ('B', 'La mesura s''ha d''haver planificat amb l''intern per la junta de tractament i està condicionada que l''intern hi presti el consentiment.', false), ('C', 'Les mesures de seguiment i control del programa poden consistir en el control personal per membres dels cossos i forces de seguretat de l''Estat.', true), ('D', 'La participació en el programa es pot revocar per decisió voluntària de l''intern.', false)) as v(label, body, ok)
)
