with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, si un penat classificat en segon grau ha d''ingressar en un hospital extrapenitenciari i hi ha de romandre més de dos dies, qui ha d''autoritzar la prolongació del permís extraordinari?', 'L''art. 155.4 RP preveu permisos extraordinaris de fins a dos dies per a ingrés hospitalari; la prolongació l''autoritza el jutge de vigilància si el penat és de segon grau i el centre directiu si és de tercer grau.', 'pcat_e16_tractament', (select id from public.topics where slug = 'pcat-e16-tractament'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 155.4 RP', 'si el interno tuviera que permanecer ingresado más de dos días, la prolongación del permiso por el tiempo necesario deberá ser autorizada por el Juez de Vigilancia cuando se trate de penados clasificados en segundo grado o por el Centro Directivo para los clasificados en tercer grado.', null, 'dd2d20276566de19e38ff893ea56f5bf0265a454eabaa639e960ad8d0682ae04', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dd2d20276566de19e38ff893ea56f5bf0265a454eabaa639e960ad8d0682ae04')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El centre directiu.', false), ('B', 'El/La director/a del centre, amb l''informe mèdic previ.', false), ('C', 'La junta de tractament.', false), ('D', 'El jutge de vigilància penitenciària.', true)) as v(label, body, ok)
)
