with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, en els centres oberts o centres d''inserció social, les unitats i seccions de règim obert i els centres especials, l''exercici de la potestat disciplinària correspon:', 'L''art. 35.3 del Decret 329/2006 atribueix a la junta de tractament la potestat disciplinària i la concessió de recompenses en aquests centres i unitats i en els que hi hagi formes especials d''execució.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 35.3 D329', 'En els centres oberts o centres d''inserció social, en les unitats i seccions de règim obert, en els centres especials, en els departaments d''atenció especialitzada i en aquells altres on es duguin a terme formes especials d''execució, correspon a la Junta de Tractament l''exercici de la potestat disciplinària', null, '54c2a9a0c15c464236b1b707a9e60d83c0371251faac75575b7c84654e54a6b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '54c2a9a0c15c464236b1b707a9e60d83c0371251faac75575b7c84654e54a6b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la Comissió Disciplinària.', false), ('B', 'A la junta de tractament.', true), ('C', 'Al/A la director/a del centre.', false), ('D', 'Al/A la cap de serveis.', false)) as v(label, body, ok)
)
