with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, amb quina periodicitat la Comissió Disciplinària ha de presentar al Consell de Direcció l''informe d''anàlisi i avaluació sobre la globalitat de les mesures disciplinàries i de les recompenses adoptades al centre?', 'L''art. 35.2.h del Decret 329/2006 encarrega a la Comissió Disciplinària analitzar i avaluar les mesures disciplinàries i les recompenses i el seu impacte, i presentar-ne l''informe al Consell de Direcció cada sis mesos.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 35.2.h D329', 'Analitzar, avaluar i emetre informe sobre la globalitat de les mesures disciplinàries i de les recompenses adoptades al centre penitenciari i el seu impacte, i presentar-lo al Consell de Direcció, amb una periodicitat semestral.', null, '85b0c0513fbeb73d7445b6672c003763b3029b180d425f5679cec0f38710a0f9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '85b0c0513fbeb73d7445b6672c003763b3029b180d425f5679cec0f38710a0f9')
  returning id
), o as (
