with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, la sanció d''aïllament en cel·la no pot excedir de:', 'L''art. 42.2.a LOGP limita l''aïllament en cel·la a catorze dies. Quaranta-dos dies consecutius és el límit màxim de compliment en cas de concurrència de diverses faltes (art. 42.5 LOGP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 42.2.a LOGP', 'a) Aislamiento en celda, que no podrá exceder de catorce días.', null, 'b7a629d932a6181a753bcbbd2ba6971dabc715def1eee2cfc5094d97ab2521fe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b7a629d932a6181a753bcbbd2ba6971dabc715def1eee2cfc5094d97ab2521fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Set dies.', false), ('B', 'Catorze dies.', true), ('C', 'Vint-i-un dies.', false), ('D', 'Quaranta-dos dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 42 de la LOGP, quina de les mesures següents NO és una sanció disciplinària que es pugui imposar als interns?', 'L''art. 42.2 LOGP enumera taxativament les sancions: aïllament en cel·la, aïllament de fins a set caps de setmana, privació de permisos (fins a dos mesos), limitació de comunicacions orals, privació de passeigs i actes recreatius comuns, i amonestació. El trasllat no hi figura.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 42.2 LOGP', 'Dos. No podrán imponerse otras sanciones que: […] b) Aislamiento de hasta siete fines de semana. c) Privación de permisos de salida por un tiempo que no podrá ser superior a dos meses. […] f) Amonestación.', null, '06b870f1eae3b57cd27d6b099f388fb28fc59d7d94d65fcfdb5c049502141638', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '06b870f1eae3b57cd27d6b099f388fb28fc59d7d94d65fcfdb5c049502141638')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El trasllat forçós a un altre centre penitenciari.', true), ('B', 'L''aïllament de fins a set caps de setmana.', false), ('C', 'La privació de permisos de sortida per un temps no superior a dos mesos.', false), ('D', 'L''amonestació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 41 de la LOGP, poden els interns exercir algun servei que impliqui facultats disciplinàries?', 'L''art. 41.2 LOGP prohibeix que cap intern exerceixi serveis que impliquin facultats disciplinàries: la potestat disciplinària és exclusiva de l''Administració.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 41.2 LOGP', 'Ningún interno desempeñará servicio alguno que implique el ejercicio de facultades disciplinarias.', null, 'c6a6d25597281a55d1c99fb85c21652a626da124a9dc4bac16d155d9e3f3670d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c6a6d25597281a55d1c99fb85c21652a626da124a9dc4bac16d155d9e3f3670d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, si ho autoritza la Comissió Disciplinària.', false), ('B', 'Sí, però només sobre els interns del seu mateix mòdul.', false), ('C', 'Només els interns classificats en tercer grau.', false), ('D', 'No, cap intern no pot exercir cap servei que impliqui l''exercici de facultats disciplinàries.', true)) as v(label, body, ok)
)
