with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, a quina de les internes següents NO es pot aplicar la sanció d''aïllament?', 'L''art. 43.3 LOGP (i l''art. 254.3 RP) exclou l''aïllament de les dones gestants, de les dones fins a sis mesos després del final de l''embaràs, de les mares lactants i de les que tinguin fills amb elles. L''edat o la situació processal no n''exclouen l''aplicació.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 43.3 LOGP', 'No se aplicará esta sanción a las mujeres gestantes y las mujeres hasta seis meses después de la terminación del embarazo, a las madres lactantes y a las que tuvieran hijos consigo.', null, '684ed80e7cc1b305a32e50d24f79453fb5a4fe16c37c5d9803cb0d3b06883285', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '684ed80e7cc1b305a32e50d24f79453fb5a4fe16c37c5d9803cb0d3b06883285')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A una interna major de seixanta anys.', false), ('B', 'A una interna reincident en faltes molt greus.', false), ('C', 'A una interna gestant.', true), ('D', 'A una interna preventiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
