with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 44 de la LOGP, cap intern no pot ser sancionat sense:', 'L''art. 44.2 LOGP garanteix el dret a ser informat de la infracció i a presentar defensa verbal o escrita abans de ser sancionat. L''assessorament (per lletrat, funcionari o qualsevol persona) és un dret, no una obligació (art. 242.2.i RP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 44.2 LOGP', 'Ningún interno será sancionado sin ser previamente informado de la infracción que se le atribuya y sin que se le haya permitido presentar su defensa, verbal o escrita.', null, 'c001261021da6c1fc8062cc13080ca13fac0dd4518edaab3ed95b94efe49c92c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c001261021da6c1fc8062cc13080ca13fac0dd4518edaab3ed95b94efe49c92c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''autorització prèvia del jutge de vigilància penitenciària.', false), ('B', 'Haver estat informat prèviament de la infracció que se li atribueix i sense que se li hagi permès presentar la seva defensa, verbal o escrita.', true), ('C', 'L''assistència obligatòria d''un advocat durant tot el procediment.', false), ('D', 'La conformitat expressa de l''intern amb els fets imputats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 42 de la LOGP, la sanció d''aïllament en cel·la només és aplicable:', 'L''art. 42.4 LOGP reserva l''aïllament en cel·la als casos d''agressivitat o violència evidents o d''alteració reiterada i greu de la convivència, i exigeix que la cel·la sigui d''unes característiques anàlogues a les altres de l''establiment.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 42.4 LOGP', 'La sanción de aislamiento en celda solo será de aplicación en los casos en que se manifieste una evidente agresividad o violencia por parte del interno, o cuando éste reiterada y gravemente altere la normal convivencia en el centro.', null, 'b84ac2da01d6ee5832788beaa011f92a551a43f907f59e17edf61a11c5af7e4d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b84ac2da01d6ee5832788beaa011f92a551a43f907f59e17edf61a11c5af7e4d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A qualsevol falta molt greu o greu, amb independència de la conducta de l''intern.', false), ('B', 'Quan l''intern hagi comès tres o més faltes lleus en un mateix mes.', false), ('C', 'Només quan l''intern hagi intentat evadir-se.', false), ('D', 'Quan l''intern manifesti una agressivitat o violència evidents, o quan alteri reiteradament i greument la convivència normal del centre.', true)) as v(label, body, ok)
)
