with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari (RP), el règim disciplinari s''aplica als interns:', 'L''art. 231.2 RP aplica el règim disciplinari a tots els interns (amb l''excepció de l''art. 188.4), sigui quina sigui la seva situació processal i penitenciària, dins dels centres i durant trasllats, conduccions o sortides autoritzades.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 231.2 RP', 'El régimen disciplinario se aplicará a todos los internos, con la excepción establecida en el artículo 188.4 de este Reglamento, con independencia de su situación procesal y penitenciaria, tanto dentro de los Centros penitenciarios como durante los traslados, conducciones o salidas autorizadas que se realicen.', null, 'd65d394a3417b8bd23c7fbca47cc48fcae1e0f38588ff42a66a157819b2af670', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd65d394a3417b8bd23c7fbca47cc48fcae1e0f38588ff42a66a157819b2af670')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només als penats, i únicament dins del recinte del centre penitenciari.', false), ('B', 'Amb independència de la seva situació processal i penitenciària, tant dins dels centres com durant els trasllats, les conduccions o les sortides autoritzades.', true), ('C', 'Només als interns classificats en primer i segon grau.', false), ('D', 'Dins dels centres penitenciaris, però no durant les sortides autoritzades, en què s''aplica la legislació penal comuna.', false)) as v(label, body, ok)
)
