with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, per la comissió de faltes molt greus es pot imposar la sanció d''aïllament en cel·la amb una durada de:', 'L''art. 233.1.a RP preveu per a les faltes molt greus l''aïllament en cel·la de sis a catorze dies (si hi ha evident agressivitat o violència o alteració reiterada i greu de la convivència) o l''aïllament de fins a set caps de setmana.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.1.a RP', 'a) Sanción de aislamiento en celda de seis a catorce días de duración', null, 'bcef40cde699738370e07e1a2657bc893082cd9162a8e65663ffae7aa2123130', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bcef40cde699738370e07e1a2657bc893082cd9162a8e65663ffae7aa2123130')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un a cinc dies.', false), ('B', 'Tres a set dies.', false), ('C', 'Catorze a quaranta-dos dies.', false), ('D', 'Sis a catorze dies.', true)) as v(label, body, ok)
)
