with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, amb quines sancions es poden corregir les faltes lleus?', 'L''art. 233.3 RP limita la correcció de les faltes lleus a la privació de passeigs i actes recreatius comuns de fins a tres dies i a l''amonestació.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.3 RP', 'Las faltas leves tipificadas en el artículo 110 del Reglamento Penitenciario aprobado por el Real Decreto 1201/1981, de 8 de mayo, sólo podrán corregirse con privación de paseos y actos recreativos comunes de hasta tres días de duración y con amonestación.', null, 'f2b82aac3196045e159dd6152c4ed5707834f545eba06b6a3e3d0d9cec1ec7a8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f2b82aac3196045e159dd6152c4ed5707834f545eba06b6a3e3d0d9cec1ec7a8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només amb privació de passeigs i actes recreatius comuns de fins a tres dies i amb amonestació.', true), ('B', 'Amb aïllament en cel·la de fins a cinc dies i amb amonestació.', false), ('C', 'Amb privació de permisos de sortida de fins a un mes i amb amonestació.', false), ('D', 'Amb limitació de les comunicacions orals durant un mes com a màxim.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, en quins terminis prescriuen les faltes disciplinàries molt greus, greus i lleus, respectivament?', 'L''art. 258.1 RP fixa la prescripció de les faltes en tres anys (molt greus), dos anys (greus) i sis mesos (lleus), des de la data de comissió de la infracció.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 258.1 RP', 'Las faltas disciplinarias muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses, desde la fecha en que se hubiese cometido la infracción.', null, '150389e76fe21b4519b2771679d195dcf43d6fa5a59621d4bff66e8131e047ec', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '150389e76fe21b4519b2771679d195dcf43d6fa5a59621d4bff66e8131e047ec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres anys, dos anys i sis mesos.', true), ('B', 'Dos anys, un any i tres mesos.', false), ('C', 'Tres anys, un any i un mes.', false), ('D', 'Cinc anys, tres anys i un any.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
