with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quins terminis han de transcórrer, des del compliment de la sanció, per cancel·lar les anotacions de sancions per faltes molt greus, greus i lleus, respectivament?', 'L''art. 260.1.a RP exigeix sis mesos (molt greus), tres mesos (greus) i un mes (lleus) des del compliment de la sanció, sempre que l''intern no hagi comès una nova falta greu o molt greu en aquests terminis. Els terminis de tres anys, dos anys i sis mesos són els de prescripció.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 260.1 RP', 'a) Transcurso de seis meses para las faltas muy graves, tres meses para las graves y un mes para las leves, a contar desde el cumplimiento de la sanción.', null, 'cae924a85482066baa037d40ea1cd819e52804ee909c5aaca4bfdbfc3d16acd9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cae924a85482066baa037d40ea1cd819e52804ee909c5aaca4bfdbfc3d16acd9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any, sis mesos i tres mesos.', false), ('B', 'Tres anys, dos anys i sis mesos.', false), ('C', 'Sis mesos, tres mesos i un mes.', true), ('D', 'Tres mesos, dos mesos i un mes.', false)) as v(label, body, ok)
)
