with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, de quin termini disposa l''intern, des de la recepció del plec de càrrecs, per presentar el plec de descàrrecs per escrit o compareixer davant l''instructor?', 'L''art. 242.2.h RP concedeix a l''intern tres dies hàbils des de la recepció del plec de càrrecs per presentar descàrrecs per escrit o al·legar verbalment davant l''instructor.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 242.2.h RP', 'h) Indicación de que el interno dispone de tres días hábiles desde el momento de su recepción para presentar pliego de descargos por escrito o para comparecer ante el Instructor y alegar verbalmente', null, '0d7a68d40a58e4e46c8f19b668a2f32ff42e7f57089f64c9e98da76313bbc32e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0d7a68d40a58e4e46c8f19b668a2f32ff42e7f57089f64c9e98da76313bbc32e')
  returning id
