)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb el procediment disciplinari ordinari regulat al Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'L''art. 246.3 RP prohibeix a l''instructor tant participar en les deliberacions com prendre part en les votacions dels expedients que hagi instruït. Les altres afirmacions reprodueixen els arts. 242.1, 244.4 i 245 RP.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Arts. 242.1, 244.4, 245 i 246.3 RP', 'El Director nombrará Instructor al funcionario que estime conveniente, excluyendo al que haya practicado la información previa y a los que puedan estar implicados en los hechos. […] inmediatamente antes de redactar la propuesta de resolución, se pondrá de manifiesto al interesado para que, en un plazo de diez días, alegue […] el Instructor formulará propuesta de resolución y la elevará, junto con aquél, a la Comisión Disciplinaria para que ésta acuerde lo que proceda, notificando la propuesta al interno con indicación de su derecho a alegar verbalmente ante la Comisión […] El Instructor del expediente no podrá participar en las deliberaciones de la Comisión Disciplinaria ni podrá tomar parte en las votaciones sobre los expedientes que haya instruido.', null, 'c3897ae95253d4086d3f245dda1322c7ac7fc738de194dacb748abfbb21ccf83', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c3897ae95253d4086d3f245dda1322c7ac7fc738de194dacb748abfbb21ccf83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El/La director/a nomena instructor el funcionari que consideri convenient, excloent qui hagi practicat la informació prèvia i qui pugui estar implicat en els fets.', false), ('B', 'Immediatament abans de redactar la proposta de resolució, es posa de manifest el procediment a l''intern perquè, en un termini de deu dies, al·legui o presenti documents.', false), ('C', 'L''instructor de l''expedient pot participar en les deliberacions de la Comissió Disciplinària, però no en les votacions dels expedients que hagi instruït.', true), ('D', 'L''instructor eleva la proposta de resolució a la Comissió Disciplinària i la notifica a l''intern indicant-li el dret a al·legar verbalment davant la Comissió.', false)) as v(label, body, ok)
)
