with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en quin termini màxim s''ha de dictar l''acord de la Comissió Disciplinària en el procediment disciplinari ordinari?', 'L''art. 246.2 RP fixa un termini màxim de tres mesos des de la iniciació. El termini d''un mes és el del procediment abreujat per a faltes lleus (art. 251.1 RP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 246.2 RP', 'El acuerdo deberá dictarse en el plazo máximo de tres meses desde la iniciación del procedimiento disciplinario.', null, 'bf5cb0f80b473c431b83be9c4c629054ffe8497759047d09e984e6e24a768ebf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bf5cb0f80b473c431b83be9c4c629054ffe8497759047d09e984e6e24a768ebf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos des de la iniciació del procediment disciplinari.', true), ('B', 'Un mes des de la iniciació del procediment disciplinari.', false), ('C', 'Sis mesos des de la notificació del plec de càrrecs.', false), ('D', 'Dos mesos des de la presentació del plec de descàrrecs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, com s''ha de notificar l''acord sancionador a l''intern en el procediment ordinari?', 'L''art. 248 RP obliga a notificar el mateix dia o l''endemà, amb lectura íntegra i còpia, indicant el recurs davant el jutge de vigilància, verbal en el mateix acte o escrit dins dels cinc dies hàbils.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 248 RP', 'La notificación del acuerdo sancionador deberá cursarse en el mismo día o al siguiente de ser adoptado, dando lectura íntegra de aquél y entregando copia al interno sancionado […] b) Indicación de que contra el mismo puede interponerse recurso ante el Juez de Vigilancia, verbalmente en el mismo acto de la notificación o por escrito dentro de los cinco días hábiles siguientes a la misma', null, 'efd391f7c767cc28e4f42f5be7072ab075243ebc2a767aa78a7e46129e09c36f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'efd391f7c767cc28e4f42f5be7072ab075243ebc2a767aa78a7e46129e09c36f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins dels deu dies següents a l''adopció, amb lliurament d''una còpia en què s''indiqui que s''hi pot interposar recurs d''alçada davant el centre directiu en el termini d''un mes.', false), ('B', 'El mateix dia o l''endemà d''adoptar-lo, amb lectura íntegra i lliurament d''una còpia en què s''indiqui que s''hi pot interposar recurs davant el jutge de vigilància, verbalment en el mateix acte o per escrit dins dels cinc dies hàbils següents.', true), ('C', 'El mateix dia d''adoptar-lo, només verbalment, i l''intern pot recórrer per escrit davant la Comissió Disciplinària dins dels tres dies hàbils següents.', false), ('D', 'Dins dels cinc dies hàbils següents a l''adopció, i l''intern pot interposar recurs davant el jutge de vigilància dins dels quinze dies hàbils següents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en el procediment abreujat per a faltes lleus:', 'L''art. 251.1 RP estableix que el part del funcionari opera com a plec de càrrecs, que hi ha deu dies per a al·legacions i proves, i que el director resol en el termini màxim d''un mes.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 251.1 RP', 'se tramitará el procedimiento abreviado, que deberá resolverse en el plazo máximo de un mes desde que se inició, con arreglo a las siguientes normas: a) El parte del funcionario, que operará como pliego de cargos, se comunicará al Jefe de Servicios y, simultáneamente, se notificará al presunto infractor.', null, '428c1e523cd925617fb4f226812c8ee7a233d9568d63e8f1b93ce3df15fae060', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '428c1e523cd925617fb4f226812c8ee7a233d9568d63e8f1b93ce3df15fae060')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''instructor formula un plec de càrrecs i el procediment s''ha de resoldre en el termini màxim de tres mesos.', false), ('B', 'La Comissió Disciplinària dicta la resolució en la primera sessió ordinària que faci.', false), ('C', 'El comunicat (part) del funcionari opera com a plec de càrrecs i el procediment s''ha de resoldre en el termini màxim d''un mes des que es va iniciar.', true), ('D', 'No hi ha tràmit d''al·legacions de l''intern, atesa la lleugeresa de la falta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, les sancions imposades es poden executar immediatament, sense esperar la resolució del recurs, quan la Comissió Disciplinària consideri que el compliment no es pot demorar i corresponguin als actes d''indisciplina greu tipificats:', 'L''art. 252.2 RP (en relació amb l''art. 44.3 LOGP i el primer paràgraf de l''art. 124 RP 1981) limita l''execució immediata als actes d''indisciplina greu de les lletres a) a f) de l''art. 108 RP 1981.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 252.2 RP', 'las sanciones impuestas serán inmediatamente ejecutadas, siempre que correspondan a los actos de indisciplina grave tipificados en las letras a), b), c), d), e) y f) del artículo 108 del Reglamento Penitenciario aprobado por Real Decreto 1201/1981, de 8 de mayo.', null, '1b75fc9df599ff21e705b99edeb041ba285e5d332af019ce1132570f1aec4cae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1b75fc9df599ff21e705b99edeb041ba285e5d332af019ce1132570f1aec4cae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A qualsevol de les lletres de l''article 108 del RP 1981.', false), ('B', 'A les lletres a), b), c), d), e) i f) de l''article 108 del RP 1981.', true), ('C', 'A les lletres a), b) i c) dels articles 108 i 109 del RP 1981.', false), ('D', 'A l''article 109 del RP 1981, quan hi hagi reiteració.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, durant el compliment de la sanció d''aïllament en cel·la, l''intern:', 'L''art. 254.5 RP reconeix dues hores diàries de passeig en solitari i prohibeix rebre paquets de l''exterior i adquirir productes de l''economat, llevat dels autoritzats pel director.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 254.5 RP', 'El recluso internado en celda disfrutará de dos horas diarias de paseo en solitario y, durante el cumplimiento de la sanción, no podrá recibir paquetes del exterior ni adquirir productos del Economato, salvo los autorizados expresamente por el Director.', null, '9f9360ab2da6f09e2ef64871c7bfc58634d57c92d3994a4a5bb3b5b70b3ee363', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9f9360ab2da6f09e2ef64871c7bfc58634d57c92d3994a4a5bb3b5b70b3ee363')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gaudeix de dues hores diàries de passeig en solitari i no pot rebre paquets de l''exterior ni adquirir productes de l''economat, llevat dels autoritzats expressament pel director.', true), ('B', 'Gaudeix de quatre hores diàries de passeig amb els altres interns sancionats.', false), ('C', 'No té dret a cap hora de passeig mentre duri la sanció.', false), ('D', 'Gaudeix d''una hora diària de passeig en solitari i pot rebre paquets de l''exterior amb l''autorització del cap de serveis.', false)) as v(label, body, ok)
)
