  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en l''exercici de la potestat disciplinària, l''aplicació analògica:', 'L''art. 232.3 RP prohibeix l''aplicació analògica, en coherència amb el principi de legalitat: els interns només poden ser corregits en els casos establerts i amb les sancions previstes (art. 42.1 LOGP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 232.3 RP', 'Queda prohibida la aplicación analógica.', null, '9a3bd0eb0cf210f5a7adcbaba5e21e84ee6e39877a96f84f3ae1f8aa81f33f88', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9a3bd0eb0cf210f5a7adcbaba5e21e84ee6e39877a96f84f3ae1f8aa81f33f88')
