)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, com a regla general, els acords sancionadors:', 'L''art. 252.1 RP estableix que l''acord sancionador no és executiu fins que es resol el recurs o venç el termini per interposar-lo; l''execució immediata és l''excepció per a actes d''indisciplina greu (art. 252.2 RP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 252.1 RP', 'Los acuerdos sancionadores no serán ejecutivos en tanto no haya sido resuelto el recurso interpuesto por el interno ante el Juez de Vigilancia o, en caso de que no se haya interpuesto, hasta que haya transcurrido el plazo para su impugnación.', null, '510dc2e55ba8dbc6d9ae9b848a4acae21c8e1da0b9d617cd5dbc0ca2e65da034', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '510dc2e55ba8dbc6d9ae9b848a4acae21c8e1da0b9d617cd5dbc0ca2e65da034')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No són executius mentre no s''hagi resolt el recurs interposat davant el jutge de vigilància o, si no se n''ha interposat cap, fins que hagi transcorregut el termini per impugnar-los.', true), ('B', 'Són executius immediatament des que es notifiquen.', false), ('C', 'Són executius quan els ratifica el centre directiu.', false), ('D', 'Són executius l''endemà de l''adopció, encara que s''hagi interposat recurs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
