  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en cas de malaltia de l''intern sancionat amb aïllament:', 'L''art. 254.2 RP (en relació amb l''art. 43.2 LOGP) preveu l''ajornament de l''efectivitat de la sanció d''aïllament fins a l''alta mèdica de l''intern.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 254.2 RP', 'En los casos de enfermedad del sancionado se aplazará la efectividad de la sanción de aislamiento hasta que el interno sea dado de alta.', null, 'c5b0712c98a2513f36b85c3c0cc0e40b98bd0db2c574cdff52c9aac871097b5f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c5b0712c98a2513f36b85c3c0cc0e40b98bd0db2c574cdff52c9aac871097b5f')
