)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, quin efecte té la cancel·lació de l''anotació de les sancions?', 'L''art. 262 RP diu que la cancel·lació de l''anotació comporta la de les faltes i situa l''intern com si no les hagués comès; per això, les sancions cancel·lades no compten per a la repetició (art. 235.2 RP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 262 RP', 'La cancelación de la anotación de las sanciones lleva aparejada la de las faltas por las que se impusieron y situará al interno, desde el punto de vista disciplinario, en igual situación que si no hubiere cometido aquéllas.', null, 'fac2dc7313bf86b7ecc4c8edf271f8c376a2a7e42544d5c53043268ddc68b6e3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fac2dc7313bf86b7ecc4c8edf271f8c376a2a7e42544d5c53043268ddc68b6e3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comporta la cancel·lació de les faltes per les quals es van imposar i situa l''intern, des del punt de vista disciplinari, en la mateixa situació que si no les hagués comès.', true), ('B', 'Només elimina la sanció, però la falta continua computant a l''efecte de repetició de la infracció.', false), ('C', 'Obliga a compensar l''intern pels dies d''aïllament complerts.', false), ('D', 'Només té efectes a partir que l''intern obté la llibertat definitiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
