with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la normativa penitenciària, en els casos de repetició de la infracció, les sancions:', 'L''art. 235.1 RP, que reprodueix l''art. 42.3 LOGP, permet incrementar les sancions en la meitat del seu màxim quan hi ha repetició de la infracció.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 235.1 RP i 42.3 LOGP', 'en los casos de repetición de la infracción, las sanciones podrán incrementarse en la mitad de su máximo.', null, '28940c6b6c1300d8106a454eedfa4732ab53d3ae434a3948f6270181fd51eebb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '28940c6b6c1300d8106a454eedfa4732ab53d3ae434a3948f6270181fd51eebb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden incrementar fins al doble del seu màxim.', false), ('B', 'Es poden incrementar en la meitat del seu màxim.', true), ('C', 'S''imposen sempre en el seu grau màxim.', false), ('D', 'Es poden incrementar en una tercera part del seu màxim.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 233 del Reglament penitenciari, quina de les sancions següents NO es pot imposar per la comissió d''una falta greu?', 'Per a les faltes greus, l''art. 233.2 RP preveu l''aïllament de dilluns a divendres fins a cinc dies (amb els requisits de violència) i, per a les altres, la privació de permisos (fins a dos mesos), la limitació de comunicacions orals o la privació de passeigs (de tres dies a un mes). L''aïllament de fins a set caps de setmana és sanció de les faltes molt greus (art. 233.1.b RP).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.2 RP', 'a) Sanción de aislamiento en celda de lunes a viernes por tiempo igual o inferior a cinco días, siempre que concurran los requisitos de la letra a) del apartado anterior. b) Las restantes faltas graves se sancionarán con privación de permisos de salida por tiempo igual o inferior a dos meses, limitación de las comunicaciones orales al mínimo tiempo previsto reglamentariamente durante un mes como máximo o privación de paseos y actos recreativos comunes desde tres días hasta un mes como máximo.', null, 'e88ae24059f0d2a1b9c2572935cc12edc142f1806f31300e8041933ac86ebf89', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e88ae24059f0d2a1b9c2572935cc12edc142f1806f31300e8041933ac86ebf89')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Aïllament en cel·la de dilluns a divendres per un temps igual o inferior a cinc dies, si concorren els requisits de violència o d''alteració greu de la convivència.', false), ('B', 'Privació de permisos de sortida per un temps igual o inferior a dos mesos.', false), ('C', 'Aïllament de fins a set caps de setmana.', true), ('D', 'Privació de passeigs i actes recreatius comuns des de tres dies fins a un mes com a màxim.', false)) as v(label, body, ok)
)
