with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, quan les sancions per dues o més faltes jutjades en un mateix expedient no es poden complir simultàniament, el màxim de compliment:', 'L''art. 236.2 RP (i l''art. 42.5 LOGP) fixa el límit del triple de la sanció més greu i de quaranta-dos dies consecutius d''aïllament quan les sancions es compleixen successivament per ordre de gravetat.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 236.2 RP', 'el máximo de cumplimiento no podrá exceder nunca del triplo del tiempo correspondiente a la sanción más grave, ni de cuarenta y dos días consecutivos en caso de aislamiento en celda.', null, '715017955c6244239b1635bbbcc27b0a9c5bba161803e71a1f1b328df97165f8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '715017955c6244239b1635bbbcc27b0a9c5bba161803e71a1f1b328df97165f8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No pot excedir del doble del temps de la sanció més greu, ni de vint-i-vuit dies consecutius d''aïllament.', false), ('B', 'És la suma aritmètica de totes les sancions, sense cap límit.', false), ('C', 'No pot excedir mai del triple del temps corresponent a la sanció més greu, ni de quaranta-dos dies consecutius en cas d''aïllament en cel·la.', true), ('D', 'No pot excedir del triple de la sanció més greu, ni de catorze dies consecutius d''aïllament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en la infracció continuada (pluralitat d''accions o omissions que infringeixen el mateix precepte o un de semblant, en execució d''un pla preconcebut o aprofitant una ocasió idèntica):', 'L''art. 237.2 RP disposa que en la infracció continuada s''imposa la sanció de la infracció més greu en el seu límit màxim.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 237 RP', 'En estos casos, se impondrá la sanción correspondiente a la infracción más grave en su límite máximo.', null, '9951c94df6a830627eaefb09e6dbb6db3eee923d59c2d26e3645ff0496e2dc63', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9951c94df6a830627eaefb09e6dbb6db3eee923d59c2d26e3645ff0496e2dc63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposa la sanció corresponent a la infracció més greu en el seu límit màxim.', true), ('B', 'S''imposen totes les sancions per complir-les simultàniament.', false), ('C', 'S''imposa la sanció de la infracció més greu en el seu límit mínim.', false), ('D', 'Se sanciona com una sola falta lleu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quina de les formes següents NO és una de les maneres en què es pot acordar la iniciació del procediment sancionador?', 'L''art. 241 RP atribueix sempre al/a la director/a la iniciació, d''ofici i motivadament: per iniciativa pròpia, per petició raonada d''un altre òrgan, per denúncia escrita d''una persona identificada o per ordre d''un òrgan superior jeràrquic. La Comissió Disciplinària resol, però no incoa.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 241.1 i 241.2 RP', 'a) Por propia iniciativa, cuando tenga conocimiento de la existencia de conductas o hechos susceptibles de constituir infracción disciplinaria a través de parte de funcionario informado por el Jefe de Servicios o por cualquier otro medio. b) Por petición razonada realizada por otro órgano administrativo que no sea superior jerárquico. […] El Director también acordará de oficio la iniciación del procedimiento como consecuencia de orden emitida por un órgano administrativo superior jerárquico.', null, 'e611f2b3e7e0b7e94625741614175b0b05eff3fb7e8fa0003a03e9100e4ebee3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e611f2b3e7e0b7e94625741614175b0b05eff3fb7e8fa0003a03e9100e4ebee3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per acord de la Comissió Disciplinària, que incoa directament l''expedient sense intervenció del/de la director/a.', true), ('B', 'Per iniciativa pròpia del/de la director/a, quan conegui els fets per un comunicat (part) d''un funcionari informat pel cap de serveis o per qualsevol altre mitjà.', false), ('C', 'Per petició raonada d''un altre òrgan administratiu que no sigui superior jeràrquic.', false), ('D', 'Per ordre d''un òrgan administratiu superior jeràrquic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb les mesures cautelars en el procediment disciplinari regulades al Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'L''art. 243 RP no exigeix autorització judicial prèvia: les acorda el/la director/a i se''n dona coneixement al jutge de vigilància (243.2). Les altres afirmacions reprodueixen els apartats 1, 2 i 4.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 243 RP', 'El Director, en el ámbito de las facultades que le atribuye este Reglamento, por sí o a propuesta del Instructor del expediente disciplinario, podrá acordar en cualquier momento del procedimiento, mediante acuerdo motivado, las medidas cautelares […] su adopción será notificada al interno y puesta en conocimiento del Juez de Vigilancia Penitenciaria. […] Cuando la sanción que recayese, en su caso, coincida en naturaleza con la medida cautelar impuesta, ésta se abonará para el cumplimiento de la sanción.', null, '27debaabf33d254b2c3f03192cb6bf94ac36e64ee377ca02cac4c57d38a886a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '27debaabf33d254b2c3f03192cb6bf94ac36e64ee377ca02cac4c57d38a886a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les pot acordar el/la director/a, per si mateix o a proposta de l''instructor, en qualsevol moment del procediment, mitjançant un acord motivat.', false), ('B', 'La seva adopció s''ha de notificar a l''intern i posar en coneixement del jutge de vigilància penitenciària.', false), ('C', 'Si la sanció que s''imposa coincideix en naturalesa amb la mesura cautelar, aquesta s''abona per al compliment de la sanció.', false), ('D', 'Requereixen l''autorització prèvia del jutge de vigilància penitenciària.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en el procediment abreujat, de quin termini disposen el cap de serveis i l''intern expedientat per aportar al·legacions, documents o informacions i, si escau, proposar i practicar proves?', 'L''art. 251.1.b RP dona deu dies, des de la comunicació i notificació del comunicat que opera com a plec de càrrecs, perquè el cap de serveis i l''intern facin aportacions; després, el/la director/a resol.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 251.1.b RP', 'En el plazo de diez días, a partir de la comunicación y notificación del pliego de cargos, el Jefe de Servicios y el interno expedientado efectuarán, respectivamente, la aportación de cuantas alegaciones, documentos o informaciones estimen convenientes', null, 'c8e5e51c767bb077427dfccb0ada1ef1e861367bfe38cf323cc541311b053625', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c8e5e51c767bb077427dfccb0ada1ef1e861367bfe38cf323cc541311b053625')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres dies hàbils des de la notificació.', false), ('B', 'Cinc dies hàbils des de la notificació.', false), ('C', 'Deu dies des de la comunicació i la notificació del plec de càrrecs.', true), ('D', 'Un mes des de l''inici del procediment.', false)) as v(label, body, ok)
)
