with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, si en un procediment abreujat el cap de serveis aprecia que els fets poden ser constitutius d''una infracció molt greu o greu:', 'L''art. 251.2 RP preveu que el cap de serveis acordi continuar pel procediment general (arts. 242 a 245 RP); l''acord es notifica perquè en cinc dies hàbils s''hi puguin fer al·legacions (251.3).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 251.2 RP', 'Cuando el Jefe de Servicios aprecie que los hechos pueden ser constitutivos de infracción muy grave o grave, acordará que el expediente continúe tramitándose por el procedimiento general', null, '0b19a5e7206e3a5cdc165203aeddd71fd5f69bde8f06802d11318e5a37c5a49d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0b19a5e7206e3a5cdc165203aeddd71fd5f69bde8f06802d11318e5a37c5a49d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha d''arxivar l''expedient i comunicar-ho al jutge de vigilància.', false), ('B', 'Acorda que l''expedient continuï tramitant-se pel procediment general.', true), ('C', 'Imposa directament la sanció corresponent.', false), ('D', 'Eleva l''expedient al centre directiu perquè el resolgui.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, la Comissió Disciplinària pot revocar o reduir una sanció en la imposició de la qual ha intervingut el jutge de vigilància, directament o en via de recurs?', 'L''art. 256.3 RP condiciona la revocació o reducció a l''autorització del jutge de vigilància quan aquest ha intervingut en la imposició de la sanció.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 256.3 RP', 'La revocación o reducción de sanciones no podrá efectuarse sin autorización del Juez de Vigilancia cuando éste haya intervenido en su imposición, directamente o en vía de recurso.', null, '92baf38bdd63eae208cf78d4f0605425b287ac356f01fa42ad239e56f1792bb4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '92baf38bdd63eae208cf78d4f0605425b287ac356f01fa42ad239e56f1792bb4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
