)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, la informació prèvia al procediment disciplinari s''ha d''acordar sempre que:', 'L''art. 241.3 RP fa preceptiva la informació prèvia quan un intern denuncia fets sancionables, tret que la denúncia no tingui manifestament fonament. La practica un funcionari designat pel/per la director/a.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 241.3 RP', 'Dicha información previa se acordará siempre que un interno formule denuncia de hechos susceptibles de sanción disciplinaria, salvo cuando ésta carezca manifiestamente de fundamento.', null, '638cb688166e8bff790e8269d4a9b8f217f0080e3f75d98aea59809c6e3151e5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '638cb688166e8bff790e8269d4a9b8f217f0080e3f75d98aea59809c6e3151e5')
  returning id
