  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quan en el compliment successiu de sancions d''aïllament en cel·la aquestes superen, en conjunt, els catorze dies:', 'L''art. 236.3 RP, d''acord amb l''art. 76.2.d LOGP, exigeix que el jutge de vigilància aprovi totes les sancions d''aïllament de compliment successiu que, en conjunt, superin els catorze dies.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 236.3 RP', 'Cuando en los supuestos de cumplimiento sucesivo de sanciones de aislamiento en celda, éstas superen, en su conjunto, los catorce días de aislamiento, deberán ser aprobadas todas ellas por el Juez de Vigilancia Penitenciaria', null, 'af23771ea586eeb56840e4ae9fa72fb89960f914a7ad1e8a5834608a45173a75', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'af23771ea586eeb56840e4ae9fa72fb89960f914a7ad1e8a5834608a45173a75')
  returning id
