with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, si la Comissió Disciplinària constata que s''ha qualificat erròniament la conducta i que això implicaria imposar una sanció per una falta més greu que la imputada en el plec de càrrecs:', 'L''art. 247.d RP impedeix sancionar per fets diferents dels del plec de càrrecs i, si la nova qualificació és més greu, obliga a formular un nou plec i a concedir el tràmit d''audiència de l''art. 244.4 RP.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 247.d RP', 'Si la Comisión Disciplinaria constatare que se ha calificado erróneamente la conducta del presunto infractor y ello implicase la imposición de una sanción por falta más grave que la que se le hubiese imputado en el pliego de cargos, ordenará al Instructor la formulación de un nuevo pliego de cargos con la calificación determinada por la Comisión Disciplinaria, concediéndose al interno el trámite previsto en el artículo 244.4.', null, '29aeb84eec22f57e894c16a0dbcbdc2d71d53c16508105c197a37baaa796fc0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29aeb84eec22f57e894c16a0dbcbdc2d71d53c16508105c197a37baaa796fc0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ordena a l''instructor que formuli un nou plec de càrrecs amb la qualificació que determini la Comissió, i es concedeix a l''intern el tràmit d''audiència.', true), ('B', 'Pot imposar directament la sanció per la falta més greu, perquè els fets són els mateixos.', false), ('C', 'Ha d''imposar la sanció per la falta qualificada en el plec de càrrecs, sense cap modificació.', false), ('D', 'Ha d''arxivar l''expedient per caducitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
