  select 'Segons el Reglament penitenciari, la prescripció de les faltes s''interromp quan s''inicia el procediment sancionador amb coneixement de l''interessat, però el còmput es reprèn si l''expedient està paralitzat per una causa no imputable al presumpte infractor durant més de:', 'L''art. 258.2 RP preveu la represa del còmput de la prescripció si l''expedient queda paralitzat més d''un mes per causa no imputable al presumpte infractor.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 258.2 RP', 'reanudándose el cómputo de los plazos de prescripción si el expediente disciplinario estuviera paralizado durante más de un mes por causa no imputable al presunto infractor.', null, '4e483b6024144df96d2af10846af14fad0f92420eb731f8e2d8dafffedb8a190', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e483b6024144df96d2af10846af14fad0f92420eb731f8e2d8dafffedb8a190')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies.', false), ('B', 'Tres mesos.', false), ('C', 'Un mes.', true), ('D', 'Sis mesos.', false)) as v(label, body, ok)
)
