with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, en quin termini prescriuen les sancions imposades per faltes lleus?', 'L''art. 258.3 RP fixa que les sancions per faltes molt greus i greus prescriuen en els mateixos terminis que les faltes (tres i dos anys) i les imposades per faltes lleus, en un any. Els sis mesos són el termini de prescripció de la falta lleu, no de la sanció.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 258.3 RP', 'las impuestas por faltas leves en el plazo de un año', null, 'c658f5d68d32084d266e6b2e8a8c9208e5d4a4021aee8bcb0e219beba381cea8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c658f5d68d32084d266e6b2e8a8c9208e5d4a4021aee8bcb0e219beba381cea8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos.', false), ('B', 'Un any.', true), ('C', 'Tres mesos.', false), ('D', 'Dos anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, un cop vençut el termini per dictar la resolució en el procediment disciplinari, aquest s''entén caducat i s''arxiven les actuacions si la resolució no s''adopta dins dels:', 'L''art. 246.2 RP preveu la caducitat si, vençut el termini per resoldre (tres mesos en l''ordinari, un mes en l''abreujat), la resolució no s''adopta en els trenta dies següents per causa no imputable a l''interessat; també caduca si l''intern és excarcerat.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 246.2 RP', 'ésta no se adoptase en el plazo de los treinta días siguientes, siempre que la demora no fuera imputable al interesado', null, '047262945d92c07fedb96e1edd31d197e8a6fecbe100b11cf069edc8238c2752', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '047262945d92c07fedb96e1edd31d197e8a6fecbe100b11cf069edc8238c2752')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies següents, en tot cas.', false), ('B', 'Tres mesos següents, sempre que l''intern ho sol·liciti.', false), ('C', 'Trenta dies següents, sempre que la demora no sigui imputable a l''interessat.', true), ('D', 'Quinze dies hàbils següents, sempre que la demora no sigui imputable a l''interessat.', false)) as v(label, body, ok)
)
