with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari de 1981 (RP 1981), quina de les conductes següents NO està tipificada com a falta molt greu?', 'L''evasió (108.e), l''agressió o coacció greu a altres interns (108.c) i la participació en motins (108.a) són faltes molt greus. La desobediència o la resistència passiva a les ordres és falta greu (art. 109.b RP 1981).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 108 RP 1981', 'Son faltas muy graves: a) Participar en motines, plantes o desórdenes colectivos, o instigar a los mismos si éstos se hubieran producido. […] c) Agredir o hacer objeto de coacción grave a otros internos. […] e) Intentar, facilitar o consumar la evasión.', null, '452945fe282216ca8f057b2f691bae2907ee13df16fac06c4e9b665531c714f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '452945fe282216ca8f057b2f691bae2907ee13df16fac06c4e9b665531c714f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Intentar, facilitar o consumar l''evasió.', false), ('B', 'Agredir o fer objecte de coacció greu altres interns.', false), ('C', 'Desobeir les ordres rebudes d''autoritats o funcionaris en l''exercici legítim de les seves atribucions o resistir-s''hi passivament.', true), ('D', 'Participar en motins, plantades o desordres col·lectius, o instigar-hi si s''han produït.', false)) as v(label, body, ok)
)
