with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el RP 1981, l''ús de drogues tòxiques, substàncies psicotròpiques o estupefaents, llevat de prescripció facultativa, constitueix:', 'L''art. 109.i del RP 1981 tipifica com a falta greu l''embriaguesa per abús de begudes alcohòliques que causi una pertorbació greu (o per begudes clandestines) i l''ús de drogues tòxiques, psicotròpics o estupefaents sense prescripció facultativa.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 109.i RP 1981', 'así como el uso de drogas tóxicas, sustancias psicotrópicas o estupefacientes, salvo prescripción facultativa.', null, 'cdcc436b76acae68e76f9433ec510d4737ee5817a9ac60b9dd56b79de685f87f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cdcc436b76acae68e76f9433ec510d4737ee5817a9ac60b9dd56b79de685f87f')
