with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 110 del RP 1981, quina de les conductes següents NO és una falta lleu?', 'Les tres darreres conductes són faltes lleus (art. 110.a, d i e del RP 1981). Organitzar jocs de sort, envit o atzar no permesos o participar-hi és falta greu (art. 109.g del RP 1981).', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 110 RP 1981', 'a) Faltar levemente a la consideración debida a las autoridades, funcionarios […] d) Hacer uso abusivo y perjudicial de objetos no prohibidos por las normas de régimen interior. e) Causar daños graves en las dependencias, materiales o efectos del establecimiento o en las pertenencias de otras personas por falta de diligencia o cuidado.', null, 'c470bbb0856d62241a87621c620ffc77b2f39c9574ac2fa1d0234fc881ff5e82', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c470bbb0856d62241a87621c620ffc77b2f39c9574ac2fa1d0234fc881ff5e82')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Faltar lleument a la consideració deguda a les autoritats i als funcionaris.', false), ('B', 'Fer un ús abusiu i perjudicial d''objectes no prohibits per les normes de règim interior.', false), ('C', 'Causar danys greus a les dependències o als materials de l''establiment per falta de diligència o cura.', false), ('D', 'Organitzar jocs de sort, envit o atzar no permesos a l''establiment o participar-hi.', true)) as v(label, body, ok)
)
