  select 'Segons el RP 1981, la sanció d''aïllament de caps de setmana es compleix:', 'L''art. 111.b del RP 1981 regula l''aïllament de fins a set caps de setmana, des de les 16 h del dissabte fins a les 8 h del dilluns següent.', 'pcat_e17_regim_disciplinari', (select id from public.topics where slug = 'pcat-e17-regim-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 111.b RP 1981', 'b) Aislamiento de hasta siete fines de semana, desde las dieciséis horas de sábado hasta las ocho del lunes siguiente.', null, 'c4de5a9503b1ac93ff9f8b0e3ee0bfc2d1952f3d861ba838f414c26d00dd9efd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c4de5a9503b1ac93ff9f8b0e3ee0bfc2d1952f3d861ba838f414c26d00dd9efd')
