  select 'D''acord amb el Decret 329/2006, en quins àmbits d''actuació s''organitza substancialment el personal que presta serveis als centres penitenciaris?', 'L''art. 52 del Decret 329/2006 organitza el personal dels centres en tres àmbits d''actuació: l''administratiu, el de rehabilitació i el de règim interior.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 52 D329', 'el personal que presti serveis als centres penitenciaris s''organitzarà substancialment en els següents àmbits d''actuació: l''administratiu, el de rehabilitació i el de règim interior.', null, 'eabeb1c1f7ff18fd2a3dd943f78928de78de0babdf23dbe5ac2cef8d55944d8d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eabeb1c1f7ff18fd2a3dd943f78928de78de0babdf23dbe5ac2cef8d55944d8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''administratiu, el sanitari i el de seguretat exterior.', false), ('B', 'El de direcció, el de tractament i el de gestió econòmica.', false), ('C', 'El de règim interior, el de règim obert i el de medi obert.', false), ('D', 'L''administratiu, el de rehabilitació i el de règim interior.', true)) as v(label, body, ok)
)
