  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, el manual d''organització del centre penitenciari l''elabora el Consell de Direcció i l''aprova:', 'L''art. 44.1 del Decret 329/2006 disposa que el manual d''organització i les seves modificacions els aprova el centre directiu per resolució expressa amb rang d''instrucció; el director només el pot modificar provisionalment (44.3).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 44.1 D329', 'Aquest manual d''organització i les seves modificacions posteriors hauran de ser aprovats pel centre directiu mitjançant resolució expressa, que tindrà rang d''instrucció.', null, 'b34c5fca25ca87f9c17f4f5ba93706b63c9b9cded0613482c09e843183bd4066', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b34c5fca25ca87f9c17f4f5ba93706b63c9b9cded0613482c09e843183bd4066')
