with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 329/2006, quan es rep una notificació de fets o circumstàncies que afecten la situació penal, processal o penitenciària d''un intern, el/la cap de gestió penitenciària ho ha de comunicar:', 'L''art. 55.2.e del Decret 329/2006 obliga el/la cap de gestió penitenciària a comunicar al/a la subdirector/a de Tractament els interns afectats per notificacions o fets que incideixin en la seva situació penal, processal o penitenciària.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 55.2.e D329', 'e) Comunicar al/a la subdirector/a de Tractament el nom dels/de les interns/es en relació amb els quals es rebi notificació o es tingui coneixement de fets o circumstàncies que afectin la seva situació penal, processal i/o penitenciària', null, '8eb8af9e5579fe3d35e51e0763616af63e43bb0adf1b6a40ca60752bbfec2594', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8eb8af9e5579fe3d35e51e0763616af63e43bb0adf1b6a40ca60752bbfec2594')
  returning id
), o as (
