  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al/A la cap de la unitat de gestió econòmica.', false), ('B', 'Al/A la cap de serveis.', false), ('C', 'Al/A la subdirector/a de Tractament.', true), ('D', 'Directament al jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quina de les funcions següents NO correspon al/a la cap de gestió penitenciària?', 'Les estadístiques (55.2.g), l''àrea d''identificació i ingressos (55.2.i) i els escrits a autoritats (55.2.f) són funcions del/de la cap de gestió penitenciària. Promoure la formació del personal correspon al/a la cap de recursos humans (art. 56.2.f).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Arts. 55.2 i 56.2.f D329', 'f) Preparar i supervisar les comunicacions i els escrits adreçats a autoritats, administratives o judicials […] g) Establir els circuits, recopilar i trametre les estadístiques relatives a la població reclusa que estableixi el centre directiu quant a la gestió penitenciària. […] i) Controlar i supervisar la gestió dels processos administratius de l''àrea d''identificació i ingressos del centre penitenciari […] f) Promoure i coordinar les activitats formatives del personal de l''establiment', null, '7c617354815ed6df1fb05eda17090df3f5f1a13e00e49ddbf7977f4edcd54d0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c617354815ed6df1fb05eda17090df3f5f1a13e00e49ddbf7977f4edcd54d0e')
  returning id
