  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Promoure i coordinar les activitats formatives del personal de l''establiment.', true), ('B', 'Establir els circuits, recopilar i trametre les estadístiques relatives a la població reclusa que estableixi el centre directiu.', false), ('C', 'Controlar i supervisar la gestió dels processos administratius de l''àrea d''identificació i ingressos.', false), ('D', 'Preparar i supervisar les comunicacions i els escrits adreçats a autoritats administratives o judicials que sol·licitin informació sobre els interns.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
