with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb el manual d''organització del centre penitenciari regulat al Decret 329/2006, quina de les afirmacions següents NO és correcta?', 'L''art. 44.3 del Decret 329/2006 exigeix revisar el manual anualment i permet que el/la director/a el modifiqui provisionalment. Les altres afirmacions recullen els apartats 2 i 3.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 44.2 i 44.3 D329', 'El manual d''organització haurà d''establir les funcions concretes i específiques, les tasques i les responsabilitats bàsiques inherents al sistema prestacional propi de cada unitat de servei. […] El manual d''organització, que haurà de tenir publicitat suficient entre la plantilla del centre penitenciari, haurà de ser revisat anualment i podrà ser modificat provisionalment pel/per la director/a del centre quan les necessitats del servei ho exigeixin.', null, '870ba918daba59e5143d5397c07a1c58d401a12c830823af7ce98a1696756e08', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '870ba918daba59e5143d5397c07a1c58d401a12c830823af7ce98a1696756e08')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de revisar cada tres anys i només el pot modificar el centre directiu.', true), ('B', 'Ha d''establir les funcions concretes i específiques, les tasques i les responsabilitats bàsiques de cada unitat de servei.', false), ('C', 'Ha de tenir publicitat suficient entre la plantilla del centre.', false), ('D', 'El/La director/a del centre el pot modificar provisionalment quan les necessitats del servei ho exigeixin.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 329/2006, quina de les dades següents NO s''ha de recollir en el llibre de serveis del centre penitenciari?', 'L''art. 45.1 del Decret 329/2006 diu que el llibre de serveis recull tots els serveis, els funcionaris assignats amb el número d''identificació, el servei i l''horari, i les modificacions del dia. No inclou cap avaluació de l''acompliment.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 45.1 D329', 'amb l''expressió del número d''identificació del/de la funcionari/ària, el servei que li correspongui i l''horari; s''hi anotaran totes les modificacions que s''esdevinguin en el transcurs del dia en relació amb la reassignació dels serveis.', null, '03e5a2c57079bf9d7f085d8fd39fcc431d4f1e8d4633f8b51b9ee5a64a1902fa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03e5a2c57079bf9d7f085d8fd39fcc431d4f1e8d4633f8b51b9ee5a64a1902fa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El número d''identificació del funcionari al qual s''assigna cada servei.', false), ('B', 'La valoració de l''acompliment professional de cada funcionari.', true), ('C', 'El servei que correspon a cada funcionari i l''horari.', false), ('D', 'Les modificacions que es produeixin durant el dia en la reassignació dels serveis.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
