with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 1/1979, general penitenciària (LOGP), un cop admès un intern en l''establiment, s''ha d''obrir:', 'L''art. 15 bis.1 LOGP preveu la ressenya alfabètica, dactilar i fotogràfica, la inscripció al llibre d''ingressos i l''obertura d''un expedient personal relatiu a la situació processal i penitenciària, amb dret d''accés de l''intern.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 15 bis.1 LOGP', 'así como a la inscripción en el libro de ingresos y a la apertura de un expediente personal relativo a su situación procesal y penitenciaria, respecto del que se reconoce el derecho de acceso.', null, 'cb102f57e04d8a917037c1c43e6017e920e1d33f02a36c90ebc43d5bd1864f50', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cb102f57e04d8a917037c1c43e6017e920e1d33f02a36c90ebc43d5bd1864f50')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un expedient personal relatiu a la seva situació processal i penitenciària, respecte del qual es reconeix el dret d''accés.', true), ('B', 'Un expedient disciplinari preventiu, que només pot consultar la Comissió Disciplinària.', false), ('C', 'Un protocol de tractament, al qual l''intern no té dret d''accés.', false), ('D', 'Una fitxa de seguretat, que s''ha de remetre al jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LOGP, el dret d''accés de l''intern al seu expedient personal:', 'L''art. 15 bis.1 LOGP reconeix el dret d''accés a l''expedient personal i només admet limitar-lo de forma individualitzada i fonamentada en raons concretes de seguretat o tractament.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 15 bis.1 LOGP', 'Este derecho sólo se verá limitado de forma individualizada y fundamentada en concretas razones de seguridad o tratamiento.', null, '40663ac579ace34d9d8d8744d547af8c2033fe43629a9650c0820064c76a4f68', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '40663ac579ace34d9d8d8744d547af8c2033fe43629a9650c0820064c76a4f68')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es pot limitar en cap cas.', false), ('B', 'Només es pot exercir amb l''autorització prèvia del jutge de vigilància penitenciària.', false), ('C', 'Només es pot limitar de manera individualitzada i fonamentada en raons concretes de seguretat o de tractament.', true), ('D', 'Es pot limitar amb caràcter general per a tots els interns classificats en primer grau.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 bis de la LOGP, el tractament de les dades personals dels interns es regeix:', 'L''art. 15 bis.2 LOGP (afegit per la LO 7/2021) remet a la llei orgànica de protecció de dades per a finalitats penals (LO 7/2021); les dades de categories especials no previstes es poden tractar amb el consentiment de l''interessat.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 15 bis.2 LOGP', 'El tratamiento de los datos personales de los internos se regirá por lo previsto en la Ley Orgánica de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales.', 'El banc ja té una pregunta sobre l''art. 2.3 LOPDGDD (tractaments penitenciaris regits per la legislació específica i supletòriament pel RGPD i la LOPDGDD). Convé revisar que les dues preguntes no es contradiguin per a l''alumne: la remissió de l''art. 15 bis.2 LOGP a la LO 7/2021 és posterior i més específica.', 'e1b2433d9e0ed73234b02bc7695b896be3d6c14bf99a6bbd20c2c31e217b9896', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e1b2433d9e0ed73234b02bc7695b896be3d6c14bf99a6bbd20c2c31e217b9896')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Pel que preveu la llei orgànica de protecció de dades personals tractades per a finalitats de prevenció, detecció, investigació i enjudiciament d''infraccions penals i d''execució de sancions penals.', true), ('B', 'Exclusivament pel Reglament (UE) 2016/679, general de protecció de dades.', false), ('C', 'Per la Llei 19/2014, de transparència, accés a la informació pública i bon govern.', false), ('D', 'Únicament pel Reglament penitenciari, sense remissió a cap altra norma.', false)) as v(label, body, ok)
)
