with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 39/2015, del procediment administratiu comú, els actes administratius es produeixen:', 'L''art. 36.1 de la Llei 39/2015 estableix la forma escrita i electrònica com a regla general dels actes administratius.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 36.1 Llei 39/2015', 'Los actos administrativos se producirán por escrito a través de medios electrónicos, a menos que su naturaleza exija otra forma más adecuada de expresión y constancia.', null, 'bf7bc1387fa6514a83b084b2c92772b3fef8eac78358339321ab91d931b92efa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bf7bc1387fa6514a83b084b2c92772b3fef8eac78358339321ab91d931b92efa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Verbalment, i només es documenten per escrit si l''interessat ho sol·licita.', false), ('B', 'Per escrit en paper, signats a mà per l''òrgan competent.', false), ('C', 'En la forma que esculli lliurement l''òrgan que els dicta.', false), ('D', 'Per escrit a través de mitjans electrònics, llevat que la seva naturalesa exigeixi una altra forma més adequada d''expressió i constància.', true)) as v(label, body, ok)
)
