with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 35 de la Llei 39/2015, quin dels actes següents s''ha de motivar, amb una referència succinta de fets i fonaments de dret?', 'L''art. 35.1.f de la Llei 39/2015 inclou entre els actes que s''han de motivar els que rebutgen proves proposades pels interessats. Els altres supòsits no figuren a la llista de l''art. 35.1.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 35.1.f Llei 39/2015', 'f) Los actos que rechacen pruebas propuestas por los interesados.', null, '8c0f4aaa83d8412ea92f273bb387ac788555030b86e8d9bfeaf83100ae70f7bd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8c0f4aaa83d8412ea92f273bb387ac788555030b86e8d9bfeaf83100ae70f7bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els actes de mer tràmit que no decideixen el fons de l''assumpte.', false), ('B', 'Les comunicacions internes entre òrgans d''una mateixa unitat.', false), ('C', 'Els actes que estimin totalment la sol·licitud de l''interessat.', false), ('D', 'Els actes que rebutgin proves proposades pels interessats.', true)) as v(label, body, ok)
)
