with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 39/2015, quin dels requisits següents NO s''exigeix perquè els documents electrònics administratius siguin vàlids?', 'L''art. 26.2 de la Llei 39/2015 exigeix, entre altres requisits, dades d''identificació, referència temporal, metadades mínimes i les signatures electròniques que corresponguin. No exigeix cap requisit de doble llengua.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 26.2 Llei 39/2015', 'b) Disponer de los datos de identificación que permitan su individualización, sin perjuicio de su posible incorporación a un expediente electrónico. c) Incorporar una referencia temporal del momento en que han sido emitidos. d) Incorporar los metadatos mínimos exigidos.', null, 'a2330dd8bf2fa8f8b198197e9c8f83b63d7a7856715d97de8e9cb80a192f602a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2330dd8bf2fa8f8b198197e9c8f83b63d7a7856715d97de8e9cb80a192f602a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Incorporar una referència temporal del moment en què s''han emès.', false), ('B', 'Incorporar les metadades mínimes exigides.', false), ('C', 'Estar redactats en dues llengües oficials.', true), ('D', 'Disposar de les dades d''identificació que en permetin la individualització.', false)) as v(label, body, ok)
)
