with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 39/2015, com s''han d''anotar els assentaments en el registre electrònic?', 'L''art. 16.2 de la Llei 39/2015 imposa l''ordre temporal de recepció o sortida i la data de l''assentament; acabat el registre, els documents s''han de cursar sense dilació als destinataris.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 16.2 Llei 39/2015', 'Los asientos se anotarán respetando el orden temporal de recepción o salida de los documentos, e indicarán la fecha del día en que se produzcan.', null, 'd0d601be26e420478da5b0ec72776b2839c3187eb39dd9b8007390962bbb29dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd0d601be26e420478da5b0ec72776b2839c3187eb39dd9b8007390962bbb29dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
