with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, l''òrgan superior jeràrquic pot emetre instruccions i circulars o ordres de servei per fixar, respectivament:', 'L''art. 7.1 de la Llei 26/2010 distingeix: les instruccions fixen criteris per aplicar les normes jurídiques i les circulars o ordres de servei regulen el funcionament dels serveis. No són disposicions reglamentàries (art. 60.2).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.1 Llei 26/2010', 'que puede emitir instrucciones y circulares u órdenes de servicios para fijar, respectivamente, los criterios para la aplicación de las normas jurídicas en el ejercicio de sus funciones y para el funcionamiento de los servicios.', null, '2aad55aeb7977075fc3b6f3af96ab58e901e3d7205c8113abd8bff9362370b65', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2aad55aeb7977075fc3b6f3af96ab58e901e3d7205c8113abd8bff9362370b65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El funcionament dels serveis i els criteris per a l''aplicació de les normes jurídiques.', false), ('B', 'Normes que innoven l''ordenament jurídic i el règim disciplinari del personal.', false), ('C', 'Els criteris per a l''aplicació de les normes jurídiques en l''exercici de les funcions i el funcionament dels serveis.', true), ('D', 'La delegació de competències i l''avocació d''assumptes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, l''incompliment de les instruccions o de les ordres de servei:', 'L''art. 7.3 de la Llei 26/2010 (com l''art. 6.2 de la Llei 40/2015) diu que l''incompliment d''instruccions o ordres de servei no afecta per si sol la validesa dels actes, però pot generar responsabilitat disciplinària.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.3 Llei 26/2010', 'El incumplimiento de las instrucciones o de las órdenes de servicio no afecta por sí solo a la validez de los actos dictados por los órganos administrativos, sin perjuicio de la responsabilidad disciplinaria en que se pueda incurrir.', null, '7c6e16888bd2053c97192423b5f6510d5441fe5fa64a480d003cd20375a7a887', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c6e16888bd2053c97192423b5f6510d5441fe5fa64a480d003cd20375a7a887')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Determina la nul·litat de ple dret dels actes dictats.', false), ('B', 'Determina l''anul·labilitat dels actes dictats.', false), ('C', 'No afecta per si sol la validesa dels actes dictats pels òrgans administratius, sens perjudici de la responsabilitat disciplinària en què es pugui incórrer.', true), ('D', 'No pot generar cap mena de responsabilitat disciplinària.', false)) as v(label, body, ok)
)
