  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, quan una disposició específica ho estableix o es considera convenient per raó dels destinataris o dels efectes que es poden produir, les instruccions i les ordres de servei s''han de publicar:', 'L''art. 7.2 de la Llei 26/2010 exigeix, en aquests casos, la publicació a la seu electrònica i al diari o butlletí oficial que correspongui.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.2 Llei 26/2010', 'las instrucciones y las órdenes de servicio deben publicarse en la sede electrónica y en el correspondiente diario o boletín oficial.', null, '8b92139f03089fe1e30783723a3785c7f08a7a60d7922c8c56e0b2b3ca38e5bd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8b92139f03089fe1e30783723a3785c7f08a7a60d7922c8c56e0b2b3ca38e5bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la seu electrònica i al diari o butlletí oficial corresponent.', true), ('B', 'Només al tauler d''anuncis de l''òrgan que les dicta.', false), ('C', 'Únicament al Butlletí Oficial de l''Estat.', false), ('D', 'A la intranet de l''organisme, sense publicitat externa.', false)) as v(label, body, ok)
)
