with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 40/2015, de règim jurídic del sector públic, mitjançant quins instruments poden els òrgans administratius dirigir les activitats dels seus òrgans jeràrquicament dependents?', 'L''art. 6.1 de la Llei 40/2015 permet dirigir les activitats dels òrgans jeràrquicament dependents mitjançant instruccions i ordres de servei, que es publiquen al butlletí oficial quan ho estableixi una disposició o es consideri convenient.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 6.1 Llei 40/2015', 'Los órganos administrativos podrán dirigir las actividades de sus órganos jerárquicamente dependientes mediante instrucciones y órdenes de servicio.', null, 'db3d53d19e6f3fdd1645773f24000593d29138fe95c3eedfad1b55834e2971c4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db3d53d19e6f3fdd1645773f24000593d29138fe95c3eedfad1b55834e2971c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Instruccions i ordres de servei.', true), ('B', 'Decrets i ordres.', false), ('C', 'Resolucions i acords.', false), ('D', 'Reglaments i circulars normatives.', false)) as v(label, body, ok)
)
