with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari (RP), què s''ha d''anotar en l''expedient personal dels interns sancionats?', 'L''art. 250.1 RP disposa que la iniciació del procediment i la sanció imposada s''anoten a l''expedient personal. També s''hi anoten la reducció, la revocació, la suspensió o l''ajornament de les sancions d''aïllament (250.2).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 250.1 RP', 'La iniciación del procedimiento y la sanción impuesta se anotarán en el expediente personal de los internos sancionados.', null, 'c0d18950376046fc3e87187a6840e261706537ee6690b80729737285239cee47', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c0d18950376046fc3e87187a6840e261706537ee6690b80729737285239cee47')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només la sanció imposada, un cop és ferma.', false), ('B', 'Només les sancions per faltes molt greus.', false), ('C', 'Cap dada disciplinària, que consta únicament en el llibre de la Comissió Disciplinària.', false), ('D', 'La iniciació del procediment i la sanció imposada.', true)) as v(label, body, ok)
)
