with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, una decisió de l''Administració penitenciària que impliqui l''apreciació del comportament humà dels interns:', 'L''art. 6.1 RP limita l''ús de la informàtica penitenciària: cap decisió que impliqui apreciar el comportament humà dels interns es pot fonamentar exclusivament en un tractament automatitzat que en defineixi el perfil o la personalitat.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 6.1 RP', 'Ninguna decisión de la Administración penitenciaria que implique la apreciación del comportamiento humano de los reclusos podrá fundamentarse, exclusivamente, en un tratamiento automatizado de datos o informaciones que ofrezcan una definición del perfil o de la personalidad del interno.', null, '9c1f90fc7279c0af6fc4db5da1386677986cebcb4f7452e70ec0e62249e88651', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9c1f90fc7279c0af6fc4db5da1386677986cebcb4f7452e70ec0e62249e88651')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es pot fonamentar exclusivament en un tractament automatitzat de dades que ofereixi una definició del perfil o de la personalitat de l''intern.', true), ('B', 'Es pot fonamentar exclusivament en un tractament automatitzat de dades si ho autoritza el centre directiu.', false), ('C', 'S''ha de fonamentar sempre en un tractament automatitzat de dades per garantir-ne l''objectivitat.', false), ('D', 'Només es pot fonamentar en dades automatitzades amb el consentiment exprés de l''intern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, per recollir dades de caràcter personal dels interns per a l''exercici de les funcions pròpies de l''Administració penitenciària:', 'L''art. 7.1 RP diu que no cal el consentiment de l''intern per recollir les seves dades per a les funcions pròpies de l''Administració penitenciària, llevat dels supòsits de l''art. 15 bis LOGP.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 7.1 RP', 'Cuando los datos de carácter personal de los reclusos se recojan para el ejercicio de las funciones propias de la Administración penitenciaria no será preciso el consentimiento del interno afectado, salvo en los supuestos recogidos en el artículo 15 bis de la Ley Orgánica 1/1979, de 26 de septiembre.', null, '6546ce6e8b4e16fd0ef35385a3b22ffb6adc3224fc4624932656cd1d6181dcfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6546ce6e8b4e16fd0ef35385a3b22ffb6adc3224fc4624932656cd1d6181dcfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cal sempre el consentiment exprés i per escrit de l''intern afectat.', false), ('B', 'Cal l''autorització prèvia del jutge de vigilància penitenciària.', false), ('C', 'Cal el consentiment de l''intern únicament si està en situació de preventiu.', false), ('D', 'No cal el consentiment de l''intern afectat, llevat dels supòsits de l''article 15 bis de la LOGP.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 7 del Reglament penitenciari, a quin dels destinataris següents NO es poden cedir sense el consentiment previ de l''intern les dades personals contingudes en els fitxers informàtics penitenciaris?', 'L''art. 7.3 RP permet cedir dades sense consentiment al Defensor del Poble o institució anàloga, al ministeri fiscal i als jutges o tribunals en l''exercici de les seves funcions. Una empresa privada no és cap dels destinataris previstos.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 7.3 RP', 'También se podrán ceder datos de carácter personal contenidos en los ficheros informáticos penitenciarios sin previo consentimiento del afectado cuando la cesión tenga por destinatarios al Defensor del Pueblo o institución análoga de las Comunidades Autónomas que ejerzan competencias ejecutivas en materia penitenciaria, al Ministerio Fiscal o a los Jueces o Tribunales, en el ejercicio de las funciones que tienen atribuidas', null, 'a9f027c57eedec3f111b981ed70fffcc172970befa0af54359e1ef7f44b00d64', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a9f027c57eedec3f111b981ed70fffcc172970befa0af54359e1ef7f44b00d64')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al ministeri fiscal, en l''exercici de les funcions que té atribuïdes.', false), ('B', 'A una empresa privada que vol contractar l''intern quan surti en llibertat.', true), ('C', 'Als jutges o tribunals, en l''exercici de les funcions que tenen atribuïdes.', false), ('D', 'Al Defensor del Poble o a la institució anàloga de la comunitat autònoma que exerceixi competències executives en matèria penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
