with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, les dades dels interns relatives a opinions polítiques, conviccions religioses o filosòfiques, origen racial i ètnic, salut o vida sexual, recollides per formular els programes de tractament, només es poden cedir o difondre:', 'L''art. 8.1 RP exigeix per a aquestes dades especialment protegides el consentiment exprés i per escrit de l''intern o una llei que ho disposi per raons d''interès general.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 8.1 RP', 'sólo podrán ser cedidos o difundidos a otras personas con el consentimiento expreso y por escrito del recluso afectado o cuando por razones de interés general así lo disponga una Ley.', null, 'b71f361c26e42cb0d91c980e18931f95261f33e50f5a9e6c7f96a94aba518b37', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b71f361c26e42cb0d91c980e18931f95261f33e50f5a9e6c7f96a94aba518b37')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb l''autorització del/de la director/a del centre penitenciari.', false), ('B', 'Amb el consentiment verbal de l''intern davant el/la cap de gestió penitenciària.', false), ('C', 'Amb el consentiment exprés i per escrit de l''intern afectat o quan, per raons d''interès general, ho disposi una llei.', true), ('D', 'Amb l''informe favorable de la junta de tractament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, quan un intern sol·licita la rectificació de les seves dades personals inexactes o incompletes dels fitxers informàtics penitenciaris, en quin termini màxim se l''ha d''informar de la rectificació efectuada?', 'L''art. 9.1 RP fixa un termini màxim de dos mesos des de la sol·licitud per informar l''interessat i, si escau, els cessionaris de la rectificació.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 9.1 RP', 'De la rectificación efectuada se informará al interesado en el plazo máximo de dos meses desde su solicitud', null, '4ac3500b4199f609c0ea2ee707b5ebafd28587e4d27537a2000b18759f4a7a96', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4ac3500b4199f609c0ea2ee707b5ebafd28587e4d27537a2000b18759f4a7a96')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes des de la sol·licitud.', false), ('B', 'Deu dies hàbils des de la sol·licitud.', false), ('C', 'Tres mesos des de la sol·licitud.', false), ('D', 'Dos mesos des de la sol·licitud.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
