with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, la concessió de recompenses als interns:', 'L''art. 264.2 RP obliga a anotar la recompensa a l''expedient personal amb els fets que la van motivar; l''intern pot demanar-ne un certificat.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 264.2 RP', 'La concesión de recompensas será anotada en el expediente personal del interno, con expresión de los hechos que la motivaron', null, '626a0f42b21b96212f3cf66fcd8a2b8e6367d0ffdfe8dd4d536ea0d8f63dfd42', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '626a0f42b21b96212f3cf66fcd8a2b8e6367d0ffdfe8dd4d536ea0d8f63dfd42')
  returning id
), o as (
