)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, en cas de trasllat d''un intern a un altre centre penitenciari per qualsevol motiu, què s''ha d''incloure en el seu expedient personal?', 'L''art. 121.2 RP disposa que, en cas de trasllat per qualsevol motiu, s''inclogui l''historial escolar a l''expedient personal de l''intern.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 121.2 RP', 'En caso de traslado de un recluso a otro Centro penitenciario por cualquier motivo, se incluirá en su expediente personal el historial escolar del mismo.', null, 'bc45bbe18e731cc5a863ee6fecdb0479ae5a10ba71787a37f0fc6db3f9e3e69c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bc45bbe18e731cc5a863ee6fecdb0479ae5a10ba71787a37f0fc6db3f9e3e69c')
  returning id
