)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, les autoritats penitenciàries responsables dels fitxers informàtics penitenciaris i les persones que intervenen en el tractament automatitzat de les dades estan obligades a guardar-ne secret professional:', 'L''art. 6.3 RP imposa el secret professional sobre les dades dels fitxers fins i tot després de finalitzar la relació amb l''Administració penitenciària, i obliga a adoptar mesures tècniques i organitzatives de seguretat.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 6.3 RP', 'a guardar secreto profesional sobre los mismos, incluso después de que haya finalizado su relación con la Administración penitenciaria.', null, '86873056df3b921c1c065a0502851f86866d0c3064e3a16f74370d73196414ec', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '86873056df3b921c1c065a0502851f86866d0c3064e3a16f74370d73196414ec')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només mentre l''intern estigui ingressat al centre.', false), ('B', 'Fins i tot després d''haver finalitzat la seva relació amb l''Administració penitenciària.', true), ('C', 'Durant un termini de cinc anys des que l''intern obté la llibertat.', false), ('D', 'Només respecte de les dades de salut dels interns.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, la inclusió d''un intern en un fitxer que té com a finalitat garantir la seguretat i el bon ordre de l''establiment i la integritat dels interns:', 'L''art. 6.4 RP permet crear fitxers d''interns per raons de seguretat, bon ordre i integritat, però la inclusió en el fitxer no determina per si mateixa un règim de vida diferent.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 6.4 RP', 'En ningún caso la inclusión en dicho fichero determinará por sí misma un régimen de vida distinto de aquél que reglamentariamente corresponda.', null, 'a7cefe39f5829f8e8d72873922cacab0ecf9a39356a1eba18e1c8c00db1777c4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a7cefe39f5829f8e8d72873922cacab0ecf9a39356a1eba18e1c8c00db1777c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comporta automàticament l''aplicació del règim tancat.', false), ('B', 'No determina per si mateixa un règim de vida diferent del que li correspongui reglamentàriament.', true), ('C', 'Requereix el consentiment exprés i per escrit de l''intern.', false), ('D', 'Comporta la suspensió dels permisos de sortida mentre hi consti.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, es poden cedir sense el consentiment de l''intern les dades personals dels fitxers informàtics penitenciaris a altres administracions públiques?', 'L''art. 7.2 RP permet aquesta cessió sense consentiment per a funcions de serveis socials, Seguretat Social, custòdia de menors o anàlogues, d''acord amb la LO 7/2021 (art. 7.4 RP).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 7.2 RP', 'Tampoco será preciso el consentimiento del recluso afectado para ceder a otras Administraciones públicas, en el ámbito de sus respectivas competencias, los datos de carácter personal contenidos en los ficheros informáticos penitenciarios que resulten necesarios para que éstas pueden ejercer sus funciones respecto de los internos en materia de servicios sociales, Seguridad Social, custodia de menores u otras análogas.', null, '8bf61e67c8bb5cd3099a8d611f3f4e17ca110317cd967a990e67f424bcd653d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8bf61e67c8bb5cd3099a8d611f3f4e17ca110317cd967a990e67f424bcd653d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, la cessió a altres administracions sempre requereix el consentiment exprés i per escrit de l''intern.', false), ('B', 'Només si ho autoritza el jutge de vigilància penitenciària.', false), ('C', 'Sí, en l''àmbit de les seves competències, quan les necessitin per exercir les seves funcions respecte dels interns en matèria de serveis socials, Seguretat Social, custòdia de menors o altres d''anàlogues.', true), ('D', 'Només a l''Administració tributària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
