  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El funcionari encarregat de l''Oficina de Règim.', true), ('B', 'El/La cap de serveis.', false), ('C', 'El/La jurista de l''equip multidisciplinari.', false), ('D', 'El/La secretari/ària de la junta de tractament.', false)) as v(label, body, ok)
)
