with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, la fitxa social que elaboren els serveis socials penitenciaris per a cada intern:', 'L''art. 229.1 RP disposa que els serveis socials atenen les persones que ingressen a la presó i elaboren per a cadascuna una fitxa social que forma part del seu protocol personal.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 229.1 RP', 'Los servicios sociales penitenciarios asistirán a las personas que ingresen en prisión y elaborarán una ficha social para cada interno, que formará parte de su protocolo personal.', null, '095ca3638a9528b244451e136dd4d8c5e101aca8a9eded4a3df45e494df3ea8a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '095ca3638a9528b244451e136dd4d8c5e101aca8a9eded4a3df45e494df3ea8a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''incorpora a l''expedient disciplinari.', false), ('B', 'S''ha de trametre al jutge de vigilància penitenciària.', false), ('C', 'Només s''elabora per als interns classificats en tercer grau.', false), ('D', 'Forma part del seu protocol personal.', true)) as v(label, body, ok)
)
