with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, quin òrgan ha de formar i custodiar el protocol corresponent a cada intern?', 'L''art. 273.n RP atribueix a la junta de tractament formar i custodiar el protocol de cada intern, on s''incorporen les informacions i els documents de la seva activitat d''observació, classificació i tractament.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 273.n RP', 'n) Formar y custodiar el protocolo correspondiente a cada interno, incorporando al mismo las informaciones y documentos a que se refieren los diferentes apartados de este artículo.', null, 'ff030859c79b0cffb7881370662728f3bafea63abcd5357d18a73a112af892d8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ff030859c79b0cffb7881370662728f3bafea63abcd5357d18a73a112af892d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Comissió Disciplinària.', false), ('B', 'El Consell de Direcció.', false), ('C', 'La junta de tractament.', true), ('D', 'La unitat de gestió econòmica.', false)) as v(label, body, ok)
)
