with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reglament penitenciari, quan es demanen a l''Administració penitenciària dades especialment protegides d''un intern per mitjà del seu representant:', 'L''art. 8.2 RP exigeix un poder especial i suficient en què consti expressament el consentiment de l''intern perquè el representant pugui accedir a les dades especialment protegides (opinions, creences, origen, salut, vida sexual).', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 8.2 RP', 'deberá exigirse, en todo caso, poder especial y bastante otorgado por el mismo en el que conste expresamente su consentimiento para que su representante pueda tener acceso a dichos datos personales del recluso.', null, '5fe99fe19990660552b2763bca083d5e3f89b2f108092b6e5e004ad7c559009d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5fe99fe19990660552b2763bca083d5e3f89b2f108092b6e5e004ad7c559009d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha d''exigir, en tot cas, un poder especial i suficient atorgat per l''intern en què consti expressament el seu consentiment.', true), ('B', 'N''hi ha prou que el representant acrediti la seva condició d''advocat.', false), ('C', 'S''han de lliurar sense cap requisit addicional, perquè el representant actua en nom de l''intern.', false), ('D', 'Cal l''autorització prèvia del jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
