with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, les dades de caràcter personal dels interns contingudes en els fitxers informàtics penitenciaris NO es cancel·len quan:', 'L''art. 9.2 RP exclou la cancel·lació de les dades quan hi concorren raons d''interès públic, de seguretat i de protecció de drets de tercers, o quan tenen un valor intrínsec històric i estadístic a efectes de recerca.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 9.2 RP', 'Los datos de carácter personal de los reclusos contenidos en los ficheros informáticos penitenciarios no serán cancelados cuando, ponderados los intereses en presencia, concurran razones de interés público, de seguridad y de protección de los derechos y libertades de terceros', null, '94e8027ba6e1e69397545ceccbff81d2770977dee8197e081028de0c27ca9720', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '94e8027ba6e1e69397545ceccbff81d2770977dee8197e081028de0c27ca9720')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''intern obté la llibertat definitiva.', false), ('B', 'Ponderats els interessos en presència, concorren raons d''interès públic, de seguretat i de protecció dels drets i les llibertats de tercers.', true), ('C', 'Han transcorregut sis mesos des del compliment de la darrera sanció.', false), ('D', 'L''intern ho sol·licita per escrit.', false)) as v(label, body, ok)
)
