with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reglament penitenciari, un cop estesa a l''expedient personal del penat la diligència de llibertat definitiva, a qui s''han de trametre les certificacions de llibertat definitiva?', 'L''art. 24.5 RP preveu que la diligència de llibertat definitiva s''estengui a l''expedient personal, tant si l''alliberament es fa al centre com si l''última part de la condemna s''ha complert en llibertat condicional, i que se''n trametin certificacions al tribunal sentenciador i al jutge de vigilància.', 'pcat_e18_gestio_administrativa', (select id from public.topics where slug = 'pcat-e18-gestio-administrativa'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 24.5 RP', 'expidiéndose y remitiéndose certificaciones de libertad definitiva al Tribunal sentenciador y al Juez de Vigilancia.', null, '38523c596a0c81d407cb994f51ed6ac1bd82bb26442fa2c41959ee59208bbd2f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '38523c596a0c81d407cb994f51ed6ac1bd82bb26442fa2c41959ee59208bbd2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al centre directiu i al Ministeri Fiscal.', false), ('B', 'Només al tribunal sentenciador.', false), ('C', 'Al jutge de vigilància i a la policia judicial.', false), ('D', 'Al tribunal sentenciador i al jutge de vigilància.', true)) as v(label, body, ok)
)
