with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 301.1 del Codi penal, qui adquireixi, posseeixi, utilitzi, converteixi o transmeti béns sabent que tenen l''origen en una activitat delictiva serà castigat amb la pena de:', 'El tipus bàsic de blanqueig de capitals (art. 301.1 CP) es castiga amb presó de sis mesos a sis anys i multa del tant al triple del valor dels béns.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 301.1 CP', 'El que adquiera, posea, utilice, convierta, o transmita bienes, sabiendo que éstos tienen su origen en una actividad delictiva, cometida por él o por cualquiera tercera persona, o realice cualquier otro acto para ocultar o encubrir su origen ilícito, o para ayudar a la persona que haya participado en la infracción o infracciones a eludir las consecuencias legales de sus actos, será castigado con la pena de prisión de seis meses a seis años y multa del tanto al triplo del valor de los bienes.', null, 'dbec24b3633593d95fa9fbe5a8284f525a40e52a84cb4be5aa6e204a426cb10d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dbec24b3633593d95fa9fbe5a8284f525a40e52a84cb4be5aa6e204a426cb10d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a dos anys i multa del tant al triple.', false), ('B', 'Presó de dos a cinc anys i multa del tant al dècuple del valor dels béns.', false), ('C', 'Presó de tres a deu anys i inhabilitació absoluta.', false), ('D', 'Presó de sis mesos a sis anys i multa del tant al triple del valor dels béns.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, quan els béns objecte de blanqueig tenen l''origen en algun dels delictes de tràfic de drogues tòxiques, estupefaents o substàncies psicotròpiques dels articles 368 a 372:', 'L''art. 301.1, paràgraf segon, CP agreuja el blanqueig de béns procedents del tràfic de drogues: la pena s''imposa en la meitat superior.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 301.1 CP', 'La pena se impondrá en su mitad superior cuando los bienes tengan su origen en alguno de los delitos relacionados con el tráfico de drogas tóxicas, estupefacientes o sustancias psicotrópicas descritos en los artículos 368 a 372 de este Código.', null, 'a668e197db0ae74687da8b5a77b1b749b74cdd49ba97c42985a9cc0feb0b90d6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a668e197db0ae74687da8b5a77b1b749b74cdd49ba97c42985a9cc0feb0b90d6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''imposa la pena superior en dos graus.', false), ('B', 'La pena s''imposa en la meitat inferior.', false), ('C', 'La pena s''imposa en la meitat superior.', true), ('D', 'S''aplica la mateixa pena del tipus bàsic, sense cap agreujament.', false)) as v(label, body, ok)
)
