with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 303 del Codi penal, si els fets de blanqueig de capitals els fa una autoritat o agent d''aquesta, s''imposa, a més de la pena corresponent, la pena de:', 'L''art. 303 CP preveu inhabilitació especial de tres a deu anys per a empresaris, intermediaris financers, facultatius, funcionaris, treballadors socials, docents o educadors, i inhabilitació absoluta de deu a vint anys si els fets els fa una autoritat o un agent seu.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 303 CP', 'Se impondrá la pena de inhabilitación absoluta de diez a veinte años cuando los referidos hechos fueren realizados por autoridad o agente de la misma.', null, '9fcd4b840cdc172f9bf21257ed3093c136ef78d139ef7c8cf7e5dbc6cc15a56c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9fcd4b840cdc172f9bf21257ed3093c136ef78d139ef7c8cf7e5dbc6cc15a56c')
