with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 248 del Codi penal, cometen estafa els qui, amb ànim de lucre:', 'L''art. 248 CP defineix l''estafa per l''ànim de lucre, l''engany suficient (bastant), l''error i l''acte de disposició en perjudici propi o d''altri; el tipus bàsic es castiga amb presó de sis mesos a tres anys.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 248 CP', 'Cometen estafa los que, con ánimo de lucro, utilizaren engaño bastante para producir error en otro, induciéndolo a realizar un acto de disposición en perjuicio propio o ajeno.', null, 'cc091cee9cbab784116b9a03f7f18d1122fcdb2e333d2f6a3cd640636665f4b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cc091cee9cbab784116b9a03f7f18d1122fcdb2e333d2f6a3cd640636665f4b0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Utilitzen un engany suficient per produir error en una altra persona, i la indueixen a fer un acte de disposició en perjudici propi o d''altri.', true), ('B', 'S''apoderen de coses mobles alienes sense la voluntat del seu propietari.', false), ('C', 'S''apropien de diners o béns que han rebut en dipòsit o administració.', false), ('D', 'Utilitzen violència o intimidació per obligar una altra persona a fer un acte en perjudici propi.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal vigent, també es consideren reus d''estafa, castigats amb presó de sis mesos a tres anys, els qui, amb ànim de lucre i mitjançant una manipulació informàtica o un artifici semblant:', 'L''estafa informàtica es regula actualment a l''art. 249.1.a) CP: transferència no consentida d''un actiu patrimonial aconseguida amb ànim de lucre mitjançant manipulació informàtica o artifici semblant. L''accés il·legal (art. 197 bis.1), els danys informàtics (art. 264) i la interceptació de dades (art. 197 bis.2) són delictes diferents.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 249.1.a) CP', 'Los que, con ánimo de lucro, obstaculizando o interfiriendo indebidamente en el funcionamiento de un sistema de información o introduciendo, alterando, borrando, transmitiendo o suprimiendo indebidamente datos informáticos o valiéndose de cualquier otra manipulación informática o artificio semejante, consigan una transferencia no consentida de cualquier activo patrimonial en perjuicio de otro.', null, '197754006f9d27cb0d5a09a12bd336eafc717781039e0029a8352de5ffaa1ca6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '197754006f9d27cb0d5a09a12bd336eafc717781039e0029a8352de5ffaa1ca6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Accedeixen sense autorització a un sistema d''informació, encara que no causin cap perjudici patrimonial.', false), ('B', 'Esborren dades informàtiques alienes de manera greu, encara que no obtinguin cap benefici.', false), ('C', 'Intercepten transmissions no públiques de dades informàtiques.', false), ('D', 'Aconsegueixen una transferència no consentida de qualsevol actiu patrimonial en perjudici d''un altre.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les afirmacions següents sobre els delictes de terrorisme NO és correcta, segons el Codi penal?', 'L''art. 580 CP equipara, en tots els delictes de terrorisme, la condemna d''un jutge o tribunal estranger a les sentències espanyoles a l''efecte de la reincidència. Les altres tres afirmacions recullen els arts. 571, 572.2 i 579.1 CP.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Arts. 571, 572.2, 579.1 i 580 CP', 'En todos los delitos de terrorismo, la condena de un juez o tribunal extranjero será equiparada a las sentencias de los jueces o tribunales españoles a los efectos de aplicación de la agravante de reincidencia.', null, '91f11610fda26b0abcdffe61e479a9041241fe79ee2722ee62fa9c3e1ec514f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91f11610fda26b0abcdffe61e479a9041241fe79ee2722ee62fa9c3e1ec514f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es consideren organitzacions o grups terroristes les agrupacions que, reunint les característiques de l''organització o del grup criminal, tenen per finalitat la comissió de delictes de terrorisme.', false), ('B', 'La condemna d''un jutge o tribunal estranger per delictes de terrorisme no es té en compte a l''efecte de l''agreujant de reincidència.', true), ('C', 'Qui participi activament en una organització o grup terrorista o en formi part és castigat amb presó de sis a dotze anys i inhabilitació absoluta durant el temps de la condemna.', false), ('D', 'Qui difongui públicament missatges o consignes idonis per incitar altres persones a cometre delictes de terrorisme és castigat amb la pena inferior en un o dos graus a la del delicte de què es tracti.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
