select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 573.1 del Codi penal, quina de les finalitats següents NO és una de les que converteixen un delicte greu en delicte de terrorisme?', 'L''art. 573.1 CP exigeix alguna d''aquestes finalitats: subvertir l''ordre constitucional o desestabilitzar greument les institucions o estructures de l''Estat, alterar greument la pau pública, desestabilitzar greument una organització internacional o provocar un estat de terror. L''ànim de lucre no hi és.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573.1 CP', '1.ª Subvertir el orden constitucional, o suprimir o desestabilizar gravemente el funcionamiento de las instituciones políticas o de las estructuras económicas o sociales del Estado, u obligar a los poderes públicos a realizar un acto o a abstenerse de hacerlo. 2.ª Alterar gravemente la paz pública. 3.ª Desestabilizar gravemente el funcionamiento de una organización internacional. 4.ª Provocar un estado de terror en la población o en una parte de ella.', null, '869b40faf8ee4b8098e256ac6eb9ebd81e921539a7e4f28863bc5e1d6efce2c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '869b40faf8ee4b8098e256ac6eb9ebd81e921539a7e4f28863bc5e1d6efce2c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Subvertir l''ordre constitucional o desestabilitzar greument el funcionament de les institucions polítiques.', false), ('B', 'Alterar greument la pau pública.', false), ('C', 'Provocar un estat de terror en la població o en una part d''aquesta.', false), ('D', 'Obtenir un benefici econòmic per a l''organització, encara que no hi hagi cap altra finalitat.', true)) as v(label, body, ok)
)
