with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 quater del Codi penal, en els supòsits d''organitzacions i grups criminals i de terrorisme, els jutges o tribunals han d''acordar:', 'L''art. 570 quater.1 CP obliga a acordar la dissolució de l''organització o grup i, si escau, les altres conseqüències dels arts. 33.7 i 129 CP, tant en el capítol d''organitzacions i grups criminals com en el de terrorisme.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 quater.1 CP', 'Los jueces o tribunales, en los supuestos previstos en este Capítulo y el siguiente, acordarán la disolución de la organización o grupo y, en su caso, cualquier otra de las consecuencias de los artículos 33.7 y 129 de este Código.', null, 'b1c1bdfddc2031611326a9c0d4070194b45aed5be74a1b94bfbc68512057f967', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b1c1bdfddc2031611326a9c0d4070194b45aed5be74a1b94bfbc68512057f967')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només una multa a la persona jurídica que hagi donat cobertura a l''organització.', false), ('B', 'La suspensió temporal de les activitats de l''organització per un màxim de cinc anys.', false), ('C', 'La intervenció judicial de l''organització, que no es pot dissoldre en cap cas.', false), ('D', 'La dissolució de l''organització o grup i, si escau, qualsevol altra de les conseqüències dels articles 33.7 i 129 del Codi penal.', true)) as v(label, body, ok)
)
