with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 573 bis del Codi penal, si un delicte de terrorisme causa la mort d''una persona, s''imposa la pena de:', 'L''art. 573 bis.1.1a CP castiga amb presó pel temps màxim previst al Codi el delicte de terrorisme que causa la mort d''una persona. Les altres penes corresponen al segrest sense donar raó del parador (20-25 anys), a determinades lesions o estralls (15-20) i a altres lesions o detencions (10-15).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573 bis.1.1a CP', '1.ª Con la de prisión por el tiempo máximo previsto en este Código si se causara la muerte de una persona.', null, '6e6fc5aa0245433bf08e34de8043ef028c2e92b64f9c57fae63c340019cf34c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6e6fc5aa0245433bf08e34de8043ef028c2e92b64f9c57fae63c340019cf34c6')
  returning id
