)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 197.1 del Codi penal, qui, per descobrir els secrets o vulnerar la intimitat d''un altre sense el seu consentiment, s''apoderi dels seus missatges de correu electrònic serà castigat amb la pena de:', 'L''art. 197.1 CP castiga amb presó d''un a quatre anys i multa de dotze a vint-i-quatre mesos l''apoderament de papers, cartes, correus electrònics o altres documents, o la interceptació de telecomunicacions, per descobrir secrets o vulnerar la intimitat.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197.1 CP', 'El que, para descubrir los secretos o vulnerar la intimidad de otro, sin su consentimiento, se apodere de sus papeles, cartas, mensajes de correo electrónico o cualesquiera otros documentos o efectos personales […] será castigado con las penas de prisión de uno a cuatro años y multa de doce a veinticuatro meses.', null, '25578de65d0e9639defc747d59b55254bd7ed363dbc7c7bc9e70b7abfbffb375', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '25578de65d0e9639defc747d59b55254bd7ed363dbc7c7bc9e70b7abfbffb375')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
