with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 264 bis del Codi penal, qui, sense estar autoritzat i de manera greu, obstaculitzi o interrompi el funcionament d''un sistema informàtic aliè serà castigat amb la pena de:', 'L''art. 264 bis.1 CP castiga l''obstaculització o interrupció greu d''un sistema informàtic aliè amb presó de sis mesos a tres anys; si hi concorre alguna circumstància de l''art. 264.2, la pena és de tres a vuit anys.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264 bis.1 CP', 'Será castigado con la pena de prisión de seis meses a tres años el que, sin estar autorizado y de manera grave, obstaculizara o interrumpiera el funcionamiento de un sistema informático ajeno', null, '3738cc3ed134603c7d0b5cbf381166cc2564fbff7720345faeb627cd3c2eb94c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3738cc3ed134603c7d0b5cbf381166cc2564fbff7720345faeb627cd3c2eb94c')
  returning id
), o as (
