)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 bis del Codi penal, qui promogui, constitueixi, organitzi, coordini o dirigeixi una organització criminal que tingui per finalitat cometre delictes que no siguin greus serà castigat amb la pena de presó de:', 'L''art. 570 bis.1 CP castiga els promotors i dirigents amb presó de quatre a vuit anys si la finalitat són delictes greus i de tres a sis anys en els altres casos; els membres o cooperadors, amb dos a cinc anys o un a tres anys, respectivament.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.1 CP', 'y con la pena de prisión de tres a seis años en los demás casos', null, '483fa45fa7ba890debb8ff8e146186f501ce9cab4f652cd57df5a04412af01e2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '483fa45fa7ba890debb8ff8e146186f501ce9cab4f652cd57df5a04412af01e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quatre a vuit anys.', false), ('B', 'Un a tres anys.', false), ('C', 'Tres a sis anys.', true), ('D', 'Dos a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 bis.3 del Codi penal, les penes de l''organització criminal s''imposen en la meitat superior si els delictes van contra determinats béns jurídics. Quin dels següents NO hi és inclòs?', 'L''art. 570 bis.3 CP agreuja les penes si els delictes són contra la vida o la integritat, la llibertat, la llibertat i la indemnitat sexuals o el tràfic d''éssers humans. Els delictes patrimonials no hi són inclosos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 bis.3 CP', 'Se impondrán en su mitad superior las penas respectivamente previstas en este artículo si los delitos fueren contra la vida o la integridad de las personas, la libertad, la libertad e indemnidad sexuales o la trata de seres humanos.', null, 'bcc4fa49dedc5b73adbfd60664f7553664bcb40ace6d5b44428f0e1af2dafd2d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bcc4fa49dedc5b73adbfd60664f7553664bcb40ace6d5b44428f0e1af2dafd2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La vida o la integritat de les persones.', false), ('B', 'La llibertat i la indemnitat sexuals.', false), ('C', 'El tràfic d''éssers humans.', false), ('D', 'El patrimoni i l''ordre socioeconòmic.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, les disposicions sobre organitzacions i grups criminals s''apliquen a les organitzacions o grups que duguin a terme qualsevol acte penalment rellevant a Espanya:', 'L''art. 570 quater.3 CP estén l''aplicació del capítol a qualsevol organització o grup que actuï penalment a Espanya, tot i que s''hagi constituït o actuï a l''estranger.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 quater.3 CP', 'Las disposiciones de este Capítulo serán aplicables a toda organización o grupo criminal que lleve a cabo cualquier acto penalmente relevante en España, aunque se hayan constituido, estén asentados o desarrollen su actividad en el extranjero.', null, 'cf3cabb5ec55b00bf6e1f18913d6bef3a238d5adffc4c79c87b99e56b04fc9d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf3cabb5ec55b00bf6e1f18913d6bef3a238d5adffc4c79c87b99e56b04fc9d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Encara que s''hagin constituït, estiguin assentats o desenvolupin la seva activitat a l''estranger.', true), ('B', 'Només si s''han constituït a Espanya.', false), ('C', 'Només si la majoria dels seus membres són de nacionalitat espanyola.', false), ('D', 'Només si tenen la seu a la Unió Europea.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 quater.4 del Codi penal, es pot imposar la pena inferior en un o dos graus al responsable d''un delicte d''organització o grup criminal que hagi abandonat voluntàriament les activitats delictives i hagi col·laborat activament amb les autoritats. Quina de les finalitats següents NO s''hi preveu com a objecte d''aquesta col·laboració?', 'L''art. 570 quater.4 CP exigeix l''abandonament voluntari i la col·laboració activa per obtenir proves decisives, impedir l''actuació de l''organització o evitar un delicte. La reparació del dany no és un requisit d''aquest precepte.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 quater.4 CP', 'bien para obtener pruebas decisivas para la identificación o captura de otros responsables o para impedir la actuación o el desarrollo de las organizaciones o grupos a que haya pertenecido, bien para evitar la perpetración de un delito que se tratara de cometer en el seno o a través de dichas organizaciones o grupos.', null, '7e940307948d0c1bd74cc04c08489f9612c7329bfe03aecc8a10a4ad6756d53c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7e940307948d0c1bd74cc04c08489f9612c7329bfe03aecc8a10a4ad6756d53c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obtenir proves decisives per identificar o capturar altres responsables.', false), ('B', 'Reparar íntegrament el dany causat a les víctimes abans del judici.', true), ('C', 'Impedir l''actuació o el desenvolupament de les organitzacions o grups a què hagi pertangut.', false), ('D', 'Evitar que es cometi un delicte en el si de les organitzacions o grups o a través d''aquests.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, si els delictes de descobriment i revelació de secrets del capítol corresponent (inclosos l''accés il·legal a sistemes d''informació i la interceptació de dades informàtiques) es cometen en el si d''una organització o grup criminal:', 'L''art. 197 quater CP disposa que, si els fets del capítol es cometen en el si d''una organització o grup criminal, s''apliquen les penes superiors en grau.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197 quater CP', 'Si los hechos descritos en este Capítulo se hubieran cometido en el seno de una organización o grupo criminal, se aplicarán respectivamente las penas superiores en grado.', null, '590f4d50667e04c6d7c5158e3b1d2b2e81cf22e43fc67a46015566bfd20ef00c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '590f4d50667e04c6d7c5158e3b1d2b2e81cf22e43fc67a46015566bfd20ef00c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''apliquen, respectivament, les penes superiors en grau.', true), ('B', 'S''apliquen les penes en la meitat inferior.', false), ('C', 'S''apliquen les mateixes penes, sense cap agreujament.', false), ('D', 'Només s''imposa la pena del delicte d''organització criminal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 574 del Codi penal, el dipòsit d''armes o municions, o la tinença o el dipòsit de substàncies o aparells explosius, quan es cometen amb alguna de les finalitats terroristes, es castiga amb la pena de presó de:', 'L''art. 574.1 CP castiga aquestes conductes amb presó de vuit a quinze anys; si es tracta d''armes o aparells nuclears, radiològics, químics o biològics, la pena és de deu a vint anys (574.2).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 574.1 CP', 'serán castigados con la pena de prisión de ocho a quince años cuando los hechos se cometan con cualquiera de las finalidades expresadas en el apartado 1 del artículo 573.', null, 'f5941f56d8ff2750c496df6e36216cf7b8e9669a98667c4b6ddfcd98ccdc9fd5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f5941f56d8ff2750c496df6e36216cf7b8e9669a98667c4b6ddfcd98ccdc9fd5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu a vint anys.', false), ('B', 'Cinc a deu anys.', false), ('C', 'Vuit a quinze anys.', true), ('D', 'Dos a cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 575.2 del Codi penal, s''entén que comet el delicte qui, amb la finalitat de capacitar-se per cometre delictes de terrorisme:', 'L''art. 575.2 CP castiga l''autocapacitació i considera que la comet qui, amb aquesta finalitat, accedeix de manera habitual a continguts en línia idonis per incitar a la incorporació o a la col·laboració amb una organització terrorista, o adquireix o té documents d''aquesta mena.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 575.2 CP', 'Se entenderá que comete este delito quien, con tal finalidad, acceda de manera habitual a uno o varios servicios de comunicación accesibles al público en línea o contenidos accesibles a través de internet o de un servicio de comunicaciones electrónicas cuyos contenidos estén dirigidos o resulten idóneos para incitar a la incorporación a una organización o grupo terrorista, o a colaborar con cualquiera de ellos o en sus fines.', null, '1f2506bd21f8bf724219170dfd0c63ece9418dd414820ca60de418b5171d5cfb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1f2506bd21f8bf724219170dfd0c63ece9418dd414820ca60de418b5171d5cfb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Consulta una sola vegada una pàgina web sobre terrorisme amb finalitats periodístiques.', false), ('B', 'Rep informació sobre terrorisme en un curs universitari reglat.', false), ('C', 'Publica un article d''opinió sobre la història d''una organització terrorista dissolta.', false), ('D', 'Accedeix de manera habitual a serveis de comunicació accessibles al públic en línia o a continguts d''internet dirigits o idonis per incitar a incorporar-se a una organització o grup terrorista o a col·laborar-hi.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb el delicte de finançament del terrorisme (art. 576 CP), quina de les afirmacions següents NO és correcta?', 'L''art. 576.1 CP castiga qui recapta, adquireix o utilitza béns amb la intenció o el coneixement que s''utilitzaran per cometre delictes de terrorisme; no cal que s''arribin a utilitzar. Si s''empren en actes concrets, el fet es castiga com a coautoria o complicitat (576.2).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 576 CP', 'Será castigado con la pena de prisión de cinco a diez años y multa del triple al quíntuplo de su valor el que, por cualquier medio, directa o indirectamente, recabe, adquiera, posea, utilice, convierta, transmita o realice cualquier otra actividad con bienes o valores de cualquier clase con la intención de que se utilicen, o a sabiendas de que serán utilizados […] Si los bienes o valores se pusieran efectivamente a disposición del responsable del delito de terrorismo, se podrá imponer la pena superior en grado. […] dé lugar, por imprudencia grave en el cumplimiento de dichas obligaciones, a que no sea detectada o impedida cualquiera de las conductas descritas en el apartado 1 será castigado con la pena inferior en uno o dos grados a la prevista en él.', null, '1fc13fd6546e787bfe2e505bb5c3cca9aa3ccd084147fa359bc6e3ace7fafb3c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1fc13fd6546e787bfe2e505bb5c3cca9aa3ccd084147fa359bc6e3ace7fafb3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només és punible si els béns o valors arriben a utilitzar-se efectivament en un acte terrorista concret.', true), ('B', 'Es castiga amb presó de cinc a deu anys i multa del triple al quíntuple del valor dels béns o valors.', false), ('C', 'Si els béns o valors es posen efectivament a disposició del responsable del delicte de terrorisme, es pot imposar la pena superior en grau.', false), ('D', 'Qui, estant subjecte per llei a col·laborar en la prevenció del finançament del terrorisme, doni lloc per imprudència greu que no es detecti o impedeixi la conducta és castigat amb la pena inferior en un o dos graus.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 302 del Codi penal, en els delictes de blanqueig de capitals, als caps, administradors o encarregats de les organitzacions dedicades a aquestes finalitats se''ls imposa:', 'L''art. 302.1 CP imposa la pena en la meitat superior als qui pertanyen a una organització dedicada al blanqueig i la pena superior en grau als seus caps, administradors o encarregats.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 302.1 CP', 'se impondrán las penas privativas de libertad en su mitad superior a las personas que pertenezca a una organización dedicada a los fines señalados en los mismos, y la pena superior en grado a los jefes, administradores o encargados de las referidas organizaciones.', null, 'b59c0cf935e55c9fae00997936d9144fa08b991cc7490a252e1af216aed1955e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b59c0cf935e55c9fae00997936d9144fa08b991cc7490a252e1af216aed1955e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pena en la meitat superior.', false), ('B', 'La mateixa pena que a la resta de membres.', false), ('C', 'La pena superior en grau.', true), ('D', 'La pena inferior en grau, si col·laboren amb la justícia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 305 bis del Codi penal, quina de les circumstàncies següents NO determina el tipus agreujat del delicte contra la Hisenda pública (presó de dos a sis anys)?', 'L''art. 305 bis.1 CP preveu tres circumstàncies: quota superior a 600.000 euros, comissió en el si d''una organització o grup criminal i ús d''interposicions o paradisos fiscals que dificultin la identificació. La condició de funcionari no hi figura.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 305 bis.1 CP', 'a) Que la cuantía de la cuota defraudada exceda de seiscientos mil euros. b) Que la defraudación se haya cometido en el seno de una organización o de un grupo criminal. c) Que la utilización de personas físicas o jurídicas o entes sin personalidad jurídica interpuestos, negocios o instrumentos fiduciarios o paraísos fiscales o territorios de nula tributación oculte o dificulte la determinación de la identidad del obligado tributario', null, '29f0647aacdbdda9babada260ae9ec9b11c47765fd81d4ca15cb4cda10fe1e71', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29f0647aacdbdda9babada260ae9ec9b11c47765fd81d4ca15cb4cda10fe1e71')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que la quantia de la quota defraudada excedeixi de sis-cents mil euros.', false), ('B', 'Que el responsable sigui funcionari de l''Administració tributària.', true), ('C', 'Que la defraudació s''hagi comès en el si d''una organització o d''un grup criminal.', false), ('D', 'Que la utilització de persones o entitats interposades o de paradisos fiscals oculti o dificulti la determinació de la identitat de l''obligat tributari o de la quantia defraudada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 286 bis del Codi penal, el directiu, administrador, empleat o col·laborador d''una empresa mercantil que rebi, sol·liciti o accepti un benefici o avantatge no justificat com a contraprestació per afavorir indegudament un altre en les relacions comercials serà castigat amb:', 'L''art. 286 bis.1 CP (corrupció en els negocis) castiga amb presó de sis mesos a quatre anys, inhabilitació especial per a la indústria o el comerç d''un a sis anys i multa del tant al triple; les mateixes penes s''apliquen a qui ofereix o concedeix l''avantatge (286 bis.2).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 286 bis.1 CP', 'será castigado con la pena de prisión de seis meses a cuatro años, inhabilitación especial para el ejercicio de industria o comercio por tiempo de uno a seis años y multa del tanto al triplo del valor del beneficio o ventaja.', null, '5013cbc81b310ddd75df8d3ba5f9ca1c529f44ab87bed3bbd43291a962dee787', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5013cbc81b310ddd75df8d3ba5f9ca1c529f44ab87bed3bbd43291a962dee787')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
