)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, qui, mitjançant artificis o instruments tècnics i sense estar degudament autoritzat, intercepti transmissions no públiques de dades informàtiques que es produeixin des d''un sistema d''informació, cap a aquest o dins d''aquest, serà castigat amb la pena de:', 'L''art. 197 bis.2 CP castiga la interceptació de transmissions no públiques de dades informàtiques (incloses les emissions electromagnètiques) amb presó de tres mesos a dos anys o multa de tres a dotze mesos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197 bis.2 CP', 'será castigado con una pena de prisión de tres meses a dos años o multa de tres a doce meses.', null, 'd6afecac1f313a7f27fa48b4344484c14c36ba3e87299d6b9ec45ed5defb49b5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6afecac1f313a7f27fa48b4344484c14c36ba3e87299d6b9ec45ed5defb49b5')
  returning id
), o as (
