)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 264.2 del Codi penal, quina de les circumstàncies següents NO comporta la pena agreujada de presó de dos a cinc anys en el delicte de danys informàtics?', 'L''art. 264.2 CP agreuja els danys informàtics, entre altres casos, si es cometen en el marc d''una organització criminal, si perjudiquen greument serveis públics essencials o si afecten una infraestructura crítica. L''edat de l''autor no hi figura.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264.2 CP', '1.ª Se hubiese cometido en el marco de una organización criminal. […] 3.ª El hecho hubiera perjudicado gravemente el funcionamiento de servicios públicos esenciales o la provisión de bienes de primera necesidad. 4.ª Los hechos hayan afectado al sistema informático de una infraestructura crítica', null, 'd23c0f33d8285fe11b2183d82e3df78d8fdfc99e5efee8a05c8c964a1096448e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd23c0f33d8285fe11b2183d82e3df78d8fdfc99e5efee8a05c8c964a1096448e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el fet s''hagi comès en el marc d''una organització criminal.', false), ('B', 'Que el fet hagi perjudicat greument el funcionament de serveis públics essencials.', false), ('C', 'Que els fets hagin afectat el sistema informàtic d''una infraestructura crítica.', false), ('D', 'Que l''autor sigui menor de vint-i-un anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 ter del Codi penal, qui constitueixi, financi o integri un grup criminal la finalitat del qual sigui cometre qualsevol delicte greu diferent dels esmentats a l''apartat 3 de l''article 570 bis serà castigat amb la pena de presó de:', 'L''art. 570 ter.1 CP castiga el grup criminal amb dos a quatre anys (delictes greus de l''art. 570 bis.3), un a tres anys (delictes menys greus d''aquest tipus), sis mesos a dos anys (qualsevol altre delicte greu) i tres mesos a un any (altres delictes menys greus o lleus reiterats).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 ter.1.b CP', 'b) Con la pena de seis meses a dos años de prisión si la finalidad del grupo es cometer cualquier otro delito grave.', null, 'aa43fd48332c1b42bf604f8ca9ff2af75ef54b5ec735a6400602df6f36b5738c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa43fd48332c1b42bf604f8ca9ff2af75ef54b5ec735a6400602df6f36b5738c')
  returning id
), o as (
