)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 570 quater del Codi penal, als responsables dels delictes d''organització o grup criminal se''ls imposa, a més, la pena d''inhabilitació especial per a les activitats econòmiques o negocis jurídics relacionats amb l''activitat de l''organització o grup per un temps:', 'L''art. 570 quater.2 CP preveu aquesta inhabilitació especial per un temps superior entre sis i vint anys al de la pena privativa de llibertat, segons la gravetat del delicte, el nombre de delictes i les circumstàncies del delinqüent.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 570 quater.2 CP', 'por un tiempo superior entre seis y veinte años al de la duración de la pena de privación de libertad impuesta en su caso', null, '4afc8de2d60f7dd627b095c365e94ce8d5f650ef4c50757ab1ecaa4ee48f3284', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4afc8de2d60f7dd627b095c365e94ce8d5f650ef4c50757ab1ecaa4ee48f3284')
  returning id
), o as (
