  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 573 bis del Codi penal, quan en un delicte de terrorisme de segrest o detenció il·legal no es dona raó del parador de la persona, la pena és de presó de:', 'L''art. 573 bis.1.2a CP fixa presó de vint a vint-i-cinc anys quan, en el segrest o la detenció il·legal terroristes, no es dona raó del parador de la persona.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 573 bis.1.2a CP', '2.ª Con la de prisión de veinte a veinticinco años cuando, en los casos de secuestro o detención ilegal, no se dé razón del paradero de la persona.', null, '948e978eb6829412195fabe6c6264a96576c933acfcfa24b1e39ebb0fbf4f1f7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '948e978eb6829412195fabe6c6264a96576c933acfcfa24b1e39ebb0fbf4f1f7')
