insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 579 bis del Codi penal, els jutges i tribunals, motivadament i atenent a les circumstàncies concretes, poden imposar la pena inferior en un o dos graus en els delictes de terrorisme quan:', 'L''art. 579 bis.4 CP permet rebaixar la pena en un o dos graus quan el fet és objectivament de menor gravetat pel mitjà emprat o el resultat; l''art. 579 bis.3 preveu també la rebaixa per abandonament i col·laboració.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 579 bis.4 CP', 'cuando el hecho sea objetivamente de menor gravedad, atendidos el medio empleado o el resultado producido.', null, '05067bb1cc3d8149e086c61c2fb577879ba2f9d0e1331023b0f5896d7d9c2bc7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '05067bb1cc3d8149e086c61c2fb577879ba2f9d0e1331023b0f5896d7d9c2bc7')
  returning id
