)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 580 bis del Codi penal, quan una persona jurídica és responsable d''un delicte de terrorisme i el delicte comès per la persona física té prevista una pena de més de dos anys de privació de llibertat, se li imposa la pena de:', 'L''art. 580 bis CP preveu per a la persona jurídica multa de dos a cinc anys (o del doble al quàdruple del perjudici) si la pena de la persona física és de més de dos anys, i multa de sis mesos a dos anys (o del doble al triple) en els altres casos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 580 bis CP', 'a) Multa de dos a cinco años, o del doble al cuádruple del perjuicio causado cuando la cantidad resultante fuese más elevada, si el delito cometido por la persona física tiene prevista una pena de más de dos años de privación de libertad.', null, '0da0028e30a276664702b04cd646364a7fc2d3dee98913e2c8c6b1280e2b92f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0da0028e30a276664702b04cd646364a7fc2d3dee98913e2c8c6b1280e2b92f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de sis mesos a dos anys, o del doble al triple del perjudici causat.', false), ('B', 'Multa d''un a tres anys, o del triple a vuit vegades el valor del perjudici.', false), ('C', 'Dissolució obligatòria, sense multa.', false), ('D', 'Multa de dos a cinc anys, o del doble al quàdruple del perjudici causat si la quantitat resultant és més elevada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 197 ter del Codi penal, qui, sense estar degudament autoritzat, produeixi, adquireixi per al seu ús, importi o faciliti a tercers una contrasenya d''ordinador o un codi d''accés amb la intenció de facilitar l''accés il·legal a un sistema d''informació serà castigat amb la pena de:', 'L''art. 197 ter CP castiga la producció, adquisició o facilitació de programes informàtics o contrasenyes per cometre els delictes dels arts. 197.1, 197.2 o 197 bis amb presó de sis mesos a dos anys o multa de tres a divuit mesos.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 197 ter CP', 'Será castigado con una pena de prisión de seis meses a dos años o multa de tres a dieciocho meses el que, sin estar debidamente autorizado, produzca, adquiera para su uso, importe o, de cualquier modo, facilite a terceros', null, '8e2b6c6edbc4f4878c017c4aefa28e3520b3d988c09380aa69774ecc693fb648', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8e2b6c6edbc4f4878c017c4aefa28e3520b3d988c09380aa69774ecc693fb648')
  returning id
), o as (
