  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a dos anys o multa de tres a divuit mesos.', true), ('B', 'Presó d''un a quatre anys i multa de dotze a vint-i-quatre mesos.', false), ('C', 'Presó de tres a cinc anys.', false), ('D', 'Multa d''un a tres mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A l''efecte de l''agreujant dels danys informàtics de l''article 264.2 del Codi penal, què es considera infraestructura crítica?', 'L''art. 264.2.4a CP defineix la infraestructura crítica pel seu caràcter essencial per a les funcions vitals de la societat i per l''impacte significatiu que tindria la seva pertorbació o destrucció.', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 264.2.4a CP', 'A estos efectos se considerará infraestructura crítica un elemento, sistema o parte de este que sea esencial para el mantenimiento de funciones vitales de la sociedad, la salud, la seguridad, la protección y el bienestar económico y social de la población cuya perturbación o destrucción tendría un impacto significativo', null, '7ff844f8f8e3b88e3e13e6c130d1dd0d7ff370156d8665b50b88ee784606560d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7ff844f8f8e3b88e3e13e6c130d1dd0d7ff370156d8665b50b88ee784606560d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un element, sistema o part d''aquest que sigui essencial per al manteniment de funcions vitals de la societat, la salut, la seguretat, la protecció i el benestar econòmic i social de la població, la pertorbació o destrucció del qual tindria un impacte significatiu.', true), ('B', 'Qualsevol sistema informàtic de titularitat pública.', false), ('C', 'Qualsevol xarxa de comunicacions amb més de cent mil usuaris.', false), ('D', 'Només els sistemes informàtics de les forces armades.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 308 del Codi penal, qui obtingui subvencions o ajudes de les administracions públiques falsejant les condicions requerides per concedir-les és castigat amb presó d''un a cinc anys i multa del tant al sèxtuple quan la quantitat o el valor obtingut és superior a:', 'L''art. 308.1 CP fixa el llindar en 100.000 euros, llevat que es faci el reintegrament; entre 10.000 i 100.000 euros la pena és de presó de tres mesos a un any o multa (308.4).', 'pcat_e19_criminologia', (select id from public.topics where slug = 'pcat-e19-criminologia'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 308.1 CP', 'El que obtenga subvenciones o ayudas de las Administraciones Públicas, incluida la Unión Europea, en una cantidad o por un valor superior a cien mil euros falseando las condiciones requeridas para su concesión u ocultando las que la hubiesen impedido será castigado con la pena de prisión de uno a cinco años y multa del tanto al séxtuplo de su importe', null, 'b844f395e37dfe429d25ab58e5d8dbdc94d006af5da6fcbf25d123e188994382', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b844f395e37dfe429d25ab58e5d8dbdc94d006af5da6fcbf25d123e188994382')
  returning id
), o as (
