with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 23/2009, del Centre d''Iniciatives per a la Reinserció (CIRE), quin és l''objecte del CIRE?', 'L''art. 2.1 de la Llei 23/2009 diu que l''objecte del CIRE és facilitar la reinserció sociolaboral dels interns en centres penitenciaris i educatius de Catalunya, mitjançant programes formatius i educatius, creació de llocs de treball i altres actuacions.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-734'), 'Art. 2.1 Llei 23/2009', 'El objeto del Centro de Iniciativas para la Reinserción es facilitar la reinserción sociolaboral de los internos en centros penitenciarios y educativos de Cataluña', 'El fitxer leyes/LCIRE.md és la versió original de 2009 (no consolidada); convé confirmar que l''art. 2.1 no s''ha modificat.', '4fda0ddc61e2e6e6ffa0c45c42600bb38645362b6bf48be8c1340ce217312a6f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4fda0ddc61e2e6e6ffa0c45c42600bb38645362b6bf48be8c1340ce217312a6f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Facilitar la reinserció sociolaboral dels interns en centres penitenciaris i educatius de Catalunya.', true), ('B', 'Gestionar la seguretat exterior dels centres penitenciaris de Catalunya.', false), ('C', 'Instruir els expedients disciplinaris dels interns que treballen als tallers.', false), ('D', 'Avaluar el risc de reincidència dels interns mitjançant el protocol RisCanvi.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 23/2009, quina naturalesa jurídica té el Centre d''Iniciatives per a la Reinserció?', 'L''art. 1.1 de la Llei 23/2009 configura el CIRE com a empresa pública de la Generalitat, entitat de dret públic amb personalitat jurídica pròpia que actua sotmesa al dret privat, llevat de les excepcions previstes.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-734'), 'Art. 1.1 Llei 23/2009', 'El Centro de Iniciativas para la Reinserción es una empresa pública de la Generalidad que tiene naturaleza de entidad de derecho público con personalidad jurídica propia, cuya actuación se ajusta al derecho privado, excepto en los supuestos y materias expresamente especificados en la presente ley.', 'El fitxer leyes/LCIRE.md és la versió original de 2009 (no consolidada); convé confirmar que l''art. 1.1 no s''ha modificat.', '266a82ff510760f8348f7b1220a24ff4ffbe74a6d99b530e93d402d83175a721', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '266a82ff510760f8348f7b1220a24ff4ffbe74a6d99b530e93d402d83175a721')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És un òrgan administratiu del departament competent en matèria d''execució penal sense personalitat jurídica pròpia.', false), ('B', 'És una societat mercantil de capital privat que gestiona els tallers per concessió administrativa.', false), ('C', 'És una fundació del sector públic subjecta íntegrament al dret administratiu.', false), ('D', 'És una empresa pública de la Generalitat amb naturalesa d''entitat de dret públic amb personalitat jurídica pròpia, que ajusta la seva actuació al dret privat, llevat dels supòsits que la llei especifica.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 23/2009, del Centre d''Iniciatives per a la Reinserció, quin dels òrgans següents NO és un òrgan de govern del CIRE?', 'L''art. 4 de la Llei 23/2009 enumera com a òrgans de govern del CIRE el Consell d''Administració, la Comissió Executiva i el director o directora. La llei també regula un Consell Assessor (art. 10), però no l''inclou entre els òrgans de govern.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-734'), 'Art. 4 Llei 23/2009', 'Los órganos de gobierno del Centro de Iniciativas para la Reinserción son: […] a) El Consejo de Administración. […] b) La Comisión Ejecutiva. […] c) El director o directora.', 'El fitxer leyes/LCIRE.md és la versió de 2009 (consolidada només fins al 2012); cal confirmar que l''art. 4 no s''ha modificat.', '935f98f882d7311b0dd1d02bec249417922e6a70bd30e93b771a0253c6cfb171', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '935f98f882d7311b0dd1d02bec249417922e6a70bd30e93b771a0253c6cfb171')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consell Assessor.', true), ('B', 'El Consell d''Administració.', false), ('C', 'La Comissió Executiva.', false), ('D', 'El director o directora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 23/2009, a què s''han de destinar els beneficis del Centre d''Iniciatives per a la Reinserció, si n''hi ha?', 'L''art. 16 de la Llei 23/2009 disposa que els beneficis del CIRE, si n''hi ha, s''han de destinar a millorar els mitjans per desenvolupar les seves activitats i a crear-ne de noves.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-734'), 'Art. 16 Llei 23/2009', 'Los beneficios del Centro de Iniciativas para la Reinserción, si los hubiere, deben destinarse a la mejora de los medios para el desarrollo de sus actividades y a la creación de otras nuevas.', 'El fitxer leyes/LCIRE.md és la versió de 2009 (consolidada només fins al 2012); cal confirmar que l''art. 16 no s''ha modificat.', '3e0afaf57764d9b5c3e11597b6c3cdb3ed19a88d29f55d97539fb072a0844cf6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e0afaf57764d9b5c3e11597b6c3cdb3ed19a88d29f55d97539fb072a0844cf6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A ingressar-los a la Tresoreria de la Generalitat, com a recurs del pressupost general.', false), ('B', 'A millorar els mitjans per desenvolupar les seves activitats i a crear-ne de noves.', true), ('C', 'A repartir-los entre els interns treballadors en proporció a les hores treballades.', false), ('D', 'A constituir un fons de reserva per pagar indemnitzacions a les víctimes dels delictes.', false)) as v(label, body, ok)
)
