with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei orgànica general penitenciària (LOGP), com es considera el treball de l''intern?', 'L''art. 26 de la LOGP considera el treball com un dret i com un deure de l''intern, i n''afirma que és un element fonamental del tractament.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 26 LOGP', 'El trabajo será considerado como un derecho y como un deber del interno, siendo un elemento fundamental del tratamiento.', null, '78ae925d2fa9caff2e0d0e935b03bdd4e0bd4df693940809765fd21f3009ce83', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '78ae925d2fa9caff2e0d0e935b03bdd4e0bd4df693940809765fd21f3009ce83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només com un dret de l''intern, que l''Administració ha de facilitar si hi ha llocs disponibles.', false), ('B', 'Només com un deure dels penats, de caràcter complementari al tractament.', false), ('C', 'Com un dret i com un deure de l''intern, i com un element fonamental del tractament.', true), ('D', 'Com una activitat voluntària, sense relació amb el tractament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, quina és la situació dels interns en presó preventiva respecte del treball?', 'L''art. 29.2 de la LOGP estableix que els preventius poden treballar d''acord amb les seves aptituds i inclinacions; l''obligació de treballar de l''art. 29.1 recau en els penats.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 29.2 LOGP', 'Los sometidos a prisión preventiva podrán trabajar conforme a sus aptitudes e inclinaciones.', null, 'fb51491f433ffcddf4d5dbfa59ed1f585f5e08b3a32fcebc2b6da0aab40f54cc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fb51491f433ffcddf4d5dbfa59ed1f585f5e08b3a32fcebc2b6da0aab40f54cc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estan obligats a treballar en les mateixes condicions que els penats.', false), ('B', 'No poden treballar fins que hi hagi sentència ferma.', false), ('C', 'Només poden fer treballs de neteja i higiene de l''establiment.', false), ('D', 'Poden treballar d''acord amb les seves aptituds i inclinacions.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, en quina mesura s''ha de tenir en compte la satisfacció dels interessos personals de l''intern en el tractament?', 'L''art. 61.2 de la LOGP disposa que s''han d''estimular l''interès i la col·laboració dels interns en el seu tractament i que la satisfacció dels seus interessos personals s''ha de tenir en compte en la mesura compatible amb les finalitats del tractament.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 61.2 LOGP', 'Serán estimulados, en cuanto sea posible, el interés y la colaboración de los internos en su propio tratamiento. La satisfacción de sus intereses personales será tenida en cuenta en la medida compatible con las finalidades del mismo.', null, '156548cb3f0130e2fafa850de3666039a3bc7961f01bf362bfa34106a2ddbfeb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '156548cb3f0130e2fafa850de3666039a3bc7961f01bf362bfa34106a2ddbfeb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre i amb caràcter prioritari respecte de qualsevol altra finalitat.', false), ('B', 'En la mesura que sigui compatible amb les finalitats del tractament.', true), ('C', 'Només quan ho autoritzi expressament el jutge de vigilància penitenciària.', false), ('D', 'No s''ha de tenir en compte, perquè el tractament el determina exclusivament l''equip tècnic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LOGP, quina de les afirmacions següents sobre les condicions del treball penitenciari NO és correcta?', 'L''art. 26 de la LOGP estableix que el treball no té caràcter aflictiu ni es pot aplicar com a mesura de correcció, que no ha d''atemptar contra la dignitat de l''intern, que té caràcter formatiu, creador o conservador d''hàbits laborals, productiu o terapèutic, i que no se supedita a l''assoliment d''interessos econòmics per part de l''Administració.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 26 LOGP', 'a) No tendrá carácter aflictivo ni será aplicado como medida de corrección. […] b) No atentará a la dignidad del interno. […] c) Tendrá carácter formativo, creador o conservador de hábitos laborales, productivo o terapéutico […] g) No se supeditará al logro de intereses económicos por la Administración.', null, 'c0c91c00e3f89293cdb536ec4a26c3f84f424b9f5e781473248ba718dc3a7ffe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c0c91c00e3f89293cdb536ec4a26c3f84f424b9f5e781473248ba718dc3a7ffe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No ha d''atemptar contra la dignitat de l''intern.', false), ('B', 'Es pot aplicar com a mesura de correcció quan la conducta de l''intern ho requereixi.', true), ('C', 'Ha de tenir caràcter formatiu, creador o conservador d''hàbits laborals, productiu o terapèutic.', false), ('D', 'No s''ha de supeditar a l''assoliment d''interessos econòmics per part de l''Administració.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, quin dels col·lectius següents NO queda exceptuat de l''obligació de treballar que tenen els penats?', 'L''art. 29.1 de la LOGP exceptua de l''obligació de treballar, entre d''altres, els qui estan sotmesos a tractament mèdic fins a l''alta, els qui pateixen incapacitat permanent per a tota classe de treballs, els majors de seixanta-cinc anys i els perceptors de prestacions per jubilació. La durada de la pena no és cap causa d''excepció.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 29.1 LOGP', 'b) Los que padezcan incapacidad permanente para toda clase de trabajos. […] c) Los mayores de sesenta y cinco años. […] d) Los perceptores de prestaciones por jubilación.', null, '9e1d9e79946d255382d3b7e1c098f37c8a6058278fd5974423c34518ea95d570', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9e1d9e79946d255382d3b7e1c098f37c8a6058278fd5974423c34518ea95d570')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els majors de seixanta-cinc anys.', false), ('B', 'Els perceptors de prestacions per jubilació.', false), ('C', 'Els qui pateixen incapacitat permanent per a tota classe de treballs.', false), ('D', 'Els penats condemnats a penes inferiors a un any.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LOGP, en quin termini s''han d''inscriure els alliberats a l''oficina d''ocupació perquè, si no reben una oferta de treball adequada, tinguin dret a la prestació per desocupació?', 'L''art. 35 de la LOGP reconeix el dret a la prestació per desocupació, en les condicions que es fixin per reglament, als alliberats que s''hagin inscrit a l''oficina d''ocupació dins dels quinze dies següents a l''excarceració i no hagin rebut una oferta de treball adequada.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708'), 'Art. 35 LOGP', 'Los liberados que se hayan inscrito en la oficina de empleo dentro de los quince días siguientes a su excarcelación y no hayan recibido una oferta de trabajo adecuada tendrán derecho a la prestación por desempleo', null, '6d8207c1d3dbda6edd17ae070610241f86be2dc86c0250041c718524f275c003', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6d8207c1d3dbda6edd17ae070610241f86be2dc86c0250041c718524f275c003')
  returning id
), o as (
