  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 782/2001, quina és la finalitat essencial del treball dels interns en els tallers productius penitenciaris?', 'L''art. 4.1 del RD 782/2001 fixa com a finalitat essencial del treball la preparació per a la futura inserció laboral de l''intern, connectada amb la formació professional ocupacional.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 4.1 RD 782/2001', 'La finalidad esencial del trabajo es la preparación para la futura inserción laboral del interno', null, '45389a0a662c80add9647056ba5390242221a2a1fa14ca31e4a5c3e6ad6949f4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '45389a0a662c80add9647056ba5390242221a2a1fa14ca31e4a5c3e6ad6949f4')
