  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''autofinançament dels centres penitenciaris.', false), ('B', 'El compliment de la sanció disciplinària imposada.', false), ('C', 'La preparació per a la futura inserció laboral de l''intern.', true), ('D', 'La reparació del dany causat a la víctima.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reial decret 782/2001, quina durada tenen les vacances anuals dels interns treballadors en els tallers productius?', 'L''art. 17.5 del RD 782/2001 estableix trenta dies naturals de vacances anuals (o la part proporcional), amb el moment de gaudi condicionat al tractament i a les necessitats de treball.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 17.5 RD 782/2001', 'Las vacaciones anuales de los internos trabajadores tendrán una duración de treinta días naturales o la parte proporcional que corresponda en su caso.', null, '4deb33686fcd81a20ed5a8ba028db270835385facbd6f54cc6eab62ea998851d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4deb33686fcd81a20ed5a8ba028db270835385facbd6f54cc6eab62ea998851d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint-i-dos dies hàbils.', false), ('B', 'Quinze dies naturals.', false), ('C', 'Trenta dies naturals o la part proporcional que correspongui.', true), ('D', 'Un mes i mig.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 782/2001, en quines categories es classifiquen els interns treballadors dels tallers productius?', 'L''art. 8.1 del RD 782/2001 classifica els interns treballadors en operari base i operari superior, segons el nivell de coneixements, la capacitat laboral i les funcions que exerceixen. L''operari superior també col·labora en l''organització i el desenvolupament dels tallers.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 8.1 RD 782/2001', 'a) Operario base: los que desempeñen el conjunto de tareas necesarias para el funcionamiento de los talleres productivos. […] b) Operario superior: los que, además de desempeñar las tareas necesarias para el funcionamiento de los talleres productivos, colaboran en su organización y su desarrollo.', null, 'fea91f7a56012e79ab2abac0be03f255275807450e3b32ee5dbd076b7f496a53', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fea91f7a56012e79ab2abac0be03f255275807450e3b32ee5dbd076b7f496a53')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Operari base i operari superior.', true), ('B', 'Aprenent, oficial i mestre de taller.', false), ('C', 'Peó, especialista i encarregat.', false), ('D', 'Auxiliar de taller i cap de taller.', false)) as v(label, body, ok)
)
