with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reial decret 782/2001, com es paguen les retribucions dels interns treballadors?', 'L''art. 16.1 del RD 782/2001 disposa que l''organisme ocupador paga les retribucions mitjançant un ingrés mensual al compte de peculi de l''intern.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 16.1 RD 782/2001', 'efectuará el pago de las retribuciones mediante su ingreso mensual en la cuenta de peculio del interno.', null, 'ffdb6a011b7bcc4ca0fae19ce62edd3edaf58d3470c45489345f7a66f1f29d97', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ffdb6a011b7bcc4ca0fae19ce62edd3edaf58d3470c45489345f7a66f1f29d97')
  returning id
), o as (
