)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 782/2001, quina relació laboral queda exclosa del seu àmbit d''aplicació?', 'L''art. 1.2 del RD 782/2001 exclou la relació laboral dels interns en règim obert sotmesos a contractació ordinària amb empresaris, que es regeix per la legislació laboral comuna, sens perjudici de la tutela de l''autoritat penitenciària. L''art. 1.1 sí que inclou el treball als tallers productius i les penes de treball en benefici de la comunitat.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 1.2 RD 782/2001', 'Queda excluida de su ámbito de aplicación la relación laboral de los internos en régimen abierto, sometidos a un sistema de contratación ordinaria con empresarios, que se regulará por la legislación laboral común', null, 'ffcab91b3735f5bd89fd8f168e98bd584856e1f698ac0a93973f1a2e93c5e20c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ffcab91b3735f5bd89fd8f168e98bd584856e1f698ac0a93973f1a2e93c5e20c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La dels interns en règim obert sotmesos a un sistema de contractació ordinària amb empresaris.', true), ('B', 'La dels interns que fan una activitat laboral als tallers productius dels centres penitenciaris.', false), ('C', 'La de les persones que compleixen penes de treball en benefici de la comunitat.', false), ('D', 'La dels interns preventius que treballen als tallers productius.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Reial decret 782/2001, quin descans setmanal tenen els interns treballadors amb caràcter general?', 'L''art. 17.2 del RD 782/2001 reconeix un descans setmanal d''un dia i mig ininterromput, que es gaudeix amb caràcter general la tarda del dissabte i el diumenge sencer, llevat del sistema per torns. També són dies de descans les festes laborals de la localitat on hi ha el centre.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 17.2 RD 782/2001', 'Los internos trabajadores tendrán derecho a un descanso semanal de día y medio ininterrumpido que se disfrutará, con carácter general, la tarde del sábado y el día completo del domingo', null, 'f07621bcd730fa5b196aa0b617a7ef7a78e522a64bc60c6bcbf0d30075080db4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f07621bcd730fa5b196aa0b617a7ef7a78e522a64bc60c6bcbf0d30075080db4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos dies ininterromputs, el dissabte i el diumenge.', false), ('B', 'Un dia complet, que es gaudeix el diumenge.', false), ('C', 'Un dia i mig ininterromput, que es gaudeix la tarda del dissabte i el diumenge sencer.', true), ('D', 'Un dia i mig, que es pot fraccionar segons les necessitats del taller.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Reial decret 782/2001, quins interns traslladats tenen prioritat per accedir als llocs de treball vacants del centre de destinació?', 'L''art. 14.1 del RD 782/2001 dona prioritat als interns traslladats per arrelament familiar o per altres raons que els beneficiïn si han ocupat un lloc de treball durant un període superior a un any i el centre de procedència n''ha valorat positivament l''exercici.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2001-13171'), 'Art. 14.1 RD 782/2001', 'los internos que hubiesen desempeñado un puesto de trabajo en un centro penitenciario por un período superior a un año, siempre que este desempeño haya sido valorado positivamente por el centro de procedencia, tendrán prioridad a la hora de acceder a puestos de trabajo vacantes del centro penitenciario de destino.', null, '92f17d68b715d00766fb9b2a2ee6a73bb252cf2472f8aba277f0061c78483318', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '92f17d68b715d00766fb9b2a2ee6a73bb252cf2472f8aba277f0061c78483318')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els qui hagin ocupat un lloc de treball al centre de procedència durant més de sis mesos, sigui quina sigui la valoració.', false), ('B', 'Els qui hagin ocupat un lloc de treball al centre de procedència durant més d''un any amb una valoració positiva.', true), ('C', 'Els qui hagin ocupat un lloc de treball al centre de procedència durant més de dos anys amb una valoració positiva.', false), ('D', 'Tots els interns traslladats per raons d''arrelament familiar, encara que no hagin treballat abans.', false)) as v(label, body, ok)
