with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del protocol RisCanvi, quin dels següents NO és un dels criteris de risc que avalua el sistema?', 'El RisCanvi avalua la violència (autodirigida, intrainstitucional i reincidència delictiva violenta), la reincidència general i el trencament de condemna. Les faltes disciplinàries lleus no són cap dels criteris.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'contribuint a desenvolupar un sistema integrat de valoració del risc de violència (en els seus tres formats principals: auto dirigida, intrainstitucional i reincidència delictiva violenta), d''avaluació de la reincidència general i de trencament de condemna.', null, '1efcb174363de2bc10299ef542aa7ca4eb02e5cfd11986d845ee8903bb1c4556', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1efcb174363de2bc10299ef542aa7ca4eb02e5cfd11986d845ee8903bb1c4556')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La violència autodirigida.', false), ('B', 'La violència intrainstitucional.', false), ('C', 'La comissió de faltes disciplinàries lleus.', true), ('D', 'El trencament de condemna.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el resum oficial del RisCanvi, en el criteri de reincidència violenta:', 'La reincidència violenta és el reingrés per un delicte violent fet a la comunitat (després de complir, durant un permís o abans de la llibertat definitiva) i exclou la violència dins del centre, que és el criteri de violència intrainstitucional.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'Reincidència violenta: reingrés penitenciari per un delicte violent realitzat a la comunitat, que pot haver-lo comés després de complir la condemna, durant un permís de sortida o en qualsevol altra situació de l''intern abans d''obtenir la llibertat definitiva. Exclou les conductes violentes dins del centre penitenciari.', null, '0784c057763582588cf67d6e7552ed44358e524d9df3d266a789c654c2583393', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0784c057763582588cf67d6e7552ed44358e524d9df3d266a789c654c2583393')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es considera el reingrés penitenciari per un delicte violent comès a la comunitat, i s''exclouen les conductes violentes dins del centre penitenciari.', true), ('B', 'S''inclouen les agressions lleus i greus a interns o funcionaris dins de la institució.', false), ('C', 'Només es computen els delictes violents comesos després d''obtenir la llibertat definitiva.', false), ('D', 'Es considera qualsevol nova sentència condemnatòria, encara que el delicte no sigui violent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, quines conductes defineixen el criteri de trencament de condemna?', 'El resum defineix el trencament de condemna com el no-retorn d''un permís (ordinari, de cap de setmana o extraordinari) o d''una sortida programada, l''evasió o fugida i el trencament de la confiança de les normes.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'Trencament de condemna: no retorn d''un permís (ordinari, de cap de setmana o extraordinari) o d''una sortida programada. Evasió o fugida del centre. Trencament de la confiança de les normes o regles de conducta.', null, 'ef5fb776dfb48f835790fb40c03420b1da2b5791726bfeb193af97671d95f454', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef5fb776dfb48f835790fb40c03420b1da2b5791726bfeb193af97671d95f454')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només l''evasió del centre penitenciari amb força o violència.', false), ('B', 'El no-retorn d''un permís o d''una sortida programada, l''evasió o fugida del centre i el trencament de la confiança de les normes o regles de conducta.', true), ('C', 'La comissió de qualsevol delicte durant el compliment de la condemna.', false), ('D', 'Les conductes violentes sobre interns o funcionaris dins de la institució.', false)) as v(label, body, ok)
)
