  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cada tres mesos.', false), ('B', 'Cada any.', false), ('C', 'Cada sis mesos.', true), ('D', 'Cada dos mesos.', false)) as v(label, body, ok)
)
