with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el resum oficial del RisCanvi, què s''exigeix si el resultat de l''escala RisCanvi-S és alt?', 'Segons el resum, si el RisCanvi-S dona un resultat alt, cal administrar el RisCanvi-C abans de prendre qualsevol decisió vinculant sobre la vida penitenciària de l''intern.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'Segons el resultat d''aquest protocol, en cas de resultar alt, s''exigeix administrar, abans de qualsevol decisió vinculant que afecti a la vida penitenciaria del intern, l''escala RisCanvi completa (RisCanvi C).', null, 'c05c460d44ab11df5fc3142c4f7244b4e4c49b24b645f5a68d5c8c7508c97f24', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c05c460d44ab11df5fc3142c4f7244b4e4c49b24b645f5a68d5c8c7508c97f24')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Proposar immediatament la regressió de l''intern a primer grau.', false), ('B', 'Comunicar-ho al jutge de vigilància penitenciària perquè decideixi sobre els permisos.', false), ('C', 'Repetir l''escala RisCanvi-S al cap d''un mes.', false), ('D', 'Administrar l''escala RisCanvi completa (RisCanvi-C) abans de qualsevol decisió vinculant que afecti la vida penitenciària de l''intern.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En relació amb l''escala RisCanvi completa (RisCanvi-C), segons el resum oficial del protocol, quina de les afirmacions següents NO és correcta?', 'El RisCanvi-C té 43 factors, valora els cinc criteris i en contempla les àrees criminals, personals i biogràfiques, socials i familiars, clíniques i de personalitat, però gradua el risc en tres nivells (baix, moderat i alt). Els dos nivells alt i baix són propis del RisCanvi-S.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'Igual que RisCanvi S, valora els cinc criteris anteriorment comentats. Aquesta escala està formada per 43 factors que contemplen les següents àrees: criminals, personals i biogràfics, socials i familiars, clínics i de personalitat. […] graduant-se tres nivells de risc: baix, moderat i alt.', null, '3a43f52b4ddf42d07dae2efe712e6a510083c7c7ebd17c38651d2bb22a0c0ef1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3a43f52b4ddf42d07dae2efe712e6a510083c7c7ebd17c38651d2bb22a0c0ef1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Està formada per 43 factors.', false), ('B', 'Contempla les àrees criminals, personals i biogràfiques, socials i familiars, clíniques i de personalitat.', false), ('C', 'Gradua el risc en dos nivells: alt i baix.', true), ('D', 'Valora els cinc criteris de risc del protocol.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, quina particularitat presenta el RisCanvi-C respecte del RisCanvi-S?', 'El RisCanvi-C, a diferència del RisCanvi-S, permet corregir el resultat actuarial per decisió motivada de l''equip; el risc finalment validat és el que decideix l''equip.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'RisCanvi C presenta la particularitat, a diferència de RisCanvi S, que permet fer una correcció del resultat actuarial, mitjançant una decisió d''equip degudament motivada', null, '980409b0fc9909cee96c42092e7226c447abd2f933f902b30c4cda079cbcb7ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '980409b0fc9909cee96c42092e7226c447abd2f933f902b30c4cda079cbcb7ee')
  returning id
), o as (
