  select 'Segons el resum oficial del RisCanvi, quines conductes inclou el criteri de violència autodirigida?', 'El resum oficial defineix la violència autodirigida com el suïcidi consumat, l''intent de suïcidi o les autolesions lleus i greus al centre penitenciari o durant el compliment de la condemna. Les altres opcions corresponen a la violència intrainstitucional, al trencament de condemna i a la reincidència violenta.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 4', 'Violència auto-dirigida: suïcidi consumat, intent de suïcidi o autolesions lleus i greus al CP o durant el compliment de la seva condemna', null, 'eb0c43b78e4fe6969b81deb7d229192f35350396eee9b09e3cb6cc17e0d47e76', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eb0c43b78e4fe6969b81deb7d229192f35350396eee9b09e3cb6cc17e0d47e76')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les agressions lleus i greus sobre altres interns o sobre funcionaris dins de la institució penitenciària.', false), ('B', 'El no-retorn d''un permís o d''una sortida programada.', false), ('C', 'El reingrés penitenciari per un delicte violent comès a la comunitat.', false), ('D', 'El suïcidi consumat, l''intent de suïcidi o les autolesions lleus i greus al centre penitenciari o durant el compliment de la condemna.', true)) as v(label, body, ok)
)
