with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, qui és responsable de cercar i recopilar la informació dels interns necessària per complimentar els factors de risc?', 'El resum oficial atribueix aquesta tasca a tots i cadascun dels membres de l''equip multidisciplinari (psicòlegs, juristes criminòlegs, treballadors socials, educadors i pedagogs), en funció del coneixement que tinguin del factor o de la seva especialització professional.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 2, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 5', 'Són responsables de cercar i recopilar aquesta informació relacionada amb els interns i internes, tots i cada un dels membres de l’equip multidisciplinari, en funció del coneixement que en tingui del factor en concret o de la seva especialització professional', null, '0c6ed19205697dec2e38d1683824f5f3dfa1f17661325b945c8a0f32542ab2a0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0c6ed19205697dec2e38d1683824f5f3dfa1f17661325b945c8a0f32542ab2a0')
  returning id
), o as (
