select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el resum oficial del RisCanvi, on està ubicat l''equip de suport, orientació i seguiment (SOS RisCanvi)?', 'El resum oficial indica que l''equip SOS RisCanvi resol els dubtes tècnics, metodològics i operacionals dels centres i fa el seguiment de la implementació. Està instal·lat als serveis centrals de la Subdirecció General de Programes de Rehabilitació i Sanitat i el componen personal tècnic i directiu d''aquesta subdirecció.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 5', 'L’equip està instal·lat als serveis centrals de la Subdirecció general de programes de rehabilitació i sanitat', null, 'f41822ef6f6f0fd0346c5e3d3b68e4053cfe8537073a05eae5153888d9773e10', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f41822ef6f6f0fd0346c5e3d3b68e4053cfe8537073a05eae5153888d9773e10')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Centre d''Estudis Jurídics i Formació Especialitzada.', false), ('B', 'Al Grup d''Estudis Avançats en Violència de la Universitat de Barcelona.', false), ('C', 'A la subdirecció de tractament de cada centre penitenciari.', false), ('D', 'Als serveis centrals de la Subdirecció General de Programes de Rehabilitació i Sanitat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el resum oficial del RisCanvi, quin dels següents NO és un objectiu específic del projecte?', 'Entre els objectius específics del projecte, el resum oficial esmenta destacar interns en risc amb independència del delicte, introduir tècniques de cribratge i homogeneïtzar criteris entre els professionals. El protocol orienta la presa de decisions i no substitueix els òrgans que decideixen; a més, el RisCanvi-C permet corregir el resultat actuarial per decisió motivada de l''equip.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 3, 'ca', true, (select id from public.sources where url = 'https://repositori.justicia.gencat.cat/bitstream/handle/20.500.14226/772/resum-riscanvi.pdf'), 'Resum RisCanvi, apartat 3', 'B. Destacar interns i internes en risc, amb independència del delicte comés. […] C. Introduir tècniques de cribratge (screening) i detecció del risc de forma ràpida i senzilla. […] F. Homogeneïtzar criteris entre els professionals i qualificar la seva capacitació tècnica.', null, 'c57791c8ae99d32d36a749011ef2473a32ec5e324ed7b0818e0392f1c0a0b35b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c57791c8ae99d32d36a749011ef2473a32ec5e324ed7b0818e0392f1c0a0b35b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Substituir les decisions dels òrgans col·legiats per un càlcul automàtic vinculant.', true), ('B', 'Destacar interns i internes en risc, amb independència del delicte comès.', false), ('C', 'Introduir tècniques de cribratge (screening) i detecció del risc de forma ràpida i senzilla.', false), ('D', 'Homogeneïtzar criteris entre els professionals i qualificar-ne la capacitació tècnica.', false)) as v(label, body, ok)
)
