with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la informació oficial del Departament de Justícia, des de quin any els equips dels centres penitenciaris utilitzen el RisCanvi de manera habitual?', 'Segons la pàgina oficial del Departament, l''eina és utilitzada de manera habitual pels equips dels centres penitenciaris des del 2009. El projecte té els orígens a finals del 2007 i les eines es van començar a construir el 2008.', 'pcat_e20_model_intervencio_riscanvi', (select id from public.topics where slug = 'pcat-e20-model-intervencio-riscanvi'), 1, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/ca/ambits/reinsercio_i_serveis_penitenciaris/serveis_penitenciaris/RisCanvi/'), 'RisCanvi (web del Departament de Justícia)', 'Des de 2009, l’eina és utilitzada de manera habitual pels equips dels centres penitenciaris.', null, 'c3fa677d01f9219cd96521e0a9ef565554a992f2df3883a453b0caabf50d36a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c3fa677d01f9219cd96521e0a9ef565554a992f2df3883a453b0caabf50d36a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Des del 2009.', true), ('B', 'Des del 2007.', false), ('C', 'Des del 2012.', false), ('D', 'Des del 2017.', false)) as v(label, body, ok)
)
