select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin dels drets següents NO es troba entre els que reconeix l''article 24.2 de la Constitució espanyola?', 'L''art. 24.2 CE reconeix, entre d''altres, el dret al jutge ordinari predeterminat per la llei, a un procés públic sense dilacions indegudes, a no declarar contra si mateix, a no confessar-se culpable i a la presumpció d''innocència. No reconeix un dret a ser jutjat en tot cas per un jurat.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 24.2 CE', 'todos tienen derecho al Juez ordinario predeterminado por la ley, a la defensa y a la asistencia de letrado, a ser informados de la acusación formulada contra ellos, a un proceso público sin dilaciones indebidas y con todas las garantías, a utilizar los medios de prueba pertinentes para su defensa, a no declarar contra sí mismos, a no confesarse culpables y a la presunción de inocencia.', null, 'd412576a86fca3921f3c56982d2c6bf28491d0ae5c83d35c47bb9576b9fbf5c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd412576a86fca3921f3c56982d2c6bf28491d0ae5c83d35c47bb9576b9fbf5c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret al jutge ordinari predeterminat per la llei.', false), ('B', 'El dret a ser jutjat, en tot cas, per un tribunal del jurat.', true), ('C', 'El dret a no declarar contra si mateix i a no confessar-se culpable.', false), ('D', 'El dret a un procés públic sense dilacions indegudes i amb totes les garanties.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53.1 de la Constitució espanyola, l''exercici dels drets i llibertats reconeguts al capítol segon del títol I:', 'Els drets del capítol segon del títol I vinculen tots els poders públics i el seu exercici només es pot regular per llei, que n''ha de respectar el contingut essencial; es tutelen d''acord amb l''art. 161.1.a (recurs d''inconstitucionalitat) (art. 53.1 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 53.1 CE', 'Sólo por ley, que en todo caso deberá respetar su contenido esencial, podrá regularse el ejercicio de tales derechos y libertades', null, '3f165694603ea0cee669306d9a19c50c1ae2f37d88c01769be93f4eb53dcbac7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3f165694603ea0cee669306d9a19c50c1ae2f37d88c01769be93f4eb53dcbac7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot regular per reial decret, sempre que en respecti el contingut essencial.', false), ('B', 'Només es pot regular per una llei aprovada per majoria de tres cinquenes parts del Congrés.', false), ('C', 'Es pot regular per llei o per reglament, segons el que determini el Govern.', false), ('D', 'Només es pot regular per llei, que n''ha de respectar en tot cas el contingut essencial.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53.2 de la Constitució espanyola, a més dels drets de l''article 14 i de la secció primera del capítol segon, el recurs d''empara davant el Tribunal Constitucional també és aplicable a:', 'L''art. 53.2 CE preveu la tutela de l''art. 14 i de la secció primera del capítol segon per un procediment preferent i sumari i, si escau, pel recurs d''empara, que també és aplicable a l''objecció de consciència de l''art. 30 CE.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 53.2 CE', 'Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30.', null, '0ea5e9bd16071fdca4101587c0fd27178c2211e10ecdbe4b87566155de3b77c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0ea5e9bd16071fdca4101587c0fd27178c2211e10ecdbe4b87566155de3b77c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''objecció de consciència reconeguda a l''article 30.', true), ('B', 'El dret al treball reconegut a l''article 35.', false), ('C', 'El dret de propietat privada reconegut a l''article 33.', false), ('D', 'El dret a gaudir d''un habitatge digne reconegut a l''article 47.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 53.3 de la Constitució espanyola, els principis reconeguts al capítol tercer del títol I (principis rectors de la política social i econòmica):', 'El reconeixement, el respecte i la protecció dels principis del capítol tercer informen la legislació positiva, la pràctica judicial i l''actuació dels poders públics, però només es poden al·legar davant la jurisdicció ordinària d''acord amb les lleis que els desenvolupin (art. 53.3 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 53.3 CE', 'Sólo podrán ser alegados ante la Jurisdicción ordinaria de acuerdo con lo que dispongan las leyes que los desarrollen.', null, 'b8b8698bcce2ccaf49f35a9cb4445026bcf3d9d5afbed04846420169acc81c54', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b8b8698bcce2ccaf49f35a9cb4445026bcf3d9d5afbed04846420169acc81c54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden tutelar mitjançant el recurs d''empara davant el Tribunal Constitucional.', false), ('B', 'Es poden al·legar directament davant qualsevol jutge o tribunal, sense necessitat de desplegament legal.', false), ('C', 'Només es poden al·legar davant la jurisdicció ordinària d''acord amb el que disposin les lleis que els desenvolupin.', true), ('D', 'Només es poden desenvolupar per llei orgànica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 55.1 de la Constitució espanyola, quin dels drets següents NO es pot suspendre quan s''acorda la declaració de l''estat d''excepció o de setge?', 'L''art. 55.1 CE permet suspendre, en l''estat d''excepció o de setge, els drets dels arts. 17, 18.2 i 18.3, 19, 20.1.a i d i 20.5, 21, 28.2 i 37.2. L''art. 24 no hi figura.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 55.1 CE', 'Los derechos reconocidos en los artículos 17, 18, apartados 2 y 3, artículos 19, 20, apartados 1, a) y d), y 5, artículos 21, 28, apartado 2, y artículo 37, apartado 2, podrán ser suspendidos cuando se acuerde la declaración del estado de excepción o de sitio en los términos previstos en la Constitución.', null, '2fbd0e09a5ab0ea6b033a41273e616abde6dc0d57f781fca035a0e09809ae158', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2fbd0e09a5ab0ea6b033a41273e616abde6dc0d57f781fca035a0e09809ae158')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El dret a escollir lliurement la residència i a circular pel territori nacional de l''article 19.', false), ('B', 'El dret a la tutela judicial efectiva de l''article 24.', true), ('C', 'El dret de reunió de l''article 21.', false), ('D', 'La inviolabilitat del domicili de l''article 18.2.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 de la Constitució espanyola, el Defensor del Poble és:', 'L''art. 54 CE remet a una llei orgànica la regulació del Defensor del Poble com a alt comissionat de les Corts Generals, designat per aquestes per defensar els drets del títol I; pot supervisar l''activitat de l''Administració i en dona compte a les Corts.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 54 CE', 'Una ley orgánica regulará la institución del Defensor del Pueblo, como alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título', null, '1fddabed966559fba5b3f6d82c5666291a89862bd694a2d2dd060c7b4affa983', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1fddabed966559fba5b3f6d82c5666291a89862bd694a2d2dd060c7b4affa983')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un òrgan del Govern encarregat de supervisar l''activitat de l''Administració.', false), ('B', 'Un alt comissionat de les Corts Generals, designat per aquestes per a la defensa dels drets del títol I.', true), ('C', 'Un alt comissionat del Consell General del Poder Judicial per a la defensa dels drets fonamentals.', false), ('D', 'Un òrgan del Tribunal Constitucional encarregat de tramitar els recursos d''empara.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 159.1 de la Constitució espanyola, quants dels membres del Tribunal Constitucional es nomenen a proposta del Consell General del Poder Judicial?', 'El TC té 12 membres nomenats pel Rei: quatre a proposta del Congrés i quatre del Senat (per majoria de tres cinquenes parts), dos a proposta del Govern i dos a proposta del Consell General del Poder Judicial (art. 159.1 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 159.1 CE', 'cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.', null, 'fe8805b19e05183801f91c1aa8f46c49b6c5eff6e5aa5a2c7df6bb9bf9e4b386', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fe8805b19e05183801f91c1aa8f46c49b6c5eff6e5aa5a2c7df6bb9bf9e4b386')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quatre.', false), ('B', 'Tres.', false), ('C', 'Cap: tots es nomenen a proposta de les cambres i del Govern.', false), ('D', 'Dos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 159.3 de la Constitució espanyola, per a quin període es designen els membres del Tribunal Constitucional?', 'Els magistrats del TC es designen per nou anys i el Tribunal es renova per terceres parts cada tres anys (art. 159.3 CE). El president és nomenat per tres anys (art. 160 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 159.3 CE', 'Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres.', null, 'a5b4724ab0329f67290c57c254507c5cc557680ed16964cc9afc32738837e403', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a5b4724ab0329f67290c57c254507c5cc557680ed16964cc9afc32738837e403')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per un període de dotze anys, i es renoven per meitats cada sis anys.', false), ('B', 'Per un període de sis anys, i es renoven per terceres parts cada dos anys.', false), ('C', 'Per un període de nou anys, i es renoven per terceres parts cada tres anys.', true), ('D', 'Per un període de nou anys, i es renoven íntegrament en acabar el mandat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 162.1.b de la Constitució espanyola, qui està legitimat per interposar el recurs d''empara?', 'La legitimació per al recurs d''empara correspon a tota persona natural o jurídica que invoqui un interès legítim, al Defensor del Poble i al Ministeri Fiscal (art. 162.1.b CE). La llista del president del Govern, 50 diputats i 50 senadors correspon al recurs d''inconstitucionalitat (art. 162.1.a CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 162.1.b CE', 'Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal.', null, '7c4d3789c776b563ac220ac7a5d009b85918ca8a4ee2dc4abe7147b71152e800', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c4d3789c776b563ac220ac7a5d009b85918ca8a4ee2dc4abe7147b71152e800')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tota persona natural o jurídica que invoqui un interès legítim, i també el Defensor del Poble i el Ministeri Fiscal.', true), ('B', 'Només la persona directament afectada per la vulneració i el Ministeri Fiscal.', false), ('C', 'El president del Govern, el Defensor del Poble, 50 diputats i 50 senadors.', false), ('D', 'Tota persona natural que invoqui un interès legítim i els òrgans col·legiats executius de les comunitats autònomes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
