with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 10.1 de la Constitució espanyola, què són fonament de l''ordre polític i de la pau social?', 'L''art. 10.1 CE situa com a fonament de l''ordre polític i de la pau social la dignitat de la persona, els drets inviolables inherents, el lliure desenvolupament de la personalitat i el respecte a la llei i als drets dels altres. Les altres opcions corresponen als valors superiors (art. 1.1), als arts. 1.2 i 2 i als principis de l''art. 9.3 CE.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 10.1 CE', 'La dignidad de la persona, los derechos inviolables que le son inherentes, el libre desarrollo de la personalidad, el respeto a la ley y a los derechos de los demás son fundamento del orden político y de la paz social.', null, 'cc8d1ac9321931e16c9b5557a0c702b0f16b4664a91cccc8daf9b3634dfe469c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cc8d1ac9321931e16c9b5557a0c702b0f16b4664a91cccc8daf9b3634dfe469c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La llibertat, la justícia, la igualtat i el pluralisme polític.', false), ('B', 'La sobirania nacional, la unitat de la nació espanyola i l''autonomia de les nacionalitats i regions.', false), ('C', 'La dignitat de la persona, els drets inviolables que li són inherents, el lliure desenvolupament de la personalitat, el respecte a la llei i als drets dels altres.', true), ('D', 'La seguretat jurídica, la responsabilitat i la interdicció de l''arbitrarietat dels poders públics.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
