with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 de la Constitució espanyola, la pena de mort:', 'L''art. 15 CE reconeix el dret a la vida i a la integritat física i moral, prohibeix la tortura i les penes o tractes inhumans o degradants i declara abolida la pena de mort, llevat del que puguin disposar les lleis penals militars per a temps de guerra.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 15 CE', 'Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra.', null, 'e606ed2c029509846cced5a2182ece0892a3a286502dab7fbcba1686d6607959', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e606ed2c029509846cced5a2182ece0892a3a286502dab7fbcba1686d6607959')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Queda abolida en tots els casos, sense cap excepció.', false), ('B', 'Queda abolida, llevat del que puguin disposar les lleis penals militars per a temps de guerra.', true), ('C', 'Només es pot imposar per delictes de terrorisme, en virtut de llei orgànica.', false), ('D', 'Queda abolida, llevat del que disposin les lleis aprovades durant l''estat de setge.', false)) as v(label, body, ok)
)
