with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les circumstàncies següents NO s''esmenta expressament a l''article 14 de la Constitució espanyola com a motiu de discriminació prohibit?', 'L''art. 14 CE esmenta expressament el naixement, la raça, el sexe, la religió i l''opinió, i afegeix una clàusula oberta («qualsevol altra condició o circumstància personal o social»). L''edat no s''hi esmenta expressament.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 14 CE', 'Los españoles son iguales ante la ley, sin que pueda prevalecer discriminación alguna por razón de nacimiento, raza, sexo, religión, opinión o cualquier otra condición o circunstancia personal o social.', null, '8619310e9ca81bc01cae5d00d945df4eb366e673f389a659ab4ed1e2da110b35', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8619310e9ca81bc01cae5d00d945df4eb366e673f389a659ab4ed1e2da110b35')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El naixement.', false), ('B', 'La religió.', false), ('C', 'L''opinió.', false), ('D', 'L''edat.', true)) as v(label, body, ok)
)
