with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 17.3 de la Constitució espanyola, tota persona detinguda:', 'L''art. 17.3 CE exigeix informar el detingut de forma immediata i comprensible dels seus drets i de les raons de la detenció, no el pot obligar a declarar i li garanteix l''assistència d''advocat en les diligències policials i judicials.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 17.3 CE', 'Toda persona detenida debe ser informada de forma inmediata, y de modo que le sea comprensible, de sus derechos y de las razones de su detención, no pudiendo ser obligada a declarar.', null, 'dd50645391ea2264470e896b5cadcac66cbabe2964c9a5a257a12627402865cb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dd50645391ea2264470e896b5cadcac66cbabe2964c9a5a257a12627402865cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
