with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 20 de la Constitució espanyola, el segrest de publicacions, enregistraments i altres mitjans d''informació:', 'L''exercici de les llibertats de l''art. 20 no es pot restringir amb cap tipus de censura prèvia (art. 20.2 CE) i el segrest de publicacions, enregistraments i altres mitjans d''informació només es pot acordar per resolució judicial (art. 20.5 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 20.2 i 20.5 CE', 'Sólo podrá acordarse el secuestro de publicaciones, grabaciones y otros medios de información en virtud de resolución judicial.', null, '03520a063bd846566f7e55c850cbd3af86fd0ddba94d79d539e167c4c224849e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03520a063bd846566f7e55c850cbd3af86fd0ddba94d79d539e167c4c224849e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només es pot acordar en virtut de resolució judicial.', true), ('B', 'Es pot acordar per l''autoritat governativa en cas d''urgència, amb ratificació judicial posterior.', false), ('C', 'Es pot acordar mitjançant censura prèvia si afecta la protecció de la joventut i de la infància.', false), ('D', 'Es pot acordar pel Govern mitjançant decret, donant-ne compte al Congrés.', false)) as v(label, body, ok)
)
