with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa al dret d''associació de l''article 22 de la Constitució espanyola, quina de les afirmacions següents NO és correcta?', 'Les associacions només poden ser dissoltes o suspeses en les seves activitats en virtut de resolució judicial motivada (art. 22.4 CE), no per resolució governativa. Les altres afirmacions reprodueixen els apartats 2, 3 i 5 de l''art. 22.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 22 CE', 'Las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada.', null, '1dfc0fc190b81e1af8522be67184df49ece3ba1736191ecbbad301cd8a96d512', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1dfc0fc190b81e1af8522be67184df49ece3ba1736191ecbbad301cd8a96d512')
  returning id
