with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 116.2 de la Constitució espanyola, l''estat d''alarma:', 'L''estat d''alarma el declara el Govern per decret acordat en Consell de Ministres per un màxim de quinze dies, donant-ne compte al Congrés, que n''ha d''autoritzar la pròrroga (art. 116.2 CE). L''autorització prèvia i els trenta dies corresponen a l''estat d''excepció (art. 116.3) i la declaració per majoria absoluta del Congrés, a l''estat de setge (art. 116.4).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 116.2 CE', 'El estado de alarma será declarado por el Gobierno mediante decreto acordado en Consejo de Ministros por un plazo máximo de quince días, dando cuenta al Congreso de los Diputados, reunido inmediatamente al efecto y sin cuya autorización no podrá ser prorrogado dicho plazo.', null, 'e6be896b69461c7e9433727f86d3e98225fe9b0b85a76cbe372f12157477c8f4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e6be896b69461c7e9433727f86d3e98225fe9b0b85a76cbe372f12157477c8f4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El declara el Congrés dels Diputats per majoria absoluta, a proposta exclusiva del Govern.', false), ('B', 'El declara el Govern, amb l''autorització prèvia del Congrés, per un termini màxim de trenta dies, prorrogable per un altre termini igual.', false), ('C', 'El declara el Govern per un termini màxim de quinze dies, prorrogable per decisió del mateix Govern.', false), ('D', 'El declara el Govern mitjançant decret acordat en Consell de Ministres per un termini màxim de quinze dies, donant-ne compte al Congrés dels Diputats, sense l''autorització del qual no es pot prorrogar.', true)) as v(label, body, ok)
)
