  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 26 de la Constitució espanyola, en l''àmbit de l''Administració civil i de les organitzacions professionals es prohibeixen:', 'L''art. 26 CE prohibeix els tribunals d''honor en l''àmbit de l''Administració civil i de les organitzacions professionals. La prohibició dels tribunals d''excepció es troba a l''art. 117.6 CE i els tribunals consuetudinaris i tradicionals es reconeixen a l''art. 125 CE.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 26 CE', 'Se prohíben los Tribunales de Honor en el ámbito de la Administración civil y de las organizaciones profesionales.', null, '1d0e32e2ab08ae76175d95206df18550b66fbafe32c5af2104e613cc9eed0034', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1d0e32e2ab08ae76175d95206df18550b66fbafe32c5af2104e613cc9eed0034')
