with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 29 de la Constitució espanyola, els membres de les forces o instituts armats o dels cossos sotmesos a disciplina militar poden exercir el dret de petició:', 'Tots els espanyols tenen el dret de petició individual i col·lectiva, per escrit (art. 29.1 CE); els membres de les forces o instituts armats i dels cossos sotmesos a disciplina militar només el poden exercir individualment i d''acord amb la seva legislació específica (art. 29.2 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 29.2 CE', 'Los miembros de las Fuerzas o Institutos armados o de los Cuerpos sometidos a disciplina militar podrán ejercer este derecho sólo individualmente y con arreglo a lo dispuesto en su legislación específica.', null, 'd08eb2b825d2f671b9ee6ac370b133072c639be401a5caab4503583de4a1a206', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd08eb2b825d2f671b9ee6ac370b133072c639be401a5caab4503583de4a1a206')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Individualment i col·lectivament, en les mateixes condicions que la resta d''espanyols.', false), ('B', 'Només col·lectivament, a través dels seus òrgans de representació.', false), ('C', 'No el poden exercir mentre estan en servei actiu.', false), ('D', 'Només individualment i d''acord amb el que disposa la seva legislació específica.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
