with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa als estats d''excepció i de setge de l''article 116 de la Constitució espanyola, quina de les afirmacions següents NO és correcta?', 'L''estat d''excepció el declara el Govern amb autorització prèvia del Congrés i per un màxim de trenta dies prorrogables per un altre termini igual (art. 116.3 CE); l''estat de setge el declara la majoria absoluta del Congrés, a proposta exclusiva del Govern, i el Congrés en determina l''àmbit, la durada i les condicions (art. 116.4 CE).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 116.3 i 116.4 CE', 'El estado de sitio será declarado por la mayoría absoluta del Congreso de los Diputados, a propuesta exclusiva del Gobierno.', null, '8f0181079147c573c486476893fc0f6b1f1fa3c9258bd35bfc8e5faac518ab55', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8f0181079147c573c486476893fc0f6b1f1fa3c9258bd35bfc8e5faac518ab55')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''estat d''excepció el declara el Govern mitjançant decret acordat en Consell de Ministres, amb l''autorització prèvia del Congrés dels Diputats.', false), ('B', 'La durada de l''estat d''excepció no pot excedir de trenta dies, prorrogables per un altre termini igual, amb els mateixos requisits.', false), ('C', 'L''estat de setge el declara el Govern mitjançant decret, amb l''autorització prèvia del Congrés per majoria simple.', true), ('D', 'L''estat de setge el declara el Congrés dels Diputats per majoria absoluta, a proposta exclusiva del Govern.', false)) as v(label, body, ok)
)
