with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 6 de l''Estatut d''autonomia de Catalunya, quines llengües són oficials a Catalunya?', 'El català és la llengua oficial de Catalunya i també ho és el castellà (art. 6.2 EAC). L''occità, anomenat aranès a l''Aran, és la llengua pròpia d''aquest territori i és oficial a Catalunya (art. 6.5 EAC).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 6.2 i 6.5 EAC', 'El catalán es la lengua oficial de Cataluña. También lo es el castellano, que es la lengua oficial del Estado español. […] La lengua occitana, denominada aranés en Arán, es la lengua propia de este territorio y es oficial en Cataluña', null, '1074685d3155f687d8e271026d54e2b68535827a0f6203ab3301f5da4e053deb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1074685d3155f687d8e271026d54e2b68535827a0f6203ab3301f5da4e053deb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només el català, que és la llengua pròpia de Catalunya.', false), ('B', 'El català, el castellà i l''occità, anomenat aranès a l''Aran.', true), ('C', 'El català i el castellà; l''occità només és oficial a l''Aran.', false), ('D', 'El català i el castellà; l''occità és llengua pròpia de l''Aran, però no és oficial.', false)) as v(label, body, ok)
)
