with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2.2 de l''Estatut d''autonomia de Catalunya, la Generalitat està integrada per:', 'La Generalitat és el sistema institucional en què s''organitza políticament l''autogovern de Catalunya i està integrada pel Parlament, la Presidència, el Govern i les altres institucions del capítol V del títol II (art. 2.1 i 2.2 EAC). Els municipis, les vegueries i les comarques també integren el sistema institucional, com a ens en què s''organitza territorialment (art. 2.3).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 2.2 EAC', 'La Generalitat está integrada por el Parlamento, la Presidencia de la Generalitat, el Gobierno y las demás instituciones que establece el Capítulo V, del Título II.', null, 'ab15aef5886bc9ae7ec0e3710ea0b910eeface645723883d48ace10b14645b82', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ab15aef5886bc9ae7ec0e3710ea0b910eeface645723883d48ace10b14645b82')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Parlament, el Govern i el Tribunal Superior de Justícia de Catalunya.', false), ('B', 'El Parlament, la Presidència de la Generalitat, el Govern i les altres institucions que estableix el capítol V del títol II.', true), ('C', 'El Govern, els departaments i els ens locals de Catalunya.', false), ('D', 'El Parlament, la Presidència de la Generalitat i el Consell de Garanties Estatutàries, exclusivament.', false)) as v(label, body, ok)
)
