with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 7.1 de l''Estatut d''autonomia de Catalunya, gaudeixen de la condició política de catalans o ciutadans de Catalunya:', 'La condició política de catalans correspon als ciutadans espanyols amb veïnatge administratiu a Catalunya (art. 7.1 EAC). També en gaudeixen, si ho sol·liciten, els espanyols residents a l''estranger que hi han tingut l''últim veïnatge administratiu i els seus descendents (art. 7.2).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 7.1 EAC', 'Gozan de la condición política de catalanes o ciudadanos de Cataluña los ciudadanos españoles que tienen vecindad administrativa en Cataluña.', null, 'a76484ea5240d25953ee13663b720bba2c354d99dc850c4075790ff02fb836e6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a76484ea5240d25953ee13663b720bba2c354d99dc850c4075790ff02fb836e6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Totes les persones, de qualsevol nacionalitat, que resideixen a Catalunya.', false), ('B', 'Els ciutadans espanyols nascuts a Catalunya, amb independència d''on resideixin.', false), ('C', 'Els ciutadans de la Unió Europea que tenen veïnatge administratiu a Catalunya.', false), ('D', 'Els ciutadans espanyols que tenen veïnatge administratiu a Catalunya.', true)) as v(label, body, ok)
