with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 4.3 de l''Estatut d''autonomia de Catalunya, quin dels valors següents NO és dels que han de promoure els poders públics de Catalunya?', 'L''art. 4.3 EAC obliga els poders públics de Catalunya a promoure els valors de la llibertat, la democràcia, la igualtat, el pluralisme, la pau, la justícia, la solidaritat, la cohesió social, l''equitat de gènere i el desenvolupament sostenible. La seguretat jurídica és un principi de l''art. 9.3 CE, però no figura en aquesta llista.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 4.3 EAC', 'Los poderes públicos de Cataluña deben promover los valores de la libertad, la democracia, la igualdad, el pluralismo, la paz, la justicia, la solidaridad, la cohesión social, la equidad de género y el desarrollo sostenible.', null, 'ce75ee977a1ce87a7b122324ce12b085e3f62086d51217cb61242a7835d1543d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ce75ee977a1ce87a7b122324ce12b085e3f62086d51217cb61242a7835d1543d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La cohesió social.', false), ('B', 'La seguretat jurídica.', true), ('C', 'L''equitat de gènere.', false), ('D', 'El desenvolupament sostenible.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
