with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 64 de l''Estatut d''autonomia de Catalunya, els decrets llei dictats pel Govern queden derogats si el Parlament no els convalida expressament, després d''un debat i una votació de totalitat, en el termini improrrogable de:', 'Els decrets llei queden derogats si en el termini improrrogable de trenta dies subsegüents a la promulgació no són convalidats expressament pel Parlament després d''un debat i una votació de totalitat (art. 64.2 EAC). Dins aquest termini, el Parlament els pot tramitar com a projectes de llei pel procediment d''urgència (art. 64.3).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 64.2 EAC', 'Los Decretos-leyes quedan derogados si en el plazo improrrogable de treinta días subsiguientes a la promulgación no son validados expresamente por el Parlamento después de un debate y una votación de totalidad.', null, '53c2b271b923afba2d631c13121b979f1d38d7529fce3955572f6b06f9c6fb8d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '53c2b271b923afba2d631c13121b979f1d38d7529fce3955572f6b06f9c6fb8d')
  returning id
), o as (
