with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 113 de l''Estatut d''autonomia de Catalunya, quan la normativa de la Unió Europea afecta l''àmbit de les competències de la Generalitat, correspon a la Generalitat:', 'L''art. 113 EAC atribueix a la Generalitat el desplegament, l''aplicació i l''execució de la normativa de la Unió Europea quan afecti l''àmbit de les seves competències, en els termes del títol V.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 113 EAC', 'Corresponde a la Generalitat el desarrollo, la aplicación y la ejecución de la normativa de la Unión Europea cuando afecte al ámbito de sus competencias, en los términos que establece el Título V.', null, '8269d0ebf63a2cbad97bf9a60ca2582b1d503fb05fa2b5d85837e1b1467875d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8269d0ebf63a2cbad97bf9a60ca2582b1d503fb05fa2b5d85837e1b1467875d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El desplegament, l''aplicació i l''execució d''aquesta normativa, en els termes que estableix el títol V.', true), ('B', 'Només l''execució d''aquesta normativa, un cop l''Estat n''hagi dictat la legislació bàsica.', false), ('C', 'La transposició de les directives, però no l''aplicació dels reglaments, que correspon a l''Estat.', false), ('D', 'Cap funció: l''aplicació del dret de la Unió Europea correspon exclusivament a l''Estat.', false)) as v(label, body, ok)
)
