with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, si el candidat o candidata a la presidència de la Generalitat no obté la majoria absoluta en la primera votació d''investidura:', 'En la primera votació cal la majoria absoluta; si no s''obté, el candidat es pot sotmetre dos dies després a un segon debat i una segona votació, en què n''hi ha prou amb la majoria simple (art. 4.4 i 4.5 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 4.4 i 4.5 Llei 13/2008', 'Si el candidato o candidata no consigue la mayoría absoluta, puede someterse, dos días después, a un segundo debate y a una segunda votación, en la que bastará la mayoría simple.', null, '56030cbf1a0881bd7f4d5631d099dd659d600009618c7c71128850139ee20b4e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '56030cbf1a0881bd7f4d5631d099dd659d600009618c7c71128850139ee20b4e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot sotmetre, deu dies després, a una segona votació, en què també cal la majoria absoluta.', false), ('B', 'Es pot sotmetre, dos dies després, a una segona votació, en què n''hi ha prou amb la majoria simple.', true), ('C', 'El president o presidenta del Parlament ha de proposar immediatament un altre candidat.', false), ('D', 'La legislatura queda dissolta automàticament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 6.3 de la Llei 13/2008, quina de les atribucions següents NO pot exercir la persona que supleix o substitueix el president o presidenta de la Generalitat?', 'Ni la suplència ni la substitució permeten exercir les atribucions relatives al plantejament d''una qüestió de confiança, a la designació i el cessament dels consellers ni a la dissolució anticipada de la legislatura (art. 6.3 Llei 13/2008; art. 67.8 EAC).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 6.3 Llei 13/2008', 'Ni la suplencia ni la sustitución del presidente o presidenta de la Generalidad permiten ejercer las atribuciones del cargo relativas al planteamiento de una cuestión de confianza, a la designación y el cese de los consejeros o a la disolución anticipada de la legislatura.', null, '11d720103e7433b326ec80ce94feccd74659a58f4486f84950ede3eb356c5756', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11d720103e7433b326ec80ce94feccd74659a58f4486f84950ede3eb356c5756')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Plantejar una qüestió de confiança.', true), ('B', 'Convocar i presidir les reunions del Govern.', false), ('C', 'Representar el Govern.', false), ('D', 'Resoldre els conflictes d''atribucions entre consellers.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, qui pot proposar una moció de censura contra el president o presidenta de la Generalitat?', 'La moció de censura l''ha de proposar com a mínim una cinquena part dels diputats o dos grups parlamentaris, i ha d''incloure un candidat a la presidència que hagi acceptat la candidatura. S''aprova si la voten afirmativament la majoria absoluta dels diputats (art. 43.1 i 43.5 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 43.1 i 43.5 Llei 13/2008', 'La moción de censura debe ser propuesta como mínimo por una quinta parte de los diputados o por dos grupos parlamentarios y debe incluir un candidato o candidata a la presidencia de la Generalidad, que debe haber aceptado la candidatura.', null, 'b7b1180126c52a548f91d5533ef1072c6e51ad41744341996fee6bfa6ab6e422', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b7b1180126c52a548f91d5533ef1072c6e51ad41744341996fee6bfa6ab6e422')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com a mínim una desena part dels diputats o un grup parlamentari.', false), ('B', 'Com a mínim una cinquena part dels diputats o dos grups parlamentaris.', true), ('C', 'Com a mínim una tercera part dels diputats o tres grups parlamentaris.', false), ('D', 'La majoria absoluta dels diputats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, quan el Govern es troba en funcions:', 'El Govern en funcions limita la seva actuació al despatx ordinari dels assumptes públics, incloent-hi la potestat reglamentària (art. 27.1); no pot aprovar el projecte de pressupostos, presentar projectes de llei ni dictar decrets legislatius (art. 27.2), però sí decrets llei (art. 27.3). A més, la delegació legislativa caduca quan el Govern és en funcions (art. 37.6).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 27.2 Llei 13/2008', 'El Gobierno, cuando se halla en funciones, no puede aprobar el proyecto de ley de presupuestos de la Generalidad, ni presentar proyectos de ley al Parlamento, ni dictar decretos legislativos.', null, '235b1b046194ec625be8473d1909f6a75fc3164f2c4ff7e0991ccfe798641b3c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '235b1b046194ec625be8473d1909f6a75fc3164f2c4ff7e0991ccfe798641b3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No pot dictar decrets llei en cap cas.', false), ('B', 'No pot exercir la potestat reglamentària, ni tan sols per al despatx ordinari dels assumptes públics.', false), ('C', 'No pot aprovar el projecte de llei de pressupostos, ni presentar projectes de llei al Parlament, ni dictar decrets legislatius.', true), ('D', 'Pot dictar decrets legislatius si la delegació legislativa s''havia fet abans que entrés en funcions.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, de la presidència de la Generalitat i del Govern, quin tractament rep el president o presidenta de la Generalitat?', 'El president o presidenta rep el tractament de molt honorable i té dret a utilitzar com a distintius la bandera de Catalunya i l''escut de la Generalitat (art. 8.1 Llei 13/2008). Els consellers reben el tractament d''honorable (art. 19.1).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 8.1 Llei 13/2008', 'El presidente o presidenta de la Generalidad recibe el tratamiento de muy honorable señor o muy honorable señora', null, 'e2ac79a3ef93c130634d3db9fc2f45d14ed2a6c560d45ec51a67ad19ee761645', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e2ac79a3ef93c130634d3db9fc2f45d14ed2a6c560d45ec51a67ad19ee761645')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Molt honorable senyor o molt honorable senyora.', true), ('B', 'Honorable senyor o honorable senyora.', false), ('C', 'Excel·lentíssim senyor o excel·lentíssima senyora.', false), ('D', 'Il·lustríssim senyor o il·lustríssima senyora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, com s''adopten les decisions del Govern?', 'Les decisions del Govern s''adopten per majoria simple i, en cas d''empat, el vot del president o presidenta és diriment. Han de constar en una acta que estén el secretari o secretària del Govern (art. 29 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 29.1 Llei 13/2008', 'Las decisiones del Gobierno se adoptan por mayoría simple. En caso de empate, el voto del presidente o presidenta de la Generalidad es dirimente.', null, 'a22a9b96569a25795f937e3c452070b65fd19b26b1478f33f65a913364ae2340', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a22a9b96569a25795f937e3c452070b65fd19b26b1478f33f65a913364ae2340')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per majoria absoluta dels seus membres; en cas d''empat, es repeteix la votació.', false), ('B', 'Per unanimitat dels membres presents.', false), ('C', 'Per majoria simple; en cas d''empat, el vot del president o presidenta de la Generalitat és diriment.', true), ('D', 'Per majoria de dues terceres parts; en cas d''empat, decideix el conseller primer.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, el nomenament del president o presidenta de la Generalitat té efectes a partir de la presa de possessió, que s''ha de fer en el termini de:', 'El nomenament es publica al DOGC i té efectes a partir de la presa de possessió, que s''ha de fer en el termini de cinc dies a partir del nomenament (art. 5.2 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 5.2 Llei 13/2008', 'tiene efectos a partir de la toma de posesión, que debe celebrarse en el plazo de cinco días a partir del nombramiento.', null, 'e10ac89aa58d6a977d143007f81fdacf0bfc2516bbea70569ecdb0a1cdb7ac11', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e10ac89aa58d6a977d143007f81fdacf0bfc2516bbea70569ecdb0a1cdb7ac11')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies a partir del nomenament.', false), ('B', 'Dos dies a partir de la investidura.', false), ('C', 'Quinze dies a partir de la publicació al Diari Oficial de la Generalitat de Catalunya.', false), ('D', 'Cinc dies a partir del nomenament.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, perquè les deliberacions i les decisions del Govern siguin vàlides cal que hi siguin presents:', 'El Govern es reuneix convocat pel president o presidenta, amb l''ordre del dia (art. 28.1), i per a la validesa de les deliberacions i les decisions cal la presència del president o presidenta, o de qui el supleixi, i almenys de la meitat dels consellers (art. 28.2 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 28.2 Llei 13/2008', 'Para que las deliberaciones y decisiones del Gobierno sean válidas, es preciso que estén presentes el presidente o presidenta de la Generalidad, o quien lo supla, y por lo menos la mitad de los consejeros.', null, '6d615c5c6627499abec0c507a151df444ec21151fb33edebbe075766045937c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6d615c5c6627499abec0c507a151df444ec21151fb33edebbe075766045937c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El president o presidenta de la Generalitat, o qui el supleixi, i almenys la meitat dels consellers.', true), ('B', 'El president o presidenta de la Generalitat i la majoria absoluta dels consellers, sense possibilitat de suplència.', false), ('C', 'Almenys dues terceres parts dels membres del Govern.', false), ('D', 'El president o presidenta, el conseller primer o el vicepresident i el secretari o secretària del Govern.', false)) as v(label, body, ok)
)
