select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, en la qüestió de confiança plantejada pel president o presidenta de la Generalitat:', 'La votació de la qüestió de confiança no es pot fer abans que hagin transcorregut com a mínim vint-i-quatre hores des de la presentació, i la confiança s''entén atorgada si s''obté la majoria simple dels vots emesos (art. 44.2 i 44.3 Llei 13/2008). Si es denega, el president cessa i el Parlament n''ha d''elegir un de nou.', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 44.2 i 44.3 Llei 13/2008', 'la votación no puede celebrarse antes de que hayan transcurrido veinticuatro horas, como mínimo, desde la presentación de la cuestión de confianza. […] Si en la votación de una cuestión de confianza el presidente o presidenta de la Generalidad obtiene la mayoría simple de los votos emitidos, se entiende que le ha sido otorgada la confianza.', null, 'b5874e9fa7afb069d5d9d50fafff173b8111ec39bf884c62d1246544e134c596', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b5874e9fa7afb069d5d9d50fafff173b8111ec39bf884c62d1246544e134c596')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La votació no es pot fer abans de cinc dies des de la presentació, i la confiança requereix la majoria absoluta dels diputats.', false), ('B', 'La votació s''ha de fer immediatament després del debat, i la confiança requereix la majoria absoluta dels diputats.', false), ('C', 'La votació no es pot fer abans de vint-i-quatre hores des de la presentació, i la confiança s''entén atorgada si s''obté la majoria simple dels vots emesos.', true), ('D', 'La votació no es pot fer abans de quaranta-vuit hores des de la presentació, i la confiança requereix la majoria de dues terceres parts.', false)) as v(label, body, ok)
)
