with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, el president o presidenta de la Generalitat cessa per incapacitat permanent, física o mental, que l''inhabiliti per a l''exercici del càrrec, la qual:', 'L''art. 7.1.d de la Llei 13/2008 exigeix que la incapacitat permanent la sol·liciti la majoria absoluta dels diputats i la reconegui una majoria de dues terceres parts. En aquest cas, el president és substituït interinament (art. 7.3 i 6.2).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 7.1.d Llei 13/2008', 'Por incapacidad permanente, física o mental, que lo inhabilite para el ejercicio del cargo, que debe ser solicitada por la mayoría absoluta de los diputados y reconocida por una mayoría de dos tercios.', null, '71fe51aa6239f8c19d22417a0871735ea784df69e40c796d19ec62c0ead6b886', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71fe51aa6239f8c19d22417a0871735ea784df69e40c796d19ec62c0ead6b886')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''ha de sol·licitar la majoria absoluta dels diputats i l''ha de reconèixer una majoria de dues terceres parts.', true), ('B', 'L''ha de sol·licitar una cinquena part dels diputats i l''ha de reconèixer la majoria absoluta.', false), ('C', 'L''ha de declarar el Tribunal Superior de Justícia de Catalunya a instància del Govern.', false), ('D', 'L''ha d''apreciar el Govern per majoria absoluta, i se n''ha de donar compte al Parlament.', false)) as v(label, body, ok)
)
