with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, quina de les afirmacions següents sobre la moció de censura és correcta?', 'El debat se substancia als cinc dies de la presentació (art. 43.3), els signants la poden retirar en qualsevol moment (art. 43.4) i no se''n pot presentar cap en el mateix període de sessions en què ja se n''ha debatut una; els signants d''una moció rebutjada o retirada no en poden presentar cap més durant el període de sessions següent (art. 43.7 Llei 13/2008).', 'pcat_g1_marc_constitucional_estatut', (select id from public.topics where slug = 'pcat-g1-marc-constitucional-estatut'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 43.3 i 43.7 Llei 13/2008', 'No puede presentarse ninguna moción de censura en el mismo período de sesiones en que ya se ha debatido una.', null, '96d39bb7e1afc3d8a5ebf6967461015390a0f9db0617e291c4ec2187a37cab58', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '96d39bb7e1afc3d8a5ebf6967461015390a0f9db0617e291c4ec2187a37cab58')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El debat s''ha de convocar perquè se substanciï als deu dies d''haver-se presentat la moció.', false), ('B', 'No se''n pot presentar cap en el mateix període de sessions en què ja se n''ha debatut una.', true), ('C', 'Els signants no la poden retirar un cop la presidència del Parlament l''ha comunicada a la presidència de la Generalitat.', false), ('D', 'Els signants d''una moció rebutjada no en poden presentar cap altra durant la resta de la legislatura.', false)) as v(label, body, ok)
)
