-- Lote pcat-g2-organitzacio-generalitat-eac-v1 (5 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/2006, de 19 de julio, de reforma del Estatuto de Autonomía de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g2-organitzacio-generalitat', 'Part general. Tema 2. Organització de l''Administració de la Generalitat i departaments') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g2-organitzacio-generalitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 71.2 de l''Estatut d''autonomia de Catalunya, l''Administració de la Generalitat:', 'L''art. 71.2 EAC disposa que l''Administració de la Generalitat serveix amb objectivitat els interessos generals i actua amb submissió plena a les lleis i al dret.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.2 EAC', 'La Administración de la Generalitat sirve con objetividad los intereses generales y actúa con sumisión plena a las leyes y al derecho.', null, 'a20c3dcd20c6e3506359d8f5d8607cdd857592e59da3041c5d3608a832ab970a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a20c3dcd20c6e3506359d8f5d8607cdd857592e59da3041c5d3608a832ab970a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Serveix els interessos generals d''acord amb les directrius del partit que dona suport al Govern.', false), ('B', 'Actua amb submissió plena a les instruccions del president o presidenta de la Generalitat.', false), ('C', 'Serveix amb objectivitat els interessos de les persones interessades en cada procediment.', false), ('D', 'Serveix amb objectivitat els interessos generals i actua amb submissió plena a les lleis i al dret.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71.5 de l''Estatut d''autonomia de Catalunya, l''Administració de la Generalitat exerceix les seves funcions en el territori d''acord amb els principis de:', 'Al territori, l''Administració de la Generalitat actua d''acord amb els principis de desconcentració i descentralització (art. 71.5 EAC). Els principis de coordinació i transversalitat també hi apareixen, però a l''art. 71.3, per garantir la integració de les polítiques públiques.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.5 EAC', 'La Administración de la Generalitat ejerce sus funciones en el territorio de acuerdo con los principios de desconcentración y descentralización.', null, '57d628273c63d1d14099e5ee33f8220c5211c2af5b17bdd4cb610c160520c08f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '57d628273c63d1d14099e5ee33f8220c5211c2af5b17bdd4cb610c160520c08f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Jerarquia i competència.', false), ('B', 'Coordinació i transversalitat.', false), ('C', 'Desconcentració i descentralització.', true), ('D', 'Subsidiarietat i proporcionalitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 71.1 de l''Estatut d''autonomia de Catalunya, l''Administració de la Generalitat és l''organització que exerceix les funcions executives atribuïdes a la Generalitat i té la condició de:', 'L''art. 71.1 EAC defineix l''Administració de la Generalitat com l''organització que exerceix les funcions executives que l''Estatut atribueix a la Generalitat i li dona la condició d''Administració ordinària, sens perjudici de les competències de l''Administració local.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.1 EAC', 'La Administración de la Generalitat es la organización que ejerce las funciones ejecutivas atribuidas por el presente Estatuto a la Generalitat. Tiene la condición de Administración ordinaria de acuerdo con lo que establecen el presente Estatuto y las leyes, sin perjuicio de las competencias que corresponden a la Administración local.', null, '4edb33fd5237a6d2b5716670452bbea8f45e635823f03b86c06fbb01c91b535c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4edb33fd5237a6d2b5716670452bbea8f45e635823f03b86c06fbb01c91b535c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Administració perifèrica de l''Estat a Catalunya.', false), ('B', 'Administració única, que exclou les competències de l''Administració local.', false), ('C', 'Administració ordinària, sens perjudici de les competències que corresponen a l''Administració local.', true), ('D', 'Administració institucional, subordinada a l''Administració General de l''Estat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb l''article 71.3 de l''Estatut d''autonomia de Catalunya, amb la finalitat de garantir la integració de les polítiques públiques, l''Administració de la Generalitat actua d''acord amb els principis de:', 'L''art. 71.3 EAC estableix que l''Administració de la Generalitat actua d''acord amb els principis de coordinació i transversalitat per garantir la integració de les polítiques públiques. La desconcentració i la descentralització són els principis de l''exercici de les funcions en el territori (art. 71.5).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 71.3 EAC', 'La Administración de la Generalitat actúa de acuerdo con los principios de coordinación y transversalidad, con el fin de garantizar la integración de las políticas públicas.', null, '777a6278d94e5d255d1b85cda8d870ca44e418da657370759c2a17bb310f10ab', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '777a6278d94e5d255d1b85cda8d870ca44e418da657370759c2a17bb310f10ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Desconcentració i descentralització.', false), ('B', 'Coordinació i transversalitat.', true), ('C', 'Jerarquia i competència.', false), ('D', 'Lleialtat institucional i bilateralitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 72 de l''Estatut d''autonomia de Catalunya, quin és l''alt òrgan consultiu del Govern?', 'La Comissió Jurídica Assessora és l''alt òrgan consultiu del Govern (art. 72.1 EAC). El Consell de Treball, Econòmic i Social és l''òrgan consultiu i d''assessorament del Govern en matèries socioeconòmiques, laborals i ocupacionals (art. 72.2).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-13087'), 'Art. 72.1 EAC', 'La Comisión Jurídica Asesora es el alto órgano consultivo del Gobierno.', null, '7dfffa6e125fc02b64102e39924ed38236b42e3e241f111bf39dca1a6e7b271b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7dfffa6e125fc02b64102e39924ed38236b42e3e241f111bf39dca1a6e7b271b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consell de Garanties Estatutàries.', false), ('B', 'El Consell de Treball, Econòmic i Social de Catalunya.', false), ('C', 'La Sindicatura de Comptes.', false), ('D', 'La Comissió Jurídica Assessora.', true)) as v(label, body, ok)
)
