-- Lote pcat-g2-organitzacio-generalitat-lpres-v1 (15 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 13/2008, de 5 de noviembre, de la presidencia de la Generalidad y del Gobierno (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g2-organitzacio-generalitat', 'Part general. Tema 2. Organització de l''Administració de la Generalitat i departaments') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g2-organitzacio-generalitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, de la presidència de la Generalitat i del Govern, a qui correspon, amb caràcter general, la direcció superior de cada departament?', 'El Govern s''organitza en departaments, que integren l''Administració de la Generalitat, i la direcció superior de cada departament correspon a un conseller o consellera, sens perjudici de les excepcions dels arts. 12.1.n i 15.2 (art. 23.1 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 23.1 Llei 13/2008', 'El Gobierno se organiza en departamentos, que integran la Administración de la Generalidad. Sin perjuicio de lo que disponen los artículos 12.1.n) y 15.2, la dirección superior de cada departamento corresponde a un consejero o consejera.', null, '67eef761846a5f1032ed2f21b455f6db87f9a4f2e40aa6c8e2902e30584fa4c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '67eef761846a5f1032ed2f21b455f6db87f9a4f2e40aa6c8e2902e30584fa4c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al secretari o secretària general del departament.', false), ('B', 'A un conseller o consellera.', true), ('C', 'Al president o presidenta de la Generalitat.', false), ('D', 'Al Consell Tècnic del Govern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, com es determinen el nombre, la denominació i l''àmbit de competències dels departaments en què s''organitza el Govern?', 'El president o presidenta de la Generalitat determina per decret el nombre, la denominació i l''àmbit de competències dels departaments; la Presidència de la Generalitat constitueix en tot cas un departament (art. 23.2 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 23.2 Llei 13/2008', 'El presidente o presidenta de la Generalidad determina por decreto el número, la denominación y el ámbito de competencias de los departamentos en que se organiza el Gobierno.', null, 'b6dda5a8e391e7e85a70c5326ce7285570f5bf251fb5cf0315c8b6c3a588c2a7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b6dda5a8e391e7e85a70c5326ce7285570f5bf251fb5cf0315c8b6c3a588c2a7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per decret del president o presidenta de la Generalitat.', true), ('B', 'Per llei del Parlament de Catalunya.', false), ('C', 'Per acord del Govern, a proposta del conseller o consellera de la Presidència.', false), ('D', 'Per ordre del conseller o consellera competent en matèria d''organització administrativa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 23.4 de la Llei 13/2008, com s''estableix l''estructura orgànica de cada departament i de quin òrgan ha de disposar en tot cas?', 'L''estructura orgànica de cada departament s''estableix per decret del Govern, d''acord amb la normativa d''organització de l''Administració de la Generalitat, i cada departament disposa en tot cas d''una secretaria general (art. 23.4 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 23.4 Llei 13/2008', 'La estructura orgánica de cada departamento se establece por decreto del Gobierno, con sujeción a lo que determina la normativa reguladora de la organización de la Administración de la Generalidad. En cualquier caso, cada departamento dispone de una secretaría general.', null, '2ebb4a31b22e4c863c64e609de14fd998081970dae5e4b1f2d0e28149c37695c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2ebb4a31b22e4c863c64e609de14fd998081970dae5e4b1f2d0e28149c37695c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per decret del president o presidenta, i cada departament disposa en tot cas d''una direcció general.', false), ('B', 'Per decret del Govern, i cada departament disposa en tot cas d''una secretaria general.', true), ('C', 'Per ordre del conseller o consellera, i cada departament disposa en tot cas d''una secretaria general.', false), ('D', 'Per decret del Govern, i cada departament disposa en tot cas d''un comissionat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, els comissionats:', 'El Govern pot nomenar comissionats, amb un àmbit d''actuació específic i adscrits al departament corresponent (art. 24.1); només assisteixen a les reunions del Govern quan hi són convocats per informar (art. 24.4) i tenen la consideració d''alts càrrecs (art. 24.5 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 24.1 i 24.5 Llei 13/2008', 'El Gobierno puede nombrar comisionados, debiendo asignarles un ámbito de actuación específico y debiendo adscribirlos al departamento correspondiente […] Los comisionados tienen la consideración de altos cargos.', null, '1a189518ae0d4bff0202e4449bd71fed01246eb028f45d16d4b8f29d9f1b1c3d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a189518ae0d4bff0202e4449bd71fed01246eb028f45d16d4b8f29d9f1b1c3d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els nomena el conseller o consellera de cada departament i no tenen la consideració d''alts càrrecs.', false), ('B', 'Els nomena el president o presidenta i són membres del Govern amb veu i vot.', false), ('C', 'Els nomena el Govern, que els ha d''assignar un àmbit d''actuació específic i adscriure''ls al departament corresponent, i tenen la consideració d''alts càrrecs.', true), ('D', 'Els nomena el Govern i depenen sempre directament del president o presidenta de la Generalitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.3 de la Llei 13/2008, quins comissionats poden rebre la denominació de viceconsellers?', 'Només els comissionats adscrits al Departament de la Presidència o al departament del qual és titular el vicepresident o vicepresidenta poden rebre la denominació de viceconsellers (art. 24.3 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 24.3 Llei 13/2008', 'Los comisionados adscritos al Departamento de la Presidencia o al departamento del que sea titular el vicepresidente o vicepresidenta pueden recibir la denominación de viceconsejeros.', null, '6700841d7c3bd22f06c1385c210b3ff4adae337305f73dd61b9dc9511d54fa63', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6700841d7c3bd22f06c1385c210b3ff4adae337305f73dd61b9dc9511d54fa63')
  returning id
), o as (
