)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, quina de les afirmacions següents sobre els delegats territorials del Govern NO és correcta?', 'Els delegats territorials representen el Govern, són la màxima autoritat de la Generalitat a la seva delegació i tenen rang de secretari general a efectes de protocol (art. 25.1); el seu nomenament i cessament els acorda el Govern per decret (art. 25.2 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 25 Llei 13/2008', 'Los delegados territoriales del Gobierno representan al Gobierno y son la máxima autoridad de la Generalidad en la respectiva delegación territorial, ostentando, a efectos de protocolo, rango de secretario o secretaria general. […] Corresponde al Gobierno acordar, por decreto, el nombramiento y el cese de los delegados territoriales.', null, '14f4d745987452f5e53fe8109ea011a2f346ca6af36ef7e33b1b353bf443ec79', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14f4d745987452f5e53fe8109ea011a2f346ca6af36ef7e33b1b353bf443ec79')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El president o presidenta de la Generalitat n''acorda el nomenament i el cessament per ordre.', true), ('B', 'Representen el Govern en la delegació territorial respectiva.', false), ('C', 'Són la màxima autoritat de la Generalitat en la delegació territorial respectiva.', false), ('D', 'A efectes de protocol, tenen rang de secretari o secretària general.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, a qui correspon, amb caràcter general, acordar el nomenament i el cessament dels alts càrrecs de l''Administració de la Generalitat de rang igual, assimilat o superior al de director o directora general?', 'Correspon al Govern acordar, a proposta del president o del conseller competent, el nomenament i el cessament dels alts càrrecs de rang igual, assimilat o superior al de director general, llevat que l''atribució correspongui al president d''acord amb l''art. 12.1.d (art. 26.h Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 26.h Llei 13/2008', 'Acordar el nombramiento y el cese, a propuesta del presidente o presidenta de la Generalidad o del consejero o consejera competente, de los altos cargos de la Administración de la Generalidad de rango igual, asimilado o superior al de director o directora general', null, '98a92ca124a5bf44b4968f978ecdc88fe91eb80dd76dba01190343d8a15b44af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '98a92ca124a5bf44b4968f978ecdc88fe91eb80dd76dba01190343d8a15b44af')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Govern, a proposta del president o presidenta o del conseller o consellera competent.', true), ('B', 'Al conseller o consellera del departament, sense necessitat de proposta.', false), ('C', 'Al secretari o secretària general del departament.', false), ('D', 'Al Parlament de Catalunya, a proposta del Govern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16 de la Llei 13/2008, quina atribució correspon als consellers en relació amb els càrrecs del seu departament?', 'Els consellers proposen al Govern el nomenament i el cessament dels alts càrrecs del departament i acorden el nomenament i el cessament dels altres càrrecs del departament (art. 16.d Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 16.d Llei 13/2008', 'Proponer al Gobierno el nombramiento y el cese de los altos cargos del departamento, y acordar el nombramiento y el cese de los demás cargos del departamento.', null, '18a7fbb674a856c9f2c769f9a916f9d5cf27e436514e34d882f7207dbc591d33', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '18a7fbb674a856c9f2c769f9a916f9d5cf27e436514e34d882f7207dbc591d33')
  returning id
