  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Acordar directament el nomenament i el cessament de tots els càrrecs del departament, inclosos els alts càrrecs.', false), ('B', 'Proposar al president o presidenta el nomenament de tots els càrrecs del departament.', false), ('C', 'Acordar el nomenament dels alts càrrecs del departament i proposar al Govern el dels altres càrrecs.', false), ('D', 'Proposar al Govern el nomenament i el cessament dels alts càrrecs del departament, i acordar el nomenament i el cessament dels altres càrrecs del departament.', true)) as v(label, body, ok)
)
