select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 34 de la Llei 13/2008, quins càrrecs són, en tot cas, membres nats del Consell Tècnic del Govern?', 'El Consell Tècnic del Govern és un òrgan col·legiat de suport al Govern; la presidència, la composició i el funcionament es regulen per decret, però en qualsevol cas els secretaris generals de cada departament en són membres nats (art. 34 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 34.2 Llei 13/2008', 'En cualquier caso, los secretarios generales de cada departamento son miembros natos del Consejo Técnico.', null, '341ae179b3bfdfc90d7bf319e42f1b6b8b61b87ea1f159a79ef12f96604507d4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '341ae179b3bfdfc90d7bf319e42f1b6b8b61b87ea1f159a79ef12f96604507d4')
  returning id
), o as (
