  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els consellers de cada departament.', false), ('B', 'Els delegats territorials del Govern.', false), ('C', 'Els secretaris generals de cada departament.', true), ('D', 'Els directors generals de cada departament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
