  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, els consellers poden dictar disposicions reglamentàries en matèria d''organització del seu departament. Quina forma adopten aquestes disposicions?', 'Els consellers poden dictar disposicions reglamentàries en matèria d''organització del departament (art. 39.3), i les disposicions reglamentàries que dicten adopten la forma d''ordre; les del Govern o del president, la de decret (art. 40.1 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 39.3 i 40.1 Llei 13/2008', 'Las disposiciones reglamentarias dictadas por el Gobierno o por el presidente o presidenta de la Generalidad adoptan forma de decreto. Las disposiciones reglamentarias dictadas por los consejeros adoptan forma de orden.', null, 'd012f0c64fdb6863d63425ad9aa9307a502d9fb130f5a218a9310cbfb801ac3a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd012f0c64fdb6863d63425ad9aa9307a502d9fb130f5a218a9310cbfb801ac3a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Forma d''ordre.', true), ('B', 'Forma de decret.', false), ('C', 'Forma de resolució.', false), ('D', 'Forma d''instrucció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
