  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 41 de la Llei 13/2008, quina relació jeràrquica hi ha entre els reglaments de la Generalitat?', 'Els reglaments aprovats per decret tenen més rang jurídic que els reglaments aprovats per ordre (art. 41 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 41 Llei 13/2008', 'Los reglamentos aprobados por decreto tienen mayor rango jurídico que los reglamentos aprobados por orden.', null, 'ec1fea4ca5308ec0bcad6fb6920133d8ff18866bb7cfdb29b3e0760e8eab0916', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ec1fea4ca5308ec0bcad6fb6920133d8ff18866bb7cfdb29b3e0760e8eab0916')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els reglaments aprovats per ordre tenen més rang jurídic que els aprovats per decret.', false), ('B', 'Els reglaments aprovats per decret i per ordre tenen el mateix rang jurídic.', false), ('C', 'El rang depèn de la data d''aprovació: preval el reglament posterior.', false), ('D', 'Els reglaments aprovats per decret tenen més rang jurídic que els aprovats per ordre.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, les circulars i instruccions emeses pels òrgans de l''Administració de la Generalitat:', 'Les circulars i instruccions dels òrgans de l''Administració de la Generalitat no es consideren en cap cas disposicions dictades en exercici de la potestat reglamentària (art. 39.4 Llei 13/2008).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 39.4 Llei 13/2008', 'Las circulares e instrucciones emitidas por los órganos de la Administración de la Generalidad no se consideran en ningún caso disposiciones dictadas en ejercicio de la potestad reglamentaria.', null, '1f7930d2dfc5f9709f45a98b45aa40e9388149cb395fb38118772ed463d5c5e7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1f7930d2dfc5f9709f45a98b45aa40e9388149cb395fb38118772ed463d5c5e7')
  returning id
