with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 13/2008, de la presidència de la Generalitat i del Govern, les deliberacions del Govern i les opinions i els vots que s''hi emeten:', 'L''art. 30.1 de la Llei 13/2008 declara secretes les deliberacions del Govern i les opinions i vots que s''hi emeten, i obliga els assistents a mantenir el secret fins i tot després d''haver cessat.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 30.1 Llei 13/2008', 'Las deliberaciones del Gobierno, así como las opiniones y los votos que se emiten, tienen carácter secreto. Las personas que asisten a las reuniones del Gobierno deben mantener el secreto incluso después de haber cesado.', null, '9f5cdd1abc2596a550ed53b37a47b320195e3f9476b6ab6ced8e657937d5ba0f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9f5cdd1abc2596a550ed53b37a47b320195e3f9476b6ab6ced8e657937d5ba0f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
