with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 32 de la Llei 13/2008, quina de les formes següents NO és una de les que adopten les decisions del Govern?', 'Les decisions del Govern adopten la forma de decret legislatiu, decret llei, decret o acord (art. 32.1 Llei 13/2008). L''ordre és la forma de les disposicions reglamentàries dictades pels consellers (art. 40.1).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2008-19526'), 'Art. 32.1 Llei 13/2008', 'Acuerdo, las decisiones del Gobierno distintas a la aprobación de decretos legislativos, de decretos ley o de decretos.', null, '2e3906deb3027674e3282923b4b074dcdc65c866f6187f250c93924ec5fdf452', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2e3906deb3027674e3282923b4b074dcdc65c866f6187f250c93924ec5fdf452')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Decret legislatiu.', false), ('B', 'Ordre.', true), ('C', 'Decret.', false), ('D', 'Acord.', false)) as v(label, body, ok)
)
