  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini de setanta-dues hores.', true), ('B', 'En el termini de quaranta-vuit hores.', false), ('C', 'En el termini de deu dies.', false), ('D', 'Abans que s''aixequi la sessió.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, la delegació de la competència, l''encàrrec de gestió, l''autorització de signatura i la suplència:', 'L''art. 6.2 de la Llei 26/2010 estableix que aquestes figures no alteren la titularitat de la competència, però sí els elements determinants del seu exercici que en cada cas s''estableixen.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 6.2 Llei 26/2010', 'La delegación de la competencia, el encargo de gestión, la autorización de firma y la suplencia no suponen alteración de la titularidad de la competencia, aunque sí de los elementos determinantes del ejercicio de la competencia que en cada caso se establecen.', null, 'a1fb4d04bb3ccd3115c27b0c094eb5943ccf4c9981809be4b78072ecfeca47c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1fb4d04bb3ccd3115c27b0c094eb5943ccf4c9981809be4b78072ecfeca47c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No suposen alteració de la titularitat de la competència, tot i que sí dels elements determinants del seu exercici.', true), ('B', 'Suposen la transferència de la titularitat de la competència a l''òrgan que la rep.', false), ('C', 'Només suposen alteració de la titularitat quan es fan a favor d''un òrgan jeràrquicament dependent.', false), ('D', 'Requereixen en tots els casos l''aprovació del Govern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, la delegació d''una competència:', 'L''art. 8.5 de la Llei 26/2010 permet a l''òrgan delegant revocar la delegació en qualsevol moment. La delegació i la seva extinció s''han de publicar al diari o butlletí oficial (art. 8.6).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 8.5 Llei 26/2010', 'La delegación de una competencia puede ser revocada en cualquier momento por el órgano que la ha conferido.', null, 'ed53e73ad38cab3346d513c44177fe48719bd52931fc3c4c1595358ede5472ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ed53e73ad38cab3346d513c44177fe48719bd52931fc3c4c1595358ede5472ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es pot revocar fins que no hagi transcorregut un any des de la publicació.', false), ('B', 'Només pot ser revocada pel Govern.', false), ('C', 'Només es pot revocar si l''òrgan delegat hi dona la conformitat.', false), ('D', 'Pot ser revocada en qualsevol moment per l''òrgan que l''ha conferida.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, els actes administratius que s''adopten per delegació:', 'Els actes adoptats per delegació es consideren dictats per l''òrgan delegant i han d''incloure abans de la signatura les paraules «per delegació», amb la data de l''acord de delegació i la de la seva publicació (art. 8.8 Llei 26/2010). La fórmula «per autorització» és pròpia de l''autorització de signatura (art. 11.5).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 8.8 Llei 26/2010', 'Los actos administrativos que se adoptan por delegación se consideran dictados por el órgano delegante, debiendo incluir antes de la firma las palabras «por delegación»', null, '29cf30cbae9cab31d1646c53d690a01062a468e4f56aadd26202df006bfe1277', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29cf30cbae9cab31d1646c53d690a01062a468e4f56aadd26202df006bfe1277')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es consideren dictats per l''òrgan delegant i han d''incloure, abans de la signatura, les paraules «per delegació».', true), ('B', 'Es consideren dictats per l''òrgan delegat i han d''incloure les paraules «per autorització».', false), ('C', 'Es consideren dictats pel superior jeràrquic comú de tots dos òrgans.', false), ('D', 'Es consideren dictats per l''òrgan delegat, que n''assumeix la titularitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, quan la secretaria d''un òrgan col·legiat l''exerceix una persona al servei de l''administració pública que no és vocal de l''òrgan:', 'La secretaria l''exerceix un vocal del mateix òrgan o una persona al servei de l''administració corresponent; en aquest darrer cas, assisteix a les sessions amb veu i sense vot (art. 14.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 14.2 Llei 26/2010', 'La secretaría es ejercida por un vocal o una vocal del mismo órgano o por una persona al servicio de la correspondiente administración pública. En este último caso, asiste a las sesiones con voz y sin voto.', null, '6e2f7e8c820d261870073ef41088a5491116198dd4d1563929df316a68e56b3a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6e2f7e8c820d261870073ef41088a5491116198dd4d1563929df316a68e56b3a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Assisteix a les sessions amb veu i vot.', false), ('B', 'Assisteix a les sessions amb veu i sense vot.', true), ('C', 'No pot assistir a les sessions, i només n''estén l''acta a partir de les notes del president.', false), ('D', 'Assisteix a les sessions sense veu i sense vot.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, llevat que les normes reguladores estableixin una majoria diferent, els acords dels òrgans col·legiats s''adopten:', 'Els acords dels òrgans col·legiats s''adopten per majoria simple de vots, llevat que les normes reguladores estableixin una altra majoria, i en cas d''empat dirimeix el vot del president o presidenta (art. 19.1 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 19.1 Llei 26/2010', 'Los acuerdos del órgano colegiado se adoptan por mayoría simple de votos, salvo que sus normas reguladoras establezcan una mayoría distinta. En caso de empate dirime los resultados de las votaciones el voto del presidente o presidenta.', null, '4c8d5ed3a2bcf88552791374f12dc25ccf1d19b3dc16ee765e7ecbb9b4557845', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c8d5ed3a2bcf88552791374f12dc25ccf1d19b3dc16ee765e7ecbb9b4557845')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per majoria absoluta dels membres; en cas d''empat, es repeteix la votació en la sessió següent.', false), ('B', 'Per majoria de dues terceres parts dels membres presents.', false), ('C', 'Per majoria simple de vots; en cas d''empat, dirimeix el vot del president o presidenta.', true), ('D', 'Per majoria simple de vots; en cas d''empat, dirimeix el vot del secretari o secretària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, si una disposició atribueix competències a una administració pública sense especificar l''òrgan que les ha d''exercir, la facultat d''instruir i resoldre els expedients correspon:', 'L''art. 6.4 de la Llei 26/2010 atribueix en aquest cas la facultat d''instruir i resoldre als òrgans inferiors competents per raó de la matèria i del territori i, si n''hi ha diversos, al superior jeràrquic comú.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 6.4 Llei 26/2010', 'se entiende que la facultad de instruir y resolver los expedientes corresponde a los órganos inferiores competentes por razón de la materia y del territorio y, de existir varios de ellos, al superior jerárquico común.', null, '77dfdd849cbbba9ba4eca06b3b0c44840519463025960c5ab8a716582e41a1a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '77dfdd849cbbba9ba4eca06b3b0c44840519463025960c5ab8a716582e41a1a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al titular del departament competent per raó de la matèria.', false), ('B', 'Als òrgans inferiors competents per raó de la matèria i del territori i, si n''hi ha diversos, al superior jeràrquic comú.', true), ('C', 'Al Govern, que ha de designar l''òrgan competent mitjançant acord.', false), ('D', 'A l''òrgan superior de l''administració, que pot delegar-la en els òrgans inferiors.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 7 de la Llei 26/2010, l''òrgan del qual depenen jeràrquicament altres òrgans pot emetre instruccions i circulars o ordres de servei. Quina és la funció de cadascuna?', 'Segons l''art. 7.1 de la Llei 26/2010, les instruccions i circulars fixen els criteris per a l''aplicació de les normes jurídiques en l''exercici de les funcions, i les ordres de servei, els criteris per al funcionament dels serveis («respectivament»).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.1 Llei 26/2010', 'puede emitir instrucciones y circulares u órdenes de servicios para fijar, respectivamente, los criterios para la aplicación de las normas jurídicas en el ejercicio de sus funciones y para el funcionamiento de los servicios.', null, '1c6b1da69b85f6f752522fe195417c83dddcb5eba835978cedbb15c78ae0f745', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1c6b1da69b85f6f752522fe195417c83dddcb5eba835978cedbb15c78ae0f745')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les instruccions i circulars fixen els criteris per a l''aplicació de les normes jurídiques, i les ordres de servei, els criteris per al funcionament dels serveis.', true), ('B', 'Les instruccions i circulars fixen els criteris per al funcionament dels serveis, i les ordres de servei, els criteris per a l''aplicació de les normes jurídiques.', false), ('C', 'Les instruccions i circulars són disposicions reglamentàries, i les ordres de servei són actes administratius singulars.', false), ('D', 'Totes dues tenen la mateixa funció i només es diferencien per l''òrgan que les dicta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, l''incompliment de les instruccions o de les ordres de servei per part d''un òrgan administratiu:', 'L''art. 7.3 de la Llei 26/2010 estableix que l''incompliment de les instruccions o ordres de servei no afecta per si sol la validesa dels actes, sens perjudici de la responsabilitat disciplinària.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 7.3 Llei 26/2010', 'El incumplimiento de las instrucciones o de las órdenes de servicio no afecta por sí solo a la validez de los actos dictados por los órganos administrativos, sin perjuicio de la responsabilidad disciplinaria en que se pueda incurrir.', null, 'db276ecacac57582a8e692ee23595c639bd8345f1ddf6fd570755d04db6b3302', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db276ecacac57582a8e692ee23595c639bd8345f1ddf6fd570755d04db6b3302')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Determina la nul·litat de ple dret dels actes dictats.', false), ('B', 'Determina l''anul·labilitat dels actes dictats, que es poden convalidar.', false), ('C', 'No té cap conseqüència, ni sobre la validesa dels actes ni de caràcter disciplinari.', false), ('D', 'No afecta per si sol la validesa dels actes dictats, sens perjudici de la responsabilitat disciplinària en què es pugui incórrer.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Pel que fa a l''encàrrec de gestió regulat a la Llei 26/2010, quina de les afirmacions següents NO és correcta?', 'L''encàrrec de gestió té per objecte activitats materials, tècniques o de serveis i es pot fer per raons d''eficàcia o per manca de mitjans idonis (art. 10.1), però no suposa la cessió de la titularitat de la competència ni dels elements substantius del seu exercici; l''òrgan que el fa és qui ha de dictar els actes jurídics (art. 10.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 10 Llei 26/2010', 'El encargo de gestión no supone la cesión de la titularidad de la competencia ni de los elementos sustantivos de su ejercicio', null, 'e63959b3abdc016a8c2cc55ce89db44cbe0643ea6e2f6ad1e52a671ed5d164a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e63959b3abdc016a8c2cc55ce89db44cbe0643ea6e2f6ad1e52a671ed5d164a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Té per objecte la realització d''activitats de caràcter material, tècnic o de serveis.', false), ('B', 'Es pot fer per raons d''eficàcia o quan no es tenen els mitjans tècnics idonis per a l''exercici de l''activitat.', false), ('C', 'Suposa la cessió de la titularitat de la competència a l''òrgan o l''entitat que el rep.', true), ('D', 'Correspon a l''òrgan que el fa dictar els actes o les resolucions de caràcter jurídic que li donin suport.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, l''autorització de signatura:', 'A diferència de la delegació, que s''ha de publicar (art. 8.6), l''autorització de signatura és vàlida i eficaç sense publicació ni notificació a les persones interessades (art. 11.6 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 11.6 Llei 26/2010', 'La autorización de firma es válida y eficaz sin necesidad de su publicación en el correspondiente diario o boletín oficial ni de su notificación a las personas interesadas.', null, 'c11bc728aa7b169b4d0b3b1716933012294ba85e52ee98dec74401b2f44ecaaa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c11bc728aa7b169b4d0b3b1716933012294ba85e52ee98dec74401b2f44ecaaa')
  returning id
), o as (
