  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només és eficaç des de la seva publicació al diari o butlletí oficial corresponent.', false), ('B', 'S''ha de notificar a les persones interessades abans de la resolució del procediment.', false), ('C', 'És vàlida i eficaç sense necessitat de publicar-la al diari o butlletí oficial ni de notificar-la a les persones interessades.', true), ('D', 'S''ha de publicar a la seu electrònica i notificar a les persones interessades.', false)) as v(label, body, ok)
)
