select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 15 de la Llei 26/2010, quina de les funcions següents NO correspon al secretari o secretària d''un òrgan col·legiat?', 'Visar les actes és funció del president o presidenta (art. 15.1.h). Al secretari o secretària li correspon, entre altres funcions, fer la convocatòria per ordre del president, estendre l''acta, emetre els certificats i custodiar i arxivar les actes (art. 15.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 15.2 Llei 26/2010', 'Visar los actos de las reuniones del órgano.', null, 'cf118f1d1b70c2403b1f34d3d8adc336fe68927504095db639533ef74dffac0c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf118f1d1b70c2403b1f34d3d8adc336fe68927504095db639533ef74dffac0c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estendre l''acta de la sessió.', false), ('B', 'Emetre els certificats pertinents.', false), ('C', 'Custodiar i arxivar les actes.', false), ('D', 'Visar les actes de les reunions de l''òrgan.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, en cas d''absència, vacant o malaltia de la persona que ocupa la secretaria d''un òrgan col·legiat, la substitueix:', 'La persona que ocupa la presidència és substituïda per la vicepresidència, segons l''ordre de nomenament, i si no n''hi ha, pel vocal de més antiguitat (art. 16.3); la que ocupa la secretaria és substituïda pel vocal o la vocal més jove (art. 16.4 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 16.3 i 16.4 Llei 26/2010', 'La persona que ocupa la secretaría es sustituida por el vocal o la vocal más joven.', null, '68b51e7871f5bd8485f1a8ed8d413f2193fb7a0b312143788cd1a1b5a930e64d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '68b51e7871f5bd8485f1a8ed8d413f2193fb7a0b312143788cd1a1b5a930e64d')
  returning id
