)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, un òrgan col·legiat pot tractar un assumpte que no figura a l''ordre del dia quan:', 'Només es poden tractar els assumptes de l''ordre del dia, llevat que siguin presents tots els membres i es declari la urgència de l''assumpte amb el vot favorable de la majoria absoluta (art. 18.4 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 18.4 Llei 26/2010', 'Solo pueden ser tratados los asuntos que figuran en el orden del día, salvo que estén presentes todos los miembros del órgano colegiado y se declare la urgencia del asunto con el voto favorable de la mayoría absoluta.', null, '35e6c35a2b03b24324af0e7cbf375a5ac351e5490567a2eb9dd10904565a23dc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '35e6c35a2b03b24324af0e7cbf375a5ac351e5490567a2eb9dd10904565a23dc')
  returning id
), o as (
