  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hi són presents tots els membres de l''òrgan i es declara la urgència de l''assumpte amb el vot favorable de la majoria absoluta.', true), ('B', 'Ho acorda el president o presidenta, per raons d''urgència.', false), ('C', 'Ho sol·licita com a mínim una tercera part dels membres presents.', false), ('D', 'Hi és present la majoria absoluta dels membres i ho acorden per unanimitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
