with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, els membres d''un òrgan col·legiat que fan constar en acta el seu vot contrari o la seva abstenció en relació amb un acord adoptat:', 'L''art. 19.3 de la Llei 26/2010 eximeix de la responsabilitat derivada de l''acord els membres que fan constar en acta el seu vot contrari o la seva abstenció. El vot particular és potestatiu i es pot formular en setanta-dues hores (art. 20.2).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 19.3 Llei 26/2010', 'Los miembros de los órganos colegiados que hacen constar en acta su voto contrario o su abstención con relación a un acuerdo adoptado quedan exentos de la responsabilidad que de ello pueda derivarse.', null, '764f8c28e9deeaa682ea0c8e556e3a66c21fa63cfcffa2ddc7fcacd622d17e96', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '764f8c28e9deeaa682ea0c8e556e3a66c21fa63cfcffa2ddc7fcacd622d17e96')
  returning id
), o as (
