with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, quan la delegació es fa per a un procediment administratiu concret que inclou un dictamen o informe preceptiu, la delegació:', 'La delegació pot ser general o per a un procediment concret; en aquest cas es pot fer en qualsevol moment previ a la resolució, llevat que el procediment inclogui un dictamen o informe preceptiu, cas en què s''ha de fer abans que s''emeti (art. 8.2 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 8.2 Llei 26/2010', 'salvo que el procedimiento incluya un dictamen o informe preceptivo, en cuyo caso la delegación debe hacerse antes de que dicho dictamen o informe haya sido emitido.', null, '7a95cdc39d86de0825ffbae4069a1266658ac0c6fd2bdce03d714c158bf09dc0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7a95cdc39d86de0825ffbae4069a1266658ac0c6fd2bdce03d714c158bf09dc0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot fer en qualsevol moment de la tramitació, fins i tot després de la proposta de resolució.', false), ('B', 'Només es pot fer un cop emès el dictamen o informe preceptiu.', false), ('C', 'No és possible: en aquests procediments només es pot fer una delegació general.', false), ('D', 'S''ha de fer abans que el dictamen o informe hagi estat emès.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, el canvi de titular de l''òrgan delegant o de l''òrgan delegat:', 'L''art. 8.7 de la Llei 26/2010 disposa que el canvi de titular de l''òrgan delegant o del delegat només extingeix la delegació si així ho estableix l''acte de delegació.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 8.7 Llei 26/2010', 'El cambio de titular del órgano delegante o del órgano delegado sólo extingue la delegación si así lo ha establecido el acto de delegación.', null, 'd9ae1e01e2dc718d63fc97aec5d11248d04da39edc1aa290cdcaf59a40ede661', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9ae1e01e2dc718d63fc97aec5d11248d04da39edc1aa290cdcaf59a40ede661')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Extingeix sempre la delegació, que s''ha de tornar a acordar i publicar.', false), ('B', 'Extingeix la delegació només quan canvia el titular de l''òrgan delegant.', false), ('C', 'Extingeix la delegació, llevat que el nou titular la ratifiqui en el termini d''un mes.', false), ('D', 'Només extingeix la delegació si així ho ha establert l''acte de delegació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, en els supòsits de delegació de competències en òrgans que no en depenen jeràrquicament, el coneixement d''un assumpte pot ser avocat:', 'Els òrgans superiors poden avocar el coneixement d''assumptes dels òrgans dependents per circumstàncies tècniques, econòmiques, socials, jurídiques o territorials; però, si la delegació s''ha fet en òrgans no dependents jeràrquicament, només pot avocar l''òrgan delegant (art. 9.1 Llei 26/2010).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 9.1 Llei 26/2010', 'En los supuestos de delegación de competencias en órganos jerárquicamente no dependientes, el conocimiento de un asunto puede ser avocado únicamente por el órgano delegante.', null, '559b425e82a434f930266c7c6e6527d74611cac48ff51e37bd692c562513505a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '559b425e82a434f930266c7c6e6527d74611cac48ff51e37bd692c562513505a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per qualsevol òrgan superior de l''òrgan delegat.', false), ('B', 'Pel superior jeràrquic comú de l''òrgan delegant i de l''òrgan delegat.', false), ('C', 'Únicament per l''òrgan delegant.', true), ('D', 'Pel Govern, a proposta del conseller competent.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, quan l''encàrrec de gestió es fa a un òrgan o entitat d''una altra administració, s''ha de formalitzar mitjançant conveni. Quina de les determinacions següents NO és una de les que ha d''establir, com a mínim, aquest conveni?', 'L''art. 10.5 de la Llei 26/2010 exigeix que el conveni estableixi almenys l''abast i el contingut de l''activitat, les raons que justifiquen l''encàrrec, la fórmula de finançament, les relacions i actuacions de seguiment i control i el termini de vigència. No exigeix la relació nominal del personal.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 10.5 Llei 26/2010', 'a) El alcance y contenido de la actividad encargada. b) Las razones que justifican el encargo. c) La fórmula de financiación de la actividad encargada, con indicación de los correspondientes créditos presupuestarios que se transfieren. d) Las relaciones y las actuaciones para realizar el seguimiento y control del encargo. e) El plazo de vigencia del convenio.', null, '2b4b692a0757a0fa10ac3e0ba9e985e73133386ecfaba3ea3ffc0c50124d0575', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2b4b692a0757a0fa10ac3e0ba9e985e73133386ecfaba3ea3ffc0c50124d0575')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''abast i el contingut de l''activitat encarregada.', false), ('B', 'La relació nominal del personal que executarà l''activitat encarregada.', true), ('C', 'La fórmula de finançament de l''activitat encarregada.', false), ('D', 'El termini de vigència del conveni.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, els conflictes d''atribucions només es poden plantejar:', 'L''art. 12.5 de la Llei 26/2010 limita els conflictes d''atribucions als òrgans de la mateixa administració o dels seus organismes i entitats dependents o vinculats que no estiguin jeràrquicament relacionats, i a assumptes amb procediment no finalitzat. Es planteja a l''òrgan que determini la normativa o, si no n''hi ha, a l''immediat superior comú (art. 12.4).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 12.5 Llei 26/2010', 'Los conflictos de atribuciones sólo pueden plantearse entre órganos de la misma administración o de organismos o entidades públicas dependientes o vinculados a la misma, siempre y cuando no estén jerárquicamente relacionados, y sobre asuntos cuyo procedimiento administrativo no haya finalizado.', null, 'aaf518e66dc51a460ab7bf1c0e69bc61b9f28c3ef7d185ae6f90d6e9b13a4abb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aaf518e66dc51a460ab7bf1c0e69bc61b9f28c3ef7d185ae6f90d6e9b13a4abb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Entre òrgans de la mateixa administració o d''organismes o entitats que en depenen o hi estan vinculats, que no estiguin jeràrquicament relacionats, i sobre assumptes el procediment dels quals no hagi finalitzat.', true), ('B', 'Entre òrgans de diferents administracions públiques, sobre assumptes ja resolts.', false), ('C', 'Entre un òrgan superior i els òrgans que en depenen jeràrquicament, en qualsevol fase del procediment.', false), ('D', 'Entre òrgans de la mateixa administració, fins i tot després que hagi finalitzat el procediment administratiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, encara que no s''hagin complert els requisits de la convocatòria, un òrgan col·legiat queda vàlidament constituït si:', 'L''art. 17.3 de la Llei 26/2010 admet la constitució vàlida sense els requisits de convocatòria si s''han reunit tots els membres i ho acorden per unanimitat.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 17.3 Llei 26/2010', 'Aunque no se hayan cumplido los requisitos de la convocatoria, un órgano colegiado queda válidamente constituido si se han reunido todos sus miembros y lo acuerdan por unanimidad.', null, 'acc647071ab502b85b74f9c33ee5f3f7e6cfebc076745ef1b98e42c9f802cd3b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'acc647071ab502b85b74f9c33ee5f3f7e6cfebc076745ef1b98e42c9f802cd3b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha reunit la majoria absoluta dels membres i ho acorda el president o presidenta.', false), ('B', 'S''han reunit tots els seus membres i ho acorden per unanimitat.', true), ('C', 'Hi són presents el president, el secretari i la meitat dels membres.', false), ('D', 'Ho acorda la majoria absoluta dels membres presents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, per a la constitució vàlida d''un òrgan col·legiat en primera convocatòria, amb caràcter general, es requereix la presència:', 'En primera convocatòria cal la presència de la presidència i la secretaria, o de qui els substitueixi, i de la meitat, com a mínim, dels membres (art. 17.4 Llei 26/2010). La tercera part amb un mínim de tres és el quòrum supletori de la segona convocatòria (art. 17.6).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 17.4 Llei 26/2010', 'se requiere la presencia de los titulares de la presidencia y de la secretaría, o en su caso de quienes les sustituyan, y la de la mitad, como mínimo, de sus miembros', null, '5a817815c4950699acbb50aac395126719db0876fc0b6ee7a3d3241ce1825ef3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a817815c4950699acbb50aac395126719db0876fc0b6ee7a3d3241ce1825ef3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dels titulars de la presidència i de la secretaria, o de qui els substitueixi, i de la meitat, com a mínim, dels membres.', true), ('B', 'Del titular de la presidència i d''una tercera part dels membres, amb un mínim de tres.', false), ('C', 'De la majoria absoluta dels membres, sense que calgui la presència del secretari o secretària.', false), ('D', 'De dues terceres parts dels membres, inclosos el president i el secretari.', false)) as v(label, body, ok)
