insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 40/2015, de 1 de octubre, de Régimen Jurídico del Sector Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g2-organitzacio-generalitat', 'Part general. Tema 2. Organització de l''Administració de la Generalitat i departaments') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g2-organitzacio-generalitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3.1 de la Llei 40/2015, de règim jurídic del sector públic, les administracions públiques actuen d''acord amb els principis d''eficàcia, jerarquia, descentralització, desconcentració i:', 'Les administracions públiques serveixen amb objectivitat els interessos generals i actuen d''acord amb els principis d''eficàcia, jerarquia, descentralització, desconcentració i coordinació, amb submissió plena a la Constitució, a la llei i al dret (art. 3.1 Llei 40/2015).', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 3.1 Llei 40/2015', 'Las Administraciones Públicas sirven con objetividad los intereses generales y actúan de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación, con sometimiento pleno a la Constitución, a la Ley y al Derecho.', null, '4d0caf933e01e1ca5c0617fc546da129849bd9f6172f28933adfd615d9cafdfe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4d0caf933e01e1ca5c0617fc546da129849bd9f6172f28933adfd615d9cafdfe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Competència.', false), ('B', 'Subsidiarietat.', false), ('C', 'Autonomia.', false), ('D', 'Coordinació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 5.3 de la Llei 40/2015, quin dels requisits següents NO s''exigeix, com a mínim, per crear un òrgan administratiu?', 'La creació de qualsevol òrgan administratiu exigeix, almenys, determinar-ne la forma d''integració i la dependència jeràrquica, delimitar-ne les funcions i competències i dotar-lo dels crèdits necessaris (art. 5.3 Llei 40/2015). No s''hi exigeix cap informe de la representació del personal.', 'pcat_g2_organitzacio_generalitat', (select id from public.topics where slug = 'pcat-g2-organitzacio-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 5.3 Llei 40/2015', 'La creación de cualquier órgano administrativo exigirá, al menos, el cumplimiento de los siguientes requisitos: a) Determinación de su forma de integración en la Administración Pública de que se trate y su dependencia jerárquica. b) Delimitación de sus funciones y competencias. c) Dotación de los créditos necesarios para su puesta en marcha y funcionamiento.', null, 'b6028b485a64082f316c9a3e280b522f2ba535e59a05c91f705af81f2ec0f000', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b6028b485a64082f316c9a3e280b522f2ba535e59a05c91f705af81f2ec0f000')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La determinació de la seva forma d''integració en l''Administració pública de què es tracti i de la seva dependència jeràrquica.', false), ('B', 'La delimitació de les seves funcions i competències.', false), ('C', 'L''informe previ favorable de la representació del personal.', true), ('D', 'La dotació dels crèdits necessaris per posar-lo en marxa i per al seu funcionament.', false)) as v(label, body, ok)
)
