insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 17/2015, de 21 de julio, de igualdad efectiva de mujeres y hombres (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g3-bon-govern-transparencia-igualtat', 'Part general. Tema 3. Bon govern, transparència, accés a la informació i igualtat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g3-bon-govern-transparencia-igualtat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, del 21 de juliol, d''igualtat efectiva de dones i homes, hi ha representació paritària quan:', 'La representació paritària garanteix una presència en què cap sexe supera el 60% ni és inferior al 40%, i ha de tendir al 50% de cada sexe (art. 2.i Llei 17/2015).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 2.i Llei 17/2015', 'Representación paritaria: la situación que garantiza una presencia de mujeres y hombres según la cual ningún sexo supera el 60% del conjunto de personas a que se refiere ni es inferior al 40%, y que debe tender a alcanzar el 50% de personas de cada sexo.', null, '6bfd8dacf840c40f602eca6ed07ee6c42ce515faf245317716d6ad1382817e48', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6bfd8dacf840c40f602eca6ed07ee6c42ce515faf245317716d6ad1382817e48')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap sexe supera el 70% del conjunt de persones a què es refereix ni és inferior al 30%.', false), ('B', 'Hi ha exactament el 50% de persones de cada sexe.', false), ('C', 'Cap sexe supera el 60% del conjunt de persones a què es refereix ni és inferior al 40%.', true), ('D', 'Les dones representen com a mínim un terç del conjunt de persones.', false)) as v(label, body, ok)
)
