with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16.3 de la Llei 17/2015, els temaris per accedir a l''ocupació pública han d''incloure continguts relatius a:', 'Els temaris d''accés a l''ocupació pública han d''incloure els continguts relatius a la normativa sobre igualtat efectiva de dones i homes i sobre violència masclista aplicables a l''activitat administrativa (art. 16.3 Llei 17/2015).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 16.3 Llei 17/2015', 'Los temarios para el acceso al empleo público deben incluir los contenidos relativos a la normativa sobre igualdad efectiva de mujeres y hombres y sobre violencia machista', null, '72e1c64aeb1dc31bb39465d94fc7129977a22272aebde2fb660b0c74a9553fdf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '72e1c64aeb1dc31bb39465d94fc7129977a22272aebde2fb660b0c74a9553fdf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
