with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, del 21 de juliol, d''igualtat efectiva de dones i homes, què han d''impulsar les administracions públiques de Catalunya en la composició dels tribunals o òrgans tècnics de selecció?', 'L''art. 16.2 de la Llei 17/2015 obliga les administracions públiques de Catalunya a impulsar la representació paritària de dones i homes en la composició dels tribunals o òrgans tècnics de selecció.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 16.2 Llei 17/2015', 'Las administraciones públicas de Cataluña deben impulsar la representación paritaria de mujeres y hombres en la composición de los tribunales u órganos técnicos de selección.', null, 'd78738869c5f1f0b12ef5cb5db1658f785cddaec89ace868faec04197d3fc7c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd78738869c5f1f0b12ef5cb5db1658f785cddaec89ace868faec04197d3fc7c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una presència majoritària de dones mentre no s''assoleixi la igualtat efectiva.', false), ('B', 'La representació paritària de dones i homes.', true), ('C', 'Una presència mínima d''un 25 % de persones de cada sexe.', false), ('D', 'La presència obligatòria d''una persona experta en igualtat amb dret de vot.', false)) as v(label, body, ok)
)
