with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54.1 de la Llei 17/2015, els serveis i centres d''execució penal han d''incorporar la perspectiva de gènere en els seus programes. Quina de les previsions següents NO hi figura?', 'L''art. 54.1 de la Llei 17/2015 preveu programes de tractament específics per a col·lectius de dones, programes formatius de sensibilització per a homes i dones interns, el reforç de l''atenció mèdica i psicològica amb perspectiva de gènere i que les activitats d''inserció laboral no perpetuïn els rols de gènere. No preveu separar per sexe totes les activitats.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 54.1 Llei 17/2015', 'Los centros de ejecución penal deben contar con programas de tratamiento específicos para los diferentes colectivos de mujeres, con especial atención a mujeres jóvenes, embarazadas y madres […] Los servicios y centros de ejecución penal deben desarrollar programas formativos destinados a hombres y mujeres internos con el objetivo de sensibilizarlos sobre la igualdad de mujeres y hombres […] Los centros de ejecución penal deben reforzar la atención médica y psicológica con perspectiva de género, así como la educación sexual y reproductiva.', null, '6c6543cd346256bb50a1112bb86cfd663a2b2cd797d275971ed179f74101e722', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6c6543cd346256bb50a1112bb86cfd663a2b2cd797d275971ed179f74101e722')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comptar amb programes de tractament específics per als diferents col·lectius de dones, amb especial atenció a les joves, les embarassades i les mares.', false), ('B', 'Desenvolupar programes formatius per sensibilitzar els homes i les dones interns sobre la igualtat de dones i homes.', false), ('C', 'Reforçar l''atenció mèdica i psicològica amb perspectiva de gènere, i també l''educació sexual i reproductiva.', false), ('D', 'Separar per sexe totes les activitats formatives i ocupacionals de les persones internes.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
