with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 17/2015, d''igualtat efectiva de dones i homes, les infraccions tipificades en aquesta llei prescriuen:', 'L''art. 63.1 de la Llei 17/2015 fixa sis mesos (lleus), dotze mesos (greus) i divuit mesos (molt greus). Els terminis de tres, sis i dotze mesos corresponen a la prescripció de les sancions (art. 63.2).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676'), 'Art. 63.1 Llei 17/2015', 'Las infracciones tipificadas como leves por la presente ley prescriben a los seis meses; las tipificadas como graves, al cabo de doce meses, y las tipificadas como muy graves, al cabo de dieciocho meses.', null, '30e1311d3a8ccc52d186a0f0c1ac7c8eeda4305f37e5814f1066474cde3bc95e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '30e1311d3a8ccc52d186a0f0c1ac7c8eeda4305f37e5814f1066474cde3bc95e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les lleus, a l''any; les greus, als dos anys, i les molt greus, als tres anys.', false), ('B', 'Les lleus, als sis mesos; les greus, al cap de dotze mesos, i les molt greus, al cap de divuit mesos.', true), ('C', 'Les lleus, als tres mesos; les greus, als sis mesos, i les molt greus, al cap de dotze mesos.', false), ('D', 'Totes, al cap de dos anys.', false)) as v(label, body, ok)
)
