with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei orgànica 3/2007, en els litigis sobre assetjament sexual i assetjament per raó de sexe:', 'Amb caràcter general, la legitimació en els processos de defensa del dret a la igualtat correspon a les persones amb interès legítim (art. 12.2), però en els litigis sobre assetjament sexual i per raó de sexe l''única legitimada és la persona assetjada (art. 12.3 LO 3/2007).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 12.3 LO 3/2007', 'La persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso por razón de sexo.', null, '439eaffab605c9449e962c80e16df7c3ce593f6c4f889b3ba4daf2ce7791f1cf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '439eaffab605c9449e962c80e16df7c3ce593f6c4f889b3ba4daf2ce7791f1cf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estan legitimats la persona assetjada i els sindicats més representatius.', false), ('B', 'Està legitimat qualsevol persona física o jurídica amb interès legítim.', false), ('C', 'L''única legitimada és la persona assetjada.', true), ('D', 'La legitimació correspon exclusivament al Ministeri Fiscal.', false)) as v(label, body, ok)
)
