with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, del 29 de desembre, de transparència, accés a la informació pública i bon govern, què s''entén per informació pública?', 'L''art. 2.b de la Llei 19/2014 defineix la informació pública com la informació elaborada per l''Administració i la que té en poder seu com a conseqüència de la seva activitat o de l''exercici de les seves funcions, incloent-hi la que li subministren els altres subjectes obligats.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 2.b Llei 19/2014', 'Información pública: la información elaborada por la Administración y la que esta tiene en su poder como consecuencia de su actividad o del ejercicio de sus funciones, incluida la que le suministran los demás sujetos obligados de acuerdo con lo establecido por la presente ley.', null, '1232b04e88efed06cefd8f368a25babecaba76ad07cf36306e9373715afd7304', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1232b04e88efed06cefd8f368a25babecaba76ad07cf36306e9373715afd7304')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només la informació que l''Administració ha publicat al Portal de la Transparència.', false), ('B', 'Només la informació elaborada per l''Administració, amb exclusió de la que li han subministrat tercers.', false), ('C', 'La informació elaborada per l''Administració i la que aquesta té en el seu poder com a conseqüència de la seva activitat o de l''exercici de les seves funcions, incloent-hi la que li subministren els altres subjectes obligats.', true), ('D', 'La informació que figura en expedients administratius finalitzats en què el sol·licitant té la condició d''interessat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, com es defineixen els principis, obligacions i regles sobre la qualitat dels serveis i el funcionament de l''Administració, i els principis ètics i bones pràctiques d''acord amb els quals han d''actuar els alts càrrecs, els càrrecs directius i la resta de personal al servei de l''Administració?', 'Aquesta és la definició de bon govern de l''art. 2.d de la Llei 19/2014. El govern obert (art. 2.e) es refereix al diàleg permanent amb les persones i als instruments de participació; la transparència (art. 2.a), a l''acció proactiva de donar a conèixer la informació, i la publicitat activa (art. 2.i), al deure de publicar-la d''ofici.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 2.d Llei 19/2014', 'Buen gobierno: los principios, obligaciones y reglas sobre la calidad de los servicios y el funcionamiento de la Administración, y los principios éticos y buenas prácticas de acuerdo con los que deben actuar los altos cargos de la Administración, los cargos directivos y demás personal al servicio de la Administración', null, 'd9c550db42f741406f1194209b1891e9c551840746ac3980a9cb14c4f91a4266', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9c550db42f741406f1194209b1891e9c551840746ac3980a9cb14c4f91a4266')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Govern obert.', false), ('B', 'Bon govern.', true), ('C', 'Transparència.', false), ('D', 'Publicitat activa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, l''exercici del dret d''accés a la informació pública:', 'El dret d''accés no està condicionat a cap interès personal, no s''ha de motivar i no requereix invocar cap norma (art. 18.2 Llei 19/2014). El sol·licitant pot exposar-ne els motius de manera potestativa, però la manca de motivació mai no és causa de denegació (art. 26.2).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 18.2 Llei 19/2014', 'El ejercicio de este derecho no está condicionado a la concurrencia de un interés personal, no queda sujeto a motivación y no requiere la invocación de ninguna norma.', null, '8ae5bdface258b46d88c39d7cc598c7420221827a770382815adaea32a162700', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8ae5bdface258b46d88c39d7cc598c7420221827a770382815adaea32a162700')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No està condicionat a la concurrència d''un interès personal, no està subjecte a motivació i no requereix la invocació de cap norma.', true), ('B', 'Requereix acreditar un interès legítim en la informació sol·licitada.', false), ('C', 'Requereix motivar la sol·licitud i indicar la norma que empara el dret.', false), ('D', 'Només correspon a les persones que tenen la condició d''interessades en un procediment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, a partir de quina edat es pot exercir el dret d''accés a la informació pública?', 'El dret d''accés a la informació pública es pot exercir a partir dels setze anys (art. 18.3 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 18.3 Llei 19/2014', 'El derecho de acceso a la información pública puede ejercerse a partir de los dieciséis años.', null, 'a78d5ab1c5ce68483ead6cf0d337e7bfa414c2ea2c9fb18c76646a3656176fe3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a78d5ab1c5ce68483ead6cf0d337e7bfa414c2ea2c9fb18c76646a3656176fe3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A partir dels catorze anys.', false), ('B', 'A partir dels divuit anys.', false), ('C', 'A qualsevol edat, sense límit mínim.', false), ('D', 'A partir dels setze anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, en quin termini s''han de resoldre les sol·licituds d''accés a la informació pública?', 'Les sol·licituds s''han de resoldre en el termini d''un mes a comptar de l''endemà de la recepció (art. 33.1 Llei 19/2014), i en aquest termini s''ha de dictar i notificar la resolució (art. 33.3).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 33.1 Llei 19/2014', 'Las solicitudes de acceso a la información pública deben resolverse en el plazo de un mes, a contar desde el día siguiente al de la recepción de la solicitud.', null, '9f0f8a491a3df11802e691feba3d3788384e29808237f57b5ee70b9d890e2250', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9f0f8a491a3df11802e691feba3d3788384e29808237f57b5ee70b9d890e2250')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini d''un mes, comptat des de l''endemà de la recepció de la sol·licitud.', true), ('B', 'En el termini de quinze dies hàbils des de la presentació de la sol·licitud.', false), ('C', 'En el termini de dos mesos, comptat des de l''endemà de la recepció de la sol·licitud.', false), ('D', 'En el termini de tres mesos des de la presentació de la sol·licitud.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si ho justifiquen el volum o la complexitat de la informació sol·licitada, el termini per resoldre una sol·licitud d''accés es pot prorrogar:', 'El termini d''un mes es pot prorrogar fins a un termini igual a la meitat de l''inicial si ho justifiquen el volum o la complexitat de la informació; la pròrroga i les causes s''han de comunicar a l''interessat (art. 33.2 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 33.2 Llei 19/2014', 'El plazo al que se refiere el apartado 1 puede prorrogarse, si lo justifican el volumen o la complejidad de la información requerida, hasta un plazo igual a la mitad del inicial.', null, '8764b2bf18fce3d1fba18da2f53720a885b43b6b3a32ba329804a9c2577ea53c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8764b2bf18fce3d1fba18da2f53720a885b43b6b3a32ba329804a9c2577ea53c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fins a un termini igual a l''inicial.', false), ('B', 'Fins a un màxim de tres mesos.', false), ('C', 'Fins a un termini igual a la meitat de l''inicial.', true), ('D', 'No es pot prorrogar en cap cas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quin és l''efecte del silenci administratiu si l''Administració no resol i notifica dins el termini una sol·licitud d''accés a la informació pública?', 'El silenci és positiu: la sol·licitud s''entén estimada, llevat que una norma amb rang de llei estableixi expressament un efecte desestimatori (art. 35.1). Ara bé, no es pot adquirir per silenci el dret d''accés si hi concorre algun límit legal (art. 35.2 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 35.1 Llei 19/2014', 'Si la Administración no resuelve y notifica dentro del plazo establecido, la solicitud se entiende estimada, salvo que una norma con rango de ley establezca expresamente un efecto desestimatorio, total o parcial, con relación a una determinada información.', null, 'eebfc2ad44e1ca785023d48bab67aa226eacab8c6042b5d8099516789471c8b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eebfc2ad44e1ca785023d48bab67aa226eacab8c6042b5d8099516789471c8b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sol·licitud s''entén desestimada en tots els casos.', false), ('B', 'La sol·licitud s''entén estimada, llevat que una norma amb rang de llei estableixi expressament un efecte desestimatori.', true), ('C', 'La sol·licitud s''entén desestimada, llevat que la informació estigui publicada al Portal de la Transparència.', false), ('D', 'La sol·licitud s''entén estimada, encara que hi concorri algun dels límits legals d''accés.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si una sol·licitud d''accés a la informació pública és estimada totalment o parcialment, en quin termini l''òrgan competent ha de subministrar la informació a l''interessat?', 'Si s''estima la sol·licitud, l''òrgan competent ha de subministrar la informació en el format sol·licitat en el termini de trenta dies (art. 36.1 Llei 19/2014); aquest mateix termini s''aplica en cas de silenci estimatori (art. 35.3).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 36.1 Llei 19/2014', 'Si una solicitud es estimada total o parcialmente, el órgano competente debe suministrar la información al interesado, en el formato en que la haya solicitado, en el plazo de treinta días.', null, '01bb4c9bd37a4b4fdf1b57209dcc55726147ae05c4f097871579077e7c237d54', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '01bb4c9bd37a4b4fdf1b57209dcc55726147ae05c4f097871579077e7c237d54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini de quinze dies.', false), ('B', 'En el termini de deu dies.', false), ('C', 'En el termini de dos mesos.', false), ('D', 'En el termini de trenta dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 21 de la Llei 19/2014, quin dels supòsits següents NO és un límit que permeti denegar o restringir el dret d''accés a la informació pública?', 'L''art. 21.1 permet denegar o restringir l''accés si la divulgació perjudica la seguretat pública, la investigació o sanció d''infraccions, el secret legal dels procediments, la igualtat de les parts o la tutela judicial, els drets dels menors, la intimitat i els drets privats legítims, o el secret professional i la propietat intel·lectual i industrial. La imatge de l''òrgan no hi figura, i els límits s''han d''interpretar restrictivament (art. 20.2).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 21.1 Llei 19/2014', 'El derecho de acceso a la información pública puede ser denegado o restringido si el conocimiento o divulgación de la información conlleva un perjuicio para: a) La seguridad pública. […] e) Los derechos de los menores de edad. […] g) El secreto profesional y los derechos de propiedad intelectual e industrial.', null, '662e12b1747b500a6a517ebd46bd20b6a9850b9b089e88c5a916106ccddfdc52', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '662e12b1747b500a6a517ebd46bd20b6a9850b9b089e88c5a916106ccddfdc52')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el coneixement de la informació comporti un perjudici per a la seguretat pública.', false), ('B', 'Que el coneixement de la informació comporti un perjudici per als drets dels menors d''edat.', false), ('C', 'Que el coneixement de la informació comporti un perjudici per al secret professional.', false), ('D', 'Que la informació pugui afectar la imatge pública de l''òrgan que la té en el seu poder.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, què s''ha de fer amb una sol·licitud d''accés a informació que conté dades personals especialment protegides, com les relatives a la salut o a les creences?', 'Les sol·licituds que contenen dades especialment protegides (ideologia, afiliació sindical, religió, creences, origen racial, salut, vida sexual o infraccions que no comportin amonestació pública) s''han de denegar, llevat del consentiment exprés i per escrit de l''afectat que acompanyi la sol·licitud (art. 23). La ponderació de l''art. 24.2 només s''aplica a les altres dades personals.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 23 Llei 19/2014', 'Las solicitudes de acceso a la información pública deben ser denegadas si la información que se desea obtener contiene datos personales especialmente protegidos, como los relativos a la ideología, la afiliación sindical, la religión, las creencias, el origen racial, la salud y la vida sexual', null, '495a8ace0071b12c979653cb33440ecd266cfd2b8266efb2c067800305940023', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '495a8ace0071b12c979653cb33440ecd266cfd2b8266efb2c067800305940023')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de denegar, llevat que l''afectat hi consenti expressament mitjançant un escrit que ha d''acompanyar la sol·licitud.', true), ('B', 'S''ha d''estimar sempre que el sol·licitant acrediti un interès legítim.', false), ('C', 'S''ha d''estimar després d''una ponderació raonada de l''interès públic en la divulgació.', false), ('D', 'S''ha d''inadmetre a tràmit, sense possibilitat d''esmena.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, s''ha d''inadmetre a tràmit una sol·licitud d''accés si la informació sol·licitada està en fase d''elaboració i s''ha de fer pública, d''acord amb les obligacions de transparència, dins el termini de:', 'Són inadmeses a tràmit les sol·licituds d''informació que està en fase d''elaboració i que s''ha de fer pública, d''acord amb les obligacions de transparència del títol II, dins el termini de tres mesos (art. 29.1.c Llei 19/2014). La inadmissió ha de ser motivada (art. 29.3).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 29.1.c Llei 19/2014', 'Si la información que solicitan está en fase de elaboración y debe hacerse pública, de acuerdo con las obligaciones de transparencia del título II, dentro del plazo de tres meses.', null, '015dcc6c0a5583fa79b765dd86445450d61620bba26f9299fbe7b6bd43a4593f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '015dcc6c0a5583fa79b765dd86445450d61620bba26f9299fbe7b6bd43a4593f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes.', false), ('B', 'Sis mesos.', false), ('C', 'Tres mesos.', true), ('D', 'Un any.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, la reclamació davant la Comissió de Garantia del Dret d''Accés a la Informació Pública (GAIP) contra les resolucions en matèria d''accés a la informació és:', 'Les resolucions expresses o presumptes en matèria d''accés, i les que resolen el recurs potestatiu de reposició, poden ser objecte de reclamació gratuïta i voluntària davant la GAIP (art. 39.1 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 39.1 Llei 19/2014', 'pueden ser objeto de reclamación gratuita y voluntaria ante la Comisión de Garantía del Derecho de Acceso a la Información Pública', null, 'eeb9218f90a3d30d581004099bc62eec266bc246a6642189920bbf72a968fc83', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eeb9218f90a3d30d581004099bc62eec266bc246a6642189920bbf72a968fc83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gratuïta i obligatòria abans d''acudir a la jurisdicció contenciosa administrativa.', false), ('B', 'Gratuïta i voluntària.', true), ('C', 'Subjecta al pagament d''una taxa i voluntària.', false), ('D', 'Obligatòria i només procedent si abans s''ha interposat recurs de reposició.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quina de les afirmacions següents sobre la Comissió de Garantia del Dret d''Accés a la Informació Pública NO és correcta?', 'La GAIP actua amb plena independència orgànica i funcional (art. 39.2) i està integrada per entre tres i cinc membres designats per majoria de tres cinquenes parts dels diputats del Parlament (art. 40.1 Llei 19/2014), no pel Govern.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 39.2 i 40.1 Llei 19/2014', 'La Comisión de Garantía del Derecho de Acceso a la Información Pública está integrada por un mínimo de tres miembros y un máximo de cinco, designados por mayoría de tres quintas partes de los diputados del Parlamento de Cataluña', null, '348aeb0cee089a4d165ebac7f6bf81d87dba488c3c1ced3552901b7153353008', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '348aeb0cee089a4d165ebac7f6bf81d87dba488c3c1ced3552901b7153353008')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els seus membres els designa el Govern per decret, a proposta del conseller o consellera competent.', true), ('B', 'Està integrada per un mínim de tres membres i un màxim de cinc.', false), ('C', 'Els seus membres són designats per majoria de tres cinquenes parts dels diputats del Parlament.', false), ('D', 'Exerceix les seves funcions amb plena independència orgànica i funcional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, en quin termini s''ha d''interposar la reclamació davant la Comissió de Garantia del Dret d''Accés a la Informació Pública?', 'La reclamació s''ha d''interposar en el termini d''un mes des de la notificació de la resolució, des que ha acabat el termini per resoldre en el supòsit de l''art. 35.2 o des de la desestimació del recurs de reposició (art. 42.1). La GAIP té dos mesos per resoldre; si no ho fa, es pot entendre desestimada (art. 42.9).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 42.1 Llei 19/2014', 'Las reclamaciones a las que se refiere el artículo 39.1 deben interponerse en el plazo de un mes a contar desde la notificación de la resolución', null, '712c2939e9e3851c2120098a751e69068bd23ba717a55622c0385416655f5d67', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '712c2939e9e3851c2120098a751e69068bd23ba717a55622c0385416655f5d67')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el termini de quinze dies a comptar de la notificació de la resolució.', false), ('B', 'En el termini d''un mes a comptar de la notificació de la resolució.', true), ('C', 'En el termini de dos mesos a comptar de la notificació de la resolució.', false), ('D', 'En el termini de tres mesos a comptar de la notificació de la resolució.', false)) as v(label, body, ok)
)
