select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 55.1 de la Llei 19/2014, quin dels següents NO és un dels principis ètics i regles de conducta dels alts càrrecs?', 'L''art. 55.1 inclou la imparcialitat (d), la dedicació absoluta (h) i la bona fe (l), i exigeix l''exclusió de qualsevol obsequi de valor, favor o servei oferts per raó del càrrec (m), sense cap excepció per declaració.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 55.1 Llei 19/2014', 'd) La imparcialidad en la toma de decisiones, con garantía de las condiciones necesarias para una actuación independiente y no condicionada por conflictos de intereses. […] h) El ejercicio del cargo con dedicación absoluta, de acuerdo con lo establecido por la legislación sobre incompatibilidades. […] l) La buena fe. m) La exclusión de cualquier obsequio de valor, favor o servicio que se les pueda ofrecer por razón de su cargo o que pueda comprometer la ejecución de sus funciones.', null, '805620ec08558ca10cdbc483b2868751f37ded4c7c317a58f28e390565605df4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '805620ec08558ca10cdbc483b2868751f37ded4c7c317a58f28e390565605df4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La imparcialitat en la presa de decisions, sense condicionaments per conflictes d''interessos.', false), ('B', 'L''exercici del càrrec amb dedicació absoluta, d''acord amb la legislació d''incompatibilitats.', false), ('C', 'La bona fe.', false), ('D', 'L''acceptació d''obsequis de valor, sempre que es declarin al registre corresponent.', true)) as v(label, body, ok)
)
