select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, del 29 de desembre, de transparència, accés a la informació pública i bon govern, com es defineix la transparència?', 'L''art. 2.a de la Llei 19/2014 defineix la transparència com l''acció proactiva de donar a conèixer la informació, amb caràcter permanent i actualitzat. El dret subjectiu de sol·licitar i obtenir informació és el dret d''accés (art. 2.c) i el diàleg bidireccional és el govern obert (art. 2.e).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 2.a Llei 19/2014', 'Transparencia: la acción proactiva de la Administración de dar a conocer la información relativa a sus ámbitos de actuación y sus obligaciones, con carácter permanente y actualizado', null, '253a629b025d3414eb2a9e870a90b6a899c63cfb23948e2966c1268ce3b18b2f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '253a629b025d3414eb2a9e870a90b6a899c63cfb23948e2966c1268ce3b18b2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com el dret subjectiu de les persones a sol·licitar i obtenir la informació pública.', false), ('B', 'Com el deure de l''Administració de respondre per escrit totes les sol·licituds d''informació que rebi.', false), ('C', 'Com l''acció proactiva de l''Administració de donar a conèixer la informació relativa als seus àmbits d''actuació i a les seves obligacions, amb caràcter permanent i actualitzat.', true), ('D', 'Com les mesures per establir un diàleg permanent i bidireccional entre l''Administració i les persones en la definició de les polítiques públiques.', false)) as v(label, body, ok)
)
