with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, el deure dels subjectes obligats de fer públics, d''ofici, els continguts d''informació pública que determina el capítol II del títol II s''anomena:', 'L''art. 2.i de la Llei 19/2014 defineix la publicitat activa com el deure de fer públics, d''ofici, els continguts d''informació pública del capítol II del títol II. En el dret d''accés, en canvi, la informació es facilita a sol·licitud de la persona interessada.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 2.i Llei 19/2014', 'Publicidad activa: el deber de los sujetos obligados de hacer públicos, de oficio, los contenidos de información pública que determina el capítulo II del título II.', null, '68e53e56424fa10e0089b627eb5e4bf49f0a206e0e54036a1a53055ac85b079a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '68e53e56424fa10e0089b627eb5e4bf49f0a206e0e54036a1a53055ac85b079a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Publicitat activa.', true), ('B', 'Dret d''accés a la informació pública.', false), ('C', 'Govern obert.', false), ('D', 'Reutilització de la informació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quina de les dades següents NO cal que consti necessàriament en una sol·licitud d''accés a la informació pública?', 'La sol·licitud ha de permetre deixar constància de la identitat del sol·licitant, la informació precisa que es vol obtenir, la forma o el format preferits i una adreça de contacte (art. 26.1). La motivació és potestativa i la manca de motivació no pot ser mai causa de denegació (art. 26.2 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 26 Llei 19/2014', 'El solicitante puede exponer, con carácter potestativo, los motivos que justifican el ejercicio del derecho de acceso a la información pública. La ausencia de motivación en ningún caso puede ser causa de denegación de la solicitud.', null, 'd1b4271e72653610488b823705c26d3377b9b7a56fc781fb7e81b08ef3488308', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd1b4271e72653610488b823705c26d3377b9b7a56fc781fb7e81b08ef3488308')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La identitat del sol·licitant.', false), ('B', 'La informació precisa a què es vol tenir accés.', false), ('C', 'Una adreça de contacte, preferentment electrònica.', false), ('D', 'Els motius que justifiquen l''exercici del dret d''accés.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 19/2014, l''accés a la informació pública és gratuït:', 'L''accés és gratuït si les dades es consulten in situ o si existeixen en format electrònic (art. 37.1). L''expedició de còpies i la transposició a altres formats poden estar subjectes a una contraprestació que no pot excedir el cost de l''operació (art. 37.2 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 37.1 Llei 19/2014', 'El acceso a la información pública es gratuito si los datos son consultados en el lugar donde se encuentran depositados, o bien si existen en formato electrónico, en cuyo caso deben ser entregados por correo electrónico.', null, '07c66e3c6930a67dfe1abe1a5fec2584d78fa1cc9ec635805297ca862329e1cf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07c66e3c6930a67dfe1abe1a5fec2584d78fa1cc9ec635805297ca862329e1cf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En tots els casos, inclosa l''expedició de còpies en paper.', false), ('B', 'Si les dades es consulten al lloc on estan dipositades o si existeixen en format electrònic, cas en què s''han de lliurar per correu electrònic.', true), ('C', 'Només per a les persones físiques que actuen a títol individual.', false), ('D', 'Només quan la sol·licitud es presenta per mitjans electrònics.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quin recurs administratiu es pot interposar contra les resolucions expresses o presumptes en matèria d''accés a la informació pública?', 'L''art. 38 de la Llei 19/2014 preveu el recurs potestatiu de reposició davant l''òrgan que ha dictat la resolució. A més, es pot presentar la reclamació gratuïta i voluntària davant la GAIP (art. 39.1).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 38 Llei 19/2014', 'Las resoluciones expresas o presuntas dictadas de acuerdo con lo dispuesto por el presente título pueden ser objeto de recurso potestativo de reposición ante el órgano que las ha dictado.', null, '8be50f13967862e7f77d2ea6ddc145ba31dbbeffa9c553867b3d735460b30124', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8be50f13967862e7f77d2ea6ddc145ba31dbbeffa9c553867b3d735460b30124')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El recurs potestatiu de reposició, davant l''òrgan que les ha dictades.', true), ('B', 'El recurs d''alçada, davant el conseller o consellera del departament.', false), ('C', 'El recurs extraordinari de revisió, davant el Govern.', false), ('D', 'Cap: només es pot acudir directament a la jurisdicció contenciosa administrativa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, qualsevol limitació en l''aplicació del principi de transparència:', 'El principi de transparència s''ha d''interpretar i aplicar en tots els casos de manera preferent, i qualsevol limitació s''ha de fonamentar en un límit o una excepció establerts expressament per una norma amb rang de llei (art. 7.2 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 7.2 Llei 19/2014', 'Cualquier limitación en la aplicación del principio de transparencia debe fundamentarse en un límite o una excepción expresamente establecidos por una norma con rango de ley.', null, '90b3f8957e190616a7c88f5af62fcec1594c6a4cf7d2e33ca347ca71c2bdf03c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '90b3f8957e190616a7c88f5af62fcec1594c6a4cf7d2e33ca347ca71c2bdf03c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de fonamentar en un límit o una excepció establerts expressament per una norma amb rang de llei.', true), ('B', 'Pot ser establerta per ordre del conseller competent, si és motivada.', false), ('C', 'Pot ser acordada lliurement per l''òrgan que té la informació, per raons d''oportunitat.', false), ('D', 'S''ha de fonamentar en un reglament aprovat pel Govern.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la Llei 19/2014, les limitacions legals al dret d''accés a la informació pública:', 'Les limitacions s''han d''aplicar d''acord amb la seva finalitat i les circumstàncies del cas, s''han d''interpretar sempre restrictivament i no es poden ampliar per analogia (art. 20.2); a més, l''Administració no té potestat discrecional per aplicar-les i ha de motivar-les (art. 20.3 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 20.2 Llei 19/2014', 'deben interpretarse siempre restrictivamente en beneficio de este derecho y no pueden ampliarse por analogía.', null, 'e9857711aa323e0175874aef254624686b1e9d7bca054e2c8ec62fcdd8db8bfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e9857711aa323e0175874aef254624686b1e9d7bca054e2c8ec62fcdd8db8bfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden ampliar per analogia a supòsits semblants quan ho justifiqui l''interès públic.', false), ('B', 'S''han d''interpretar extensivament per protegir els drets de tercers.', false), ('C', 'Les pot aplicar l''Administració de manera discrecional, sense necessitat de motivació.', false), ('D', 'S''han d''interpretar sempre restrictivament en benefici d''aquest dret i no es poden ampliar per analogia.', true)) as v(label, body, ok)
)
