with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si una sol·licitud d''accés s''ha formulat en termes imprecisos o massa genèrics i l''Administració demana al sol·licitant que la concreti:', 'El requeriment de concreció suspèn el termini per resoldre (art. 28.1). Si el sol·licitant no compleix el tràmit en el termini fixat, que no pot ser inferior a deu dies, es considera que ha desistit i s''arxiva l''expedient (art. 28.3 Llei 19/2014), sens perjudici que en pugui presentar una nova sol·licitud (art. 28.4).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 28.1 i 28.3 Llei 19/2014', 'Este trámite suspende el plazo para resolver. […] Si el solicitante no cumple el trámite al que se refiere el apartado 1 dentro del plazo establecido, que no puede ser inferior a diez días, se considera que ha desistido del procedimiento', null, 'ae4d8cce8fbd393441a2650b0cec0a2e88d102246cbfa32c2e7f92d761987edc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ae4d8cce8fbd393441a2650b0cec0a2e88d102246cbfa32c2e7f92d761987edc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El termini per resoldre continua corrent i la sol·licitud s''entén estimada si no es concreta en cinc dies.', false), ('B', 'El termini per resoldre se suspèn i, si el sol·licitant no la concreta dins el termini establert, que no pot ser inferior a deu dies, es considera que ha desistit.', true), ('C', 'La sol·licitud s''ha d''inadmetre directament, sense donar-li cap tràmit d''esmena.', false), ('D', 'El termini per resoldre se suspèn i, si el sol·licitant no la concreta en quinze dies, la sol·licitud s''entén desestimada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si una sol·licitud d''accés es dirigeix a un òrgan que no disposa de la informació, aquest l''ha de derivar a l''òrgan que en disposi en el termini de:', 'L''art. 30.1 de la Llei 19/2014 obliga l''òrgan que no disposa de la informació a derivar la sol·licitud en el termini de quinze dies naturals i a comunicar al sol·licitant a quin òrgan l''ha derivada i les dades de contacte.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 30.1 Llei 19/2014', 'debe derivarla a la entidad o al órgano que disponga de ella, si lo conoce, o a la oficina responsable de la información pública que corresponda, en un plazo de quince días naturales, y comunicar al solicitante a qué órgano se ha derivado la solicitud', null, 'e26f4ed63f51758399428dc852e6a6de64d87ce89dcdc2252a4b1778c970a031', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e26f4ed63f51758399428dc852e6a6de64d87ce89dcdc2252a4b1778c970a031')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies hàbils, sense necessitat de comunicar-ho al sol·licitant.', false), ('B', 'Un mes, i ha de comunicar al sol·licitant a quin òrgan l''ha derivada.', false), ('C', 'Quinze dies naturals, i ha de comunicar al sol·licitant a quin òrgan l''ha derivada.', true), ('D', 'Cinc dies hàbils, i la sol·licitud s''entén presentada a l''òrgan competent des de la derivació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quan una sol·licitud d''informació pública pot afectar drets o interessos de tercers identificats, se''ls ha de donar trasllat de la sol·licitud perquè presentin al·legacions en el termini de:', 'Els tercers afectats identificats o fàcilment identificables tenen deu dies per presentar al·legacions si poden ser determinants del sentit de la resolució (art. 31.1), i aquest tràmit suspèn el termini per resoldre (art. 31.2 Llei 19/2014). No cal revelar la identitat del sol·licitant (art. 31.3).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 31.1 i 31.2 Llei 19/2014', 'tienen un plazo de diez días para presentar alegaciones si estas pueden resultar determinantes del sentido de la resolución. […] El trámite de alegaciones al que se refiere el apartado 1 suspende el plazo para resolver.', null, 'e4f52c6943259141c9917cc9881d6757bf20f4da48c79d75553ae823cf068d69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4f52c6943259141c9917cc9881d6757bf20f4da48c79d75553ae823cf068d69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quinze dies, i aquest tràmit no suspèn el termini per resoldre.', false), ('B', 'Deu dies, i aquest tràmit suspèn el termini per resoldre.', true), ('C', 'Cinc dies, i aquest tràmit suspèn el termini per resoldre.', false), ('D', 'Un mes, i aquest tràmit amplia automàticament el termini per resoldre a dos mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 34 de la Llei 19/2014, quina de les resolucions següents sobre sol·licituds d''accés a la informació pública NO ha de ser necessàriament motivada?', 'Cal motivar les resolucions que desestimen total o parcialment la sol·licitud, les que l''estimen malgrat l''oposició de tercers i les que estableixen un format diferent del sol·licitat (art. 34.4). Si s''estima la sol·licitud sense oposició de tercers, la resolució es pot substituir per una comunicació (art. 34.8 Llei 19/2014).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 34.4 Llei 19/2014', 'Deben ser motivadas las siguientes resoluciones: a) Las que desestiman total o parcialmente la solicitud. b) Las que estiman la solicitud pese a la oposición de terceros. c) Las que establecen como forma de acceso a la información un formato diferente al solicitado.', null, '66db909e519ad1a323bfca5dc6d7d377f48fc85e4c9bbf7907eced77c0667fc2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '66db909e519ad1a323bfca5dc6d7d377f48fc85e4c9bbf7907eced77c0667fc2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La que estima íntegrament la sol·licitud sense que hi hagi hagut oposició de tercers.', true), ('B', 'La que desestima parcialment la sol·licitud.', false), ('C', 'La que estima la sol·licitud malgrat l''oposició de tercers.', false), ('D', 'La que estableix com a forma d''accés un format diferent del sol·licitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, les sol·licituds d''informació que consisteixen en consultes jurídiques o peticions d''informes o dictàmens:', 'L''art. 29.2 de la Llei 19/2014 ordena inadmetre les consultes jurídiques i les peticions d''informes o dictàmens, sens perjudici de la consulta o l''orientació previstes per la legislació de procediment i les lleis sectorials. La inadmissió ha de ser motivada i comunicada (art. 29.3).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 29.2 Llei 19/2014', 'Son inadmitidas a trámite las solicitudes de información consistentes en consultas jurídicas o peticiones de informes o dictámenes', null, '2f9dc9ff662744d6cc7e4f393ded1bb350ee95a8b4a96db6974fcb6217dca519', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2f9dc9ff662744d6cc7e4f393ded1bb350ee95a8b4a96db6974fcb6217dca519')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''han de resoldre en el termini d''un mes, com qualsevol sol·licitud d''accés.', false), ('B', 'S''han de derivar a la Comissió Jurídica Assessora.', false), ('C', 'S''han d''inadmetre a tràmit, sens perjudici dels supòsits de consulta o orientació previstos per la legislació de procediment i les lleis sectorials.', true), ('D', 'S''han d''estimar si el sol·licitant acredita un interès legítim.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si la Comissió de Garantia del Dret d''Accés a la Informació Pública no ha dictat i notificat la resolució de la reclamació en el termini de dos mesos des de la presentació:', 'L''art. 42.9 de la Llei 19/2014 permet entendre desestimada la reclamació si en dos mesos no s''ha dictat i notificat la resolució; el termini es pot ampliar fins a quinze dies més si s''han demanat informes o dades. Les resolucions de la GAIP posen fi a la via administrativa (art. 42.10).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 42.9 Llei 19/2014', 'Si en el plazo de dos meses desde la presentación de la reclamación no se ha dictado y notificado la resolución, esta puede entenderse desestimada.', null, 'fdbb46bfd1177ba0f0281b7bf0ac44de80b65378ed9c004ccb97b184f73a13f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fdbb46bfd1177ba0f0281b7bf0ac44de80b65378ed9c004ccb97b184f73a13f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La reclamació s''entén estimada i l''Administració ha de lliurar la informació.', false), ('B', 'El procediment caduca i s''arxiven les actuacions.', false), ('C', 'El reclamant pot interposar recurs d''alçada davant el Parlament.', false), ('D', 'La reclamació es pot entendre desestimada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, les infraccions previstes en aquesta llei prescriuen:', 'L''art. 90.1 de la Llei 19/2014 fixa la prescripció de les infraccions en tres anys (molt greus), dos anys (greus) i un any (lleus); les sancions prescriuen en els mateixos terminis (art. 90.2).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 90.1 Llei 19/2014', 'Las infracciones muy graves prescriben al cabo de tres años; las infracciones graves, al cabo de dos años, y las infracciones leves, al cabo de un año.', null, '236e7bdf81257dc0f32f87d113d266d31ecbc5a943c1434e632fdd1d581874fe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '236e7bdf81257dc0f32f87d113d266d31ecbc5a943c1434e632fdd1d581874fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les molt greus, al cap de cinc anys; les greus, al cap de tres anys, i les lleus, al cap de sis mesos.', false), ('B', 'Les molt greus, al cap de tres anys; les greus, al cap de dos anys, i les lleus, al cap d''un any.', true), ('C', 'Les molt greus, al cap de divuit mesos; les greus, al cap de dotze mesos, i les lleus, al cap de sis mesos.', false), ('D', 'Totes, al cap de quatre anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, quan la denegació d''accés que es reclama davant la Comissió de Garantia del Dret d''Accés a la Informació Pública s''ha fonamentat en la protecció de dades personals, la Comissió:', 'L''art. 42.8 de la Llei 19/2014 imposa a la GAIP sol·licitar informe a l''Autoritat Catalana de Protecció de Dades, que l''ha d''emetre en quinze dies. En aquest cas, la GAIP pot ampliar fins a quinze dies més el termini per resoldre (art. 42.9).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 42.8 Llei 19/2014', 'Si la denegación se ha fundamentado en la protección de datos personales, la Comisión debe solicitar informe a la Autoridad Catalana de Protección de Datos, el cual debe ser emitido en el plazo de quince días.', null, '619d7f807d92b13dc29fe3d67f20de411c3ec7efe25fa8985c475fcc1e53a243', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '619d7f807d92b13dc29fe3d67f20de411c3ec7efe25fa8985c475fcc1e53a243')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha de sol·licitar informe a l''Autoritat Catalana de Protecció de Dades, que l''ha d''emetre en el termini de quinze dies.', true), ('B', 'Ha de sol·licitar informe a l''Agència Espanyola de Protecció de Dades, que l''ha d''emetre en el termini d''un mes.', false), ('C', 'Ha d''inadmetre la reclamació, perquè la competència correspon a l''autoritat de protecció de dades.', false), ('D', 'Pot sol·licitar informe potestatiu a l''Autoritat Catalana de Protecció de Dades, que l''ha d''emetre en el termini de deu dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, els membres de la Comissió de Garantia del Dret d''Accés a la Informació Pública han de ser juristes especialistes en dret públic i tècnics en matèria d''arxius o gestió documental, elegits entre experts de reconeguda competència i prestigi i amb:', 'L''art. 40.3 de la Llei 19/2014 exigeix més de deu anys d''experiència professional. Els membres exerceixen el càrrec en règim de dedicació exclusiva (art. 40.4).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 40.3 Llei 19/2014', 'elegidos entre expertos de reconocida competencia y prestigio y con más de diez años de experiencia profesional.', null, 'f643c07dbedb9c3007d09559f73ff675089aac8395eafbe0b5cf8aefb13a3489', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f643c07dbedb9c3007d09559f73ff675089aac8395eafbe0b5cf8aefb13a3489')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Més de cinc anys d''experiència professional.', false), ('B', 'Més de quinze anys d''experiència professional.', false), ('C', 'La condició de funcionari de carrera del subgrup A1.', false), ('D', 'Més de deu anys d''experiència professional.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.2 de la Llei 19/2014, per fer la ponderació entre l''interès públic en la divulgació i els drets de les persones afectades quan la informació conté dades personals no especialment protegides, quina de les circumstàncies següents NO s''esmenta?', 'L''art. 24.2 de la Llei 19/2014 esmenta, entre altres, el temps transcorregut, la finalitat de l''accés (especialment si és històrica, estadística o científica) i les garanties que s''ofereixin, el fet que es tracti de dades de menors i el fet que pugui afectar la seguretat de les persones. La nacionalitat del sol·licitant no hi figura.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 24.2 Llei 19/2014', 'a) El tiempo transcurrido. b) La finalidad del acceso, especialmente si tiene una finalidad histórica, estadística o científica, y las garantías que se ofrezcan. c) El hecho de que se trate de datos relativos a menores de edad. d) El hecho de que pueda afectar a la seguridad de las personas.', null, 'cf8884febcea86f17395e370b53f7dd7dcdc72994d665dd745eae65ab1ff1e34', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf8884febcea86f17395e370b53f7dd7dcdc72994d665dd745eae65ab1ff1e34')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La nacionalitat del sol·licitant.', true), ('B', 'El temps transcorregut.', false), ('C', 'El fet que es tracti de dades relatives a menors d''edat.', false), ('D', 'El fet que pugui afectar la seguretat de les persones.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2014, si la resolució estima la sol·licitud d''accés i hi ha hagut oposició de tercers, l''accés a la informació:', 'L''art. 34.3 de la Llei 19/2014 protegeix els tercers que s''hi han oposat: l''accés s''endarrereix fins que transcorre el termini del recurs contenciós sense que s''hagi interposat o, si s''ha interposat, fins que es constata que no s''ha demanat la suspensió cautelar o que s''ha mantingut l''executivitat de l''acte.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-470'), 'Art. 34.3 Llei 19/2014', 'Si la resolución es estimatoria de la solicitud y ha existido oposición de terceros, el acceso a la información solamente puede hacerse efectivo una vez ha transcurrido el plazo para interponer recurso contencioso-administrativo sin que se haya formalizado', null, '89d49e67f5bea2701756014e25ed4c5559a4a655dc63bdc691ac5d90f4108cd4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '89d49e67f5bea2701756014e25ed4c5559a4a655dc63bdc691ac5d90f4108cd4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de fer efectiu immediatament després de la notificació, sense esperar cap termini.', false), ('B', 'Només es pot fer efectiu quan la resolució ha estat confirmada per la Comissió de Garantia del Dret d''Accés a la Informació Pública.', false), ('C', 'Només es pot fer efectiu un cop transcorregut el termini per interposar recurs contenciós administratiu sense que s''hagi formalitzat o, si s''ha interposat, si no s''ha demanat la suspensió cautelar o s''ha mantingut l''executivitat de l''acte.', true), ('D', 'Queda en suspens fins que els tercers hi donin el consentiment exprés.', false)) as v(label, body, ok)
)
