insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g3-bon-govern-transparencia-igualtat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.3 de la Llei 19/2020, del 30 de desembre, d''igualtat de tracte i no-discriminació, la llei té la finalitat d''evitar les formes de discriminació que prenen com a pretext, entre d''altres:', 'L''art. 1.3.h de la Llei 19/2020 inclou entre els motius de discriminació la condició social o econòmica, la situació administrativa, la professió o la condició de privació de llibertat, i qualsevol manifestació d''aporofòbia.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 1.3.h Llei 19/2020', 'h) Condición social o económica, situación administrativa, profesión o condición de privación de libertad, y cualquier manifestación de aporofobia o de odio a las personas sin hogar.', null, '327d7acf2f46816596965ca75f793e9e0f190e026c47c760fb00f29451f08985', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '327d7acf2f46816596965ca75f793e9e0f190e026c47c760fb00f29451f08985')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La condició social o econòmica, la situació administrativa, la professió o la condició de privació de llibertat.', true), ('B', 'La situació penitenciària, només en el cas dels interns classificats en tercer grau.', false), ('C', 'La condició de privació de llibertat, només si és per una condemna ferma.', false), ('D', 'Els antecedents penals, només quan s''hagin cancel·lat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2020, com s''anomena la discriminació que es produeix quan una persona o el grup al qual se l''associa és objecte de discriminació com a conseqüència de la seva relació amb una persona o un grup per algun dels motius de l''article 1?', 'És la discriminació per associació (art. 4.o). La discriminació per error es produeix per atribuir erròniament una característica (art. 4.p); la múltiple, per la concurrència de diversos motius (art. 4.n), i la de segon ordre és el maltractament contra qui defensa persones discriminades (art. 4.k).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 4.o Llei 19/2020', 'Discriminación por asociación: La discriminación que se produce cuando una persona o el grupo al que se le asocia es objeto de discriminación, real o atribuida, como consecuencia de su relación con una persona o un grupo por alguno de los motivos a los que se refiere el artículo 1.', null, '76072e08012037e6d43a2bc299d84d621d08870c86ebd50027a85f28de1dd7dc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '76072e08012037e6d43a2bc299d84d621d08870c86ebd50027a85f28de1dd7dc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminació per associació.', true), ('B', 'Discriminació per error.', false), ('C', 'Discriminació múltiple.', false), ('D', 'Discriminació de segon ordre.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 32.2 de la Llei 19/2020, les administracions públiques han d''impulsar la formació obligatòria en igualtat de tracte i no-discriminació del personal, tant funcionari com laboral, amb especial atenció, entre d''altres, a:', 'L''art. 32.2 obliga a impulsar la formació obligatòria del personal funcionari i laboral, amb especial atenció a la magistratura, al personal dels centres penitenciaris, als cossos i forces de seguretat, al personal docent, als professionals de la salut i a les autoritats locals.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 32.2 Llei 19/2020', 'Las administraciones públicas deben impulsar la formación obligatoria del personal, tanto funcionario como laboral, independientemente de su vinculación mediante convenios de colaboración u otros instrumentos, con especial atención a la magistratura, el personal de los centros penitenciarios, los cuerpos y fuerzas de seguridad, el personal docente, los profesionales de la salud y las autoridades locales.', null, '108090ae10aedc4626216804a90aed85da0bc9a7f3da815d07de6abbbde7be1b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '108090ae10aedc4626216804a90aed85da0bc9a7f3da815d07de6abbbde7be1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només el personal que ocupa llocs de comandament.', false), ('B', 'La magistratura, el personal dels centres penitenciaris, els cossos i forces de seguretat, el personal docent, els professionals de la salut i les autoritats locals.', true), ('C', 'Només el personal de nou ingrés durant el període de pràctiques.', false), ('D', 'El personal laboral, perquè el funcionari en queda exclòs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2020, del 30 de desembre, d''igualtat de tracte i no-discriminació, la discriminació que es produeix quan una persona és tractada de manera menys favorable que una altra en una situació anàloga per algun dels motius de l''article 1 és:', 'L''art. 4.l de la Llei 19/2020 defineix així la discriminació directa. La indirecta es produeix per una disposició, un criteri o una pràctica pretesament neutres (art. 4.m) i la múltiple, per la concurrència de diversos motius (art. 4.n).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 4.l Llei 19/2020', 'Discriminación directa: La discriminación que se produce cuando una persona es tratada de una forma menos favorable que otra en situación análoga por alguno de los motivos a los que se refiere el artículo 1.', null, '967c311ad23d97d05f379ed445786933c14c6b7df8736d097e600fadbb31a47d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '967c311ad23d97d05f379ed445786933c14c6b7df8736d097e600fadbb31a47d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La discriminació indirecta.', false), ('B', 'La discriminació per error.', false), ('C', 'La discriminació directa.', true), ('D', 'La discriminació múltiple.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2020, com s''anomena el maltractament exercit contra persones o grups de persones pel fet de defensar persones o grups discriminats?', 'L''art. 4.k de la Llei 19/2020 defineix la discriminació de segon ordre com el maltractament contra qui defensa persones o grups discriminats. La discriminació per associació es produeix per la relació amb una persona o grup per algun motiu de l''art. 1 (art. 4.o).', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 4.k Llei 19/2020', 'Discriminación de segundo orden: El maltrato ejercido contra personas o grupos de personas por el hecho de defender a personas o grupos discriminados.', null, 'e389622c379709f826d9e9e6cf57b0f563f28190e96ffa275bc67978c2186464', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e389622c379709f826d9e9e6cf57b0f563f28190e96ffa275bc67978c2186464')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminació per associació.', false), ('B', 'Discriminació per estigmatització.', false), ('C', 'Discriminació de segon ordre.', true), ('D', 'Assetjament discriminatori.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 19/2020, perquè les associacions i organitzacions que tenen entre els seus fins la defensa dels drets humans puguin tenir la consideració de persona interessada en els procediments administratius per discriminació, han d''haver-se constituït legalment, amb caràcter general:', 'L''art. 26.4 de la Llei 19/2020 exigeix haver-se constituït legalment almenys dos anys abans de l''inici del procediment (llevat que actuïn en defensa dels seus membres o de les persones que representen) i desenvolupar l''activitat en territori català.', 'pcat_g3_bon_govern_transparencia_igualtat', (select id from public.topics where slug = 'pcat-g3-bon-govern-transparencia-igualtat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 26.4.a Llei 19/2020', 'Haberse constituido legalmente al menos dos años antes de la iniciación del procedimiento correspondiente, salvo que ejerzan las acciones administrativas o judiciales en defensa de los miembros que las integran o de las personas que las representan. b) Desarrollar su actividad en territorio catalán.', null, '5e79128aa11d4f9435040f7bca3f6d5c9738947b2c893e0d7af1c17f02d35eba', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e79128aa11d4f9435040f7bca3f6d5c9738947b2c893e0d7af1c17f02d35eba')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys dos anys abans de l''inici del procediment corresponent, i desenvolupar la seva activitat en territori català.', true), ('B', 'Almenys cinc anys abans de l''inici del procediment, i tenir la seu social a Catalunya.', false), ('C', 'Almenys un any abans de l''inici del procediment, sense cap requisit territorial.', false), ('D', 'En qualsevol moment, sempre que estiguin inscrites en un registre d''associacions de Catalunya.', false)) as v(label, body, ok)
)
