with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb la LPAC, llevat que la norma corresponent fixi un termini diferent, els tràmits que han de complimentar les persones interessades s''han de fer en el termini de:', 'L''art. 73.1 LPAC estableix, amb caràcter supletori, un termini de deu dies a partir de l''endemà de la notificació per complimentar els tràmits.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 73.1 LPAC', 'Los trámites que deban ser cumplimentados por los interesados deberán realizarse en el plazo de diez días a partir del siguiente al de la notificación del correspondiente acto, salvo en el caso de que en la norma correspondiente se fije plazo distinto.', null, '2eeb5a3ad58486fbae302f2e95f4ee6d04d68465f95f2a346a7aaf19ea32f388', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2eeb5a3ad58486fbae302f2e95f4ee6d04d68465f95f2a346a7aaf19ea32f388')
