with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 39 de la LPAC, els actes de les administracions públiques subjectes al dret administratiu:', 'L''art. 39.1 LPAC estableix la presumpció de validesa dels actes i la seva eficàcia des de la data en què es dicten, llevat que en disposin una altra cosa. L''eficàcia es demora quan ho exigeix el contingut de l''acte o està supeditada a notificació, publicació o aprovació superior (art. 39.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 39.1 LPAC', 'Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.', null, 'f30e8a6c8ba49fadbe6a75878e6ac4054bfde1ab87243994dcd786e56a0da29a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f30e8a6c8ba49fadbe6a75878e6ac4054bfde1ab87243994dcd786e56a0da29a')
  returning id
), o as (
