with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, la interposició de qualsevol recurs administratiu, llevat que una disposició estableixi el contrari:', 'L''art. 117.1 LPAC estableix que la interposició del recurs no suspèn l''execució de l''acte. L''òrgan que l''ha de resoldre pot acordar la suspensió si l''execució pot causar perjudicis de reparació impossible o difícil o si la impugnació es fonamenta en una causa de nul·litat de ple dret (art. 117.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 117.1 LPAC', 'La interposición de cualquier recurso, excepto en los casos en que una disposición establezca lo contrario, no suspenderá la ejecución del acto impugnado.', null, '0e99fe986b33b00ee44fcace674ee3362ff45ad06c6a2c6a5874a0c886f41b38', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0e99fe986b33b00ee44fcace674ee3362ff45ad06c6a2c6a5874a0c886f41b38')
  returning id
), o as (
