  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspèn automàticament l''execució de l''acte impugnat.', false), ('B', 'No suspèn l''execució de l''acte impugnat.', true), ('C', 'Suspèn l''execució de l''acte impugnat si el recurs és d''alçada.', false), ('D', 'Suspèn l''execució de l''acte impugnat fins que s''hagi resolt el recurs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan les persones interessades en un procediment són desconegudes, s''ignora el lloc de la notificació o, un cop intentada, no s''ha pogut practicar, la notificació es fa per mitjà d''un anunci publicat:', 'L''art. 44 LPAC obliga a publicar l''anunci al BOE. Prèviament i amb caràcter facultatiu, també es pot publicar al butlletí oficial de la comunitat autònoma o de la província, al tauler d''edictes de l''ajuntament o al consolat.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 44 LPAC', 'Cuando los interesados en un procedimiento sean desconocidos, se ignore el lugar de la notificación o bien, intentada ésta, no se hubiese podido practicar, la notificación se hará por medio de un anuncio publicado en el «Boletín Oficial del Estado».', null, 'e06c271f6a747f86d42390766a73dc7115913a2f84c0c3b904e7c4ae50f4d9ca', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e06c271f6a747f86d42390766a73dc7115913a2f84c0c3b904e7c4ae50f4d9ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Butlletí Oficial de l''Estat.', true), ('B', 'Al Diari Oficial de la Generalitat de Catalunya, exclusivament.', false), ('C', 'Al tauler d''edictes de l''ajuntament de l''últim domicili, exclusivament.', false), ('D', 'A la seu electrònica de l''òrgan que tramita el procediment, exclusivament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 3 de la LPAC, els menors d''edat tenen capacitat d''obrar davant les administracions públiques:', 'L''art. 3.b LPAC reconeix capacitat d''obrar als menors per als drets i interessos l''actuació dels quals està permesa per l''ordenament sense l''assistència de qui exerceix la pàtria potestat, la tutela o la curatela, llevat dels menors incapacitats quan la incapacitació afecti aquests drets.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 3.b LPAC', 'Los menores de edad para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de la persona que ejerza la patria potestad, tutela o curatela.', null, '7cc3ee26565eef9b1a03557fb7a6f7c753ee12770ba964d7d94907e4d324d2a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7cc3ee26565eef9b1a03557fb7a6f7c753ee12770ba964d7d94907e4d324d2a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En cap cas: sempre han d''actuar mitjançant els seus representants legals.', false), ('B', 'Només a partir dels setze anys i per a qualsevol procediment.', false), ('C', 'Només en els procediments iniciats d''ofici que els afectin directament.', false), ('D', 'Per a l''exercici i la defensa dels seus drets i interessos l''actuació dels quals estigui permesa per l''ordenament jurídic sense l''assistència de qui n''exerceixi la pàtria potestat, la tutela o la curatela.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan en una sol·licitud, un escrit o una comunicació figuren diverses persones interessades, les actuacions a què donin lloc s''han de fer:', 'L''art. 7 LPAC estableix que, en cas de pluralitat d''interessats, les actuacions s''entenen amb el representant o interessat assenyalat expressament i, si no n''hi ha, amb el que figuri en primer terme.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 7 LPAC', 'Cuando en una solicitud, escrito o comunicación figuren varios interesados, las actuaciones a que den lugar se efectuarán con el representante o el interesado que expresamente hayan señalado, y, en su defecto, con el que figure en primer término.', null, 'e56409c950758fe9cc56895a6579721335480a4b38b03ebb43d4577839e9b3d5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e56409c950758fe9cc56895a6579721335480a4b38b03ebb43d4577839e9b3d5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb el representant o la persona interessada que hagin assenyalat expressament i, si no n''han assenyalat cap, amb la que figuri en primer terme.', true), ('B', 'Amb totes les persones interessades, de manera individual i separada.', false), ('C', 'Amb la persona interessada de més edat.', false), ('D', 'Amb la persona interessada que designi l''òrgan instructor.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 14.2 de la LPAC, quin dels subjectes següents NO està obligat, en tot cas, a relacionar-se amb les administracions públiques per mitjans electrònics?', 'Les persones físiques poden triar si es comuniquen per mitjans electrònics o no, llevat que hi estiguin obligades (art. 14.1). Hi estan obligades les persones jurídiques, les entitats sense personalitat jurídica, els professionals de col·legiació obligatòria, els representants d''un obligat i els empleats públics per raó de la seva condició (art. 14.2 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 14.2 LPAC', 'Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas.', null, 'ca6be5fbca9ad924e44a49724162c74097ca1ea7dcb249067e94c287ec39ff74', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca6be5fbca9ad924e44a49724162c74097ca1ea7dcb249067e94c287ec39ff74')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les persones jurídiques.', false), ('B', 'Qualsevol persona física major d''edat, pel sol fet de ser-ho.', true), ('C', 'Les entitats sense personalitat jurídica.', false), ('D', 'Els empleats de les administracions públiques, per als tràmits que hi facin per raó de la seva condició d''empleat públic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 24.1 de la LPAC, en quin dels procediments següents iniciats a sol·licitud de la persona interessada el silenci administratiu té efecte desestimatori?', 'La regla general és el silenci estimatori, però és desestimatori, entre d''altres, en el dret de petició, en els procediments que transfereixin facultats sobre el domini públic o el servei públic, en els que impliquin activitats que puguin danyar el medi ambient i en els de responsabilitat patrimonial (art. 24.1 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 24.1 LPAC', 'El silencio tendrá efecto desestimatorio en los procedimientos relativos al ejercicio del derecho de petición, a que se refiere el artículo 29 de la Constitución, aquellos cuya estimación tuviera como consecuencia que se transfirieran al solicitante o a terceros facultades relativas al dominio público o al servicio público, impliquen el ejercicio de actividades que puedan dañar el medio ambiente y en los procedimientos de responsabilidad patrimonial de las Administraciones Públicas.', 'Els distractors són procediments que la LPAC no esmenta entre les excepcions de l''art. 24.1; la normativa sectorial podria fixar un altre sentit del silenci. Cal revisar que no es puguin considerar correctes.', 'caf1a37384747ff3cd0b13af41573f38fb7b620c01d00838d8b46b0018964ea9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'caf1a37384747ff3cd0b13af41573f38fb7b620c01d00838d8b46b0018964ea9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En els procediments de sol·licitud d''inscripció en un registre administratiu.', false), ('B', 'En els procediments de sol·licitud de reconeixement de triennis d''un funcionari.', false), ('C', 'En els procediments de responsabilitat patrimonial de les administracions públiques.', true), ('D', 'En els procediments de sol·licitud d''un permís per assumptes personals.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, en un procediment iniciat d''ofici en què l''Administració exerceix la potestat sancionadora, el venciment del termini màxim sense que s''hagi dictat i notificat la resolució expressa produeix:', 'En els procediments d''ofici en què l''Administració exerceix potestats sancionadores o d''intervenció amb efectes desfavorables o de gravamen, el venciment del termini produeix la caducitat, i la resolució que la declara ordena l''arxiu de les actuacions (art. 25.1.b LPAC). La caducitat no produeix per si sola la prescripció (art. 95.3).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 25.1.b LPAC', 'En los procedimientos en que la Administración ejercite potestades sancionadoras o, en general, de intervención, susceptibles de producir efectos desfavorables o de gravamen, se producirá la caducidad.', null, '420651dfa2acba017d649cb240f5193cab13b9f2c93da1f40b91be94d6fa2662', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '420651dfa2acba017d649cb240f5193cab13b9f2c93da1f40b91be94d6fa2662')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''estimació de les pretensions de la persona interessada per silenci administratiu.', false), ('B', 'La caducitat del procediment.', true), ('C', 'La prescripció automàtica de la infracció.', false), ('D', 'La desestimació de les pretensions de la persona interessada per silenci administratiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, a efectes del còmput dels terminis fixats en dies hàbils per a les persones interessades, la presentació d''un document en el registre electrònic en un dia inhàbil:', 'El registre electrònic admet documents tots els dies de l''any durant les vint-i-quatre hores (art. 31.2.a), però la presentació en dia inhàbil s''entén feta a la primera hora del primer dia hàbil següent, llevat que una norma permeti la recepció en dia inhàbil (art. 31.2.b LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 31.2.b LPAC', 'la presentación en un día inhábil se entenderá realizada en la primera hora del primer día hábil siguiente salvo que una norma permita expresamente la recepción en día inhábil.', null, '035cd15412e49cade1d42cc6c68f0c5c6a8b785cb8d5f0dad8a3b450432a4b56', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '035cd15412e49cade1d42cc6c68f0c5c6a8b785cb8d5f0dad8a3b450432a4b56')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''entén feta a l''última hora del dia hàbil anterior.', false), ('B', 'No és vàlida i el document s''ha de tornar a presentar en un dia hàbil.', false), ('C', 'S''entén feta a la primera hora del primer dia hàbil següent, llevat que una norma permeti expressament la recepció en dia inhàbil.', true), ('D', 'S''entén feta en el mateix dia inhàbil, a tots els efectes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan la notificació per mitjans electrònics és obligatòria o l''ha triada expressament la persona interessada, s''entén rebutjada quan:', 'Les notificacions electròniques s''entenen practicades quan s''accedeix al contingut, i s''entenen rebutjades si passen deu dies naturals des de la posada a disposició sense accedir-hi (art. 43.2 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 43.2 LPAC', 'Cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido.', null, '310ca7297bad6a3b8716114d24112307c949e6bfd1888eb6a2874ed44a8ca90f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '310ca7297bad6a3b8716114d24112307c949e6bfd1888eb6a2874ed44a8ca90f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Han transcorregut quinze dies hàbils des de la posada a disposició sense que s''hi hagi accedit.', false), ('B', 'Han transcorregut cinc dies hàbils des de l''enviament de l''avís.', false), ('C', 'Han transcorregut deu dies hàbils des de l''enviament de l''avís a l''adreça de correu electrònic.', false), ('D', 'Han transcorregut deu dies naturals des de la posada a disposició sense que s''hi hagi accedit.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 35 de la LPAC, quin dels actes següents NO s''esmenta entre els que s''han de motivar, amb una referència succinta de fets i fonaments de dret?', 'L''art. 35.1 LPAC exigeix motivar, entre d''altres, els actes que limitin drets o interessos legítims, els que resolguin recursos o revisions d''ofici, els que se separin del criteri precedent, les suspensions, els que rebutgin proves, les resolucions sancionadores i els actes discrecionals. La incorporació d''un informe facultatiu no hi figura.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 35.1 LPAC', 'a) Los actos que limiten derechos subjetivos o intereses legítimos. […] Los actos que rechacen pruebas propuestas por los interesados. […] Los actos que se dicten en el ejercicio de potestades discrecionales', null, 'd73c2bd1777a862e8d2488caf636bf30f102a1aef05418b3c903bf61e21c057f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd73c2bd1777a862e8d2488caf636bf30f102a1aef05418b3c903bf61e21c057f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els actes de tràmit que acorden la incorporació d''un informe facultatiu a l''expedient.', true), ('B', 'Els actes que limitin drets subjectius o interessos legítims.', false), ('C', 'Els actes que rebutgin proves proposades per les persones interessades.', false), ('D', 'Els actes que es dictin en l''exercici de potestats discrecionals.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan l''òrgan competent acorda un període d''informació pública, el termini per formular al·legacions que ha d''assenyalar l''anunci no pot ser inferior a:', 'L''anunci d''informació pública es publica al diari oficial corresponent i ha de fixar un termini d''al·legacions que en cap cas pot ser inferior a vint dies (art. 83.2 LPAC). La compareixença en aquest tràmit no atorga per si sola la condició d''interessat (art. 83.3).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 83.2 LPAC', 'determinará el plazo para formular alegaciones, que en ningún caso podrá ser inferior a veinte días.', null, '6f74b48c7d3dca34abb7f46944f0e69719b466d14f751e73cd04c98922135d53', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6f74b48c7d3dca34abb7f46944f0e69719b466d14f751e73cd04c98922135d53')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vint dies.', true), ('B', 'Deu dies.', false), ('C', 'Quinze dies.', false), ('D', 'Un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, en els procediments iniciats a sol·licitud de la persona interessada que es paralitzen per una causa que li és imputable, l''Administració li ha d''advertir que es produirà la caducitat del procediment un cop transcorreguts:', 'L''art. 95.1 LPAC preveu l''advertiment de caducitat als tres mesos; passat aquest termini sense que l''interessat reprengui la tramitació, s''acorda l''arxiu de les actuacions. No es pot acordar la caducitat per la simple inactivitat en tràmits no indispensables per resoldre (art. 95.2).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 95.1 LPAC', 'la Administración le advertirá que, transcurridos tres meses, se producirá la caducidad del procedimiento.', null, '399c11f4065b4675f714c6af897f31ca97465ac8735aa86a46d53e3525894194', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '399c11f4065b4675f714c6af897f31ca97465ac8735aa86a46d53e3525894194')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sis mesos.', false), ('B', 'Un mes.', false), ('C', 'Tres mesos.', true), ('D', 'Deu dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 5.3 de la LPAC, en quin dels casos següents NO cal acreditar la representació per actuar en nom d''una altra persona?', 'Cal acreditar la representació per formular sol·licituds, presentar declaracions responsables o comunicacions, interposar recursos, desistir d''accions i renunciar a drets; per als actes i gestions de mer tràmit, la representació es presumeix (art. 5.3 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 5.3 LPAC', 'Para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos en nombre de otra persona, deberá acreditarse la representación. Para los actos y gestiones de mero trámite se presumirá aquella representación.', null, '69e13e5afccae26271e930633122c6ab11cfc2a4304063f26236bd086a2ee047', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '69e13e5afccae26271e930633122c6ab11cfc2a4304063f26236bd086a2ee047')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per formular sol·licituds.', false), ('B', 'Per als actes i gestions de mer tràmit.', true), ('C', 'Per interposar recursos.', false), ('D', 'Per desistir d''accions i renunciar a drets.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan la notificació en paper es practica al domicili de la persona interessada i aquesta no hi és:', 'L''art. 42.2 LPAC permet que es faci càrrec de la notificació qualsevol persona major de catorze anys que sigui al domicili i s''identifiqui. Si ningú no se''n fa càrrec, es fa constar a l''expedient i l''intent es repeteix una sola vegada en una hora diferent dins els tres dies següents.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 42.2 LPAC', 'podrá hacerse cargo de la misma cualquier persona mayor de catorce años que se encuentre en el domicilio y haga constar su identidad. Si nadie se hiciera cargo de la notificación, se hará constar esta circunstancia en el expediente, junto con el día y la hora en que se intentó la notificación, intento que se repetirá por una sola vez y en una hora distinta dentro de los tres días siguientes.', null, '73a2bf54ba6e27b13af7a27c8a5727d2f9dd358903f38c7aceff5fa60c200bde', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '73a2bf54ba6e27b13af7a27c8a5727d2f9dd358903f38c7aceff5fa60c200bde')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se''n pot fer càrrec qualsevol persona major d''edat que hi sigui; si ningú no se''n fa càrrec, s''ha de publicar directament l''anunci al BOE.', false), ('B', 'Se''n pot fer càrrec qualsevol persona major de setze anys; si ningú no se''n fa càrrec, s''ha de repetir l''intent dues vegades més dins els cinc dies següents.', false), ('C', 'Se''n pot fer càrrec qualsevol persona major de catorze anys que hi sigui i faci constar la seva identitat; si ningú no se''n fa càrrec, s''ha de repetir l''intent una sola vegada, en una hora diferent, dins els tres dies següents.', true), ('D', 'Només se''n pot fer càrrec la mateixa persona interessada; si no hi és, la notificació s''entén rebutjada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, en el procediment de revisió d''ofici d''actes nuls iniciat d''ofici, el transcurs del termini de sis mesos des de l''inici sense que s''hagi dictat resolució produeix:', 'L''art. 106.5 LPAC estableix que, si el procediment s''ha iniciat d''ofici, el transcurs de sis mesos sense resolució en produeix la caducitat; si s''ha iniciat a sol·licitud de la persona interessada, es pot entendre desestimada per silenci.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 106.5 LPAC', 'Cuando el procedimiento se hubiera iniciado de oficio, el transcurso del plazo de seis meses desde su inicio sin dictarse resolución producirá la caducidad del mismo.', null, '468119d0f8a0ecad9163fff5a9cc750b7563a4ed7155a82aab1b61b26d40b44d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '468119d0f8a0ecad9163fff5a9cc750b7563a4ed7155a82aab1b61b26d40b44d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La desestimació per silenci administratiu.', false), ('B', 'La confirmació de l''acte, que esdevé inatacable.', false), ('C', 'La declaració presumpta de nul·litat de l''acte.', false), ('D', 'La caducitat del procediment.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, l''execució de l''acte impugnat s''entén suspesa si, des que la sol·licitud de suspensió ha entrat en el registre electrònic de l''òrgan competent per decidir-hi, l''òrgan que ha de resoldre el recurs no ha dictat i notificat resolució expressa en el termini de:', 'L''art. 117.3 LPAC estableix el silenci positiu sobre la sol·licitud de suspensió: si en un mes des de l''entrada de la sol·licitud no s''ha dictat i notificat resolució expressa, l''execució s''entén suspesa.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 117.3 LPAC', 'La ejecución del acto impugnado se entenderá suspendida si transcurrido un mes desde que la solicitud de suspensión haya tenido entrada en el registro electrónico de la Administración u Organismo competente para decidir sobre la misma, el órgano a quien competa resolver el recurso no ha dictado y notificado resolución expresa al respecto.', null, 'f49b6095437e0f051162ef58034d21891528a15ed688bd951e0c8bea0f9acaa9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f49b6095437e0f051162ef58034d21891528a15ed688bd951e0c8bea0f9acaa9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes.', true), ('B', 'Deu dies.', false), ('C', 'Quinze dies.', false), ('D', 'Tres mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la LPAC, quan el recurs extraordinari de revisió es fonamenta en un error de fet que resulta dels documents mateixos incorporats a l''expedient, s''ha d''interposar dins el termini de:', 'Per a la causa de l''art. 125.1.a (error de fet que resulta dels documents de l''expedient), el termini és de quatre anys des de la notificació; en els altres casos, de tres mesos des del coneixement dels documents o des de la fermesa de la sentència (art. 125.2 LPAC).', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 125.2 LPAC', 'El recurso extraordinario de revisión se interpondrá, cuando se trate de la causa a) del apartado anterior, dentro del plazo de cuatro años siguientes a la fecha de la notificación de la resolución impugnada.', null, 'd66c355ff4b05905d3ca3b8f9eae38b1cfdefb5f20289b10f64b982d2b46fc50', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd66c355ff4b05905d3ca3b8f9eae38b1cfdefb5f20289b10f64b982d2b46fc50')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos des de la notificació de la resolució impugnada.', false), ('B', 'Quatre anys següents a la data de la notificació de la resolució impugnada.', true), ('C', 'Un any des que la resolució impugnada va esdevenir ferma.', false), ('D', 'Sis mesos des que es va conèixer l''error.', false)) as v(label, body, ok)
)
