-- Lote pcat-g4-procediment-pressupost-lrjcat-v1 (3 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 26/2010, de 3 de agosto, de régimen jurídico y de procedimiento de las administraciones públicas de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g4-procediment-pressupost', 'Part general. Tema 4. Procediment administratiu i pressupost de la Generalitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g4-procediment-pressupost' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, en el tràmit d''audiència les persones interessades poden formular al·legacions i aportar documents en un termini:', 'L''art. 51.1 de la Llei 26/2010 situa l''audiència immediatament abans de redactar la proposta de resolució i fixa un termini d''al·legacions no inferior a deu dies ni superior a quinze, llevat d''una altra previsió normativa.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 51.1 LRJCAT', 'para que puedan formular las alegaciones y aportar los documentos que estimen procedentes en un plazo no inferior a diez días ni superior a quince, a no ser que se fije otro distinto en la correspondiente normativa.', null, '23600e7603c916e1c3f07a6a88c1aa99748ce695c1cab3275edc929488078533', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '23600e7603c916e1c3f07a6a88c1aa99748ce695c1cab3275edc929488078533')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No inferior a cinc dies ni superior a deu.', false), ('B', 'D''un mes, comptador des de la notificació de la proposta de resolució.', false), ('C', 'No inferior a deu dies ni superior a quinze, si la normativa corresponent no en fixa un altre de diferent.', true), ('D', 'No inferior a quinze dies ni superior a vint.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la revisió d''ofici d''actes nuls de ple dret de l''Administració de la Generalitat, la Llei 26/2010 estableix que és preceptiu el dictamen:', 'L''art. 72 de la Llei 26/2010 fa preceptiu el dictamen de la Comissió Jurídica Assessora en la revisió d''ofici d''actes nuls i de disposicions reglamentàries. L''art. 106.1 LPAC parla del dictamen favorable del Consell d''Estat o de l''òrgan consultiu equivalent de la comunitat autònoma.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 72 LRJCAT', 'El dictamen de la Comisión Jurídica Asesora es preceptivo en los expedientes de la Administración de la Generalidad o de la Administración local relativos a la revisión de oficio de actos nulos de pleno derecho y de disposiciones reglamentarias.', null, '7df34d92f37fa3512338f4a66cdbeb745ac4b8383a59f61f0b583cad19581c36', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7df34d92f37fa3512338f4a66cdbeb745ac4b8383a59f61f0b583cad19581c36')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del Consell de Garanties Estatutàries.', false), ('B', 'Del Consell d''Estat.', false), ('C', 'Del Gabinet Jurídic de la Generalitat.', false), ('D', 'De la Comissió Jurídica Assessora.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En l''àmbit de l''Administració de la Generalitat, segons la Llei 26/2010, posen fi a la via administrativa els actes dels secretaris generals i dels directors generals:', 'L''art. 75.1.b) de la Llei 26/2010 inclou entre els òrgans els actes dels quals posen fi a la via administrativa els secretaris generals, els directors generals i els òrgans directius dels organismes i entitats públiques dependents, en matèria de personal.', 'pcat_g4_procediment_pressupost', (select id from public.topics where slug = 'pcat-g4-procediment-pressupost'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 75.1 LRJCAT', 'b) Los secretarios generales, los directores generales y los órganos directivos de los organismos y entidades públicas dependientes de la Administración de la Generalidad en materia de personal.', null, '3d71921d4722fd7bf41c59d39041651f8684ae90997278db00697d59da3938d1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3d71921d4722fd7bf41c59d39041651f8684ae90997278db00697d59da3938d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En matèria de personal.', true), ('B', 'En tota matèria, sense excepció.', false), ('C', 'Només quan resolen recursos de reposició.', false), ('D', 'Només quan actuen per delegació del Govern.', false)) as v(label, body, ok)
)
