-- Lote pcat-g5-funcio-publica-cp-v1 (4 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, l''autoritat o funcionari públic que, sabent-ho, sostreu, destrueix, inutilitza o oculta, totalment o parcialment, documents la custòdia dels quals li està encomanada per raó del seu càrrec, incorre en la pena de:', 'L''art. 413 CP castiga la infidelitat en la custòdia de documents amb presó d''1 a 4 anys, multa de 7 a 24 mesos i inhabilitació especial de 3 a 6 anys. Les altres penes corresponen als arts. 414.1 (destrucció dels mitjans que impedeixen l''accés), 415 (accés a documents secrets) i 417.2 (revelació de secrets d''un particular).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 413 CP', 'La autoridad o funcionario público que, a sabiendas, sustrajere, destruyere, inutilizare u ocultare, total o parcialmente, documentos cuya custodia le esté encomendada por razón de su cargo, incurrirá en las penas de prisión de uno a cuatro años, multa de siete a veinticuatro meses, e inhabilitación especial para empleo o cargo público por tiempo de tres a seis años.', null, '4874cf9e14dbc0c4bfe554314fadf8a411b5426d48e5d5c15eabf18e3103134b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4874cf9e14dbc0c4bfe554314fadf8a411b5426d48e5d5c15eabf18e3103134b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó de sis mesos a un any o multa de sis a vint-i-quatre mesos i inhabilitació especial d''un a tres anys.', false), ('B', 'Multa de sis a dotze mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('C', 'Presó d''un a quatre anys, multa de set a vint-i-quatre mesos i inhabilitació especial per a ocupació o càrrec públic de tres a sis anys.', true), ('D', 'Presó de dos a quatre anys, multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Codi penal, si de la revelació per part d''un funcionari públic de secrets o informacions coneguts per raó del seu càrrec, que no s''han de divulgar, en resulta un dany greu per a la causa pública o per a un tercer, la pena és de:', 'L''art. 417.1 CP castiga la revelació de secrets o informacions amb multa de 12 a 18 mesos i inhabilitació especial d''1 a 3 anys; si en resulta un dany greu per a la causa pública o per a un tercer, la pena és de presó d''1 a 3 anys i inhabilitació especial de 3 a 5 anys.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 417.1 CP', 'Si de la revelación a que se refiere el párrafo anterior resultara grave daño para la causa pública o para tercero, la pena será de prisión de uno a tres años, e inhabilitación especial para empleo o cargo público por tiempo de tres a cinco años.', null, 'cf56c6cb01a7600959aa7b1c527764e543e60a2e4346ca8efc74693be42b1f7c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf56c6cb01a7600959aa7b1c527764e543e60a2e4346ca8efc74693be42b1f7c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a divuit mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('B', 'Presó d''un a tres anys i inhabilitació especial per a ocupació o càrrec públic de tres a cinc anys.', true), ('C', 'Presó de dos a quatre anys i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('D', 'Presó de tres a sis anys i inhabilitació absoluta de sis a dotze anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Codi penal, l''autoritat o funcionari públic que, sabent-ho i sense l''autorització deguda, accedeix o permet accedir a documents secrets la custòdia dels quals li està confiada per raó del seu càrrec incorre en la pena de:', 'L''art. 415 CP castiga l''accés no autoritzat a documents secrets custodiats amb multa de sis a dotze mesos i inhabilitació especial d''un a tres anys. La pena de presó d''un a quatre anys correspon a la sostracció o destrucció de documents (art. 413 CP).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 415 CP', 'accediere o permitiere acceder a documentos secretos cuya custodia le esté confiada por razón de su cargo, incurrirá en la pena de multa de seis a doce meses, e inhabilitación especial para empleo o cargo público por tiempo de uno a tres años.', null, '7c8aabe94ee1f5e68b66993ff9a489727fded5fb10bf504fad66707178fd868b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c8aabe94ee1f5e68b66993ff9a489727fded5fb10bf504fad66707178fd868b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presó d''un a quatre anys, multa de set a vint-i-quatre mesos i inhabilitació especial de tres a sis anys.', false), ('B', 'Presó de sis mesos a un any i inhabilitació especial d''un a tres anys.', false), ('C', 'Multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('D', 'Multa de sis a dotze mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 417 del Codi penal, si els secrets revelats per l''autoritat o funcionari públic són d''un particular, les penes són:', 'L''art. 417.1 CP castiga la revelació de secrets coneguts per raó del càrrec amb multa i inhabilitació (o amb presó d''un a tres anys si hi ha dany greu), i l''art. 417.2 eleva la pena a presó de dos a quatre anys, multa de dotze a divuit mesos i suspensió d''un a tres anys quan es tracta de secrets d''un particular.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 417.2 CP', 'Si se tratara de secretos de un particular, las penas serán las de prisión de dos a cuatro años, multa de doce a dieciocho meses, y suspensión de empleo o cargo público por tiempo de uno a tres años.', null, '5eff3d49752c7ece0d4b38543183cea4ff823193473219bb28bd25707342b8e9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5eff3d49752c7ece0d4b38543183cea4ff823193473219bb28bd25707342b8e9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de dotze a divuit mesos i inhabilitació especial per a ocupació o càrrec públic d''un a tres anys.', false), ('B', 'Presó d''un a tres anys i inhabilitació especial per a ocupació o càrrec públic de tres a cinc anys.', false), ('C', 'Presó de sis mesos a dos anys i suspensió d''ocupació o càrrec públic d''un a tres anys.', false), ('D', 'Presó de dos a quatre anys, multa de dotze a divuit mesos i suspensió d''ocupació o càrrec públic d''un a tres anys.', true)) as v(label, body, ok)
)
