-- Lote pcat-g5-funcio-publica-d123-v1 (5 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 123/1997, de 13 de maig, pel qual s''aprova el Reglament general de provisió de llocs de treball i promoció professional dels funcionaris de l''Administració de la Generalitat de Catalunya (text consolidat)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=144359', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 123/1997, pel qual s''aprova el Reglament general de provisió de llocs de treball i promoció professional dels funcionaris de la Generalitat, els sistemes generals de provisió de llocs per al personal funcionari són:', 'L''art. 5 del Decret 123/1997 estableix que la provisió es fa pel sistema de concurs de mèrits i capacitats, que és el normal, i pel de lliure designació, d''acord amb les relacions de llocs de treball. La comissió de serveis és un sistema extraordinari (art. 6).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=144359'), 'Art. 5 D123', 'la provisió dels llocs per al personal funcionari de l''Administració de la Generalitat es realitzarà pel sistema de concurs de mèrits i capacitats, que serà el normal per proveir els llocs de treball, i pel sistema de lliure designació.', null, 'd574158ed0c71dc5927fe593afe351943f24369af49dea46f65e8a3beb8c478e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd574158ed0c71dc5927fe593afe351943f24369af49dea46f65e8a3beb8c478e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La lliure designació, que és el sistema normal, i el concurs de mèrits i capacitats.', false), ('B', 'El concurs de mèrits i capacitats i la comissió de serveis.', false), ('C', 'L''oposició, el concurs oposició i el concurs.', false), ('D', 'El concurs de mèrits i capacitats, que és el sistema normal, i la lliure designació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 123/1997, quin dels sistemes següents NO és un sistema extraordinari de provisió de llocs de treball?', 'L''art. 6 del Decret 123/1997 enumera com a sistemes extraordinaris la comissió de serveis, l''encàrrec de funcions, l''acumulació de tasques, la redistribució d''efectius, el trasllat interdepartamental, la reassignació d''efectius, la mobilitat per trasllat de llocs, l''adscripció provisional i la permuta. El concurs específic és una modalitat del concurs, sistema general (arts. 9 i 11).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=144359'), 'Art. 6 D123', 'a) Comissió de serveis. b) Encàrrec de funcions. c) Acumulació de tasques. d) Redistribució d''efectius. e) Trasllat interdepartamental. f) Reassignació d''efectius. g) Mobilitat per trasllat de llocs de treball. h) Adscripció provisional. i) Permuta de llocs de treball.', null, '550b956d4836253f43d816bbbcca73b0853a0f888b749262bba945f67d2d0b5f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '550b956d4836253f43d816bbbcca73b0853a0f888b749262bba945f67d2d0b5f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''encàrrec de funcions.', false), ('B', 'La permuta de llocs de treball.', false), ('C', 'El concurs específic.', true), ('D', 'L''adscripció provisional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 123/1997, llevat que a la relació de llocs de treball constin com de lliure designació, els llocs de cap de negociat, de secció i de servei es proveeixen per:', 'L''art. 11.2 del Decret 123/1997 reserva al concurs específic els llocs de cap de negociat, secció, servei i assimilats i els llocs singulars que exigeixen tècniques o responsabilitats especials o tenen peculiaritats d''ocupació pròpies, llevat que la RLT els qualifiqui de lliure designació.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=144359'), 'Art. 11.2 D123', 'Es proveiran per concurs específic, llevat dels que en la relació de llocs de treball constin com de lliure designació, els llocs següents: a) Cap de negociat, secció, servei i assimilats a aquests per la norma que els crea.', null, '50a4a9f52d6eda7acdb1e72d38c2896d37e214121129231aff0d78a5604949b0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50a4a9f52d6eda7acdb1e72d38c2896d37e214121129231aff0d78a5604949b0')
  returning id
