with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, pel qual s''aprova el Reglament de règim disciplinari de la funció pública de l''Administració de la Generalitat, quina de les conductes següents NO és una falta molt greu?', 'L''art. 3 del Decret 243/1995 qualifica de molt greus, entre d''altres, l''abandonament del servei (c), l''incompliment de les normes sobre incompatibilitats (h) i haver estat sancionat per tres faltes greus en un any (o). L''abús d''autoritat és una falta greu (art. 4.b).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Arts. 3 i 4 D243', 'c) L''abandonament del servei. […] h) L''incompliment de les normes sobre incompatibilitats. […] o) El fet d''haver estat sancionat per la comissió de tres faltes greus en el període d''un any. […] b) L''abús d''autoritat en l''exercici del càrrec.', null, 'a0c99789d0b5a2d21f552251ab27708baa0a8189ece767ebfa8c38416a909eb1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a0c99789d0b5a2d21f552251ab27708baa0a8189ece767ebfa8c38416a909eb1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''abús d''autoritat en l''exercici del càrrec.', true), ('B', 'L''incompliment de les normes sobre incompatibilitats.', false), ('C', 'L''abandonament del servei.', false), ('D', 'El fet d''haver estat sancionat per la comissió de tres faltes greus en el període d''un any.', false)) as v(label, body, ok)
)
