with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el Decret 243/1995, quin òrgan imposa les sancions per faltes molt greus?', 'L''art. 52.1 del Decret 243/1995 atribueix les sancions per faltes lleus als secretaris generals, directors generals o assimilats; per faltes greus, al secretari general del departament; i per faltes molt greus, al titular del departament.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 52.1 D243', 'c) Les sancions per faltes molt greus seran imposades pel titular del departament o del qual depèn l''organisme o entitat on presta serveis el funcionari responsable', null, 'a1ff2ca280caf273563f32ee52260ce1f490ef11bb1b7fa8877ed718f49ec376', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1ff2ca280caf273563f32ee52260ce1f490ef11bb1b7fa8877ed718f49ec376')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El secretari general del departament.', false), ('B', 'El director general de la Funció Pública.', false), ('C', 'El Govern de la Generalitat, amb l''informe previ de la Comissió Jurídica Assessora.', false), ('D', 'El titular del departament o del qual depèn l''organisme o l''entitat on presta serveis el funcionari responsable.', true)) as v(label, body, ok)
)
