with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, pel qual s''aprova el Reglament de règim disciplinari de la funció pública de l''Administració de la Generalitat, per la comissió de faltes lleus es poden imposar les sancions de:', 'L''art. 12 del Decret 243/1995 preveu per a les faltes lleus la suspensió de funcions fins a quinze dies i l''amonestació. La suspensió de més de quinze dies i fins a un any és pròpia de les faltes greus (art. 11).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 12 D243', 'La suspensió de funcions, amb pèrdua de retribucions, fins a quinze dies. -2 L''amonestació.', null, '0892d7845562a88cfb355638b3f7badb37a5b3680389dc541970b8d0ab8d5581', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0892d7845562a88cfb355638b3f7badb37a5b3680389dc541970b8d0ab8d5581')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspensió de funcions, amb pèrdua de retribucions, fins a quinze dies, i amonestació.', true), ('B', 'Suspensió de funcions, amb pèrdua de retribucions, fins a un mes, i amonestació.', false), ('C', 'Amonestació i trasllat de lloc de treball dins la mateixa localitat.', false), ('D', 'Només amonestació.', false)) as v(label, body, ok)
)
