with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, per la comissió de faltes greus es pot imposar la suspensió de funcions, amb pèrdua de retribucions:', 'Per faltes greus es pot imposar la suspensió de funcions per més de quinze dies i fins a un any, el trasllat dins la mateixa localitat, la destitució del càrrec de comandament, la rescissió del nomenament d''interí i la pèrdua d''un o dos graus personals (art. 11 Decret 243/1995). La suspensió de més d''un any i menys de sis és pròpia de les faltes molt greus (art. 10).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 11 D243', 'La suspensió de funcions, amb pèrdua de retribucions, per més de quinze dies i fins a un any.', null, '7abcd987233995ff0840f9884a8a275cd1383648f3ad313d368e2ec9d9233f5c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7abcd987233995ff0840f9884a8a275cd1383648f3ad313d368e2ec9d9233f5c')
  returning id
), o as (
