  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per més d''un any i menys de sis.', false), ('B', 'Fins a quinze dies.', false), ('C', 'Per més de quinze dies i fins a un any.', true), ('D', 'Per més d''un mes i fins a tres anys.', false)) as v(label, body, ok)
)
