with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, quina de les conductes següents NO és una falta greu?', 'La manca d''assistència injustificada d''un dia és una falta lleu (art. 5.c). L''abús d''autoritat, l''incompliment de jornada que acumulat suposi un mínim de deu hores per mes natural i la intervenció en un procediment amb motius d''abstenció són faltes greus (art. 4.b, 4.o i 4.h Decret 243/1995).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Arts. 4 i 5 D243', 'c) La manca d''assistència al treball injustificada d''un dia.', null, 'a58bbf2a4411e8ee9142c163be3c46fd26b298b9f0e8dced9ac00c5c955433bb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a58bbf2a4411e8ee9142c163be3c46fd26b298b9f0e8dced9ac00c5c955433bb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La manca d''assistència al treball injustificada d''un dia.', true), ('B', 'L''abús d''autoritat en l''exercici del càrrec.', false), ('C', 'L''incompliment injustificat de la jornada i l''horari de treball que acumulat suposi un mínim de deu hores per mes natural.', false), ('D', 'La intervenció en un procediment administratiu quan hi ha motius d''abstenció establerts legalment.', false)) as v(label, body, ok)
)
