  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El titular del departament en què estigui destinat el funcionari.', false), ('B', 'El secretari general del departament en què estigui destinat el funcionari o, si escau, el director de l''organisme autònom corresponent.', true), ('C', 'El cap de la unitat on presta serveis el funcionari.', false), ('D', 'El director general de Funció Pública.', false)) as v(label, body, ok)
)
