with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, la sanció de destitució del càrrec de comandament impossibilita obtenir un nou càrrec de comandament a l''Administració de la Generalitat durant un període de:', 'L''art. 17 del Decret 243/1995 estableix que la destitució del càrrec de comandament i la rescissió del nomenament d''interí impedeixen, respectivament, obtenir un nou càrrec de comandament o un nou interinatge durant tres anys (falta molt greu) o dos anys (falta greu).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 17 D243', 'per un període de tres anys si la falta comesa va ser qualificada de molt greu, o per un període de dos anys si la falta comesa va ser qualificada de greu.', null, 'd664b80b465b7997b70963007783f2a003b08b3da67d0f2506696e73c597fa30', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd664b80b465b7997b70963007783f2a003b08b3da67d0f2506696e73c597fa30')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres anys si la falta es va qualificar de molt greu, o dos anys si es va qualificar de greu.', true), ('B', 'Cinc anys si la falta es va qualificar de molt greu, o tres anys si es va qualificar de greu.', false), ('C', 'Dos anys, en tots els casos.', false), ('D', 'Sis anys si la falta es va qualificar de molt greu, o dos anys si es va qualificar de greu.', false)) as v(label, body, ok)
)
