with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, quina de les sancions següents NO es pot imposar en cap cas a un funcionari?', 'L''art. 18 del Decret 243/1995 prohibeix les sancions que consisteixin en la reducció de la durada de les vacances o una altra minoració dels drets de descans, o en multa d''havers, i cap sanció no pot suposar violació del dret a la dignitat de la persona.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 18 D243', 'No es poden imposar sancions que consisteixin en la reducció de la durada de les vacances o una altra minoració dels drets de descans del funcionari o multa d''havers.', null, 'edf0b9e9e626d36c43d9caaf221e73f1483143ee62cbaddfd3e032e585e13f1b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'edf0b9e9e626d36c43d9caaf221e73f1483143ee62cbaddfd3e032e585e13f1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''amonestació.', false), ('B', 'El trasllat de lloc de treball dins la mateixa localitat.', false), ('C', 'La destitució del càrrec de comandament.', false), ('D', 'La reducció de la durada de les vacances.', true)) as v(label, body, ok)
)
