with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procediment disciplinari ordinari del Decret 243/1995, en quin termini, comptat a partir de la notificació de la incoació, l''instructor pot proposar l''arxiu de les actuacions, el sobreseïment o formular el plec de càrrecs?', 'L''art. 45.5 del Decret 243/1995 fixa un termini no superior a un mes des de la notificació de la incoació, prorrogable per un altre mes, perquè l''instructor proposi l''arxiu, el sobreseïment o formuli el plec de càrrecs. Notificat el plec, l''inculpat té deu dies per al·legar (art. 46.3).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 45.5 D243', 'en un termini no superior a un mes, comptador a partir de la notificació de la incoació de l''expedient, termini que serà prorrogable per un altre mes, l''instructor podrà proposar l''arxiu d''actuacions, el sobreseïment o formular el plec de càrrecs', null, 'bb197b3174bad6c4d5a5b685a4c7b8b54cc4a4fb07b29ca2412ddee465fb9391', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bb197b3174bad6c4d5a5b685a4c7b8b54cc4a4fb07b29ca2412ddee465fb9391')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En un termini no superior a un mes, prorrogable per un altre mes.', true), ('B', 'En un termini no superior a deu dies, prorrogable per cinc dies més.', false), ('C', 'En un termini no superior a quinze dies, improrrogable.', false), ('D', 'En un termini no superior a tres mesos, improrrogable.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
