with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret 243/1995, quina és la durada màxima de l''expedient disciplinari ordinari, llevat que l''instructor justifiqui una pròrroga expressa o hi hagi una conducta dilatòria de l''inculpat?', 'Qualsevol termini del procediment el pot ampliar l''instructor si hi ha causa justificada (art. 51.1), però la durada màxima de l''expedient no pot ser superior a sis mesos, llevat de pròrroga expressa justificada o de conducta dilatòria de l''inculpat (art. 51.2 Decret 243/1995).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 51.2 D243', 'En tot cas, la durada màxima de l''expedient no podrà ésser superior a sis mesos, llevat que l''instructor justifiqui una pròrroga expressa o hi hagi una conducta dilatòria de l''inculpat.', null, '8137574e24a1cf086b21b98b48b248eaea29314045d2e0b642d44ea3ec58c835', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8137574e24a1cf086b21b98b48b248eaea29314045d2e0b642d44ea3ec58c835')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos.', false), ('B', 'Sis mesos.', true), ('C', 'Un any.', false), ('D', 'Dos mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
