with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procediment disciplinari sumari per faltes lleus del Decret 243/1995, del plec de càrrecs es dona trasllat al funcionari inculpat perquè formuli al·legacions en el termini de:', 'En el procediment sumari, l''inculpat té cinc dies per formular al·legacions i proposar proves (art. 34), les proves pertinents es practiquen en cinc dies (art. 35) i la resolució es dicta en tres dies (art. 36). En el procediment ordinari, el termini d''al·legacions al plec de càrrecs és de deu dies (art. 46.3).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=110907'), 'Art. 34 D243', 'Del plec de càrrecs es donarà trasllat al funcionari inculpat per tal que en el termini de cinc dies formuli les al·legacions que consideri convenients per a la seva defensa', null, '96341200f64402ea1f23f08f06264e543fe41346f78eb9635b053303e2ad7fd1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '96341200f64402ea1f23f08f06264e543fe41346f78eb9635b053303e2ad7fd1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies.', false), ('B', 'Tres dies.', false), ('C', 'Cinc dies.', true), ('D', 'Quinze dies.', false)) as v(label, body, ok)
)
