insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret legislatiu 1/1997, text únic dels preceptes de determinats textos legals vigents a Catalunya en matèria de funció pública, quina de les causes següents NO comporta la pèrdua de la condició de funcionari de la Generalitat?', 'L''art. 35 DL 1/1997 preveu com a causes de pèrdua la renúncia escrita, la sanció de separació del servei, la pena d''inhabilitació absoluta o especial, la pèrdua de la ciutadania espanyola, la jubilació forçosa o voluntària i la defunció. La suspensió de funcions és una situació administrativa (art. 84.e) i no extingeix la condició de funcionari.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 35 DLFP', 'a) Por renuncia escrita del interesado. b) Como consecuencia de sanción disciplinaria que suponga la separación del servicio. c) Por pena principal o accesoria de inhabilitación absoluta o especial para cargo público. d) Por pérdida de la ciudadanía española. e) Por jubilación forzosa o voluntaria. f) Por defunción.', null, 'd6f0540ba609ec6cfabee165299dc9b34e158e72fdd4c9a574b3db4028c07472', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6f0540ba609ec6cfabee165299dc9b34e158e72fdd4c9a574b3db4028c07472')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La renúncia escrita de la persona interessada.', false), ('B', 'La pèrdua de la ciutadania espanyola.', false), ('C', 'La suspensió ferma de funcions.', true), ('D', 'La jubilació forçosa o voluntària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret legislatiu 1/1997, la comissió de servei d''un funcionari de la Generalitat té caràcter temporal i no pot durar més de:', 'L''art. 85.3 DL 1/1997 configura la comissió de servei com una situació de servei actiu, temporal, per necessitats del servei, amb reserva del lloc d''origen i amb una durada màxima de dos anys.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 85.3 DLFP', 'La comisión de servicio, que tendrá carácter temporal y no podrá durar más de dos años, se dará exclusivamente por necesidades del servicio', null, 'a1b5dc586fdf6aa53eda3b7d799b38cdf8fa596f9aecc3ddab0bf25bf2688c8a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a1b5dc586fdf6aa53eda3b7d799b38cdf8fa596f9aecc3ddab0bf25bf2688c8a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un any.', false), ('B', 'Sis mesos.', false), ('C', 'Dos anys.', true), ('D', 'Tres anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per poder obtenir l''excedència voluntària per interès particular, el Decret legislatiu 1/1997 exigeix haver prestat serveis efectius en qualsevol de les administracions públiques durant:', 'L''art. 86.2.a) DL 1/1997 exigeix cinc anys de serveis efectius immediatament anteriors i una permanència mínima de dos anys continuats en l''excedència voluntària per interès particular.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 86.2.a DLFP', 'Para poder solicitar esta excedencia deben haberse prestado servicios efectivos en cualquiera de las administraciones públicas durante los cinco años inmediatamente anteriores, y en ella no podrá permanecer menos de dos años continuados.', 'El text consolidat del DL 1/1997 del BOE consta com a «Desactualizado»; cal confirmar que l''art. 86.2.a) (cinc anys de serveis i dos de permanència mínima) continua vigent amb aquesta redacció.', '90edb2b17958cf7ed6228f53debd7792c7811d1f29b1d103014599e6ec55d696', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '90edb2b17958cf7ed6228f53debd7792c7811d1f29b1d103014599e6ec55d696')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els tres anys immediatament anteriors, i no s''hi pot romandre menys d''un any.', false), ('B', 'Els cinc anys immediatament anteriors, i no s''hi pot romandre menys de dos anys continuats.', true), ('C', 'Els cinc anys immediatament anteriors, sense cap període mínim de permanència.', false), ('D', 'Els dos anys immediatament anteriors, i no s''hi pot romandre menys de cinc anys.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Decret legislatiu 1/1997, el període màxim de durada de la situació d''expectativa de destinació és:', 'L''art. 91 DL 1/1997 fixa una durada màxima d''un any per a l''expectativa de destinació, després del qual es passa a excedència forçosa. Mentrestant, el funcionari cobra les retribucions bàsiques, el complement de destinació del grau personal i el 50 % del complement específic.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 91 DLFP', 'El período máximo de duración de la situación de expectativa de destino es de un año, transcurrido el cual se pasa a la situación de excedencia forzosa.', 'El text consolidat del DL 1/1997 del BOE consta com a «Desactualizado» i l''expectativa de destinació no figura entre les situacions de l''art. 85 TREBEP; cal confirmar la vigència de l''art. 91 a Catalunya.', 'c7bfb8cf6c8d252745fa9f47f70f584ae774b67f42ab7d1b799caf6ecb2e6db9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c7bfb8cf6c8d252745fa9f47f70f584ae774b67f42ab7d1b799caf6ecb2e6db9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'D''un any; transcorregut aquest, el funcionari passa a la situació d''excedència forçosa.', true), ('B', 'De dos anys; transcorreguts aquests, el funcionari passa a la situació d''excedència voluntària per interès particular.', false), ('C', 'De sis mesos; transcorreguts aquests, el funcionari passa a la situació de disponibilitat.', false), ('D', 'D''un any; transcorregut aquest, el funcionari perd la condició de funcionari.', false)) as v(label, body, ok)
)
