insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 21/1987, de 26 de noviembre, de incompatibilidades del personal al servicio de la Administración de la Generalidad (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionària de la Generalitat té reconeguda la compatibilitat per exercir una activitat privada i obté, per concurs, un altre lloc de treball en el sector públic. Segons la Llei 21/1987, d''incompatibilitats del personal al servei de l''Administració de la Generalitat, el reconeixement de compatibilitat:', 'L''art. 21.1 de la Llei 21/1987 disposa que els reconeixements de compatibilitat queden automàticament sense efecte en cas de canvi de lloc en el sector públic o de modificació de les condicions del lloc de treball.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 21.1 LINCAT', 'Los reconocimientos de compatibilidad no podrán modificar la jornada de trabajo ni el horario del interesado, y quedarán automáticamente sin efecto en caso de cambio de puesto en el sector público o de modificación en las condiciones del puesto de trabajo.', null, 'cee16c0ae9a00451b1812280f1fc8ce915b1a2427f1202c4298b1723f3204c68', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cee16c0ae9a00451b1812280f1fc8ce915b1a2427f1202c4298b1723f3204c68')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es manté vigent fins que s''hagi de renovar, al cap de cinc anys.', false), ('B', 'Es manté vigent si el nou lloc té el mateix nivell i la mateixa jornada.', false), ('C', 'S''ha de ratificar per l''òrgan competent en el termini d''un mes.', false), ('D', 'Queda automàticament sense efecte.', true)) as v(label, body, ok)
)
