with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 21/1987, qui accedeix a un nou lloc de treball del sector públic que pot ser declarat compatible amb el que ja ocupa ha de sol·licitar l''autorització de compatibilitat:', 'L''art. 10.3 de la Llei 21/1987 fixa deu dies des de l''inici del termini de presa de possessió, termini que s''entén prorrogat fins que es resolgui la sol·licitud. Els quinze dies són el termini per exercir l''opció quan l''òrgan aprecia incompatibilitat (art. 10.4).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 10.3 LINCAT', 'Si el nuevo puesto pudiera ser declarado compatible, dentro de diez días contados desde el inicio del plazo de toma de posesión, deberá solicitarse su autorización.', null, '757f07bc41159ad63bb18944d2255e0bb570b32cb84b7a3a9b6ef5a520842e0e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '757f07bc41159ad63bb18944d2255e0bb570b32cb84b7a3a9b6ef5a520842e0e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de quinze dies comptats des de la presa de possessió.', false), ('B', 'Abans de presentar-se al procés de selecció o de provisió.', false), ('C', 'Dins de deu dies comptats des de l''inici del termini de presa de possessió.', true), ('D', 'Dins del mes següent a la publicació del nomenament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
