with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 21/1987, d''incompatibilitats del personal al servei de l''Administració de la Generalitat, l''exercici d''un segon lloc de treball o activitat pública o privada:', 'L''art. 17.1 de la Llei 21/1987 exigeix autorització expressa prèvia en tots els casos. Si no es resol i notifica en el termini reglamentari, la sol·licitud s''entén desestimada (art. 17.2).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 17.1 Llei 21/1987', 'El ejercicio de un segundo puesto de trabajo o actividad pública o privada requiere, en todos los casos, autorización expresa previa.', null, 'a95cced5a2f94bc3f93ff0c4ee880d7d6cc59020dedc5920b8db5ff180c33bcb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a95cced5a2f94bc3f93ff0c4ee880d7d6cc59020dedc5920b8db5ff180c33bcb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només requereix una comunicació posterior a l''òrgan de personal.', false), ('B', 'Requereix, en tots els casos, autorització expressa prèvia.', true), ('C', 'Requereix autorització només si l''activitat és pública.', false), ('D', 'No requereix autorització si es fa fora de l''horari de treball.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
