with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 2 de la Llei 21/1987, quina de les activitats següents NO queda exclosa del règim d''incompatibilitats?', 'L''art. 2 de la Llei 21/1987 exclou de les incompatibilitats, entre d''altres, l''administració del patrimoni personal o familiar, la participació en tribunals de selecció i la creació literària, artística, científica i tècnica. En canvi, no es pot autoritzar l''activitat privada relacionada directament amb la del departament (art. 11.a).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 2 Llei 21/1987', 'a)	Las derivadas de la administración del patrimonio personal o familiar, salvo lo determinado por el artículo 11. […] c)	La participación en tribunales u órganos de selección para el ingreso en las Administraciones públicas.', null, '7f910b2fdbb7d93543cfce3a58c70f6e81c559f2fec8e1150211ec2b0c10e7a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f910b2fdbb7d93543cfce3a58c70f6e81c559f2fec8e1150211ec2b0c10e7a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La participació en tribunals o òrgans de selecció per a l''ingrés a les administracions públiques.', false), ('B', 'Les activitats derivades de l''administració del patrimoni personal o familiar.', false), ('C', 'L''exercici d''una activitat professional privada relacionada directament amb les que du a terme el departament on es presten serveis.', true), ('D', 'La producció i la creació literàries, artístiques, científiques i tècniques que no derivin d''una relació de treball.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 21/1987, quan es reconeix la compatibilitat per exercir una activitat privada, la suma de les jornades de l''activitat pública principal i de l''activitat privada:', 'L''art. 12.2 de la Llei 21/1987 fixa com a límit la jornada ordinària de l''Administració incrementada en un 50 %. A més, el reconeixement de compatibilitat no pot modificar la jornada ni l''horari del lloc públic (art. 21.1).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 12.2 Llei 21/1987', 'en ningún caso la suma de jornadas de la actividad pública principal y la actividad privada podrá superar la jornada ordinaria de la Administración incrementada en un 50 por 100.', null, 'f66f1289e1355f43847efc20a30740d2a36553583f9496066b298b5e0c066aa4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f66f1289e1355f43847efc20a30740d2a36553583f9496066b298b5e0c066aa4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No pot superar la jornada ordinària de l''Administració incrementada en un 30 %.', false), ('B', 'No pot superar les quaranta hores setmanals.', false), ('C', 'No pot superar en cap cas la jornada ordinària de l''Administració incrementada en un 50 %.', true), ('D', 'No té cap límit, sempre que es compleixi l''horari del lloc públic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 21/1987, les remuneracions totals per un segon lloc o activitat pública autoritzats no poden superar la retribució de l''activitat principal, en règim de jornada ordinària, incrementada per als funcionaris del grup C o personal de nivell equivalent en un:', 'L''art. 5.1 de la Llei 21/1987 fixa els increments màxims següents: 30 % (grup A), 35 % (grup B), 40 % (grup C), 45 % (grup D) i 50 % (grup E), i en cap cas es poden superar les remuneracions màximes del càrrec de director general.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 5.1 Llei 21/1987', 'c) Un 40 por 100, los funcionarios del Grupo C o personal del nivel equivalente.', 'La Llei 21/1987 usa la classificació antiga de grups (A-E); cal confirmar l''equivalència amb el grup C/subgrup C1 actual del TREBEP abans d''aprovar-la.', '3302180210eb716e77c5631093ca340e43291a69a981f9dd2691802369970a45', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3302180210eb716e77c5631093ca340e43291a69a981f9dd2691802369970a45')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '30 %.', false), ('B', '40 %.', true), ('C', '35 %.', false), ('D', '50 %.', false)) as v(label, body, ok)
)
