insert into public.topics (slug, title) values ('pcat-g5-funcio-publica', 'Part general. Tema 5. La funció pública: drets i deures, situacions, provisió, incompatibilitats i règim disciplinari') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcat-g5-funcio-publica' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 8 del text refós de la Llei de l''Estatut bàsic de l''empleat públic (TREBEP), quina de les categories següents NO és una de les classes en què es classifiquen els empleats públics?', 'L''art. 8.2 TREBEP classifica els empleats públics en funcionaris de carrera, funcionaris interins, personal laboral (fix, per temps indefinit o temporal) i personal eventual. El personal directiu professional es regula a part (art. 13) i no és una d''aquestes classes.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 8.2 TREBEP', 'Los empleados públicos se clasifican en: a) Funcionarios de carrera. b) Funcionarios interinos. c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. d) Personal eventual.', null, '925aed6e9a4a4e671885ad5e38fb34b495e8722bc960a224db82ef02956c8fa1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '925aed6e9a4a4e671885ad5e38fb34b495e8722bc960a224db82ef02956c8fa1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Personal directiu professional.', true), ('B', 'Funcionaris interins.', false), ('C', 'Personal laboral, ja sigui fix, per temps indefinit o temporal.', false), ('D', 'Personal eventual.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el TREBEP, el cessament del personal eventual:', 'L''art. 12.3 TREBEP estableix que el nomenament i el cessament del personal eventual són lliures i que el cessament té lloc, en tot cas, quan es produeix el de l''autoritat a la qual presta la funció de confiança o assessorament especial.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 12.3 TREBEP', 'El nombramiento y cese serán libres. El cese tendrá lugar, en todo caso, cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento.', null, '264e06ff6e3df71e17e4b80bc86889d6d5c521cfb6a5aeebdc4a49faa7eb1d72', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '264e06ff6e3df71e17e4b80bc86889d6d5c521cfb6a5aeebdc4a49faa7eb1d72')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només es pot acordar per expedient disciplinari o per finalització del termini fixat en el nomenament.', false), ('B', 'Es produeix automàticament al cap de quatre anys del nomenament.', false), ('C', 'Requereix l''informe previ de l''òrgan competent en matèria de funció pública.', false), ('D', 'És lliure i es produeix, en tot cas, quan cessa l''autoritat a la qual presta la funció de confiança o assessorament.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons els principis de conducta del TREBEP, davant d''un regal, favor o servei en condicions avantatjoses, els empleats públics:', 'L''art. 54.6 TREBEP obliga a rebutjar qualsevol regal, favor o servei en condicions avantatjoses que vagi més enllà dels usos habituals, socials i de cortesia, sens perjudici del que estableix el Codi penal.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.6 TREBEP', 'Se rechazará cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía, sin perjuicio de lo establecido en el Código Penal.', null, '53938573aeb47360d07149040a00a661f21ce6181d6770fe578d0aa4afc7d0b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '53938573aeb47360d07149040a00a661f21ce6181d6770fe578d0aa4afc7d0b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El poden acceptar sempre que en comuniquin la recepció al superior jeràrquic en el termini de deu dies.', false), ('B', 'El poden acceptar si el seu valor no supera l''import que fixi la llei de pressupostos.', false), ('C', 'L''han de rebutjar quan vagi més enllà dels usos habituals, socials i de cortesia, sens perjudici del que estableix el Codi penal.', true), ('D', 'L''han de rebutjar en tot cas, fins i tot quan s''ajusti als usos habituals i de cortesia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el codi de conducta del TREBEP, quan una ordre professional d''un superior constitueix una infracció manifesta de l''ordenament jurídic, l''empleat públic:', 'L''art. 54.3 TREBEP imposa obeir les instruccions i ordres professionals dels superiors, llevat que constitueixin una infracció manifesta de l''ordenament jurídic; en aquest cas s''han de posar immediatament en coneixement dels òrgans d''inspecció procedents.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.3 TREBEP', 'Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico, en cuyo caso las pondrán inmediatamente en conocimiento de los órganos de inspección procedentes.', null, '73750a8f34fe693b7b918f7795af2dea007735c8b16d6afbd84437b07923bf2f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '73750a8f34fe693b7b918f7795af2dea007735c8b16d6afbd84437b07923bf2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''ha d''obeir i després pot presentar una queixa davant el superior jeràrquic de qui l''ha donada.', false), ('B', 'No l''ha d''obeir i ho ha de posar immediatament en coneixement dels òrgans d''inspecció procedents.', true), ('C', 'L''ha d''obeir si se li dona per escrit, i en pot demanar la revisió en via de recurs.', false), ('D', 'No l''ha d''obeir i ho ha de comunicar al Ministeri Fiscal en el termini de vint-i-quatre hores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 54 del TREBEP, pel que fa a la llengua, els empleats públics:', 'L''art. 54.11 TREBEP inclou entre els principis de conducta garantir l''atenció al ciutadà en la llengua que sol·liciti sempre que sigui oficial en el territori.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 54.11 TREBEP', 'Garantizarán la atención al ciudadano en la lengua que lo solicite siempre que sea oficial en el territorio.', null, '6f2e62b1b67df944885bc953237e3ef365669ea5090f25e4a06e801e0d4e7c61', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6f2e62b1b67df944885bc953237e3ef365669ea5090f25e4a06e801e0d4e7c61')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Han d''atendre la ciutadania exclusivament en castellà, com a llengua oficial de l''Estat.', false), ('B', 'Han d''atendre la ciutadania en la llengua que triï l''Administració on presten serveis.', false), ('C', 'Han de garantir l''atenció en qualsevol llengua de la Unió Europea que sol·liciti la persona interessada.', false), ('D', 'Han de garantir l''atenció a la ciutadania en la llengua que sol·liciti, sempre que sigui oficial en el territori.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, la condició de funcionari de carrera s''adquireix pel compliment successiu de diversos requisits. Quin és l''últim?', 'L''art. 62.1 TREBEP enumera, per aquest ordre: superació del procés selectiu, nomenament publicat al diari oficial, acte d''acatament de la Constitució (i de l''Estatut, si escau) i presa de possessió dins el termini establert.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 62.1 TREBEP', 'a) Superación del proceso selectivo. b) Nombramiento por el órgano o autoridad competente, que será publicado en el Diario Oficial correspondiente. c) Acto de acatamiento de la Constitución y, en su caso, del Estatuto de Autonomía correspondiente y del resto del Ordenamiento Jurídico. d) Toma de posesión dentro del plazo que se establezca.', null, 'bce0c2ac22856e1c6bb7ff8ea810e17660abc49bd4f483305ce43578dd587d16', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bce0c2ac22856e1c6bb7ff8ea810e17660abc49bd4f483305ce43578dd587d16')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La presa de possessió dins el termini que s''estableixi.', true), ('B', 'El nomenament per l''òrgan o l''autoritat competent.', false), ('C', 'L''acte d''acatament de la Constitució i, si escau, de l''Estatut d''autonomia.', false), ('D', 'La superació del procés selectiu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el TREBEP, la pena principal o accessòria d''inhabilitació especial per a càrrec públic, quan la sentència que la imposa ha esdevingut ferma:', 'Segons l''art. 66 TREBEP, la inhabilitació absoluta ferma comporta la pèrdua de la condició de funcionari respecte de tots els càrrecs, i la inhabilitació especial ferma, respecte dels especificats a la sentència.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 66 TREBEP', 'La pena principal o accesoria de inhabilitación especial cuando hubiere adquirido firmeza la sentencia que la imponga produce la pérdida de la condición de funcionario respecto de aquellos empleos o cargos especificados en la sentencia.', null, 'f7679f21720dea5fd7d11c88c6281dac84ca65cb51593591a5f45ed5ab39612b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f7679f21720dea5fd7d11c88c6281dac84ca65cb51593591a5f45ed5ab39612b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Produeix la pèrdua de la condició de funcionari respecte de totes les ocupacions o càrrecs que tingués.', false), ('B', 'Produeix la pèrdua de la condició de funcionari respecte de les ocupacions o càrrecs especificats a la sentència.', true), ('C', 'Només determina el pas a la situació de suspensió de funcions mentre duri la condemna.', false), ('D', 'No afecta la condició de funcionari, sinó només el lloc de treball que ocupava.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
