with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el TREBEP, la situació de suspensió de funcions determina la pèrdua del lloc de treball quan excedeix de:', 'L''art. 90.1 TREBEP priva el funcionari suspès de l''exercici de les funcions i dels drets inherents a la condició, i la suspensió comporta la pèrdua del lloc quan excedeix de sis mesos. Sis anys és la durada màxima de la suspensió ferma per sanció disciplinària (art. 90.2).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 90.1 TREBEP', 'La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses.', null, 'bda5614b528e803393e3eec30d7fb429f89f83ddcd45ea3f947b9f4148f6e120', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bda5614b528e803393e3eec30d7fb429f89f83ddcd45ea3f947b9f4148f6e120')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres mesos.', false), ('B', 'Un any.', false), ('C', 'Sis anys.', false), ('D', 'Sis mesos.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, l''exercici de les funcions que impliquen la participació directa o indirecta en l''exercici de les potestats públiques o en la salvaguarda dels interessos generals correspon:', 'L''art. 9.2 TREBEP reserva en tot cas als funcionaris públics les funcions que impliquen la participació en l''exercici de potestats públiques o en la salvaguarda dels interessos generals.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 9.2 TREBEP', 'En todo caso, el ejercicio de las funciones que impliquen la participación directa o indirecta en el ejercicio de las potestades públicas o en la salvaguardia de los intereses generales del Estado y de las Administraciones Públicas corresponden exclusivamente a los funcionarios públicos', null, '987f6fdb03fc66032eee6ab26bd2129ce9fedcc7cbc5adb0d30aefbe299a25a6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '987f6fdb03fc66032eee6ab26bd2129ce9fedcc7cbc5adb0d30aefbe299a25a6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
