  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, quin requisit d''edat s''exigeix amb caràcter general per participar en els processos selectius d''accés a l''ocupació pública?', 'L''art. 56.1.c TREBEP exigeix tenir setze anys complerts i no excedir, si escau, l''edat màxima de jubilació forçosa; només per llei es pot establir una altra edat màxima.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 56.1.c TREBEP', 'Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.', null, 'd604f9980dc65ea4cbc3eb4e1f7680ed72b7f20cb0793052d12bd412f0536349', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd604f9980dc65ea4cbc3eb4e1f7680ed72b7f20cb0793052d12bd412f0536349')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tenir divuit anys complerts i no excedir l''edat de seixanta-cinc anys.', false), ('B', 'Tenir setze anys complerts i no excedir, si escau, l''edat màxima de jubilació forçosa.', true), ('C', 'Tenir setze anys complerts i no excedir l''edat de cinquanta-cinc anys.', false), ('D', 'Ser major d''edat, sense cap límit màxim.', false)) as v(label, body, ok)
)
