with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el TREBEP, els funcionaris de carrera tenen dret a un període d''excedència per atendre la cura de cada fill d''una durada no superior a:', 'L''art. 89.4 TREBEP reconeix una excedència de fins a tres anys per a la cura de cada fill i també de fins a tres anys per a la cura d''un familiar fins al segon grau que no es pugui valer per si mateix. El temps és computable a efectes de triennis, carrera i Seguretat Social, i el lloc es reserva almenys durant dos anys.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 89.4 TREBEP', 'Los funcionarios de carrera tendrán derecho a un período de excedencia de duración no superior a tres años para atender al cuidado de cada hijo', null, '2461df05e7df704f7fbb86025ccfae9803e83e1f4c0792b525c9f388f44a4e8d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2461df05e7df704f7fbb86025ccfae9803e83e1f4c0792b525c9f388f44a4e8d')
  returning id
), o as (
