  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos anys, a comptar de la data del naixement.', false), ('B', 'Un any, prorrogable per un altre any.', false), ('C', 'Cinc anys, a comptar de la data del naixement.', false), ('D', 'Tres anys, a comptar de la data del naixement o de la resolució judicial o administrativa.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, la sanció de suspensió ferma de funcions té una durada màxima de:', 'L''art. 96.1.c TREBEP limita la suspensió ferma de funcions (o d''ocupació i sou per al personal laboral) a una durada màxima de sis anys.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 96.1.c TREBEP', 'Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 años.', null, '7dba5407a311f6efb07b323f3c8d38f5df482081c919520cb427789717b15471', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7dba5407a311f6efb07b323f3c8d38f5df482081c919520cb427789717b15471')
