)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el TREBEP, la imposició de sancions per faltes lleus:', 'No es poden imposar sancions per faltes molt greus o greus sinó mitjançant el procediment establert, i les sancions per faltes lleus s''imposen per procediment sumari amb audiència a la persona interessada (art. 98.1 TREBEP).', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 98.1 TREBEP', 'La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado.', null, 'dce666b8d6f400467c5bed38ecc65dcbc0b9af195683ae8b44667398fcfb6ff7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'dce666b8d6f400467c5bed38ecc65dcbc0b9af195683ae8b44667398fcfb6ff7')
  returning id
), o as (
