with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, es pot nomenar personal funcionari interí per excés o acumulació de tasques per un termini màxim de:', 'L''art. 10.1 TREBEP preveu el nomenament d''interins per a vacants (màxim tres anys), substitucions, programes temporals (màxim tres anys, ampliable dotze mesos) i excés o acumulació de tasques per un màxim de nou mesos dins un període de divuit.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 10.1.d TREBEP', 'El exceso o acumulación de tareas por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses.', null, '15238119ba012e6a33c7e5ecebf64e1145e9abc94d8db3c20bb2f13a9de57cb3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '15238119ba012e6a33c7e5ecebf64e1145e9abc94d8db3c20bb2f13a9de57cb3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Nou mesos, dins un període de divuit mesos.', true), ('B', 'Sis mesos, dins un període de dotze mesos.', false), ('C', 'Tres anys.', false), ('D', 'Dotze mesos, dins un període de vint-i-quatre mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, les funcionàries víctimes de violència de gènere o de violència sexual que sol·liciten l''excedència per aquesta raó:', 'L''art. 89.5 TREBEP no exigeix temps mínim de serveis previs ni de permanència; durant els sis primers mesos hi ha reserva del lloc, computable a efectes d''antiguitat, carrera i Seguretat Social, prorrogable per períodes de tres mesos fins a un màxim de divuit quan ho exigeixin les actuacions judicials.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 89.5 TREBEP', 'Durante los seis primeros meses tendrán derecho a la reserva del puesto de trabajo que desempeñarán […] Cuando las actuaciones judiciales lo exigieran se podrá prorrogar este periodo por tres meses, con un máximo de dieciocho', null, 'ddc0f08061299ff8c7cac71c0430645d2d8191ec6d879696af0101a7dda55982', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ddc0f08061299ff8c7cac71c0430645d2d8191ec6d879696af0101a7dda55982')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Han d''haver prestat un mínim d''un any de serveis previs i tenen dret a la reserva del lloc durant dos anys.', false), ('B', 'Tenen dret a la reserva del lloc de treball durant tres anys, sense possibilitat de pròrroga.', false), ('C', 'No tenen dret a la reserva del lloc de treball, però el període és computable a efectes d''antiguitat.', false), ('D', 'Tenen dret a la reserva del lloc de treball durant els sis primers mesos, prorrogable per períodes de tres mesos fins a un màxim de divuit si ho exigeixen les actuacions judicials.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 94.2 del TREBEP, quin dels principis següents NO és un dels que regeixen l''exercici de la potestat disciplinària?', 'L''art. 94.2 TREBEP enumera els principis de legalitat i tipicitat, irretroactivitat de les disposicions sancionadores no favorables i retroactivitat de les favorables, proporcionalitat, culpabilitat i presumpció d''innocència. L''oportunitat no hi figura.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 94.2 TREBEP', 'a) Principio de legalidad y tipicidad de las faltas y sanciones, a través de la predeterminación normativa o, en el caso del personal laboral, de los convenios colectivos. b) Principio de irretroactividad de las disposiciones sancionadoras no favorables y de retroactividad de las favorables al presunto infractor. c) Principio de proporcionalidad, aplicable tanto a la clasificación de las infracciones y sanciones como a su aplicación. d) Principio de culpabilidad. e) Principio de presunción de inocencia.', null, 'df55d9809b8342eb9d2ca56db65588ac6bcc192da388ce45024eef891ff5d981', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'df55d9809b8342eb9d2ca56db65588ac6bcc192da388ce45024eef891ff5d981')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El principi de legalitat i tipicitat de les faltes i sancions.', false), ('B', 'El principi d''oportunitat.', true), ('C', 'El principi de culpabilitat.', false), ('D', 'El principi de presumpció d''innocència.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, les infraccions disciplinàries prescriuen:', 'L''art. 97.1 TREBEP fixa la prescripció de les infraccions en tres anys (molt greus), dos anys (greus) i sis mesos (lleus), i la de les sancions en tres anys, dos anys i un any, respectivament.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 97.1 TREBEP', 'Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses', 'El Decret 243/1995 (art. 22.1) fixa per als funcionaris de la Generalitat terminis diferents (sis anys, dos anys i dos mesos), que figuren com a distractor. El TREBEP és bàsic; cal confirmar quin criteri s''aplica i que la pregunta, formulada «segons el TREBEP», no generi confusió.', '00657ff6d1a495e8b5d5cfdb2058b12667c4827f71a78fbbcb5fec6f38416976', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '00657ff6d1a495e8b5d5cfdb2058b12667c4827f71a78fbbcb5fec6f38416976')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les molt greus, als sis anys; les greus, als dos anys, i les lleus, als dos mesos.', false), ('B', 'Les molt greus, als cinc anys; les greus, als tres anys, i les lleus, a l''any.', false), ('C', 'Les molt greus, als tres anys; les greus, als dos anys, i les lleus, als sis mesos.', true), ('D', 'Les molt greus, als quatre anys; les greus, als dos anys, i les lleus, als tres mesos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, la suspensió provisional com a mesura cautelar en la tramitació d''un expedient disciplinari:', 'L''art. 98.3 TREBEP limita la suspensió provisional a sis mesos, llevat de paralització imputable a l''interessat, i reconeix al funcionari suspès provisionalment el dret a percebre les retribucions bàsiques i, si escau, les prestacions familiars per fill a càrrec.', 'pcat_g5_funcio_publica', (select id from public.topics where slug = 'pcat-g5-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 98.3 TREBEP', 'La suspensión provisional como medida cautelar en la tramitación de un expediente disciplinario no podrá exceder de 6 meses, salvo en caso de paralización del procedimiento imputable al interesado. […] El funcionario suspenso provisional tendrá derecho a percibir durante la suspensión las retribuciones básicas', null, 'f045e5147fde354f59edb765d4b8f35aac148bec610e77b4bf4953d8b71870c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f045e5147fde354f59edb765d4b8f35aac148bec610e77b4bf4953d8b71870c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No pot excedir de tres mesos i el funcionari no té dret a percebre cap retribució.', false), ('B', 'No pot excedir de sis mesos, llevat de paralització del procediment imputable a l''interessat, i el funcionari té dret a percebre les retribucions bàsiques.', true), ('C', 'No pot excedir d''un any i el funcionari conserva totes les retribucions.', false), ('D', 'Es pot mantenir fins a la resolució de l''expedient, sense límit temporal, amb pèrdua de totes les retribucions.', false)) as v(label, body, ok)
)
