select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcatsup-s1-ingres-seguretat-lohc-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de «Habeas Corpus» (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s1-ingres-seguretat', 'Supòsit pràctic I. Ingressos, seguretat, escorcolls i mitjans coercitius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El detingut I.M., ingressat al centre per ordre de la policia judicial, manifesta al funcionari del departament d''ingressos que vol sol·licitar un habeas corpus perquè considera que s''ha superat el termini màxim de detenció. Segons la Llei orgànica 6/1984, què ha de fer el funcionari que el té sota custòdia?', 'L''art. 5 de la LO 6/1984 obliga el funcionari que té sota custòdia la persona privada de llibertat a posar immediatament en coneixement del jutge competent la sol·licitud d''habeas corpus; segons l''art. 2, és competent el jutge d''instrucció del lloc on es troba la persona privada de llibertat. No cal advocat ni procurador (art. 4).', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Arts. 2 i 5 LO 6/1984', 'Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad […] estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus», formulada por la persona privada de libertad que se encuentre bajo su custodia.', null, 'b11c829f79bbc03c7d6b01faf7fa8b3be50fb167bc434d522dac7cb7e5fc2d01', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b11c829f79bbc03c7d6b01faf7fa8b3be50fb167bc434d522dac7cb7e5fc2d01')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Traslladar-la al jutge de vigilància penitenciària en el termini de vint-i-quatre hores.', false), ('B', 'Lliurar-la al director perquè la resolgui, ja que l''intern és sota la custòdia del centre.', false), ('C', 'Tramitar-la només si la presenta per mitjà d''advocat i procurador.', false), ('D', 'Posar immediatament la sol·licitud en coneixement del jutge competent, que és el jutge d''instrucció del lloc on es troba la persona privada de llibertat.', true)) as v(label, body, ok)
)
