select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcatsup-s1-ingres-seguretat-rp-v1 (15 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s1-ingres-seguretat', 'Supòsit pràctic I. Ingressos, seguretat, escorcolls i mitjans coercitius') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s1-ingres-seguretat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Uns agents dels Mossos d''Esquadra, actuant com a policia judicial, porten al departament d''ingressos el detingut J.R.P. amb una ordre de detenció. Segons l''article 15 del Reglament penitenciari, quin d''aquests extrems NO ha de constar expressament en aquesta ordre?', 'L''art. 15.2 RP exigeix que l''ordre de detenció de la policia judicial contingui les dades identificatives del detingut, el delicte imputat, que es troba a disposició judicial i l''hora i el dia de venciment del termini màxim de detenció. El domicili i l''advocat no hi figuren.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 15.2 RP', 'a) Datos identificativos del detenido. b) Delito imputado. c) Que se halla a disposición judicial. d) Hora y día de vencimiento del plazo máximo de detención.', null, 'c0fd0833e20e41d8b826fd489483e7a4f96a477437cdb5a1d65bbb39f81e1756', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c0fd0833e20e41d8b826fd489483e7a4f96a477437cdb5a1d65bbb39f81e1756')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El domicili habitual del detingut i el nom del seu advocat.', true), ('B', 'El delicte imputat.', false), ('C', 'Que el detingut es troba a disposició judicial.', false), ('D', 'L''hora i el dia de venciment del termini màxim de detenció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Uns agents de policia judicial porten al centre penitenciari el detingut M.T. amb una ordre de detenció en què no consten l''hora ni el dia de venciment del termini màxim de detenció. Segons el Reglament penitenciari, què pot fer la direcció del centre?', 'Segons l''art. 15.2 RP, quan a l''ordre de detenció no consten expressament els extrems exigits (entre ells, l''hora i el dia de venciment del termini màxim de detenció), la direcció del centre pot denegar motivadament l''ingrés.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 15.2 RP', 'La Dirección del centro podrá denegar motivadamente el ingreso cuando en la orden de detención que se entregue no consten expresamente los citados extremos.', null, 'f0c8977245dbe9c379b81762ac77a0bd670c14589d0469713c6501d31106fcfd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f0c8977245dbe9c379b81762ac77a0bd670c14589d0469713c6501d31106fcfd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Admetre''l i completar ella mateixa les dades que falten a l''ordre.', false), ('B', 'Denegar motivadament l''ingrés.', true), ('C', 'Admetre''l provisionalment i demanar al jutge de vigilància penitenciària que confirmi l''ingrés en 72 hores.', false), ('D', 'Admetre''l en règim d''incomunicació fins que arribi una ordre completa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El centre admet l''ingrés del detingut A.L., que arriba amb una ordre de detenció de la policia judicial completa. Segons el Reglament penitenciari, en quin termini el director ha de comunicar l''ingrés a l''autoritat judicial a la disposició de la qual es troba el detingut?', 'L''art. 23.2 RP obliga el director a comunicar l''ingrés del detingut, pel mitjà més ràpid que deixi constància de la recepció, a l''autoritat judicial a la disposició de la qual es troba, dins de les 24 hores següents a l''ingrés.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 23.2 RP', 'el Director del establecimiento o quien haga sus veces comunicará el ingreso, por el medio más rápido disponible que deje constancia de la recepción de la comunicación, a la autoridad judicial a cuya disposición se encuentre el detenido, dentro de las veinticuatro horas siguientes a su ingreso.', null, 'c693c2a582b46ddde30c33ee1aad2de2ed628d1f8afe50517adc8b05f9353851', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c693c2a582b46ddde30c33ee1aad2de2ed628d1f8afe50517adc8b05f9353851')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les quaranta-vuit hores següents a l''ingrés.', false), ('B', 'Dins de les setanta-dues hores següents a l''ingrés.', false), ('C', 'Dins de les vint-i-quatre hores següents a l''ingrés.', true), ('D', 'Dins dels cinc dies que pot durar l''estada al departament d''ingressos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El detingut P.G. va ingressar al centre per ordre de la policia judicial i el director en va comunicar l''ingrés al jutjat. Han passat setanta-dues hores des de l''ingrés i no s''ha rebut cap ordre ni manament judicial. Segons el Reglament penitenciari, què s''ha de fer?', 'L''art. 23.3 RP disposa que, si en el termini màxim de 72 hores des de l''ingrés o des de la detenció no s''ha rebut ordre o manament judicial, s''ha d''excarcerar l''intern i comunicar-ho a l''autoritat que en va ordenar l''ingrés i a l''autoritat judicial.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 23.3 RP', 'si en el plazo máximo de setenta y dos horas desde su ingreso o desde su detención no se hubiese recibido orden o mandamiento judicial, se procederá a excarcelar al interno, comunicándolo por el mismo medio a la autoridad que ordenó el ingreso y a la autoridad judicial a cuya disposición hubiese sido puesto.', null, 'f2c4674464c9d035b587483f47944b8f1ecf7e271c5d6196dc332b82ae8b4b0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f2c4674464c9d035b587483f47944b8f1ecf7e271c5d6196dc332b82ae8b4b0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mantenir-lo ingressat fins que arribi el manament, perquè ja ha estat admès.', false), ('B', 'Posar-lo a disposició del jutge de vigilància penitenciària perquè decideixi.', false), ('C', 'Demanar al centre directiu una pròrroga de la detenció de vint-i-quatre hores.', false), ('D', 'Excarcerar-lo i comunicar-ho per la mateixa via a l''autoritat que va ordenar l''ingrés i a l''autoritat judicial a la disposició de la qual va ser posat.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El dissabte a la nit ingressa al centre l''intern preventiu E.S. Segons el Reglament penitenciari, en quin termini ha de ser examinat pel metge?', 'L''art. 214.1 RP estableix que tots els interns, en ingressar, han de ser examinats per un metge i que el reconeixement s''ha de fer durant les primeres 24 hores a partir de l''ingrés.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 214.1 RP', 'Todos los internos, a su ingreso en el Establecimiento, serán examinados por un médico. El reconocimiento se llevará a cabo durante las primeras veinticuatro horas a partir del ingreso.', null, '4505315e2f28347399e8cdbce26ac203f6e8fc6b42fecc639da556ffbf2798cb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4505315e2f28347399e8cdbce26ac203f6e8fc6b42fecc639da556ffbf2798cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Durant les primeres setanta-dues hores a partir de l''ingrés.', false), ('B', 'Durant les primeres vint-i-quatre hores a partir de l''ingrés.', true), ('C', 'Abans que acabi la seva estada al departament d''ingressos, que pot durar cinc dies.', false), ('D', 'El primer dia feiner següent a l''ingrés.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern preventiu R.S. fa cinc dies que és al departament d''ingressos i els serveis mèdics aconsellen que s''hi quedi uns dies més per un problema de salut. Segons el Reglament penitenciari, es pot prolongar l''estada i a qui s''ha de donar compte de la pròrroga?', 'L''art. 20.3 RP limita l''estada al departament d''ingressos a cinc dies, que només es poden prolongar per motius d''ordre sanitari o per preservar la seguretat de l''intern, i de la pròrroga s''ha de donar compte al jutge de vigilància.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 20.3 RP', 'La estancia de preventivos o penados en el departamento de ingresos será, como máximo, de cinco días y sólo podrá prolongarse por motivos de orden sanitario o para preservar su seguridad. De la prolongación se dará cuenta al Juez de Vigilancia correspondiente.', null, '6817442f119411459c10466b29d84cc62584b22e64f30e0086b260f692bf821c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6817442f119411459c10466b29d84cc62584b22e64f30e0086b260f692bf821c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, perquè l''estada màxima de cinc dies no admet cap excepció.', false), ('B', 'Sí, però només amb l''autorització prèvia del centre directiu.', false), ('C', 'Sí, per motius d''ordre sanitari, donant-ne compte al jutge de vigilància corresponent.', true), ('D', 'Sí, per qualsevol motiu, donant-ne compte al jutge d''instrucció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern K.D., de nacionalitat estrangera, ingressa per primer cop al centre penitenciari. Segons el Reglament penitenciari, com s''ha de procedir respecte de la comunicació del seu ingrés a les autoritats consulars del seu país?', 'L''art. 15.5 RP reconeix als interns estrangers el dret que el seu ingrés es posi en coneixement de les autoritats diplomàtiques o consulars; en el moment de l''ingrés se''ls ha d''informar d''aquest dret i demanar-los per escrit l''autorització per fer la comunicació.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 15.5 RP', 'Los internos extranjeros tienen derecho a que se ponga en conocimiento de las autoridades diplomáticas o consulares correspondientes su ingreso en prisión. A tal fin, en el momento del ingreso, incluido el voluntario a que se refiere el artículo siguiente, se les informará de forma comprensible, a ser posible en su propio idioma, de este derecho, recabando por escrito su autorización para proceder, en su caso, a tal comunicación.', null, '1d85c34d4b99491022408d676cb2b183a76c6f0e3b6b1b058bf065fd74cd0618', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1d85c34d4b99491022408d676cb2b183a76c6f0e3b6b1b058bf065fd74cd0618')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha d''informar l''intern d''aquest dret i demanar-li per escrit l''autorització per fer la comunicació.', true), ('B', 'El centre ho ha de comunicar sempre d''ofici, encara que l''intern s''hi oposi.', false), ('C', 'Només s''ha de comunicar si ho ordena el jutge que n''ha decretat la presó.', false), ('D', 'Només es pot comunicar un cop l''intern hagi estat classificat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'S.G., que té una condemna ferma pendent de complir, es presenta voluntàriament a la porta del centre penitenciari i hi és admès. Segons el Reglament penitenciari, en quin termini el director ha de demanar al jutge o tribunal el manament corresponent?', 'En els ingressos voluntaris, l''art. 16.3 RP obliga el director a demanar al jutge o tribunal el manament corresponent dins de les 24 hores següents a l''ingrés. Les 72 hores de l''art. 16.4 són el termini a partir del qual, si no s''ha rebut la documentació, s''ha d''excarcerar l''ingressat.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 16.3 RP', 'En los casos de ingresos voluntarios, el Director del centro recabará del Juez o Tribunal, dentro de las veinticuatro horas siguientes al ingreso, el correspondiente mandamiento', null, '5a67af39039743e035261fba9b6ea372ca8143c339f8c0eefe6fbb17ed5b9119', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5a67af39039743e035261fba9b6ea372ca8143c339f8c0eefe6fbb17ed5b9119')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les quaranta-vuit hores següents a l''ingrés.', false), ('B', 'Dins de les setanta-dues hores següents a l''ingrés.', false), ('C', 'Dins dels cinc dies següents a l''ingrés.', false), ('D', 'Dins de les vint-i-quatre hores següents a l''ingrés.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El manament de presó de l''intern preventiu L.F. disposa la seva incomunicació. Segons el Reglament penitenciari, amb qui pot comunicar mentre duri aquesta situació?', 'L''art. 19.1 RP disposa que el detingut o pres incomunicat ocupa una cel·la individual, és reconegut pel metge, és atès exclusivament pels funcionaris encarregats i únicament pot comunicar amb les persones que tinguin autorització expressa del jutge.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 19.1 RP', 'Únicamente podrá comunicar con las personas que tengan expresa autorización del Juez.', null, '75bdedd76966aa390298acc4bab563b9c8b25399e7a443b42020e8258fbffc8e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '75bdedd76966aa390298acc4bab563b9c8b25399e7a443b42020e8258fbffc8e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb el seu advocat i amb els familiars de primer grau.', false), ('B', 'Amb les persones que autoritzi el director del centre.', false), ('C', 'Només amb les persones que tinguin autorització expressa del jutge.', true), ('D', 'Amb qualsevol persona, sempre que la comunicació sigui intervinguda.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionari del mòdul 2 té informació contrastada segons la qual l''intern T.V. amaga al seu cos un objecte punxant. Segons l''article 68 del Reglament penitenciari, qui ha d''autoritzar el cacheig (escorcoll) amb despullament integral?', 'L''art. 68.2 RP permet l''escorcoll amb despullament integral per motius de seguretat concrets i específics, quan hi ha raons individuals i contrastades que l''intern amaga al cos un objecte perillós, amb autorització del cap de serveis (Jefe de Servicios).', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.2 RP', 'se podrá realizar cacheo con desnudo integral con autorización del Jefe de Servicios.', null, '37c7193cc6d77d3657d96ac05018d71ee75577000dedc32faf821c8fb081dd1f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '37c7193cc6d77d3657d96ac05018d71ee75577000dedc32faf821c8fb081dd1f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director del centre.', false), ('B', 'El cap de serveis.', true), ('C', 'El jutge de vigilància penitenciària.', false), ('D', 'El subdirector d''interior.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El cap de serveis ha autoritzat un escorcoll amb despullament integral a la interna B.M. Segons el Reglament penitenciari, com s''ha de practicar?', 'L''art. 68.3 RP disposa que l''escorcoll amb despullament integral l''han de fer funcionaris del mateix sexe que l''intern, en lloc tancat, sense la presència d''altres interns i preservant, tant com es pugui, la intimitat.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 68.3 RP', 'El cacheo con desnudo integral se efectuará por funcionarios del mismo sexo que el interno, en lugar cerrado sin la presencia de otros internos y preservando, en todo lo posible, la intimidad.', null, '02f7f9f6fc0d6b53c2404dd70d9f4b70aff4d5873dfd4a4b2e90e7bea57a284d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '02f7f9f6fc0d6b53c2404dd70d9f4b70aff4d5873dfd4a4b2e90e7bea57a284d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per funcionàries del mateix sexe que la interna, en un lloc tancat, sense presència d''altres interns i preservant al màxim la intimitat.', true), ('B', 'Per qualsevol funcionari de servei, en presència d''una altra interna que actuï com a testimoni.', false), ('C', 'Per personal sanitari, a la infermeria i en presència del metge de guàrdia.', false), ('D', 'Per funcionàries del mateix sexe, en un espai obert del mòdul per garantir-ne la visibilitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durant un incident al mòdul 4, l''intern C.J. s''enfronta violentament als funcionaris. Segons l''article 72 del Reglament penitenciari, quin dels següents NO és un mitjà coercitiu?', 'L''art. 72.1 RP enumera com a mitjans coercitius l''aïllament provisional, la força física personal, les defenses de goma, els aerosols d''acció adequada i les manilles. La privació de passeigs i actes recreatius és una sanció disciplinària (art. 42.2 LOGP), no un mitjà coercitiu.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.1 RP', 'Son medios coercitivos, a los efectos del artículo 45.1 de la Ley Orgánica General Penitenciaria, el aislamiento provisional, la fuerza física personal, las defensas de goma, los aerosoles de acción adecuada y las esposas.', null, '052d44d65a4b8d0dc9c5b066fb4d1c4318d34a65b210fcdfa00a7a7c5bc004f7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '052d44d65a4b8d0dc9c5b066fb4d1c4318d34a65b210fcdfa00a7a7c5bc004f7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''aïllament provisional.', false), ('B', 'Les defenses de goma.', false), ('C', 'Els aerosols d''acció adequada.', false), ('D', 'La privació de passeigs i actes recreatius comuns.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director autoritza l''aplicació de l''aïllament provisional a l''intern Y.B., que ha trencat el mobiliari de la cel·la i amenaça d''autolesionar-se. Segons el Reglament penitenciari, què ha de comunicar el director al jutge de vigilància?', 'L''art. 72.3 RP obliga el director a comunicar immediatament al jutge de vigilància l''adopció i el cessament dels mitjans coercitius, amb expressió detallada dels fets que n''han motivat l''ús i de les circumstàncies que en puguin aconsellar el manteniment.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 72.3 RP', 'El Director comunicará inmediatamente al Juez de Vigilancia la adopción y cese de los medios coercitivos, con expresión detallada de los hechos que hubieran dado lugar a dicha utilización y de las circunstancias que pudiesen aconsejar su mantenimiento.', null, 'bf19a91196c8e7ed06616070c4a7f4d77c5d5963ba2d59c1991e1c5e783065cd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bf19a91196c8e7ed06616070c4a7f4d77c5d5963ba2d59c1991e1c5e783065cd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Immediatament, l''adopció i el cessament del mitjà coercitiu, amb expressió detallada dels fets i de les circumstàncies que en puguin aconsellar el manteniment.', true), ('B', 'Només el cessament de la mesura, en el termini de setanta-dues hores.', false), ('C', 'Res, perquè l''aïllament provisional autoritzat pel director no s''ha de comunicar.', false), ('D', 'L''adopció de la mesura, només si es manté més de catorze dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Després d''una baralla al mòdul 3, es vol comprovar que tots els interns són a les seves cel·les fora dels horaris de recompte fixats. Segons el Reglament penitenciari, qui ordena aquest recompte extraordinari?', 'L''art. 67.2 RP preveu els recomptes extraordinaris que ordeni el cap de serveis, comunicant-ho a la direcció; els horaris dels recomptes ordinaris els fixa el Consell de Direcció (art. 67.1 RP).', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 67.2 RP', 'También se efectuarán los recuentos extraordinarios que se ordenen por el Jefe de Servicios, comunicándolo a la Dirección', null, '6293928fbbffc70d0078553bc8793f71b5ab3996a243f3fa01bfacf680e0992c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6293928fbbffc70d0078553bc8793f71b5ab3996a243f3fa01bfacf680e0992c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consell de Direcció, reunit en sessió extraordinària.', false), ('B', 'El cap de serveis, comunicant-ho a la direcció.', true), ('C', 'El cap d''unitat, sense necessitat de comunicar-ho a ningú.', false), ('D', 'El subdirector de tractament, amb l''informe previ de la Junta de Tractament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern N.E. demana protecció perquè altres interns del mòdul l''han amenaçat de mort. Segons l''article 75 del Reglament penitenciari, qui pot acordar limitacions regimentals per protegir-lo i a qui se n''ha de donar compte?', 'L''art. 75.2 RP permet al director, a sol·licitud de l''intern o per iniciativa pròpia, acordar mitjançant resolució motivada mesures que impliquin limitacions regimentals per salvaguardar la vida o la integritat física de l''intern, donant-ne compte al jutge de vigilància.', 'pcatsup_s1_ingres_seguretat', (select id from public.topics where slug = 'pcatsup-s1-ingres-seguretat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 75.2 RP', 'En su caso, a solicitud del interno o por propia iniciativa, el Director podrá acordar mediante resolución motivada, cuando fuere preciso para salvaguardar la vida o integridad física del recluso, la adopción de medidas que impliquen limitaciones regimentales, dando cuenta al Juez de Vigilancia.', null, 'b3dc04ae0b10b98938c8a3cd222f815d5e76eba57f0df73ff28f76c9cfeb9f73', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b3dc04ae0b10b98938c8a3cd222f815d5e76eba57f0df73ff28f76c9cfeb9f73')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director, mitjançant resolució motivada, donant-ne compte al jutge de vigilància.', true), ('B', 'La Junta de Tractament, donant-ne compte al centre directiu.', false), ('C', 'El cap de serveis, sense necessitat de donar-ne compte a ningú.', false), ('D', 'La Comissió Disciplinària, donant-ne compte al Ministeri Fiscal.', false)) as v(label, body, ok)
)
