select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Junta de Tractament acorda proposar la regressió a primer grau de l''intern K.M. després d''una agressió greu a un company. Segons la Circular 2/2017, en quin termini màxim s''han d''elevar la proposta i els informes, i quan s''ha de revisar la regressió?', 'Segons l''apartat IV.2 de la Circular 2/2017, la proposta de regressió i els informes s''han d''elevar en un termini màxim de 10 dies i per via telemàtica (art. 32.3 del Decret 329/2006), i la Junta de Tractament ha de revisar la regressió, com a màxim, al cap de 3 mesos de la resolució.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://justicia.gencat.cat/web/.content/home/departament/legislacio/instruccions_i_circulars/instruccio_SP_2_2017.pdf'), 'Circular 2/2017, apartat IV.2', 'En tot cas, la proposta i els informes s’han d’elevar en el termini màxim de 10 dies i per via telemàtica d’acord amb l’article 32.3 del ROFSEPC. La regressió l’haurà de revisar la Junta de Tractament, com a màxim, al cap de 3 mesos de la data de la resolució.', null, '8a6e9e25ac89a47720a4d630d0a6cc1e05cc15ad4ea650568452d1251b8ce2f0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8a6e9e25ac89a47720a4d630d0a6cc1e05cc15ad4ea650568452d1251b8ce2f0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En setanta-dues hores; la regressió s''ha de revisar cada sis mesos.', false), ('B', 'En deu dies i per via telemàtica; la Junta de Tractament ha de revisar la regressió com a màxim al cap de tres mesos de la data de la resolució.', true), ('C', 'En catorze dies; la regressió s''ha de revisar al cap de quaranta-cinc dies.', false), ('D', 'En dos mesos; la regressió s''ha de revisar cada any.', false)) as v(label, body, ok)
)
