with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Després de diversos incidents greus protagonitzats pel penat L.N., l''equip multidisciplinari considera que concorren els supòsits de l''article 10 de la LOGP. Segons el Decret 329/2006, quin òrgan proposa al centre directiu l''aplicació del règim tancat i amb quins informes previs?', 'L''art. 32.1.c) del Decret 329/2006 atribueix a la Junta de Tractament la funció de proposar al centre directiu l''aplicació del règim tancat als penats i preventius, amb els informes preceptius previs del cap de serveis i de l''equip multidisciplinari de la unitat residencial.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252'), 'Art. 32.1.c) Decret 329/2006', 'Proposar al centre directiu l''aplicació del règim tancat als/a les penats/ades i preventius/ives en els/les quals concorrin les circumstàncies previstes per la legislació penitenciària, amb els informes preceptius previs del/de la cap de serveis i de l''equip multidisciplinari de la unitat residencial que correspongui.', null, '169b1a4b3878f6c87eeffbe0905cd47072ec75a437aa230c25b3ab0d1a2d9862', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '169b1a4b3878f6c87eeffbe0905cd47072ec75a437aa230c25b3ab0d1a2d9862')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Junta de Tractament, amb els informes preceptius previs del cap de serveis i de l''equip multidisciplinari de la unitat residencial.', true), ('B', 'La Comissió Disciplinària, amb l''informe previ del subdirector d''interior.', false), ('C', 'El Consell de Direcció, amb l''informe previ dels serveis mèdics.', false), ('D', 'El director, amb l''informe previ del jutge de vigilància penitenciària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
