insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s2-classificacio-comunicacions' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Junta de Tractament proposa la regressió a primer grau del penat A.C., classificat en segon grau, i la seva destinació al departament especial de règim tancat (DERT). Segons el Reglament penitenciari, qui és competent per acordar el trasllat i en quin termini se n''ha de donar coneixement al jutge de vigilància penitenciària?', 'L''art. 95.1 RP atribueix al centre directiu, per resolució motivada i amb proposta raonada de la Junta de Tractament, el trasllat d''un penat a un departament especial o establiment de règim tancat, i d''aquest acord s''ha de donar coneixement al jutge de vigilància dins de les 72 hores següents.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 95.1 RP', 'competerá al Centro Directivo mediante resolución motivada, previa propuesta razonada de la Junta de Tratamiento contenida en el ejemplar de clasificación o, en su caso, en el de regresión de grado. De este acuerdo se dará conocimiento al Juez de Vigilancia Penitenciaria dentro de las setenta y dos horas siguientes a su adopción.', null, 'f3a70c161519e520152d65ddc613828f38990c16d1e68a848985984dc4b6f644', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f3a70c161519e520152d65ddc613828f38990c16d1e68a848985984dc4b6f644')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director del centre; dins de les vint-i-quatre hores següents.', false), ('B', 'La Junta de Tractament; dins dels catorze dies següents.', false), ('C', 'El centre directiu; dins dels deu dies següents.', false), ('D', 'El centre directiu, mitjançant resolució motivada; dins de les setanta-dues hores següents a l''adopció.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El penat B.D., classificat en segon grau, pren com a ostatge un funcionari durant un motí. El centre directiu n''acorda el trasllat a un establiment de règim tancat abans que hi hagi resolució de classificació en primer grau. Segons el Reglament penitenciari, en quin termini s''ha de dictar aquesta resolució classificatòria?', 'L''art. 95.3 RP permet al centre directiu, si hi ha motí, agressió física amb arma o objecte perillós, presa d''ostatges o intent violent d''evasió, traslladar el penat a règim tancat abans de la classificació en primer grau, que s''ha de fer dins dels 14 dies següents, donant compte immediatament del trasllat al jutge de vigilància.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 95.3 RP', 'Mediando motín, agresión física con arma u objeto peligroso, toma de rehenes o intento violento de evasión, el traslado del penado a un Establecimiento de régimen cerrado podrá acordarse por el Centro Directivo, aunque no se haya producido resolución clasificatoria en primer grado, que, en todo caso, deberá efectuarse dentro de los catorce días siguientes, dando cuenta inmediatamente del traslado al Juez de Vigilancia.', null, 'f58e7e56b11f94b80cc34cb2c01164792d995e7995409ac7e5325cf1a8a7f03b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f58e7e56b11f94b80cc34cb2c01164792d995e7995409ac7e5325cf1a8a7f03b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins de les setanta-dues hores següents.', false), ('B', 'Dins dels catorze dies següents, donant compte immediatament del trasllat al jutge de vigilància.', true), ('C', 'Dins dels deu dies següents.', false), ('D', 'Dins dels dos mesos següents.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El penat C.E., classificat en primer grau, va ser l''inductor d''un motí en què es va posar en perill la vida de diversos funcionaris, i se n''evidencia una perillositat extrema. Segons l''article 91 del Reglament penitenciari, on ha de ser destinat?', 'L''art. 91.3 RP destina als departaments especials els penats en primer grau que han estat protagonistes o inductors d''alteracions regimentals molt greus que han posat en perill la vida o la integritat de funcionaris o altres persones, i en els quals s''evidencia una perillositat extrema. Els centres o mòduls de règim tancat són per a la inadaptació manifesta (art. 91.2 RP).', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 91.3 RP', 'Serán destinados a departamentos especiales aquellos penados clasificados en primer grado que hayan sido protagonistas o inductores de alteraciones regimentales muy graves, que hayan puesto en peligro la vida o integridad de los funcionarios', null, '4d2ca29e2b650602f0026e9b627316ae47796781234c196fb593bb17bfc41bbb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4d2ca29e2b650602f0026e9b627316ae47796781234c196fb593bb17bfc41bbb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A un departament especial.', true), ('B', 'A un centre o mòdul de règim tancat, previst per a la inadaptació manifesta als règims comuns.', false), ('C', 'A una unitat de règim obert restringit.', false), ('D', 'Al departament d''ingressos fins que es resolgui l''expedient disciplinari.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern D.F. és al departament especial, en la modalitat de vida de l''article 93 del Reglament penitenciari. Segons aquest article, de quantes hores diàries de sortida al pati ha de gaudir, com a mínim?', 'La norma 1a de l''art. 93.1 RP garanteix als interns dels departaments especials un mínim de tres hores diàries de sortida al pati, ampliables fins a tres hores més per a activitats programades. Les quatre hores de vida en comú corresponen als mòduls o centres tancats (art. 94 RP).', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP', 'Los internos disfrutarán, como mínimo, de tres horas diarias de salida al patio.', null, 'ea7de637ce4cf971492182c9de8b6f9bc18d14eea54c79b0d496767c86a97989', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ea7de637ce4cf971492182c9de8b6f9bc18d14eea54c79b0d496767c86a97989')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues hores.', false), ('B', 'Quatre hores.', false), ('C', 'Tres hores.', true), ('D', 'Sis hores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al departament especial, el funcionari ha d''organitzar les sortides al pati dels interns E.G., F.H. i G.I. Segons l''article 93 del Reglament penitenciari, quants interns poden estar junts al pati, com a màxim, quan no es fan activitats programades?', 'La norma 3a de l''art. 93.1 RP estableix que en les sortides al pati no hi poden estar mai més de dos interns junts; aquest nombre es pot augmentar fins a un màxim de cinc per fer activitats programades.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP', 'En las salidas al patio no podrán permanecer, en ningún caso, más de dos internos juntos. Este número podrá aumentarse hasta un máximo de cinco para la ejecución de actividades programadas.', null, '386ceceaa86719060e73358577564b29548ad9115a83e154831733e801be53c1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '386ceceaa86719060e73358577564b29548ad9115a83e154831733e801be53c1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres.', false), ('B', 'Dos.', true), ('C', 'Quatre.', false), ('D', 'Cinc.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern H.J. és al departament especial (art. 93 RP). Un matí hi ha sospites fonamentades que té un objecte prohibit i raons d''urgència exigeixen actuar immediatament. Segons el Reglament penitenciari, quina afirmació és correcta?', 'La norma 2a de l''art. 93.1 RP imposa el registre diari de les cel·les i l''escorcoll dels interns i permet el despullament integral, quan hi ha sospites fonamentades i raons d''urgència, per ordre motivada del cap de serveis, donant-ne compte al director.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 93.1 RP', 'Diariamente deberá practicarse registro de las celdas y cacheo de los internos. Cuando existan fundadas sospechas de que el interno posee objetos prohibidos y razones de urgencia exijan una actuación inmediata, podrá recurrirse al desnudo integral por orden motivada del Jefe de Servicios, dando cuenta al Director.', null, '18a2e70a952fe4cc16fdb0e58d6b618f00a7396ab59d5b7f6c4532e63cab4bff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '18a2e70a952fe4cc16fdb0e58d6b618f00a7396ab59d5b7f6c4532e63cab4bff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El registre de la cel·la es fa setmanalment, i el despullament integral l''ha d''ordenar el director, donant-ne compte al jutge de vigilància.', false), ('B', 'El registre de la cel·la es fa diàriament, però el despullament integral requereix l''autorització prèvia del jutge de guàrdia.', false), ('C', 'El registre de la cel·la i l''escorcoll s''hi fan diàriament, i el despullament integral el pot ordenar el cap de serveis per ordre motivada, donant-ne compte al director.', true), ('D', 'El cap d''unitat pot ordenar verbalment el despullament integral sense donar-ne compte a ningú.', false)) as v(label, body, ok)
)
