select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern M.O., classificat en tercer grau, és detingut una nit en què tenia autoritzat no pernoctar al centre i és imputat per un nou delicte. Segons l''article 108 del Reglament penitenciari, què pot acordar el director?', 'L''art. 108.3 RP permet al director, quan un intern de tercer grau és detingut, ingressat a presó, processat o imputat per presumptes noves responsabilitats, suspendre cautelarment les noves sortides, acordar la separació interior i el pas provisional a règim ordinari; la Junta de Tractament ha de fer immediatament la reclassificació.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 108.3 RP', 'En los supuestos de internos clasificados en tercer grado que fuesen detenidos, ingresados en prisión, procesados o imputados judicialmente por presuntas nuevas responsabilidades, el Director podrá suspender cautelarmente cualquier nueva salida, así como acordar la separación interior que proceda y su pase provisional a régimen ordinario, debiendo proceder la Junta de Tratamiento inmediatamente a la reclasificación correspondiente en su caso.', null, '5712df8c12bbdbc3c051180b509365ef5ce19e54a653cdd7c61870047451aa70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5712df8c12bbdbc3c051180b509365ef5ce19e54a653cdd7c61870047451aa70')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Classificar-lo directament en primer grau, sense intervenció de la Junta de Tractament.', false), ('B', 'Mantenir-lo en tercer grau fins que hi hagi una sentència ferma.', false), ('C', 'Suspendre cautelarment qualsevol nova sortida i acordar-ne el pas provisional a règim ordinari; la Junta de Tractament n''ha de fer immediatament la reclassificació.', true), ('D', 'Privar-lo de permisos de sortida durant dos mesos sense necessitat d''expedient.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Durant una comunicació oral al locutori, la visitant de l''intern N.P. insulta reiteradament el funcionari i no manté un comportament correcte. Segons el Reglament penitenciari, qui pot ordenar la suspensió de la comunicació?', 'L''art. 44.1 RP permet al cap de serveis (Jefe de Servicios) ordenar la suspensió de les comunicacions orals, per iniciativa pròpia o a proposta del funcionari, entre altres casos quan els comunicants no observen un comportament correcte.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 44.1 RP', 'El Jefe de Servicios podrá ordenar la suspensión de las comunicaciones orales, por propia iniciativa o a propuesta del funcionario encargado del servicio, en los siguientes casos: […] b) Cuando los comunicantes no observen un comportamiento correcto.', null, '296610f6867dadc4dc5c686c720a713409b246f7474d0932e6cedf5a792b0727', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '296610f6867dadc4dc5c686c720a713409b246f7474d0932e6cedf5a792b0727')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El director, amb l''informe previ de la Junta de Tractament.', false), ('B', 'El jutge de vigilància penitenciària.', false), ('C', 'El subdirector de tractament.', false), ('D', 'El cap de serveis, per iniciativa pròpia o a proposta del funcionari encarregat del servei.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El cap de serveis suspèn la comunicació oral de l''intern O.Q. perquè hi ha raons fundades per creure que els comunicants preparen una actuació delictiva. Segons el Reglament penitenciari, quin tràmit s''ha de seguir després?', 'L''art. 44.2 RP disposa que el cap de serveis ha de donar compte immediat de la suspensió al director i que aquest, si ratifica la mesura en resolució motivada, n''ha de donar compte al jutge de vigilància el mateix dia o l''endemà.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 44.2 RP', 'El Jefe de Servicios dará cuenta inmediata de la suspensión al Director del centro y éste, a su vez, si ratifica la medida en resolución motivada, deberá dar cuenta al Juez de Vigilancia en el mismo día o al día siguiente.', null, '9af92274187c684cb3dfa27ef9290a399437287f508067cc2daa9fb0286a0158', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9af92274187c684cb3dfa27ef9290a399437287f508067cc2daa9fb0286a0158')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis n''ha de donar compte directament al jutge de vigilància dins de les setanta-dues hores.', false), ('B', 'El cap de serveis n''ha de donar compte immediat al director, i aquest, si ratifica la mesura en resolució motivada, n''ha de donar compte al jutge de vigilància el mateix dia o l''endemà.', true), ('C', 'La suspensió l''ha de ratificar la Junta de Tractament en la sessió ordinària següent.', false), ('D', 'No cal cap tràmit, perquè la suspensió esgota els efectes en el mateix moment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern P.R. vol rebre, en una comunicació oral ordinària, la visita de la seva mare, dos germans, la seva parella i un amic. Segons el Reglament penitenciari, quantes persones poden comunicar simultàniament amb ell, com a màxim?', 'La norma 2a de l''art. 42 RP estableix que l''horari ha de permetre comunicacions de vint minuts com a mínim i que no poden comunicar més de quatre persones simultàniament amb el mateix intern.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 42 RP', 'El horario destinado a este servicio será suficiente para permitir una comunicación de veinte minutos de duración como mínimo, no pudiendo comunicar más de cuatro personas simultáneamente con el mismo interno.', null, '8af39db338f12cb1c02aa2407821e0c304079061bc4bdb7b8b7a99fadae77fd1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8af39db338f12cb1c02aa2407821e0c304079061bc4bdb7b8b7a99fadae77fd1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues.', false), ('B', 'Tres.', false), ('C', 'Quatre.', true), ('D', 'Cinc.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern Q.S., que no gaudeix de permisos de sortida, sol·licita una comunicació íntima amb la seva parella. Segons el Reglament penitenciari, amb quina freqüència i durada s''ha de concedir?', 'L''art. 45.4 RP disposa que, prèvia sol·licitud, s''ha de concedir com a mínim una comunicació íntima al mes, d''una durada no superior a tres hores ni inferior a una, llevat que raons d''ordre o seguretat ho impedeixin.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 45.4 RP', 'Previa solicitud del interno, se concederá una comunicación íntima al mes como mínimo, cuya duración no será superior a tres horas ni inferior a una, salvo que razones de orden o de seguridad del establecimiento lo impidan.', null, '0a6faf31915f624331394985870b1c13dbd4629e35901e840bdf4ce1caeaf4c6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a6faf31915f624331394985870b1c13dbd4629e35901e840bdf4ce1caeaf4c6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com a mínim una al mes, d''una durada no superior a tres hores ni inferior a una.', true), ('B', 'Com a mínim una a la setmana, de dues hores.', false), ('C', 'Com a màxim una al mes, de sis hores.', false), ('D', 'Com a mínim dues al mes, d''una durada no inferior a tres hores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern R.T. té intervingudes les comunicacions ordinàries per raons de seguretat. Segons el Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'L''art. 48.3 RP prohibeix que les comunicacions amb l''advocat defensor es suspenguin o intervinguin per decisió administrativa: només es pot fer amb ordre expressa de l''autoritat judicial. L''art. 49.2 RP exclou de tota suspensió, intervenció o restricció administrativa les comunicacions amb el Defensor del Poble, les institucions anàlogues autonòmiques, les autoritats judicials i el Ministeri Fiscal.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Arts. 48.3 i 49.2 RP', 'no podrán ser suspendidas o intervenidas, en ningún caso, por decisión administrativa. La suspensión o la intervención de estas comunicaciones sólo podrá realizarse previa orden expresa de la autoridad judicial. […] Las comunicaciones orales y escritas de los internos con el Defensor del Pueblo o sus Adjuntos o delegados o con instituciones análogas de las Comunidades Autónomas, Autoridades judiciales y miembros del Ministerio Fiscal no podrán ser suspendidas, ni ser objeto de intervención o restricción administrativa de ningún tipo.', null, '8398342537c3d0146034fe8b5def66c60fee83a2d23b9b950ca1686327bdbd45', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8398342537c3d0146034fe8b5def66c60fee83a2d23b9b950ca1686327bdbd45')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La comunicació amb el seu advocat defensor només es pot suspendre o intervenir amb una ordre expressa de l''autoritat judicial.', false), ('B', 'Les comunicacions orals i escrites amb el Defensor del Poble no poden ser suspeses ni objecte d''intervenció administrativa.', false), ('C', 'Les comunicacions amb les autoritats judicials i el Ministeri Fiscal no poden ser objecte de restricció administrativa.', false), ('D', 'El director pot suspendre, per raons de seguretat, la comunicació amb el seu advocat defensor en la causa penal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per raons de seguretat, el director acorda intervenir la correspondència del penat S.U. Segons el Reglament penitenciari, a qui s''ha de comunicar aquesta decisió?', 'La norma 5a de l''art. 46 RP disposa que la intervenció de les comunicacions escrites acordada pel director s''ha de comunicar als interns afectats i, si són penats, al jutge de vigilància (si són detinguts o presos, a l''autoritat judicial de què depenen).', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 46.5 RP', 'En los casos en que, por razones de seguridad, del buen orden del establecimiento o del interés del tratamiento, el Director acuerde la intervención de las comunicaciones escritas, esta decisión se comunicará a los internos afectados y también a la autoridad judicial de que dependa si se trata de detenidos o presos, o al Juez de Vigilancia si se trata de penados.', null, '3faf3deb9b3c66a736d75e97ec9c81d39f79bc287cdd06f54d5aad96032e9f74', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3faf3deb9b3c66a736d75e97ec9c81d39f79bc287cdd06f54d5aad96032e9f74')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només a l''intern afectat.', false), ('B', 'A l''intern afectat i al jutge o tribunal sentenciador.', false), ('C', 'Al centre directiu i al Ministeri Fiscal.', false), ('D', 'A l''intern afectat i al jutge de vigilància.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Els familiars de l''intern T.V. viuen a l''estranger i no el poden visitar, i el director n''ha autoritzat les comunicacions telefòniques. Segons el Reglament penitenciari, quina freqüència mínima de trucades s''ha de garantir i quina durada mínima han de tenir?', 'L''art. 47.4 RP garanteix una freqüència mínima de cinc trucades per setmana; la durada la fixen les normes de règim interior, però no pot ser inferior a cinc minuts.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 47.4 RP', 'garantizando una frecuencia mínima de cinco llamadas por semana; su duración vendrá determinada en las normas de régimen interior del centro penitenciario, no siendo inferior a cinco minutos.', null, 'a6ae07f30fb30d68bd8acb7de8748b4d02061aab6f6c8adf63dab1a760863dd8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a6ae07f30fb30d68bd8acb7de8748b4d02061aab6f6c8adf63dab1a760863dd8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dues trucades per setmana, de no menys de deu minuts.', false), ('B', 'Cinc trucades al mes, de no menys de cinc minuts.', false), ('C', 'Cinc trucades per setmana, de no menys de cinc minuts.', true), ('D', 'Una trucada al dia, de no menys de vint minuts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La germana de l''intern U.X., en règim ordinari, diposita a la dependència de paquets un paquet amb 4,5 kg d''objectes d''higiene autoritzats i 3 kg de llibres i revistes. Segons el Reglament penitenciari, quina de les afirmacions següents NO és correcta?', 'L''art. 50.5 RP permet als interns rebre dos paquets al mes (un en règim tancat), de cinc quilos com a màxim cadascun, sense computar-hi els llibres, les publicacions ni la roba; per tant, el paquet és admissible. L''art. 50.3 RP exigeix comprovar el document d''identitat de qui el diposita.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 50.3 i 50.5 RP', 'La recepción de paquetes dirigidos a los internos se llevará a cabo previa comprobación por el funcionario del documento de identidad de quien lo deposita […] El número de paquetes que pueden recibir los internos es de dos al mes, salvo en los Establecimientos o departamentos de régimen cerrado, que será de uno al mes. El peso de cada paquete no excederá de cinco kilogramos, no computándose dentro de dicho peso máximo los libros y publicaciones, ni tampoco la ropa.', null, 'e82d341e8203cb948007ffc05a44b82cbe6cdf7249ef19d000268cf3e1eb76cf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e82d341e8203cb948007ffc05a44b82cbe6cdf7249ef19d000268cf3e1eb76cf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''ha de rebutjar perquè el pes total supera els cinc quilos.', true), ('B', 'Els llibres i les publicacions no computen dins del pes màxim de cinc quilos.', false), ('C', 'Abans de registrar-lo, el funcionari ha de comprovar el document d''identitat de qui el diposita.', false), ('D', 'Un intern en règim ordinari pot rebre dos paquets al mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern V.Y. ha estat destinat al departament de règim tancat i la seva família vol enviar-li paquets. Segons el Reglament penitenciari, quants paquets pot rebre al mes?', 'L''art. 50.5 RP fixa en dos paquets al mes el nombre que poden rebre els interns, excepte en els establiments o departaments de règim tancat, en què és d''un al mes.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 50.5 RP', 'El número de paquetes que pueden recibir los internos es de dos al mes, salvo en los Establecimientos o departamentos de régimen cerrado, que será de uno al mes.', null, '64b009e4be264fd5c896cf080ac800f0ed585d03d3733f8c90004d6e1b918aae', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '64b009e4be264fd5c896cf080ac800f0ed585d03d3733f8c90004d6e1b918aae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos.', false), ('B', 'Un.', true), ('C', 'Quatre.', false), ('D', 'Cap, mentre continuï en règim tancat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un jutjat penal situat en una altra província ha de celebrar el judici oral de l''intern W.Z., que és en un centre penitenciari català. Segons el Reglament penitenciari, a qui i amb quina antelació mínima ha de demanar el jutjat la conducció?', 'L''art. 33.2 RP disposa que les autoritats judicials o governatives han de demanar la conducció amb una antelació mínima de 30 dies al centre directiu, si l''intern és en un centre d''una altra província, i al director de l''establiment, si és de la mateixa província o localitat.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 33.2 RP', 'Las autoridades judiciales o gubernativas recabarán del centro directivo, con una antelación mínima de treinta días, la conducción oportuna del interno, cuando estuviere recluido en el centro penitenciario ubicado en otra provincia, y del Director del establecimiento, si se trata de una misma provincia o localidad.', null, 'e4dedd06fdf8a179e136c08947d714f5fa6691f6787969e855f99f08074e7b81', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4dedd06fdf8a179e136c08947d714f5fa6691f6787969e855f99f08074e7b81')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al director del centre, amb una antelació mínima de quinze dies.', false), ('B', 'Al centre directiu, amb una antelació mínima de setanta-dues hores.', false), ('C', 'Al director del centre, amb una antelació mínima de deu dies.', false), ('D', 'Al centre directiu, amb una antelació mínima de trenta dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De matinada, el metge de guàrdia dictamina que l''intern A.B. ha de ser ingressat d''urgència en un hospital extern. Segons el Reglament penitenciari, com s''ha de procedir?', 'Amb caràcter general la sortida a hospitals no penitenciaris l''acorda el centre directiu (art. 35.1 RP), però en cas d''urgència, segons dictamen mèdic, l''art. 35.3 RP permet al director fer la conducció i l''ingrés, donant-ne compte tot seguit al centre directiu.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 35.3 RP', 'En caso de urgencia, según dictamen médico, el Director procederá a la conducción e ingreso en el centro hospitalario, dando cuenta seguidamente al centro directivo.', null, '5b28bda211a514102ffe777cccd6779b9140ae03505b84cbf7e2bf9848d8b7f4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5b28bda211a514102ffe777cccd6779b9140ae03505b84cbf7e2bf9848d8b7f4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cal esperar que el centre directiu acordi la sortida.', false), ('B', 'El director fa la conducció i l''ingrés a l''hospital i en dona compte tot seguit al centre directiu.', true), ('C', 'L''ha d''autoritzar el jutge de vigilància penitenciària a proposta del metge.', false), ('D', 'La decideix el cap de serveis, que en dona compte al jutge de guàrdia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El penat C.D., classificat en segon grau, ha extingit més de la quarta part de la condemna i sol·licita el seu primer permís ordinari de sortida. Segons el Reglament penitenciari, quina és la durada màxima de cada permís ordinari i el total anual per a un penat de segon grau?', 'L''art. 154.1 RP preveu permisos ordinaris de fins a set dies, amb un total de 36 dies l''any per als penats de segon grau i 48 per als de tercer grau, sempre que hagin extingit la quarta part de la condemna i no observin mala conducta.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 154.1 RP', 'Se podrán conceder, previo informe preceptivo del Equipo Técnico, permisos de salida ordinarios de hasta siete días de duración como preparación para la vida en libertad, hasta un total de treinta y seis o cuarenta y ocho días por año a los condenados clasificados en segundo o tercer grado respectivamente, siempre que hayan extinguido la cuarta parte de la condena o condenas y no observen mala conducta.', null, '18c5647a88392fc17de08c9eb0b7833d104e9919e8a006c84b81efa18f2d4ed7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '18c5647a88392fc17de08c9eb0b7833d104e9919e8a006c84b81efa18f2d4ed7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fins a set dies cada permís, i fins a quaranta-vuit dies l''any.', false), ('B', 'Fins a cinc dies cada permís, i fins a trenta-sis dies l''any.', false), ('C', 'Fins a set dies cada permís, i fins a trenta-sis dies l''any.', true), ('D', 'Fins a catorze dies cada permís, i fins a trenta-sis dies l''any.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Junta de Tractament, amb l''informe favorable de l''equip, acorda concedir al penat E.F., classificat en segon grau, un permís ordinari de quatre dies. Segons el Reglament penitenciari, qui l''ha d''autoritzar?', 'L''art. 161.1 RP disposa que la Junta de Tractament eleva l''acord de concessió al jutge de vigilància (penats de segon grau) o al centre directiu (tercer grau). L''art. 161.2 RP atribueix al centre directiu els permisos ordinaris de fins a dos dies; com que aquest és de quatre dies i el penat és de segon grau, l''ha d''autoritzar el jutge de vigilància.', 'pcatsup_s2_classificacio_comunicacions', (select id from public.topics where slug = 'pcatsup-s2-classificacio-comunicacions'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 161.1 i 161.2 RP', 'Si la Junta de Tratamiento acuerda conceder el permiso solicitado por el interno, elevará dicho acuerdo, junto con el informe del Equipo Técnico, al Juez de Vigilancia o al Centro Directivo, según se trate de internos clasificados en segundo o tercer grado de tratamiento, respectivamente, para la autorización correspondiente. […] Los permisos ordinarios a penados de hasta dos días de duración serán autorizados por el Centro Directivo.', null, '9f83c95fc1159fd02a1a43efd94f27627149583e01cac3229083f076f917f943', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9f83c95fc1159fd02a1a43efd94f27627149583e01cac3229083f076f917f943')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El jutge de vigilància penitenciària.', true), ('B', 'El centre directiu.', false), ('C', 'El director del centre.', false), ('D', 'Ningú: l''acord de la Junta de Tractament és directament executiu.', false)) as v(label, body, ok)
)
