select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
-- Lote pcatsup-s3-procediment-disciplinari-rp-v1 (16 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pcatsup-s3-procediment-disciplinari', 'Supòsit pràctic III. Procediment disciplinari i recompenses') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('serveis-penitenciaris-catalunya') and t.slug = 'pcatsup-s3-procediment-disciplinari' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Comissió Disciplinària considera provat que l''intern F.L. va agredir un altre intern manifestant una evident agressivitat, fet constitutiu de falta molt greu. Segons l''article 233 del Reglament penitenciari, quina sanció d''aïllament en cel·la li pot imposar?', 'L''art. 233.1.a) RP preveu per a les faltes molt greus l''aïllament en cel·la de sis a catorze dies, sempre que s''hagi manifestat una evident agressivitat o violència o una alteració reiterada i greu de la convivència. L''aïllament de dilluns a divendres fins a cinc dies és per a les greus (art. 233.2.a).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.1.a) RP', 'Sanción de aislamiento en celda de seis a catorce días de duración, siempre que se haya manifestado una evidente agresividad o violencia por parte del interno', null, 'c7e5eb48453760521d7e2dd1ea3f630e7aa81e9b149fe8f67af9c4ae7698a174', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c7e5eb48453760521d7e2dd1ea3f630e7aa81e9b149fe8f67af9c4ae7698a174')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De sis a catorze dies.', true), ('B', 'De dilluns a divendres, per un temps igual o inferior a cinc dies.', false), ('C', 'Fins a quaranta-dos dies.', false), ('D', 'D''un a sis dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director ha de resoldre un procediment abreujat obert a l''intern G.M. per una falta lleu. Segons el Reglament penitenciari, quines sancions li pot imposar?', 'L''art. 233.3 RP disposa que les faltes lleus de l''art. 110 del RP de 1981 només es poden corregir amb privació de passeigs i actes recreatius comuns de fins a tres dies i amb amonestació.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 233.3 RP', 'Las faltas leves tipificadas en el artículo 110 del Reglamento Penitenciario aprobado por el Real Decreto 1201/1981, de 8 de mayo, sólo podrán corregirse con privación de paseos y actos recreativos comunes de hasta tres días de duración y con amonestación.', null, '19b2d2733b60469edbe45d252e6b14b029931a0cc81227031fe8a7c763103d63', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19b2d2733b60469edbe45d252e6b14b029931a0cc81227031fe8a7c763103d63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Aïllament en cel·la de fins a cinc dies.', false), ('B', 'Privació de permisos de sortida de fins a un mes.', false), ('C', 'Limitació de les comunicacions orals durant un mes.', false), ('D', 'Privació de passeigs i actes recreatius comuns de fins a tres dies, i amonestació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El cap de serveis informa el comunicat d''un funcionari segons el qual l''intern K.Q. ha amenaçat un company de mòdul. Segons el Reglament penitenciari, qui acorda la iniciació del procediment sancionador?', 'L''art. 241.1 RP disposa que el director acorda d''ofici i motivadament la iniciació del procediment sancionador, entre altres formes per iniciativa pròpia a partir d''un comunicat de funcionari informat pel cap de serveis.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 241.1 RP', 'el Director del Establecimiento acordará de oficio y motivadamente la iniciación del procedimiento sancionador de alguna de las siguientes formas: a) Por propia iniciativa, cuando tenga conocimiento de la existencia de conductas o hechos susceptibles de constituir infracción disciplinaria a través de parte de funcionario informado por el Jefe de Servicios o por cualquier otro medio.', null, '96e3c148671be2c18b4edfb0a07d623abc4ea3853f4d692f81935da4eaf85c87', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '96e3c148671be2c18b4edfb0a07d623abc4ea3853f4d692f81935da4eaf85c87')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El cap de serveis, en el moment d''informar el comunicat.', false), ('B', 'La Comissió Disciplinària, en la sessió ordinària següent.', false), ('C', 'L''instructor que designi el subdirector d''interior.', false), ('D', 'El director, d''ofici i de manera motivada.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director va encarregar al funcionari L.R. una informació prèvia sobre uns fets atribuïts a l''intern M.S. i ara ha de nomenar l''instructor de l''expedient disciplinari. Segons el Reglament penitenciari, quina afirmació és correcta?', 'L''art. 242.1 RP disposa que el director nomena instructor el funcionari que consideri convenient, excloent-ne el que ha practicat la informació prèvia i els que puguin estar implicats en els fets.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 242.1 RP', 'El Director nombrará Instructor al funcionario que estime conveniente, excluyendo al que haya practicado la información previa y a los que puedan estar implicados en los hechos.', null, '835e2343114e087d42a95f7b5a89c1abc1297aded4ef3218f7d682f3a8b1131f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '835e2343114e087d42a95f7b5a89c1abc1297aded4ef3218f7d682f3a8b1131f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha de nomenar L.R., perquè és qui millor coneix els fets.', false), ('B', 'Pot nomenar el funcionari que consideri convenient, excepte L.R. i els que puguin estar implicats en els fets.', true), ('C', 'Ha de nomenar necessàriament el secretari tècnic jurídic del centre.', false), ('D', 'L''instructor l''elegeix la Comissió Disciplinària per majoria.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern N.T. rep el plec de càrrecs d''un expedient per falta greu. Segons el Reglament penitenciari, de quin termini disposa per presentar el plec de descàrrecs per escrit o comparèixer davant l''instructor i al·legar verbalment?', 'L''art. 242.2.h) RP exigeix que el plec de càrrecs indiqui que l''intern disposa de tres dies hàbils des de la recepció per presentar el plec de descàrrecs per escrit o comparèixer i al·legar verbalment.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 242.2.h) RP', 'Indicación de que el interno dispone de tres días hábiles desde el momento de su recepción para presentar pliego de descargos por escrito o para comparecer ante el Instructor y alegar verbalmente', null, 'a2026aaad492c3e363ca783c5a6d3532fedc85d908d6fd1607ca0475b8804da4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2026aaad492c3e363ca783c5a6d3532fedc85d908d6fd1607ca0475b8804da4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinc dies hàbils des que el rep.', false), ('B', 'Deu dies des que el rep.', false), ('C', 'Vint-i-quatre hores des que el rep.', false), ('D', 'Tres dies hàbils des que el rep.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern O.U. ha presentat el plec de descàrrecs i hi proposa la declaració de dos interns com a testimonis. Segons el Reglament penitenciari, en quin termini s''han de practicar les proves pertinents?', 'L''art. 244.2 RP disposa que dins dels deu dies següents a la presentació del plec de descàrrecs o a les al·legacions verbals (o un cop passat el termini per fer-ho) s''han de practicar les proves pertinents proposades per l''intern i les que l''instructor consideri convenients.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 244.2 RP', 'Dentro de los diez días siguientes a la presentación del pliego de descargos o a la formalización verbal de alegaciones, o transcurrido el plazo previsto en el artículo 242.2, h), si el interno no hubiese ejercitado su derecho, se practicarán las pruebas pertinentes propuestas por el mismo y las que el Instructor considere convenientes.', null, '94b345597839a36dea8c8a45f0646a8f28096f8806258c83fdbdaf6d4248288c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '94b345597839a36dea8c8a45f0646a8f28096f8806258c83fdbdaf6d4248288c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins dels tres dies hàbils següents a la presentació del plec de descàrrecs.', false), ('B', 'Dins dels deu dies següents a la presentació del plec de descàrrecs.', true), ('C', 'Dins dels cinc dies hàbils següents a la notificació del plec de càrrecs.', false), ('D', 'Dins del mes següent a la iniciació del procediment.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Instruït l''expedient de l''intern P.V., i immediatament abans de redactar la proposta de resolució, l''instructor li posa de manifest tot el que s''ha actuat. Segons el Reglament penitenciari, de quin termini disposa l''intern per al·legar i presentar documents i justificacions?', 'L''art. 244.4 RP regula el tràmit d''audiència: abans de la proposta de resolució es posa de manifest l''expedient a l''interessat perquè, en un termini de deu dies, al·legui o presenti els documents i justificacions pertinents.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 244.4 RP', 'Instruido el procedimiento, e inmediatamente antes de redactar la propuesta de resolución, se pondrá de manifiesto al interesado para que, en un plazo de diez días, alegue o presente los documentos y justificaciones que estime pertinentes.', null, 'a8d4aa93a4b482180a1c5be3cdd276ae898567f465f327f0540ae64747356d96', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a8d4aa93a4b482180a1c5be3cdd276ae898567f465f327f0540ae64747356d96')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deu dies.', true), ('B', 'Tres dies hàbils.', false), ('C', 'Cinc dies hàbils.', false), ('D', 'Quinze dies.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''expedient disciplinari per falta greu de l''intern Q.X. es va iniciar fa més de tres mesos i la Comissió Disciplinària encara no l''ha resolt, sense que la demora sigui imputable a l''intern. Segons el Reglament penitenciari, quan s''entén caducat el procediment?', 'L''art. 246.2 RP fixa un termini màxim de tres mesos per resoldre des de la iniciació; el procediment s''entén caducat i s''arxiva quan, vençut aquest termini, no es resol dins dels trenta dies següents, sempre que la demora no sigui imputable a l''interessat.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 246.2 RP', 'El acuerdo deberá dictarse en el plazo máximo de tres meses desde la iniciación del procedimiento disciplinario. Se entenderá caducado el procedimiento disciplinario y se procederá al archivo de las actuaciones, de oficio o a solicitud del interesado, cuando, una vez vencido el plazo señalado en este apartado para dictar resolución o, en el supuesto del procedimiento abreviado, el señalado en el artículo 251.1, ésta no se adoptase en el plazo de los treinta días siguientes, siempre que la demora no fuera imputable al interesado', null, '2f60b1178f1ff436a82ecdcaef1fc98d428f84e48c242be84daea74f0c99f30e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2f60b1178f1ff436a82ecdcaef1fc98d428f84e48c242be84daea74f0c99f30e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Automàticament, el mateix dia en què es compleixen els tres mesos.', false), ('B', 'Quan han passat sis mesos des de la iniciació.', false), ('C', 'Quan, vençut el termini de tres mesos, no s''adopta la resolució dins dels trenta dies següents.', true), ('D', 'Mai: el procediment disciplinari no caduca, només prescriu.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Comissió Disciplinària imposa a l''intern R.Y. una sanció de privació de permisos de sortida per una falta greu. Segons el Reglament penitenciari, quan s''ha de notificar l''acord i de quin termini disposa l''intern per recórrer per escrit davant el jutge de vigilància?', 'L''art. 248 RP obliga a notificar l''acord sancionador el mateix dia o l''endemà, amb lectura íntegra i lliurament de còpia, i indicar que s''hi pot recórrer davant el jutge de vigilància verbalment en el mateix acte o per escrit dins dels cinc dies hàbils següents.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 248 RP', 'La notificación del acuerdo sancionador deberá cursarse en el mismo día o al siguiente de ser adoptado […] Indicación de que contra el mismo puede interponerse recurso ante el Juez de Vigilancia, verbalmente en el mismo acto de la notificación o por escrito dentro de los cinco días hábiles siguientes a la misma', null, '5626e4d36759dda0697f25e9fb7d287f1ef22840d0701711254274fe9a0aba70', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5626e4d36759dda0697f25e9fb7d287f1ef22840d0701711254274fe9a0aba70')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El mateix dia en què s''adopta o l''endemà; cinc dies hàbils des de la notificació.', true), ('B', 'Dins dels deu dies següents; un mes des de la notificació.', false), ('C', 'Dins dels tres dies següents; deu dies hàbils des de la notificació.', false), ('D', 'El mateix dia; tres dies hàbils des de la notificació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director considera que el comunicat de fets contra l''intern S.Z. conté prou elements de judici per qualificar la infracció com a falta lleu. Segons el Reglament penitenciari, quina afirmació és correcta sobre el procediment que s''ha de seguir?', 'L''art. 251.1 RP disposa que, quan el director considera que hi ha prou elements per qualificar la infracció de lleu, es tramita el procediment abreujat, que s''ha de resoldre en el termini màxim d''un mes des que es va iniciar; el comunicat del funcionari opera com a plec de càrrecs i es notifica al presumpte infractor.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 251.1 RP', 'se tramitará el procedimiento abreviado, que deberá resolverse en el plazo máximo de un mes desde que se inició, con arreglo a las siguientes normas: a) El parte del funcionario, que operará como pliego de cargos, se comunicará al Jefe de Servicios y, simultáneamente, se notificará al presunto infractor.', null, '204a24c226fecd1cae19863507e28ccfaaaf4a75926b1be04a5b0aa880bffa28', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '204a24c226fecd1cae19863507e28ccfaaaf4a75926b1be04a5b0aa880bffa28')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cal nomenar instructor i formular un plec de càrrecs ordinari, i s''ha de resoldre en tres mesos.', false), ('B', 'Es tramita el procediment abreujat, en què el comunicat del funcionari opera com a plec de càrrecs, i s''ha de resoldre en el termini màxim d''un mes des que es va iniciar.', true), ('C', 'Es tramita el procediment abreujat, que s''ha de resoldre en el termini màxim de tres mesos.', false), ('D', 'El resol la Comissió Disciplinària en la primera sessió ordinària, sense plec de càrrecs.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Comissió Disciplinària sanciona l''intern T.A. per una falta molt greu i vol acordar l''execució immediata de la sanció perquè considera que el compliment no es pot demorar. Segons l''article 252 del Reglament penitenciari, en quin dels casos següents NO es pot acordar l''execució immediata?', 'L''art. 252.2 RP (en relació amb l''art. 44.3 LOGP i el primer paràgraf de l''art. 124 del RP de 1981) només permet l''execució immediata de les sancions corresponents als actes d''indisciplina greu de les lletres a) a f) de l''art. 108 del RP de 1981. La sostracció és la lletra g).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 252.2 RP', 'las sanciones impuestas serán inmediatamente ejecutadas, siempre que correspondan a los actos de indisciplina grave tipificados en las letras a), b), c), d), e) y f) del artículo 108 del Reglamento Penitenciario aprobado por Real Decreto 1201/1981, de 8 de mayo.', null, '018b0c988d6fd1e4a1a5a1147a2a1a8e7b8ee44c504789735fd65e6d504916c5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '018b0c988d6fd1e4a1a5a1147a2a1a8e7b8ee44c504789735fd65e6d504916c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Participació en un motí (art. 108.a RP 1981).', false), ('B', 'Agressió a un funcionari (art. 108.b RP 1981).', false), ('C', 'Intent d''evasió (art. 108.e RP 1981).', false), ('D', 'Sostracció de materials o efectes de l''establiment (art. 108.g RP 1981).', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Mentre es tramita l''expedient obert a l''intern U.B. per una baralla greu, es planteja separar-lo cautelarment de la víctima. Segons el Reglament penitenciari, quina de les afirmacions següents sobre les mesures cautelars NO és correcta?', 'L''art. 243 RP atribueix al director, per si mateix o a proposta de l''instructor, l''adopció de mesures cautelars motivades en qualsevol moment del procediment; s''han de notificar a l''intern i comunicar al jutge de vigilància, i s''abonen si coincideixen en naturalesa amb la sanció. També ho recull l''art. 12.2.h) del Decret 329/2006.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 243 RP', 'El Director, en el ámbito de las facultades que le atribuye este Reglamento, por sí o a propuesta del Instructor del expediente disciplinario, podrá acordar en cualquier momento del procedimiento, mediante acuerdo motivado, las medidas cautelares […] su adopción será notificada al interno y puesta en conocimiento del Juez de Vigilancia Penitenciaria. […] Cuando la sanción que recayese, en su caso, coincida en naturaleza con la medida cautelar impuesta, ésta se abonará para el cumplimiento de la sanción.', null, '55f787cd7daccf9a69608a542282717ecda7f4345279c609c8f215cbb3c606a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '55f787cd7daccf9a69608a542282717ecda7f4345279c609c8f215cbb3c606a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les pot acordar el director, per iniciativa pròpia o a proposta de l''instructor, en qualsevol moment del procediment.', false), ('B', 'S''han de notificar a l''intern i posar en coneixement del jutge de vigilància penitenciària.', false), ('C', 'Només les pot acordar la Comissió Disciplinària, un cop resolt l''expedient.', true), ('D', 'Si la sanció que s''imposa coincideix en naturalesa amb la mesura cautelar, aquesta s''abona per al compliment de la sanció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un mateix expedient, la Comissió Disciplinària imposa a l''intern V.C. tres sancions d''aïllament en cel·la que s''han de complir successivament i que sumen vint dies. Segons el Reglament penitenciari, quina afirmació és correcta?', 'L''art. 236.3 RP disposa que, en el compliment successiu de sancions d''aïllament en cel·la, quan en conjunt superen els catorze dies, totes han de ser aprovades pel jutge de vigilància, d''acord amb l''art. 76.2.d) LOGP.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 236.3 RP', 'Cuando en los supuestos de cumplimiento sucesivo de sanciones de aislamiento en celda, éstas superen, en su conjunto, los catorce días de aislamiento, deberán ser aprobadas todas ellas por el Juez de Vigilancia Penitenciaria', null, 'e35d3be83acb69437fce2d620c1269947852229ca8606c81b4cf8e51577a9f50', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e35d3be83acb69437fce2d620c1269947852229ca8606c81b4cf8e51577a9f50')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es poden executar sense intervenció judicial, perquè cap d''elles no supera per si sola els catorze dies.', false), ('B', 'Només es compleix la més greu i les altres queden sense efecte.', false), ('C', 'Se''n compleixen catorze dies consecutius i la resta s''extingeix automàticament.', false), ('D', 'Totes les sancions han de ser aprovades pel jutge de vigilància penitenciària, perquè en conjunt superen els catorze dies.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
