with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern X.D. compleix una sanció d''aïllament en cel·la. Segons el Reglament penitenciari, de quantes hores diàries de passeig en solitari ha de gaudir?', 'L''art. 254.5 RP disposa que l''intern que compleix aïllament en cel·la gaudeix de dues hores diàries de passeig en solitari i que, mentre dura la sanció, no pot rebre paquets de l''exterior ni comprar a l''economat, llevat del que autoritzi expressament el director.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 254.5 RP', 'El recluso internado en celda disfrutará de dos horas diarias de paseo en solitario', null, '49f6bc8ef69ebdc417b005db0672fb7d5a1e7f3aaf2a6c55ab6793a07ad39357', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '49f6bc8ef69ebdc417b005db0672fb7d5a1e7f3aaf2a6c55ab6793a07ad39357')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una hora.', false), ('B', 'Dues hores.', true), ('C', 'Tres hores.', false), ('D', 'Quatre hores.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern Y.E. té pendent de complir una sanció d''aïllament, i la Junta de Tractament considera que el compliment en pertorbaria el tractament. Segons el Reglament penitenciari, quin òrgan pot acordar motivadament la suspensió de l''efectivitat de la sanció?', 'L''art. 255.1 RP atribueix a la Comissió Disciplinària, d''ofici o a proposta de la Junta de Tractament, la suspensió motivada de l''efectivitat de les sancions d''aïllament. Només cal autorització del jutge de vigilància si aquest ha confirmat la sanció (art. 255.3 RP).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Art. 255.1 RP', 'siempre que las circunstancias lo aconsejen, la Comisión Disciplinaria, de oficio o a propuesta de la Junta de Tratamiento, podrá acordar motivadamente la suspensión de la efectividad de las sanciones de aislamiento impuestas.', null, 'aa9f1304925a49159542ca7a7bceaa79beda8ed03b4c1380a5ae4ce28ba27117', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa9f1304925a49159542ca7a7bceaa79beda8ed03b4c1380a5ae4ce28ba27117')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La mateixa Junta de Tractament.', false), ('B', 'El director, per resolució motivada.', false), ('C', 'La Comissió Disciplinària, d''ofici o a proposta de la Junta de Tractament.', true), ('D', 'El jutge de vigilància penitenciària, en tots els casos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('serveis-penitenciaris-catalunya');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'L''intern Z.F. va complir fa dos mesos una sanció per falta greu i des d''aleshores no ha comès cap altra falta. La setmana passada la Comissió Disciplinària li va concedir una nota meritòria. Segons el Reglament penitenciari, quina afirmació és correcta sobre la cancel·lació de l''anotació de la sanció?', 'L''art. 260.1 RP fixa el termini de cancel·lació en tres mesos per a les faltes greus, comptats des del compliment, sempre que no hi hagi nova falta greu o molt greu. L''art. 261 RP permet escurçar aquests terminis fins a la meitat si, abans de completar-los, l''intern obté una recompensa de l''art. 263 (entre les quals hi ha les notes meritòries).', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'Arts. 260.1 i 261 RP', 'Transcurso de seis meses para las faltas muy graves, tres meses para las graves y un mes para las leves, a contar desde el cumplimiento de la sanción. […] Los plazos de cancelación podrán ser acortados hasta la mitad de su duración si, con posterioridad a la sanción y antes de completarse dichos plazos, el interno obtuviere alguna recompensa de las previstas en el artículo 263 de este Reglamento.', null, 'e4c3de94cdf523c973402b5ccafe945e1628b4c5224a8e4317da945f87489da2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4c3de94cdf523c973402b5ccafe945e1628b4c5224a8e4317da945f87489da2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ja es pot cancel·lar, perquè el termini de tres mesos es pot escurçar fins a la meitat per haver obtingut una recompensa.', true), ('B', 'No es pot cancel·lar fins que passin sis mesos des del compliment.', false), ('C', 'Ha d''esperar un mes més, perquè el termini de tres mesos no es pot reduir.', false), ('D', 'No es pot cancel·lar fins que l''intern sigui excarcerat.', false)) as v(label, body, ok)
)
