with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En lloc d''utilitzar les instàncies i els canals de queixa establerts, l''intern D.J. enganxa reiteradament a les parets del menjador escrits de reclamació adreçats a la direcció. Segons el Reglament penitenciari de 1981, quina falta pot constituir aquesta conducta?', 'L''art. 110.c) del RP de 1981 qualifica de falta lleu formular reclamacions sense fer ús dels canals establerts reglamentàriament.', 'pcatsup_s3_procediment_disciplinari', (select id from public.topics where slug = 'pcatsup-s3-procediment-disciplinari'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'Art. 110.c) RP 1981', 'c) Formular reclamaciones sin hacer uso de los cauces establecidos reglamentariamente.', null, 'f346e831f9c0fb7363d778e50a2d2b481925b0cf09b17cc13bb1626561f39327', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f346e831f9c0fb7363d778e50a2d2b481925b0cf09b17cc13bb1626561f39327')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Falta greu de l''article 109.h).', false), ('B', 'Falta greu de l''article 109.c).', false), ('C', 'Falta lleu de l''article 110.c).', true), ('D', 'Cap falta, perquè el dret de queixa no té límits formals.', false)) as v(label, body, ok)
)
