insert into public.sources (title, url, kind, publisher, published_on) values ('Decret 329/2006, de 5 de setembre, pel qual s''aprova el Reglament d''organització i funcionament dels serveis d''execució penal a Catalunya (DOGC núm. 4714, 07/09/2006)', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=460252', 'diario_autonomico'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
